window.GRAMMAR_DATA = [
{"id":"wa","pattern":"は","level":"N5","category":"Partikel","meaning":"topic marker","explanation":"は marks the topic of a sentence, i.e. what is being talked about. It is always pronounced \"wa\", even though it is the hiragana character \"ha\". The topic does not have to be the grammatical subject.","formation":"Noun + は","examples":[{"japanese":"私は学生です。","cloze":{"start":1,"answer":"は","quiz":{"level":"N5","japanese":"私は学生です。","german":"I am a student.","start":1,"answer":"は","acceptedAnswers":["は","が"],"distractors":[{"text":"を","reason":"を marks an object; the copula has none here."},{"text":"で","reason":"で does not form a noun-predicate statement here."},{"text":"へ","reason":"へ indicates a direction, not an identity."}],"promptKana":"わたし＿＿＿がくせいです。"}},"romaji":"Watashi wa gakusei desu.","german":"I am a student."},{"japanese":"東京は大きいです。","cloze":{"start":2,"answer":"は"},"romaji":"Tōkyō wa ōkii desu.","german":"Tokyo is big."}],"notes":"Don't confuse it with が (ga). は emphasizes the topic, が emphasizes the subject. が is used for new information, は for topics that are already known.","related":["ga"]},
{"id":"ga","pattern":"が","level":"N5","category":"Partikel","meaning":"subject marker","explanation":"が marks the grammatical subject of a sentence and emphasizes who or what performs the action. It is often used to introduce new information or to put special emphasis on the subject.","formation":"Noun + が","examples":[{"japanese":"猫がいます。","cloze":{"start":1,"answer":"が","quiz":{"level":"N5","japanese":"猫がいます。","german":"There is a cat. / A cat is here.","start":1,"answer":"が","acceptedAnswers":["が","は","も"],"distractors":[{"text":"を","reason":"います does not take a direct object here."},{"text":"へ","reason":"へ marks a destination of movement, not a cat that exists."},{"text":"の","reason":"の would need a following noun to modify."}],"promptKana":"ねこ＿＿＿います。"}},"romaji":"Neko ga imasu.","german":"There is a cat. / A cat is here."},{"japanese":"誰が来ましたか。","cloze":{"start":1,"answer":"が"},"romaji":"Dare ga kimashita ka.","german":"Who came?"}],"notes":"が is used after question words (誰が、何が) and before certain predicates such as 好き、欲しい、分かる、ある、いる.","related":["wa","ga-aru","ga-iru","n4-ga-suru"]},
{"id":"wo","pattern":"を","level":"N5","category":"Partikel","meaning":"object marker","explanation":"を marks the direct object of a sentence, i.e. what the action affects. It is pronounced \"o\". It is also used to mark a place that you move through.","formation":"Noun + を + Verb","examples":[{"japanese":"パンを食べます。","cloze":{"start":2,"answer":"を","quiz":{"level":"N5","japanese":"パンを食べます。","german":"I eat bread.","start":2,"answer":"を","acceptedAnswers":["を","は","も"],"distractors":[{"text":"に","reason":"に does not mark the thing being eaten."},{"text":"へ","reason":"Bread is not a destination of movement here."},{"text":"が","reason":"With active 食べます, bread is the object, not the one eating."}],"promptKana":"パン＿＿＿たべます。"}},"romaji":"Pan o tabemasu.","german":"I eat bread."},{"japanese":"公園を歩きます。","cloze":{"start":2,"answer":"を"},"romaji":"Kōen o arukimasu.","german":"I walk through the park."}],"notes":"を is only used with transitive verbs (verbs that take an object). With verbs of motion such as 歩く、走る, を marks the place you pass through.","related":["wa","ga"]},
{"id":"ni","pattern":"に","level":"N5","category":"Partikel","meaning":"direction / point in time / place of existence","explanation":"に has many functions: it marks the destination of a movement, a point in time, the place where something exists, and the indirect recipient. It is one of the most versatile particles in Japanese.","formation":"Noun + に","examples":[{"japanese":"学校に行きます。","cloze":{"start":2,"answer":"に","quiz":{"level":"N5","japanese":"学校に行きます。","german":"I go to school.","start":2,"answer":"に","acceptedAnswers":["に","へ"],"distractors":[{"text":"を","reason":"The school is a destination, not a route you pass through."},{"text":"の","reason":"の cannot link the destination to 行きます."},{"text":"が","reason":"The school is not the subject of the movement."}],"promptKana":"がっこう＿＿＿いきます。"}},"romaji":"Gakkō ni ikimasu.","german":"I go to school."},{"japanese":"七時に起きます。","cloze":{"start":2,"answer":"に"},"romaji":"Shichi-ji ni okimasu.","german":"I get up at seven o'clock."}],"notes":"With days of the week and specific clock times you use に, but with relative time expressions such as 今日、明日、来週, に is not used.","related":["de","e","n5-koko-soko-asoko-doko","n5-goro"]},
{"id":"de","pattern":"で","level":"N5","category":"Partikel","meaning":"place of action / means","explanation":"で marks the place where an action takes place, or the means by which something is done. It can also indicate a cause or a material.","formation":"Noun + で","examples":[{"japanese":"図書館で勉強します。","cloze":{"start":3,"answer":"で","quiz":{"level":"N5","japanese":"図書館で勉強します。","german":"I study at the library.","start":3,"answer":"で","acceptedAnswers":["で"],"distractors":[{"text":"に","reason":"The place where 勉強します happens is marked with で."},{"text":"へ","reason":"へ would require a movement."},{"text":"を","reason":"The library is not the thing being studied."}],"promptKana":"としょかん＿＿＿べんきょうします。"}},"romaji":"Toshokan de benkyō shimasu.","german":"I study at the library."},{"japanese":"バスで行きます。","cloze":{"start":2,"answer":"で"},"romaji":"Basu de ikimasu.","german":"I go by bus."}],"notes":"Difference from に: で marks the place of an activity (図書館で勉強する), while に marks the place of existence (図書館にいる).","related":["ni"]},
{"id":"e","pattern":"へ","level":"N5","category":"Partikel","meaning":"direction (towards)","explanation":"へ marks the direction of a movement. It is pronounced \"e\", not \"he\". With verbs of motion it is interchangeable with に, but it puts more emphasis on the direction than on the destination.","formation":"Noun + へ","examples":[{"japanese":"日本へ行きます。","cloze":{"start":2,"answer":"へ","quiz":{"level":"N5","japanese":"日本へ行きます。","german":"I'm going to Japan.","start":2,"answer":"へ","acceptedAnswers":["へ","に"],"distractors":[{"text":"が","reason":"Japan is the destination here, not the traveler."},{"text":"の","reason":"の does not link a noun to 行きます here."},{"text":"を","reason":"Japan is the travel destination here, not a route passed through."}],"promptKana":"にほん＿＿＿いきます。"}},"romaji":"Nihon e ikimasu.","german":"I'm going to Japan."},{"japanese":"南へ歩きましょう。","cloze":{"start":1,"answer":"へ"},"romaji":"Minami e arukimashō.","german":"Let's walk south."}],"notes":"へ emphasizes the direction of the movement, while に emphasizes the destination. In everyday speech, に is often preferred.","related":["ni"]},
{"id":"kara","pattern":"から","level":"N5","category":"Partikel","meaning":"from; starting at (starting point)","explanation":"から marks the starting point of an action in time or space. It means \"from\" or \"starting at\". When it comes after a verb at the end of a sentence, it can also mean \"because\".","formation":"Noun + から","examples":[{"japanese":"九時から始まります。","cloze":{"start":2,"answer":"から","quiz":{"level":"N5","japanese":"九時から始まります。","german":"It starts at nine o'clock.","start":2,"answer":"から","acceptedAnswers":["から","に"],"distractors":[{"text":"まで","reason":"まで names an end point, not the start at nine."},{"text":"へ","reason":"へ indicates a direction, not a starting time."},{"text":"を","reason":"始まります has no direct object here."}],"promptKana":"くじ＿＿＿はじまります。"}},"romaji":"Ku-ji kara hajimarimasu.","german":"It starts at nine o'clock."},{"japanese":"東京から来ました。","cloze":{"start":2,"answer":"から"},"romaji":"Tōkyō kara kimashita.","german":"I came from Tokyo."}],"notes":"As a particle, から means \"from/starting at\"; as a conjunction after a verb it means \"because\". See also the conjunction から under sentence structures.","related":["made","kara-because"]},
{"id":"made","pattern":"まで","level":"N5","category":"Partikel","meaning":"until; as far as (end point)","explanation":"まで marks the end point in time or space. It is often used together with から to express a period of time or a distance.","formation":"Noun + まで","examples":[{"japanese":"五時まで働きます。","cloze":{"start":2,"answer":"まで","quiz":{"level":"N5","japanese":"五時まで働きます。","german":"I work until five o'clock.","start":2,"answer":"まで","acceptedAnswers":["まで"],"distractors":[{"text":"から","reason":"から would mean \"from five\" instead of \"until five\"."},{"text":"へ","reason":"へ does not mark an end point in time."},{"text":"を","reason":"を marks neither the length of work nor the end time here."}],"promptKana":"ごじ＿＿＿はたらきます。"}},"romaji":"Go-ji made hatarakimasu.","german":"I work until five o'clock."},{"japanese":"駅から学校まで歩きます。","cloze":{"start":5,"answer":"まで"},"romaji":"Eki kara gakkō made arukimasu.","german":"I walk from the station to the school."}],"notes":"から～まで is a common pair: 月曜日から金曜日まで (from Monday to Friday).","related":["kara"]},
{"id":"to","pattern":"と","level":"N5","category":"Partikel","meaning":"and; with (together with)","explanation":"と has two main meanings: it joins nouns in a list (\"and\") or marks someone you do something with (\"with\"). In a list, all items are named (a complete list).","formation":"Noun + と + Noun / Noun + と + Verb","examples":[{"japanese":"パンと牛乳を買いました。","cloze":{"start":2,"answer":"と","quiz":{"level":"N5","japanese":"パンと牛乳を買いました。","german":"I bought bread and milk.","start":2,"answer":"と","acceptedAnswers":["と","や"],"distractors":[{"text":"へ","reason":"へ does not join items that were bought."},{"text":"で","reason":"で would mark bread as a means instead of as another item bought."},{"text":"が","reason":"が makes bread the subject instead of the second item bought."}],"promptKana":"パン＿＿＿ぎゅうにゅうをかいました。"}},"romaji":"Pan to gyūnyū o kaimashita.","german":"I bought bread and milk."},{"japanese":"友達と映画を見ました。","cloze":{"start":2,"answer":"と"},"romaji":"Tomodachi to eiga o mimashita.","german":"I watched a movie with a friend."}],"notes":"と lists all items completely. For an incomplete list (\"and so on\") you use や.","related":["ya"]},
{"id":"no","pattern":"の","level":"N5","category":"Partikel","meaning":"possessive marker / link","explanation":"の connects two nouns and shows belonging, possession or a closer description. It often corresponds to English 's or \"of\". の can also replace a noun when it is clear from context.","formation":"Noun + の + Noun","examples":[{"japanese":"私の本です。","cloze":{"start":1,"answer":"の","quiz":{"level":"N5","japanese":"私の本です。","german":"It's my book.","start":1,"answer":"の","acceptedAnswers":["の"],"distractors":[{"text":"を","reason":"を does not create a possessive relation to the following noun."},{"text":"へ","reason":"A direction is not a statement of possession."},{"text":"に","reason":"に cannot directly mark 本 as someone's possession here."}],"promptKana":"わたし＿＿＿ほんです。"}},"romaji":"Watashi no hon desu.","german":"It's my book."},{"japanese":"日本語の先生です。","cloze":{"start":3,"answer":"の"},"romaji":"Nihongo no sensei desu.","german":"He/She is a Japanese teacher."}],"notes":"の can also be used as a nominalizer: 食べるのが好きです (I like eating).","related":["no-wa-desu"]},
{"id":"mo","pattern":"も","level":"N5","category":"Partikel","meaning":"also; too","explanation":"も replaces は, が or を and means \"also\" or \"too\". It shows that what is said also applies to the marked element. With amounts it can mean \"even\".","formation":"Noun + も","examples":[{"japanese":"私も学生です。","cloze":{"start":1,"answer":"も","quiz":{"level":"N5","japanese":"私も学生です。","german":"I'm a student too.","start":1,"answer":"も","acceptedAnswers":["も"],"distractors":[{"text":"を","reason":"The copula does not take an object here."},{"text":"へ","reason":"A direction does not express \"also\"."},{"text":"の","reason":"私の学生 would mean \"my student\" instead of me."}],"promptKana":"わたし＿＿＿がくせいです。"}},"romaji":"Watashi mo gakusei desu.","german":"I'm a student too."},{"japanese":"猫も犬も好きです。","romaji":"Neko mo inu mo suki desu.","german":"I like both cats and dogs."}],"notes":"も replaces は, が and を, but is added on to other particles: にも、でも、からも, etc.","related":["wa","ga","n5-question-word-ka-mo"]},
{"id":"ne","pattern":"ね","level":"N5","category":"Partikel","meaning":"isn't it? / confirmation particle","explanation":"ね is used at the end of a sentence to seek agreement or express a shared opinion. It is like English \"isn't it?\" or \"right?\".","formation":"Sentence + ね","examples":[{"japanese":"いい天気ですね。","cloze":{"start":6,"answer":"ね","quiz":{"level":"N5","japanese":"いい天気ですね。","german":"Nice weather, isn't it?","start":6,"answer":"ね","acceptedAnswers":["ね","の"],"distractors":[{"text":"を","reason":"を cannot close the copula as a sentence-final particle."},{"text":"に","reason":"に is not a sentence-final particle that seeks agreement here."},{"text":"ます","reason":"ですます doubles the polite ending, which is not allowed."}],"promptKana":"いいてんきです＿＿＿。"}},"romaji":"Ii tenki desu ne.","german":"Nice weather, isn't it?"},{"japanese":"この映画はおもしろいですね。","cloze":{"start":12,"answer":"ね"},"romaji":"Kono eiga wa omoshiroi desu ne.","german":"This movie is interesting, isn't it?"}],"notes":"ね is often used in conversation to create a friendly atmosphere and signal agreement.","related":["yo"]},
{"id":"yo","pattern":"よ","level":"N5","category":"Partikel","meaning":"emphasis particle (I'm telling you!)","explanation":"よ is used at the end of a sentence to share new information or to emphasize a statement. It signals to the listener that you are saying something new or important.","formation":"Sentence + よ","examples":[{"japanese":"これはおいしいですよ。","cloze":{"start":9,"answer":"よ","quiz":{"level":"N5","japanese":"これはおいしいですよ。","german":"This is delicious, I'm telling you!","start":9,"answer":"よ","acceptedAnswers":["よ"],"distractors":[{"text":"を","reason":"を is not a suitable sentence-final particle after です."},{"text":"に","reason":"に does not close this copula sentence."},{"text":"へ","reason":"へ is a direction particle, not an emphasizer."}],"promptKana":"これはおいしいです＿＿＿。"}},"romaji":"Kore wa oishii desu yo.","german":"This is delicious, I'm telling you!"},{"japanese":"もう遅いですよ。","cloze":{"start":6,"answer":"よ"},"romaji":"Mō osoi desu yo.","german":"It's already late!"}],"notes":"よ sounds more assertive than ね. Using it too often can come across as pushy. よね combines both particles (emphasis + confirmation).","related":["ne"]},
{"id":"ka","pattern":"か","level":"N5","category":"Partikel","meaning":"question particle","explanation":"か is attached to the end of a sentence to form a question. In polite Japanese, か replaces the question mark. The word order does not change.","formation":"Sentence + か","examples":[{"japanese":"学生ですか。","cloze":{"start":4,"answer":"か","quiz":{"level":"N5","japanese":"学生ですか。","german":"Are you a student?","start":4,"answer":"か","acceptedAnswers":["か"],"distractors":[{"text":"を","reason":"を does not form a question after です."},{"text":"に","reason":"に does not form a question after です."},{"text":"へ","reason":"へ does not form a question after です."}],"promptKana":"がくせいです＿＿＿。"}},"romaji":"Gakusei desu ka.","german":"Are you a student?"},{"japanese":"何を食べますか。","cloze":{"start":6,"answer":"か"},"romaji":"Nani o tabemasu ka.","german":"What will you eat?"}],"notes":"In polite speech, か is used without a question mark. In informal Japanese, か can be left out; the question is then formed with rising intonation.","related":["n5-ka-ka","n5-question-word-ka-mo","n4-kana-kashira","n4-indirect-question"]},
{"id":"ya","pattern":"や","level":"N5","category":"Partikel","meaning":"and (incomplete list)","explanation":"や joins nouns in an incomplete list. It means \"and (among other things)\" and shows that there are further items that are not mentioned.","formation":"Noun + や + Noun (+ など)","examples":[{"japanese":"りんごやみかんを買いました。","cloze":{"start":3,"answer":"や","quiz":{"level":"N5","japanese":"りんごやみかんを買いました。","german":"I bought apples and mandarins (among other things).","start":3,"answer":"や","acceptedAnswers":["や","とか","と","に"],"distractors":[{"text":"へ","reason":"へ does not list items that were bought."},{"text":"が","reason":"が would make the apples the subject."},{"text":"の","reason":"This makes the apples a modifier of the mandarins instead of listing both."}],"promptKana":"りんご＿＿＿みかんをかいました。"}},"romaji":"Ringo ya mikan o kaimashita.","german":"I bought apples and mandarins (among other things)."},{"japanese":"本やノートなどがあります。","cloze":{"start":1,"answer":"や"},"romaji":"Hon ya nōto nado ga arimasu.","german":"There are books, notebooks and so on."}],"notes":"や is often combined with など (and so on). Unlike と (complete list), や suggests that the list is not complete.","related":["to","n5-ka-ka"]},
{"id":"masu","pattern":"～ます","level":"N5","category":"Verben","meaning":"polite non-past form (affirmative)","explanation":"～ます is the polite non-past form of a verb. It expresses actions in the present or future. This form is used in formal situations and with strangers.","formation":"Verb stem + ます","examples":[{"japanese":"毎日日本語を勉強します。","cloze":{"start":9,"answer":"ます","quiz":{"level":"N5","japanese":"毎日日本語を勉強します。","german":"I study Japanese every day.","start":9,"answer":"ます","acceptedAnswers":["ます"],"distractors":[{"text":"ません","reason":"The translation is affirmative, not \"I don't study\"."},{"text":"ました","reason":"The translation describes a present habit, not a completed past action."},{"text":"ませんでした","reason":"This would be the negative past."}],"promptKana":"まいにちにほんごをべんきょうし＿＿＿。"}},"romaji":"Mainichi nihongo o benkyō shimasu.","german":"I study Japanese every day."},{"japanese":"明日友達に会います。","cloze":{"start":7,"answer":"ます"},"romaji":"Ashita tomodachi ni aimasu.","german":"I'm meeting a friend tomorrow."}],"notes":"The ます-form is built from the verb stem (masu-stem). With group 1 (godan) verbs, the last syllable changes: 書く → 書きます, 飲む → 飲みます.","related":["masen","mashita","masen-deshita"]},
{"id":"masen","pattern":"～ません","level":"N5","category":"Verben","meaning":"polite non-past form (negative)","explanation":"～ません is the polite negative of a verb in the non-past. It expresses that you don't do something or won't do it.","formation":"Verb stem + ません","examples":[{"japanese":"肉を食べません。","cloze":{"start":4,"answer":"ません","quiz":{"level":"N5","japanese":"肉を食べません。","german":"I don't eat meat.","start":4,"answer":"ません","acceptedAnswers":["ません"],"distractors":[{"text":"ます","reason":"This would be an affirmative statement: I eat meat."},{"text":"ました","reason":"This would be the affirmative past."},{"text":"ましょう","reason":"This would be a suggestion, not a negation."}],"promptKana":"にくをたべ＿＿＿。"}},"romaji":"Niku o tabemasen.","german":"I don't eat meat."},{"japanese":"今日は学校に行きません。","cloze":{"start":8,"answer":"ません"},"romaji":"Kyō wa gakkō ni ikimasen.","german":"I'm not going to school today."}],"notes":"ません can also be used as a polite invitation: 一緒に行きませんか (Why don't we go together?).","related":["masu","mashita","masen-deshita","n5-amari-nai","n5-masen-ka"]},
{"id":"mashita","pattern":"～ました","level":"N5","category":"Verben","meaning":"polite past form (affirmative)","explanation":"～ました is the polite past form of a verb. It expresses that an action was completed in the past.","formation":"Verb stem + ました","examples":[{"japanese":"昨日映画を見ました。","cloze":{"start":6,"answer":"ました","quiz":{"level":"N5","japanese":"昨日映画を見ました。","german":"I watched a movie yesterday.","start":6,"answer":"ました","acceptedAnswers":["ました"],"distractors":[{"text":"ます","reason":"昨日 calls for the past for the completed action."},{"text":"ません","reason":"This would be non-past and negative."},{"text":"ませんでした","reason":"The translation says the movie was watched."}],"promptKana":"きのうえいがをみ＿＿＿。"}},"romaji":"Kinō eiga o mimashita.","german":"I watched a movie yesterday."},{"japanese":"日本に行きました。","cloze":{"start":5,"answer":"ました"},"romaji":"Nihon ni ikimashita.","german":"I went to Japan."}],"notes":"It's easy to form: you replace ます with ました. The verb stem stays the same.","related":["masu","masen","masen-deshita"]},
{"id":"masen-deshita","pattern":"～ませんでした","level":"N5","category":"Verben","meaning":"polite past form (negative)","explanation":"～ませんでした is the polite negative in the past. It expresses that you did not do something.","formation":"Verb stem + ませんでした","examples":[{"japanese":"朝ごはんを食べませんでした。","cloze":{"start":7,"answer":"ませんでした","quiz":{"level":"N5","japanese":"朝ごはんを食べませんでした。","german":"I didn't eat breakfast.","start":7,"answer":"ませんでした","acceptedAnswers":["ませんでした"],"distractors":[{"text":"ました","reason":"This says breakfast was eaten."},{"text":"ます","reason":"This is the affirmative non-past."},{"text":"ましょう","reason":"This suggests having breakfast together."}],"promptKana":"あさごはんをたべ＿＿＿。"}},"romaji":"Asagohan o tabemasen deshita.","german":"I didn't eat breakfast."},{"japanese":"昨日勉強しませんでした。","cloze":{"start":5,"answer":"ませんでした"},"romaji":"Kinō benkyō shimasen deshita.","german":"I didn't study yesterday."}],"notes":"This form is regular. You replace ます with ませんでした.","related":["masu","masen","mashita"]},
{"id":"te-form","pattern":"～て / ～で","level":"N5","category":"Verben","meaning":"て-form (connective form)","explanation":"The て-form is one of the most important verb forms in Japanese. It is used as the basis for many grammatical constructions, such as ～ている, ～てください and ～てもいい. How it is formed depends on the verb group.","formation":"Group 1 (godan): う・つ・る → って, む・ぶ・ぬ → んで, く → いて, ぐ → いで, す → して / Group 2 (ichidan): る → て / Group 3 (irregular): する → して, くる → きて","examples":[{"japanese":"本を読んでいます。","cloze":{"start":4,"answer":"で","quiz":{"level":"N5","japanese":"本を読んでいます。","german":"I'm reading a book.","start":4,"answer":"で","acceptedAnswers":["で"],"distractors":[{"text":"て","reason":"読む forms the voiced connective 読んで."},{"text":"た","reason":"読んた is not a form of 読む."},{"text":"だ","reason":"読んだ cannot come directly before います."}],"promptKana":"ほんをよん＿＿＿います。"}},"romaji":"Hon o yonde imasu.","german":"I'm reading a book."},{"japanese":"食べて寝ました。","cloze":{"start":2,"answer":"て"},"romaji":"Tabete nemashita.","german":"I ate and went to sleep."}],"notes":"The て-form on its own is not a complete sentence. One exception: 行って (as a short form of 行ってください = Go!). You have to memorize how the て-form is formed.","related":["te-iru","te-kudasai","temo-ii","te-connective","n4-te-yokatta"]},
{"id":"te-iru","pattern":"～ている","level":"N5","category":"Verben","meaning":"progressive form / state","explanation":"～ている expresses an ongoing action (progressive) or a resulting state. The polite form is ～ています. With some verbs it describes a state rather than an activity.","formation":"Verb て-form + いる / います","examples":[{"japanese":"今、本を読んでいます。","romaji":"Ima, hon o yonde imasu.","german":"I'm reading a book right now.","cloze":{"start":4,"answer":"読んでいます","quiz":{"level":"N5","japanese":"今、本を読んでいます。","german":"I'm reading a book right now.","start":4,"answer":"読んでいます","acceptedAnswers":["読んでいます"],"distractors":[{"text":"読みます","reason":"The translation stresses the action going on right now."},{"text":"読みません","reason":"This negates the reading."},{"text":"読みました","reason":"This describes finished reading instead of reading in progress."}],"promptKana":"いま、ほんを＿＿＿。"}}},{"japanese":"東京に住んでいます。","romaji":"Tōkyō ni sunde imasu.","german":"I live in Tokyo."}],"notes":"With state verbs such as 知る, 結婚する, 持つ, ている describes the resulting state: 知っています (I know it), not an ongoing action.","related":["te-form","n5-chuu-juu"]},
{"id":"te-kudasai","pattern":"～てください","level":"N5","category":"Verben","meaning":"please do...","explanation":"～てください is a polite request to do something. It corresponds to English \"Please do...\". It is one of the most common forms in everyday life.","formation":"Verb て-form + ください","examples":[{"japanese":"ここに名前を書いてください。","cloze":{"start":8,"answer":"てください","quiz":{"level":"N5","japanese":"ここに名前を書いてください。","german":"Please write your name here.","start":8,"answer":"てください","acceptedAnswers":["てください"],"distractors":[{"text":"でください","reason":"書く forms 書いて, not 書いで."},{"text":"たください","reason":"ください does not attach to the た-form."},{"text":"ますください","reason":"ください does not attach to the ます-form."}],"promptKana":"ここになまえをかい＿＿＿。"}},"romaji":"Koko ni namae o kaite kudasai.","german":"Please write your name here."},{"japanese":"もう一度言ってください。","cloze":{"start":6,"answer":"てください"},"romaji":"Mō ichido itte kudasai.","german":"Please say it once more."}],"notes":"てください is polite, but it is still an instruction. For even more polite requests you use ていただけませんか.","related":["te-form","naide-kudasai"]},
{"id":"naide-kudasai","pattern":"～ないでください","level":"N5","category":"Verben","meaning":"please don't...","explanation":"～ないでください is a polite request not to do something. It is the negative form of ～てください.","formation":"Verb ない-form + でください","examples":[{"japanese":"ここで写真を撮らないでください。","cloze":{"start":8,"answer":"ないでください","quiz":{"level":"N5","japanese":"ここで写真を撮らないでください。","german":"Please don't take photos here.","start":8,"answer":"ないでください","acceptedAnswers":["ないでください"],"distractors":[{"text":"なくください","reason":"The negative request needs ないで, not なく."},{"text":"ませんください","reason":"ません does not connect directly with ください."},{"text":"なかったください","reason":"The negative past does not form a request."}],"promptKana":"ここでしゃしんをとら＿＿＿。"}},"romaji":"Koko de shashin o toranaide kudasai.","german":"Please don't take photos here."},{"japanese":"心配しないでください。","cloze":{"start":3,"answer":"ないでください"},"romaji":"Shinpai shinaide kudasai.","german":"Please don't worry."}],"notes":"The ない-form is built from the dictionary form: group 1 (godan): う-row → あ-row + ない (書く → 書かない), group 2 (ichidan): る → ない (食べる → 食べない).","related":["te-kudasai"]},
{"id":"tai","pattern":"～たい","level":"N5","category":"Verben","meaning":"want to (do something)","explanation":"～たい expresses the speaker's wish to do something. It is conjugated like an い-adjective. You only use it for your own wishes, not for other people's.","formation":"Verb stem + たい","examples":[{"japanese":"水を飲みたいです。","cloze":{"start":4,"answer":"たい","quiz":{"level":"N5","japanese":"水を飲みたいです。","german":"I want to drink some water.","start":4,"answer":"たい","acceptedAnswers":["たい"],"distractors":[{"text":"ます","reason":"飲みますです doubles the polite ending, which is not allowed."},{"text":"ません","reason":"飲みませんです is not a desire form here."},{"text":"ました","reason":"飲みましたです is not a desire form here."}],"promptKana":"みずをのみ＿＿＿です。"}},"romaji":"Mizu o nomitai desu.","german":"I want to drink some water."},{"japanese":"日本に行きたいです。","cloze":{"start":5,"answer":"たい"},"romaji":"Nihon ni ikitai desu.","german":"I want to go to Japan."}],"notes":"たい is only used for yourself. For others you say ～たがっている. The object can be marked with を or が: 水を飲みたい / 水が飲みたい.","related":["ga-hoshii"]},
{"id":"mashou","pattern":"～ましょう","level":"N5","category":"Verben","meaning":"let's... / I'll...","explanation":"～ましょう expresses a suggestion (\"Let's...\") or an intention (\"I'll...\"). It is the polite volitional form.","formation":"Verb stem + ましょう","examples":[{"japanese":"一緒に行きましょう。","cloze":{"start":5,"answer":"ましょう","quiz":{"level":"N5","japanese":"一緒に行きましょう。","german":"Let's go together.","start":5,"answer":"ましょう","acceptedAnswers":["ましょう"],"distractors":[{"text":"ません","reason":"This is a negation, not a joint suggestion."},{"text":"ました","reason":"This reports something in the past."},{"text":"ませんでした","reason":"This negates a past action."}],"promptKana":"いっしょにいき＿＿＿。"}},"romaji":"Issho ni ikimashō.","german":"Let's go together."},{"japanese":"休みましょう。","cloze":{"start":2,"answer":"ましょう"},"romaji":"Yasumimashō.","german":"Let's take a break."}],"notes":"ましょう is a suggestion; ましょうか is a question about whether to do something together, or an offer.","related":["mashou-ka","n5-demo-suggestion","n5-masen-ka"]},
{"id":"mashou-ka","pattern":"～ましょうか","level":"N5","category":"Verben","meaning":"shall we...? / shall I...?","explanation":"～ましょうか is used as a question to suggest doing something together (\"Shall we...?\") or to offer help (\"Shall I...?\").","formation":"Verb stem + ましょうか","examples":[{"japanese":"窓を開けましょうか。","cloze":{"start":4,"answer":"ましょうか","quiz":{"level":"N5","japanese":"窓を開けましょうか。","german":"Shall I open the window?","start":4,"answer":"ましょうか","acceptedAnswers":["ましょうか"],"distractors":[{"text":"ました","reason":"This reports a past action instead of offering help."},{"text":"ません","reason":"This negates the opening instead of offering help."},{"text":"ませんでした","reason":"This reports that the window was not opened."}],"promptKana":"まどをあけ＿＿＿。"}},"romaji":"Mado o akemashō ka.","german":"Shall I open the window?"},{"japanese":"一緒に昼ごはんを食べましょうか。","cloze":{"start":10,"answer":"ましょうか"},"romaji":"Issho ni hirugohan o tabemashō ka.","german":"Shall we have lunch together?"}],"notes":"When you offer someone help, ましょうか is more polite than just ましょう.","related":["mashou","n5-masen-ka"]},
{"id":"temo-ii","pattern":"～てもいいです","level":"N5","category":"Verben","meaning":"may; it is all right to...","explanation":"～てもいいです expresses permission. It means \"you may...\" or \"it's okay if...\". As a question, it is used to ask for permission.","formation":"Verb て-form + もいいです","examples":[{"japanese":"ここで写真を撮ってもいいですか。","cloze":{"start":8,"answer":"てもいいです","quiz":{"level":"N5","japanese":"ここで写真を撮ってもいいですか。","german":"May I take photos here?","start":8,"answer":"てもいいです","acceptedAnswers":["てもいいです"],"distractors":[{"text":"たもいいです","reason":"Permission attaches to the て-form."},{"text":"てもいいでした","reason":"いい does not form its past with でした."},{"text":"てもいいます","reason":"いい, as an adjective, does not take ます."}],"promptKana":"ここでしゃしんをとっ＿＿＿か。"}},"romaji":"Koko de shashin o totte mo ii desu ka.","german":"May I take photos here?"},{"japanese":"帰ってもいいですよ。","cloze":{"start":2,"answer":"てもいいです"},"romaji":"Kaette mo ii desu yo.","german":"You may go home."}],"notes":"The negative \"you must not\" is ～てはいけません, not ～てもよくないです.","related":["te-form","tewa-ikemasen","nakutemo-ii","n4-temo-kamawanai"]},
{"id":"tewa-ikemasen","pattern":"～てはいけません","level":"N5","category":"Verben","meaning":"must not; it is forbidden to...","explanation":"～てはいけません expresses a prohibition. It means \"you must not...\" or \"it is not allowed to...\". It is stronger than a simple request.","formation":"Verb て-form + はいけません","examples":[{"japanese":"ここでタバコを吸ってはいけません。","cloze":{"start":9,"answer":"てはいけません","quiz":{"level":"N5","japanese":"ここでタバコを吸ってはいけません。","german":"You must not smoke here.","start":9,"answer":"てはいけません","acceptedAnswers":["てはいけません"],"distractors":[{"text":"たはいけません","reason":"The prohibition needs the て-form before は."},{"text":"てもいいです","reason":"This explicitly allows smoking."},{"text":"てください","reason":"This tells someone to smoke."}],"promptKana":"ここでタバコをすっ＿＿＿。"}},"romaji":"Koko de tabako o sutte wa ikemasen.","german":"You must not smoke here."},{"japanese":"教室で食べてはいけません。","cloze":{"start":5,"answer":"てはいけません"},"romaji":"Kyōshitsu de tabete wa ikemasen.","german":"You must not eat in the classroom."}],"notes":"In colloquial speech, ～ちゃだめ or ～ちゃいけない is used. ～てはいけません is the more formal variant.","related":["temo-ii","nakereba-naranai","n4-cha-ikenai"]},
{"id":"koto-ga-dekiru","pattern":"～ことができる","level":"N5","category":"Verben","meaning":"can; to be able to...","explanation":"～ことができる expresses the ability to do something. The polite form is ～ことができます. It is an alternative to the potential form of the verb.","formation":"Verb (dictionary form) + ことができる","examples":[{"japanese":"日本語を話すことができます。","romaji":"Nihongo o hanasu koto ga dekimasu.","german":"I can speak Japanese.","cloze":{"start":6,"answer":"ことができます","quiz":{"level":"N5","japanese":"日本語を話すことができます。","german":"I can speak Japanese.","start":6,"answer":"ことができます","acceptedAnswers":["ことができます"],"distractors":[{"text":"ことをできます","reason":"できる requires が in this construction."},{"text":"ことができません","reason":"The translation affirms the ability."},{"text":"ことができました","reason":"The translation states a present ability, not something that was possible in the past."}],"promptKana":"にほんごをはなす＿＿＿。"}}},{"japanese":"漢字を読むことができますか。","romaji":"Kanji o yomu koto ga dekimasu ka.","german":"Can you read kanji?"}],"notes":"This form is somewhat more formal than the potential form (話せる). The two are interchangeable, but ことができる is used more often in written language.","related":[]},
{"id":"ta-koto-ga-aru","pattern":"～たことがある","level":"N5","category":"Verben","meaning":"to have (ever) done... (experience)","explanation":"～たことがある expresses that you have experienced something before. It refers to experiences in the past. The polite form is ～たことがあります.","formation":"Verb た-form + ことがある","examples":[{"japanese":"日本に行ったことがあります。","romaji":"Nihon ni itta koto ga arimasu.","german":"I have been to Japan before.","cloze":{"start":5,"answer":"たことがあります","quiz":{"level":"N5","japanese":"日本に行ったことがあります。","german":"I have been to Japan before.","start":5,"answer":"たことがあります","acceptedAnswers":["たことがあります"],"distractors":[{"text":"たことがありません","reason":"This negates the experience."},{"text":"てことがあります","reason":"Experience requires the た-form."},{"text":"ますことがあります","reason":"A ます-form does not go before こと here."}],"promptKana":"にほんにいっ＿＿＿。"}}},{"japanese":"すしを食べたことがありますか。","romaji":"Sushi o tabeta koto ga arimasu ka.","german":"Have you ever eaten sushi?"}],"notes":"The negative is ～たことがない (I have never...). This form refers to your whole life experience, not to a specific event.","related":[]},
{"id":"ni-iku","pattern":"～に行く","level":"N5","category":"Verben","meaning":"to go (in order) to...","explanation":"～に行く expresses the purpose of a movement: you go somewhere in order to do something. Instead of 行く you can also use 来る or 帰る.","formation":"Verb stem + に行く / に来る / に帰る","examples":[{"japanese":"映画を見に行きます。","romaji":"Eiga o mi ni ikimasu.","german":"I'm going to see a movie.","cloze":{"start":4,"answer":"に行きます","quiz":{"level":"N5","japanese":"映画を見に行きます。","german":"I'm going to see a movie.","start":4,"answer":"に行きます","acceptedAnswers":["に行きます"],"distractors":[{"text":"を行きます","reason":"A purpose after the verb stem is marked with に."},{"text":"が行きます","reason":"が does not connect the verb stem as a purpose."},{"text":"で行きます","reason":"で does not attach to 見 as a purpose here."}],"promptKana":"えいがをみ＿＿＿。"}}},{"japanese":"昼ごはんを食べに来ませんか。","romaji":"Hirugohan o tabe ni kimasen ka.","german":"Won't you come over for lunch?"}],"notes":"You use the verb stem (masu-stem), not the dictionary form: 食べに行く (correct), 食べるに行く (wrong). With する-verbs: 買い物しに行く.","related":["ni"]},
{"id":"nagara","pattern":"～ながら","level":"N4","category":"Verben","meaning":"while; at the same time","explanation":"～ながら expresses that two actions are done at the same time by the same person. The main action comes at the end of the sentence, the secondary action before ながら.","formation":"Verb stem + ながら + main action","examples":[{"japanese":"音楽を聞きながら勉強します。","cloze":{"start":5,"answer":"ながら","quiz":{"level":"N4","japanese":"音楽を聞きながら勉強します。","german":"I study while listening to music.","start":5,"answer":"ながら","acceptedAnswers":["ながら"],"distractors":[{"text":"てから","reason":"聞きて is not a て-form; besides, it would mean \"only afterwards\"."},{"text":"たあとで","reason":"聞きた is not a た-form."},{"text":"ないで","reason":"聞きない is not a negative form."}],"promptKana":"おんがくをきき＿＿＿べんきょうします。"}},"romaji":"Ongaku o kikinagara benkyō shimasu.","german":"I study while listening to music."},{"japanese":"テレビを見ながら食べないでください。","cloze":{"start":5,"answer":"ながら"},"romaji":"Terebi o minagara tabenaide kudasai.","german":"Please don't eat while watching TV."}],"notes":"Both actions must be done by the same person. For different people you use ～間に (aida ni).","related":["n3-tsuide-ni"]},
{"id":"mae-ni","pattern":"～前に","level":"N5","category":"Verben","meaning":"before","explanation":"～前に means \"before doing something\" or \"before something\". With verbs, the dictionary form comes before 前に; with nouns, の comes before 前に.","formation":"Verb (dictionary form) + 前に / Noun + の前に","examples":[{"japanese":"寝る前に歯を磨きます。","cloze":{"start":2,"answer":"前に","quiz":{"level":"N5","japanese":"寝る前に歯を磨きます。","german":"I brush my teeth before going to bed.","start":2,"answer":"前に","acceptedAnswers":["前に"],"distractors":[{"text":"後で","reason":"After the dictionary form 寝る, 寝た後で doesn't fit; besides, the meaning is \"before\"."},{"text":"ながら","reason":"ながら requires the stem 寝, not 寝る."},{"text":"てから","reason":"てから must attach to the matching て-form."}],"promptKana":"ねる＿＿＿はをみがきます。"}},"romaji":"Neru mae ni ha o migakimasu.","german":"I brush my teeth before going to bed."},{"japanese":"食事の前に手を洗ってください。","cloze":{"start":3,"answer":"前に"},"romaji":"Shokuji no mae ni te o aratte kudasai.","german":"Please wash your hands before the meal."}],"notes":"The verb before 前に is always in the dictionary form, regardless of the tense of the main clause.","related":["ato-de"]},
{"id":"ato-de","pattern":"～後で","level":"N5","category":"Verben","meaning":"after","explanation":"～後で means \"after doing something\" or \"after something\". With verbs, the た-form comes before 後で; with nouns, の comes before 後で.","formation":"Verb た-form + 後で / Noun + の後で","examples":[{"japanese":"仕事の後で飲みに行きましょう。","cloze":{"start":3,"answer":"後で","quiz":{"level":"N5","japanese":"仕事の後で飲みに行きましょう。","german":"Let's go for a drink after work.","start":3,"answer":"後で","acceptedAnswers":["後で"],"distractors":[{"text":"前に","reason":"前に means \"before\" work, not \"after\"."},{"text":"ながら","reason":"仕事のながら is not a valid connection."},{"text":"てから","reason":"仕事のてから is not a valid connection."}],"promptKana":"しごとの＿＿＿のみにいきましょう。"}},"romaji":"Shigoto no ato de nomi ni ikimashō.","german":"Let's go for a drink after work."},{"japanese":"ごはんを食べた後で散歩しました。","cloze":{"start":7,"answer":"後で"},"romaji":"Gohan o tabeta ato de sanpo shimashita.","german":"After I ate, I went for a walk."}],"notes":"後で on its own can also mean \"later\": 後で電話します (I'll call later). ～てから is an alternative with a similar meaning.","related":["mae-ni","te-kara"]},
{"id":"tari-tari","pattern":"～たり～たりする","level":"N5","category":"Verben","meaning":"to do things like ... and ...","explanation":"～たり～たりする lists example actions. It means \"to do things like ... and ...\" and implies that other actions also take place. The final form is always する.","formation":"Verb た-form + り + Verb た-form + り + する","examples":[{"japanese":"週末は本を読んだりテレビを見たりします。","romaji":"Shūmatsu wa hon o yondari terebi o mitari shimasu.","german":"On weekends I do things like read books and watch TV.","cloze":{"start":5,"answer":"読んだりテレビを見たりします","quiz":{"level":"N5","japanese":"週末は本を読んだりテレビを見たりします。","german":"On weekends I do things like read books and watch TV.","start":5,"answer":"読んだりテレビを見たりします","acceptedAnswers":["読んだりテレビを見たりします"],"distractors":[{"text":"読んたりテレビを見たりします","reason":"読む forms 読んだり, not 読んたり."},{"text":"読んだりテレビを見だりします","reason":"見る forms 見たり, not 見だり."},{"text":"読むたりテレビを見るたりします","reason":"たり requires the た-form of the verbs."}],"promptKana":"しゅうまつはほんを＿＿＿。"}}},{"japanese":"休みの日は買い物したり料理したりしました。","romaji":"Yasumi no hi wa kaimono shitari ryōri shitari shimashita.","german":"On my days off I did things like shopping and cooking."}],"notes":"The list must always end with する (in the appropriate tense). It also works with adjectives: 大きかったり小さかったり.","related":["ya","n2-yara-yara"]},
{"id":"te-kara","pattern":"～てから","level":"N5","category":"Verben","meaning":"after; since","explanation":"～てから emphasizes the order of two actions: first the first action is completed, then the second begins. It stresses more strongly than 後で that the first action must be finished first.","formation":"Verb て-form + から","examples":[{"japanese":"手を洗ってから食べてください。","cloze":{"start":4,"answer":"てから","quiz":{"level":"N5","japanese":"手を洗ってから食べてください。","german":"Please wash your hands first and then eat.","start":4,"answer":"てから","acceptedAnswers":["てから"],"distractors":[{"text":"たから","reason":"This gives a reason instead of the order for the request."},{"text":"ますから","reason":"洗っます is not a verb form."},{"text":"ないから","reason":"洗っない is not a verb form."}],"promptKana":"てをあらっ＿＿＿たべてください。"}},"romaji":"Te o aratte kara tabete kudasai.","german":"Please wash your hands first and then eat."},{"japanese":"日本に来てから日本語を勉強し始めました。","cloze":{"start":4,"answer":"てから"},"romaji":"Nihon ni kite kara nihongo o benkyō shihajimemashita.","german":"After coming to Japan, I started studying Japanese."}],"notes":"てから emphasizes the sequence more strongly than 後で. With てから, the first action must be completed before the second begins.","related":["ato-de","te-form"]},
{"id":"naide","pattern":"～ないで","level":"N5","category":"Verben","meaning":"without doing...; instead of doing...","explanation":"～ないで means \"without doing something\". It expresses that one action is not carried out while another takes place.","formation":"Verb ない-form + で","examples":[{"japanese":"朝ごはんを食べないで学校に行きました。","cloze":{"start":7,"answer":"ないで","quiz":{"level":"N5","japanese":"朝ごはんを食べないで学校に行きました。","german":"I went to school without eating breakfast.","start":7,"answer":"ないで","acceptedAnswers":["ないで"],"distractors":[{"text":"てから","reason":"This says breakfast was eaten beforehand."},{"text":"ながら","reason":"This describes eating at the same time instead of going without breakfast."},{"text":"た後で","reason":"This says \"after breakfast\"."}],"promptKana":"あさごはんをたべ＿＿＿がっこうにいきました。"}},"romaji":"Asagohan o tabenaide gakkō ni ikimashita.","german":"I went to school without eating breakfast."},{"japanese":"辞書を使わないで読みました。","cloze":{"start":5,"answer":"ないで"},"romaji":"Jisho o tsukawanaide yomimashita.","german":"I read it without using a dictionary."}],"notes":"～ないで can also express a request when ください is added: 食べないでください (Please don't eat).","related":["naide-kudasai"]},
{"id":"sugiru","pattern":"～すぎる","level":"N4","category":"Verben","meaning":"too much; too","explanation":"～すぎる expresses that something is excessive. It can be used with verbs and adjectives and means \"too much\" or \"too\". すぎる itself conjugates as a group 2 (ichidan) verb.","formation":"Verb stem + すぎる / い-adj. (without い) + すぎる / な-adj. + すぎる","examples":[{"japanese":"昨日食べすぎました。","romaji":"Kinō tabesugimashita.","german":"I ate too much yesterday.","cloze":{"start":4,"answer":"すぎました","quiz":{"level":"N4","japanese":"昨日食べすぎました。","german":"I ate too much yesterday.","start":4,"answer":"すぎました","acceptedAnswers":["すぎました"],"distractors":[{"text":"すぎます","reason":"The completed action yesterday needs the past."},{"text":"すぎませんでした","reason":"This negates the overeating."},{"text":"すぎでした","reason":"すぎる is a verb and forms its polite past with ました."}],"promptKana":"きのうたべ＿＿＿。"}}},{"japanese":"この鞄は高すぎます。","romaji":"Kono kaban wa takasugimasu.","german":"This bag is too expensive."}],"notes":"With い-adjectives the い drops: 高い → 高すぎる. With な-adjectives the な drops: 静か → 静かすぎる.","related":["n2-ni-mo-hodo-ga-aru"]},
{"id":"kata","pattern":"～方","level":"N4","category":"Verben","meaning":"way of doing; how to...","explanation":"～方 (かた) means \"the way you do something\". It is attached to the verb stem and forms a noun.","formation":"Verb stem + 方(かた)","examples":[{"japanese":"この漢字の読み方を教えてください。","cloze":{"start":7,"answer":"方","quiz":{"level":"N4","japanese":"この漢字の読み方を教えてください。","german":"Please tell me how to read this kanji.","start":7,"answer":"方","acceptedAnswers":["方"],"distractors":[{"text":"ながら","reason":"ながら does not form a noun for the way of reading here."},{"text":"ます","reason":"読みます cannot come directly before を."},{"text":"たい","reason":"読みたい would need to be nominalized here; を cannot follow it directly."}],"promptKana":"このかんじのよみ＿＿＿をおしえてください。"}},"romaji":"Kono kanji no yomikata o oshiete kudasai.","german":"Please tell me how to read this kanji."},{"japanese":"使い方が分かりません。","cloze":{"start":2,"answer":"方"},"romaji":"Tsukaikata ga wakarimasen.","german":"I don't know how to use it."}],"notes":"方 is read かた when it means \"way, manner\". The result is a noun: 食べ方 (way of eating), 書き方 (way of writing).","related":[]},
{"id":"te-connective","pattern":"～て (Verbindung)","level":"N5","category":"Verben","meaning":"and then; and (linking clauses)","explanation":"The て-form can link clauses and express a sequence in time. It means \"and then\" or \"and\". The last verb in the sentence determines the tense.","formation":"Verb て-form + next action","examples":[{"japanese":"朝起きて、顔を洗って、朝ごはんを食べます。","romaji":"Asa okite, kao o aratte, asagohan o tabemasu.","german":"In the morning I get up, wash my face and eat breakfast.","cloze":{"start":1,"answer":"起きて","quiz":{"level":"N5","japanese":"朝起きて、顔を洗って、朝ごはんを食べます。","german":"In the morning I get up, wash my face and eat breakfast.","start":1,"answer":"起きて","acceptedAnswers":["起きて"],"distractors":[{"text":"起きたて","reason":"起きたて is a noun-like \"freshly ...\" form and does not link the action here."},{"text":"起きますて","reason":"The て-form is not attached to ます."},{"text":"起きないで","reason":"This says \"without getting up\" and contradicts the sequence."}],"promptKana":"あさ＿＿＿、かおをあらって、あさごはんをたべます。"}}},{"japanese":"バスに乗って学校に行きます。","romaji":"Basu ni notte gakkō ni ikimasu.","german":"I take the bus and go to school."}],"notes":"The て-form used as a link often implies a sequence in time. The last verb in the sentence determines the politeness level and tense for the whole sentence.","related":["te-form"]},
{"id":"nakutemo-ii","pattern":"～なくてもいい","level":"N5","category":"Verben","meaning":"don't have to; need not...","explanation":"～なくてもいい expresses that it is not necessary to do something. It is the opposite of ～なければならない. The polite form is ～なくてもいいです.","formation":"Verb ない-form (without い) + くてもいい","examples":[{"japanese":"明日は来なくてもいいです。","cloze":{"start":4,"answer":"なくてもいい","quiz":{"level":"N5","japanese":"明日は来なくてもいいです。","german":"You don't have to come tomorrow.","start":4,"answer":"なくてもいい","acceptedAnswers":["なくてもいい"],"distractors":[{"text":"なければならない","reason":"This obliges the person to come instead of releasing them from it."},{"text":"ないといけない","reason":"This obliges the person to come."},{"text":"なくてもいいます","reason":"いい is an adjective and does not take ます here."}],"promptKana":"あしたはこ＿＿＿です。"}},"romaji":"Ashita wa konakutemo ii desu.","german":"You don't have to come tomorrow."},{"japanese":"全部食べなくてもいいですよ。","cloze":{"start":4,"answer":"なくてもいい"},"romaji":"Zenbu tabenakutemo ii desu yo.","german":"You don't have to eat all of it."}],"notes":"How it's formed: Verb ない-form → ない becomes なくて: 食べない → 食べなくてもいい. Don't confuse it with ～てもいい (permission).","related":["temo-ii","nakereba-naranai","n4-nakute-wa-ikenai"]},
{"id":"te-miru","pattern":"～てみる","level":"N4","category":"Verben","meaning":"to try (doing) something","explanation":"～てみる means \"to try something out\" or \"to do something as a test\". It expresses that you do something for the first time or to see what it's like. The polite form is ～てみます.","formation":"Verb て-form + みる","examples":[{"japanese":"この料理を食べてみてください。","romaji":"Kono ryōri o tabete mite kudasai.","german":"Please try this dish.","cloze":{"start":7,"answer":"てみて","quiz":{"level":"N4","japanese":"この料理を食べてみてください。","german":"Please try this dish.","start":7,"answer":"てみて","acceptedAnswers":["てみて"],"distractors":[{"text":"てみます","reason":"A ます-form does not go before ください."},{"text":"たみて","reason":"Trying something out needs 食べて, not 食べた."},{"text":"てみた","reason":"The request needs みてください, not みたください."}],"promptKana":"このりょうりをたべ＿＿＿ください。"}}},{"japanese":"日本語で話してみます。","romaji":"Nihongo de hanashite mimasu.","german":"I'll try speaking in Japanese."}],"notes":"てみる stresses trying something out, not \"trying\" in the sense of making an effort. For \"to make an effort\" you would rather use ～ようとする.","related":["te-form","n2-te-miseru"]},
{"id":"te-shimau","pattern":"～てしまう","level":"N4","category":"Verben","meaning":"to do accidentally / to do completely","explanation":"～てしまう has two meanings: doing something unintentionally or regrettably, or completing an action fully. The polite form is ～てしまいます. In colloquial speech it is shortened to ～ちゃう.","formation":"Verb て-form + しまう","examples":[{"japanese":"財布を忘れてしまいました。","romaji":"Saifu o wasurete shimaimashita.","german":"Unfortunately, I forgot my wallet.","cloze":{"start":5,"answer":"てしまいました","quiz":{"level":"N4","japanese":"財布を忘れてしまいました。","german":"Unfortunately, I forgot my wallet.","start":5,"answer":"てしまいました","acceptedAnswers":["てしまいました"],"distractors":[{"text":"たしまいました","reason":"しまう attaches to the て-form."},{"text":"てしまいでした","reason":"The polite past ends in ました."},{"text":"てしまいませんでした","reason":"This negates the forgetting."}],"promptKana":"さいふをわすれ＿＿＿。"}}},{"japanese":"本を全部読んでしまいました。","romaji":"Hon o zenbu yonde shimaimashita.","german":"I finished reading the whole book."}],"notes":"Colloquial: ～てしまう → ～ちゃう (食べてしまう → 食べちゃう), ～でしまう → ～じゃう (飲んでしまう → 飲んじゃう).","related":["te-form"]},
{"id":"i-adj-present","pattern":"い-Adjektiv (Gegenwart)","level":"N5","category":"Adjektive","meaning":"い-adjective in the present form","explanation":"い-adjectives end in い and can come directly before a noun or be used as a predicate. In the polite predicate form, です is added.","formation":"い-adjective + です / い-adjective + Noun","examples":[{"japanese":"この本はおもしろいです。","romaji":"Kono hon wa omoshiroi desu.","german":"This book is interesting.","cloze":{"start":4,"answer":"おもしろいです","quiz":{"level":"N5","japanese":"この本はおもしろいです。","german":"This book is interesting.","start":4,"answer":"おもしろいです","acceptedAnswers":["おもしろいです"],"distractors":[{"text":"おもしろいでした","reason":"い-adjectives do not form the past with でした."},{"text":"おもしろいじゃないです","reason":"The regular negative is おもしろくないです."},{"text":"おもしろくありません","reason":"This means \"not interesting\"."}],"promptKana":"このほんは＿＿＿。"}}},{"japanese":"大きい犬が好きです。","romaji":"Ōkii inu ga suki desu.","german":"I like big dogs."}],"notes":"きれい (beautiful) and 有名 (famous) look like い-adjectives, but they are な-adjectives! There, the い is part of the word stem.","related":["i-adj-negative","i-adj-past","i-adj-past-negative"]},
{"id":"i-adj-negative","pattern":"～くない","level":"N5","category":"Adjektive","meaning":"い-adjective negative","explanation":"To negate an い-adjective, the い is replaced by くない. The polite form is ～くないです or ～くありません.","formation":"い-adjective (without い) + くない(です)","examples":[{"japanese":"今日は暑くないです。","cloze":{"start":4,"answer":"くない","quiz":{"level":"N5","japanese":"今日は暑くないです。","german":"It's not hot today.","start":4,"answer":"くない","acceptedAnswers":["くない"],"distractors":[{"text":"いない","reason":"Negating an い-adjective requires くない."},{"text":"かった","reason":"This would be the affirmative past."},{"text":"くなかった","reason":"This would be the negative past instead of today's state."}],"promptKana":"きょうはあつ＿＿＿です。"}},"romaji":"Kyō wa atsuku nai desu.","german":"It's not hot today."},{"japanese":"この映画はおもしろくないです。","cloze":{"start":9,"answer":"くない"},"romaji":"Kono eiga wa omoshiroku nai desu.","german":"This movie isn't interesting."}],"notes":"Exception: いい (good) → よくない (not good). The adjective いい changes to よ- in all conjugated forms.","related":["i-adj-present","i-adj-past","i-adj-past-negative","n5-amari-nai","n5-zenzen-nai"]},
{"id":"i-adj-past","pattern":"～かった","level":"N5","category":"Adjektive","meaning":"い-adjective past","explanation":"For the past form of an い-adjective, the い is replaced by かった. The polite form is ～かったです.","formation":"い-adjective (without い) + かった(です)","examples":[{"japanese":"昨日は寒かったです。","cloze":{"start":4,"answer":"かった","quiz":{"level":"N5","japanese":"昨日は寒かったです。","german":"It was cold yesterday.","start":4,"answer":"かった","acceptedAnswers":["かった"],"distractors":[{"text":"いでした","reason":"い-adjectives form the past with かった."},{"text":"くでした","reason":"くでした is not a past form."},{"text":"くない","reason":"This would be \"not cold\" instead of \"was cold\"."}],"promptKana":"きのうはさむ＿＿＿です。"}},"romaji":"Kinō wa samukatta desu.","german":"It was cold yesterday."},{"japanese":"旅行は楽しかったです。","cloze":{"start":5,"answer":"かった"},"romaji":"Ryokō wa tanoshikatta desu.","german":"The trip was fun."}],"notes":"Exception: いい (good) → よかった (was good). Remember: いい → よくない → よかった → よくなかった.","related":["i-adj-present","i-adj-negative","i-adj-past-negative"]},
{"id":"i-adj-past-negative","pattern":"～くなかった","level":"N5","category":"Adjektive","meaning":"い-adjective past (negative)","explanation":"For the negative past form of an い-adjective, the い is replaced by くなかった. The polite form is ～くなかったです.","formation":"い-adjective (without い) + くなかった(です)","examples":[{"japanese":"テストは難しくなかったです。","cloze":{"start":6,"answer":"くなかった","quiz":{"level":"N5","japanese":"テストは難しくなかったです。","german":"The test wasn't difficult.","start":6,"answer":"くなかった","acceptedAnswers":["くなかった"],"distractors":[{"text":"かった","reason":"This means \"was difficult\"."},{"text":"いなかった","reason":"The negative form needs く before なかった."},{"text":"くありません","reason":"This is non-past, not the past that is asked for."}],"promptKana":"テストはむずかし＿＿＿です。"}},"romaji":"Tesuto wa muzukashiku nakatta desu.","german":"The test wasn't difficult."},{"japanese":"あまりおいしくなかったです。","cloze":{"start":6,"answer":"くなかった"},"romaji":"Amari oishiku nakatta desu.","german":"It wasn't very tasty."}],"notes":"Exception: いい (good) → よくなかった (was not good).","related":["i-adj-present","i-adj-negative","i-adj-past"]},
{"id":"na-adj-present","pattern":"な-Adjektiv (Gegenwart)","level":"N5","category":"Adjektive","meaning":"な-adjective in the present form","explanation":"な-adjectives need な when they come directly before a noun. As a predicate, they are used with です like nouns. They do not conjugate like い-adjectives.","formation":"な-adjective + な + Noun / な-adjective + です","examples":[{"japanese":"ここは静かです。","romaji":"Koko wa shizuka desu.","german":"It's quiet here.","cloze":{"start":3,"answer":"静かです","quiz":{"level":"N5","japanese":"ここは静かです。","german":"It's quiet here.","start":3,"answer":"静かです","acceptedAnswers":["静かです"],"distractors":[{"text":"静かいです","reason":"静か is a な-adjective and doesn't take い."},{"text":"静かくないです","reason":"The negative of a な-adjective does not use くない."},{"text":"静かじゃないです","reason":"This means \"not quiet\"."}],"promptKana":"ここは＿＿＿。"}}},{"japanese":"元気な子供ですね。","romaji":"Genki na kodomo desu ne.","german":"That's a lively child, isn't it?"}],"notes":"な-adjectives behave like nouns when conjugating: they use じゃない, でした, じゃなかった instead of changing their ending.","related":["na-adj-negative","na-adj-past","na-adj-past-negative","n5-adverb-ku-ni"]},
{"id":"na-adj-negative","pattern":"な-Adjektiv + じゃない","level":"N5","category":"Adjektive","meaning":"な-adjective negative","explanation":"To negate a な-adjective, じゃないです or ではありません is used after the adjective stem. The conjugation is the same as for negating nouns.","formation":"な-adjective + じゃないです / ではありません","examples":[{"japanese":"この部屋はきれいじゃないです。","romaji":"Kono heya wa kirei ja nai desu.","german":"This room isn't clean.","cloze":{"start":8,"answer":"じゃないです","quiz":{"level":"N5","japanese":"この部屋はきれいじゃないです。","german":"This room isn't clean.","start":8,"answer":"じゃないです","acceptedAnswers":["じゃないです"],"distractors":[{"text":"です","reason":"This says the room is clean."},{"text":"くないです","reason":"Despite the い at the end, きれい is a な-adjective."},{"text":"でした","reason":"This is the affirmative past."}],"promptKana":"このへやはきれい＿＿＿。"}}},{"japanese":"日本語は簡単じゃありません。","romaji":"Nihongo wa kantan ja arimasen.","german":"Japanese isn't easy."}],"notes":"じゃないです is more colloquial, ではありません is more formal. Both are correct.","related":["na-adj-present","na-adj-past","na-adj-past-negative","ja-nai"]},
{"id":"na-adj-past","pattern":"な-Adjektiv + でした","level":"N5","category":"Adjektive","meaning":"な-adjective past","explanation":"For the past form of a な-adjective, でした is used after the adjective stem. The conjugation is the same as the past form of nouns.","formation":"な-adjective + でした","examples":[{"japanese":"パーティーはにぎやかでした。","romaji":"Pātī wa nigiyaka deshita.","german":"The party was lively.","cloze":{"start":10,"answer":"でした","quiz":{"level":"N5","japanese":"パーティーはにぎやかでした。","german":"The party was lively.","start":10,"answer":"でした","acceptedAnswers":["でした"],"distractors":[{"text":"かったです","reason":"な-adjectives do not form the past with かった."},{"text":"くなかったです","reason":"This is not a negative form of a な-adjective."},{"text":"じゃなかったです","reason":"This says the party was not lively."}],"promptKana":"パーティーはにぎやか＿＿＿。"}}},{"japanese":"彼は元気でした。","romaji":"Kare wa genki deshita.","german":"He was well. / He was doing fine."}],"notes":"The conjugation of な-adjectives follows the same pattern as Noun + です/でした/じゃない/じゃなかった.","related":["na-adj-present","na-adj-negative","na-adj-past-negative","deshita"]},
{"id":"na-adj-past-negative","pattern":"な-Adjektiv + じゃなかった","level":"N5","category":"Adjektive","meaning":"な-adjective past (negative)","explanation":"For the negative past form of a な-adjective, じゃなかったです or ではありませんでした is used.","formation":"な-adjective + じゃなかったです / ではありませんでした","examples":[{"japanese":"昨日は暇じゃなかったです。","romaji":"Kinō wa hima ja nakatta desu.","german":"I wasn't free yesterday.","cloze":{"start":4,"answer":"じゃなかったです","quiz":{"level":"N5","japanese":"昨日は暇じゃなかったです。","german":"I wasn't free yesterday.","start":4,"answer":"じゃなかったです","acceptedAnswers":["じゃなかったです"],"distractors":[{"text":"でした","reason":"This says there was free time."},{"text":"かったです","reason":"暇 is a な-adjective."},{"text":"くなかったです","reason":"暇 does not form its negative like an い-adjective."}],"promptKana":"きのうはひま＿＿＿。"}}},{"japanese":"あの店は有名じゃなかったです。","romaji":"Ano mise wa yūmei ja nakatta desu.","german":"That shop wasn't famous."}],"notes":"Here too: じゃなかったです is more colloquial, ではありませんでした is more formal.","related":["na-adj-present","na-adj-negative","na-adj-past","ja-nakatta"]},
{"id":"ku-naru-ni-naru","pattern":"～くなる / ～になる","level":"N5","category":"Adjektive","meaning":"to become ... (change)","explanation":"～くなる and ～になる express a change of state (\"something becomes something\"). い-adjectives use ～くなる; な-adjectives and nouns use ～になる.","formation":"い-adj. (without い) + くなる / な-adj. + になる / Noun + になる","examples":[{"japanese":"日本語が上手になりました。","romaji":"Nihongo ga jōzu ni narimashita.","german":"My Japanese has gotten better.","cloze":{"start":6,"answer":"になりました","quiz":{"level":"N5","japanese":"日本語が上手になりました。","german":"My Japanese has gotten better.","start":6,"answer":"になりました","acceptedAnswers":["になりました"],"distractors":[{"text":"くなりました","reason":"上手 is a な-adjective and requires に."},{"text":"になりません","reason":"This negates the change."},{"text":"になるでした","reason":"The polite past is なりました."}],"promptKana":"にほんごがじょうず＿＿＿。"}}},{"japanese":"最近寒くなりましたね。","romaji":"Saikin samuku narimashita ne.","german":"It's gotten cold lately, hasn't it?"}],"notes":"くなる/になる describes a natural or spontaneous change. For deliberate changes you use くする/にする.","related":["i-adj-present","na-adj-present","n5-adverb-ku-ni"]},
{"id":"no-ga-suki","pattern":"～のが好き / 上手 / 下手","level":"N5","category":"Adjektive","meaning":"to like doing / to be good at / to be bad at","explanation":"With ～のが, verbs can be nominalized so they can be combined with adjectives such as 好き (to like), 上手 (good at), 下手 (bad at).","formation":"Verb (dictionary form) + のが + 好き/上手/下手 + です","examples":[{"japanese":"料理を作るのが好きです。","cloze":{"start":5,"answer":"のが好き","quiz":{"level":"N5","japanese":"料理を作るのが好きです。","german":"I like cooking.","start":5,"answer":"のが好き","acceptedAnswers":["のが好き","ことが好き"],"distractors":[{"text":"が好き","reason":"The verb needs to be nominalized with の or こと here."},{"text":"のが嫌い","reason":"This means \"don't like cooking\"."},{"text":"のを好き","reason":"好き requires が here, not を."}],"promptKana":"りょうりをつくる＿＿＿です。"}},"romaji":"Ryōri o tsukuru no ga suki desu.","german":"I like cooking."},{"japanese":"歌を歌うのが下手です。","cloze":{"start":6,"answer":"下手"},"romaji":"Uta o utau no ga heta desu.","german":"I'm bad at singing."}],"notes":"上手 and 下手 are not used about yourself in polite speech. About yourself, you'd rather say 得意 (tokui, good at) or 苦手 (nigate, bad at).","related":["no"]},
{"id":"desu","pattern":"～です","level":"N5","category":"Satzstrukturen","meaning":"to be (polite copula)","explanation":"です is the polite form of the copula and means \"to be\". It is used after nouns and な-adjectives to make polite statements.","formation":"Noun + です / な-adjective + です","examples":[{"japanese":"私は田中です。","cloze":{"start":4,"answer":"です","quiz":{"level":"N5","japanese":"私は田中です。","german":"I am Tanaka.","start":4,"answer":"です","acceptedAnswers":["です"],"distractors":[{"text":"ます","reason":"A name does not take the verb ending ます."},{"text":"くないです","reason":"A name is not an い-adjective."},{"text":"じゃないです","reason":"This negates the identity."}],"promptKana":"わたしはたなか＿＿＿。"}},"romaji":"Watashi wa Tanaka desu.","german":"I am Tanaka."},{"japanese":"これはペンです。","cloze":{"start":5,"answer":"です"},"romaji":"Kore wa pen desu.","german":"This is a pen."}],"notes":"です is not used as a copula with い-adjectives; it is only added for politeness: 暑いです. With verbs, ます is used, not です.","related":["ja-nai","deshita","ja-nakatta"]},
{"id":"ja-nai","pattern":"～じゃない","level":"N5","category":"Satzstrukturen","meaning":"is not (negative of です)","explanation":"～じゃないです or ～ではありません is the negative of です. It means \"is not\" or \"am not\". じゃない is more colloquial, ではありません is more formal.","formation":"Noun + じゃないです / ではありません","examples":[{"japanese":"学生じゃないです。","cloze":{"start":2,"answer":"じゃない","quiz":{"level":"N5","japanese":"学生じゃないです。","german":"I'm not a student.","start":2,"answer":"じゃない","acceptedAnswers":["じゃない","ではない"],"distractors":[{"text":"くない","reason":"Nouns are not negated with くない."},{"text":"なかった","reason":"This is not a standalone copula negative after a noun."},{"text":"だった","reason":"だったです is not the regular polite negative here."}],"promptKana":"がくせい＿＿＿です。"}},"romaji":"Gakusei ja nai desu.","german":"I'm not a student."},{"japanese":"これは私のではありません。","romaji":"Kore wa watashi no dewa arimasen.","german":"This isn't mine."}],"notes":"じゃ is the short form of では. Both forms are correct: じゃないです (colloquial) and ではありません (formal).","related":["desu","deshita","ja-nakatta","n3-jan"]},
{"id":"deshita","pattern":"～でした","level":"N5","category":"Satzstrukturen","meaning":"was (past of です)","explanation":"～でした is the past form of です. It means \"was\" or \"were\".","formation":"Noun + でした / な-adjective + でした","examples":[{"japanese":"昨日は日曜日でした。","cloze":{"start":6,"answer":"でした","quiz":{"level":"N5","japanese":"昨日は日曜日でした。","german":"Yesterday was Sunday.","start":6,"answer":"でした","acceptedAnswers":["でした"],"distractors":[{"text":"ます","reason":"Nouns don't take the verb ending ます."},{"text":"かったです","reason":"Nouns don't take the い-adjective past."},{"text":"じゃありませんでした","reason":"This denies that it was Sunday."}],"promptKana":"きのうはにちようび＿＿＿。"}},"romaji":"Kinō wa nichiyōbi deshita.","german":"Yesterday was Sunday."},{"japanese":"とても大変でした。","cloze":{"start":5,"answer":"でした"},"romaji":"Totemo taihen deshita.","german":"It was really tough."}],"notes":"でした is used for nouns and な-adjectives. For い-adjectives in the past, ～かったです is used, not ～いでした.","related":["desu","ja-nai","ja-nakatta"]},
{"id":"ja-nakatta","pattern":"～じゃなかった","level":"N5","category":"Satzstrukturen","meaning":"was not (past, negative)","explanation":"～じゃなかったです or ～ではありませんでした is the negative past form of です. It means \"was not\".","formation":"Noun + じゃなかったです / ではありませんでした","examples":[{"japanese":"あの人は先生じゃなかったです。","cloze":{"start":6,"answer":"じゃなかった","quiz":{"level":"N5","japanese":"あの人は先生じゃなかったです。","german":"That person wasn't a teacher.","start":6,"answer":"じゃなかった","acceptedAnswers":["じゃなかった","ではなかった"],"distractors":[{"text":"だった","reason":"This says the person was a teacher instead of denying it."},{"text":"くなかった","reason":"A noun is not negated with くなかった."},{"text":"じゃない","reason":"This is non-past instead of the past that is asked for."}],"promptKana":"あのひとはせんせい＿＿＿です。"}},"romaji":"Ano hito wa sensei ja nakatta desu.","german":"That person wasn't a teacher."},{"japanese":"天気はよくありませんでした。","romaji":"Tenki wa yoku arimasen deshita.","german":"The weather wasn't good."}],"notes":"The four forms make up a system: です → じゃない → でした → じゃなかった. This system applies to nouns and な-adjectives.","related":["desu","ja-nai","deshita"]},
{"id":"n-desu","pattern":"～んです / ～のです","level":"N5","category":"Satzstrukturen","meaning":"it's that... (explanation/emphasis)","explanation":"～んです is used to give an explanation, ask for an explanation, or emphasize a statement. It signals that the speaker wants to explain the context.","formation":"Verb/い-adj. + んです / な-adj. + なんです / Noun + なんです","examples":[{"japanese":"どうしたんですか。","cloze":{"start":4,"answer":"んです","quiz":{"level":"N5","japanese":"どうしたんですか。","german":"What's wrong? / What happened?","start":4,"answer":"んです","acceptedAnswers":["んです","のです"],"distractors":[{"text":"なです","reason":"A verbal statement is not connected with なです here."},{"text":"にです","reason":"にです is not an explanatory connection here."},{"text":"をです","reason":"をです is not an explanatory connection here."}],"promptKana":"どうした＿＿＿か。"}},"romaji":"Dō shita n desu ka.","german":"What's wrong? / What happened?"},{"japanese":"明日テストがあるんです。","cloze":{"start":8,"answer":"んです"},"romaji":"Ashita tesuto ga aru n desu.","german":"It's just that I have a test tomorrow."}],"notes":"んです (spoken form) and のです (written form) are interchangeable. ～んですか sounds more natural than ～ますか when you ask for the reason behind something.","related":["n3-no-dewa-nai-ka"]},
{"id":"to-omoimasu","pattern":"～と思います","level":"N5","category":"Satzstrukturen","meaning":"I think that...","explanation":"～と思います expresses your own opinion or assumption. It corresponds to English \"I think (that)...\". For other people's opinions, you use ～と思っています.","formation":"Sentence (plain form) + と思います","examples":[{"japanese":"明日は雨が降ると思います。","cloze":{"start":7,"answer":"と思います","quiz":{"level":"N5","japanese":"明日は雨が降ると思います。","german":"I think it will rain tomorrow.","start":7,"answer":"と思います","acceptedAnswers":["と思います"],"distractors":[{"text":"を思います","reason":"A complete thought is quoted with と."},{"text":"に思います","reason":"に does not link a quoted sentence here."},{"text":"が思います","reason":"が does not replace the quotation particle here."}],"promptKana":"あしたはあめがふる＿＿＿。"}},"romaji":"Ashita wa ame ga furu to omoimasu.","german":"I think it will rain tomorrow."},{"japanese":"この本はおもしろいと思います。","cloze":{"start":9,"answer":"と思います"},"romaji":"Kono hon wa omoshiroi to omoimasu.","german":"I think this book is interesting."}],"notes":"The plain form comes before と思います, not the ます-form: 行くと思います (correct), 行きますと思います (wrong).","related":["deshou","kamoshirenai","n3-ki-ga-suru"]},
{"id":"deshou","pattern":"～でしょう","level":"N5","category":"Satzstrukturen","meaning":"probably; presumably","explanation":"～でしょう expresses a guess and means \"probably\" or \"I suppose...\". It is less certain than a direct statement, but more certain than かもしれない.","formation":"Verb/い-adj. (plain form) + でしょう / な-adj./Noun + でしょう","examples":[{"japanese":"明日は暖かいでしょう。","cloze":{"start":6,"answer":"でしょう","quiz":{"level":"N5","japanese":"明日は暖かいでしょう。","german":"It will probably be warm tomorrow.","start":6,"answer":"でしょう","acceptedAnswers":["でしょう"],"distractors":[{"text":"でした","reason":"暖かいでした is not a regular adjective form."},{"text":"ました","reason":"An い-adjective does not take ました."},{"text":"くでしょう","reason":"The guess comes after 暖かい, not 暖かいく."}],"promptKana":"あしたはあたたかい＿＿＿。"}},"romaji":"Ashita wa atatakai deshō.","german":"It will probably be warm tomorrow."},{"japanese":"彼はもう帰ったでしょう。","cloze":{"start":7,"answer":"でしょう"},"romaji":"Kare wa mō kaetta deshō.","german":"He has probably gone home already."}],"notes":"でしょう is often used in weather forecasts. With rising intonation (でしょう？) you are seeking confirmation: そうでしょう？ (Right?).","related":["to-omoimasu","kamoshirenai","n4-kana-kashira","n3-no-dewa-nai-ka"]},
{"id":"kamoshirenai","pattern":"～かもしれない","level":"N4","category":"Satzstrukturen","meaning":"maybe; it might be that...","explanation":"～かもしれない expresses an uncertain guess. It means \"maybe\" or \"it might be that...\". The polite form is ～かもしれません.","formation":"Verb/い-adj. (plain form) + かもしれない / な-adj./Noun + かもしれない","examples":[{"japanese":"雨が降るかもしれません。","romaji":"Ame ga furu kamoshiremasen.","german":"It might rain.","cloze":{"start":4,"answer":"かもしれません","quiz":{"level":"N4","japanese":"雨が降るかもしれません。","german":"It might rain.","start":4,"answer":"かもしれません","acceptedAnswers":["かもしれません"],"distractors":[{"text":"かもしれます","reason":"The fixed form for possibility is かもしれません."},{"text":"かもします","reason":"This is not a form of the possibility expression."},{"text":"なのかもしれません","reason":"No な is inserted after a verb here."}],"promptKana":"あめがふる＿＿＿。"}}},{"japanese":"あの人は日本人かもしれません。","romaji":"Ano hito wa nihonjin kamoshiremasen.","german":"That person might be Japanese."}],"notes":"Level of certainty: かもしれない (maybe, ~30%) < でしょう (probably, ~70%) < と思います (I think, personal opinion).","related":["deshou","to-omoimasu"]},
{"id":"ga-aru","pattern":"～がある","level":"N5","category":"Satzstrukturen","meaning":"there is (inanimate things)","explanation":"～がある is used to express the existence of inanimate things (objects, plants, buildings, events). The polite form is ～があります.","formation":"Noun + がある / があります","examples":[{"japanese":"机の上に本があります。","romaji":"Tsukue no ue ni hon ga arimasu.","german":"There is a book on the desk.","cloze":{"start":5,"answer":"があります","quiz":{"level":"N5","japanese":"机の上に本があります。","german":"There is a book on the desk.","start":5,"answer":"があります","acceptedAnswers":["があります","はあります"],"distractors":[{"text":"がいます","reason":"A book is not a living being."},{"text":"をあります","reason":"あります does not take a direct object."},{"text":"がありません","reason":"This denies that the book is there."}],"promptKana":"つくえのうえにほん＿＿＿。"}}},{"japanese":"明日テストがあります。","romaji":"Ashita tesuto ga arimasu.","german":"There's a test tomorrow."}],"notes":"ある is used for inanimate things, いる for living beings (people, animals). ある is also used for events.","related":["ga-iru","ga"]},
{"id":"ga-iru","pattern":"～がいる","level":"N5","category":"Satzstrukturen","meaning":"there is (living beings)","explanation":"～がいる is used to express the existence of living beings (people, animals). The polite form is ～がいます.","formation":"Noun + がいる / がいます","examples":[{"japanese":"公園に子供がいます。","romaji":"Kōen ni kodomo ga imasu.","german":"There are children in the park.","cloze":{"start":5,"answer":"がいます","quiz":{"level":"N5","japanese":"公園に子供がいます。","german":"There are children in the park.","start":5,"answer":"がいます","acceptedAnswers":["がいます","はいます"],"distractors":[{"text":"があります","reason":"People are described with いる here."},{"text":"をいます","reason":"います does not take a direct object here."},{"text":"がいません","reason":"This denies that they are there."}],"promptKana":"こうえんにこども＿＿＿。"}}},{"japanese":"私は兄弟が三人います。","romaji":"Watashi wa kyōdai ga sannin imasu.","german":"I have three siblings."}],"notes":"Rule of thumb: anything that can move by itself uses いる. Plants and cars use ある, even though they are \"alive\" or move.","related":["ga-aru","ga"]},
{"id":"ga-hoshii","pattern":"～が欲しい","level":"N5","category":"Satzstrukturen","meaning":"to want (to have) something","explanation":"～が欲しい expresses the wish to own or get something. It is conjugated like an い-adjective and only used for your own wishes.","formation":"Noun + が欲しい(です)","examples":[{"japanese":"新しいパソコンが欲しいです。","cloze":{"start":7,"answer":"が欲しい","quiz":{"level":"N5","japanese":"新しいパソコンが欲しいです。","german":"I want a new computer.","start":7,"answer":"が欲しい","acceptedAnswers":["が欲しい","は欲しい"],"distractors":[{"text":"に欲しい","reason":"The thing you want is not marked with に."},{"text":"が欲しくない","reason":"This negates the wish."},{"text":"が欲しいでした","reason":"欲しい does not form its past with でした."}],"promptKana":"あたらしいパソコン＿＿＿です。"}},"romaji":"Atarashii pasokon ga hoshii desu.","german":"I want a new computer."},{"japanese":"何が欲しいですか。","cloze":{"start":1,"answer":"が欲しい"},"romaji":"Nani ga hoshii desu ka.","german":"What do you want?"}],"notes":"欲しい is for things (nouns), たい is for actions (verbs). For other people, you use ～欲しがっている.","related":["tai"]},
{"id":"tsumori","pattern":"～つもり","level":"N5","category":"Satzstrukturen","meaning":"intention; to intend to","explanation":"～つもり expresses a firm intention or plan. It means \"I plan to...\" or \"I intend to...\". The negative can be formed in two ways.","formation":"Verb (dictionary form) + つもりです / Verb ない-form + つもりです","examples":[{"japanese":"来年日本に行くつもりです。","cloze":{"start":7,"answer":"つもり","quiz":{"level":"N5","japanese":"来年日本に行くつもりです。","german":"I plan to go to Japan next year.","start":7,"answer":"つもり","acceptedAnswers":["つもり"],"distractors":[{"text":"ながら","reason":"ながら requires the verb stem and does not form a noun before です here."},{"text":"てから","reason":"行くてから is not a correct connection."},{"text":"ました","reason":"行くましたです is not a verb form."}],"promptKana":"らいねんにほんにいく＿＿＿です。"}},"romaji":"Rainen Nihon ni iku tsumori desu.","german":"I plan to go to Japan next year."},{"japanese":"もうお酒を飲まないつもりです。","cloze":{"start":9,"answer":"つもり"},"romaji":"Mō osake o nomanai tsumori desu.","german":"I intend not to drink alcohol anymore."},{"japanese":"もう甘いものは食べないつもりだ。","romaji":"Mō amai mono wa tabenai tsumori da.","german":"I'm not going to eat sweets anymore."}],"notes":"つもり expresses a personal intention. For other people's plans, you use ～予定 (yotei) or ask directly.","related":["n4-volitional","n4-koto-ni-suru","n4-you-to-omou"],"legacyIds":["n4-tsumori"]},
{"id":"yori","pattern":"～より","level":"N5","category":"Satzstrukturen","meaning":"than; compared to (comparative)","explanation":"～より is used for comparisons and marks what something is compared with. It corresponds to English \"than\" in comparisons.","formation":"B + より + A + のほうが + Adjective","examples":[{"japanese":"東京は大阪より大きいです。","cloze":{"start":5,"answer":"より","quiz":{"level":"N5","japanese":"東京は大阪より大きいです。","german":"Tokyo is bigger than Osaka.","start":5,"answer":"より","acceptedAnswers":["より"],"distractors":[{"text":"まで","reason":"まで sets a limit, not a standard of comparison."},{"text":"から","reason":"から does not express a comparison of size here."},{"text":"へ","reason":"へ indicates a direction, not a comparison of size."}],"promptKana":"とうきょうはおおさか＿＿＿おおきいです。"}},"romaji":"Tōkyō wa Ōsaka yori ōkii desu.","german":"Tokyo is bigger than Osaka."},{"japanese":"バスより電車のほうが速いです。","cloze":{"start":2,"answer":"より"},"romaji":"Basu yori densha no hō ga hayai desu.","german":"Trains are faster than buses."}],"notes":"より marks the \"loser\" in the comparison. The full structure is: B より A のほうが ～. You can also use just より: 東京は大阪より大きい.","related":["no-hou-ga","ichiban","n3-to-iu-yori"]},
{"id":"no-hou-ga","pattern":"～のほうが","level":"N5","category":"Satzstrukturen","meaning":"... is more / ... rather (comparative)","explanation":"～のほうが marks the preferred or highlighted side in a comparison. It is often combined with ～より.","formation":"Noun + のほうが + Adjective","examples":[{"japanese":"夏より冬のほうが好きです。","cloze":{"start":4,"answer":"のほうが","quiz":{"level":"N5","japanese":"夏より冬のほうが好きです。","german":"I like winter better than summer.","start":4,"answer":"のほうが","acceptedAnswers":["のほうが","が"],"distractors":[{"text":"のほうを","reason":"好き requires が here, not を."},{"text":"のほうに","reason":"に does not mark the preferred item in the comparison here."},{"text":"のほどが","reason":"のほどが is not the comparative construction asked for."}],"promptKana":"なつよりふゆ＿＿＿すきです。"}},"romaji":"Natsu yori fuyu no hō ga suki desu.","german":"I like winter better than summer."},{"japanese":"こっちのほうが安いです。","cloze":{"start":3,"answer":"のほうが"},"romaji":"Kocchi no hō ga yasui desu.","german":"This one is cheaper."}],"notes":"どちらのほうが (dochira no hō ga) is used in questions: コーヒーとお茶とどちらのほうが好きですか。 (Which do you like better, coffee or tea?)","related":["yori","ichiban"]},
{"id":"ichiban","pattern":"～が一番","level":"N5","category":"Satzstrukturen","meaning":"most; best (superlative)","explanation":"一番 (いちばん) means \"most\" or \"number one\" and is used for superlatives. It comes before the adjective.","formation":"(Noun + の中で) + Noun + が一番 + Adjective","examples":[{"japanese":"果物の中でりんごが一番好きです。","cloze":{"start":8,"answer":"が一番","quiz":{"level":"N5","japanese":"果物の中でりんごが一番好きです。","german":"Of all fruits, I like apples best.","start":8,"answer":"が一番","acceptedAnswers":["が一番","は一番"],"distractors":[{"text":"が一つ","reason":"一つ counts one item, not the top rank."},{"text":"を一番","reason":"好き requires が here, not を."},{"text":"に一番","reason":"に does not mark the preferred item here."}],"promptKana":"くだもののなかでりんご＿＿＿すきです。"}},"romaji":"Kudamono no naka de ringo ga ichiban suki desu.","german":"Of all fruits, I like apples best."},{"japanese":"日本で一番高い山は富士山です。","romaji":"Nihon de ichiban takai yama wa Fujisan desu.","german":"The highest mountain in Japan is Mt. Fuji."},{"japanese":"クラスで誰が一番背が高い？","romaji":"Kurasu de dare ga ichiban se ga takai?","german":"Who's the tallest in the class?"}],"notes":"For questions you use: ～の中で何/どこ/誰が一番～ですか。 (What/Where/Who is the most ~?)","related":["yori","no-hou-ga","n4-yori","n3-ni-kagiru"],"legacyIds":["n4-ichiban"]},
{"id":"mada","pattern":"まだ～","level":"N5","category":"Satzstrukturen","meaning":"still / not yet","explanation":"まだ means \"still\". With an affirmative form it means \"still\"; with a negative form it means \"not yet\".","formation":"まだ + Verb/Adjective (affirmative or negative)","examples":[{"japanese":"まだ雨が降っています。","romaji":"Mada ame ga futte imasu.","german":"It's still raining.","cloze":{"start":0,"answer":"まだ","quiz":{"level":"N5","japanese":"まだ雨が降っています。","german":"It's still raining.","start":0,"answer":"まだ","acceptedAnswers":["まだ"],"distractors":[{"text":"もうすぐ","reason":"This means \"soon\" instead of \"still\"."},{"text":"これから","reason":"This means \"from now on\" instead of \"still\"."},{"text":"きのう","reason":"This means \"yesterday\" instead of \"still\"."}],"promptKana":"＿＿＿あめがふっています。"}}},{"japanese":"まだ食べていません。","romaji":"Mada tabete imasen.","german":"I haven't eaten yet."}],"notes":"To the question もう～ましたか (Have you already...?) you answer: はい、もう～ました (Yes, already) or いいえ、まだです (No, not yet).","related":["mou"]},
{"id":"mou","pattern":"もう～","level":"N5","category":"Satzstrukturen","meaning":"already / no longer","explanation":"With an affirmative form, もう means \"already\". With a negative form it means \"no longer\" or \"not anymore\". It expresses that a change has taken place.","formation":"もう + Verb (affirmative: already / negative: no longer)","examples":[{"japanese":"もう宿題をしました。","romaji":"Mō shukudai o shimashita.","german":"I've already done my homework.","cloze":{"start":0,"answer":"もう","quiz":{"level":"N5","japanese":"もう宿題をしました。","german":"I've already done my homework.","start":0,"answer":"もう","acceptedAnswers":["もう","すでに"],"distractors":[{"text":"あした","reason":"This means \"tomorrow\" instead of \"already\"."},{"text":"これから","reason":"This means \"from now on\" instead of \"already\"."},{"text":"もうすぐ","reason":"This means \"soon\" instead of \"already done\"."}],"promptKana":"＿＿＿しゅくだいをしました。"}}},{"japanese":"もう食べません。","romaji":"Mō tabemasen.","german":"I won't eat any more."}],"notes":"もう一度 (mō ichido) means \"once more\"; here もう has a different meaning. もう and まだ form a pair of opposites.","related":["mada"]},
{"id":"dake","pattern":"～だけ","level":"N5","category":"Satzstrukturen","meaning":"only; just","explanation":"～だけ means \"only\" or \"just\" and limits something. It can be used after nouns, verbs and numbers.","formation":"Noun + だけ / Verb + だけ","examples":[{"japanese":"水だけ飲みます。","cloze":{"start":1,"answer":"だけ","quiz":{"level":"N5","japanese":"水だけ飲みます。","german":"I only drink water.","start":1,"answer":"だけ","acceptedAnswers":["だけ"],"distractors":[{"text":"まで","reason":"まで expresses \"even water\" here instead of \"only water\"."},{"text":"へ","reason":"A direction does not mark the drink."},{"text":"しか","reason":"しか requires a negative verb form."}],"promptKana":"みず＿＿＿のみます。"}},"romaji":"Mizu dake nomimasu.","german":"I only drink water."},{"japanese":"少しだけ食べました。","cloze":{"start":2,"answer":"だけ"},"romaji":"Sukoshi dake tabemashita.","german":"I only ate a little."}],"notes":"だけ limits neutrally; しか～ない puts more stress on how little there is or that it's the only thing (only, just ... and nothing else).","related":["shika-nai"]},
{"id":"shika-nai","pattern":"～しか～ない","level":"N5","category":"Satzstrukturen","meaning":"only; nothing but (stresses the limit)","explanation":"～しか～ない means \"only\" and stresses that something is little or limited. It is always used with the negative verb form and often expresses disappointment or regret.","formation":"Noun + しか + Verb (negative)","examples":[{"japanese":"百円しかありません。","romaji":"Hyaku-en shika arimasen.","german":"I only have a hundred yen.","cloze":{"start":2,"answer":"しかありません","quiz":{"level":"N5","japanese":"百円しかありません。","german":"I only have a hundred yen.","start":2,"answer":"しかありません","acceptedAnswers":["しかありません","だけあります"],"distractors":[{"text":"しかあります","reason":"しか requires a negative form."},{"text":"だけありません","reason":"This means \"exactly a hundred yen are missing\"."},{"text":"がたくさんあります","reason":"This claims a large amount instead of only a hundred yen."}],"promptKana":"ひゃくえん＿＿＿。"}}},{"japanese":"日本語しか話せません。","romaji":"Nihongo shika hanasemasen.","german":"I can only speak Japanese."}],"notes":"しか replaces は、が and を, but is added on to other particles: にしか、でしか. Difference from だけ: しか stresses the limit more strongly.","related":["dake","n4-shika-nai-option"]},
{"id":"toki","pattern":"～時","level":"N5","category":"Satzstrukturen","meaning":"when (time)","explanation":"～時 (とき) means \"when\" and indicates a point or period in time. It can be used with verbs, adjectives and nouns.","formation":"Verb (dictionary/た-form) + 時 / い-adj. + 時 / な-adj. + な + 時 / Noun + の + 時","examples":[{"japanese":"日本に行った時、たくさん写真を撮りました。","cloze":{"start":6,"answer":"時","quiz":{"level":"N5","japanese":"日本に行った時、たくさん写真を撮りました。","german":"When I went to Japan, I took a lot of photos.","start":6,"answer":"時","acceptedAnswers":["時","際"],"distractors":[{"text":"ながら","reason":"ながら requires the stem, not 行った."},{"text":"前に","reason":"前に requires the dictionary form here, not 行った."},{"text":"てから","reason":"てから cannot also be attached to 行った."}],"promptKana":"にほんにいった＿＿＿、たくさんしゃしんをとりました。"}},"romaji":"Nihon ni itta toki, takusan shashin o torimashita.","german":"When I went to Japan, I took a lot of photos."},{"japanese":"暇な時、何をしますか。","cloze":{"start":2,"answer":"時"},"romaji":"Hima na toki, nani o shimasu ka.","german":"What do you do when you have free time?"}],"notes":"Dictionary form + 時 = \"when you are going to do something\"; た-form + 時 = \"after you have done something\". The difference is subtle and depends on context.","related":["tara"]},
{"id":"tara","pattern":"～たら","level":"N5","category":"Satzstrukturen","meaning":"if; when; after","explanation":"～たら expresses a condition: \"If/When A happens, then B\". It can also mean \"after\". The form is made from the た-form + ら.","formation":"Verb た-form + ら / い-adj. → ～かったら / な-adj./Noun → だったら","examples":[{"japanese":"雨が降ったら、家にいます。","cloze":{"start":4,"answer":"たら","quiz":{"level":"N5","japanese":"雨が降ったら、家にいます。","german":"If it rains, I'll stay at home.","start":4,"answer":"たら","acceptedAnswers":["たら"],"distractors":[{"text":"れば","reason":"降っれば is not a conditional form."},{"text":"なら","reason":"降っなら is not a valid connecting form."},{"text":"ても","reason":"降っても means \"even if\" instead of the neutral condition."}],"promptKana":"あめがふっ＿＿＿、いえにいます。"}},"romaji":"Ame ga futtara, ie ni imasu.","german":"If it rains, I'll stay at home."},{"japanese":"安かったら買います。","cloze":{"start":3,"answer":"たら"},"romaji":"Yasukattara kaimasu.","german":"If it's cheap, I'll buy it."}],"notes":"たら is the most versatile conditional form. It can be used for hypothetical and real conditions. Unlike ～と, たら is also used for one-time situations.","related":["toki"]},
{"id":"ga-but","pattern":"～が (aber)","level":"N5","category":"Satzstrukturen","meaning":"but; however","explanation":"が is used as a conjunction to connect two clauses with contrasting or complementary content. It means \"but\" or \"however\". Don't confuse it with the subject particle が.","formation":"Sentence 1 + が、+ Sentence 2","examples":[{"japanese":"日本語は難しいですが、おもしろいです。","romaji":"Nihongo wa muzukashii desu ga, omoshiroi desu.","german":"Japanese is difficult, but interesting.","cloze":{"start":9,"answer":"が","quiz":{"level":"N5","japanese":"日本語は難しいですが、おもしろいです。","german":"Japanese is difficult, but interesting.","start":9,"answer":"が","acceptedAnswers":["が","けど","けれど","けれども","のに"],"distractors":[{"text":"ので","reason":"This gives a reason instead of the intended contrast."},{"text":"ます","reason":"ですます doubles the polite ending, which is not allowed."},{"text":"を","reason":"を does not connect contrasting statements here."}],"promptKana":"にほんごはむずかしいです＿＿＿、おもしろいです。"}}},{"japanese":"すみませんが、もう一度言ってください。","romaji":"Sumimasen ga, mō ichido itte kudasai.","german":"I'm sorry, but please say it once more."}],"notes":"が as a conjunction is more formal than けど. It is often used for polite lead-ins: ～ですが... (It's that..., but...).","related":["kedo"]},
{"id":"kedo","pattern":"～けど / ～けれども","level":"N5","category":"Satzstrukturen","meaning":"but; although (colloquial)","explanation":"～けど is the colloquial version of が (but). The more formal form is ～けれども. It connects two clauses with contrasting content.","formation":"Sentence 1 (plain) + けど、+ Sentence 2","examples":[{"japanese":"高いけど、おいしいです。","cloze":{"start":2,"answer":"けど","quiz":{"level":"N5","japanese":"高いけど、おいしいです。","german":"It's expensive, but it's tasty.","start":2,"answer":"けど","acceptedAnswers":["けど","が","けれど","けれども","のに"],"distractors":[{"text":"ので","reason":"This gives \"expensive\" as a reason instead of a contrast."},{"text":"から","reason":"This gives a reason instead of \"although it's expensive\"."},{"text":"のため","reason":"のため is not a correct connection after the い-adjective here."}],"promptKana":"たかい＿＿＿、おいしいです。"}},"romaji":"Takai kedo, oishii desu.","german":"It's expensive, but it's tasty."},{"japanese":"行きたいけど、時間がありません。","cloze":{"start":4,"answer":"けど"},"romaji":"Ikitai kedo, jikan ga arimasen.","german":"I want to go, but I don't have time."}],"notes":"Level of formality: けど (most casual) → けれど → けれども (formal) → が (most formal). けど can also come at the end of a sentence and leave it open.","related":["ga-but"]},
{"id":"kara-because","pattern":"～から (weil)","level":"N5","category":"Satzstrukturen","meaning":"because; so","explanation":"から after a verb or adjective means \"because\". It gives the reason for the action described in the main clause. The reason comes before から.","formation":"Sentence (reason) + から、+ Sentence (result)","examples":[{"japanese":"暑いから、窓を開けましょう。","romaji":"Atsui kara, mado o akemashō.","german":"It's hot, so let's open the window.","cloze":{"start":2,"answer":"から","quiz":{"level":"N5","japanese":"暑いから、窓を開けましょう。","german":"It's hot, so let's open the window.","start":2,"answer":"から","acceptedAnswers":["から","ので"],"distractors":[{"text":"のため","reason":"のため is not a correct connection after 暑い."},{"text":"なのに","reason":"No な is inserted after 暑い."},{"text":"けれど","reason":"This sets up a contrast instead of the stated reason."}],"promptKana":"あつい＿＿＿、まどをあけましょう。"}}},{"japanese":"明日テストがありますから、今日勉強します。","romaji":"Ashita tesuto ga arimasu kara, kyō benkyō shimasu.","german":"I have a test tomorrow, so I'm studying today."}],"notes":"から (because) is more subjective than ので. から can also come at the end of a sentence to add a reason afterwards: 行きません。高いですから。","related":["node","kara"]},
{"id":"node","pattern":"～ので","level":"N5","category":"Satzstrukturen","meaning":"because; since (more polite than から)","explanation":"～ので gives a reason and is more polite and objective than から. It is often used in more formal situations or in writing.","formation":"Verb/い-adj. (plain form) + ので / な-adj. + なので / Noun + なので","examples":[{"japanese":"病気なので、休みます。","cloze":{"start":3,"answer":"ので","quiz":{"level":"N5","japanese":"病気なので、休みます。","german":"I'm sick, so I'll take the day off.","start":3,"answer":"ので","acceptedAnswers":["ので"],"distractors":[{"text":"から","reason":"病気なから is not a form; the correct one would be 病気だから."},{"text":"ため","reason":"病気なため is not a correct noun connection."},{"text":"けど","reason":"病気なけど is not a correct connection."}],"promptKana":"びょうきな＿＿＿、やすみます。"}},"romaji":"Byōki na node, yasumimasu.","german":"I'm sick, so I'll take the day off."},{"japanese":"電車が遅れたので、遅刻しました。","cloze":{"start":6,"answer":"ので"},"romaji":"Densha ga okureta node, chikoku shimashita.","german":"Since the train was delayed, I was late."}],"notes":"ので sounds more polite and less direct than から. With requests and apologies, ので is preferred. The plain form comes before ので (na-adj. + なので).","related":["kara-because"]},
{"id":"noni","pattern":"～のに","level":"N4","category":"Satzstrukturen","meaning":"although; even though","explanation":"～のに expresses a contradiction or disappointment. It means \"although\" or \"even though\" and shows that the result is different from what was expected.","formation":"Verb/い-adj. (plain form) + のに / な-adj. + なのに / Noun + なのに","examples":[{"japanese":"たくさん勉強したのに、テストに落ちました。","cloze":{"start":8,"answer":"のに","quiz":{"level":"N4","japanese":"たくさん勉強したのに、テストに落ちました。","german":"Even though I studied a lot, I failed the test.","start":8,"answer":"のに","acceptedAnswers":["のに","けれど","けれども","けど","が"],"distractors":[{"text":"ので","reason":"This claims a reason instead of the contrast."},{"text":"から","reason":"This makes the studying the reason for failing."},{"text":"ために","reason":"This gives a cause or purpose instead of the unexpected contrast."}],"promptKana":"たくさんべんきょうした＿＿＿、テストにおちました。"}},"romaji":"Takusan benkyō shita noni, tesuto ni ochimashita.","german":"Even though I studied a lot, I failed the test."},{"japanese":"約束したのに、来ませんでした。","cloze":{"start":4,"answer":"のに"},"romaji":"Yakusoku shita noni, kimasen deshita.","german":"Even though he promised, he didn't come."}],"notes":"のに often expresses disappointment or frustration. It is more subjective than けれども and implies that the result is unwelcome.","related":["kedo","ga-but"]},
{"id":"nakereba-naranai","pattern":"～なければならない","level":"N5","category":"Satzstrukturen","meaning":"must; it is necessary to...","explanation":"～なければならない means \"must\" or \"have to\". It expresses an obligation or necessity. There are several short forms of it.","formation":"Verb ない-form (without い) + ければならない","examples":[{"japanese":"毎日薬を飲まなければなりません。","romaji":"Mainichi kusuri o nomanakereba narimasen.","german":"I have to take medicine every day.","cloze":{"start":6,"answer":"なければなりません","quiz":{"level":"N5","japanese":"毎日薬を飲まなければなりません。","german":"I have to take medicine every day.","start":6,"answer":"なければなりません","acceptedAnswers":["なければなりません","なくてはいけません","ないといけません"],"distractors":[{"text":"なくてもいいです","reason":"This explicitly removes the obligation."},{"text":"ないほうがいいです","reason":"This advises against taking it."},{"text":"なくてはいけます","reason":"The obligation needs the negative ending いけません."}],"promptKana":"まいにちくすりをのま＿＿＿。"}}},{"japanese":"宿題をしなければなりません。","romaji":"Shukudai o shinakereba narimasen.","german":"I have to do my homework."}],"notes":"Short forms: ～なければならない → ～なければいけない → ～なきゃいけない → ～なきゃ (shortest, colloquial). They all have the same meaning.","related":["tewa-ikemasen","nakutemo-ii","n4-nakute-wa-ikenai","n4-nai-to-ikenai","n2-neba-naranai","n4-nakya-nakucha"]},
{"id":"donna","pattern":"どんな","level":"N5","category":"Satzstrukturen","meaning":"what kind of","explanation":"どんな is a question word that asks about the kind or nature of something. It comes directly before a noun and means \"What kind of...?\".","formation":"どんな + Noun","examples":[{"japanese":"どんな音楽が好きですか。","cloze":{"start":0,"answer":"どんな","quiz":{"level":"N5","japanese":"どんな音楽が好きですか。","german":"What kind of music do you like?","start":0,"answer":"どんな","acceptedAnswers":["どんな"],"distractors":[{"text":"どう","reason":"Before a noun, the attributive どんな is used here."},{"text":"だれ","reason":"だれ asks about a person, not a kind of music."},{"text":"どこ","reason":"どこ asks about a place, not a kind of music."}],"promptKana":"＿＿＿おんがくがすきですか。"}},"romaji":"Donna ongaku ga suki desu ka.","german":"What kind of music do you like?"},{"japanese":"どんな人ですか。","cloze":{"start":0,"answer":"どんな"},"romaji":"Donna hito desu ka.","german":"What kind of person is he/she?"}],"notes":"どんな belongs to the こそあど series: こんな (this kind, like this one here), そんな (that kind, like that one there), あんな (that kind, like that one over there), どんな (what kind?).","related":["n5-kore-sore-are-dore","n5-kono-sono-ano-dono"]},
{"id":"counters","pattern":"数え方 (Zählwörter)","level":"N5","category":"Satzstrukturen","meaning":"counters; counter words","explanation":"In Japanese, counters (suffixes) are used after numbers, depending on the shape or type of the thing being counted. The most important N5 counters are ～つ (general), ～人 (people), ～本 (long things), ～枚 (flat things), ～匹 (small animals), ～台 (machines/vehicles).","formation":"Number + counter + の + Noun / Noun + を + Number + counter + Verb","examples":[{"japanese":"りんごを三つください。","romaji":"Ringo o mittsu kudasai.","german":"Three apples, please.","cloze":{"start":4,"answer":"三つ","quiz":{"level":"N5","japanese":"りんごを三つください。","german":"Three apples, please.","start":4,"answer":"三つ","acceptedAnswers":["三つ","三個"],"distractors":[{"text":"一つ","reason":"The translation calls for three apples, not one."},{"text":"二つ","reason":"The translation calls for three apples, not two."},{"text":"四つ","reason":"The translation calls for three apples, not four."}],"promptKana":"りんごを＿＿＿ください。"}}},{"japanese":"学生が五人います。","romaji":"Gakusei ga gonin imasu.","german":"There are five students."}],"notes":"～つ (hitotsu, futatsu...) is the general counter and works up to 10. After that you use the specific counter. With some counters the numbers change: 三本 = さんぼん, 一匹 = いっぴき.","related":["n5-tachi"]},
{"id":"hou-ga-ii","pattern":"～ほうがいい","level":"N4","category":"Satzstrukturen","meaning":"should; it would be better to...","explanation":"～ほうがいい is used to give advice. It means \"You should...\" or \"It would be better if...\". For positive advice you use the た-form, for negative advice the ない-form.","formation":"Verb た-form + ほうがいい (should do) / Verb ない-form + ほうがいい (should not do)","examples":[{"japanese":"もっと野菜を食べたほうがいいですよ。","cloze":{"start":9,"answer":"ほうがいい","quiz":{"level":"N4","japanese":"もっと野菜を食べたほうがいいですよ。","german":"You should eat more vegetables.","start":9,"answer":"ほうがいい","acceptedAnswers":["ほうがいい"],"distractors":[{"text":"ほうをいい","reason":"いい requires が in this evaluation."},{"text":"ほうにいい","reason":"に does not replace が here."},{"text":"ほうがよくない","reason":"This advises against eating more vegetables."}],"promptKana":"もっとやさいをたべた＿＿＿ですよ。"}},"romaji":"Motto yasai o tabeta hō ga ii desu yo.","german":"You should eat more vegetables."},{"japanese":"夜遅く食べないほうがいいです。","cloze":{"start":7,"answer":"ほうがいい"},"romaji":"Yoru osoku tabenai hō ga ii desu.","german":"You shouldn't eat late at night."}],"notes":"Positive advice: た-form + ほうがいい. Negative advice: ない-form + ほうがいい. This form can sound direct; with superiors it's better to use ～たらどうですか.","related":["yori","no-hou-ga"]},
{"id":"temo","pattern":"～ても / ～でも","level":"N4","category":"Satzstrukturen","meaning":"even if","explanation":"～ても expresses that something holds true despite a certain condition. It means \"even if\". The result doesn't change, whether or not the condition occurs.","formation":"Verb て-form + も / い-adj. (～くても) / な-adj. (～でも) / Noun (～でも)","examples":[{"japanese":"雨が降っても行きます。","cloze":{"start":4,"answer":"ても","quiz":{"level":"N4","japanese":"雨が降っても行きます。","german":"Even if it rains, I'll go.","start":4,"answer":"ても","acceptedAnswers":["ても"],"distractors":[{"text":"たも","reason":"\"Even if\" needs ても, not たも."},{"text":"れば","reason":"降っれば is not a conditional form."},{"text":"ないと","reason":"降っない is not a negative form."}],"promptKana":"あめがふっ＿＿＿いきます。"}},"romaji":"Ame ga futte mo ikimasu.","german":"Even if it rains, I'll go."},{"japanese":"高くても買いたいです。","cloze":{"start":2,"answer":"ても"},"romaji":"Takakutemo kaitai desu.","german":"Even if it's expensive, I want to buy it."}],"notes":"い-adjectives: 高い → 高くても. な-adjectives: 静か → 静かでも. Nouns: 雨 → 雨でも. Don't confuse it with ～てもいい (permission).","related":["temo-ii","noni","n5-demo-suggestion","n4-temo-kamawanai","n3-tatte-datte","n3-tatoe-temo","n2-te-made","n2-te-demo"]},
{"id":"no-wa-desu","pattern":"～のは～です","level":"N5","category":"Satzstrukturen","meaning":"(doing) ... is ... (nominalization)","explanation":"～のは～です nominalizes part of a sentence with の and makes it the topic. It lets you talk about actions or situations as nouns. It is often used for explanations and definitions.","formation":"Verb/Sentence + のは + Noun/Adjective + です","examples":[{"japanese":"日本語を勉強するのは楽しいです。","romaji":"Nihongo o benkyō suru no wa tanoshii desu.","german":"Studying Japanese is fun.","cloze":{"start":8,"answer":"のは","quiz":{"level":"N5","japanese":"日本語を勉強するのは楽しいです。","german":"Studying Japanese is fun.","start":8,"answer":"のは","acceptedAnswers":["のは","のが","ことは","ことが"],"distractors":[{"text":"を","reason":"を does not nominalize the activity."},{"text":"に","reason":"に does not nominalize the activity."},{"text":"と","reason":"と does not form a nominalized topic here."}],"promptKana":"にほんごをべんきょうする＿＿＿たのしいです。"}}},{"japanese":"朝早く起きるのは大変です。","romaji":"Asa hayaku okiru no wa taihen desu.","german":"Getting up early in the morning is hard."}],"notes":"の turns a sentence into a noun. Similar constructions: ～のが好き (to like doing), ～のを忘れる (to forget to do).","related":["no","no-ga-suki"]},
{"id":"n4-bakari-p","pattern":"～ばかり","level":"N4","category":"Partikel","meaning":"only, nothing but","explanation":"ばかり expresses that someone does something exclusively or excessively.","formation":"Verb (て-form) + ばかり / Noun + ばかり","examples":[{"japanese":"彼はゲームばかりしている。","cloze":{"start":5,"answer":"ばかり","quiz":{"level":"N4","japanese":"彼はゲームばかりしている。","german":"He does nothing but play games.","start":5,"answer":"ばかり","acceptedAnswers":["ばかり","だけ"],"distractors":[{"text":"しか","reason":"しか requires a negative verb form."},{"text":"へ","reason":"へ does not mark an exclusive activity here."},{"text":"から","reason":"から does not express \"nothing but games\" here."}],"promptKana":"かれはゲーム＿＿＿している。"}},"romaji":"Kare wa gēmu bakari shiteiru.","german":"He does nothing but play games."},{"japanese":"甘いものばかり食べないで。","cloze":{"start":4,"answer":"ばかり"},"romaji":"Amai mono bakari tabenaide.","german":"Don't eat only sweet things."}],"notes":"With the た-form it means \"just (now)\": 来たばかり = just arrived.","related":["dake","shika-nai","n2-bakari-da"]},
{"id":"n4-sae","pattern":"～さえ","level":"N3","category":"Partikel","meaning":"even","explanation":"さえ emphasizes an extreme case and implies that everything else goes without saying.","formation":"Noun + さえ / Verb (ます-stem) + さえする","examples":[{"japanese":"子供でさえ知っている。","cloze":{"start":3,"answer":"さえ","quiz":{"level":"N3","japanese":"子供でさえ知っている。","german":"Even children know that.","start":3,"answer":"さえ","acceptedAnswers":["さえ","も"],"distractors":[{"text":"しか","reason":"しか requires a negative verb form."},{"text":"から","reason":"子供でから is not a suitable connection."},{"text":"を","reason":"子供でを is not a suitable particle combination."}],"promptKana":"こどもで＿＿＿しっている。"}},"romaji":"Kodomo de sae shitteiru.","german":"Even children know that."},{"japanese":"名前さえ覚えていない。","cloze":{"start":2,"answer":"さえ"},"romaji":"Namae sae oboeteinai.","german":"I don't even remember the name."}],"notes":"さえ～ば means \"if only / as long as\": お金さえあれば = If only I had money.","related":["mo","n2-te-made","n2-mo-shinai"]},
{"id":"n4-koso","pattern":"～こそ","level":"N3","category":"Partikel","meaning":"precisely, exactly (emphasis)","explanation":"こそ is an emphatic particle that gives special emphasis to the word before it.","formation":"Noun + こそ","examples":[{"japanese":"こちらこそよろしくお願いします。","cloze":{"start":3,"answer":"こそ","quiz":{"level":"N3","japanese":"こちらこそよろしくお願いします。","german":"Likewise, nice to meet you.","start":3,"answer":"こそ","acceptedAnswers":["こそ","も"],"distractors":[{"text":"を","reason":"を does not express an emphatic reply."},{"text":"へ","reason":"へ marks a direction rather than \"likewise\"."},{"text":"しか","reason":"しか does not fit the positive ending."}],"promptKana":"こちら＿＿＿よろしくおねがいします。"}},"romaji":"Kochira koso yoroshiku onegai shimasu.","german":"Likewise, nice to meet you."},{"japanese":"今年こそ合格したい。","cloze":{"start":2,"answer":"こそ"},"romaji":"Kotoshi koso gōkaku shitai.","german":"This year I really want to pass."}],"notes":"Very common: こちらこそ (likewise / the pleasure is mine).","related":["wa"]},
{"id":"n4-hodo-p","pattern":"～ほど","level":"N4","category":"Partikel","meaning":"to the extent that; degree","explanation":"ほど expresses degree or extent. Often used in comparisons and in ～ば～ほど (the more ..., the more ...).","formation":"Verb (辞書形) + ほど / Noun + ほど","examples":[{"japanese":"泣きたいほど嬉しかった。","cloze":{"start":4,"answer":"ほど","quiz":{"level":"N4","japanese":"泣きたいほど嬉しかった。","german":"I was so happy I wanted to cry.","start":4,"answer":"ほど","acceptedAnswers":["ほど","くらい","ぐらい"],"distractors":[{"text":"ながら","reason":"ながら follows the verb stem, not たい."},{"text":"すぎて","reason":"泣きたいすぎて is not a correct connection."},{"text":"から","reason":"This makes the wish to cry the reason rather than the degree of happiness."}],"promptKana":"なきたい＿＿＿うれしかった。"}},"romaji":"Nakitai hodo ureshikatta.","german":"I was so happy I wanted to cry."},{"japanese":"勉強すればするほど面白い。","cloze":{"start":7,"answer":"ほど"},"romaji":"Benkyō sureba suru hodo omoshiroi.","german":"The more you study, the more interesting it gets."}],"notes":"～ば～ほど = the more ..., the more .... Negative: ～ほど～ない = not as ... as.","related":["n4-ba","n3-ba-hodo"]},
{"id":"n4-zutsu","pattern":"～ずつ","level":"N4","category":"Partikel","meaning":"each; little by little","explanation":"ずつ expresses equal distribution or gradual change.","formation":"Number/quantity + ずつ","examples":[{"japanese":"毎日少しずつ勉強しています。","cloze":{"start":4,"answer":"ずつ","quiz":{"level":"N4","japanese":"毎日少しずつ勉強しています。","german":"I study a little every day.","start":4,"answer":"ずつ","acceptedAnswers":["ずつ"],"distractors":[{"text":"しか","reason":"しか requires a negative."},{"text":"へ","reason":"へ does not divide studying into small amounts."},{"text":"をに","reason":"をに is not a quantity particle combination here."}],"promptKana":"まいにちすこし＿＿＿べんきょうしています。"}},"romaji":"Mainichi sukoshi zutsu benkyō shiteimasu.","german":"I study a little every day."},{"japanese":"一人に二つずつ配ってください。","cloze":{"start":5,"answer":"ずつ"},"romaji":"Hitori ni futatsu zutsu kubatte kudasai.","german":"Please hand out two to each person."}],"notes":"少しずつ (little by little) is especially common.","related":[]},
{"id":"n4-nado","pattern":"～など","level":"N4","category":"Partikel","meaning":"and so on; such as","explanation":"など lists examples and implies that there are more. More formal than とか.","formation":"Noun + など","examples":[{"japanese":"りんごやバナナなどの果物が好きです。","cloze":{"start":7,"answer":"など","quiz":{"level":"N4","japanese":"りんごやバナナなどの果物が好きです。","german":"I like fruit such as apples and bananas.","start":7,"answer":"など","acceptedAnswers":["など","等"],"distractors":[{"text":"しか","reason":"しか does not fit the positive predicate."},{"text":"へ","reason":"への would mark a destination rather than examples of fruit."},{"text":"から","reason":"からの marks an origin rather than a set of examples."}],"promptKana":"りんごやバナナ＿＿＿のくだものがすきです。"}},"romaji":"Ringo ya banana nado no kudamono ga suki desu.","german":"I like fruit such as apples and bananas."},{"japanese":"私などまだまだです。","cloze":{"start":1,"answer":"など"},"romaji":"Watashi nado mada mada desu.","german":"Someone like me still has a long way to go."}],"notes":"Casual variant: なんか. Often with や: AやBなど.","related":["ya","n4-toka","n3-nante-nanka","n3-to-itta"]},
{"id":"n4-toshite","pattern":"～として","level":"N3","category":"Partikel","meaning":"as; in the role of","explanation":"として indicates the function or capacity in which someone or something is regarded.","formation":"Noun + として","examples":[{"japanese":"留学生として日本に来ました。","cloze":{"start":3,"answer":"として","quiz":{"level":"N3","japanese":"留学生として日本に来ました。","german":"I came to Japan as an exchange student.","start":3,"answer":"として","acceptedAnswers":["として"],"distractors":[{"text":"としての","reason":"の would have to modify a noun, not 日本に来ました."},{"text":"にとって","reason":"This marks a point of view rather than the role in which the person came to Japan."},{"text":"によると","reason":"This names a source of information rather than a role."}],"promptKana":"りゅうがくせい＿＿＿にほんにきました。"}},"romaji":"Ryūgakusei toshite Nihon ni kimashita.","german":"I came to Japan as an exchange student."},{"japanese":"この町は観光地として有名です。","cloze":{"start":7,"answer":"として"},"romaji":"Kono machi wa kankōchi toshite yūmei desu.","german":"This town is famous as a tourist destination."}],"notes":"Common with job titles and roles.","related":["n2-wo-to-shite"]},
{"id":"n4-ni-taishite","pattern":"～に対して","level":"N3","category":"Partikel","meaning":"toward; in contrast to","explanation":"に対して expresses whom an action is directed at, or a contrast between two things.","formation":"Noun + に対して","examples":[{"japanese":"お客様に対して丁寧に話してください。","cloze":{"start":3,"answer":"に対して","quiz":{"level":"N3","japanese":"お客様に対して丁寧に話してください。","german":"Please speak politely to customers.","start":3,"answer":"に対して","acceptedAnswers":["に対して","に"],"distractors":[{"text":"に対する","reason":"The attributive form needs a noun after it."},{"text":"にとって","reason":"This marks a point of view, not the customers being addressed."},{"text":"によると","reason":"This marks a news source, not the people being spoken to."}],"promptKana":"おきゃくさま＿＿＿ていねいにはなしてください。"}},"romaji":"Okyakusama ni taishite teinei ni hanashite kudasai.","german":"Please speak politely to customers."},{"japanese":"兄はスポーツが好きなのに対して、弟は読書が好きだ。","cloze":{"start":11,"answer":"に対して"},"romaji":"Ani wa supōtsu ga suki na no ni taishite, otōto wa dokusho ga suki da.","german":"My older brother likes sports, whereas my younger brother likes reading."}],"notes":"Before a noun: ～に対する + noun (e.g. 学生に対する態度).","related":["ni"]},
{"id":"n4-ni-totte","pattern":"～にとって","level":"N4","category":"Partikel","meaning":"for (from the point of view of)","explanation":"にとって expresses from whose perspective something is judged.","formation":"Noun + にとって","examples":[{"japanese":"私にとって家族が一番大切です。","cloze":{"start":1,"answer":"にとって","quiz":{"level":"N4","japanese":"私にとって家族が一番大切です。","german":"For me, family is the most important thing.","start":1,"answer":"にとって","acceptedAnswers":["にとって"],"distractors":[{"text":"によると","reason":"This marks a quoted source of information rather than one's own standard of value."},{"text":"としての","reason":"の needs a following head noun here."},{"text":"をとって","reason":"をとって is not the perspective construction."}],"promptKana":"わたし＿＿＿かぞくがいちばんたいせつです。"}},"romaji":"Watashi ni totte kazoku ga ichiban taisetsu desu.","german":"For me, family is the most important thing."},{"japanese":"外国人にとって漢字は難しい。","cloze":{"start":3,"answer":"にとって"},"romaji":"Gaikokujin ni totte kanji wa muzukashii.","german":"Kanji are difficult for foreigners."}],"notes":"Don't confuse with ～のために (for the purpose of). にとって = subjective perspective.","related":["ni","n2-ni-shitara"]},
{"id":"n4-ni-yotte","pattern":"～によって","level":"N4","category":"Partikel","meaning":"by, by means of; depending on","explanation":"によって has several meanings: means (by means of), the agent in the passive (by), and variation depending on the situation.","formation":"Noun + によって","examples":[{"japanese":"この小説は夏目漱石によって書かれた。","cloze":{"start":9,"answer":"によって","quiz":{"level":"N4","japanese":"この小説は夏目漱石によって書かれた。","german":"This novel was written by Natsume Sōseki.","start":9,"answer":"によって","acceptedAnswers":["によって","に"],"distractors":[{"text":"による","reason":"による modifies a noun, not the following verb."},{"text":"にとって","reason":"This marks a perspective rather than the author."},{"text":"について","reason":"This would make the author the subject matter of the novel."}],"promptKana":"このしょうせつはなつめそうせき＿＿＿かかれた。"}},"romaji":"Kono shōsetsu wa Natsume Sōseki ni yotte kakareta.","german":"This novel was written by Natsume Sōseki."},{"japanese":"国によって文化が違います。","cloze":{"start":1,"answer":"によって"},"romaji":"Kuni ni yotte bunka ga chigaimasu.","german":"Culture differs from country to country."}],"notes":"Before a noun: ～による + noun. ～によると = according to.","related":["n4-rareru","n4-ni-yoru-to","n3-ni-yori-ni-yoru","n2-ni-yotte-wa"]},
{"id":"n4-no-you-ni","pattern":"～のように / ～みたいに","level":"N4","category":"Partikel","meaning":"like, just like, similar to","explanation":"のように (formal) and みたいに (casual) express a comparison.","formation":"Noun + のように / Noun + みたいに","examples":[{"japanese":"鳥のように空を飛びたい。","cloze":{"start":1,"answer":"のように","quiz":{"level":"N4","japanese":"鳥のように空を飛びたい。","german":"I want to fly through the sky like a bird.","start":1,"answer":"のように","acceptedAnswers":["のように","みたいに"],"distractors":[{"text":"のような","reason":"Before the verb, the adverbial form with に is needed."},{"text":"なように","reason":"After a noun, の is used here."},{"text":"のようでの","reason":"This does not form an adverbial comparison."}],"promptKana":"とり＿＿＿そらをとびたい。"}},"romaji":"Tori no yō ni sora o tobitai.","german":"I want to fly through the sky like a bird."},{"japanese":"子供みたいに遊んでいる。","cloze":{"start":2,"answer":"みたいに"},"romaji":"Kodomo mitai ni asondeiru.","german":"He's playing like a child."}],"notes":"Before a noun: のような/みたいな: 夢のような話 = a dreamlike story.","related":["n4-you-da","n4-mitai-da"]},
{"id":"n4-dake-de-naku","pattern":"～だけでなく","level":"N4","category":"Partikel","meaning":"not only ... but also","explanation":"だけでなく expresses that not just one thing applies, but another one as well.","formation":"Noun/Verb/Adj + だけでなく ～も","examples":[{"japanese":"日本語だけでなく中国語も話せます。","cloze":{"start":3,"answer":"だけでなく","quiz":{"level":"N4","japanese":"日本語だけでなく中国語も話せます。","german":"I can speak not only Japanese but also Chinese.","start":3,"answer":"だけでなく","acceptedAnswers":["だけでなく","だけではなく","ばかりでなく","のみならず"],"distractors":[{"text":"しか","reason":"しか requires a negative ending."},{"text":"だけでないの","reason":"の cannot connect to the following clause here."},{"text":"だけでは","reason":"This leaves the contrastive link to the additional language incomplete."}],"promptKana":"にほんご＿＿＿ちゅうごくごもはなせます。"}},"romaji":"Nihongo dake de naku chūgokugo mo hanasemasu.","german":"I can speak not only Japanese but also Chinese."},{"japanese":"安いだけでなく、おいしいです。","cloze":{"start":2,"answer":"だけでなく"},"romaji":"Yasui dake de naku, oishii desu.","german":"It's not only cheap but also tasty."}],"notes":"Casual: ～だけじゃなくて. Formal: ～のみならず.","related":["dake","mo"]},
{"id":"n4-rareru","pattern":"～られる / ～れる","level":"N4","category":"Verben","meaning":"passive form","explanation":"The passive form expresses that the subject undergoes an action. Japanese also has the \"suffering passive\" (迷惑の受身).","formation":"Ichidan: ～られる / Godan: ～あれる (u→areru)","examples":[{"japanese":"先生に褒められた。","romaji":"Sensei ni homerareta.","german":"I was praised by the teacher.","cloze":{"start":3,"answer":"褒められた","quiz":{"level":"N4","japanese":"先生に褒められた。","german":"I was praised by the teacher.","start":3,"answer":"褒められた","acceptedAnswers":["褒められた"],"distractors":[{"text":"褒めた","reason":"This is active rather than passive."},{"text":"褒められなかった","reason":"This negates the praise."},{"text":"褒めれるた","reason":"This is not a past form."}],"promptKana":"せんせいに＿＿＿。"}}},{"japanese":"電車で足を踏まれた。","romaji":"Densha de ashi o fumareta.","german":"Someone stepped on my foot on the train."},{"japanese":"雨に降られた。","romaji":"Ame ni furareta.","german":"I got caught in the rain."}],"notes":"Godan: 書く→書かれる, 読む→読まれる. Ichidan: 食べる→食べられる. する→される, 来る→来られる.","related":["n4-saseru","n4-ni-yotte"]},
{"id":"n4-saseru","pattern":"～させる / ～せる","level":"N4","category":"Verben","meaning":"causative form (make/let)","explanation":"The causative form expresses that someone makes or lets another person do something.","formation":"Ichidan: ～させる / Godan: ～あせる (u→aseru)","examples":[{"japanese":"母は子供に野菜を食べさせた。","romaji":"Haha wa kodomo ni yasai o tabesaseta.","german":"The mother made her child eat vegetables.","cloze":{"start":8,"answer":"食べさせた","quiz":{"level":"N4","japanese":"母は子供に野菜を食べさせた。","german":"The mother made her child eat vegetables.","start":8,"answer":"食べさせた","acceptedAnswers":["食べさせた"],"distractors":[{"text":"食べられた","reason":"This is passive/potential, not the action being caused."},{"text":"食べさせなかった","reason":"This negates making the child eat."},{"text":"食べるさせた","reason":"する is not attached to the dictionary form."}],"promptKana":"はははこどもにやさいを＿＿＿。"}}},{"japanese":"先生は学生を立たせた。","romaji":"Sensei wa gakusei o tataseta.","german":"The teacher made the students stand up."}],"notes":"Godan: 書く→書かせる, 読む→読ませる. Ichidan: 食べる→食べさせる. する→させる, 来る→来させる.","related":["n4-rareru","n4-saserareru","n4-sasetekudasai"]},
{"id":"n4-saserareru","pattern":"～させられる","level":"N4","category":"Verben","meaning":"causative passive (to be made to)","explanation":"A combination of causative and passive. Expresses that you are forced to do something.","formation":"Ichidan: ～させられる / Godan: ～あせられる","examples":[{"japanese":"嫌いな野菜を食べさせられた。","romaji":"Kirai na yasai o tabesaserareta.","german":"I was made to eat vegetables I don't like.","cloze":{"start":6,"answer":"食べさせられた","quiz":{"level":"N4","japanese":"嫌いな野菜を食べさせられた。","german":"I was made to eat vegetables I don't like.","start":6,"answer":"食べさせられた","acceptedAnswers":["食べさせられた"],"distractors":[{"text":"食べさせた","reason":"This means making someone eat, not being forced to eat yourself."},{"text":"食べさせられなかった","reason":"This negates the compulsion."},{"text":"食べるさせられた","reason":"The causative passive is formed from the stem."}],"promptKana":"きらいなやさいを＿＿＿。"}}},{"japanese":"毎日残業させられている。","romaji":"Mainichi zangyō saserareteiru.","german":"I'm made to work overtime every day."}],"notes":"Godan short form: ～される (e.g. 行かされる instead of 行かせられる).","related":["n4-rareru","n4-saseru"]},
{"id":"n4-potential","pattern":"～える / ～られる","level":"N4","category":"Verben","meaning":"potential form (can)","explanation":"The potential form expresses ability or possibility. The object is often marked with が instead of を.","formation":"Ichidan: ～られる / Godan: u→eru","examples":[{"japanese":"日本語が話せます。","romaji":"Nihongo ga hanasemasu.","german":"I can speak Japanese.","cloze":{"start":4,"answer":"話せます","quiz":{"level":"N4","japanese":"日本語が話せます。","german":"I can speak Japanese.","start":4,"answer":"話せます","acceptedAnswers":["話せます"],"distractors":[{"text":"話せません","reason":"This negates the ability."},{"text":"話しました","reason":"This reports an action rather than the ability."},{"text":"話すます","reason":"ます is not attached to the dictionary form."}],"promptKana":"にほんごが＿＿＿。"}}},{"japanese":"この漢字が読めますか。","romaji":"Kono kanji ga yomemasu ka.","german":"Can you read this kanji?"},{"japanese":"明日来られますか。","romaji":"Ashita koraremasu ka.","german":"Can you come tomorrow?"}],"notes":"Godan: 書く→書ける, 読む→読める. Ichidan: 食べる→食べられる. する→できる, 来る→来られる. Colloquial: 食べれる (dropping the ra).","related":["koto-ga-dekiru"]},
{"id":"n4-volitional","pattern":"～よう / ～おう","level":"N4","category":"Verben","meaning":"volitional form (let's / I'll)","explanation":"The volitional form expresses intention, a suggestion or an invitation. It corresponds to \"Let's ...\" or \"I'll ...\".","formation":"Ichidan: ～よう / Godan: u→ō","examples":[{"japanese":"映画を見よう。","cloze":{"start":4,"answer":"よう","quiz":{"level":"N4","japanese":"映画を見よう。","german":"Let's watch a movie.","start":4,"answer":"よう","acceptedAnswers":["よう"],"distractors":[{"text":"ろう","reason":"見る forms 見よう, not 見ろう."},{"text":"るよう","reason":"見るよう is not a standalone suggestion to do something together."},{"text":"ない","reason":"This negates watching."}],"promptKana":"えいがをみ＿＿＿。"}},"romaji":"Eiga o miyō.","german":"Let's watch a movie."},{"japanese":"明日早く起きようと思う。","cloze":{"start":6,"answer":"よう"},"romaji":"Ashita hayaku okiyō to omou.","german":"I think I'll get up early tomorrow."}],"notes":"Godan: 書く→書こう, 読む→読もう. する→しよう, 来る→来よう. ～ようと思う = I intend to.","related":["n4-you-ni-suru","mashou","n4-you-to-omou"]},
{"id":"n4-teoku","pattern":"～ておく","level":"N4","category":"Verben","meaning":"to do in advance, to prepare","explanation":"ておく expresses that an action is done as preparation or in advance.","formation":"Verb (て-form) + おく","examples":[{"japanese":"パーティーの前に料理を作っておく。","cloze":{"start":13,"answer":"ておく","quiz":{"level":"N4","japanese":"パーティーの前に料理を作っておく。","german":"I'll cook the food ahead of the party.","start":13,"answer":"ておく","acceptedAnswers":["ておく"],"distractors":[{"text":"たおく","reason":"おく needs the て-connection."},{"text":"ておかない","reason":"This negates the preparation."},{"text":"ますおく","reason":"作っます is not a verb form."}],"promptKana":"パーティーのまえにりょうりをつくっ＿＿＿。"}},"romaji":"Pātī no mae ni ryōri o tsukutte oku.","german":"I'll cook the food ahead of the party."},{"japanese":"明日のために準備しておいてください。","romaji":"Ashita no tame ni junbi shite oite kudasai.","german":"Please get ready for tomorrow."}],"notes":"Colloquial: ～とく (買っとく = buy it and have it ready).","related":["te-form","n4-toku"]},
{"id":"n4-teiku","pattern":"～ていく","level":"N4","category":"Verben","meaning":"to go and ...; from now on","explanation":"ていく expresses movement away from the speaker or a change that continues into the future.","formation":"Verb (て-form) + いく","examples":[{"japanese":"これからも頑張っていきます。","romaji":"Kore kara mo ganbatte ikimasu.","german":"I'll keep doing my best from now on, too."},{"japanese":"お弁当を持っていく。","cloze":{"start":6,"answer":"ていく","quiz":{"level":"N4","japanese":"お弁当を持っていく。","german":"I'll take a bento box with me.","start":6,"answer":"ていく","acceptedAnswers":["ていく"],"distractors":[{"text":"た行く","reason":"持った行く is not a valid verb connection."},{"text":"ていかない","reason":"This negates taking it along."},{"text":"ます行く","reason":"持っます is not a verb form."}],"promptKana":"おべんとうをもっ＿＿＿。"}},"romaji":"Obentō o motte iku.","german":"I'll take a bento box with me."}],"notes":"Opposite of ～てくる. Toward the future: だんだん暑くなっていく (it's going to get hotter and hotter).","related":["n4-tekuru","te-form"]},
{"id":"n4-tekuru","pattern":"～てくる","level":"N4","category":"Verben","meaning":"to come and ...; up to now","explanation":"てくる expresses movement toward the speaker or a change from the past up to now.","formation":"Verb (て-form) + くる","examples":[{"japanese":"雨が降ってきた。","romaji":"Ame ga futte kita.","german":"It has started to rain.","cloze":{"start":2,"answer":"降ってきた","quiz":{"level":"N4","japanese":"雨が降ってきた。","german":"It has started to rain.","start":2,"answer":"降ってきた","acceptedAnswers":["降ってきた"],"distractors":[{"text":"降ってこなかった","reason":"This negates the rain starting."},{"text":"降ったきた","reason":"くる follows the て-form here."},{"text":"降ってくるた","reason":"The past of くる is きた."}],"promptKana":"あめが＿＿＿。"}}},{"japanese":"日本語を三年間勉強してきました。","romaji":"Nihongo o sannenkan benkyō shite kimashita.","german":"I have been studying Japanese for three years."}],"notes":"Opposite of ～ていく. Up to now: だんだん寒くなってきた (it has been getting colder).","related":["n4-teiku","te-form"]},
{"id":"n4-teageru","pattern":"～てあげる","level":"N4","category":"Verben","meaning":"to do something for someone (giving)","explanation":"てあげる expresses that you do someone the favor of doing something for them.","formation":"Verb (て-form) + あげる","examples":[{"japanese":"友達に日本語を教えてあげた。","romaji":"Tomodachi ni nihongo o oshiete ageta.","german":"I taught my friend Japanese.","cloze":{"start":9,"answer":"てあげた","quiz":{"level":"N4","japanese":"友達に日本語を教えてあげた。","german":"I taught my friend Japanese.","start":9,"answer":"てあげた","acceptedAnswers":["てあげた"],"distractors":[{"text":"たあげた","reason":"あげる follows the て-form here."},{"text":"てあげなかった","reason":"This negates the help given."},{"text":"てあげるた","reason":"あげる forms the past tense あげた."}],"promptKana":"ともだちににほんごをおしえ＿＿＿。"}}},{"japanese":"荷物を持ってあげましょうか。","romaji":"Nimotsu o motte agemashō ka.","german":"Shall I carry your luggage for you?"}],"notes":"Can sound condescending. More polite: ～て差し上げる. Don't use it toward people of higher status about things you do for them.","related":["n4-temorau","n4-tekureru"]},
{"id":"n4-temorau","pattern":"～てもらう","level":"N4","category":"Verben","meaning":"to have something done by someone","explanation":"てもらう expresses that you receive the favor of someone doing something for you.","formation":"Person に + Verb (て-form) + もらう","examples":[{"japanese":"友達に手伝ってもらった。","romaji":"Tomodachi ni tetsudatte moratta.","german":"My friend helped me (I received help).","cloze":{"start":3,"answer":"手伝ってもらった","quiz":{"level":"N4","japanese":"友達に手伝ってもらった。","german":"My friend helped me (I received help).","start":3,"answer":"手伝ってもらった","acceptedAnswers":["手伝ってもらった"],"distractors":[{"text":"手伝ってあげた","reason":"This reverses the direction of the help."},{"text":"手伝ってもらわなかった","reason":"This negates the help received."},{"text":"手伝ったもらった","reason":"もらう follows the て-form."}],"promptKana":"ともだちに＿＿＿。"}}},{"japanese":"先生に説明してもらいました。","romaji":"Sensei ni setsumei shite moraimashita.","german":"The teacher explained it to me."}],"notes":"Polite: ～ていただく. Request: ～てもらえませんか (Could you please ...?).","related":["n4-teageru","n4-tekureru"]},
{"id":"n4-tekureru","pattern":"～てくれる","level":"N4","category":"Verben","meaning":"to do something for me (receiving)","explanation":"てくれる expresses that someone does something for the speaker or the speaker's group. It implies gratitude.","formation":"Person が + Verb (て-form) + くれる","examples":[{"japanese":"母が弁当を作ってくれた。","romaji":"Haha ga bentō o tsukutte kureta.","german":"My mother made me a bento.","cloze":{"start":5,"answer":"作ってくれた","quiz":{"level":"N4","japanese":"母が弁当を作ってくれた。","german":"My mother made me a bento.","start":5,"answer":"作ってくれた","acceptedAnswers":["作ってくれた"],"distractors":[{"text":"作ってもらった","reason":"This makes the mother the recipient rather than the one acting."},{"text":"作ってくれなかった","reason":"This negates the action."},{"text":"作ったくれた","reason":"くれる follows the て-form."}],"promptKana":"ははがべんとうを＿＿＿。"}}},{"japanese":"友達が駅まで送ってくれた。","romaji":"Tomodachi ga eki made okutte kureta.","german":"My friend took me to the station."}],"notes":"Polite: ～てくださる. Request: ～てくれませんか (Could you please ...?).","related":["n4-teageru","n4-temorau"]},
{"id":"n4-koto-ni-suru","pattern":"～ことにする","level":"N4","category":"Verben","meaning":"to decide to","explanation":"ことにする expresses an active, personal decision.","formation":"Verb (辞書形/ない形) + ことにする","examples":[{"japanese":"来年日本に行くことにした。","romaji":"Rainen Nihon ni iku koto ni shita.","german":"I decided to go to Japan next year.","cloze":{"start":7,"answer":"ことにした","quiz":{"level":"N4","japanese":"来年日本に行くことにした。","german":"I decided to go to Japan next year.","start":7,"answer":"ことにした","acceptedAnswers":["ことにした"],"distractors":[{"text":"ことをした","reason":"The decision construction requires に."},{"text":"ことにしなかった","reason":"This negates the decision."},{"text":"ことにするた","reason":"する forms the past tense した."}],"promptKana":"らいねんにほんにいく＿＿＿。"}}},{"japanese":"甘いものを食べないことにした。","romaji":"Amai mono o tabenai koto ni shita.","german":"I decided not to eat sweets."}],"notes":"～ことにしている = a regular habit based on your own decision.","related":["n4-koto-ni-naru"]},
{"id":"n4-koto-ni-naru","pattern":"～ことになる","level":"N4","category":"Verben","meaning":"it has been decided that; it turns out that","explanation":"ことになる expresses that a decision was made by others or that things turned out that way.","formation":"Verb (辞書形/ない形) + ことになる","examples":[{"japanese":"来月から大阪に転勤することになりました。","romaji":"Raigetsu kara Ōsaka ni tenkin suru koto ni narimashita.","german":"It has been decided that I'll be transferred to Osaka starting next month.","cloze":{"start":11,"answer":"ことになりました","quiz":{"level":"N4","japanese":"来月から大阪に転勤することになりました。","german":"It has been decided that I'll be transferred to Osaka starting next month.","start":11,"answer":"ことになりました","acceptedAnswers":["ことになりました"],"distractors":[{"text":"ことをなりました","reason":"なる requires に here, not を."},{"text":"ことになりませんでした","reason":"This negates the decision that was made."},{"text":"ことになるました","reason":"ます is not attached to なる."}],"promptKana":"らいげつからおおさかにてんきんする＿＿＿。"}}},{"japanese":"会議は中止になることになった。","romaji":"Kaigi wa chūshi ni naru koto ni natta.","german":"It was decided that the meeting would be canceled."}],"notes":"～ことになっている = an existing rule/arrangement.","related":["n4-koto-ni-suru"]},
{"id":"n4-you-ni-suru","pattern":"～ようにする","level":"N4","category":"Verben","meaning":"to try to, to make sure to","explanation":"ようにする expresses that you make a conscious effort to do or avoid something.","formation":"Verb (辞書形/ない形) + ようにする","examples":[{"japanese":"毎日運動するようにしています。","romaji":"Mainichi undō suru yō ni shiteimasu.","german":"I make a point of exercising every day.","cloze":{"start":6,"answer":"ようにしています","quiz":{"level":"N4","japanese":"毎日運動するようにしています。","german":"I make a point of exercising every day.","start":6,"answer":"ようにしています","acceptedAnswers":["ようにしています"],"distractors":[{"text":"ようをしています","reason":"The habit you aim for is connected with に."},{"text":"ようにしていません","reason":"This negates the effort."},{"text":"ようにしますて","reason":"しますて is not a て-form."}],"promptKana":"まいにちうんどうする＿＿＿。"}}},{"japanese":"遅刻しないようにしてください。","romaji":"Chikoku shinai yō ni shite kudasai.","german":"Please make sure not to be late."}],"notes":"～ようにしている = a regular habit you make a point of keeping.","related":["n4-you-ni-naru"]},
{"id":"n4-you-ni-naru","pattern":"～ようになる","level":"N4","category":"Verben","meaning":"to come to (be able to), to reach the point where","explanation":"ようになる expresses a gradual change or development: something that was not possible before becomes possible.","formation":"Verb (辞書形/ない形) + ようになる","examples":[{"japanese":"日本語が話せるようになりました。","romaji":"Nihongo ga hanaseru yō ni narimashita.","german":"I've become able to speak Japanese.","cloze":{"start":7,"answer":"ようになりました","quiz":{"level":"N4","japanese":"日本語が話せるようになりました。","german":"I've become able to speak Japanese.","start":7,"answer":"ようになりました","acceptedAnswers":["ようになりました"],"distractors":[{"text":"ようをなりました","reason":"The change requires に."},{"text":"ようになりませんでした","reason":"This negates the ability that was gained."},{"text":"ようになるました","reason":"なるました is not a verb form."}],"promptKana":"にほんごがはなせる＿＿＿。"}}},{"japanese":"野菜を食べるようになった。","romaji":"Yasai o taberu yō ni natta.","german":"I've started eating vegetables."}],"notes":"Negative: ～なくなる (to stop doing): 食べなくなった = stopped eating.","related":["n4-you-ni-suru"]},
{"id":"n4-tehoshii","pattern":"～てほしい","level":"N4","category":"Verben","meaning":"to want someone to do something","explanation":"てほしい expresses the wish that another person does something.","formation":"Person に + Verb (て-form) + ほしい","examples":[{"japanese":"早く来てほしい。","cloze":{"start":3,"answer":"てほしい","quiz":{"level":"N4","japanese":"早く来てほしい。","german":"I want you to come soon.","start":3,"answer":"てほしい","acceptedAnswers":["てほしい"],"distractors":[{"text":"たほしい","reason":"Wanting someone else to act requires the て-form."},{"text":"てほしくない","reason":"This negates the wish."},{"text":"ますほしい","reason":"ます cannot come before ほしい."}],"promptKana":"はやくき＿＿＿。"}},"romaji":"Hayaku kite hoshii.","german":"I want you to come soon."},{"japanese":"もっと勉強してほしいです。","cloze":{"start":6,"answer":"てほしい"},"romaji":"Motto benkyō shite hoshii desu.","german":"I want you to study more."}],"notes":"Negative: ～ないでほしい (I want you not to do it).","related":["ga-hoshii","n4-temorau","n2-tai-mono-da"]},
{"id":"n4-sasetekudasai","pattern":"～させてください","level":"N4","category":"Verben","meaning":"please let me","explanation":"させてください is a polite request for permission to do something. A combination of the causative and ください.","formation":"Verb (させ-form) + てください","examples":[{"japanese":"私にやらせてください。","romaji":"Watashi ni yarasete kudasai.","german":"Please let me do it."},{"japanese":"少し考えさせてください。","cloze":{"start":4,"answer":"させてください","quiz":{"level":"N4","japanese":"少し考えさせてください。","german":"Please let me think about it for a moment.","start":4,"answer":"させてください","acceptedAnswers":["させてください"],"distractors":[{"text":"させたください","reason":"The request requires the て-form."},{"text":"させますください","reason":"ます cannot come before ください here."},{"text":"させないでください","reason":"This asks not to be allowed to think."}],"promptKana":"すこしかんがえ＿＿＿。"}},"romaji":"Sukoshi kangaesasete kudasai.","german":"Please let me think about it for a moment."}],"notes":"Very polite. Often used in business contexts.","related":["n4-saseru","te-kudasai"]},
{"id":"n4-tabakari","pattern":"～たばかり","level":"N4","category":"Verben","meaning":"just (done)","explanation":"たばかり expresses that an action has only just been completed.","formation":"Verb (た-form) + ばかり","examples":[{"japanese":"日本に来たばかりです。","cloze":{"start":4,"answer":"たばかり","quiz":{"level":"N4","japanese":"日本に来たばかりです。","german":"I've only just come to Japan.","start":4,"answer":"たばかり","acceptedAnswers":["たばかり"],"distractors":[{"text":"てばかり","reason":"This means constantly coming rather than having just arrived."},{"text":"るばかり","reason":"来る is read くる, not きる; besides, it does not express a completed arrival."},{"text":"たばかりな","reason":"No な is inserted after ばかり before です."}],"promptKana":"にほんにき＿＿＿です。"}},"romaji":"Nihon ni kita bakari desu.","german":"I've only just come to Japan."},{"japanese":"さっき食べたばかりなのに、もうお腹が空いた。","cloze":{"start":5,"answer":"たばかり"},"romaji":"Sakki tabeta bakari na noni, mō onaka ga suita.","german":"I only just ate, but I'm already hungry."}],"notes":"Don't confuse with ～ばかり (only / nothing but).","related":["n4-bakari-p","n4-tokoro-da","n3-tate"]},
{"id":"n4-hajimeru","pattern":"～始める","level":"N4","category":"Verben","meaning":"to begin to","explanation":"As a suffix, 始める expresses the beginning of an action.","formation":"Verb (ます-stem) + 始める","examples":[{"japanese":"雨が降り始めた。","romaji":"Ame ga furi hajimeta.","german":"It started to rain.","cloze":{"start":4,"answer":"始めた","quiz":{"level":"N4","japanese":"雨が降り始めた。","german":"It started to rain.","start":4,"answer":"始めた","acceptedAnswers":["始めた"],"distractors":[{"text":"終わった","reason":"This marks the end rather than the beginning."},{"text":"始めなかった","reason":"This negates the beginning."},{"text":"始めるた","reason":"The past is 始めた."}],"promptKana":"あめがふり＿＿＿。"}}},{"japanese":"日本語を勉強し始めました。","romaji":"Nihongo o benkyō shi hajimemashita.","german":"I started studying Japanese."}],"notes":"Also a standalone verb: 始める = to begin.","related":["n4-tsuzukeru","n4-owaru"]},
{"id":"n4-tsuzukeru","pattern":"～続ける","level":"N4","category":"Verben","meaning":"to continue to, to keep doing","explanation":"As a suffix, 続ける expresses that an action continues.","formation":"Verb (ます-stem) + 続ける","examples":[{"japanese":"三時間歩き続けた。","romaji":"Sanjikan aruki tsuzuketa.","german":"I kept walking for three hours.","cloze":{"start":5,"answer":"続けた","quiz":{"level":"N4","japanese":"三時間歩き続けた。","german":"I kept walking for three hours.","start":5,"answer":"続けた","acceptedAnswers":["続けた"],"distractors":[{"text":"続けなかった","reason":"This negates continuing to walk."},{"text":"続けるた","reason":"This is not a past form."},{"text":"ます続けた","reason":"ます is not inserted before 続けた."}],"promptKana":"さんじかんあるき＿＿＿。"}}},{"japanese":"諦めずに努力し続けてください。","romaji":"Akiramezu ni doryoku shi tsuzukete kudasai.","german":"Don't give up, and keep making an effort."}],"notes":"Also standalone: 続ける = to continue.","related":["n4-hajimeru","n4-owaru"]},
{"id":"n4-owaru","pattern":"～終わる","level":"N4","category":"Verben","meaning":"to finish (doing)","explanation":"As a suffix, 終わる expresses that an action has been brought to an end.","formation":"Verb (ます-stem) + 終わる","examples":[{"japanese":"本を読み終わりました。","romaji":"Hon o yomi owarimashita.","german":"I finished reading the book.","cloze":{"start":4,"answer":"終わりました","quiz":{"level":"N4","japanese":"本を読み終わりました。","german":"I finished reading the book.","start":4,"answer":"終わりました","acceptedAnswers":["終わりました"],"distractors":[{"text":"始めました","reason":"This marks the beginning rather than the completion."},{"text":"終わりませんでした","reason":"This negates the completion."},{"text":"終わるました","reason":"This is not a polite past form."}],"promptKana":"ほんをよみ＿＿＿。"}}},{"japanese":"宿題を書き終わった。","romaji":"Shukudai o kaki owatta.","german":"I finished writing my homework."}],"notes":"Also standalone: 終わる = to end.","related":["n4-hajimeru","n4-tsuzukeru"]},
{"id":"n4-yasui","pattern":"～やすい","level":"N4","category":"Verben","meaning":"easy to","explanation":"As a suffix, やすい expresses that something is easy to do or that there is a tendency.","formation":"Verb (ます-stem) + やすい","examples":[{"japanese":"この本は読みやすい。","cloze":{"start":6,"answer":"やすい","quiz":{"level":"N4","japanese":"この本は読みやすい。","german":"This book is easy to read.","start":6,"answer":"やすい","acceptedAnswers":["やすい"],"distractors":[{"text":"にくい","reason":"This means hard to read."},{"text":"やすいだ","reason":"An い-adjective does not end with だ."},{"text":"やすくでした","reason":"This is not an adjective form."}],"promptKana":"このほんはよみ＿＿＿。"}},"romaji":"Kono hon wa yomiyasui.","german":"This book is easy to read."},{"japanese":"ガラスは割れやすい。","cloze":{"start":6,"answer":"やすい"},"romaji":"Garasu wa wareyasui.","german":"Glass breaks easily."}],"notes":"Conjugates like an い-adjective: やすくない, やすかった.","related":["n4-nikui","sugiru"]},
{"id":"n4-nikui","pattern":"～にくい","level":"N4","category":"Verben","meaning":"hard to, difficult to","explanation":"As a suffix, にくい expresses that something is hard to do.","formation":"Verb (ます-stem) + にくい","examples":[{"japanese":"この字は読みにくい。","cloze":{"start":6,"answer":"にくい","quiz":{"level":"N4","japanese":"この字は読みにくい。","german":"This handwriting is hard to read.","start":6,"answer":"にくい","acceptedAnswers":["にくい","づらい"],"distractors":[{"text":"やすい","reason":"This means easy to read."},{"text":"にくいだ","reason":"An い-adjective does not end with だ."},{"text":"にくかっただ","reason":"だ does not go after the past of an い-adjective."}],"promptKana":"このじはよみ＿＿＿。"}},"romaji":"Kono ji wa yominikui.","german":"This handwriting is hard to read."},{"japanese":"この靴は歩きにくい。","cloze":{"start":6,"answer":"にくい"},"romaji":"Kono kutsu wa aruki nikui.","german":"These shoes are hard to walk in."}],"notes":"Conjugates like an い-adjective. Similar: ～づらい (with emotional difficulty).","related":["n4-yasui","sugiru"]},
{"id":"n4-sou-appearance","pattern":"～そうだ (様態)","level":"N4","category":"Verben","meaning":"looks like, seems","explanation":"そうだ (様態/yōtai) expresses an impression based on appearance. It is based on your own observation.","formation":"Verb (ます-stem) + そうだ / い-Adj (without い) + そうだ / な-Adj + そうだ","examples":[{"japanese":"雨が降りそうだ。","romaji":"Ame ga furisō da.","german":"It looks like it's going to rain.","cloze":{"start":4,"answer":"そうだ","quiz":{"level":"N4","japanese":"雨が降りそうだ。","german":"It looks like it's going to rain.","start":4,"answer":"そうだ","acceptedAnswers":["そうだ"],"distractors":[{"text":"そうな","reason":"The attributive form needs a noun after it."},{"text":"そうに","reason":"The adverbial form needs a following predicate."},{"text":"そうのだ","reason":"そう expressing appearance does not connect with のだ."}],"promptKana":"あめがふり＿＿＿。"}}},{"japanese":"このケーキはおいしそうだ。","romaji":"Kono kēki wa oishisō da.","german":"This cake looks delicious."}],"notes":"Exceptions: いい→よさそう, ない→なさそう. Don't confuse with ～そうだ (hearsay).","related":["n4-sou-hearsay","n4-you-da","n4-rashii"]},
{"id":"n4-tearu","pattern":"～てある","level":"N4","category":"Verben","meaning":"has been done (resulting state)","explanation":"てある expresses that a deliberate action has been carried out and its result still remains.","formation":"Verb (て-form) + ある","examples":[{"japanese":"窓が開けてある。","cloze":{"start":4,"answer":"てある","quiz":{"level":"N4","japanese":"窓が開けてある。","german":"The window has been opened (and is still open).","start":4,"answer":"てある","acceptedAnswers":["てある"],"distractors":[{"text":"たある","reason":"ある follows the て-form here."},{"text":"てあらない","reason":"ある is negated with ない, not あらない."},{"text":"ますある","reason":"ます cannot come before ある."}],"promptKana":"まどがあけ＿＿＿。"}},"romaji":"Mado ga akete aru.","german":"The window has been opened (and is still open)."},{"japanese":"テーブルの上にメモが書いてある。","cloze":{"start":12,"answer":"てある"},"romaji":"Tēburu no ue ni memo ga kaite aru.","german":"A note has been written on the table."}],"notes":"Difference from ～ている: てある emphasizes deliberate preparation, ている the current state.","related":["te-iru","n4-teoku"]},
{"id":"n4-zu-ni","pattern":"～ずに / ～ないで","level":"N4","category":"Verben","meaning":"without doing","explanation":"ずに is the formal variant of ないで. Both express that one action is not done while another takes place.","formation":"Verb (ない-stem) + ずに / Verb (ない-form) + で","examples":[{"japanese":"朝ご飯を食べずに学校に行った。","cloze":{"start":6,"answer":"ずに","quiz":{"level":"N4","japanese":"朝ご飯を食べずに学校に行った。","german":"I went to school without eating breakfast.","start":6,"answer":"ずに","acceptedAnswers":["ずに","ないで"],"distractors":[{"text":"てから","reason":"This means after breakfast."},{"text":"た後で","reason":"This means after breakfast."},{"text":"ながら","reason":"This means while eating."}],"promptKana":"あさごはんをたべ＿＿＿がっこうにいった。"}},"romaji":"Asagohan o tabezu ni gakkō ni itta.","german":"I went to school without eating breakfast."},{"japanese":"辞書を使わないで読めた。","cloze":{"start":5,"answer":"ないで"},"romaji":"Jisho o tsukawanaide yometa.","german":"I was able to read it without a dictionary."}],"notes":"する→せずに (exception). ずに is more typical of written language than ないで.","related":["naide"]},
{"id":"n4-imperative","pattern":"命令形","level":"N4","category":"Verben","meaning":"imperative form (command)","explanation":"The imperative form is a direct command. It is rarely used in everyday speech and sounds rough.","formation":"Godan: u→e (書く→書け) / Ichidan: る→ろ (食べる→食べろ)","examples":[{"japanese":"早くしろ！","romaji":"Hayaku shiro!","german":"Hurry up!","cloze":{"start":2,"answer":"しろ","quiz":{"level":"N4","japanese":"早くしろ！","german":"Hurry up!","start":2,"answer":"しろ","acceptedAnswers":["しろ","せよ"],"distractors":[{"text":"した","reason":"This reports the past rather than giving an order."},{"text":"しない","reason":"This negates the action."},{"text":"するろ","reason":"This is not an imperative form."}],"promptKana":"はやく＿＿＿！"}}},{"japanese":"静かにしろ。","romaji":"Shizuka ni shiro.","german":"Be quiet."},{"japanese":"頑張れ！","romaji":"Ganbare!","german":"Go for it!"}],"notes":"する→しろ, 来る→来い (こい). Often used for cheering someone on: 頑張れ! Negative form: ～な (するな = don't do it).","related":["n4-nasai"]},
{"id":"n4-nasai","pattern":"～なさい","level":"N4","category":"Verben","meaning":"do ... (polite command)","explanation":"なさい is a more polite command form, often used by parents, teachers or superiors.","formation":"Verb (ます-stem) + なさい","examples":[{"japanese":"早く寝なさい。","cloze":{"start":3,"answer":"なさい","quiz":{"level":"N4","japanese":"早く寝なさい。","german":"Go to bed early.","start":3,"answer":"なさい","acceptedAnswers":["なさい"],"distractors":[{"text":"るなさい","reason":"なさい follows the stem, not the dictionary form."},{"text":"たなさい","reason":"なさい does not follow the た-form."},{"text":"なかった","reason":"This reports not sleeping rather than giving an instruction."}],"promptKana":"はやくね＿＿＿。"}},"romaji":"Hayaku nenasai.","german":"Go to bed early."},{"japanese":"宿題をしなさい。","cloze":{"start":4,"answer":"なさい"},"romaji":"Shukudai o shinasai.","german":"Do your homework."}],"notes":"More polite than 命令形, but still authoritative. Only used toward people of lower status.","related":["n4-imperative","te-kudasai"]},
{"id":"n4-adj-ba","pattern":"～ければ / ～なら","level":"N4","category":"Adjektive","meaning":"if (adjective conditional)","explanation":"い-adjectives: い→ければ. な-adjectives: なら(ば).","formation":"い-Adj: い→ければ / な-Adj: ～なら(ば)","examples":[{"japanese":"安ければ買います。","cloze":{"start":1,"answer":"ければ","quiz":{"level":"N4","japanese":"安ければ買います。","german":"If it's cheap, I'll buy it.","start":1,"answer":"ければ","acceptedAnswers":["ければ"],"distractors":[{"text":"いければ","reason":"The い is dropped before ければ."},{"text":"かったれば","reason":"This is not a conditional form."},{"text":"くないなら","reason":"This reverses the condition: if it is not cheap."}],"promptKana":"やす＿＿＿かいます。"}},"romaji":"Yasukereba kaimasu.","german":"If it's cheap, I'll buy it."},{"japanese":"暇なら遊びに来てください。","cloze":{"start":1,"answer":"なら"},"romaji":"Hima nara asobi ni kite kudasai.","german":"If you're free, come over."}],"notes":"いい→よければ. Negative: ～くなければ / ～でなければ.","related":["n4-ba","n4-nara","n3-ba-hodo"]},
{"id":"n4-adj-souna","pattern":"～そうな / ～そうに","level":"N4","category":"Adjektive","meaning":"looks ... (impression)","explanation":"そうな before nouns, そうに before verbs. A visual impression.","formation":"い-Adj (without い) + そうな/に / な-Adj + そうな/に","examples":[{"japanese":"おいしそうなケーキですね。","cloze":{"start":3,"answer":"そうな","quiz":{"level":"N4","japanese":"おいしそうなケーキですね。","german":"That's a delicious-looking cake.","start":3,"answer":"そうな","acceptedAnswers":["そうな"],"distractors":[{"text":"そうに","reason":"Before a noun you need そうな."},{"text":"そうだ","reason":"The copula does not come before ケーキ as a modifier here."},{"text":"そうの","reason":"The attributive form is そうな."}],"promptKana":"おいし＿＿＿ケーキですね。"}},"romaji":"Oishisō na kēki desu ne.","german":"That's a delicious-looking cake."},{"japanese":"楽しそうに笑っている。","cloze":{"start":2,"answer":"そうに"},"romaji":"Tanoshisō ni waratteiru.","german":"He's laughing cheerfully."}],"notes":"いい→よさそう, ない→なさそう.","related":["n4-sou-appearance"]},
{"id":"n4-adj-sugiru","pattern":"～すぎる (Adj.)","level":"N4","category":"Adjektive","meaning":"too ... (excess)","explanation":"すぎる with adjectives: an excessively strong quality.","formation":"い-Adj (without い) + すぎる / な-Adj + すぎる","examples":[{"japanese":"この部屋は暑すぎる。","romaji":"Kono heya wa atsusugiru.","german":"This room is too hot.","cloze":{"start":6,"answer":"すぎる","quiz":{"level":"N4","japanese":"この部屋は暑すぎる。","german":"This room is too hot.","start":6,"answer":"すぎる","acceptedAnswers":["すぎる"],"distractors":[{"text":"いすぎる","reason":"The final い is dropped before すぎる."},{"text":"すぎるだ","reason":"だ does not follow the verb すぎる."},{"text":"くすぎる","reason":"The form attaches directly to 暑 here."}],"promptKana":"このへやはあつ＿＿＿。"}}},{"japanese":"静かすぎて怖い。","romaji":"Shizuka sugite kowai.","german":"It's so quiet it's scary."}],"notes":"Conjugates like an ichidan verb.","related":["sugiru"]},
{"id":"n4-ku-suru","pattern":"～くする / ～にする","level":"N4","category":"Adjektive","meaning":"to make something ...","explanation":"くする (い-adj) and にする (な-adj): actively bringing about a change.","formation":"い-Adj: い→くする / な-Adj: ～にする","examples":[{"japanese":"部屋を明るくした。","romaji":"Heya o akaruku shita.","german":"I made the room brighter.","cloze":{"start":3,"answer":"明るくした","quiz":{"level":"N4","japanese":"部屋を明るくした。","german":"I made the room brighter.","start":3,"answer":"明るくした","acceptedAnswers":["明るくした"],"distractors":[{"text":"明るいした","reason":"Before する, an い-adjective needs the く-form."},{"text":"明るくしなかった","reason":"This negates making it brighter."},{"text":"明るくするた","reason":"This is not a past form of する."}],"promptKana":"へやを＿＿＿。"}}},{"japanese":"部屋をきれいにしてください。","romaji":"Heya o kirei ni shite kudasai.","german":"Please tidy up the room."}],"notes":"Compare ～くなる/～になる (to become, by itself).","related":["ku-naru-ni-naru","n5-adverb-ku-ni"]},
{"id":"n4-sa","pattern":"～さ","level":"N4","category":"Adjektive","meaning":"-ness (nominalization)","explanation":"さ turns adjectives into nouns.","formation":"い-Adj (without い) + さ / な-Adj + さ","examples":[{"japanese":"この山の高さは何メートルですか。","cloze":{"start":5,"answer":"さ","quiz":{"level":"N4","japanese":"この山の高さは何メートルですか。","german":"How many meters high is this mountain?","start":5,"answer":"さ","acceptedAnswers":["さ"],"distractors":[{"text":"い","reason":"高い does not turn the measurable height into a noun here."},{"text":"く","reason":"The く-form is not a noun for height here."},{"text":"かった","reason":"This would be the past rather than a measurable height."}],"promptKana":"このやまのたか＿＿＿はなんメートルですか。"}},"romaji":"Kono yama no takasa wa nan mētoru desu ka.","german":"How many meters high is this mountain?"},{"japanese":"日本語の難しさを実感した。","cloze":{"start":6,"answer":"さ"},"romaji":"Nihongo no muzukashisa o jikkan shita.","german":"I really felt how difficult Japanese is."}],"notes":"高さ, 長さ, 深さ, 大きさ, 便利さ, etc.","related":[]},
{"id":"n4-garu","pattern":"～がる","level":"N4","category":"Adjektive","meaning":"to show signs of","explanation":"がる: outward signs of a feeling in a third person.","formation":"い-Adj (without い) + がる","examples":[{"japanese":"子供が怖がっている。","romaji":"Kodomo ga kowagatte iru.","german":"The child is showing fear.","cloze":{"start":3,"answer":"怖がっている","quiz":{"level":"N4","japanese":"子供が怖がっている。","german":"The child is showing fear.","start":3,"answer":"怖がっている","acceptedAnswers":["怖がっている"],"distractors":[{"text":"怖いがっている","reason":"The final い is dropped before がる."},{"text":"怖がっていない","reason":"This negates the fear being shown."},{"text":"怖がるている","reason":"The て-form is 怖がって."}],"promptKana":"こどもが＿＿＿。"}}},{"japanese":"彼女は新しい服を欲しがっている。","romaji":"Kanojo wa atarashii fuku o hoshigatte iru.","german":"She wants new clothes."}],"notes":"欲しい→欲しがる, 怖い→怖がる. Godan verb.","related":["ga-hoshii","n2-buru"]},
{"id":"n4-you-na","pattern":"～ような / ～みたいな","level":"N4","category":"Adjektive","meaning":"like ... (attributive)","explanation":"ような (formal) and みたいな (casual) before nouns.","formation":"Noun + のような/みたいな + Noun","examples":[{"japanese":"夢のような一日だった。","cloze":{"start":2,"answer":"ような","quiz":{"level":"N4","japanese":"夢のような一日だった。","german":"It was a dreamlike day.","start":2,"answer":"ような","acceptedAnswers":["ような"],"distractors":[{"text":"ように","reason":"Before a noun, ような is used."},{"text":"ようだ","reason":"だ is not an attributive connection here."},{"text":"ようの","reason":"夢のような requires な before 一日."}],"promptKana":"ゆめの＿＿＿いちにちだった。"}},"romaji":"Yume no yō na ichinichi datta.","german":"It was a dreamlike day."},{"japanese":"彼みたいな人になりたい。","cloze":{"start":1,"answer":"みたいな"},"romaji":"Kare mitai na hito ni naritai.","german":"I want to become someone like him."}],"notes":"のような = formal, みたいな = casual.","related":["n4-no-you-ni","n4-you-da"]},
{"id":"n4-yori","pattern":"～より～のほうが","level":"N4","category":"Adjektive","meaning":"more ... than (comparative)","explanation":"より = the thing being compared against, のほうが = the element that has more of the quality.","formation":"A より B のほうが + Adj","examples":[{"japanese":"電車よりバスのほうが安い。","romaji":"Densha yori basu no hō ga yasui.","german":"The bus is cheaper than the train.","cloze":{"start":2,"answer":"より","quiz":{"level":"N4","japanese":"電車よりバスのほうが安い。","german":"The bus is cheaper than the train.","start":2,"answer":"より","acceptedAnswers":["より"],"distractors":[{"text":"まで","reason":"まで sets a limit rather than a standard of comparison."},{"text":"へ","reason":"へ marks a direction."},{"text":"を","reason":"を does not mark a standard of comparison here."}],"promptKana":"でんしゃ＿＿＿バスのほうがやすい。"}}},{"japanese":"夏より冬のほうが好きです。","romaji":"Natsu yori fuyu no hō ga suki desu.","german":"I like winter better than summer."}],"notes":"思ったより難しい (harder than I thought).","related":["ichiban"]},
{"id":"n4-rashii-adj","pattern":"～らしい (typisch)","level":"N4","category":"Adjektive","meaning":"typical of, -like","explanation":"らしい as a suffix: typical, characteristic.","formation":"Noun + らしい","examples":[{"japanese":"今日は春らしい天気ですね。","romaji":"Kyō wa haru rashii tenki desu ne.","german":"Typical spring weather today, isn't it?","cloze":{"start":4,"answer":"らしい","quiz":{"level":"N4","japanese":"今日は春らしい天気ですね。","german":"Typical spring weather today, isn't it?","start":4,"answer":"らしい","acceptedAnswers":["らしい"],"distractors":[{"text":"らしいな","reason":"らしい modifies nouns without an extra な."},{"text":"らしく","reason":"The adverbial form does not modify the noun here."},{"text":"らしいの","reason":"The attributive form does not need の."}],"promptKana":"きょうははる＿＿＿てんきですね。"}}},{"japanese":"彼女はとても女性らしい。","romaji":"Kanojo wa totemo josei rashii.","german":"She is very feminine."}],"notes":"Don't confuse with ～らしい (supposition).","related":["n4-rashii"]},
{"id":"n4-gachi","pattern":"～がち","level":"N3","category":"Adjektive","meaning":"tendency to","explanation":"がち: a (usually negative) tendency.","formation":"Verb (ます-stem) + がち / Noun + がち","examples":[{"japanese":"最近風邪を引きがちだ。","cloze":{"start":7,"answer":"がち","quiz":{"level":"N3","japanese":"最近風邪を引きがちだ。","german":"Lately I tend to catch colds.","start":7,"answer":"がち","acceptedAnswers":["がち"],"distractors":[{"text":"たい","reason":"A たい expression does not take だ."},{"text":"やすい","reason":"An い-adjective does not take だ."},{"text":"がちに","reason":"The adverbial form cannot come before だ."}],"promptKana":"さいきんかぜをひき＿＿＿だ。"}},"romaji":"Saikin kaze o hikigachi da.","german":"Lately I tend to catch colds."},{"japanese":"曇りがちの天気が続く。","cloze":{"start":2,"answer":"がち"},"romaji":"Kumorigachi no tenki ga tsuzuku.","german":"Mostly cloudy weather continues."}],"notes":"Behaves like a な-adj: ～がちな + noun.","related":["n4-yasui","n1-kirai-ga-aru"]},
{"id":"n4-you-da","pattern":"～ようだ","level":"N4","category":"Satzstrukturen","meaning":"it seems that","explanation":"ようだ: a supposition based on your own observation.","formation":"Verb/い-Adj + ようだ / な-Adj + なようだ / Noun + のようだ","examples":[{"japanese":"彼は忙しいようだ。","cloze":{"start":5,"answer":"ようだ","quiz":{"level":"N4","japanese":"彼は忙しいようだ。","german":"He seems to be busy.","start":5,"answer":"ようだ","acceptedAnswers":["ようだ","みたいだ","らしい"],"distractors":[{"text":"なようだ","reason":"No な is inserted after an い-adjective."},{"text":"ような","reason":"The attributive form requires a following noun."},{"text":"ように","reason":"The adverbial form requires a following statement."}],"promptKana":"かれはいそがしい＿＿＿。"}},"romaji":"Kare wa isogashii yō da.","german":"He seems to be busy."},{"japanese":"風邪を引いたようです。","romaji":"Kaze o hiita yō desu.","german":"I seem to have caught a cold."}],"notes":"More formal than みたいだ.","related":["n4-mitai-da","n4-rashii","n3-ki-ga-suru","n2-to-mieru"]},
{"id":"n4-mitai-da","pattern":"～みたいだ","level":"N4","category":"Satzstrukturen","meaning":"seems like (colloquial)","explanation":"みたいだ: the casual variant of ようだ.","formation":"Verb/Adj/Noun + みたいだ","examples":[{"japanese":"雨が降るみたいだ。","cloze":{"start":4,"answer":"みたいだ","quiz":{"level":"N4","japanese":"雨が降るみたいだ。","german":"It looks like it's going to rain.","start":4,"answer":"みたいだ","acceptedAnswers":["みたいだ","ようだ","らしい"],"distractors":[{"text":"なみたいだ","reason":"No な is inserted after the verb."},{"text":"みたいな","reason":"This form needs a following noun."},{"text":"みたいに","reason":"This form needs a following predicate."}],"promptKana":"あめがふる＿＿＿。"}},"romaji":"Ame ga furu mitai da.","german":"It looks like it's going to rain."},{"japanese":"あの人は先生みたいだ。","cloze":{"start":6,"answer":"みたいだ"},"romaji":"Ano hito wa sensei mitai da.","german":"That person seems to be a teacher."}],"notes":"Before nouns: みたいな, before verbs: みたいに.","related":["n4-you-da","n4-rashii"]},
{"id":"n4-rashii","pattern":"～らしい","level":"N4","category":"Satzstrukturen","meaning":"apparently, seemingly","explanation":"らしい: a supposition based on hearsay or inference.","formation":"Verb/Adj/Noun + らしい","examples":[{"japanese":"明日は雨らしい。","cloze":{"start":4,"answer":"らしい","quiz":{"level":"N4","japanese":"明日は雨らしい。","german":"Apparently it's going to rain tomorrow.","start":4,"answer":"らしい","acceptedAnswers":["らしい","のようだ","みたいだ","だそうだ"],"distractors":[{"text":"なようだ","reason":"After the noun, 雨のようだ would be correct."},{"text":"らしく","reason":"The adverbial form does not end the sentence."},{"text":"らしいだ","reason":"だ does not follow らしい."}],"promptKana":"あしたはあめ＿＿＿。"}},"romaji":"Ashita wa ame rashii.","german":"Apparently it's going to rain tomorrow."},{"japanese":"あの店はおいしいらしいですよ。","cloze":{"start":8,"answer":"らしい"},"romaji":"Ano mise wa oishii rashii desu yo.","german":"That restaurant is supposed to be good."}],"notes":"Conjugates like an い-adj.","related":["n4-you-da","n4-sou-hearsay","n2-to-mieru"]},
{"id":"n4-sou-hearsay","pattern":"～そうだ (伝聞)","level":"N4","category":"Satzstrukturen","meaning":"I heard that (hearsay)","explanation":"そうだ (伝聞): reports what you have heard or read.","formation":"Clause (plain form) + そうだ","examples":[{"japanese":"天気予報によると、明日は晴れるそうだ。","romaji":"Tenki yohō ni yoru to, ashita wa hareru sō da.","german":"According to the weather forecast, it will be sunny tomorrow.","cloze":{"start":15,"answer":"そうだ","quiz":{"level":"N4","japanese":"天気予報によると、明日は晴れるそうだ。","german":"According to the weather forecast, it will be sunny tomorrow.","start":15,"answer":"そうだ","acceptedAnswers":["そうだ","らしい","とのことだ"],"distractors":[{"text":"そうな","reason":"The attributive form needs a following noun."},{"text":"そうに","reason":"The adverbial form needs a following predicate."},{"text":"なそうだ","reason":"No な is inserted after the verb."}],"promptKana":"てんきよほうによると、あしたははれる＿＿＿。"}}},{"japanese":"あの映画は面白いそうです。","romaji":"Ano eiga wa omoshiroi sō desu.","german":"I hear that movie is interesting."}],"notes":"Hearsay: plain form + そうだ. Appearance: stem + そうだ.","related":["n4-sou-appearance","n4-rashii","n2-to-no-koto-da","n2-toka-denbun"]},
{"id":"n4-hazu-da","pattern":"～はずだ","level":"N4","category":"Satzstrukturen","meaning":"should be, is expected to","explanation":"はずだ: a strong expectation or logical conclusion.","formation":"Verb/い-Adj + はずだ / な-Adj + なはずだ","examples":[{"japanese":"もう届いているはずです。","romaji":"Mō todoiteiru hazu desu.","german":"It should have arrived by now."},{"japanese":"彼は知っているはずだ。","cloze":{"start":7,"answer":"はずだ","quiz":{"level":"N4","japanese":"彼は知っているはずだ。","german":"He should know.","start":7,"answer":"はずだ","acceptedAnswers":["はずだ"],"distractors":[{"text":"なはずだ","reason":"No な is inserted after the verb."},{"text":"はずな","reason":"This does not end the sentence here."},{"text":"はずをだ","reason":"を does not come before this copula."}],"promptKana":"かれはしっている＿＿＿。"}},"romaji":"Kare wa shitteiru hazu da.","german":"He should know."}],"notes":"はずがない = impossible.","related":["kamoshirenai","n4-beki-da"]},
{"id":"n4-ka-dou-ka","pattern":"～かどうか","level":"N4","category":"Satzstrukturen","meaning":"whether or not","explanation":"かどうか: a yes/no question as a subordinate clause.","formation":"Verb/Adj (plain form) + かどうか","examples":[{"japanese":"行くかどうか迷っています。","cloze":{"start":2,"answer":"かどうか","quiz":{"level":"N4","japanese":"行くかどうか迷っています。","german":"I can't decide whether to go.","start":2,"answer":"かどうか","acceptedAnswers":["かどうか"],"distractors":[{"text":"をどうか","reason":"The embedded yes/no question begins with か."},{"text":"がどうか","reason":"が does not replace the embedding か."},{"text":"などうか","reason":"No な is inserted after the verb."}],"promptKana":"いく＿＿＿まよっています。"}},"romaji":"Iku ka dō ka mayotteimasu.","german":"I can't decide whether to go."},{"japanese":"正しいかどうか確認してください。","cloze":{"start":3,"answer":"かどうか"},"romaji":"Tadashii ka dō ka kakunin shite kudasai.","german":"Please check whether it's correct."}],"notes":"Questions with a question word: just か (何時に来るか分からない).","related":["ka","n5-ka-ka","n4-indirect-question"]},
{"id":"n4-tame-ni","pattern":"～ために","level":"N4","category":"Satzstrukturen","meaning":"in order to (purpose) / because of (reason)","explanation":"ために: purpose (辞書形) or reason (た形/noun).","formation":"Verb (辞書形) + ために / Noun + のために","examples":[{"japanese":"日本語を勉強するために日本に来た。","cloze":{"start":8,"answer":"ために","quiz":{"level":"N4","japanese":"日本語を勉強するために日本に来た。","german":"I came to Japan to study Japanese.","start":8,"answer":"ために","acceptedAnswers":["ために"],"distractors":[{"text":"ためな","reason":"The purpose expression needs に, not な."},{"text":"なために","reason":"No な is inserted after a verb."},{"text":"ためを","reason":"を does not form a purpose expression here."}],"promptKana":"にほんごをべんきょうする＿＿＿にほんにきた。"}},"romaji":"Nihongo o benkyō suru tame ni Nihon ni kita.","german":"I came to Japan to study Japanese."},{"japanese":"台風のために電車が止まった。","cloze":{"start":3,"answer":"ために"},"romaji":"Taifū no tame ni densha ga tomatta.","german":"The trains stopped because of the typhoon."}],"notes":"Purpose: 辞書形. Reason: た形/noun.","related":["n4-you-ni-purpose","node"]},
{"id":"n4-you-ni-purpose","pattern":"～ように (Zweck)","level":"N4","category":"Satzstrukturen","meaning":"so that, in order that","explanation":"ように: an indirect purpose, used with the potential form or the ない-form.","formation":"Verb (辞書形/ない形) + ように","examples":[{"japanese":"忘れないように書いておきます。","romaji":"Wasurenai yō ni kaite okimasu.","german":"I'll write it down so that I don't forget.","cloze":{"start":4,"answer":"ように","quiz":{"level":"N4","japanese":"忘れないように書いておきます。","german":"I'll write it down so that I don't forget.","start":4,"answer":"ように","acceptedAnswers":["ように","ために"],"distractors":[{"text":"ような","reason":"Before the verb, an adverbial form is needed."},{"text":"ようを","reason":"を does not form a purpose expression here."},{"text":"なように","reason":"No な is inserted after the verb."}],"promptKana":"わすれない＿＿＿かいておきます。"}}},{"japanese":"聞こえるように大きい声で話して。","romaji":"Kikoeru yō ni ōkii koe de hanashite.","german":"Speak loudly so people can hear you."}],"notes":"ために = direct purpose. ように = indirect purpose.","related":["n4-tame-ni","n3-masu-you-ni"]},
{"id":"n4-ba","pattern":"～ば","level":"N4","category":"Satzstrukturen","meaning":"if (conditional)","explanation":"ば-form: a hypothetical condition.","formation":"Godan: u→eba / Ichidan: る→れば","examples":[{"japanese":"時間があれば行きます。","cloze":{"start":5,"answer":"ば","quiz":{"level":"N4","japanese":"時間があれば行きます。","german":"If I have time, I'll go.","start":5,"answer":"ば","acceptedAnswers":["ば"],"distractors":[{"text":"たら","reason":"あれたら is not a conditional form of ある."},{"text":"なら","reason":"あれなら is not a form of ある here."},{"text":"ても","reason":"あれても is not a verb form."}],"promptKana":"じかんがあれ＿＿＿いきます。"}},"romaji":"Jikan ga areba ikimasu.","german":"If I have time, I'll go."},{"japanese":"安ければ買います。","cloze":{"start":3,"answer":"ば"},"romaji":"Yasukereba kaimasu.","german":"If it's cheap, I'll buy it."}],"notes":"する→すれば, 来る→来れば. ～ば～ほど = the more ..., the more ....","related":["n4-nara","temo","n4-to-conditional","n3-ba-hodo"]},
{"id":"n4-nara","pattern":"～なら","level":"N4","category":"Satzstrukturen","meaning":"if, in case (topic)","explanation":"なら: picks up a topic and responds to what has been said.","formation":"Verb/Adj/Noun + なら","examples":[{"japanese":"日本に行くなら京都がおすすめです。","cloze":{"start":5,"answer":"なら","quiz":{"level":"N4","japanese":"日本に行くなら京都がおすすめです。","german":"If you're going to Japan, I recommend Kyoto.","start":5,"answer":"なら","acceptedAnswers":["なら"],"distractors":[{"text":"たら","reason":"行くたら is not a conditional form."},{"text":"れば","reason":"行くれば is not a conditional form."},{"text":"なのに","reason":"No な is inserted after 行く."}],"promptKana":"にほんにいく＿＿＿きょうとがおすすめです。"}},"romaji":"Nihon ni iku nara Kyōto ga osusume desu.","german":"If you're going to Japan, I recommend Kyoto."},{"japanese":"魚なら、このレストランがいい。","cloze":{"start":1,"answer":"なら"},"romaji":"Sakana nara, kono resutoran ga ii.","german":"If it's fish you want, this restaurant is good."}],"notes":"Often responds to information from the other person.","related":["n4-ba","n4-to-conditional","n3-to-suru-to","n2-you-dewa"]},
{"id":"n4-shi","pattern":"～し","level":"N4","category":"Satzstrukturen","meaning":"and what's more (listing reasons)","explanation":"し: lists several reasons or qualities.","formation":"Verb/い-Adj + し / な-Adj + だし","examples":[{"japanese":"この店は安いし、おいしいし、最高だ。","romaji":"Kono mise wa yasui shi, oishii shi, saikō da.","german":"It's cheap and tasty, simply the best.","cloze":{"start":6,"answer":"し","quiz":{"level":"N4","japanese":"この店は安いし、おいしいし、最高だ。","german":"It's cheap and tasty, simply the best.","start":6,"answer":"し","acceptedAnswers":["し"],"distractors":[{"text":"な","reason":"An い-adjective does not take な here."},{"text":"の","reason":"安いの does not link the parallel reason here."},{"text":"を","reason":"を does not coordinate reasons here."}],"promptKana":"このみせはやすい＿＿＿、おいしいし、さいこうだ。"}}},{"japanese":"時間もないし、お金もないし、行けない。","romaji":"Jikan mo nai shi, okane mo nai shi, ikenai.","german":"No time, no money, so I can't go."}],"notes":"Also with just one reason: 疲れたし、帰ろう.","related":["node","n2-koto-dashi","n2-mo-ba-mo"]},
{"id":"n4-mama","pattern":"～まま","level":"N4","category":"Satzstrukturen","meaning":"as it is, in the state of","explanation":"まま: a state remains unchanged.","formation":"Verb (た形) + まま / Noun + のまま","examples":[{"japanese":"靴を履いたまま入らないで。","cloze":{"start":5,"answer":"まま","quiz":{"level":"N4","japanese":"靴を履いたまま入らないで。","german":"Don't come in with your shoes on.","start":5,"answer":"まま","acceptedAnswers":["まま"],"distractors":[{"text":"ながら","reason":"ながら does not attach to 履いた."},{"text":"てから","reason":"履いたてから is not a valid verb connection."},{"text":"なまま","reason":"No な is inserted after the verb."}],"promptKana":"くつをはいた＿＿＿はいらないで。"}},"romaji":"Kutsu o haita mama hairanaide.","german":"Don't come in with your shoes on."},{"japanese":"電気をつけたまま寝てしまった。","cloze":{"start":6,"answer":"まま"},"romaji":"Denki o tsuketa mama nete shimatta.","german":"I fell asleep with the light on."}],"notes":"そのまま = as it is.","related":["n2-zu-jimai"]},
{"id":"n4-tokoro-da","pattern":"～ところだ","level":"N4","category":"Satzstrukturen","meaning":"about to / just did","explanation":"ところだ: the point in time of an action (before/in the middle of it/after).","formation":"辞書形+ところ / ている+ところ / た形+ところ","examples":[{"japanese":"今から出かけるところです。","romaji":"Ima kara dekakeru tokoro desu.","german":"I'm just about to go out.","cloze":{"start":7,"answer":"ところです","quiz":{"level":"N4","japanese":"今から出かけるところです。","german":"I'm just about to go out.","start":7,"answer":"ところです","acceptedAnswers":["ところです"],"distractors":[{"text":"ところな","reason":"This does not end the sentence here."},{"text":"なところです","reason":"No な is inserted after the verb."},{"text":"ところをです","reason":"を does not come before です here."}],"promptKana":"いまからでかける＿＿＿。"}}},{"japanese":"今食べ終わったところです。","romaji":"Ima tabe owatta tokoro desu.","german":"I've just finished eating."}],"notes":"辞書形 = about to. ている = right now, in the middle of it. た形 = just now.","related":["n4-tabakari"]},
{"id":"n4-ni-tsuite","pattern":"～について","level":"N4","category":"Satzstrukturen","meaning":"about, concerning","explanation":"について: indicates the topic that is being talked about.","formation":"Noun + について","examples":[{"japanese":"日本の文化について調べています。","cloze":{"start":5,"answer":"について","quiz":{"level":"N4","japanese":"日本の文化について調べています。","german":"I'm researching Japanese culture.","start":5,"answer":"について","acceptedAnswers":["について","を","に関して"],"distractors":[{"text":"についての","reason":"の would modify a noun instead of the verb."},{"text":"にとって","reason":"This marks a standard of value, not a research topic."},{"text":"によると","reason":"This names a source, not the topic being researched."}],"promptKana":"にほんのぶんか＿＿＿しらべています。"}},"romaji":"Nihon no bunka ni tsuite shirabeteimasu.","german":"I'm researching Japanese culture."},{"japanese":"この問題について話し合いましょう。","cloze":{"start":4,"answer":"について"},"romaji":"Kono mondai ni tsuite hanashi aimashō.","german":"Let's discuss this problem."}],"notes":"Before a noun: ～についての + noun.","related":["n4-ni-taishite","n2-ni-tsuki"]},
{"id":"n4-ni-yoru-to","pattern":"～によると","level":"N4","category":"Satzstrukturen","meaning":"according to","explanation":"によると: indicates the source of a piece of information.","formation":"Noun + によると","examples":[{"japanese":"天気予報によると明日は雨だそうだ。","cloze":{"start":4,"answer":"によると","quiz":{"level":"N4","japanese":"天気予報によると明日は雨だそうだ。","german":"According to the weather forecast, it will rain tomorrow.","start":4,"answer":"によると","acceptedAnswers":["によると","では"],"distractors":[{"text":"によるの","reason":"の does not form a source expression before the following clause here."},{"text":"にとって","reason":"A weather forecast is a source of information here, not a standard of value."},{"text":"としての","reason":"の needs a head noun."}],"promptKana":"てんきよほう＿＿＿あしたはあめだそうだ。"}},"romaji":"Tenki yohō ni yoru to ashita wa ame da sō da.","german":"According to the weather forecast, it will rain tomorrow."},{"japanese":"ニュースによると事故があったそうだ。","cloze":{"start":4,"answer":"によると"},"romaji":"Nyūsu ni yoru to jiko ga atta sō da.","german":"According to the news, there was an accident."}],"notes":"Often with ～そうだ or ～ということだ.","related":["n4-sou-hearsay","n4-ni-yotte","n3-ni-yori-ni-yoru"]},
{"id":"n4-okage-de","pattern":"～おかげで","level":"N4","category":"Satzstrukturen","meaning":"thanks to (positive)","explanation":"おかげで: a positive cause, expressing gratitude.","formation":"Verb/Adj + おかげで / Noun + のおかげで","examples":[{"japanese":"先生のおかげで合格しました。","cloze":{"start":3,"answer":"おかげで","quiz":{"level":"N4","japanese":"先生のおかげで合格しました。","german":"Thanks to my teacher, I passed.","start":3,"answer":"おかげで","acceptedAnswers":["おかげで"],"distractors":[{"text":"前に","reason":"This means before the teacher, not thanks to them."},{"text":"代わりに","reason":"This means instead of the teacher, not thanks to them."},{"text":"せいで","reason":"せいで assigns negative blame; the translation \"thanks to\" calls for positive appreciation."}],"promptKana":"せんせいの＿＿＿ごうかくしました。"}},"romaji":"Sensei no okage de gōkaku shimashita.","german":"Thanks to my teacher, I passed."},{"japanese":"薬のおかげで元気になった。","cloze":{"start":2,"answer":"おかげで"},"romaji":"Kusuri no okage de genki ni natta.","german":"Thanks to the medicine, I got better."}],"notes":"Positive: おかげで. Negative: せいで.","related":["n4-sei-de","n3-sei-ka"]},
{"id":"n4-sei-de","pattern":"～せいで","level":"N4","category":"Satzstrukturen","meaning":"because of (negative, blame)","explanation":"せいで: a negative cause, assigning blame.","formation":"Verb/Adj + せいで / Noun + のせいで","examples":[{"japanese":"雨のせいで試合が中止になった。","cloze":{"start":2,"answer":"せいで","quiz":{"level":"N4","japanese":"雨のせいで試合が中止になった。","german":"The game was canceled because of the rain.","start":2,"answer":"せいで","acceptedAnswers":["せいで","ために","ため"],"distractors":[{"text":"前に","reason":"This means before the rain, not because of the rain."},{"text":"代わりに","reason":"This means instead of the rain, not because of it."},{"text":"おかげで","reason":"This would praise the cancellation as something to be grateful for; what is meant is an unfavorable cause."}],"promptKana":"あめの＿＿＿しあいがちゅうしになった。"}},"romaji":"Ame no sei de shiai ga chūshi ni natta.","german":"The game was canceled because of the rain."},{"japanese":"寝坊したせいで遅刻した。","cloze":{"start":4,"answer":"せいで"},"romaji":"Nebō shita sei de chikoku shita.","german":"I was late because I overslept."}],"notes":"Opposite: おかげで (positive).","related":["n4-okage-de","n3-sei-ka"]},
{"id":"n4-wake-da","pattern":"～わけだ","level":"N4","category":"Satzstrukturen","meaning":"no wonder, that explains it","explanation":"わけだ: a logical conclusion.","formation":"Verb/Adj (plain form) + わけだ","examples":[{"japanese":"毎日練習してるから上手なわけだ。","cloze":{"start":12,"answer":"わけだ","quiz":{"level":"N4","japanese":"毎日練習してるから上手なわけだ。","german":"He practices every day, so no wonder he's good.","start":12,"answer":"わけだ","acceptedAnswers":["わけだ"],"distractors":[{"text":"わけをだ","reason":"を does not come before this copula."},{"text":"わけな","reason":"This does not end the sentence here."},{"text":"ようだ","reason":"上手なようだ can express a guess; the given sentence, however, explains the established skill as no wonder."}],"promptKana":"まいにちれんしゅうしてるからじょうずな＿＿＿。"}},"romaji":"Mainichi renshū shiteru kara jōzu na wake da.","german":"He practices every day, so no wonder he's good."},{"japanese":"道理で安いわけだ。","cloze":{"start":5,"answer":"わけだ"},"romaji":"Dōri de yasui wake da.","german":"No wonder it's cheap."}],"notes":"わけがない = impossible. わけではない = not necessarily.","related":["n4-hazu-da"]},
{"id":"n4-beki-da","pattern":"～べきだ","level":"N3","category":"Satzstrukturen","meaning":"should (moral obligation)","explanation":"べきだ: a strong recommendation or duty.","formation":"Verb (辞書形) + べきだ","examples":[{"japanese":"約束は守るべきだ。","cloze":{"start":5,"answer":"べきだ","quiz":{"level":"N3","japanese":"約束は守るべきだ。","german":"You should keep your promises.","start":5,"answer":"べきだ","acceptedAnswers":["べきだ"],"distractors":[{"text":"なべきだ","reason":"No な is inserted after the verb."},{"text":"べきな","reason":"The attributive form does not end the sentence here."},{"text":"べきをだ","reason":"を does not come before this copula."}],"promptKana":"やくそくはまもる＿＿＿。"}},"romaji":"Yakusoku wa mamoru beki da.","german":"You should keep your promises."},{"japanese":"もっと早く言うべきだった。","cloze":{"start":7,"answer":"べきだ"},"romaji":"Motto hayaku iu beki datta.","german":"I should have said so sooner."}],"notes":"する→すべき/するべき. Negative: ～べきではない.","related":["n4-hazu-da","nakereba-naranai"]},
{"id":"n4-tewa-ikenai","pattern":"～てはいけない","level":"N4","category":"Satzstrukturen","meaning":"must not, forbidden","explanation":"てはいけない: a prohibition.","formation":"Verb (て-form) + はいけない","examples":[{"japanese":"ここで写真を撮ってはいけません。","romaji":"Koko de shashin o totte wa ikemasen.","german":"You may not take photos here."},{"japanese":"授業中に寝てはいけない。","cloze":{"start":5,"answer":"てはいけない","quiz":{"level":"N4","japanese":"授業中に寝てはいけない。","german":"You must not sleep in class.","start":5,"answer":"てはいけない","acceptedAnswers":["てはいけない"],"distractors":[{"text":"てもいい","reason":"This allows sleeping."},{"text":"てください","reason":"This tells you to sleep."},{"text":"たはいけない","reason":"The prohibition requires the て-form."}],"promptKana":"じゅぎょうちゅうにね＿＿＿。"}},"romaji":"Jugyō-chū ni nete wa ikenai.","german":"You must not sleep in class."}],"notes":"Colloquial: ～ちゃだめ.","related":["nakereba-naranai","nakutemo-ii","n4-temo-kamawanai","n4-cha-ikenai","n2-te-wa-naranai"]},
{"id":"n4-ta-hou-ga-ii","pattern":"～たほうがいい","level":"N4","category":"Satzstrukturen","meaning":"had better","explanation":"たほうがいい: advice or a recommendation.","formation":"Verb (た形) + ほうがいい / Verb (ない形) + ほうがいい","examples":[{"japanese":"早く寝たほうがいいですよ。","cloze":{"start":3,"answer":"たほうがいい","quiz":{"level":"N4","japanese":"早く寝たほうがいいですよ。","german":"You'd better go to bed early.","start":3,"answer":"たほうがいい","acceptedAnswers":["たほうがいい"],"distractors":[{"text":"たほうをいい","reason":"The evaluation requires が."},{"text":"たほうがよくない","reason":"This advises against going to bed early."},{"text":"るほうをいい","reason":"を does not fit the comparative evaluation."}],"promptKana":"はやくね＿＿＿ですよ。"}},"romaji":"Hayaku neta hō ga ii desu yo.","german":"You'd better go to bed early."},{"japanese":"飲まないほうがいい。","romaji":"Nomanai hō ga ii.","german":"You'd better not drink."}],"notes":"た形 = recommending. ない形 = advising against.","related":["n4-beki-da","n3-tara-ii-ba-ii"]},
{"id":"n4-to-conditional","pattern":"～と (Konditional)","level":"N4","category":"Satzstrukturen","meaning":"when, whenever (natural consequence)","explanation":"と: a natural, automatic or habitual consequence.","formation":"Verb (辞書形/ない形) + と","examples":[{"japanese":"春になると桜が咲く。","romaji":"Haru ni naru to sakura ga saku.","german":"When spring comes, the cherry blossoms bloom.","cloze":{"start":4,"answer":"と","quiz":{"level":"N4","japanese":"春になると桜が咲く。","german":"When spring comes, the cherry blossoms bloom.","start":4,"answer":"と","acceptedAnswers":["と","なら"],"distractors":[{"text":"たら","reason":"なるたら is not a conditional form."},{"text":"れば","reason":"なるれば is not a conditional form."},{"text":"ながら","reason":"ながら requires the stem なり."}],"promptKana":"はるになる＿＿＿さくらがさく。"}}},{"japanese":"このボタンを押すとドアが開きます。","romaji":"Kono botan o osu to doa ga akimasu.","german":"When you press this button, the door opens."}],"notes":"Used for laws of nature, habits and giving directions.","related":["n4-ba","n4-nara","n4-nai-to-ikenai"]},
{"id":"n4-aida-ni","pattern":"～間に / ～間","level":"N4","category":"Satzstrukturen","meaning":"while, during (period of time)","explanation":"間に: at some point within a period of time. 間: for the whole duration.","formation":"Verb (ている) + 間(に) / Noun + の間(に)","examples":[{"japanese":"母が寝ている間に掃除した。","romaji":"Haha ga neteiru aida ni sōji shita.","german":"I cleaned while my mother was sleeping."},{"japanese":"夏休みの間旅行していた。","cloze":{"start":4,"answer":"間","quiz":{"level":"N4","japanese":"夏休みの間旅行していた。","german":"I was traveling during the summer vacation.","start":4,"answer":"間","acceptedAnswers":["間","間に","間は"],"distractors":[{"text":"前","reason":"This means before the vacation."},{"text":"後","reason":"This means after the vacation."},{"text":"ためな","reason":"This is not a temporal noun connection."}],"promptKana":"なつやすみの＿＿＿りょこうしていた。"}},"romaji":"Natsuyasumi no aida ryokō shiteita.","german":"I was traveling during the summer vacation."}],"notes":"間に = at a point. 間 = throughout.","related":["nagara"]},
{"id":"n4-ato-de","pattern":"～後で / ～てから","level":"N4","category":"Satzstrukturen","meaning":"after","explanation":"後で and てから: after an action.","formation":"Verb (た形) + 後で / Verb (て) + から","examples":[{"japanese":"仕事が終わった後で飲みに行こう。","cloze":{"start":7,"answer":"後で","quiz":{"level":"N4","japanese":"仕事が終わった後で飲みに行こう。","german":"Let's go for a drink after work.","start":7,"answer":"後で","acceptedAnswers":["後で"],"distractors":[{"text":"前に","reason":"前に requires the dictionary form and means before."},{"text":"ながら","reason":"ながら requires the verb stem."},{"text":"てから","reason":"終わったてから is not a valid verb connection."}],"promptKana":"しごとがおわった＿＿＿のみにいこう。"}},"romaji":"Shigoto ga owatta ato de nomi ni ikō.","german":"Let's go for a drink after work."},{"japanese":"ご飯を食べてから出かけます。","cloze":{"start":5,"answer":"てから"},"romaji":"Gohan o tabete kara dekakemasu.","german":"I'll go out after eating."}],"notes":"てから puts more emphasis on the sequence.","related":["mae-ni"]},
{"id":"n4-made-ni","pattern":"～までに","level":"N4","category":"Satzstrukturen","meaning":"by (deadline)","explanation":"までに: a deadline by which something has to be done.","formation":"Point in time/Verb (辞書形) + までに","examples":[{"japanese":"金曜日までにレポートを出してください。","cloze":{"start":3,"answer":"までに","quiz":{"level":"N4","japanese":"金曜日までにレポートを出してください。","german":"Please hand in the report by Friday.","start":3,"answer":"までに","acceptedAnswers":["までに"],"distractors":[{"text":"から","reason":"This means from Friday on rather than by Friday at the latest."},{"text":"の後で","reason":"This means after Friday."},{"text":"より後に","reason":"This means later than Friday."}],"promptKana":"きんようび＿＿＿レポートをだしてください。"}},"romaji":"Kin'yōbi made ni repōto o dashite kudasai.","german":"Please hand in the report by Friday."},{"japanese":"電車が来るまでに切符を買おう。","cloze":{"start":5,"answer":"までに"},"romaji":"Densha ga kuru made ni kippu o kaō.","german":"Let's buy our tickets before the train comes."}],"notes":"までに = by (deadline). まで = until (continuously).","related":["made"]},
{"id":"n4-relative-clause","pattern":"Relativsätze","level":"N4","category":"Satzstrukturen","meaning":"clause that describes a noun","explanation":"In Japanese, relative clauses come before the noun. No relative pronoun is needed.","formation":"Verb/Adj (plain form) + Noun","examples":[{"japanese":"昨日買った本はとても面白い。","romaji":"Kinō katta hon wa totemo omoshiroi.","german":"The book I bought yesterday is very interesting.","cloze":{"start":0,"answer":"昨日買った","quiz":{"level":"N4","japanese":"昨日買った本はとても面白い。","german":"The book I bought yesterday is very interesting.","start":0,"answer":"昨日買った","acceptedAnswers":["昨日買った"],"distractors":[{"text":"昨日買いました","reason":"The plain form is used here before the head noun."},{"text":"昨日買ったの","reason":"A verbal relative clause does not need の before 本."},{"text":"昨日買うでした","reason":"This is not a verb form."}],"promptKana":"＿＿＿ほんはとてもおもしろい。"}}},{"japanese":"日本語を教えている先生は田中先生です。","romaji":"Nihongo o oshieteiru sensei wa Tanaka-sensei desu.","german":"The teacher who teaches Japanese is Mr. Tanaka."}],"notes":"Simply put the clause in front of the noun.","related":[]},
{"id":"n4-koto-ga-aru","pattern":"～ことがある (manchmal)","level":"N4","category":"Satzstrukturen","meaning":"there are times when","explanation":"辞書形 + ことがある: something happens occasionally.","formation":"Verb (辞書形) + ことがある","examples":[{"japanese":"朝ご飯を食べないことがある。","romaji":"Asagohan o tabenai koto ga aru.","german":"Sometimes I don't eat breakfast.","cloze":{"start":8,"answer":"ことがある","quiz":{"level":"N4","japanese":"朝ご飯を食べないことがある。","german":"Sometimes I don't eat breakfast.","start":8,"answer":"ことがある","acceptedAnswers":["ことがある"],"distractors":[{"text":"ことをある","reason":"ある does not take an object with を here."},{"text":"なことがある","reason":"No な is inserted after the verb."},{"text":"ことがない","reason":"This negates occasionally skipping it."}],"promptKana":"あさごはんをたべない＿＿＿。"}}},{"japanese":"たまに遅刻することがあります。","romaji":"Tama ni chikoku suru koto ga arimasu.","german":"Occasionally I'm late."}],"notes":"辞書形 = sometimes. た形 = experience.","related":["ta-koto-ga-aru"]},
{"id":"n4-toka","pattern":"～とか","level":"N4","category":"Satzstrukturen","meaning":"things like, for example","explanation":"とか: casual listing of examples.","formation":"Noun + とか + Noun + とか","examples":[{"japanese":"週末は映画とか買い物とかする。","romaji":"Shūmatsu wa eiga toka kaimono toka suru.","german":"On weekends I do things like watching movies and shopping.","cloze":{"start":5,"answer":"とか","quiz":{"level":"N4","japanese":"週末は映画とか買い物とかする。","german":"On weekends I do things like watching movies and shopping.","start":5,"answer":"とか","acceptedAnswers":["とか","や"],"distractors":[{"text":"しか","reason":"しか requires a negative ending."},{"text":"へ","reason":"へ does not list leisure activities."},{"text":"が","reason":"が makes movies the subject rather than an item in the list."}],"promptKana":"しゅうまつはえいが＿＿＿かいものとかする。"}}},{"japanese":"りんごとかバナナとか買ってきて。","romaji":"Ringo toka banana toka katte kite.","german":"Buy some apples or bananas or something."}],"notes":"More casual than ～など.","related":["n4-nado","ya","n3-nante-nanka","n3-to-itta","n2-yara-yara"]},
{"id":"n4-tte","pattern":"～って","level":"N4","category":"Satzstrukturen","meaning":"casual quotation","explanation":"って: colloquial と (quotation particle).","formation":"Sentence + って","examples":[{"japanese":"田中さんは来ないって。","cloze":{"start":8,"answer":"って","quiz":{"level":"N4","japanese":"田中さんは来ないって。","german":"Tanaka says he's not coming.","start":8,"answer":"って","acceptedAnswers":["って","そうだ","とのことだ"],"distractors":[{"text":"なって","reason":"No な is inserted after 来ない for a quotation."},{"text":"をって","reason":"をって is not a quotation connection."},{"text":"ってを","reason":"を cannot end the quotation here without a further predicate."}],"promptKana":"たなかさんはこない＿＿＿。"}},"romaji":"Tanaka-san wa konai tte.","german":"Tanaka says he's not coming."},{"japanese":"すみませんって日本語で何？","cloze":{"start":5,"answer":"って"},"romaji":"Sumimasen tte nihongo de nani?","german":"What does \"sumimasen\" mean?"}],"notes":"～って言ってた = said that. ～っていう = called, named.","related":["n4-toiu","n3-to-iu-no-wa","n2-ttara","n3-tteba"]},
{"id":"n4-ba-yokatta","pattern":"～ばよかった","level":"N4","category":"Satzstrukturen","meaning":"should have","explanation":"ばよかった: regret about something you didn't do.","formation":"Verb (ば-form) + よかった","examples":[{"japanese":"もっと勉強すればよかった。","cloze":{"start":7,"answer":"ばよかった","quiz":{"level":"N4","japanese":"もっと勉強すればよかった。","german":"I should have studied more.","start":7,"answer":"ばよかった","acceptedAnswers":["ばよかった"],"distractors":[{"text":"たらよかった","reason":"すれたら is not a verb form."},{"text":"ばよくない","reason":"This does not express regret in hindsight."},{"text":"ばよいだった","reason":"よい forms its past as よかった."}],"promptKana":"もっとべんきょうすれ＿＿＿。"}},"romaji":"Motto benkyō sureba yokatta.","german":"I should have studied more."},{"japanese":"傘を持ってくればよかった。","cloze":{"start":7,"answer":"ばよかった"},"romaji":"Kasa o motte kureba yokatta.","german":"I should have brought an umbrella."}],"notes":"Negative: ～なければよかった (shouldn't have done it).","related":["n4-ba","n4-te-yokatta"]},
{"id":"n4-te-itadakemasenka","pattern":"～ていただけませんか","level":"N4","category":"Satzstrukturen","meaning":"could you please (very polite)","explanation":"ていただけませんか: a very polite request.","formation":"Verb (て-form) + いただけませんか","examples":[{"japanese":"少々お待ちいただけませんか。","romaji":"Shōshō omachi itadakemasen ka.","german":"Could you please wait a moment?"},{"japanese":"もう一度説明していただけませんか。","cloze":{"start":7,"answer":"ていただけませんか","quiz":{"level":"N4","japanese":"もう一度説明していただけませんか。","german":"Could you explain it once more?","start":7,"answer":"ていただけませんか","acceptedAnswers":["ていただけませんか"],"distractors":[{"text":"たいただけませんか","reason":"いただく follows the て-form here."},{"text":"ていただけるませんか","reason":"The polite form is いただけません."},{"text":"ていただけませんた","reason":"This is not a polite question form."}],"promptKana":"もういちどせつめいし＿＿＿。"}},"romaji":"Mō ichido setsumei shite itadakemasen ka.","german":"Could you explain it once more?"}],"notes":"てください < てもらえませんか < ていただけませんか.","related":["te-kudasai","n4-temorau","keigo-teinei-itadakemasenka"]},
{"id":"n4-hodo-nai","pattern":"～ほど～ない","level":"N4","category":"Satzstrukturen","meaning":"not as ... as","explanation":"ほど～ない: a negative comparison.","formation":"A は B ほど + Adj (ない形)","examples":[{"japanese":"東京は大阪ほど暑くない。","romaji":"Tōkyō wa Ōsaka hodo atsuku nai.","german":"Tokyo is not as hot as Osaka.","cloze":{"start":5,"answer":"ほど暑くない","quiz":{"level":"N4","japanese":"東京は大阪ほど暑くない。","german":"Tokyo is not as hot as Osaka.","start":5,"answer":"ほど暑くない","acceptedAnswers":["ほど暑くない"],"distractors":[{"text":"より暑い","reason":"This claims Tokyo is hotter."},{"text":"ほど暑いない","reason":"The negative form is 暑くない."},{"text":"ほど暑くあります","reason":"This does not negate the comparison."}],"promptKana":"とうきょうはおおさか＿＿＿。"}}},{"japanese":"日本語は中国語ほど難しくない。","romaji":"Nihongo wa chūgokugo hodo muzukashiku nai.","german":"Japanese is not as difficult as Chinese."}],"notes":"Negative comparison. Positive: ～より～のほうが.","related":["n4-yori","n4-hodo-p"]},
{"id":"n4-you-ni-shiteiru","pattern":"～ようにしている","level":"N4","category":"Satzstrukturen","meaning":"to make a point of, to keep up a habit","explanation":"ようにしている: a conscious habit you make a point of keeping.","formation":"Verb (辞書形/ない形) + ようにしている","examples":[{"japanese":"毎日野菜を食べるようにしている。","cloze":{"start":8,"answer":"ようにしている","quiz":{"level":"N4","japanese":"毎日野菜を食べるようにしている。","german":"I make a point of eating vegetables every day.","start":8,"answer":"ようにしている","acceptedAnswers":["ようにしている"],"distractors":[{"text":"ようをしている","reason":"The habit you aim for requires に."},{"text":"なようにしている","reason":"No な is inserted after the verb."},{"text":"ようにしていない","reason":"This negates the effort."}],"promptKana":"まいにちやさいをたべる＿＿＿。"}},"romaji":"Mainichi yasai o taberu yō ni shiteiru.","german":"I make a point of eating vegetables every day."},{"japanese":"夜遅く食べないようにしている。","cloze":{"start":7,"answer":"ようにしている"},"romaji":"Yoru osoku tabenai yō ni shiteiru.","german":"I make a point of not eating late at night."}],"notes":"ようにする = to try on one occasion. ようにしている = a regular habit.","related":["n4-you-ni-suru"]},
{"id":"n4-tagaru","pattern":"～たがる","level":"N4","category":"Verben","meaning":"to want (of a third person)","explanation":"たがる: expresses the wish of a third person. ～たい can only be used for yourself.","formation":"Verb (ます-stem) + たがる","examples":[{"japanese":"子供は外に出たがっている。","romaji":"Kodomo wa soto ni detagatte iru.","german":"The child wants to go outside.","cloze":{"start":6,"answer":"たがっている","quiz":{"level":"N4","japanese":"子供は外に出たがっている。","german":"The child wants to go outside.","start":6,"answer":"たがっている","acceptedAnswers":["たがっている"],"distractors":[{"text":"たいがっている","reason":"The final い of たい is dropped before がる."},{"text":"たがっていない","reason":"This negates the wish being shown."},{"text":"たがるている","reason":"The て-form is たがって."}],"promptKana":"こどもはそとにで＿＿＿。"}}},{"japanese":"彼は日本に行きたがっている。","romaji":"Kare wa Nihon ni ikitagatte iru.","german":"He wants to go to Japan."}],"notes":"Your own wish: ～たい. Third persons: ～たがる. Godan conjugation.","related":["tai","n4-garu"]},
{"id":"n4-ppoi","pattern":"～っぽい","level":"N4","category":"Adjektive","meaning":"-ish, -like, seeming","explanation":"っぽい: casual; expresses that something gives the impression of something else.","formation":"Noun/verb stem + っぽい","examples":[{"japanese":"この色は白っぽい。","cloze":{"start":5,"answer":"っぽい","quiz":{"level":"N4","japanese":"この色は白っぽい。","german":"This color is whitish.","start":5,"answer":"っぽい","acceptedAnswers":["っぽい"],"distractors":[{"text":"っぽいだ","reason":"An い-adjective does not take だ."},{"text":"っぽくでした","reason":"This is not an adjective form."},{"text":"っぽくます","reason":"An い-adjective does not take ます."}],"promptKana":"このいろはしろ＿＿＿。"}},"romaji":"Kono iro wa shiroppoi.","german":"This color is whitish."},{"japanese":"彼は怒りっぽい。","cloze":{"start":4,"answer":"っぽい"},"romaji":"Kare wa okorippoi.","german":"He gets angry easily."},{"japanese":"子供っぽい行動だ。","cloze":{"start":2,"answer":"っぽい"},"romaji":"Kodomoppoi kōdō da.","german":"That's childish behavior."}],"notes":"Often slightly negative. Conjugates like an い-adj: っぽくない, っぽかった.","related":["n4-rashii-adj","n4-gachi","n2-buru"]},
{"id":"n4-kakeru","pattern":"～かける","level":"N3","category":"Verben","meaning":"to start to; to half do","explanation":"かける: an action was started but not finished.","formation":"Verb (ます-stem) + かける","examples":[{"japanese":"読みかけの本がある。","romaji":"Yomikake no hon ga aru.","german":"I have a book I've started reading.","cloze":{"start":2,"answer":"かけ","quiz":{"level":"N3","japanese":"読みかけの本がある。","german":"I have a book I've started reading.","start":2,"answer":"かけ","acceptedAnswers":["かけ"],"distractors":[{"text":"ます","reason":"読みますの is not a suitable noun modifier here."},{"text":"た","reason":"読みた is not a form of 読む."},{"text":"かける","reason":"読みかける would modify 本 directly, without の."}],"promptKana":"よみ＿＿＿のほんがある。"}}},{"japanese":"言いかけてやめた。","romaji":"Iikakete yameta.","german":"I started to say something and stopped."}],"notes":"死にかける = to come close to death. 食べかけ = half-eaten.","related":["n4-hajimeru","n3-tate"]},
{"id":"n4-naosu","pattern":"～直す","level":"N4","category":"Verben","meaning":"to redo, to do again","explanation":"直す as a suffix: repeating an action in order to improve it.","formation":"Verb (ます-stem) + 直す","examples":[{"japanese":"もう一度やり直してください。","romaji":"Mō ichido yari naoshite kudasai.","german":"Please do it over again.","cloze":{"start":6,"answer":"直して","quiz":{"level":"N4","japanese":"もう一度やり直してください。","german":"Please do it over again.","start":6,"answer":"直して","acceptedAnswers":["直して"],"distractors":[{"text":"直した","reason":"The request requires the て-form."},{"text":"直します","reason":"ます cannot come before ください here."},{"text":"直さないで","reason":"This asks not to redo the action."}],"promptKana":"もういちどやり＿＿＿ください。"}}},{"japanese":"この文を書き直した。","romaji":"Kono bun o kaki naoshita.","german":"I rewrote this sentence."}],"notes":"やり直す (to redo), 考え直す (to reconsider), 見直す (to look over again).","related":[]},
{"id":"n4-au","pattern":"～合う","level":"N4","category":"Verben","meaning":"mutually, with each other","explanation":"合う as a suffix: an action is done mutually.","formation":"Verb (ます-stem) + 合う","examples":[{"japanese":"友達と助け合っている。","romaji":"Tomodachi to tasuke atte iru.","german":"My friends and I help each other.","cloze":{"start":5,"answer":"合っている","quiz":{"level":"N4","japanese":"友達と助け合っている。","german":"My friends and I help each other.","start":5,"answer":"合っている","acceptedAnswers":["合っている"],"distractors":[{"text":"合っていない","reason":"This negates the mutual help."},{"text":"合うている","reason":"合う forms the て-form 合って."},{"text":"ます合っている","reason":"ます is not inserted between the verbs."}],"promptKana":"ともだちとたすけ＿＿＿。"}}},{"japanese":"この問題について話し合いましょう。","romaji":"Kono mondai ni tsuite hanashi aimashō.","german":"Let's discuss this problem."}],"notes":"話し合う (to discuss), 助け合う (to help each other), 愛し合う (to love each other).","related":[]},
{"id":"n4-koto-wa-ga","pattern":"～ことは～が","level":"N4","category":"Satzstrukturen","meaning":"it's true that ... but","explanation":"ことは～が: concedes something, but then qualifies it.","formation":"Verb/Adj + ことは + Verb/Adj + が","examples":[{"japanese":"食べることは食べたが、おいしくなかった。","romaji":"Taberu koto wa tabeta ga, oishiku nakatta.","german":"I did eat it, but it wasn't tasty.","cloze":{"start":3,"answer":"ことは食べたが","quiz":{"level":"N4","japanese":"食べることは食べたが、おいしくなかった。","german":"I did eat it, but it wasn't tasty.","start":3,"answer":"ことは食べたが","acceptedAnswers":["ことは食べたが"],"distractors":[{"text":"ことは食べなかったが","reason":"This negates the action that is explicitly conceded."},{"text":"ことを食べたが","reason":"The concession requires は."},{"text":"ことは食べたので","reason":"ので gives a reason rather than the conceded contrast."}],"promptKana":"たべる＿＿＿、おいしくなかった。"}}},{"japanese":"高いことは高いが、品質はいい。","romaji":"Takai koto wa takai ga, hinshitsu wa ii.","german":"It is expensive, but the quality is good."}],"notes":"The same verb/adjective is repeated.","related":["noni"]},
{"id":"n4-te-kudasaimasenka","pattern":"～てくださいませんか","level":"N4","category":"Satzstrukturen","meaning":"would you please (polite)","explanation":"てくださいませんか: a polite request, between てください and ていただけませんか.","formation":"Verb (て-form) + くださいませんか","examples":[{"japanese":"ちょっと手伝ってくださいませんか。","cloze":{"start":7,"answer":"てくださいませんか","quiz":{"level":"N4","japanese":"ちょっと手伝ってくださいませんか。","german":"Would you please help me for a moment?","start":7,"answer":"てくださいませんか","acceptedAnswers":["てくださいませんか"],"distractors":[{"text":"たくださいませんか","reason":"The request requires the て-form."},{"text":"てくださるませんか","reason":"The polite form of くださる is くださいません."},{"text":"てくださいませんた","reason":"This is not a question form."}],"promptKana":"ちょっとてつだっ＿＿＿。"}},"romaji":"Chotto tetsudatte kudasaimasen ka.","german":"Would you please help me for a moment?"},{"japanese":"写真を撮ってくださいませんか。","cloze":{"start":5,"answer":"てくださいませんか"},"romaji":"Shashin o totte kudasaimasen ka.","german":"Would you please take a photo?"}],"notes":"てください < てくださいませんか < ていただけませんか.","related":["te-kudasai","n4-te-itadakemasenka"]},
{"id":"n4-sasete-morau","pattern":"～させてもらう","level":"N4","category":"Verben","meaning":"to be allowed to, to take the liberty of","explanation":"させてもらう: asking for and receiving permission to do something.","formation":"Verb (させ-form) + てもらう","examples":[{"japanese":"今日は早退させてもらいます。","romaji":"Kyō wa sōtai sasete moraimasu.","german":"I'll take the liberty of leaving early today.","cloze":{"start":5,"answer":"させてもらいます","quiz":{"level":"N4","japanese":"今日は早退させてもらいます。","german":"I'll take the liberty of leaving early today.","start":5,"answer":"させてもらいます","acceptedAnswers":["させてもらいます"],"distractors":[{"text":"させたもらいます","reason":"もらう follows the て-form."},{"text":"させてもらいません","reason":"This negates making use of the permission."},{"text":"させてもらうます","reason":"The polite form is もらいます."}],"promptKana":"きょうはそうたい＿＿＿。"}}},{"japanese":"一言言わせてもらいたい。","romaji":"Hitokoto iwasete moraitai.","german":"I'd like to take the liberty of saying a word."}],"notes":"Polite: ～させていただく. Very common in business Japanese.","related":["n4-saseru","n4-temorau","n4-sasetekudasai"]},
{"id":"n4-toiu","pattern":"～という","level":"N4","category":"Satzstrukturen","meaning":"called, named; that","explanation":"という: identifies or defines something, or introduces indirect speech.","formation":"Noun/Clause + という + Noun","examples":[{"japanese":"「桜」という漢字を知っていますか。","cloze":{"start":3,"answer":"という","quiz":{"level":"N4","japanese":"「桜」という漢字を知っていますか。","german":"Do you know the kanji called \"sakura\"?","start":3,"answer":"という","acceptedAnswers":["という","といった"],"distractors":[{"text":"をいう","reason":"The quoted name needs と."},{"text":"にいう","reason":"に does not replace the quotation particle here."},{"text":"というの","reason":"The relative structure modifies 漢字 without an extra の."}],"promptKana":"「さくら」＿＿＿かんじをしっていますか。"}},"romaji":"\"Sakura\" to iu kanji o shitteimasu ka.","german":"Do you know the kanji called \"sakura\"?"},{"japanese":"明日テストがあるということを聞いた。","cloze":{"start":8,"answer":"という"},"romaji":"Ashita tesuto ga aru to iu koto o kiita.","german":"I heard that there's a test tomorrow."}],"notes":"Colloquial: っていう. ～ということだ = that means.","related":["n4-tte","n3-to-ieba","n3-to-itta","n3-to-iu-no-wa"]},
{"id":"n4-you-to-suru","pattern":"～ようとする","level":"N4","category":"Verben","meaning":"to try to, to be about to","explanation":"ようとする: making an attempt or being just about to do something.","formation":"Verb (volitional form) + とする","examples":[{"japanese":"ドアを開けようとしたが開かなかった。","romaji":"Doa o akeyō to shita ga akanakatta.","german":"I tried to open the door, but it wouldn't open.","cloze":{"start":5,"answer":"ようとした","quiz":{"level":"N4","japanese":"ドアを開けようとしたが開かなかった。","german":"I tried to open the door, but it wouldn't open.","start":5,"answer":"ようとした","acceptedAnswers":["ようとした"],"distractors":[{"text":"るようとした","reason":"The intention uses 開けよう."},{"text":"ようをした","reason":"The attempt construction requires と."},{"text":"ようとしなかった","reason":"This negates the attempt."}],"promptKana":"ドアをあけ＿＿＿があかなかった。"}}},{"japanese":"出かけようとした時電話が鳴った。","romaji":"Dekakeyō to shita toki denwa ga natta.","german":"Just as I was about to go out, the phone rang."}],"notes":"～ようとしている = to be just about to.","related":["n4-volitional","te-miru","n4-you-to-omou"]},
{"id":"n4-tokini","pattern":"～時(に)","level":"N4","category":"Satzstrukturen","meaning":"when (point in time)","explanation":"時に: indicates the point in time when something happens.","formation":"Verb (辞書形/た形) + 時 / Noun + の時","examples":[{"japanese":"日本に行った時お寺を見ました。","romaji":"Nihon ni itta toki otera o mimashita.","german":"When I went to Japan, I saw temples.","cloze":{"start":6,"answer":"時","quiz":{"level":"N4","japanese":"日本に行った時お寺を見ました。","german":"When I went to Japan, I saw temples.","start":6,"answer":"時","acceptedAnswers":["時","際","時に"],"distractors":[{"text":"ながら","reason":"ながら requires the verb stem."},{"text":"前に","reason":"前に requires 行く here and means before the trip."},{"text":"てから","reason":"行ったてから is not a valid verb connection."}],"promptKana":"にほんにいった＿＿＿おてらをみました。"}}},{"japanese":"困った時は相談してください。","romaji":"Komatta toki wa sōdan shite kudasai.","german":"When you have a problem, please come and talk to us."}],"notes":"辞書形+時 = before you do it. た形+時 = after you have done it.","related":["n4-aida-ni","tara"]},
{"id":"n4-noni-purpose","pattern":"～のに (Zweck)","level":"N4","category":"Satzstrukturen","meaning":"in order to, for (purpose)","explanation":"のに expressing purpose: says what something is needed for.","formation":"Verb (辞書形) + のに + necessary/useful/etc.","examples":[{"japanese":"この本は勉強するのに役立つ。","romaji":"Kono hon wa benkyō suru noni yakudatsu.","german":"This book is useful for studying.","cloze":{"start":8,"answer":"のに","quiz":{"level":"N4","japanese":"この本は勉強するのに役立つ。","german":"This book is useful for studying.","start":8,"answer":"のに","acceptedAnswers":["のに","ために","ため"],"distractors":[{"text":"を","reason":"The verb clause first has to be nominalized."},{"text":"にの","reason":"The order is のに."},{"text":"なに","reason":"After the verb, なに does not express purpose here."}],"promptKana":"このほんはべんきょうする＿＿＿やくだつ。"}}},{"japanese":"日本語を覚えるのに時間がかかる。","romaji":"Nihongo o oboeru noni jikan ga kakaru.","german":"Learning Japanese takes time."}],"notes":"Don't confuse with ～のに (although). Here: purpose/use.","related":["noni","n4-tame-ni"]},
{"id":"n4-te-sumu","pattern":"～てすむ / ～ずにすむ","level":"N4","category":"Verben","meaning":"to be enough; to get out of having to","explanation":"てすむ: something is enough. ずにすむ/ないですむ: you get away without having to do it.","formation":"Verb (て) + すむ / Verb (ず) + にすむ","examples":[{"japanese":"薬を飲まずにすんだ。","romaji":"Kusuri o nomazu ni sunda.","german":"I got away without having to take medicine.","cloze":{"start":4,"answer":"ずにすんだ","quiz":{"level":"N4","japanese":"薬を飲まずにすんだ。","german":"I got away without having to take medicine.","start":4,"answer":"ずにすんだ","acceptedAnswers":["ずにすんだ","ないですんだ"],"distractors":[{"text":"ずにすむた","reason":"The past of 済む is すんだ."},{"text":"ずにすまなかった","reason":"This negates that taking it could be avoided."},{"text":"ずをすんだ","reason":"済む is connected with に here."}],"promptKana":"くすりをのま＿＿＿。"}}},{"japanese":"千円ですみました。","romaji":"Sen-en de sumimashita.","german":"A thousand yen was enough."}],"notes":"ないですむ = more casual than ずにすむ.","related":["n4-zu-ni","n2-zu-jimai"]},
{"id":"n4-te-shimau-casual","pattern":"～ちゃう / ～じゃう","level":"N4","category":"Verben","meaning":"colloquial ～てしまう","explanation":"ちゃう and じゃう: contracted forms of てしまう and でしまう.","formation":"Verb (て→ちゃう) / Verb (で→じゃう)","examples":[{"japanese":"全部食べちゃった。","romaji":"Zenbu tabechatta.","german":"I ate it all.","cloze":{"start":4,"answer":"ちゃった","quiz":{"level":"N4","japanese":"全部食べちゃった。","german":"I ate it all.","start":4,"answer":"ちゃった","acceptedAnswers":["ちゃった","てしまった"],"distractors":[{"text":"じゃった","reason":"食べてしまった becomes 食べちゃった, not 食べじゃった."},{"text":"ちゃうた","reason":"The past is ちゃった."},{"text":"ちゃわなかった","reason":"This negates eating it all."}],"promptKana":"ぜんぶたべ＿＿＿。"}}},{"japanese":"電車に忘れ物しちゃった。","romaji":"Densha ni wasuremono shichatta.","german":"I left something on the train."},{"japanese":"飲んじゃだめだよ。","romaji":"Nonja dame da yo.","german":"You mustn't drink that."}],"notes":"Very common in everyday speech. て→ちゃ, で→じゃ.","related":["te-shimau","n4-toku","n4-cha-ikenai"]},
{"id":"n4-dasu","pattern":"～出す","level":"N4","category":"Verben","meaning":"to suddenly start to","explanation":"出す as a suffix: the sudden start of an action.","formation":"Verb (ます-stem) + 出す","examples":[{"japanese":"急に雨が降り出した。","romaji":"Kyū ni ame ga furi dashita.","german":"Suddenly it started to rain.","cloze":{"start":6,"answer":"出した","quiz":{"level":"N4","japanese":"急に雨が降り出した。","german":"Suddenly it started to rain.","start":6,"answer":"出した","acceptedAnswers":["出した"],"distractors":[{"text":"終わった","reason":"This marks the end rather than the beginning."},{"text":"出さなかった","reason":"This negates the onset."},{"text":"出すた","reason":"This is not a past form."}],"promptKana":"きゅうにあめがふり＿＿＿。"}}},{"japanese":"赤ちゃんが泣き出した。","romaji":"Akachan ga naki dashita.","german":"The baby suddenly started crying."}],"notes":"Emphasizes the sudden start. Compare ～始める (start in general).","related":["n4-hajimeru"]},
{"id":"n4-wasureru","pattern":"～忘れる","level":"N4","category":"Verben","meaning":"to forget to do","explanation":"忘れる as a suffix: you forget to carry out an action.","formation":"Verb (ます-stem) + 忘れる","examples":[{"japanese":"鍵をかけ忘れた。","romaji":"Kagi o kake wasureta.","german":"I forgot to lock the door.","cloze":{"start":4,"answer":"忘れた","quiz":{"level":"N4","japanese":"鍵をかけ忘れた。","german":"I forgot to lock the door.","start":4,"answer":"忘れた","acceptedAnswers":["忘れた"],"distractors":[{"text":"忘れなかった","reason":"This negates the forgetting."},{"text":"忘れるた","reason":"This is not a past form."},{"text":"ます忘れた","reason":"ます is not inserted before 忘れた."}],"promptKana":"かぎをかけ＿＿＿。"}}},{"japanese":"薬を飲み忘れないでね。","romaji":"Kusuri o nomi wasurenaide ne.","german":"Don't forget to take your medicine."}],"notes":"言い忘れる (to forget to say), 買い忘れる (to forget to buy).","related":[]},
{"id":"n4-souni-suru","pattern":"～ふりをする","level":"N4","category":"Satzstrukturen","meaning":"to pretend","explanation":"ふりをする: to feign, to put on an act.","formation":"Verb (辞書形/ない形) + ふりをする / Noun + のふりをする","examples":[{"japanese":"知らないふりをした。","romaji":"Shiranai furi o shita.","german":"I pretended not to know.","cloze":{"start":4,"answer":"ふりをした","quiz":{"level":"N4","japanese":"知らないふりをした。","german":"I pretended not to know.","start":4,"answer":"ふりをした","acceptedAnswers":["ふりをした"],"distractors":[{"text":"ふりをしなかった","reason":"This negates the pretending."},{"text":"なふりをした","reason":"No な is inserted after the verb."},{"text":"ふりにした","reason":"The fixed expression for pretending is ふりをする."}],"promptKana":"しらない＿＿＿。"}}},{"japanese":"寝たふりをしている。","romaji":"Neta furi o shiteiru.","german":"He's pretending to be asleep."}],"notes":"Always deliberate pretending.","related":[]},
{"id":"n4-hazu-ga-nai","pattern":"～はずがない","level":"N4","category":"Satzstrukturen","meaning":"cannot possibly be","explanation":"はずがない: a strong denial of a possibility.","formation":"Verb/Adj (plain form) + はずがない","examples":[{"japanese":"彼がそんなことをするはずがない。","cloze":{"start":10,"answer":"はずがない","quiz":{"level":"N4","japanese":"彼がそんなことをするはずがない。","german":"There's no way he would do something like that.","start":10,"answer":"はずがない","acceptedAnswers":["はずがない"],"distractors":[{"text":"はずだ","reason":"This asserts an expectation rather than an impossibility."},{"text":"なはずがない","reason":"No な is inserted after the verb."},{"text":"はずをない","reason":"The negation uses が, not を."}],"promptKana":"かれがそんなことをする＿＿＿。"}},"romaji":"Kare ga sonna koto o suru hazu ga nai.","german":"There's no way he would do something like that."},{"japanese":"こんなに安いはずがない。","cloze":{"start":6,"answer":"はずがない"},"romaji":"Konna ni yasui hazu ga nai.","german":"It can't possibly be this cheap."}],"notes":"Stronger than ～ないだろう. Opposite: ～はずだ (should be).","related":["n4-hazu-da","n4-wake-da"]},
{"id":"n4-wake-ni-ikanai","pattern":"～わけにはいかない","level":"N3","category":"Satzstrukturen","meaning":"cannot very well, must not","explanation":"わけにはいかない: not possible for moral or social reasons.","formation":"Verb (辞書形) + わけにはいかない","examples":[{"japanese":"約束したから行かないわけにはいかない。","cloze":{"start":10,"answer":"わけにはいかない","quiz":{"level":"N3","japanese":"約束したから行かないわけにはいかない。","german":"I promised, so I can't very well not go.","start":10,"answer":"わけにはいかない","acceptedAnswers":["わけにはいかない","わけにいかない"],"distractors":[{"text":"わけにはいく","reason":"This would present not going as possible."},{"text":"なわけにはいかない","reason":"No な is inserted after the verb."},{"text":"わけをはいかない","reason":"The fixed construction uses に."}],"promptKana":"やくそくしたからいかない＿＿＿。"}},"romaji":"Yakusoku shita kara ikanai wake ni wa ikanai.","german":"I promised, so I can't very well not go."},{"japanese":"ここで諦めるわけにはいかない。","cloze":{"start":6,"answer":"わけにはいかない"},"romaji":"Koko de akirameru wake ni wa ikanai.","german":"I can't just give up here."}],"notes":"A social/moral impossibility, not a physical one.","related":["n4-wake-da","nakereba-naranai"]},
{"id":"n4-tara-dou","pattern":"～たらどう","level":"N4","category":"Satzstrukturen","meaning":"how about ...?","explanation":"たらどう: a casual suggestion or piece of advice.","formation":"Verb (たら) + どう(ですか)","examples":[{"japanese":"医者に行ったらどう？","cloze":{"start":5,"answer":"たらどう","quiz":{"level":"N4","japanese":"医者に行ったらどう？","german":"Why don't you go see a doctor?","start":5,"answer":"たらどう","acceptedAnswers":["たらどう"],"distractors":[{"text":"ればどう","reason":"行っれば is not a verb form."},{"text":"ますどう","reason":"行っます is not a verb form."},{"text":"たどう","reason":"The suggestion requires the conditional form たら."}],"promptKana":"いしゃにいっ＿＿＿？"}},"romaji":"Isha ni ittara dō?","german":"Why don't you go see a doctor?"},{"japanese":"もっと休んだらどうですか。","romaji":"Motto yasundara dō desu ka.","german":"How about getting more rest?"}],"notes":"Depending on the tone, it can also sound impatient.","related":["n4-ta-hou-ga-ii","tara","n3-tara-ii-ba-ii"]},
{"id":"n4-no-wa-da","pattern":"～のは～だ","level":"N4","category":"Satzstrukturen","meaning":"the reason is; it is ... that","explanation":"のは～だ/からだ: emphasizing or explaining the reason.","formation":"Clause + のは + Noun/Adj + だ/からだ","examples":[{"japanese":"遅れたのは電車のせいだ。","romaji":"Okureta no wa densha no sei da.","german":"The reason I was late was the train.","cloze":{"start":3,"answer":"のは","quiz":{"level":"N4","japanese":"遅れたのは電車のせいだ。","german":"The reason I was late was the train.","start":3,"answer":"のは","acceptedAnswers":["のは"],"distractors":[{"text":"を","reason":"を does not nominalize the clause as a topic."},{"text":"に","reason":"に does not nominalize the clause as a topic."},{"text":"なは","reason":"After the verb, なは is not a valid connection."}],"promptKana":"おくれた＿＿＿でんしゃのせいだ。"}}},{"japanese":"驚いたのは値段が高かったからだ。","romaji":"Odoroita no wa nedan ga takakatta kara da.","german":"The reason I was surprised was that the price was high."}],"notes":"Emphasizes the reason or the key element.","related":[]},
{"id":"n4-daroo","pattern":"～だろう / ～でしょう","level":"N4","category":"Satzstrukturen","meaning":"probably, presumably","explanation":"だろう (casual) and でしょう (polite): a supposition or expectation.","formation":"Verb/Adj/Noun + だろう/でしょう","examples":[{"japanese":"明日は晴れるでしょう。","cloze":{"start":6,"answer":"でしょう","quiz":{"level":"N4","japanese":"明日は晴れるでしょう。","german":"It will probably be sunny tomorrow.","start":6,"answer":"でしょう","acceptedAnswers":["でしょう","だろう"],"distractors":[{"text":"でした","reason":"The copula でした does not attach to a verb here."},{"text":"ます","reason":"ます is not attached to the dictionary form."},{"text":"なでしょう","reason":"No な is inserted after the verb."}],"promptKana":"あしたははれる＿＿＿。"}},"romaji":"Ashita wa hareru deshō.","german":"It will probably be sunny tomorrow."},{"japanese":"彼はもう帰っただろう。","cloze":{"start":7,"answer":"だろう"},"romaji":"Kare wa mō kaetta darō.","german":"He has probably gone home already."}],"notes":"でしょう? (with rising intonation) = right? / isn't it?","related":["kamoshirenai","n4-hazu-da","n4-kana-kashira"]},
{"id":"n3-ni-kanshite","pattern":"～に関して","level":"N3","category":"Partikel","meaning":"regarding, concerning","explanation":"に関して: the formal variant of ～について. Common in writing and reports.","formation":"Noun + に関して / に関する + Noun","examples":[{"japanese":"この件に関して質問があります。","cloze":{"start":3,"answer":"に関して","quiz":{"level":"N3","japanese":"この件に関して質問があります。","german":"I have a question regarding this matter.","start":3,"answer":"に関して","acceptedAnswers":["に関して","について","に関する"],"distractors":[{"text":"に比べて","reason":"This marks a comparison rather than the topic of the question."},{"text":"にとって","reason":"This marks a standard of value rather than the topic of the question."},{"text":"にかけて","reason":"This does not mark the topic of a question here."}]}},"romaji":"Kono ken ni kanshite shitsumon ga arimasu.","german":"I have a question regarding this matter."},{"japanese":"環境に関する問題が増えている。","romaji":"Kankyō ni kansuru mondai ga fueteiru.","german":"Environmental problems are increasing."}],"notes":"More formal than ～について. Before nouns: ～に関する.","related":["n4-ni-tsuite"]},
{"id":"n3-ni-kurabete","pattern":"～に比べて","level":"N3","category":"Partikel","meaning":"compared to","explanation":"に比べて: expresses a comparison between two things.","formation":"Noun + に比べて","examples":[{"japanese":"去年に比べて売上が伸びた。","cloze":{"start":2,"answer":"に比べて","quiz":{"level":"N3","japanese":"去年に比べて売上が伸びた。","german":"Compared to last year, sales have grown.","start":2,"answer":"に比べて","acceptedAnswers":["に比べて"],"distractors":[{"text":"に反して","reason":"This marks a contradiction rather than the comparison over time."},{"text":"について","reason":"This names a topic rather than the standard of comparison."},{"text":"にとって","reason":"A year is a standard of comparison here, not a standard of value."}]}},"romaji":"Kyonen ni kurabete uriage ga nobita.","german":"Compared to last year, sales have grown."},{"japanese":"東京に比べて大阪は物価が安い。","cloze":{"start":2,"answer":"に比べて"},"romaji":"Tōkyō ni kurabete Ōsaka wa bukka ga yasui.","german":"Compared to Tokyo, prices in Osaka are lower."}],"notes":"Similar to ～より, but more formal and explicit.","related":["n4-yori"]},
{"id":"n3-ni-motozuite","pattern":"～に基づいて","level":"N3","category":"Partikel","meaning":"based on, on the basis of","explanation":"に基づいて: something is done on the basis of facts or rules.","formation":"Noun + に基づいて / に基づく + Noun","examples":[{"japanese":"法律に基づいて判断する。","cloze":{"start":2,"answer":"に基づいて","quiz":{"level":"N3","japanese":"法律に基づいて判断する。","german":"Making a judgment on the basis of the law.","start":2,"answer":"に基づいて","acceptedAnswers":["に基づいて","に従って"],"distractors":[{"text":"に反して","reason":"This means against the law."},{"text":"を問わず","reason":"This means regardless of the law."},{"text":"について","reason":"This makes the law the subject matter rather than the basis for the judgment."}]}},"romaji":"Hōritsu ni motozuite handan suru.","german":"Making a judgment on the basis of the law."},{"japanese":"事実に基づいた映画です。","romaji":"Jijitsu ni motozuita eiga desu.","german":"It's a film based on true events."}],"notes":"Before nouns: ～に基づく/～に基づいた.","related":[]},
{"id":"n3-ni-oite","pattern":"～において","level":"N3","category":"Partikel","meaning":"in, at (formal)","explanation":"において: the formal variant of ～で (place/domain). Written language.","formation":"Noun + において / における + Noun","examples":[{"japanese":"会議は東京において行われた。","cloze":{"start":5,"answer":"において","quiz":{"level":"N3","japanese":"会議は東京において行われた。","german":"The conference was held in Tokyo.","start":5,"answer":"において","acceptedAnswers":["において","で"],"distractors":[{"text":"について","reason":"This makes Tokyo the topic of the conference rather than its venue."},{"text":"にとって","reason":"This does not name a venue."},{"text":"に代わって","reason":"This means instead of Tokyo, not in Tokyo."}]}},"romaji":"Kaigi wa Tōkyō ni oite okonawareta.","german":"The conference was held in Tokyo."},{"japanese":"現代社会における問題を考える。","romaji":"Gendai shakai ni okeru mondai o kangaeru.","german":"Thinking about problems in modern society."}],"notes":"Before nouns: ～における. Very formal/written.","related":["de"]},
{"id":"n3-ni-ojite","pattern":"～に応じて","level":"N3","category":"Partikel","meaning":"according to, depending on","explanation":"に応じて: adapting to circumstances or conditions.","formation":"Noun + に応じて / に応じた + Noun","examples":[{"japanese":"状況に応じて対応を変える。","cloze":{"start":2,"answer":"に応じて","quiz":{"level":"N3","japanese":"状況に応じて対応を変える。","german":"Changing your response depending on the situation.","start":2,"answer":"に応じて","acceptedAnswers":["に応じて"],"distractors":[{"text":"に反して","reason":"This means contrary to the situation rather than in line with it."},{"text":"を問わず","reason":"This means regardless of the situation rather than depending on it."},{"text":"に関する","reason":"状況に関する対応 means a response concerning the situation, not the required dependence of how the response changes."}]}},"romaji":"Jōkyō ni ōjite taiō o kaeru.","german":"Changing your response depending on the situation."},{"japanese":"能力に応じた仕事を与える。","romaji":"Nōryoku ni ōjita shigoto o ataeru.","german":"Giving work that matches someone's abilities."}],"notes":"Similar: ～に合わせて, ～次第で.","related":["n3-shidai"]},
{"id":"n3-ni-tomonatte","pattern":"～に伴って","level":"N2","category":"Partikel","meaning":"with, along with","explanation":"に伴って: a change that takes place alongside another one.","formation":"Noun + に伴って / に伴い / に伴う + Noun","examples":[{"japanese":"人口増加に伴って環境問題が深刻化した。","cloze":{"start":4,"answer":"に伴って","quiz":{"level":"N2","japanese":"人口増加に伴って環境問題が深刻化した。","german":"Along with population growth, environmental problems became more serious.","start":4,"answer":"に伴って","acceptedAnswers":["に伴って","につれて","とともに"],"distractors":[{"text":"に反して","reason":"This means against the population growth."},{"text":"を問わず","reason":"This claims independence rather than an accompanying change."},{"text":"にとって","reason":"This names a standard of value rather than a parallel development."}]}},"romaji":"Jinkō zōka ni tomonatte kankyō mondai ga shinkokuka shita.","german":"Along with population growth, environmental problems became more serious."},{"japanese":"経済成長に伴う変化が見られる。","romaji":"Keizai seichō ni tomonau henka ga mirareru.","german":"Changes that come with economic growth can be seen."}],"notes":"Formal. Similar: ～につれて, ～とともに.","related":["n3-ni-tsurete"]},
{"id":"n3-o-hajime","pattern":"～をはじめ","level":"N3","category":"Partikel","meaning":"starting with, first and foremost","explanation":"をはじめ: highlights a main example and implies there are more.","formation":"Noun + をはじめ(として)","examples":[{"japanese":"日本をはじめアジアの国々を訪れた。","cloze":{"start":2,"answer":"をはじめ","quiz":{"level":"N3","japanese":"日本をはじめアジアの国々を訪れた。","german":"I visited countries in Asia, starting with Japan.","start":2,"answer":"をはじめ","acceptedAnswers":["をはじめ"],"distractors":[{"text":"にとって","reason":"This does not express a highlighted start of a list."},{"text":"に代わって","reason":"This means instead of Japan rather than including Japan."},{"text":"を除いて","reason":"This excludes Japan, even though it was explicitly visited."}]}},"romaji":"Nihon o hajime Ajia no kuniguni o otozureta.","german":"I visited countries in Asia, starting with Japan."},{"japanese":"社長をはじめ社員全員が参加した。","cloze":{"start":2,"answer":"をはじめ"},"romaji":"Shachō o hajime shain zen'in ga sanka shita.","german":"All the employees took part, starting with the company president."}],"notes":"Formal. The item named with をはじめ is the most important example.","related":["n4-nado","n2-wo-hajime-to-suru"]},
{"id":"n3-o-tsujite","pattern":"～を通じて / ～を通して","level":"N3","category":"Partikel","meaning":"through, via; throughout (means/period)","explanation":"を通じて/を通して: via a medium or throughout a period of time.","formation":"Noun + を通じて/を通して","examples":[{"japanese":"インターネットを通じて世界とつながる。","cloze":{"start":7,"answer":"を通じて","quiz":{"level":"N3","japanese":"インターネットを通じて世界とつながる。","german":"Connecting with the world through the internet.","start":7,"answer":"を通じて","acceptedAnswers":["を通じて","を通して","で"],"distractors":[{"text":"を避けて","reason":"This means avoiding the internet."},{"text":"とは無関係に","reason":"This means regardless of the internet."},{"text":"に反して","reason":"This means against the internet rather than by means of it."}]}},"romaji":"Intānetto o tsūjite sekai to tsunagaru.","german":"Connecting with the world through the internet."},{"japanese":"一年を通して暖かい気候だ。","cloze":{"start":2,"answer":"を通して"},"romaji":"Ichinen o tōshite atatakai kikō da.","german":"The climate is warm all year round."},{"japanese":"インターネットを通じて世界中の人と交流できる。","romaji":"Intānetto wo tsūjite sekaijū no hito to kōryū dekiru.","german":"Through the internet, you can interact with people all over the world."},{"japanese":"一年を通じて温暖な気候だ。","romaji":"Ichinen wo tsūjite ondan na kikō da.","german":"The climate is mild all year round."},{"japanese":"ボランティア活動を通して、多くのことを学んだ。","romaji":"Borantia katsudō wo tōshite, ōku no koto wo mananda.","german":"I learned a lot through volunteer work."},{"japanese":"一年を通して暖かい地域に住みたい。","romaji":"Ichinen wo tōshite atatakai chiiki ni sumitai.","german":"I want to live in an area that is warm all year round."}],"notes":"を通じて = more abstract/a medium. を通して = also concrete/a period of time.","related":["n4-ni-yotte","n3-ni-watatte"],"legacyIds":["n2-wo-tsujite","n2-wo-toshite"]},
{"id":"n3-o-chushin-ni","pattern":"～を中心に","level":"N3","category":"Partikel","meaning":"with ... at the center, focusing on","explanation":"を中心に: something is at the center or in focus.","formation":"Noun + を中心に(して)","examples":[{"japanese":"駅を中心に町が発展した。","cloze":{"start":1,"answer":"を中心に","quiz":{"level":"N3","japanese":"駅を中心に町が発展した。","german":"The town developed around the station.","start":1,"answer":"を中心に","acceptedAnswers":["を中心に"],"distractors":[{"text":"から遠く離れて","reason":"This moves the development far away from the station."},{"text":"を中心な","reason":"The adverbial connection requires に."},{"text":"が中心を","reason":"This is not an adverbial connection to 発展した."}]}},"romaji":"Eki o chūshin ni machi ga hatten shita.","german":"The town developed around the station."},{"japanese":"文法を中心に勉強している。","cloze":{"start":2,"answer":"を中心に"},"romaji":"Bunpō o chūshin ni benkyō shiteiru.","german":"I'm studying with a focus on grammar."}],"notes":"Also: ～を中心として (more formal).","related":["n2-wo-hajime-to-suru","n2-wo-to-shite"]},
{"id":"n3-ni-tsurete","pattern":"～につれて","level":"N3","category":"Partikel","meaning":"as; the more ..., the more (proportional)","explanation":"につれて: two changes happen in parallel.","formation":"Verb (辞書形) + につれて / Noun + につれて","examples":[{"japanese":"年を取るにつれて体力が落ちる。","cloze":{"start":4,"answer":"につれて","quiz":{"level":"N3","japanese":"年を取るにつれて体力が落ちる。","german":"As you get older, your physical strength declines.","start":4,"answer":"につれて","acceptedAnswers":["につれて","に従って"],"distractors":[{"text":"につれる","reason":"The fixed construction for change ends in て here."},{"text":"をつれて","reason":"を連れて means taking someone along and does not connect to 年を取る."},{"text":"ながら","reason":"ながら requires the stem, not 年を取る."}]}},"romaji":"Toshi o toru ni tsurete tairyoku ga ochiru.","german":"As you get older, your physical strength declines."},{"japanese":"時間が経つにつれて忘れてしまう。","cloze":{"start":5,"answer":"につれて"},"romaji":"Jikan ga tatsu ni tsurete wasurete shimau.","german":"As time passes, you forget."}],"notes":"Similar: ～に伴って (more formal), ～に従って (following a rule).","related":["n3-ni-tomonatte","n3-ni-shitagatte","n2-ni-tsuke"]},
{"id":"n3-ni-shitagatte","pattern":"～に従って","level":"N3","category":"Partikel","meaning":"in accordance with, following; as ... (proportional change)","explanation":"に従って: following a rule/instruction, or a proportional change.","formation":"Noun + に従って / Verb (辞書形) + に従って","examples":[{"japanese":"指示に従って作業してください。","cloze":{"start":2,"answer":"に従って","quiz":{"level":"N3","japanese":"指示に従って作業してください。","german":"Please work according to the instructions.","start":2,"answer":"に従って","acceptedAnswers":["に従って","に沿って"],"distractors":[{"text":"に反して","reason":"This would mean acting against the instructions."},{"text":"を無視して","reason":"This would mean ignoring the instructions."},{"text":"に従うて","reason":"The て-form of 従う is 従って."}]}},"romaji":"Shiji ni shitagatte sagyō shite kudasai.","german":"Please work according to the instructions."},{"japanese":"高度が上がるに従って気温が下がる。","cloze":{"start":6,"answer":"に従って"},"romaji":"Kōdo ga agaru ni shitagatte kion ga sagaru.","german":"As the altitude rises, the temperature drops."}],"notes":"Rule: ～に従って + action. Proportional: like ～につれて.","related":["n3-ni-tsurete"]},
{"id":"n3-ni-watatte","pattern":"～にわたって","level":"N2","category":"Partikel","meaning":"over, throughout, spanning","explanation":"にわたって: expresses that something covers a wide area or a long period.","formation":"Noun + にわたって / にわたる + Noun","examples":[{"japanese":"三日間にわたって会議が行われた。","cloze":{"start":3,"answer":"にわたって","quiz":{"level":"N2","japanese":"三日間にわたって会議が行われた。","german":"The conference was held over three days.","start":3,"answer":"にわたって","acceptedAnswers":["にわたって"],"distractors":[{"text":"の前に","reason":"This means before the period."},{"text":"の後に","reason":"This means after the period."},{"text":"にわたるて","reason":"The て-form of わたる is わたって."}]}},"romaji":"Mikkakan ni watatte kaigi ga okonawareta.","german":"The conference was held over three days."},{"japanese":"広い範囲にわたる調査を行った。","romaji":"Hiroi han'i ni wataru chōsa o okonatta.","german":"A survey covering a wide area was carried out."}],"notes":"Before nouns: ～にわたる. Emphasizes extent in time or space.","related":["n3-ni-kakete"]},
{"id":"n3-ni-kakete","pattern":"～にかけて","level":"N3","category":"Partikel","meaning":"from ... to, through (period/area)","explanation":"にかけて: from one point to another, usually with ～から.","formation":"Noun + から + Noun + にかけて","examples":[{"japanese":"午後から夕方にかけて雨が降るでしょう。","cloze":{"start":6,"answer":"にかけて","quiz":{"level":"N3","japanese":"午後から夕方にかけて雨が降るでしょう。","german":"It will probably rain from the afternoon into the evening.","start":6,"answer":"にかけて","acceptedAnswers":["にかけて","まで"],"distractors":[{"text":"の後だけ","reason":"This means only afterwards instead of through to the evening."},{"text":"にかけるて","reason":"The て-form of かける is かけて."},{"text":"をかけて","reason":"をかけて does not express a time span starting from 午後から here."}]}},"romaji":"Gogo kara yūgata ni kakete ame ga furu deshō.","german":"It will probably rain from the afternoon into the evening."},{"japanese":"関東から東北にかけて地震があった。","cloze":{"start":6,"answer":"にかけて"},"romaji":"Kantō kara Tōhoku ni kakete jishin ga atta.","german":"There was an earthquake from Kantō to Tōhoku."}],"notes":"Often with ～から: AからBにかけて = from A to B.","related":["n3-ni-watatte"]},
{"id":"n3-muke","pattern":"～向け","level":"N3","category":"Partikel","meaning":"for, aimed at (target group)","explanation":"向け: indicates the target group something is intended for.","formation":"Noun + 向け(の) + Noun","examples":[{"japanese":"子供向けの番組が多い。","cloze":{"start":2,"answer":"向け","quiz":{"level":"N3","japanese":"子供向けの番組が多い。","german":"There are a lot of programs for children.","start":2,"answer":"向け","acceptedAnswers":["向け","向き"],"distractors":[{"text":"向ける","reason":"向けるの is not an attributive target-group marker here."},{"text":"向けに","reason":"No additional adverbial ending に fits before の番組."},{"text":"を向けた","reason":"子供を向けた would mean pointing the children somewhere, not aiming programs at them."}]}},"romaji":"Kodomo muke no bangumi ga ōi.","german":"There are a lot of programs for children."},{"japanese":"外国人向けの日本語教材です。","cloze":{"start":3,"answer":"向け"},"romaji":"Gaikokujin muke no nihongo kyōzai desu.","german":"This is Japanese learning material for foreigners."}],"notes":"向け = target group. 向き = suitable for (n3-muki).","related":["n3-muki","n2-ni-mukete"]},
{"id":"n3-muki","pattern":"～向き","level":"N3","category":"Partikel","meaning":"suitable for, suited to","explanation":"向き: expresses that something is suitable for a certain group.","formation":"Noun + 向き(の) + Noun","examples":[{"japanese":"この本は初心者向きだ。","cloze":{"start":7,"answer":"向き","quiz":{"level":"N3","japanese":"この本は初心者向きだ。","german":"This book is suitable for beginners.","start":7,"answer":"向き","acceptedAnswers":["向き","向け"],"distractors":[{"text":"向きに","reason":"An adverbial ending does not fit directly before だ."},{"text":"向くの","reason":"This is not a noun-like expression of suitability here."},{"text":"を向く","reason":"初心者を向くだ is not a fitting sentence ending."}]}},"romaji":"Kono hon wa shoshinsha muki da.","german":"This book is suitable for beginners."},{"japanese":"家族向きのレストランを探している。","cloze":{"start":2,"answer":"向き"},"romaji":"Kazoku muki no resutoran o sagashiteiru.","german":"I'm looking for a family-friendly restaurant."}],"notes":"向き = suitable. 向け = aimed at.","related":["n3-muke"]},
{"id":"n3-zaruwoenai","pattern":"～ざるを得ない","level":"N2","category":"Verben","meaning":"cannot help but, have no choice but to","explanation":"ざるを得ない: you have no choice but to do something.","formation":"Verb (ない-stem) + ざるを得ない","examples":[{"japanese":"この条件を受け入れざるを得ない。","cloze":{"start":9,"answer":"ざるを得ない","quiz":{"level":"N2","japanese":"この条件を受け入れざるを得ない。","german":"I have no choice but to accept these conditions.","start":9,"answer":"ざるを得ない","acceptedAnswers":["ざるを得ない","なければならない","ざるをえない"],"distractors":[{"text":"ざるを得る","reason":"The obligation construction needs the negative 得ない."},{"text":"ざるが得ない","reason":"The set phrase requires を."},{"text":"ないほうがいい","reason":"This advises against accepting."}]}},"romaji":"Kono jōken o ukeirezaru o enai.","german":"I have no choice but to accept these conditions."},{"japanese":"事情があって辞めざるを得なかった。","romaji":"Jijō ga atte yamezaru o enakatta.","german":"Due to circumstances, I had no choice but to quit."}],"notes":"する→せざるを得ない. Formal. Similar: ～ないわけにはいかない.","related":["nakereba-naranai","n4-wake-ni-ikanai","n4-shika-nai-option","n2-neba-naranai"]},
{"id":"n3-nuku","pattern":"～抜く","level":"N3","category":"Verben","meaning":"to see through to the end, to do thoroughly","explanation":"抜く as a suffix: carrying a difficult action through to completion.","formation":"Verb (ます-stem) + 抜く","examples":[{"japanese":"最後まで走り抜いた。","romaji":"Saigo made hashiri nuita.","german":"I ran all the way to the end.","cloze":{"start":6,"answer":"抜いた","quiz":{"level":"N3","japanese":"最後まで走り抜いた。","german":"I ran all the way to the end.","start":6,"answer":"抜いた","acceptedAnswers":["抜いた"],"distractors":[{"text":"抜かなかった","reason":"This negates the persevering."},{"text":"抜くた","reason":"This is not a past form."},{"text":"ます抜いた","reason":"ます does not go between the verbs."}]}}},{"japanese":"困難を乗り越え、やり抜いた。","romaji":"Konnan o norikoe, yarinuita.","german":"I overcame the difficulties and saw it through."}],"notes":"考え抜く (to think through thoroughly), 悩み抜く (to agonize at length).","related":["n2-kiru","n4-tsuzukeru"]},
{"id":"n3-ppanashi","pattern":"～っぱなし","level":"N3","category":"Verben","meaning":"leaving something as it is (unchanged)","explanation":"っぱなし: a state stays unchanged, often with a negative connotation.","formation":"Verb (ます-stem) + っぱなし","examples":[{"japanese":"ドアを開けっぱなしにしないで。","cloze":{"start":5,"answer":"っぱなし","quiz":{"level":"N3","japanese":"ドアを開けっぱなしにしないで。","german":"Don't leave the door open.","start":5,"answer":"っぱなし","acceptedAnswers":["っぱなし"],"distractors":[{"text":"っぱなしな","reason":"No additional な fits before にしないで."},{"text":"っぱなす","reason":"This is not the noun for the state left as it is here."},{"text":"っぱなしを","reason":"The construction requires っぱなしにする."}]}},"romaji":"Doa o akeppanashi ni shinaide.","german":"Don't leave the door open."},{"japanese":"テレビをつけっぱなしで寝た。","cloze":{"start":6,"answer":"っぱなし"},"romaji":"Terebi o tsukeppanashi de neta.","german":"I fell asleep with the TV on."}],"notes":"Often critical: 出しっぱなし (left out), 立ちっぱなし (standing the whole time).","related":["n4-mama"]},
{"id":"n3-koto-naku","pattern":"～ことなく","level":"N3","category":"Verben","meaning":"without (doing) (formal)","explanation":"ことなく: formal variant of ～ないで/～ずに.","formation":"Verb (辞書形) + ことなく","examples":[{"japanese":"諦めることなく努力し続けた。","cloze":{"start":3,"answer":"ことなく","quiz":{"level":"N3","japanese":"諦めることなく努力し続けた。","german":"I kept making an effort without giving up.","start":3,"answer":"ことなく","acceptedAnswers":["ことなく"],"distractors":[{"text":"ことをなく","reason":"The adverbial phrase does not use を."},{"text":"なことなく","reason":"No な is inserted after the verb."},{"text":"ことなしを","reason":"を does not attach an accompanying circumstance here."}]}},"romaji":"Akirameru koto naku doryoku shi tsuzuketa.","german":"I kept making an effort without giving up."},{"japanese":"一度も休むことなく働いた。","cloze":{"start":5,"answer":"ことなく"},"romaji":"Ichido mo yasumu koto naku hataraita.","german":"I worked without taking a single break."}],"notes":"More formal than ～ないで/～ずに.","related":["n4-zu-ni"]},
{"id":"n3-te-tamaranai","pattern":"～てたまらない","level":"N3","category":"Verben","meaning":"unbearably, extremely (feeling)","explanation":"てたまらない: a feeling or state is so strong that you can hardly bear it.","formation":"Verb (て) + たまらない / い-adj. (くて) + たまらない","examples":[{"japanese":"暑くてたまらない。","cloze":{"start":2,"answer":"てたまらない","quiz":{"level":"N3","japanese":"暑くてたまらない。","german":"It's unbearably hot.","start":2,"answer":"てたまらない","acceptedAnswers":["てたまらない","てならない","てしかたがない"],"distractors":[{"text":"たたまらない","reason":"After 暑く, the て-connection is required."},{"text":"てたまるない","reason":"The negative form is たまらない."},{"text":"てたまらないだ","reason":"No だ follows the negative form."}]}},"romaji":"Atsukute tamaranai.","german":"It's unbearably hot."},{"japanese":"会いたくてたまらない。","cloze":{"start":4,"answer":"てたまらない"},"romaji":"Aitakute tamaranai.","german":"I want to see you so badly I can hardly stand it."}],"notes":"Similar: ～てしかたがない, ～てならない. All = an unbearable feeling.","related":["n3-te-naranai","n3-te-shikata-ga-nai"]},
{"id":"n3-te-naranai","pattern":"～てならない","level":"N3","category":"Verben","meaning":"can't help (feeling)","explanation":"てならない: an involuntary feeling that you cannot control.","formation":"Verb (て) + ならない / い-adj. (くて) + ならない","examples":[{"japanese":"彼のことが心配でならない。","romaji":"Kare no koto ga shinpai de naranai.","german":"I can't help worrying about him.","cloze":{"start":7,"answer":"でならない","quiz":{"level":"N3","japanese":"彼のことが心配でならない。","german":"I can't help worrying about him.","start":7,"answer":"でならない","acceptedAnswers":["でならない","でたまらない","でしかたがない"],"distractors":[{"text":"てならない","reason":"心配 is nominal/adjectival and connects with で here."},{"text":"でなるない","reason":"The negative form is ならない."},{"text":"でならないだ","reason":"No だ follows the negative form."}]}}},{"japanese":"残念でならない。","romaji":"Zannen de naranai.","german":"It's deeply regrettable."}],"notes":"More formal than ～てたまらない. Used mainly for emotional feelings.","related":["n3-te-tamaranai","n2-te-wa-naranai"]},
{"id":"n3-te-shikata-ga-nai","pattern":"～てしかたがない","level":"N3","category":"Verben","meaning":"can't help it (feeling)","explanation":"てしかたがない/てしょうがない: a feeling is so strong that you can't do anything about it.","formation":"Verb (て) + しかたがない / い-adj. (くて) + しかたがない","examples":[{"japanese":"眠くてしかたがない。","cloze":{"start":2,"answer":"てしかたがない","quiz":{"level":"N3","japanese":"眠くてしかたがない。","german":"I'm so sleepy I can't help it.","start":2,"answer":"てしかたがない","acceptedAnswers":["てしかたがない","て仕方がない","てたまらない","てならない"],"distractors":[{"text":"てしかたをない","reason":"ない requires が here, not を."},{"text":"たしかたがない","reason":"眠く requires the て-connection."},{"text":"てしかたがある","reason":"This is not the set phrase for irresistible sleepiness."}]}},"romaji":"Nemukute shikata ga nai.","german":"I'm so sleepy I can't help it."},{"japanese":"面白くてしょうがない。","romaji":"Omoshirokute shō ga nai.","german":"It's so much fun I can't stop."}],"notes":"しょうがない = more informal. Similar: ～てたまらない, ～てならない.","related":["n3-te-tamaranai","n3-te-naranai"]},
{"id":"n3-kke","pattern":"～っけ","level":"N3","category":"Verben","meaning":"was it ...? (trying to remember)","explanation":"っけ: you are trying to remember something or checking again.","formation":"Verb/adj./noun (た形/だ) + っけ","examples":[{"japanese":"明日は何曜日だっけ？","cloze":{"start":7,"answer":"っけ","quiz":{"level":"N3","japanese":"明日は何曜日だっけ？","german":"What day is it tomorrow again?","start":7,"answer":"っけ","acceptedAnswers":["っけ"],"distractors":[{"text":"を","reason":"を does not form a recollecting question here."},{"text":"へ","reason":"へ does not form a recollecting question here."},{"text":"ます","reason":"だます is not a sentence-final form."}]}},"romaji":"Ashita wa nan'yōbi dakke?","german":"What day is it tomorrow again?"},{"japanese":"あの人の名前は何だっけ。","cloze":{"start":9,"answer":"っけ"},"romaji":"Ano hito no namae wa nan dakke.","german":"What was that person's name again?"}],"notes":"Informal. Expresses that you have forgotten something and want to recall it.","related":[]},
{"id":"n3-te-irai","pattern":"～て以来","level":"N3","category":"Verben","meaning":"since (an event)","explanation":"て以来: since a certain event, with the state continuing.","formation":"Verb (て-form) + 以来","examples":[{"japanese":"日本に来て以来、毎日日本語を使っている。","cloze":{"start":4,"answer":"て以来","quiz":{"level":"N3","japanese":"日本に来て以来、毎日日本語を使っている。","german":"Since coming to Japan, I've been using Japanese every day.","start":4,"answer":"て以来","acceptedAnswers":["て以来"],"distractors":[{"text":"た以来","reason":"The time expression requires 来て以来."},{"text":"ます以来","reason":"以来 does not attach to ます here."},{"text":"て以前","reason":"This means before rather than since arriving."}]}},"romaji":"Nihon ni kite irai, mainichi nihongo o tsukatte iru.","german":"Since coming to Japan, I've been using Japanese every day."},{"japanese":"卒業して以来、彼に会っていない。","cloze":{"start":3,"answer":"て以来"},"romaji":"Sotsugyō shite irai, kare ni atte inai.","german":"I haven't seen him since graduating."}],"notes":"More formal than ～てから. The state after the event continues.","related":["n4-ato-de"]},
{"id":"n3-tsutsu","pattern":"～つつ","level":"N3","category":"Verben","meaning":"while; although (formal)","explanation":"つつ: formal variant of ～ながら (at the same time) or ～のに (although).","formation":"Verb (ます-stem) + つつ","examples":[{"japanese":"悪いと思いつつ、つい食べてしまう。","cloze":{"start":5,"answer":"つつ","quiz":{"level":"N3","japanese":"悪いと思いつつ、つい食べてしまう。","german":"Even though I know it's bad, I end up eating it anyway.","start":5,"answer":"つつ","acceptedAnswers":["つつ","ながら"],"distractors":[{"text":"たら","reason":"思いたら is not a verb form."},{"text":"ても","reason":"思いても is not the て-form of 思う."},{"text":"ないで","reason":"思いないで is not a negative form."}]}},"romaji":"Warui to omoi tsutsu, tsui tabete shimau.","german":"Even though I know it's bad, I end up eating it anyway."},{"japanese":"景色を楽しみつつ散歩した。","cloze":{"start":6,"answer":"つつ"},"romaji":"Keshiki o tanoshimi tsutsu sanpo shita.","german":"I took a walk while enjoying the scenery."}],"notes":"～つつも = although. ～つつある = to be in the process of.","related":["nagara","n3-tsutsu-aru"]},
{"id":"n3-tsutsu-aru","pattern":"～つつある","level":"N3","category":"Verben","meaning":"to be in the process of, to be gradually changing","explanation":"つつある: a gradual change is under way.","formation":"Verb (ます-stem) + つつある","examples":[{"japanese":"状況は改善しつつある。","cloze":{"start":6,"answer":"つつある","quiz":{"level":"N3","japanese":"状況は改善しつつある。","german":"The situation is improving.","start":6,"answer":"つつある","acceptedAnswers":["つつある"],"distractors":[{"text":"つつない","reason":"The fixed progressive form is つつある."},{"text":"つつあるだ","reason":"No だ follows ある."},{"text":"るつつある","reason":"つつ attaches to 改善し, not to 改善する."}]}},"romaji":"Jōkyō wa kaizen shitsutsu aru.","german":"The situation is improving."},{"japanese":"この文化は消えつつある。","cloze":{"start":7,"answer":"つつある"},"romaji":"Kono bunka wa kietsutsu aru.","german":"This culture is disappearing."}],"notes":"Formal/written. Similar: ～ている (process of change).","related":["n3-tsutsu","te-iru"]},
{"id":"n3-gimi","pattern":"～気味","level":"N3","category":"Adjektive","meaning":"slightly, a bit, -ish","explanation":"気味 (ぎみ): a slight condition or tendency, usually negative.","formation":"Verb (ます-stem) + 気味 / Noun + 気味","examples":[{"japanese":"最近太り気味だ。","cloze":{"start":4,"answer":"気味","quiz":{"level":"N3","japanese":"最近太り気味だ。","german":"I've been putting on a bit of weight lately.","start":4,"answer":"気味","acceptedAnswers":["気味"],"distractors":[{"text":"気味な","reason":"No additional な goes before だ."},{"text":"気味に","reason":"An adverbial ending does not fit directly before だ."},{"text":"気味を","reason":"を does not connect to the copula here."}]}},"romaji":"Saikin futori gimi da.","german":"I've been putting on a bit of weight lately."},{"japanese":"風邪気味で体がだるい。","cloze":{"start":2,"answer":"気味"},"romaji":"Kaze gimi de karada ga darui.","german":"I have a slight cold and feel sluggish."}],"notes":"Usually a slightly negative tendency. Behaves like a な-adjective: ～気味の + noun.","related":["n4-gachi"]},
{"id":"n3-darake","pattern":"～だらけ","level":"N3","category":"Adjektive","meaning":"full of, covered with (negative)","explanation":"だらけ: covered with or full of something, usually with a negative connotation.","formation":"Noun + だらけ","examples":[{"japanese":"部屋がゴミだらけだ。","cloze":{"start":5,"answer":"だらけ","quiz":{"level":"N3","japanese":"部屋がゴミだらけだ。","german":"The room is full of trash.","start":5,"answer":"だらけ","acceptedAnswers":["だらけ"],"distractors":[{"text":"だらけな","reason":"No additional な goes before だ."},{"text":"だらけに","reason":"に does not form a predicate ending here."},{"text":"だらけを","reason":"を does not connect to the copula here."}]}},"romaji":"Heya ga gomi darake da.","german":"The room is full of trash."},{"japanese":"この作文は間違いだらけだ。","cloze":{"start":8,"answer":"だらけ"},"romaji":"Kono sakubun wa machigai darake da.","german":"This essay is full of mistakes."}],"notes":"Negative: 泥だらけ (covered in mud), 傷だらけ (covered in scratches).","related":[]},
{"id":"n3-buri","pattern":"～ぶり","level":"N3","category":"Adjektive","meaning":"manner, way of; for the first time in (a period)","explanation":"ぶり has two meanings: 1) the way something is done, 2) again after a long time.","formation":"Verb (ます-stem) + ぶり / Time period + ぶり","examples":[{"japanese":"三年ぶりに日本に行った。","cloze":{"start":2,"answer":"ぶり","quiz":{"level":"N3","japanese":"三年ぶりに日本に行った。","german":"I went to Japan for the first time in three years.","start":2,"answer":"ぶり","acceptedAnswers":["ぶり"],"distractors":[{"text":"前","reason":"This means three years ago instead of again after three years."},{"text":"後","reason":"This means after three years without expressing that it happened again."},{"text":"ずつ","reason":"This distributes amounts per three years instead of naming the gap before it happened again."}]}},"romaji":"Sannen buri ni Nihon ni itta.","german":"I went to Japan for the first time in three years."},{"japanese":"彼の仕事ぶりは素晴らしい。","cloze":{"start":4,"answer":"ぶり"},"romaji":"Kare no shigoto-buri wa subarashii.","german":"His way of working is wonderful."}],"notes":"久しぶり = it's been a long time. ～ぶりに = for the first time in.","related":[]},
{"id":"n3-teki","pattern":"～的","level":"N3","category":"Adjektive","meaning":"-ic, -al, -like","explanation":"的 (てき): turns nouns into な-adjectives, much like the English suffixes '-ic' or '-al'.","formation":"Noun + 的(な/に)","examples":[{"japanese":"日本的な考え方だ。","cloze":{"start":2,"answer":"的","quiz":{"level":"N3","japanese":"日本的な考え方だ。","german":"That's a Japanese way of thinking.","start":2,"answer":"的","acceptedAnswers":["的"],"distractors":[{"text":"的に","reason":"に must not be added before な考え方."},{"text":"的の","reason":"The attributive connection uses な."},{"text":"的だ","reason":"だ does not go before な考え方 here."}]}},"romaji":"Nihon-teki na kangaekata da.","german":"That's a Japanese way of thinking."},{"japanese":"具体的に説明してください。","cloze":{"start":2,"answer":"的"},"romaji":"Gutai-teki ni setsumei shite kudasai.","german":"Please explain it concretely."},{"japanese":"積極的に参加する。","cloze":{"start":2,"answer":"的"},"romaji":"Sekkyoku-teki ni sanka suru.","german":"I take part actively."}],"notes":"Very productive: 国際的 (international), 一般的 (general), 基本的 (basic).","related":["n2-jou"]},
{"id":"n3-kurai-gurai","pattern":"～くらい / ～ぐらい","level":"N3","category":"Adjektive","meaning":"about, around; so ... that","explanation":"くらい/ぐらい: indicates an extent or expresses 'about'.","formation":"Verb/adj. + くらい / Number + くらい","examples":[{"japanese":"泣きたいくらい悔しい。","cloze":{"start":4,"answer":"くらい","quiz":{"level":"N3","japanese":"泣きたいくらい悔しい。","german":"I'm so frustrated I could cry.","start":4,"answer":"くらい","acceptedAnswers":["くらい","ぐらい","ほど"],"distractors":[{"text":"ながら","reason":"ながら does not attach to たい."},{"text":"から","reason":"This makes the wish to cry the reason instead of the degree of frustration."},{"text":"すぎて","reason":"泣きたいすぎて is not a correct connection."}]}},"romaji":"Nakitai kurai kuyashii.","german":"I'm so frustrated I could cry."},{"japanese":"三十分くらい待った。","cloze":{"start":3,"answer":"くらい"},"romaji":"Sanjuppun kurai matta.","german":"I waited about thirty minutes."}],"notes":"As extent: ～くらい = so much that. As an estimate: ～くらい = about.","related":["n4-hodo-p","n5-goro","n2-kurai-nara"]},
{"id":"n3-wari-ni","pattern":"～割に(は)","level":"N3","category":"Adjektive","meaning":"considering, for (relative to)","explanation":"割に: the result does not match what you would expect.","formation":"Verb/adj. + 割に / Noun + の割に","examples":[{"japanese":"この店は値段の割においしい。","romaji":"Kono mise wa nedan no wari ni oishii.","german":"This restaurant is good for the price.","cloze":{"start":7,"answer":"割に","quiz":{"level":"N3","japanese":"この店は値段の割においしい。","german":"This restaurant is good for the price.","start":7,"answer":"割に","acceptedAnswers":["割に"],"distractors":[{"text":"割の","reason":"The adverbial evaluation needs に."},{"text":"ためな","reason":"This is not an adverbial evaluation of the price."},{"text":"前に","reason":"This does not express a price-quality comparison here."}]}}},{"japanese":"勉強した割に成績が悪い。","romaji":"Benkyō shita wari ni seiseki ga warui.","german":"Considering I studied, my grades are bad."}],"notes":"Expresses an unexpected result.","related":["n3-ni-shite-wa"]},
{"id":"n3-ni-shite-wa","pattern":"～にしては","level":"N3","category":"Adjektive","meaning":"for (compared with expectations)","explanation":"にしては: the result differs from what you would expect of X.","formation":"Noun/verb + にしては","examples":[{"japanese":"初心者にしては上手ですね。","cloze":{"start":3,"answer":"にしては","quiz":{"level":"N3","japanese":"初心者にしては上手ですね。","german":"You're good for a beginner.","start":3,"answer":"にしては","acceptedAnswers":["にしては"],"distractors":[{"text":"としての","reason":"の needs a following noun instead of 上手ですね."},{"text":"によると","reason":"This makes beginners the source of information instead of the standard of comparison."},{"text":"を問わず","reason":"This means regardless of being a beginner, not surprisingly good for one."}]}},"romaji":"Shoshinsha ni shite wa jōzu desu ne.","german":"You're good for a beginner."},{"japanese":"日本人にしては背が高い。","cloze":{"start":3,"answer":"にしては"},"romaji":"Nihonjin ni shite wa se ga takai.","german":"He's tall for a Japanese person."}],"notes":"Implies: 'considering that...'.","related":["n3-wari-ni","n2-nari-ni"]},
{"id":"n3-ppoi-negative","pattern":"～っぽい (N3)","level":"N3","category":"Adjektive","meaning":"-ish, -like; tending to (extended)","explanation":"っぽい at N3 level: further nuances and uses.","formation":"Noun/verb stem + っぽい","examples":[{"japanese":"この話は嘘っぽい。","romaji":"Kono hanashi wa usoppoi.","german":"This story sounds like a lie.","cloze":{"start":5,"answer":"っぽい","quiz":{"level":"N3","japanese":"この話は嘘っぽい。","german":"This story sounds like a lie.","start":5,"answer":"っぽい","acceptedAnswers":["っぽい"],"distractors":[{"text":"っぽいだ","reason":"An い-adjective does not take だ."},{"text":"っぽくでした","reason":"This is not an adjective form."},{"text":"っぽくます","reason":"An adjective does not take ます."}]}}},{"japanese":"大人っぽい服装だ。","romaji":"Otonappoi fukusō da.","german":"It's a grown-up-looking style of dress."}],"notes":"忘れっぽい (forgetful), 飽きっぽい (quickly bored).","related":["n4-ppoi"]},
{"id":"n3-zurai","pattern":"～づらい","level":"N3","category":"Adjektive","meaning":"hard to (emotionally/psychologically)","explanation":"づらい: something is psychologically or emotionally hard to do.","formation":"Verb (ます-stem) + づらい","examples":[{"japanese":"上司に言いづらいことがある。","cloze":{"start":5,"answer":"づらい","quiz":{"level":"N3","japanese":"上司に言いづらいことがある。","german":"There are things that are hard to say to my boss.","start":5,"answer":"づらい","acceptedAnswers":["づらい","にくい","がたい"],"distractors":[{"text":"づらいな","reason":"An い-adjective modifies こと without な."},{"text":"づらく","reason":"The adverbial form does not modify こと here."},{"text":"づらいの","reason":"The adjective modifies こと without の."}]}},"romaji":"Jōshi ni iidzurai koto ga aru.","german":"There are things that are hard to say to my boss."},{"japanese":"この靴は歩きづらい。","cloze":{"start":6,"answer":"づらい"},"romaji":"Kono kutsu wa arukidzurai.","german":"These shoes are hard to walk in."}],"notes":"づらい = psychological difficulty. にくい = physical difficulty.","related":["n4-nikui","n4-yasui"]},
{"id":"n3-mono-da","pattern":"～ものだ","level":"N3","category":"Satzstrukturen","meaning":"should; used to; how ...! (amazement)","explanation":"ものだ has three meanings: 1) general truth/what one should do, 2) reminiscence, 3) amazement.","formation":"Verb (辞書形/た形) + ものだ","examples":[{"japanese":"年上の人を尊敬するものだ。","cloze":{"start":9,"answer":"ものだ","quiz":{"level":"N3","japanese":"年上の人を尊敬するものだ。","german":"You should respect your elders.","start":9,"answer":"ものだ","acceptedAnswers":["ものだ","べきだ"],"distractors":[{"text":"なものだ","reason":"No な is inserted after the verb."},{"text":"ものをだ","reason":"を does not go before this copula."},{"text":"ものな","reason":"The attributive form does not end the sentence."}]}},"romaji":"Toshiue no hito o sonkei suru mono da.","german":"You should respect your elders."},{"japanese":"子供の頃よくここで遊んだものだ。","cloze":{"start":12,"answer":"ものだ"},"romaji":"Kodomo no koro yoku koko de asonda mono da.","german":"When I was a child, I often used to play here."}],"notes":"辞書形 = should/general truth. た形 = reminiscence. よく～たものだ = recalling something you often did.","related":["n3-mono-no","n2-mono-dakara","n2-mono-dewa-nai","n2-tai-mono-da"]},
{"id":"n3-mono-no","pattern":"～ものの","level":"N2","category":"Satzstrukturen","meaning":"although, it's true that ... but","explanation":"ものの: concedes something but then expresses a contradiction. Formal.","formation":"Verb/Adj (plain form) + ものの","examples":[{"japanese":"買ったものの、一度も使っていない。","cloze":{"start":3,"answer":"ものの","quiz":{"level":"N2","japanese":"買ったものの、一度も使っていない。","german":"I bought it, but I haven't used it even once.","start":3,"answer":"ものの","acceptedAnswers":["ものの","のに","けれど","が"],"distractors":[{"text":"ものだから","reason":"This makes the purchase the cause instead of a contrast."},{"text":"なものの","reason":"No な is inserted after the verb."},{"text":"ものにの","reason":"This is not a concessive connection."}]}},"romaji":"Katta mono no, ichido mo tsukatte inai.","german":"I bought it, but I haven't used it even once."},{"japanese":"日本語は勉強しているものの、まだ上手に話せない。","cloze":{"start":10,"answer":"ものの"},"romaji":"Nihongo wa benkyō shiteiru mono no, mada jōzu ni hanasenai.","german":"Although I'm studying Japanese, I still can't speak it well."}],"notes":"More formal than ～けど/～のに.","related":["noni","n3-mono-da","n2-to-wa-iu-mono-no"]},
{"id":"n3-wake-dewa-nai","pattern":"～わけではない","level":"N3","category":"Satzstrukturen","meaning":"it's not that, not necessarily","explanation":"わけではない: partially negates an assumption: it's not quite like that.","formation":"Verb/Adj (plain form) + わけではない","examples":[{"japanese":"嫌いなわけではないが、あまり食べない。","cloze":{"start":3,"answer":"わけではない","quiz":{"level":"N3","japanese":"嫌いなわけではないが、あまり食べない。","german":"It's not that I dislike it, but I don't eat it much.","start":3,"answer":"わけではない","acceptedAnswers":["わけではない","わけじゃない"],"distractors":[{"text":"わけだ","reason":"This affirms the dislike instead of rejecting the inference."},{"text":"わけをない","reason":"The negation is わけではない."},{"text":"わけではある","reason":"This concedes a dislike instead of denying it."}]}},"romaji":"Kirai na wake dewa nai ga, amari tabenai.","german":"It's not that I dislike it, but I don't eat it much."},{"japanese":"全員が賛成しているわけではない。","cloze":{"start":9,"answer":"わけではない"},"romaji":"Zen'in ga sansei shiteiru wake dewa nai.","german":"It's not that everyone agrees."}],"notes":"Partial negation. ～わけがない = complete impossibility.","related":["n4-wake-da","n4-hazu-ga-nai","n3-no-dewa-nai-ka","n2-ka-to-iu-to"]},
{"id":"n3-ni-chigainai","pattern":"～に違いない","level":"N3","category":"Satzstrukturen","meaning":"must be, surely","explanation":"に違いない: strong conviction that something is the case.","formation":"Verb/adj./noun + に違いない","examples":[{"japanese":"彼は知っているに違いない。","cloze":{"start":7,"answer":"に違いない","quiz":{"level":"N3","japanese":"彼は知っているに違いない。","german":"He must know.","start":7,"answer":"に違いない","acceptedAnswers":["に違いない","はずだ"],"distractors":[{"text":"を違いない","reason":"The fixed expression of certainty requires に."},{"text":"に違うない","reason":"The negative form is 違いない."},{"text":"なに違いない","reason":"No な is inserted after the verb."}]}},"romaji":"Kare wa shitteiru ni chigainai.","german":"He must know."},{"japanese":"あの音は猫に違いない。","cloze":{"start":5,"answer":"に違いない"},"romaji":"Ano oto wa neko ni chigainai.","german":"That sound must be a cat."}],"notes":"Stronger than ～はずだ. Almost 100% certainty.","related":["n4-hazu-da","n3-ni-kimatte-iru","n2-ni-soui-nai"]},
{"id":"n3-ni-kimatte-iru","pattern":"～に決まっている","level":"N3","category":"Satzstrukturen","meaning":"it's certain that, of course","explanation":"に決まっている: the speaker is absolutely certain.","formation":"Verb/adj./noun + に決まっている","examples":[{"japanese":"そんなことをしたら怒られるに決まっている。","cloze":{"start":13,"answer":"に決まっている","quiz":{"level":"N3","japanese":"そんなことをしたら怒られるに決まっている。","german":"If you do something like that, you're bound to get told off.","start":13,"answer":"に決まっている","acceptedAnswers":["に決まっている","に違いない"],"distractors":[{"text":"を決まっている","reason":"The fixed expression of certainty requires に."},{"text":"に決まるている","reason":"The て-form of 決まる is 決まって."},{"text":"なに決まっている","reason":"No な is inserted after the verb."}]}},"romaji":"Sonna koto o shitara okorareru ni kimatte iru.","german":"If you do something like that, you're bound to get told off."},{"japanese":"あの店はおいしいに決まっている。","cloze":{"start":8,"answer":"に決まっている"},"romaji":"Ano mise wa oishii ni kimatte iru.","german":"That restaurant is bound to be good."}],"notes":"Very subjective and colloquial. Stronger than ～に違いない.","related":["n3-ni-chigainai","n2-ni-soui-nai"]},
{"id":"n3-osore-ga-aru","pattern":"～おそれがある","level":"N3","category":"Satzstrukturen","meaning":"there is a risk that, there is a danger of","explanation":"おそれがある: formally warns of a possible negative outcome.","formation":"Verb (辞書形) + おそれがある / Noun + のおそれがある","examples":[{"japanese":"台風が近づくおそれがある。","cloze":{"start":6,"answer":"おそれがある","quiz":{"level":"N3","japanese":"台風が近づくおそれがある。","german":"There is a risk that a typhoon will approach.","start":6,"answer":"おそれがある","acceptedAnswers":["おそれがある"],"distractors":[{"text":"おそれをある","reason":"ある does not take a direct object here."},{"text":"なおそれがある","reason":"No な is inserted after the verb."},{"text":"おそれがない","reason":"This denies the danger."}]}},"romaji":"Taifū ga chikazuku osore ga aru.","german":"There is a risk that a typhoon will approach."},{"japanese":"地震のおそれがあります。","romaji":"Jishin no osore ga arimasu.","german":"There is a risk of an earthquake."}],"notes":"Formal. Often used in news reports and warnings.","related":["n2-kaneru"]},
{"id":"n3-you-ga-nai","pattern":"～ようがない / ～ようもない","level":"N3","category":"Satzstrukturen","meaning":"there is no way to","explanation":"ようがない: it is absolutely impossible to do something.","formation":"Verb (ます-stem) + ようがない","examples":[{"japanese":"連絡先が分からなくて連絡しようがない。","cloze":{"start":13,"answer":"ようがない","quiz":{"level":"N3","japanese":"連絡先が分からなくて連絡しようがない。","german":"I don't know their contact details, so there's no way for me to get in touch.","start":13,"answer":"ようがない","acceptedAnswers":["ようがない"],"distractors":[{"text":"ようをない","reason":"The expression requires が."},{"text":"ようがある","reason":"This affirms that contact is possible."},{"text":"るようがない","reason":"ようがない follows the stem し."}]}},"romaji":"Renrakusaki ga wakaranakute renraku shiyō ga nai.","german":"I don't know their contact details, so there's no way for me to get in touch."},{"japanese":"どうしようもない状況だ。","cloze":{"start":3,"answer":"ようもない"},"romaji":"Dō shiyō mo nai jōkyō da.","german":"It's a hopeless situation."},{"japanese":"住所が分からないので、連絡のしようがない。","romaji":"Jūsho ga wakaranai no de, renraku no shiyō ga nai.","german":"Since I don't know the address, there's no way to contact them."},{"japanese":"証拠がないので、証明のしようがない。","romaji":"Shōko ga nai no de, shōmei no shiyō ga nai.","german":"Since there's no evidence, there's no way to prove it."}],"notes":"どうしようもない = there is absolutely nothing you can do.","related":["n3-hoka-nai","n2-you-ni-yotte-wa"],"legacyIds":["n2-you-ga-nai"]},
{"id":"n3-hoka-nai","pattern":"～ほかない / ～よりほかない","level":"N3","category":"Satzstrukturen","meaning":"have no choice but to","explanation":"ほかない: there is no other option.","formation":"Verb (辞書形) + ほかない/よりほかない","examples":[{"japanese":"自分でやるほかない。","cloze":{"start":5,"answer":"ほかない","quiz":{"level":"N3","japanese":"自分でやるほかない。","german":"There's nothing for it but to do it myself.","start":5,"answer":"ほかない","acceptedAnswers":["ほかない","しかない","よりほかない"],"distractors":[{"text":"なほかない","reason":"No な is inserted after the verb."},{"text":"ほかをない","reason":"This is not a construction meaning 'nothing but'."},{"text":"ほかないだ","reason":"No だ follows ない."}]}},"romaji":"Jibun de yaru hoka nai.","german":"There's nothing for it but to do it myself."},{"japanese":"歩いて帰るほかなかった。","romaji":"Aruite kaeru hoka nakatta.","german":"I had no choice but to walk home."}],"notes":"Similar: ～しかない, ～ざるを得ない.","related":["n3-zaruwoenai","shika-nai","n4-shika-nai-option"]},
{"id":"n3-kiri","pattern":"～きり / ～っきり","level":"N3","category":"Satzstrukturen","meaning":"since (and nothing more); only","explanation":"きり: nothing has changed since a certain point, or only this one thing.","formation":"Verb (た形) + きり / Noun + きり","examples":[{"japanese":"彼とは一度会ったきり連絡がない。","cloze":{"start":8,"answer":"きり","quiz":{"level":"N3","japanese":"彼とは一度会ったきり連絡がない。","german":"I met him once, and I haven't heard from him since.","start":8,"answer":"きり","acceptedAnswers":["きり"],"distractors":[{"text":"ながら","reason":"ながら does not follow the た-form."},{"text":"てから","reason":"会ったてから is not a valid verb connection."},{"text":"なきり","reason":"No な is inserted after the verb."}]}},"romaji":"Kare to wa ichido atta kiri renraku ga nai.","german":"I met him once, and I haven't heard from him since."},{"japanese":"二人きりで話したい。","cloze":{"start":2,"answer":"きり"},"romaji":"Futari kiri de hanashitai.","german":"I want to talk, just the two of us (alone)."}],"notes":"～たきり = since (negative). ～きり = only (二人きり = just the two of us).","related":["n4-bakari-p"]},
{"id":"n3-kuseni","pattern":"～くせに","level":"N3","category":"Satzstrukturen","meaning":"even though, despite (critical)","explanation":"くせに: like ～のに, but with a negative, reproachful nuance.","formation":"Verb/adj. + くせに / Noun + のくせに","examples":[{"japanese":"知っているくせに教えてくれない。","cloze":{"start":5,"answer":"くせに","quiz":{"level":"N3","japanese":"知っているくせに教えてくれない。","german":"He knows, yet he won't tell me.","start":5,"answer":"くせに","acceptedAnswers":["くせに","のに"],"distractors":[{"text":"なくせに","reason":"No な is inserted after the verb."},{"text":"くせを","reason":"を does not connect contrasting statements here."},{"text":"くせにの","reason":"の cannot connect the following clause here."}]}},"romaji":"Shitteiru kuse ni oshiete kurenai.","german":"He knows, yet he won't tell me."},{"japanese":"子供のくせに生意気だ。","cloze":{"start":3,"answer":"くせに"},"romaji":"Kodomo no kuse ni namaiki da.","german":"He's just a kid, but he's so cheeky."}],"notes":"Stronger and more negative than ～のに. Expresses annoyance.","related":["noni"]},
{"id":"n3-totan","pattern":"～たとたん(に)","level":"N3","category":"Satzstrukturen","meaning":"the moment, as soon as","explanation":"たとたん: right after an action, something unexpected happens.","formation":"Verb (た形) + とたん(に)","examples":[{"japanese":"ドアを開けたとたん、猫が飛び出した。","romaji":"Doa o aketa totan, neko ga tobidashita.","german":"The moment I opened the door, the cat jumped out.","cloze":{"start":5,"answer":"たとたん","quiz":{"level":"N3","japanese":"ドアを開けたとたん、猫が飛び出した。","german":"The moment I opened the door, the cat jumped out.","start":5,"answer":"たとたん","acceptedAnswers":["たとたん"],"distractors":[{"text":"るとたん","reason":"After 開け this gives 開けるとたん; the sudden follow-up event requires the た-form."},{"text":"たとたんな","reason":"な is not a clause connector here."},{"text":"ますとたん","reason":"The expression does not follow the ます-form."}]}}},{"japanese":"横になったとたんに寝てしまった。","romaji":"Yoko ni natta totan ni nete shimatta.","german":"The moment I lay down, I fell asleep."}],"notes":"Always unexpected/surprising. Similar: ～た瞬間.","related":["tara","n2-ka-nai-ka-no-uchi-ni","n1-ga-hayai-ka"]},
{"id":"n3-saichuu","pattern":"～最中に","level":"N3","category":"Satzstrukturen","meaning":"in the middle of, right while","explanation":"最中に: something happens right in the middle of an action.","formation":"Verb (ている) + 最中に / Noun + の最中に","examples":[{"japanese":"会議の最中に電話が鳴った。","cloze":{"start":3,"answer":"最中に","quiz":{"level":"N3","japanese":"会議の最中に電話が鳴った。","german":"The phone rang in the middle of the meeting.","start":3,"answer":"最中に","acceptedAnswers":["最中に"],"distractors":[{"text":"前に","reason":"This means before the meeting."},{"text":"後に","reason":"This means after the meeting."},{"text":"最中な","reason":"The adverbial time expression requires に."}]}},"romaji":"Kaigi no saichū ni denwa ga natta.","german":"The phone rang in the middle of the meeting."},{"japanese":"食べている最中に来客があった。","cloze":{"start":5,"answer":"最中に"},"romaji":"Tabeteiru saichū ni raikyaku ga atta.","german":"A visitor came while I was in the middle of eating."}],"notes":"Emphasizes that the action is in full swing.","related":["n4-aida-ni","n4-tokoro-da","n5-chuu-juu"]},
{"id":"n3-sai-ni","pattern":"～際(に)","level":"N3","category":"Satzstrukturen","meaning":"when, on the occasion of (formal)","explanation":"際に: formal variant of ～時に. Often used in official contexts.","formation":"Verb (辞書形/た形) + 際(に) / Noun + の際(に)","examples":[{"japanese":"お帰りの際はお忘れ物のないようご注意ください。","romaji":"Okaeri no sai wa owasuremono no nai yō go-chūi kudasai.","german":"When leaving, please take care not to forget anything.","cloze":{"start":4,"answer":"際","quiz":{"level":"N3","japanese":"お帰りの際はお忘れ物のないようご注意ください。","german":"When leaving, please take care not to forget anything.","start":4,"answer":"際","acceptedAnswers":["際","時"],"distractors":[{"text":"際な","reason":"No な is inserted before は here."},{"text":"際を","reason":"を does not fit before the topic-marked time expression with は."},{"text":"際だ","reason":"The copula does not fit before は."}]}}},{"japanese":"申し込みの際に身分証明書が必要です。","romaji":"Mōshikomi no sai ni mibun shōmeisho ga hitsuyō desu.","german":"ID is required when applying."},{"japanese":"お帰りの際は、忘れ物にご注意ください。","romaji":"Okaeri no sai wa, wasuremono ni go-chūi kudasai.","german":"When leaving, please be careful not to leave anything behind."},{"japanese":"申し込みの際に、身分証明書が必要です。","romaji":"Mōshikomi no sai ni, mibun shōmeisho ga hitsuyō desu.","german":"ID is required when applying."}],"notes":"Formal/written. Everyday language: ～時に.","related":["n4-tokini","n2-ni-atatte","n2-ni-saishite"],"legacyIds":["n2-sai-ni"]},
{"id":"n3-ue-de","pattern":"～上で","level":"N3","category":"Satzstrukturen","meaning":"after; in terms of, regarding","explanation":"上で: 1) after doing something (た形), 2) in terms of, when it comes to ... (辞書形).","formation":"Verb (た形/辞書形) + 上で / Noun + の上で","examples":[{"japanese":"よく考えた上で決めてください。","cloze":{"start":5,"answer":"上で","quiz":{"level":"N3","japanese":"よく考えた上で決めてください。","german":"Please decide after thinking it over carefully.","start":5,"answer":"上で","acceptedAnswers":["上で"],"distractors":[{"text":"上を","reason":"The decision that follows requires 上で here."},{"text":"前に","reason":"前に requires the dictionary form and means beforehand."},{"text":"ながら","reason":"ながら does not follow the た-form."}]}},"romaji":"Yoku kangaeta ue de kimete kudasai.","german":"Please decide after thinking it over carefully."},{"japanese":"仕事の上で大切なことだ。","cloze":{"start":3,"answer":"上で"},"romaji":"Shigoto no ue de taisetsu na koto da.","german":"That's important when it comes to work."}],"notes":"た形 + 上で = after. 辞書形/noun + 上で = regarding.","related":["n4-ato-de","n2-jou"]},
{"id":"n3-uchi-ni","pattern":"～うちに","level":"N3","category":"Satzstrukturen","meaning":"while (still), before (something changes)","explanation":"うちに: doing something while a state still lasts.","formation":"Verb (辞書形/ない形/ている) + うちに / Adj. + うちに","examples":[{"japanese":"若いうちにいろいろ経験したい。","cloze":{"start":2,"answer":"うちに","quiz":{"level":"N3","japanese":"若いうちにいろいろ経験したい。","german":"I want to experience lots of things while I'm young.","start":2,"answer":"うちに","acceptedAnswers":["うちに"],"distractors":[{"text":"なうちに","reason":"An い-adjective does not take な here."},{"text":"うちの","reason":"の would modify a noun instead of the following clause."},{"text":"うちを","reason":"を does not form a time expression here."}]}},"romaji":"Wakai uchi ni iroiro keiken shitai.","german":"I want to experience lots of things while I'm young."},{"japanese":"忘れないうちにメモしておこう。","cloze":{"start":4,"answer":"うちに"},"romaji":"Wasurenai uchi ni memo shite okō.","german":"Let me make a note of it before I forget."}],"notes":"～ているうちに = while (and meanwhile something changes).","related":["n4-aida-ni","n2-uchi-ni-hairanai"]},
{"id":"n3-tabi-ni","pattern":"～たびに","level":"N3","category":"Satzstrukturen","meaning":"every time, whenever","explanation":"たびに: every time an action takes place, something happens.","formation":"Verb (辞書形) + たびに / Noun + のたびに","examples":[{"japanese":"日本に行くたびにお土産を買う。","cloze":{"start":5,"answer":"たびに","quiz":{"level":"N3","japanese":"日本に行くたびにお土産を買う。","german":"Every time I go to Japan, I buy souvenirs.","start":5,"answer":"たびに","acceptedAnswers":["たびに"],"distractors":[{"text":"たびな","reason":"The repeated time expression requires に."},{"text":"なたびに","reason":"No な is inserted after the verb."},{"text":"たびを","reason":"を does not form a repeated time expression here."}]}},"romaji":"Nihon ni iku tabi ni omiyage o kau.","german":"Every time I go to Japan, I buy souvenirs."},{"japanese":"この曲を聞くたびに学生時代を思い出す。","cloze":{"start":6,"answer":"たびに"},"romaji":"Kono kyoku o kiku tabi ni gakusei jidai o omoidasu.","german":"Every time I hear this song, I remember my student days."},{"japanese":"日本に行くたびに、新しい発見がある。","romaji":"Nihon ni iku tabi ni, atarashii hakken ga aru.","german":"Every time I go to Japan, I discover something new."},{"japanese":"この曲を聞くたびに、学生時代を思い出す。","romaji":"Kono kyoku wo kiku tabi ni, gakusei jidai wo omoidasu.","german":"Every time I hear this song, I'm reminded of my student days."}],"notes":"Regular repetition.","related":["n4-to-conditional","n2-ni-tsuke"],"legacyIds":["n2-tabi-ni"]},
{"id":"n3-toori","pattern":"～とおり(に)","level":"N3","category":"Satzstrukturen","meaning":"as, just as, exactly as","explanation":"とおりに: exactly as something was said/done/expected.","formation":"Verb (た形/辞書形) + とおり(に) / Noun + のとおり(に)","examples":[{"japanese":"説明書のとおりに組み立ててください。","romaji":"Setsumeisho no tōri ni kumitatete kudasai.","german":"Please assemble it according to the instructions.","cloze":{"start":4,"answer":"とおりに","quiz":{"level":"N3","japanese":"説明書のとおりに組み立ててください。","german":"Please assemble it according to the instructions.","start":4,"answer":"とおりに","acceptedAnswers":["とおりに"],"distractors":[{"text":"とおりな","reason":"The adverbial 'in line with' requires に."},{"text":"とおりを","reason":"を does not express manner here."},{"text":"とおりの","reason":"の needs a following noun instead of 組み立てて."}]}}},{"japanese":"思ったとおりだった。","romaji":"Omotta tōri datta.","german":"It was just as I thought."}],"notes":"言ったとおり (as I said), 予想どおり (as expected).","related":[]},
{"id":"n3-dokoro-ka","pattern":"～どころか","level":"N2","category":"Satzstrukturen","meaning":"far from; let alone","explanation":"どころか: reality is far from what was expected.","formation":"Verb/adj./noun + どころか","examples":[{"japanese":"旅行どころか、休みも取れない。","cloze":{"start":2,"answer":"どころか","quiz":{"level":"N2","japanese":"旅行どころか、休みも取れない。","german":"Forget a trip, I can't even take a day off.","start":2,"answer":"どころか","acceptedAnswers":["どころか"],"distractors":[{"text":"どころを","reason":"This is not an escalating contrast."},{"text":"どころにの","reason":"This is not an escalating contrast."},{"text":"どころな","reason":"This does not connect the following clause."}]}},"romaji":"Ryokō dokoro ka, yasumi mo torenai.","german":"Forget a trip, I can't even take a day off."},{"japanese":"減るどころか、増えている。","cloze":{"start":2,"answer":"どころか"},"romaji":"Heru dokoro ka, fueteiru.","german":"Far from decreasing, it's increasing."}],"notes":"Intensifies the contrast between expectation and reality.","related":["n3-dokoro-dewa-nai","n3-to-iu-yori"]},
{"id":"n3-dokoro-dewa-nai","pattern":"～どころではない","level":"N3","category":"Satzstrukturen","meaning":"not the time/situation for","explanation":"どころではない: the situation doesn't allow you to deal with that.","formation":"Verb (辞書形) + どころではない / Noun + どころではない","examples":[{"japanese":"忙しくて旅行どころではない。","cloze":{"start":6,"answer":"どころではない","quiz":{"level":"N3","japanese":"忙しくて旅行どころではない。","german":"I'm so busy that a trip is out of the question.","start":6,"answer":"どころではない","acceptedAnswers":["どころではない","どころじゃない"],"distractors":[{"text":"どころではある","reason":"This affirms that there is room for a trip."},{"text":"どころをない","reason":"The set phrase uses では."},{"text":"どころではないだ","reason":"No だ follows ない."}]}},"romaji":"Isogashikute ryokō dokoro dewa nai.","german":"I'm so busy that a trip is out of the question."},{"japanese":"遊ぶどころじゃないよ。","romaji":"Asobu dokoro ja nai yo.","german":"This is no time for playing around!"}],"notes":"Informal: ～どころじゃない.","related":["n3-dokoro-ka","n3-te-iru-baai-janai"]},
{"id":"n3-bakari-ka","pattern":"～ばかりか","level":"N3","category":"Satzstrukturen","meaning":"not only ... but also","explanation":"ばかりか: not only X, but Y as well.","formation":"Verb/adj./noun + ばかりか ～も/さえ","examples":[{"japanese":"日本語ばかりか中国語も話せる。","cloze":{"start":3,"answer":"ばかりか","quiz":{"level":"N3","japanese":"日本語ばかりか中国語も話せる。","german":"He can speak not only Japanese but also Chinese.","start":3,"answer":"ばかりか","acceptedAnswers":["ばかりか","だけでなく","のみならず"],"distractors":[{"text":"しか","reason":"しか requires a negative ending."},{"text":"ばかりを","reason":"を does not form a 'not only ... but also' connection here."},{"text":"ばかりな","reason":"な does not connect to the following clause here."}]}},"romaji":"Nihongo bakari ka chūgokugo mo hanaseru.","german":"He can speak not only Japanese but also Chinese."},{"japanese":"成績が上がるばかりか、友達も増えた。","cloze":{"start":6,"answer":"ばかりか"},"romaji":"Seiseki ga agaru bakari ka, tomodachi mo fueta.","german":"Not only did my grades go up, I also made more friends."}],"notes":"More formal than ～だけでなく.","related":["n4-dake-de-naku"]},
{"id":"n3-bakari-ni","pattern":"～ばかりに","level":"N3","category":"Satzstrukturen","meaning":"simply because (with a bad result)","explanation":"ばかりに: just because of one particular reason, things turned out badly.","formation":"Verb (た形) + ばかりに","examples":[{"japanese":"遅刻したばかりに大事な話を聞き逃した。","cloze":{"start":4,"answer":"ばかりに","quiz":{"level":"N3","japanese":"遅刻したばかりに大事な話を聞き逃した。","german":"Just because I was late, I missed the important talk.","start":4,"answer":"ばかりに","acceptedAnswers":["ばかりに","ために","せいで"],"distractors":[{"text":"ばかりを","reason":"The causal connection requires に."},{"text":"なばかりに","reason":"No な is inserted after the verb."},{"text":"ばかりの","reason":"の needs a following noun instead of the next clause."}]}},"romaji":"Chikoku shita bakari ni daiji na hanashi o kikinogashita.","german":"Just because I was late, I missed the important talk."},{"japanese":"お金がないばかりに夢を諦めた。","cloze":{"start":5,"answer":"ばかりに"},"romaji":"Okane ga nai bakari ni yume o akirameta.","german":"Just because I had no money, I gave up on my dream."}],"notes":"Always a negative result. Expresses regret.","related":["n4-sei-de"]},
{"id":"n3-kara-niwa","pattern":"～からには","level":"N2","category":"Satzstrukturen","meaning":"now that, since (having decided)","explanation":"からには: once you've committed to something, you have to see it through.","formation":"Verb (辞書形/た形) + からには","examples":[{"japanese":"やるからには最後までやる。","cloze":{"start":2,"answer":"からには","quiz":{"level":"N2","japanese":"やるからには最後までやる。","german":"If I'm going to do it, I'll see it through to the end.","start":2,"answer":"からには","acceptedAnswers":["からには","以上は"],"distractors":[{"text":"なからには","reason":"No な is inserted after the verb."},{"text":"からのには","reason":"The fixed premise construction contains no の."},{"text":"からにを","reason":"This is not a premise construction."}]}},"romaji":"Yaru kara ni wa saigo made yaru.","german":"If I'm going to do it, I'll see it through to the end."},{"japanese":"約束したからには守らなければならない。","cloze":{"start":4,"answer":"からには"},"romaji":"Yakusoku shita kara ni wa mamoranakereba naranai.","german":"Since I promised, I have to keep my word."}],"notes":"Similar: ～以上は.","related":["n2-ijou-wa"]},
{"id":"n3-kara-toitte","pattern":"～からといって","level":"N3","category":"Satzstrukturen","meaning":"just because ... doesn't mean","explanation":"からといって: just because X, it doesn't automatically mean Y.","formation":"Verb/adj./noun + からといって ～わけではない","examples":[{"japanese":"安いからといって品質が悪いわけではない。","cloze":{"start":2,"answer":"からといって","quiz":{"level":"N3","japanese":"安いからといって品質が悪いわけではない。","german":"Just because it's cheap doesn't mean the quality is bad.","start":2,"answer":"からといって","acceptedAnswers":["からといって"],"distractors":[{"text":"からと言うて","reason":"In the standard language, 言う becomes 言って."},{"text":"なからといって","reason":"An い-adjective does not take な here."},{"text":"からをいって","reason":"The quoting connection requires と."}]}},"romaji":"Yasui kara to itte hinshitsu ga warui wake dewa nai.","german":"Just because it's cheap doesn't mean the quality is bad."},{"japanese":"日本人だからといって漢字が全部読めるわけではない。","cloze":{"start":4,"answer":"からといって"},"romaji":"Nihonjin da kara to itte kanji ga zenbu yomeru wake dewa nai.","german":"Just because you're Japanese doesn't mean you can read every kanji."}],"notes":"Often with ～わけではない or ～とは限らない.","related":["n3-wake-dewa-nai","n2-ka-to-iu-to"]},
{"id":"n3-kagiri","pattern":"～限り","level":"N3","category":"Satzstrukturen","meaning":"as long as, as far as","explanation":"限り: as long as a state lasts / as far as one knows.","formation":"Verb (辞書形/ない形/ている) + 限り","examples":[{"japanese":"私が知っている限りでは問題ない。","cloze":{"start":7,"answer":"限り","quiz":{"level":"N3","japanese":"私が知っている限りでは問題ない。","german":"As far as I know, there's no problem.","start":7,"answer":"限り","acceptedAnswers":["限り"],"distractors":[{"text":"な限り","reason":"No な is inserted after the verb."},{"text":"限りを","reason":"を does not fit before では here."},{"text":"限りだ","reason":"だ does not fit before では here."}]}},"romaji":"Watashi ga shitteiru kagiri de wa mondai nai.","german":"As far as I know, there's no problem."},{"japanese":"体が元気な限り働き続けたい。","cloze":{"start":5,"answer":"限り"},"romaji":"Karada ga genki na kagiri hataraki tsuzuketai.","german":"As long as I'm healthy, I want to keep working."}],"notes":"できる限り = as much as possible.","related":["n2-nai-kagiri"]},
{"id":"n3-koto-da","pattern":"～ことだ","level":"N3","category":"Satzstrukturen","meaning":"should, it's advisable to","explanation":"ことだ: gives advice or a general recommendation.","formation":"Verb (辞書形/ない形) + ことだ","examples":[{"japanese":"健康のために野菜を食べることだ。","cloze":{"start":12,"answer":"ことだ","quiz":{"level":"N3","japanese":"健康のために野菜を食べることだ。","german":"For your health, you should eat vegetables.","start":12,"answer":"ことだ","acceptedAnswers":["ことだ","べきだ"],"distractors":[{"text":"なことだ","reason":"No な is inserted after the verb."},{"text":"ことをだ","reason":"を does not go before this copula."},{"text":"ことな","reason":"This is not a sentence ending."}]}},"romaji":"Kenkō no tame ni yasai o taberu koto da.","german":"For your health, you should eat vegetables."},{"japanese":"遅刻しないことだ。","cloze":{"start":5,"answer":"ことだ"},"romaji":"Chikoku shinai koto da.","german":"You shouldn't be late."}],"notes":"General advice, not aimed at a specific person.","related":["n4-ta-hou-ga-ii","n4-beki-da"]},
{"id":"n3-ta-tokoro","pattern":"～たところ","level":"N3","category":"Satzstrukturen","meaning":"when I did ... (result)","explanation":"たところ: when you tried something, a (often unexpected) result came about.","formation":"Verb (た形) + ところ","examples":[{"japanese":"聞いてみたところ、もう売り切れだった。","cloze":{"start":4,"answer":"たところ","quiz":{"level":"N3","japanese":"聞いてみたところ、もう売り切れだった。","german":"When I asked, it was already sold out.","start":4,"answer":"たところ","acceptedAnswers":["たところ"],"distractors":[{"text":"るところ","reason":"みるところ does not describe the result of asking here."},{"text":"ますところ","reason":"The expression does not follow the ます-form here."},{"text":"たところな","reason":"な does not connect the following clause."}]}},"romaji":"Kiite mita tokoro, mō urikire datta.","german":"When I asked, it was already sold out."},{"japanese":"調べたところ、問題が見つかった。","cloze":{"start":2,"answer":"たところ"},"romaji":"Shirabeta tokoro, mondai ga mitsukatta.","german":"When I looked into it, I found a problem."}],"notes":"Difference from ～ところだ (point in time): ～たところ = result.","related":["n4-tokoro-da","tara"]},
{"id":"n3-nai-koto-wa-nai","pattern":"～ないことはない","level":"N3","category":"Satzstrukturen","meaning":"it's not that one can't","explanation":"ないことはない: a double negative = a weak affirmative. 'It's possible, but...'","formation":"Verb (ない形) + ことはない","examples":[{"japanese":"食べられないことはないが、好きではない。","cloze":{"start":4,"answer":"ないことはない","quiz":{"level":"N3","japanese":"食べられないことはないが、好きではない。","german":"It's not that I can't eat it, but I don't like it.","start":4,"answer":"ないことはない","acceptedAnswers":["ないことはない"],"distractors":[{"text":"ないことはある","reason":"This concedes inability instead of basic ability."},{"text":"ないことをない","reason":"The qualifying double negative uses は."},{"text":"ないことはないだ","reason":"No だ follows ない."}]}},"romaji":"Taberarenai koto wa nai ga, suki dewa nai.","german":"It's not that I can't eat it, but I don't like it."},{"japanese":"分からないことはないが、説明しにくい。","cloze":{"start":3,"answer":"ないことはない"},"romaji":"Wakaranai koto wa nai ga, setsumei shinikui.","german":"It's not that I don't understand it, but it's hard to explain."}],"notes":"A weak affirmative with reservations.","related":["n3-wake-dewa-nai"]},
{"id":"n3-ni-mo-kakawarazu","pattern":"～にもかかわらず","level":"N3","category":"Satzstrukturen","meaning":"despite, in spite of","explanation":"にもかかわらず: formal variant of ～のに (despite).","formation":"Verb/adj./noun + にもかかわらず","examples":[{"japanese":"雨にもかかわらず多くの人が集まった。","cloze":{"start":1,"answer":"にもかかわらず","quiz":{"level":"N3","japanese":"雨にもかかわらず多くの人が集まった。","german":"Despite the rain, many people gathered.","start":1,"answer":"にもかかわらず","acceptedAnswers":["にもかかわらず"],"distractors":[{"text":"にもかかわるず","reason":"The negative form is かかわらず."},{"text":"をもかかわらず","reason":"The set phrase requires に."},{"text":"にもかかわらずの","reason":"の does not connect a following clause here."}]}},"romaji":"Ame ni mo kakawarazu ōku no hito ga atsumatta.","german":"Despite the rain, many people gathered."},{"japanese":"努力したにもかかわらず失敗した。","cloze":{"start":4,"answer":"にもかかわらず"},"romaji":"Doryoku shita ni mo kakawarazu shippai shita.","german":"Despite my efforts, I failed."}],"notes":"Very formal/written. Everyday language: ～のに.","related":["noni","n2-mo-kamawazu"]},
{"id":"n3-to-shitemo","pattern":"～としても","level":"N3","category":"Satzstrukturen","meaning":"even if (supposing)","explanation":"としても: even if you assume that X is true.","formation":"Verb/adj./noun + としても","examples":[{"japanese":"たとえ失敗したとしても後悔しない。","cloze":{"start":7,"answer":"としても","quiz":{"level":"N3","japanese":"たとえ失敗したとしても後悔しない。","german":"Even if I fail, I won't regret it.","start":7,"answer":"としても","acceptedAnswers":["としても"],"distractors":[{"text":"をしても","reason":"The hypothetical assumption requires と."},{"text":"とするても","reason":"The て-form of する is して."},{"text":"なとしても","reason":"No な is inserted after the verb."}]}},"romaji":"Tatoe shippai shita to shitemo kōkai shinai.","german":"Even if I fail, I won't regret it."},{"japanese":"仮に合格したとしても、まだ先は長い。","cloze":{"start":6,"answer":"としても"},"romaji":"Kari ni gōkaku shita to shitemo, mada saki wa nagai.","german":"Even supposing I pass, there's still a long way to go."}],"notes":"More hypothetical than ～ても.","related":["temo","n3-tatte-datte","n3-to-suru-to","n3-tatoe-temo"]},
{"id":"n3-shidai","pattern":"～次第","level":"N2","category":"Satzstrukturen","meaning":"as soon as; depending on","explanation":"次第: 1) as soon as something happens (ます-stem + 次第), 2) it depends on (noun + 次第).","formation":"Verb (ます-stem) + 次第 / Noun + 次第","examples":[{"japanese":"届き次第ご連絡します。","cloze":{"start":2,"answer":"次第","quiz":{"level":"N2","japanese":"届き次第ご連絡します。","german":"I'll contact you as soon as it arrives.","start":2,"answer":"次第","acceptedAnswers":["次第"],"distractors":[{"text":"たら","reason":"届きたら is not a verb form."},{"text":"次第な","reason":"This does not connect the following action adverbially."},{"text":"次第を","reason":"を does not form a time expression here."}]}},"romaji":"Todoki shidai go-renraku shimasu.","german":"I'll contact you as soon as it arrives."},{"japanese":"結果はあなた次第です。","cloze":{"start":6,"answer":"次第"},"romaji":"Kekka wa anata shidai desu.","german":"The result depends on you."}],"notes":"ます-stem + 次第 = as soon as (formal). Noun + 次第 = it depends on.","related":["n3-ni-ojite","n2-ni-yotte-wa","n2-ni-kakatte-iru"]},
{"id":"n3-hanmen","pattern":"～反面","level":"N3","category":"Satzstrukturen","meaning":"on the other hand, whereas","explanation":"反面: shows the flip side or the opposite of a quality.","formation":"Verb/Adj (plain form) + 反面","examples":[{"japanese":"この仕事はやりがいがある反面、ストレスも多い。","cloze":{"start":12,"answer":"反面","quiz":{"level":"N3","japanese":"この仕事はやりがいがある反面、ストレスも多い。","german":"This job is rewarding, but it's also very stressful.","start":12,"answer":"反面","acceptedAnswers":["反面","一方で"],"distractors":[{"text":"な反面","reason":"No な is inserted after the verb."},{"text":"反面を","reason":"を does not form a contrastive connection here."},{"text":"反面だの","reason":"This does not connect the following clause."}]}},"romaji":"Kono shigoto wa yarigai ga aru hanmen, sutoresu mo ōi.","german":"This job is rewarding, but it's also very stressful."},{"japanese":"都会は便利な反面、家賃が高い。","cloze":{"start":6,"answer":"反面"},"romaji":"Tokai wa benri na hanmen, yachin ga takai.","german":"The city is convenient, but the rent is high."}],"notes":"Similar to ～一方で, but emphasizes the contrast more strongly.","related":["n2-ippou-de"]},
{"id":"n3-sae-ba","pattern":"～さえ～ば","level":"N3","category":"Satzstrukturen","meaning":"if only, as long as","explanation":"さえ～ば: a single condition is enough.","formation":"Noun + さえ + Verb (ば-form) / Verb (ます-stem) + さえすれば","examples":[{"japanese":"お金さえあれば何でもできる。","romaji":"Okane sae areba nandemo dekiru.","german":"As long as you have money, you can do anything.","cloze":{"start":2,"answer":"さえあれば","quiz":{"level":"N3","japanese":"お金さえあれば何でもできる。","german":"As long as you have money, you can do anything.","start":2,"answer":"さえあれば","acceptedAnswers":["さえあれば"],"distractors":[{"text":"さえあるば","reason":"The conditional form of ある is あれば."},{"text":"さえをあれば","reason":"を does not go between さえ and あれば."},{"text":"さえなければ","reason":"This reverses the necessary condition of having money."}]}}},{"japanese":"薬を飲みさえすれば治る。","romaji":"Kusuri o nomi sae sureba naoru.","german":"All you have to do is take the medicine and you'll get better."}],"notes":"Emphasizes that only THIS ONE condition is needed.","related":["n4-sae","n4-ba"]},
{"id":"n3-koto-kara","pattern":"～ことから","level":"N3","category":"Satzstrukturen","meaning":"from the fact that, because","explanation":"ことから: gives the reason for, or origin of, a name or conclusion.","formation":"Verb/Adj (plain form) + ことから","examples":[{"japanese":"形が星に似ていることからスターフルーツと呼ばれている。","cloze":{"start":8,"answer":"ことから","quiz":{"level":"N3","japanese":"形が星に似ていることからスターフルーツと呼ばれている。","german":"Because its shape resembles a star, it's called a star fruit.","start":8,"answer":"ことから","acceptedAnswers":["ことから","ので","ため"],"distractors":[{"text":"なことから","reason":"No な is inserted after the verb."},{"text":"ことをから","reason":"This is not a causal connection."},{"text":"ことからの","reason":"の does not connect a following predicate here."}]}},"romaji":"Katachi ga hoshi ni niteiru koto kara sutā furūtsu to yobareteiru.","german":"Because its shape resembles a star, it's called a star fruit."},{"japanese":"彼が犯人であることから逮捕された。","cloze":{"start":7,"answer":"ことから"},"romaji":"Kare ga hannin de aru koto kara taiho sareta.","german":"He was arrested on the grounds that he was the culprit."}],"notes":"Often used to explain names or origins.","related":["n4-tame-ni"]},
{"id":"n3-to-wa-kagiranai","pattern":"～とは限らない","level":"N3","category":"Satzstrukturen","meaning":"not necessarily, not always","explanation":"とは限らない: something does not apply in every case.","formation":"Verb/adj./noun + とは限らない","examples":[{"japanese":"高いものがいいとは限らない。","cloze":{"start":7,"answer":"とは限らない","quiz":{"level":"N3","japanese":"高いものがいいとは限らない。","german":"Expensive things aren't necessarily good.","start":7,"answer":"とは限らない","acceptedAnswers":["とは限らない"],"distractors":[{"text":"とは限る","reason":"This affirms the restriction instead of rejecting it."},{"text":"とは限るない","reason":"The negative form is 限らない."},{"text":"をは限らない","reason":"The quoted claim is connected with と."}]}},"romaji":"Takai mono ga ii to wa kagiranai.","german":"Expensive things aren't necessarily good."},{"japanese":"努力すれば成功するとは限らない。","cloze":{"start":9,"answer":"とは限らない"},"romaji":"Doryoku sureba seikō suru to wa kagiranai.","german":"Working hard doesn't necessarily mean you'll succeed."}],"notes":"Rejects an overly simple generalization.","related":["n3-wake-dewa-nai"]},
{"id":"n3-keigo-sonkei","pattern":"尊敬語 (Respektsprache)","level":"N3","category":"Satzstrukturen","meaning":"respectful form (for others)","explanation":"尊敬語 (そんけいご): elevates other people's actions to show respect.","formation":"お + Verb (ます-stem) + になる / 特別な形 (いらっしゃる, おっしゃる etc.)","examples":[{"japanese":"先生はもうお帰りになりました。","romaji":"Sensei wa mō okaeri ni narimashita.","german":"The teacher has already gone home (respectful).","cloze":{"start":5,"answer":"お帰りになりました","quiz":{"level":"N3","japanese":"先生はもうお帰りになりました。","german":"The teacher has already gone home (respectful).","start":5,"answer":"お帰りになりました","acceptedAnswers":["お帰りになりました","帰られました"],"distractors":[{"text":"お帰るになりました","reason":"お～になる requires the verb stem."},{"text":"お帰りになりませんでした","reason":"This negates going home."},{"text":"お帰りをなりました","reason":"The honorific expression uses に."}]}}},{"japanese":"社長がそうおっしゃいました。","romaji":"Shachō ga sō osshaimashita.","german":"The company president said so (respectful)."}],"notes":"Special forms: いる→いらっしゃる, 言う→おっしゃる, 食べる→召し上がる, する→なさる.","related":["n3-keigo-kenjou","keigo-sonkeigo-oninaru","keigo-sonkeigo-irassharu"]},
{"id":"n3-keigo-kenjou","pattern":"謙譲語 (Bescheidenheitssprache)","level":"N3","category":"Satzstrukturen","meaning":"humble form (for one's own actions)","explanation":"謙譲語 (けんじょうご): lowers your own actions to elevate the person you are talking to.","formation":"お + Verb (ます-stem) + する / 特別な形 (参る, 申す etc.)","examples":[{"japanese":"私がご案内いたします。","romaji":"Watashi ga go-annai itashimasu.","german":"I will show you the way (humble).","cloze":{"start":2,"answer":"ご案内いたします","quiz":{"level":"N3","japanese":"私がご案内いたします。","german":"I will show you the way (humble).","start":2,"answer":"ご案内いたします","acceptedAnswers":["ご案内いたします","ご案内します"],"distractors":[{"text":"ご案内いたしません","reason":"This negates showing the way."},{"text":"ご案内いたすます","reason":"The polite form is いたします."},{"text":"ご案内なります","reason":"Here the humble action is connected with いたす."}]}}},{"japanese":"明日お伺いしてもよろしいですか。","romaji":"Ashita oukagai shitemo yoroshii desu ka.","german":"May I visit you tomorrow (humble)?"}],"notes":"Special forms: 行く/来る→参る, 言う→申す, する→いたす, 見る→拝見する.","related":["n3-keigo-sonkei","keigo-kenjougo-osuru","keigo-kenjougo-mairu"]},
{"id":"n3-toshite-mo","pattern":"～にしても～にしても","level":"N3","category":"Satzstrukturen","meaning":"whether ... or ... (either way)","explanation":"にしても～にしても: whichever the alternative, the outcome is the same.","formation":"A + にしても + B + にしても","examples":[{"japanese":"行くにしても行かないにしても連絡してください。","romaji":"Iku ni shitemo ikanai ni shitemo renraku shite kudasai.","german":"Whether you go or not, please let me know.","cloze":{"start":2,"answer":"にしても","quiz":{"level":"N3","japanese":"行くにしても行かないにしても連絡してください。","german":"Whether you go or not, please let me know.","start":2,"answer":"にしても","acceptedAnswers":["にしても","としても"],"distractors":[{"text":"をしても","reason":"を does not form a hypothetical assumption here."},{"text":"にするても","reason":"The て-form of する is して."},{"text":"なにしても","reason":"No な is inserted after the verb."}]}}},{"japanese":"賛成にしても反対にしても理由を言ってください。","romaji":"Sansei ni shitemo hantai ni shitemo riyū o itte kudasai.","german":"Whether you're for or against it, please give your reason."}],"notes":"Similar: ～ても～ても, ～にせよ～にせよ.","related":["temo"]},
{"id":"n3-koto-ni-natte-iru","pattern":"～ことになっている","level":"N3","category":"Satzstrukturen","meaning":"to be planned/scheduled; to be the rule (extended)","explanation":"ことになっている at N3: extended use for plans and social norms.","formation":"Verb (辞書形) + ことになっている","examples":[{"japanese":"来月から新しいプロジェクトが始まることになっている。","romaji":"Raigetsu kara atarashii purojekuto ga hajimaru koto ni natte iru.","german":"A new project is scheduled to start next month.","cloze":{"start":17,"answer":"ことになっている","quiz":{"level":"N3","japanese":"来月から新しいプロジェクトが始まることになっている。","german":"A new project is scheduled to start next month.","start":17,"answer":"ことになっている","acceptedAnswers":["ことになっている"],"distractors":[{"text":"ことをなっている","reason":"The construction for something decided uses に."},{"text":"なことになっている","reason":"No な is inserted after the verb."},{"text":"ことになっていない","reason":"This denies the existing plan."}]}}},{"japanese":"日本では靴を脱ぐことになっている。","romaji":"Nihon de wa kutsu o nugu koto ni natte iru.","german":"In Japan, it's customary to take off your shoes."},{"japanese":"この学校では制服を着ることになっている。","romaji":"Kono gakkō de wa seifuku o kiru koto ni natteiru.","german":"At this school, you're supposed to wear a uniform."},{"japanese":"ここでは喫煙しないことになっています。","romaji":"Koko de wa kitsuen shinai koto ni natteimasu.","german":"Smoking is not allowed here."}],"notes":"A social norm or a fixed plan.","related":["n4-koto-ni-naru"],"legacyIds":["n4-koto-ni-natteiru"]},
{"id":"n3-tewa-tewa","pattern":"～ては～ては","level":"N3","category":"Satzstrukturen","meaning":"over and over, alternating","explanation":"ては～ては: two actions keep repeating in alternation.","formation":"Verb (て) + は + Verb (て) + は","examples":[{"japanese":"食べては寝て、食べては寝ての生活だ。","romaji":"Tabete wa nete, tabete wa nete no seikatsu da.","german":"It's a life of eating and sleeping, eating and sleeping.","cloze":{"start":2,"answer":"ては","quiz":{"level":"N3","japanese":"食べては寝て、食べては寝ての生活だ。","german":"It's a life of eating and sleeping, eating and sleeping.","start":2,"answer":"ては","acceptedAnswers":["ては"],"distractors":[{"text":"たは","reason":"The repeated sequence needs the て-form."},{"text":"ますは","reason":"ます does not link the repeated actions here."},{"text":"るては","reason":"食べるて is not a て-form."}]}}},{"japanese":"書いては消し、書いては消しの繰り返しだ。","romaji":"Kaite wa keshi, kaite wa keshi no kurikaeshi da.","german":"Writing and erasing, writing and erasing, over and over."}],"notes":"Expresses tiresome repetition.","related":["tari-tari"]},
{"id":"n3-you-ni-to","pattern":"～ように言う","level":"N3","category":"Satzstrukturen","meaning":"to tell/ask someone to do something","explanation":"ように言う: passing on an indirect request or instruction.","formation":"Verb (辞書形/ない形) + ように言う/頼む/注意する","examples":[{"japanese":"医者に運動するように言われた。","romaji":"Isha ni undō suru yō ni iwareta.","german":"The doctor told me to exercise.","cloze":{"start":7,"answer":"ように言われた","quiz":{"level":"N3","japanese":"医者に運動するように言われた。","german":"The doctor told me to exercise.","start":7,"answer":"ように言われた","acceptedAnswers":["ように言われた"],"distractors":[{"text":"ようを言われた","reason":"The reported request requires に."},{"text":"なように言われた","reason":"No な is inserted after the verb."},{"text":"ように言われなかった","reason":"This negates the doctor's instruction."}]}}},{"japanese":"子供に早く寝るように言った。","romaji":"Kodomo ni hayaku neru yō ni itta.","german":"I told the child to go to bed early."}],"notes":"Reported instructions. Also with 頼む, 注意する, etc.","related":["n4-you-ni-suru","n3-masu-you-ni"]},
{"id":"n3-koto-ni-suru-2","pattern":"～ことにしている","level":"N3","category":"Satzstrukturen","meaning":"to make it a rule to","explanation":"ことにしている: a personal rule or habit that you keep deliberately.","formation":"Verb (辞書形/ない形) + ことにしている","examples":[{"japanese":"毎朝ジョギングすることにしている。","romaji":"Maiasa jogingu suru koto ni shiteiru.","german":"I make it a rule to go jogging every morning.","cloze":{"start":9,"answer":"ことにしている","quiz":{"level":"N3","japanese":"毎朝ジョギングすることにしている。","german":"I make it a rule to go jogging every morning.","start":9,"answer":"ことにしている","acceptedAnswers":["ことにしている"],"distractors":[{"text":"ことをしている","reason":"The personal rule uses に."},{"text":"なことにしている","reason":"No な is inserted after the verb."},{"text":"ことにしていない","reason":"This negates the personal rule."}]}}},{"japanese":"夜九時以降はスマホを見ないことにしている。","romaji":"Yoru kuji ikō wa sumaho o minai koto ni shiteiru.","german":"I make a point of not looking at my phone after 9 p.m."}],"notes":"Emphasizes a conscious personal decision that has become a habit.","related":["n4-koto-ni-suru","n4-you-ni-shiteiru"]},
{"id":"n3-te-kara-de-nai-to","pattern":"～てからでないと","level":"N3","category":"Satzstrukturen","meaning":"not unless one first ...","explanation":"てからでないと: an action has to be completed first.","formation":"Verb (て-form) + からでないと/からでなければ","examples":[{"japanese":"調べてからでないと答えられない。","cloze":{"start":2,"answer":"てからでないと","quiz":{"level":"N3","japanese":"調べてからでないと答えられない。","german":"I can't answer until I've looked into it.","start":2,"answer":"てからでないと","acceptedAnswers":["てからでないと"],"distractors":[{"text":"たからでないと","reason":"This is not a connection for checking first."},{"text":"てからではあると","reason":"This is not a necessary precondition."},{"text":"ますからでないと","reason":"The time construction requires the て-form."}]}},"romaji":"Shirabete kara de nai to kotaerarenai.","german":"I can't answer until I've looked into it."},{"japanese":"食べてみてからでないと分からない。","cloze":{"start":4,"answer":"てからでないと"},"romaji":"Tabete mite kara de nai to wakaranai.","german":"I can't tell until I've tried it."}],"notes":"Condition: first X, then Y becomes possible.","related":["n4-ato-de"]},
{"id":"n3-nai-koto-ni-wa","pattern":"～ないことには","level":"N3","category":"Satzstrukturen","meaning":"unless one ..., not","explanation":"ないことには: without this precondition, the outcome is not possible.","formation":"Verb (ない形) + ことには","examples":[{"japanese":"やってみないことには分からない。","cloze":{"start":4,"answer":"ないことには","quiz":{"level":"N3","japanese":"やってみないことには分からない。","german":"You won't know until you try.","start":4,"answer":"ないことには","acceptedAnswers":["ないことには"],"distractors":[{"text":"ないことをは","reason":"The necessary precondition uses には."},{"text":"ないことなは","reason":"This is not a connection for the precondition."},{"text":"ないことにはだ","reason":"だ does not belong after the precondition expression."}]}},"romaji":"Yatte minai koto ni wa wakaranai.","german":"You won't know until you try."},{"japanese":"本人に聞かないことには確認できない。","cloze":{"start":5,"answer":"ないことには"},"romaji":"Honnin ni kikanai koto ni wa kakunin dekinai.","german":"I can't confirm it without asking the person themselves."}],"notes":"Emphasizes that a precondition is necessary.","related":["n3-te-kara-de-nai-to","n2-nai-kagiri","n2-you-dewa"]},
{"id":"n3-kara-koso","pattern":"～からこそ","level":"N3","category":"Satzstrukturen","meaning":"precisely because","explanation":"からこそ: puts strong emphasis on the reason. 'Precisely BECAUSE...'.","formation":"Verb/adj./noun + だからこそ","examples":[{"japanese":"好きだからこそ厳しくする。","cloze":{"start":3,"answer":"からこそ","quiz":{"level":"N3","japanese":"好きだからこそ厳しくする。","german":"It's precisely because I care about you that I'm strict.","start":3,"answer":"からこそ","acceptedAnswers":["からこそ"],"distractors":[{"text":"からをこそ","reason":"The emphatic causal form contains no を."},{"text":"からこその","reason":"の needs a noun, not 厳しくする."},{"text":"からこそだ","reason":"だ does not connect a following clause here."}]}},"romaji":"Suki da kara koso kibishiku suru.","german":"It's precisely because I care about you that I'm strict."},{"japanese":"失敗したからこそ学べたことがある。","cloze":{"start":4,"answer":"からこそ"},"romaji":"Shippai shita kara koso manabeta koto ga aru.","german":"There are things I was able to learn precisely because I failed."}],"notes":"Emphasizes the reason as especially important and positive.","related":["n4-koso","kara"]},
{"id":"n3-te-koso","pattern":"～てこそ","level":"N3","category":"Satzstrukturen","meaning":"only by (doing) ... (does it really)","explanation":"てこそ: only through this action does something become truly possible/worthwhile.","formation":"Verb (て-form) + こそ","examples":[{"japanese":"練習してこそ上手になる。","cloze":{"start":3,"answer":"てこそ","quiz":{"level":"N3","japanese":"練習してこそ上手になる。","german":"Only by practicing do you get good.","start":3,"answer":"てこそ","acceptedAnswers":["てこそ"],"distractors":[{"text":"たこそ","reason":"The necessary experience is connected with the て-form."},{"text":"ますこそ","reason":"ます is not a connection for 'only by' here."},{"text":"るてこそ","reason":"するて is not a て-form."}]}},"romaji":"Renshū shite koso jōzu ni naru.","german":"Only by practicing do you get good."},{"japanese":"自分でやってこそ意味がある。","cloze":{"start":5,"answer":"てこそ"},"romaji":"Jibun de yatte koso imi ga aru.","german":"It only has meaning if you do it yourself."}],"notes":"Emphasizes that the action is an indispensable precondition.","related":["n4-koso","n3-kara-koso"]},
{"id":"n3-kkonai","pattern":"～っこない","level":"N2","category":"Satzstrukturen","meaning":"no way that, absolutely impossible","explanation":"っこない: colloquial, expresses absolute impossibility.","formation":"Verb (ます-stem) + っこない","examples":[{"japanese":"そんな難しい試験、受かりっこない。","cloze":{"start":12,"answer":"っこない","quiz":{"level":"N2","japanese":"そんな難しい試験、受かりっこない。","german":"An exam that hard? There's no way I'll pass.","start":12,"answer":"っこない","acceptedAnswers":["っこない"],"distractors":[{"text":"っこある","reason":"The fixed emphatic negative is っこない."},{"text":"っこないだ","reason":"No だ follows ない."},{"text":"るっこない","reason":"っこない follows the stem 受かり."}]}},"romaji":"Sonna muzukashii shiken, ukarikkonai.","german":"An exam that hard? There's no way I'll pass."},{"japanese":"あの人に勝てっこない。","cloze":{"start":6,"answer":"っこない"},"romaji":"Ano hito ni katekkonai.","german":"There's no way I can beat that person."}],"notes":"Very colloquial. Stronger than ～はずがない.","related":["n3-you-ga-nai","n4-hazu-ga-nai","n2-ta-mono-dewa-nai"]},
{"id":"n3-ni-kawatte","pattern":"～にかわって / ～にかわり","level":"N3","category":"Partikel","meaning":"instead of, on behalf of","explanation":"にかわって: someone takes over another person's role or position.","formation":"Noun + にかわって/にかわり","examples":[{"japanese":"社長にかわって副社長が挨拶した。","cloze":{"start":2,"answer":"にかわって","quiz":{"level":"N3","japanese":"社長にかわって副社長が挨拶した。","german":"The vice president gave the greeting on behalf of the president.","start":2,"answer":"にかわって","acceptedAnswers":["にかわって","のかわりに","に代わって"],"distractors":[{"text":"に加えて","reason":"This adds the vice president instead of standing in for the president."},{"text":"をかわって","reason":"The expression for standing in uses に."},{"text":"にかわるて","reason":"The て-form of かわる is かわって."}]}},"romaji":"Shachō ni kawatte fukushachō ga aisatsu shita.","german":"The vice president gave the greeting on behalf of the president."},{"japanese":"手紙にかわってメールが普及した。","cloze":{"start":2,"answer":"にかわって"},"romaji":"Tegami ni kawatte mēru ga fukyū shita.","german":"Email has spread and replaced letters."},{"japanese":"社長にかわって、副社長が挨拶した。","romaji":"Shachō ni kawatte, fuku-shachō ga aisatsu shita.","german":"The vice president gave the greeting on behalf of the president."},{"japanese":"手紙にかわって、メールが主な連絡手段になった。","romaji":"Tegami ni kawatte, mēru ga omo na renraku shudan ni natta.","german":"Email has replaced letters as the main means of communication."}],"notes":"Also: ～のかわりに (more informal).","related":["n3-kawari-ni"],"legacyIds":["n2-ni-kawatte"]},
{"id":"n3-kawari-ni","pattern":"～かわりに","level":"N3","category":"Satzstrukturen","meaning":"instead of; in return for","explanation":"かわりに: 1) instead of doing something, 2) in return.","formation":"Verb (辞書形) + かわりに / Noun + のかわりに","examples":[{"japanese":"車を買うかわりに自転車にした。","cloze":{"start":4,"answer":"かわりに","quiz":{"level":"N3","japanese":"車を買うかわりに自転車にした。","german":"Instead of buying a car, I went with a bicycle.","start":4,"answer":"かわりに","acceptedAnswers":["かわりに"],"distractors":[{"text":"なかわりに","reason":"No な is inserted after the verb."},{"text":"かわりを","reason":"を does not form an 'instead of' connection here."},{"text":"かわりの","reason":"の needs a following noun."}]}},"romaji":"Kuruma o kau kawari ni jitensha ni shita.","german":"Instead of buying a car, I went with a bicycle."},{"japanese":"手伝ってあげるかわりに、ご飯をおごって。","cloze":{"start":7,"answer":"かわりに"},"romaji":"Tetsudatte ageru kawari ni, gohan o ogotte.","german":"In return for my helping you, treat me to a meal."}],"notes":"An exchange/something in return, or an alternative.","related":["n3-ni-kawatte"]},
{"id":"n3-o-kikkake-ni","pattern":"～をきっかけに","level":"N3","category":"Partikel","meaning":"triggered by, prompted by","explanation":"をきっかけに: an event becomes the trigger for a change.","formation":"Noun/verb (た形) + のをきっかけに","examples":[{"japanese":"留学をきっかけに日本語を勉強し始めた。","cloze":{"start":2,"answer":"をきっかけに","quiz":{"level":"N3","japanese":"留学をきっかけに日本語を勉強し始めた。","german":"Studying abroad was what got me to start learning Japanese.","start":2,"answer":"をきっかけに","acceptedAnswers":["をきっかけに"],"distractors":[{"text":"をきっかけな","reason":"The adverbial trigger expression requires に."},{"text":"がきっかけを","reason":"This is not an adverbial connection."},{"text":"をきっかけの","reason":"The attributive form would be をきっかけにした, not をきっかけの."}]}},"romaji":"Ryūgaku o kikkake ni nihongo o benkyō shi hajimeta.","german":"Studying abroad was what got me to start learning Japanese."},{"japanese":"病気をきっかけに生活を見直した。","cloze":{"start":2,"answer":"をきっかけに"},"romaji":"Byōki o kikkake ni seikatsu o minaoshita.","german":"My illness prompted me to rethink my lifestyle."}],"notes":"The trigger is usually a single, concrete event.","related":[]},
{"id":"n3-o-towazu","pattern":"～を問わず","level":"N2","category":"Partikel","meaning":"regardless of, irrespective of","explanation":"を問わず: it doesn't matter which case applies.","formation":"Noun + を問わず","examples":[{"japanese":"年齢を問わず参加できます。","cloze":{"start":2,"answer":"を問わず","quiz":{"level":"N2","japanese":"年齢を問わず参加できます。","german":"Anyone can take part, regardless of age.","start":2,"answer":"を問わず","acceptedAnswers":["を問わず"],"distractors":[{"text":"を問うず","reason":"The negative form of 問う is 問わず."},{"text":"に問わず","reason":"The set phrase uses を."},{"text":"を問わずだ","reason":"だ does not connect a following clause here."}]}},"romaji":"Nenrei o towazu sanka dekimasu.","german":"Anyone can take part, regardless of age."},{"japanese":"経験の有無を問わず応募できる。","cloze":{"start":5,"answer":"を問わず"},"romaji":"Keiken no umu o towazu ōbo dekiru.","german":"Anyone can apply, with or without experience."}],"notes":"Formal. Common: 国籍を問わず, 男女を問わず.","related":["n3-ni-kakawarazu"]},
{"id":"n3-ni-kakawarazu","pattern":"～にかかわらず","level":"N2","category":"Partikel","meaning":"regardless of, whether or not","explanation":"にかかわらず: the outcome doesn't change, whatever the condition.","formation":"Noun + にかかわらず / Verb (辞書形/ない形) + にかかわらず","examples":[{"japanese":"天気にかかわらず試合は行われる。","cloze":{"start":2,"answer":"にかかわらず","quiz":{"level":"N2","japanese":"天気にかかわらず試合は行われる。","german":"The match will be held regardless of the weather.","start":2,"answer":"にかかわらず","acceptedAnswers":["にかかわらず"],"distractors":[{"text":"にかかわるず","reason":"The negative form is かかわらず."},{"text":"をかかわらず","reason":"The set phrase uses に."},{"text":"にかかわらずの","reason":"の does not attach to a verb here."}]}},"romaji":"Tenki ni kakawarazu shiai wa okonawareru.","german":"The match will be held regardless of the weather."},{"japanese":"賛成するしないにかかわらず出席してください。","cloze":{"start":7,"answer":"にかかわらず"},"romaji":"Sansei suru shinai ni kakawarazu shusseki shite kudasai.","german":"Please attend, whether you agree or not."}],"notes":"More formal than ～に関係なく. Don't confuse it with ～にもかかわらず (despite).","related":["n3-o-towazu","n3-ni-mo-kakawarazu"]},
{"id":"n3-ni-sotte","pattern":"～に沿って","level":"N3","category":"Partikel","meaning":"along; in line with, in accordance with","explanation":"に沿って: following a line, a plan or a guideline.","formation":"Noun + に沿って / に沿った + Noun","examples":[{"japanese":"川に沿って歩いた。","cloze":{"start":1,"answer":"に沿って","quiz":{"level":"N3","japanese":"川に沿って歩いた。","german":"I walked along the river.","start":1,"answer":"に沿って","acceptedAnswers":["に沿って"],"distractors":[{"text":"から離れて","reason":"This means away from the river instead of along it."},{"text":"に沿うて","reason":"The standard て-form is 沿って."},{"text":"を沿って","reason":"沿う is connected with に here."}]}},"romaji":"Kawa ni sotte aruita.","german":"I walked along the river."},{"japanese":"計画に沿って進めてください。","cloze":{"start":2,"answer":"に沿って"},"romaji":"Keikaku ni sotte susumete kudasai.","german":"Please proceed according to the plan."}],"notes":"Works both concretely (a river) and abstractly (a plan).","related":["n3-ni-shitagatte"]},
{"id":"n3-ta-tokoro-de","pattern":"～たところで","level":"N3","category":"Satzstrukturen","meaning":"even if one does ... (pointless)","explanation":"たところで: even if you do something, nothing changes / it's pointless.","formation":"Verb (た形) + ところで","examples":[{"japanese":"今更謝ったところで許してもらえない。","cloze":{"start":4,"answer":"たところで","quiz":{"level":"N3","japanese":"今更謝ったところで許してもらえない。","german":"Even if I apologize now, they won't forgive me.","start":4,"answer":"たところで","acceptedAnswers":["たところで"],"distractors":[{"text":"るところで","reason":"謝っる is not a verb form."},{"text":"たところをで","reason":"を does not go before the concessive ending で."},{"text":"ますところで","reason":"謝っます is not a verb form."}]}},"romaji":"Imasara ayamatta tokoro de yurushite moraenai.","german":"Even if I apologize now, they won't forgive me."},{"japanese":"急いだところで間に合わない。","romaji":"Isoida tokoro de maniawanai.","german":"Even if I hurry, I won't make it in time."}],"notes":"Always a negative/resigned outcome.","related":["temo","n3-ta-tokoro"]},
{"id":"n3-oki-ni","pattern":"～おきに","level":"N3","category":"Satzstrukturen","meaning":"every ... (interval)","explanation":"おきに: expresses regular intervals.","formation":"Number + time unit + おきに","examples":[{"japanese":"二時間おきに薬を飲んでください。","cloze":{"start":3,"answer":"おきに","quiz":{"level":"N3","japanese":"二時間おきに薬を飲んでください。","german":"Please take the medicine every two hours.","start":3,"answer":"おきに","acceptedAnswers":["おきに","ごとに"],"distractors":[{"text":"おきな","reason":"The interval expression requires に."},{"text":"おきを","reason":"を does not form an interval expression here."},{"text":"前に","reason":"This means two hours ago instead of every two hours."}]}},"romaji":"Nijikan oki ni kusuri o nonde kudasai.","german":"Please take the medicine every two hours."},{"japanese":"一日おきにジョギングしている。","cloze":{"start":2,"answer":"おきに"},"romaji":"Ichinichi oki ni jogingu shiteiru.","german":"I go jogging every other day."}],"notes":"一日おきに = every other day. 一つおきに = every other one.","related":["n4-zutsu"]},
{"id":"n3-to-iu-mono-da","pattern":"～というものだ","level":"N3","category":"Satzstrukturen","meaning":"that's what ... is (the true nature of)","explanation":"というものだ: emphasizes the true nature or essence of something.","formation":"Noun/clause + というものだ","examples":[{"japanese":"それが本当の友情というものだ。","cloze":{"start":8,"answer":"というものだ","quiz":{"level":"N3","japanese":"それが本当の友情というものだ。","german":"That is true friendship.","start":8,"answer":"というものだ","acceptedAnswers":["というものだ"],"distractors":[{"text":"をいうものだ","reason":"The defining expression uses と."},{"text":"というものをだ","reason":"を does not go before this copula."},{"text":"というものな","reason":"This is not a sentence ending here."}]}},"romaji":"Sore ga hontō no yūjō to iu mono da.","german":"That is true friendship."},{"japanese":"人生とはそういうものだ。","romaji":"Jinsei to wa sō iu mono da.","german":"That's just how life is."}],"notes":"Philosophical/instructive. というものではない = it's not that simple.","related":["n4-toiu"]},
{"id":"n3-ba-ii-noni","pattern":"～ばいいのに","level":"N3","category":"Satzstrukturen","meaning":"I wish, if only","explanation":"ばいいのに: expresses an unfulfilled wish or regret.","formation":"Verb (ば-form) + いいのに","examples":[{"japanese":"もっと早く言えばいいのに。","cloze":{"start":7,"answer":"ばいいのに","quiz":{"level":"N3","japanese":"もっと早く言えばいいのに。","german":"If only you'd said so sooner.","start":7,"answer":"ばいいのに","acceptedAnswers":["ばいいのに","ばよかったのに","たらいいのに"],"distractors":[{"text":"ばいいますのに","reason":"The adjective いい does not take ます."},{"text":"ばいいなに","reason":"The fixed wish expression is のに."},{"text":"ばいかったのに","reason":"The past of いい is よかった."}]}},"romaji":"Motto hayaku ieba ii noni.","german":"If only you'd said so sooner."},{"japanese":"毎日晴れればいいのに。","cloze":{"start":5,"answer":"ばいいのに"},"romaji":"Mainichi harereba ii noni.","german":"I wish it were sunny every day."}],"notes":"Your own wish, or a reproach to someone else.","related":["n4-ba-yokatta","n4-ba","n3-tara-ii-ba-ii"]},
{"id":"n3-o-komete","pattern":"～を込めて","level":"N3","category":"Partikel","meaning":"with (feeling/effort) put into it","explanation":"を込めて: something is done with a particular feeling or effort put into it.","formation":"Noun + を込めて","examples":[{"japanese":"心を込めて作りました。","cloze":{"start":1,"answer":"を込めて","quiz":{"level":"N3","japanese":"心を込めて作りました。","german":"I made it with all my heart.","start":1,"answer":"を込めて","acceptedAnswers":["を込めて"],"distractors":[{"text":"を込めるて","reason":"The て-form of 込める is 込めて."},{"text":"が込めて","reason":"The feeling put into it is marked with を."},{"text":"を込めずに","reason":"This means without putting your heart into it, which contradicts the translation."}]}},"romaji":"Kokoro o komete tsukurimashita.","german":"I made it with all my heart."},{"japanese":"感謝の気持ちを込めてプレゼントを贈った。","cloze":{"start":6,"answer":"を込めて"},"romaji":"Kansha no kimochi o komete purezento o okutta.","german":"I gave a present as a token of my gratitude."}],"notes":"心を込めて (wholeheartedly), 願いを込めて (with a wish).","related":[]},
{"id":"n3-ayamaru","pattern":"謝る / ～てすみません","level":"N3","category":"Verben","meaning":"to apologize","explanation":"謝る (あやまる): to apologize. Japanese has various ways of apologizing depending on the situation and level of politeness.","formation":"謝る / ～てすみません / ～て申し訳ありません / ～てごめんなさい","examples":[{"japanese":"遅れたことを謝った。","romaji":"Okureta koto o ayamatta.","german":"I apologized for being late."},{"japanese":"ご迷惑をおかけして申し訳ありません。","romaji":"Gomeiwaku o okake shite mōshiwake arimasen.","german":"I'm sorry for the inconvenience."},{"japanese":"遅くなってすみません。","cloze":{"start":4,"answer":"てすみません","quiz":{"level":"N3","japanese":"遅くなってすみません。","german":"Sorry I'm late.","start":4,"answer":"てすみません","acceptedAnswers":["てすみません"],"distractors":[{"text":"たすみません","reason":"An apology for a circumstance needs the て-connection."},{"text":"ますすみません","reason":"The ます-form does not form a connection here."},{"text":"てすみます","reason":"This is not a form of apology."}]}},"romaji":"Osoku natte sumimasen.","german":"Sorry I'm late."}],"notes":"Politeness: ごめん(なさい) < すみません < 申し訳ありません/ございません. 謝る is the verb 'to apologize'.","related":[]},
{"id":"n3-ni-totte-no","pattern":"～にとっての","level":"N3","category":"Partikel","meaning":"for ... (attributive)","explanation":"にとっての: attributive form of にとって, used before nouns.","formation":"Noun + にとっての + Noun","examples":[{"japanese":"私にとっての幸せは家族と過ごすことだ。","cloze":{"start":1,"answer":"にとっての","quiz":{"level":"N3","japanese":"私にとっての幸せは家族と過ごすことだ。","german":"For me, happiness is spending time with my family.","start":1,"answer":"にとっての","acceptedAnswers":["にとっての"],"distractors":[{"text":"にとってな","reason":"The attributive perspective is connected with の."},{"text":"にとってを","reason":"を does not fit before 幸せ here."},{"text":"をとっての","reason":"を取っての is not the perspective construction here."}]}},"romaji":"Watashi ni totte no shiawase wa kazoku to sugosu koto da.","german":"For me, happiness is spending time with my family."},{"japanese":"学生にとっての最大の課題は就職だ。","cloze":{"start":2,"answer":"にとっての"},"romaji":"Gakusei ni totte no saidai no kadai wa shūshoku da.","german":"The biggest challenge for students is finding a job."}],"notes":"にとって + clause vs. にとっての + noun.","related":["n4-ni-totte"]},
{"id":"n5-kore-sore-are-dore","pattern":"これ / それ / あれ / どれ","level":"N5","category":"Satzstrukturen","meaning":"this / that (near you) / that (over there) / which one","explanation":"These demonstrative pronouns stand alone in place of a noun. こ- points to something near the speaker, そ- to something near the listener, and あ- to something far from both. どれ asks which thing out of three or more is meant.","formation":"これ / それ / あれ / どれ + particle (は, が, を …) – with no noun after it","examples":[{"japanese":"あなたのかばんはどれですか。","romaji":"Anata no kaban wa dore desu ka.","german":"Which one is your bag?","cloze":{"start":8,"answer":"どれ","quiz":{"level":"N5","japanese":"あなたのかばんはどれですか。","german":"Which one is your bag?","start":8,"answer":"どれ","acceptedAnswers":["どれ","どちら"],"distractors":[{"text":"どの","reason":"どの must come directly before a noun (どのかばん) and cannot stand alone."},{"text":"どんな","reason":"どんな asks about the kind of thing and needs a following noun."},{"text":"だれ","reason":"だれ asks about a person, not a bag."}],"promptKana":"あなたのかばんは＿＿＿ですか。"}}},{"japanese":"これは日本のお茶です。","romaji":"Kore wa Nihon no ocha desu.","german":"This is Japanese tea."},{"japanese":"すみません、それをください。","romaji":"Sumimasen, sore o kudasai.","german":"Excuse me, I'd like that one (near you), please."}],"notes":"これ/それ/あれ/どれ are never directly followed by a noun: not *これ本, but この本 (→ この/その/あの/どの). As the subject of a question, どれ takes が, not は: どれがいいですか. When there are only two options, you ask with どちら/どっち. To the question それは何ですか you answer with これは…, because the perspective switches.","related":["n5-kono-sono-ano-dono","n5-koko-soko-asoko-doko","donna"]},
{"id":"n5-kono-sono-ano-dono","pattern":"この / その / あの / どの","level":"N5","category":"Satzstrukturen","meaning":"this ... / that ... (near you) / that ... (over there) / which ...","explanation":"この, その, あの and どの always come directly before a noun and specify it – like 'this' and 'that' in 'this book' or 'that book'. The distance follows the same こ-そ-あ system as これ/それ/あれ. どの asks which thing out of a group is meant.","formation":"この / その / あの / どの + Noun","examples":[{"japanese":"あの人はだれですか。","romaji":"Ano hito wa dare desu ka.","german":"Who is that person over there?","cloze":{"start":0,"answer":"あの","quiz":{"level":"N5","japanese":"あの人はだれですか。","german":"Who is that person over there?","start":0,"answer":"あの","acceptedAnswers":["あの"],"distractors":[{"text":"あれ","reason":"あれ stands alone and cannot directly modify a noun like 人."},{"text":"あそこ","reason":"あそこ is a place word and cannot come directly before a noun like 人."},{"text":"あちら","reason":"あちら is a direction/place word and cannot come directly before 人."}],"promptKana":"＿＿＿ひとはだれですか。"}}},{"japanese":"この本はとてもおもしろいです。","romaji":"Kono hon wa totemo omoshiroi desu.","german":"This book is very interesting."},{"japanese":"どの電車に乗りますか。","romaji":"Dono densha ni norimasu ka.","german":"Which train are you taking?"}],"notes":"この/その/あの/どの can never stand alone: not *このは…, but これは…. To talk about something both speakers know but can't see at the moment, you use あの: あの店、おいしかったね (That place back then was good, wasn't it?). あのう… is also a typical filler when addressing someone.","related":["n5-kore-sore-are-dore","n5-koko-soko-asoko-doko","donna"]},
{"id":"n5-koko-soko-asoko-doko","pattern":"ここ / そこ / あそこ / どこ","level":"N5","category":"Satzstrukturen","meaning":"here / there (near you) / over there / where","explanation":"ここ, そこ, あそこ and どこ are place words following the こ-そ-あ-ど system: ここ is the place near the speaker, そこ the place near the listener, あそこ a place far from both. どこ asks about the place. They behave like nouns and take particles such as に, で or へ.","formation":"ここ / そこ / あそこ / どこ + particle (は, に, で, へ, から …) or + です","examples":[{"japanese":"トイレはどこですか。","romaji":"Toire wa doko desu ka.","german":"Where is the restroom?","cloze":{"start":4,"answer":"どこ","quiz":{"level":"N5","japanese":"トイレはどこですか。","german":"Where is the restroom?","start":4,"answer":"どこ","acceptedAnswers":["どこ","どちら"],"distractors":[{"text":"どの","reason":"どの needs a following noun and cannot stand alone before です."},{"text":"いつ","reason":"いつ asks about time, not place."},{"text":"だれ","reason":"だれ asks about a person, not a place."}],"promptKana":"トイレは＿＿＿ですか。"}}},{"japanese":"ここで写真を撮ってもいいですか。","romaji":"Koko de shashin o totte mo ii desu ka.","german":"May I take pictures here?"},{"japanese":"駅はあそこです。","romaji":"Eki wa asoko desu.","german":"The station is over there."}],"notes":"The polite equivalents are こちら/そちら/あちら/どちら – common in shops and on the phone (お手洗いはどちらですか). Colloquial: こっち/そっち/あっち/どっち. そこ also refers to a place the other person has just mentioned: 「京都に住んでいます。」「そこはどんな所ですか。」","related":["n5-kore-sore-are-dore","n5-kono-sono-ano-dono","ni"]},
{"id":"n5-goro","pattern":"～ごろ","level":"N5","category":"Partikel","meaning":"around, about (point in time)","explanation":"ごろ is attached to a time expression and makes it approximate: 三時ごろ = around three o'clock. It only works with points in time such as clock times, days, months or years, not with durations or amounts. It can be followed by に, but this is often dropped.","formation":"Point in time + ごろ (+ に)","examples":[{"japanese":"毎晩十一時ごろ寝ます。","romaji":"Maiban jūichi-ji goro nemasu.","german":"I go to bed around eleven every night.","cloze":{"start":5,"answer":"ごろ","quiz":{"level":"N5","japanese":"毎晩十一時ごろ寝ます。","german":"I go to bed around eleven every night.","start":5,"answer":"ごろ","acceptedAnswers":["ごろ","ごろに"],"distractors":[{"text":"ころ","reason":"After a time expression, the suffix is voiced: ごろ."},{"text":"ずつ","reason":"ずつ distributes amounts evenly and does not fit a clock time."},{"text":"しか","reason":"しか requires a negative form and means 'only'."}],"promptKana":"まいばんじゅういちじ＿＿＿ねます。"}}},{"japanese":"日本には四月ごろ行きたいです。","romaji":"Nihon ni wa shigatsu goro ikitai desu.","german":"I'd like to go to Japan around April."},{"japanese":"昼ごろ駅で会いましょう。","romaji":"Hiru goro eki de aimashō.","german":"Let's meet at the station around noon."}],"notes":"ごろ = approximate point in time, ぐらい/くらい = approximate amount or duration: 三時ごろ (around three o'clock) vs. 三時間ぐらい (about three hours). In everyday speech you also hear 三時ぐらい, but the textbook form for points in time is ごろ. Don't combine it with durations (*二時間ごろ). As a word on its own it is ころ: 子供のころ (when I was a child).","related":["n3-kurai-gurai","ni"]},
{"id":"n5-amari-nai","pattern":"あまり～ない","level":"N5","category":"Satzstrukturen","meaning":"not very, not particularly","explanation":"あまり comes before a negated verb or adjective and softens the negation: 'not particularly, not often, not much'. This makes a negative statement sound soft and polite. In this meaning, あまり always needs a negative form.","formation":"あまり + Verb (ない / ません) / あまり + い-adj. (～くない) / あまり + な-adj. (～じゃない)","examples":[{"japanese":"この映画はあまりおもしろくなかったです。","romaji":"Kono eiga wa amari omoshiroku nakatta desu.","german":"This movie wasn't very interesting.","cloze":{"start":5,"answer":"あまり","quiz":{"level":"N5","japanese":"この映画はあまりおもしろくなかったです。","german":"This movie wasn't very interesting.","start":5,"answer":"あまり","acceptedAnswers":["あまり","あんまり"],"distractors":[{"text":"とても","reason":"とても intensifies positive statements; before a negative it does not give 'not particularly'."},{"text":"たくさん","reason":"たくさん expresses a quantity and cannot grade an adjective."},{"text":"よく","reason":"よく means 'often' or 'well' and does not fit before おもしろくなかった."}],"promptKana":"このえいがは＿＿＿おもしろくなかったです。"}}},{"japanese":"私はお酒をあまり飲みません。","romaji":"Watashi wa osake o amari nomimasen.","german":"I don't drink much alcohol."},{"japanese":"今日はあまり寒くないですね。","romaji":"Kyō wa amari samuku nai desu ne.","german":"It's not very cold today, is it?"}],"notes":"Degrees: 全然～ない (not at all) is stronger than あまり～ない (not particularly). Colloquially often あんまり. To questions like 好きですか, answering あまり… is an evasive, polite alternative to a blunt いいえ. With a positive form, あまり(に) means 'far too much' – a different, more advanced use.","related":["n5-zenzen-nai","i-adj-negative","masen","n3-kesshite-nai"]},
{"id":"n5-zenzen-nai","pattern":"全然～ない","level":"N5","category":"Satzstrukturen","meaning":"not at all","explanation":"全然 (ぜんぜん) strengthens a negation to 'not at all'. It comes before a negated verb or adjective and is very common in conversation. In formal texts, まったく～ない is preferred.","formation":"全然 + Verb (ない / ません) / 全然 + い-adj. (～くない) / 全然 + な-adj. (～じゃない)","examples":[{"japanese":"このカレーはぜんぜん辛くないです。","romaji":"Kono karē wa zenzen karaku nai desu.","german":"This curry isn't spicy at all.","cloze":{"start":6,"answer":"ぜんぜん","quiz":{"level":"N5","japanese":"このカレーはぜんぜん辛くないです。","german":"This curry isn't spicy at all.","start":6,"answer":"ぜんぜん","acceptedAnswers":["ぜんぜん","全然","まったく","ちっとも","すこしも"],"distractors":[{"text":"とても","reason":"とても comes before positive adjectives; with 辛くない it does not make a natural sentence."},{"text":"いっぱい","reason":"いっぱい expresses a quantity and cannot intensify an adjective."},{"text":"よく","reason":"よく means 'often' or 'well' and cannot intensify 辛くない."}],"promptKana":"このカレーは＿＿＿からくないです。"}}},{"japanese":"テレビはぜんぜん見ません。","romaji":"Terebi wa zenzen mimasen.","german":"I don't watch TV at all."},{"japanese":"テストはぜんぜんわかりませんでした。","romaji":"Tesuto wa zenzen wakarimasen deshita.","german":"I didn't understand the test at all."}],"notes":"In today's colloquial Japanese you also hear 全然 with positive statements: 全然大丈夫 (totally fine) – usually to ease the other person's worry. In exams and polite speech, however, the rule is 全然 + negative. Degrees: 全然～ない > あまり～ない. Written language: まったく～ない.","related":["n5-amari-nai","i-adj-negative","n3-kesshite-nai"]},
{"id":"n5-ka-ka","pattern":"～か～か","level":"N5","category":"Partikel","meaning":"either ... or ...; whether ... or ...","explanation":"か between two options means 'or': AかB. When two clauses with か follow each other (…か…か), you get 'whether ... or ...' for something that is still open. Unlike や, か names alternatives of which only one applies.","formation":"Noun + か + Noun / Clause (plain form) + か + Clause (plain form) + か","examples":[{"japanese":"パーティーに行くか行かないか、まだ決めていません。","romaji":"Pātī ni iku ka ikanai ka, mada kimete imasen.","german":"I haven't decided yet whether I'll go to the party or not.","cloze":{"start":8,"answer":"か","quiz":{"level":"N5","japanese":"パーティーに行くか行かないか、まだ決めていません。","german":"I haven't decided yet whether I'll go to the party or not.","start":8,"answer":"か","acceptedAnswers":["か"],"distractors":[{"text":"と","reason":"と joins nouns ('and'), but not two clauses as alternatives."},{"text":"や","reason":"や only lists nouns and cannot come after a verb."},{"text":"が","reason":"With が you do not get 'whether ... or'; the sentence becomes ungrammatical."}],"promptKana":"パーティーにいく＿＿＿いかないか、まだきめていません。"}}},{"japanese":"毎朝パンかごはんを食べます。","romaji":"Maiasa pan ka gohan o tabemasu.","german":"Every morning I eat bread or rice."},{"japanese":"月曜日か火曜日に電話します。","romaji":"Getsuyōbi ka kayōbi ni denwa shimasu.","german":"I'll call on Monday or Tuesday."}],"notes":"AかB: only one of the two. AやB: examples from a larger set. AとB: both, a complete list. With two clauses, か comes at both ends (行くか行かないか); the second か must not be left out. For 'whether or not' there is also the shorter form ～かどうか (N4).","related":["ka","ya","n4-ka-dou-ka"]},
{"id":"n5-tachi","pattern":"～たち","level":"N5","category":"Partikel","meaning":"plural suffix for people","explanation":"たち is attached to pronouns and words for people to turn them into a group: 私たち (we), 子供たち (the children). Japanese nouns otherwise have no plural, so たち is optional and is used almost only for people and animals.","formation":"Pronoun / word for a person / name + たち","examples":[{"japanese":"私たちは同じクラスです。","romaji":"Watashitachi wa onaji kurasu desu.","german":"We're in the same class.","cloze":{"start":1,"answer":"たち","quiz":{"level":"N5","japanese":"私たちは同じクラスです。","german":"We're in the same class.","start":1,"answer":"たち","acceptedAnswers":["たち"],"distractors":[{"text":"さん","reason":"さん is an honorific suffix for others and is never attached to 私."},{"text":"がた","reason":"がた is respectful and is only used for others (あなたがた), not for yourself."},{"text":"ごろ","reason":"ごろ makes points in time approximate and does not fit people."}],"promptKana":"わたし＿＿＿はおなじクラスです。"}}},{"japanese":"子供たちが公園で遊んでいます。","romaji":"Kodomotachi ga kōen de asonde imasu.","german":"The children are playing in the park."},{"japanese":"田中さんたちはもう帰りました。","romaji":"Tanaka-san-tachi wa mō kaerimashita.","german":"Tanaka and the others have already gone home."}],"notes":"After a name, たち means 'X and their group': 田中さんたち are not several Tanakas. たち is not normally used for objects (*本たち) – the noun stays unchanged. Respectful for others: ～がた (先生がた, あなたがた); casual: ～ら (僕ら).","related":["counters"]},
{"id":"n5-chuu-juu","pattern":"～中 (じゅう・ちゅう)","level":"N5","category":"Partikel","meaning":"throughout, all over (じゅう) · in progress (ちゅう)","explanation":"Read じゅう, 中 means 'whole, throughout': 一日中 (all day long), 世界中 (all over the world). Read ちゅう, it means 'in the middle of, in progress': 電話中 (on the phone right now), 会議中. Which reading applies depends on the word.","formation":"Time period / place + 中 (じゅう) / Action noun + 中 (ちゅう)","examples":[{"japanese":"田中さんは今、電話中です。","romaji":"Tanaka-san wa ima, denwa-chū desu.","german":"Mr. Tanaka is on the phone right now.","cloze":{"start":9,"answer":"中","quiz":{"level":"N5","japanese":"田中さんは今、電話中です。","german":"Mr. Tanaka is on the phone right now.","start":9,"answer":"中","acceptedAnswers":["中"],"distractors":[{"text":"間","reason":"間 (かん) comes after durations like 三日間 and does not form 'in the middle of a phone call'."},{"text":"ごろ","reason":"ごろ makes points in time approximate and does not fit an activity."},{"text":"たち","reason":"たち forms the plural of people and does not fit 電話."}],"promptKana":"たなかさんはいま、でんわ＿＿＿です。"}}},{"japanese":"昨日は一日中雨でした。","romaji":"Kinō wa ichinichijū ame deshita.","german":"Yesterday it rained all day."},{"japanese":"この歌は世界中で有名です。","romaji":"Kono uta wa sekaijū de yūmei desu.","german":"This song is famous all over the world."}],"notes":"Rule of thumb: じゅう with time periods and places (一年中, 日本中, 家中), ちゅう with ongoing activities (授業中, 食事中, 工事中). On signs: 営業中 (open), 準備中 (in preparation). 今日中に (きょうじゅうに) means 'by the end of today'. Don't confuse it with 中 (なか) = 'in, inside'.","related":["te-iru","n3-saichuu"]},
{"id":"n5-adverb-ku-ni","pattern":"～く / ～に (Adverb)","level":"N5","category":"Adjektive","meaning":"adjective as adverb (quickly, quietly ...)","explanation":"To describe a verb more closely, an い-adjective becomes ～く (早い → 早く) and a な-adjective becomes ～に (静か → 静かに). This is how 'quick' becomes 'quickly' and 'quiet' becomes 'quietly' (as in 'speak quietly'). The adverb comes before the verb.","formation":"い-adj.: い → く + Verb (早い → 早く) / な-adj. + に + Verb (静か → 静かに) / Exception: いい → よく","examples":[{"japanese":"図書館では静かに話してください。","romaji":"Toshokan de wa shizuka ni hanashite kudasai.","german":"Please speak quietly in the library.","cloze":{"start":7,"answer":"に","quiz":{"level":"N5","japanese":"図書館では静かに話してください。","german":"Please speak quietly in the library.","start":7,"answer":"に","acceptedAnswers":["に"],"distractors":[{"text":"な","reason":"な only goes between a な-adjective and a noun (静かな部屋), not before a verb."},{"text":"で","reason":"静かで is the て-form and links clauses, but does not describe the speaking."},{"text":"く","reason":"～く is the adverb form of い-adjectives; 静か is a な-adjective."}],"promptKana":"としょかんではしずか＿＿＿はなしてください。"}}},{"japanese":"毎朝早く起きます。","romaji":"Maiasa hayaku okimasu.","german":"I get up early every morning."},{"japanese":"漢字をきれいに書きました。","romaji":"Kanji o kirei ni kakimashita.","german":"I wrote the kanji neatly."}],"notes":"Irregular: いい → よく (よくできました = well done). Watch out with きれい and 有名: they are な-adjectives, so きれいに, not *きれく. The same form appears in ～くなる/～になる (to become) and ～くする/～にする (to make). Some adverbs are words in their own right: とても, ゆっくり, すぐ.","related":["ku-naru-ni-naru","n4-ku-suru","na-adj-present"]},
{"id":"n5-demo-suggestion","pattern":"～でも (Vorschlag)","level":"N5","category":"Partikel","meaning":"... or something (soft suggestion)","explanation":"Noun + でも softens a suggestion or invitation: お茶でも飲みませんか = 'Shall we have some tea or something?'. でも hints that it could just as well be something else and leaves the other person some leeway. It replaces は, が or を.","formation":"Noun + でも + suggestion / invitation / wish (～ませんか, ～ましょう, ～どうですか)","examples":[{"japanese":"お茶でも飲みませんか。","romaji":"Ocha demo nomimasen ka.","german":"Would you like to have some tea or something?","cloze":{"start":2,"answer":"でも","quiz":{"level":"N5","japanese":"お茶でも飲みませんか。","german":"Would you like to have some tea or something?","start":2,"answer":"でも","acceptedAnswers":["でも","なんか"],"distractors":[{"text":"ても","reason":"ても attaches to the て-form of verbs and adjectives, not to a noun like お茶."},{"text":"が","reason":"飲む takes its object with を; with が the sentence becomes ungrammatical."},{"text":"に","reason":"に marks a destination or a time, not a drink that you drink."}],"promptKana":"おちゃ＿＿＿のみませんか。"}}},{"japanese":"日曜日に映画でも見に行きましょう。","romaji":"Nichiyōbi ni eiga demo mi ni ikimashō.","german":"Let's go see a movie or something on Sunday."},{"japanese":"暑いですね。冷たいものでもどうですか。","romaji":"Atsui desu ne. Tsumetai mono demo dō desu ka.","german":"It's hot, isn't it? How about something cold?"}],"notes":"Don't confuse it with でも at the start of a sentence ('but') or with noun + でも meaning 'even' (子供でもわかる = even a child understands that). In a suggestion, でも sounds modest because you don't commit to anything. Colloquially also ～なんか: コーヒーなんかどう？","related":["n5-masen-ka","temo","mashou"]},
{"id":"n5-masen-ka","pattern":"～ませんか","level":"N5","category":"Verben","meaning":"won't you ...? (polite invitation)","explanation":"With the negative question ～ませんか you invite someone politely: 一緒に行きませんか = 'Won't you come along?'. The negation sounds reserved and leaves the other person a choice. This is more considerate than ～ましょう, which already assumes agreement.","formation":"Verb stem (ます-form without ます) + ませんか","examples":[{"japanese":"週末、一緒に映画を見ませんか。","romaji":"Shūmatsu, issho ni eiga o mimasen ka.","german":"Would you like to watch a movie together this weekend?","cloze":{"start":10,"answer":"ませんか","quiz":{"level":"N5","japanese":"週末、一緒に映画を見ませんか。","german":"Would you like to watch a movie together this weekend?","start":10,"answer":"ませんか","acceptedAnswers":["ませんか","ましょうか"],"distractors":[{"text":"ませんでした","reason":"ませんでした negates the past ('didn't watch') and is not an invitation."},{"text":"ましたか","reason":"ましたか asks whether someone did something instead of inviting them."},{"text":"ないでください","reason":"ないでください asks someone not to do something – the opposite of an invitation."}],"promptKana":"しゅうまつ、いっしょにえいがをみ＿＿＿。"}}},{"japanese":"ちょっと休みませんか。","romaji":"Chotto yasumimasen ka.","german":"Shall we take a short break?"},{"japanese":"「今晩、食事に行きませんか。」「いいですね。行きましょう。」","romaji":"\"Konban, shokuji ni ikimasen ka.\" \"Ii desu ne. Ikimashō.\"","german":"\"Would you like to go out to eat tonight?\" – \"Sounds good. Let's go!\""}],"notes":"Typical exchange: invitation with ～ませんか, acceptance with いいですね、～ましょう. Refusals are indirect: 土曜日はちょっと… (Saturday is a bit …). Don't invite with ～たいですか – it asks directly about the other person's wishes and comes across as pushy. Informal: 行かない？ with rising intonation.","related":["mashou","mashou-ka","masen","n5-demo-suggestion"]},
{"id":"n5-question-word-ka-mo","pattern":"疑問詞 + か / 疑問詞 + も～ない","level":"N5","category":"Satzstrukturen","meaning":"some- (何か, どこか) / nothing, nobody (何も～ない)","explanation":"Question words combine with particles to form new words: + か gives \"some-\" (何か = something, 誰か = someone, どこか = somewhere), + も with a negative gives \"nothing, nobody, nowhere\" (何も～ない, 誰も～ない). These forms are very common in everyday speech.","formation":"何 / 誰 / どこ / いつ + か / 何 / 誰 + も + negative / どこ + へ・に + も + negative","examples":[{"japanese":"冷蔵庫の中に何もありません。","romaji":"Reizōko no naka ni nani mo arimasen.","german":"There's nothing in the fridge.","cloze":{"start":7,"answer":"も","quiz":{"level":"N5","japanese":"冷蔵庫の中に何もありません。","german":"There's nothing in the fridge.","start":7,"answer":"も","acceptedAnswers":["も"],"distractors":[{"text":"か","reason":"何か means \"something\" and with ありません does not give the statement \"nothing\"."},{"text":"が","reason":"何が asks about the subject; without a final か, the sentence is ungrammatical."},{"text":"を","reason":"ある does not take an object with を."}],"promptKana":"れいぞうこのなかになに＿＿＿ありません。"}}},{"japanese":"何か飲みたいです。","romaji":"Nanika nomitai desu.","german":"I'd like to drink something."},{"japanese":"日曜日はどこへも行きませんでした。","romaji":"Nichiyōbi wa doko e mo ikimasen deshita.","german":"I didn't go anywhere on Sunday."}],"notes":"The answer to 何か食べましたか is: いいえ、何も食べませんでした. Other particles go before も: 誰とも話さなかった (didn't talk to anyone), どこにもない (nowhere). Careful: いつも means \"always\", and どれも/どちらも with a positive verb means \"every one/both\" – \"no/none\" only comes about with a negative.","related":["ka","mo","n4-indirect-question"]},
{"id":"n4-nakute-wa-ikenai","pattern":"～なくてはいけない / ～なくてはならない","level":"N4","category":"Satzstrukturen","meaning":"must, have to (obligation, necessity)","explanation":"～なくてはいけない and ～なくてはならない mean \"must\" – literally \"if you don't do it, it won't do\". They mean the same as ～なければならない but sound a bit more conversational. いけない fits personal obligations better, ならない general rules.","formation":"Verb (ない-form: ない → なくて) + は + いけない / ならない","examples":[{"japanese":"明日は早く起きなくてはいけません。","romaji":"Ashita wa hayaku okinakute wa ikemasen.","german":"I have to get up early tomorrow.","cloze":{"start":7,"answer":"なくてはいけません","quiz":{"level":"N4","japanese":"明日は早く起きなくてはいけません。","german":"I have to get up early tomorrow.","start":7,"answer":"なくてはいけません","acceptedAnswers":["なくてはいけません","なくてはなりません","なければなりません","なければいけません","ないといけません"],"distractors":[{"text":"てはいけません","reason":"起きてはいけません is a prohibition (\"must not get up\"), not an obligation."},{"text":"なくてもいいです","reason":"なくてもいい means \"don't have to\" – the opposite of the statement."},{"text":"ないではいけません","reason":"The obligation form is built on なくて; ないでは is ungrammatical here."}],"promptKana":"あしたははやくおき＿＿＿。"}}},{"japanese":"この薬は毎日飲まなくてはならない。","romaji":"Kono kusuri wa mainichi nomanakute wa naranai.","german":"You have to take this medicine every day."},{"japanese":"もう帰らなくちゃ。","romaji":"Mō kaeranakucha.","german":"I've got to go home now."}],"notes":"Spoken short form: ～なくては → ～なくちゃ (いけない), often shortened all the way: 行かなくちゃ! ～なきゃ (from ～なければ) is equivalent. The meaning stays the same; only the register changes: なければならない (written, official) > なくてはならない > なくてはいけない > ないといけない > なくちゃ/なきゃ (casual). Opposite: ～なくてもいい (don't have to).","related":["nakereba-naranai","n4-nai-to-ikenai","nakutemo-ii","n4-nakya-nakucha"]},
{"id":"n4-nai-to-ikenai","pattern":"～ないといけない","level":"N4","category":"Satzstrukturen","meaning":"must, have to (spoken, very common)","explanation":"～ないといけない means \"must\" and is the most common way to say it in spoken Japanese. Literally: \"If you don't do it, it won't do.\" It usually expresses a necessity arising from the concrete situation. In conversation いけない is often dropped: もう行かないと。","formation":"Verb (ない-form) + と + いけない / いけません","examples":[{"japanese":"レポートを金曜日までに出さないといけない。","romaji":"Repōto o kin'yōbi made ni dasanai to ikenai.","german":"I have to hand in the report by Friday.","cloze":{"start":13,"answer":"ないといけない","quiz":{"level":"N4","japanese":"レポートを金曜日までに出さないといけない。","german":"I have to hand in the report by Friday.","start":13,"answer":"ないといけない","acceptedAnswers":["ないといけない","ないといけません","ないとだめだ","なければならない","なければいけない","なくてはいけない","なくてはならない"],"distractors":[{"text":"なくてもいい","reason":"なくてもいい means \"don't have to\" – the opposite of the statement."},{"text":"ないでください","reason":"ないでください asks someone not to do something; it does not express your own obligation."},{"text":"ないはいけない","reason":"と belongs between ない and いけない; ないは is ungrammatical."}],"promptKana":"レポートをきんようびまでにださ＿＿＿。"}}},{"japanese":"もう十時だ。そろそろ帰らないと。","romaji":"Mō jūji da. Sorosoro kaeranai to.","german":"It's already ten. I should be heading home soon."},{"japanese":"日本では家に入る前に靴を脱がないといけません。","romaji":"Nihon de wa ie ni hairu mae ni kutsu o nuganai to ikemasen.","german":"In Japan, you have to take off your shoes before entering a house."}],"notes":"Instead of いけない you also hear だめ: 早く寝ないとだめだよ. The short form ～ないと without いけない sounds like a half-spoken thought – typical when reminding yourself or saying goodbye. Regulations and official texts tend to use ～なければならない.","related":["nakereba-naranai","n4-nakute-wa-ikenai","n4-to-conditional","n4-nakya-nakucha"]},
{"id":"n4-temo-kamawanai","pattern":"～ても構わない","level":"N4","category":"Satzstrukturen","meaning":"it's fine if …; feel free to …","explanation":"～ても構わない expresses permission or indifference: \"It doesn't matter if …\". It corresponds to ～てもいい but sounds a little more formal and stresses that the speaker has no problem with it. As a question (～ても構いませんか) it politely asks for permission.","formation":"Verb (て-form) + も構わない / い-adj (～くても) / な-adj・noun (～でも) + 構わない","examples":[{"japanese":"この部屋の本は自由に読んでも構いません。","romaji":"Kono heya no hon wa jiyū ni yonde mo kamaimasen.","german":"Feel free to read the books in this room.","cloze":{"start":12,"answer":"でも構いません","quiz":{"level":"N4","japanese":"この部屋の本は自由に読んでも構いません。","german":"Feel free to read the books in this room.","start":12,"answer":"でも構いません","acceptedAnswers":["でも構いません","でもかまいません","でもいいです","でも大丈夫です"],"distractors":[{"text":"ではいけません","reason":"ではいけません is a prohibition – the opposite of permission."},{"text":"でも構います","reason":"構う is only used in the negative in this expression; the affirmative makes no sense."},{"text":"だら構いません","reason":"The permission form is ～ても構わない; 構わない cannot be combined with たら."}],"promptKana":"このへやのほんはじゆうによん＿＿＿。"}}},{"japanese":"「窓を開けても構いませんか。」「ええ、どうぞ。」","romaji":"\"Mado o akete mo kamaimasen ka.\" \"Ē, dōzo.\"","german":"\"May I open the window?\" \"Yes, please go ahead.\""},{"japanese":"安ければ、古くても構わない。","romaji":"Yasukereba, furukute mo kamawanai.","german":"As long as it's cheap, I don't mind if it's old."}],"notes":"構う means \"to mind, to care about\" and is used almost only in the negative: 構わない = \"don't mind\". Politeness levels when asking for permission: ～てもいい？ (casual) < ～てもいいですか < ～ても構いませんか < ～てもよろしいでしょうか (very polite). As a short reply: 構いませんよ = No problem.","related":["temo-ii","temo","n4-tewa-ikenai"]},
{"id":"n4-kana-kashira","pattern":"～かな / ～かしら","level":"N4","category":"Partikel","meaning":"I wonder if …? (question thought aloud)","explanation":"かな and かしら come at the end of a sentence and express wondering aloud: \"I wonder if …\". You are asking yourself rather than the other person, so it sounds soft and unobtrusive. かな is neutral; かしら sounds traditionally feminine and is less common today.","formation":"Verb / い-adj (plain form) + かな / な-adj・noun (without だ) + かな; かしら works the same way","examples":[{"japanese":"明日は晴れるかな。","romaji":"Ashita wa hareru ka na.","german":"I wonder if it'll be sunny tomorrow.","cloze":{"start":6,"answer":"かな","quiz":{"level":"N4","japanese":"明日は晴れるかな。","german":"I wonder if it'll be sunny tomorrow.","start":6,"answer":"かな","acceptedAnswers":["かな","かしら","かなあ","だろうか","でしょうか"],"distractors":[{"text":"だな","reason":"だ cannot come directly after a verb like 晴れる."},{"text":"なか","reason":"The order is reversed; the ending is かな."},{"text":"ですかな","reason":"です cannot come directly after the dictionary form of a verb."}],"promptKana":"あしたははれる＿＿＿。"}}},{"japanese":"この服、ちょっと派手かな。","romaji":"Kono fuku, chotto hade ka na.","german":"I wonder if these clothes are a bit too flashy."},{"japanese":"田中さん、もう着いたかしら。","romaji":"Tanaka-san, mō tsuita kashira.","german":"I wonder if Mr. Tanaka has arrived yet."}],"notes":"With a negative, かな becomes an indirect wish: 早く来ないかな = If only he'd come soon! ～てくれないかな is a soft request. After nouns and な-adjectives, だ is dropped (学生かな, not *学生だかな). With superiors, it's better to use ～でしょうか.","related":["ka","deshou","n4-daroo"]},
{"id":"n4-ga-suru","pattern":"～がする","level":"N4","category":"Verben","meaning":"to smell / sound / taste of …","explanation":"A noun of sensory perception + がする describes something you perceive involuntarily: 音がする (a sound can be heard), においがする (there's a smell), 味がする (it tastes of). The perception is the subject, marked with が – not the person perceiving it.","formation":"音 / 声 / におい / 味 / 感じ + がする; with a description in front: noun + の / adjective + perception noun + がする","examples":[{"japanese":"キッチンからいいにおいがします。","romaji":"Kitchin kara ii nioi ga shimasu.","german":"There's a nice smell coming from the kitchen.","cloze":{"start":11,"answer":"がします","quiz":{"level":"N4","japanese":"キッチンからいいにおいがします。","german":"There's a nice smell coming from the kitchen.","start":11,"answer":"がします","acceptedAnswers":["がします","がする"],"distractors":[{"text":"をします","reason":"Perceptions like におい take が with する, not を."},{"text":"がいます","reason":"いる is only used for living beings, not for a smell."},{"text":"でします","reason":"で marks a place or means and does not make a sentence with します here."}],"promptKana":"キッチンからいいにおい＿＿＿。"}}},{"japanese":"隣の部屋から変な音がした。","romaji":"Tonari no heya kara hen na oto ga shita.","german":"A strange noise came from the next room."},{"japanese":"このスープはしょうがの味がする。","romaji":"Kono sūpu wa shōga no aji ga suru.","german":"This soup tastes of ginger."}],"notes":"Typical nouns: 音, 声, におい (pleasant: 匂い, unpleasant: 臭い), 味, 香り, 感じ, 寒気 (chills), 吐き気 (nausea). With 気 you get ～気がする (\"I have a feeling that …\", N3). Comparison: 音が聞こえる emphasizes the hearing, 音がする the fact that a sound is there.","related":["n3-ki-ga-suru","ga"]},
{"id":"n4-toku","pattern":"～とく / ～どく","level":"N4","category":"Verben","meaning":"colloquial ～ておく (do in advance)","explanation":"～とく is the spoken contraction of ～ておく: て + おく merges into とく, で + おく into どく. The meaning stays the same – doing something in advance or deliberately leaving it as it is. Among friends and family the short form is much more common than the full form.","formation":"Verb (て-form): ～ておく → ～とく / ～でおく → ～どく; conjugates like a godan verb: とく, といて, といた","examples":[{"japanese":"ビール、冷蔵庫に入れといたよ。","romaji":"Bīru, reizōko ni iretoita yo.","german":"I put the beer in the fridge already.","cloze":{"start":10,"answer":"といた","quiz":{"level":"N4","japanese":"ビール、冷蔵庫に入れといたよ。","german":"I put the beer in the fridge already.","start":10,"answer":"といた","acceptedAnswers":["といた","ておいた"],"distractors":[{"text":"とった","reason":"The past of ～とく is ～といた, not ～とった."},{"text":"どいた","reason":"どく only comes from でおく (読んどく); 入れて has て, so it's とく."},{"text":"といだ","reason":"とく forms its past like 書く → 書いた, so it's といた."}],"promptKana":"ビール、れいぞうこにいれ＿＿＿よ。"}}},{"japanese":"明日の会議の資料、コピーしとくね。","romaji":"Ashita no kaigi no shiryō, kopī shitoku ne.","german":"I'll go ahead and copy the documents for tomorrow's meeting."},{"japanese":"この本、今週中に読んどいて。","romaji":"Kono hon, konshū-chū ni yondoite.","german":"Read this book by the end of the week, OK?"}],"notes":"Examples: 買っておく → 買っとく, 見ておいて → 見といて, 飲んでおく → 飲んどく. Don't confuse it with 解く (とく, to solve) or どく (to move out of the way). Like ～ちゃう (← てしまう), ～とく belongs to casual speech; in emails to superiors or in essays, stick with ～ておきます.","related":["n4-teoku","n4-te-shimau-casual"]},
{"id":"n4-cha-ikenai","pattern":"～ちゃいけない / ～じゃいけない","level":"N4","category":"Satzstrukturen","meaning":"must not (colloquial prohibition)","explanation":"～ちゃいけない is the spoken short form of ～てはいけない: ては becomes ちゃ, では becomes じゃ. You often hear it from parents, teachers or among friends. Even more casual is ～ちゃだめ. The meaning remains a clear prohibition.","formation":"Verb (て-form): ～ては → ～ちゃ / ～では → ～じゃ + いけない / だめ","examples":[{"japanese":"ここで泳いじゃいけないよ。","romaji":"Koko de oyoija ikenai yo.","german":"You mustn't swim here.","cloze":{"start":5,"answer":"じゃいけない","quiz":{"level":"N4","japanese":"ここで泳いじゃいけないよ。","german":"You mustn't swim here.","start":5,"answer":"じゃいけない","acceptedAnswers":["じゃいけない","ではいけない","じゃだめ","じゃだめだ"],"distractors":[{"text":"ちゃいけない","reason":"泳ぐ has the て-form 泳いで; では becomes じゃ, not ちゃ."},{"text":"じゃいい","reason":"Permission would be ～でもいい; じゃいい is not a form."},{"text":"じゃいかない","reason":"The prohibition ends in いけない, not いかない."}],"promptKana":"ここでおよい＿＿＿よ。"}}},{"japanese":"まだ食べちゃいけません。","romaji":"Mada tabecha ikemasen.","german":"You can't eat yet."},{"japanese":"夜遅くまでゲームしちゃだめだよ。","romaji":"Yoru osoku made gēmu shicha dame da yo.","german":"You mustn't play games until late at night."}],"notes":"て → ちゃ (食べては → 食べちゃ), で → じゃ (飲んでは → 飲んじゃ). Don't confuse it with ～ちゃう/～じゃう (← てしまう): 食べちゃった = ate it all up, 食べちゃいけない = must not eat. With ～なくちゃ (← なくては), on the other hand, you get \"must\": 食べなくちゃ.","related":["n4-tewa-ikenai","tewa-ikemasen","n4-te-shimau-casual","n4-nakya-nakucha"]},
{"id":"n4-te-yokatta","pattern":"～てよかった","level":"N4","category":"Satzstrukturen","meaning":"good that …; I'm glad that …","explanation":"～てよかった expresses relief or joy about something that happened: \"Good that …\". It looks back on an action or situation that turned out well. The opposite – regret about something you didn't do – is expressed by ～ばよかった.","formation":"Verb (て-form) + よかった / い-adj (～くて) / な-adj・noun (～で) + よかった; negative: ～なくてよかった","examples":[{"japanese":"日本に来てよかったです。","romaji":"Nihon ni kite yokatta desu.","german":"I'm glad I came to Japan.","cloze":{"start":4,"answer":"てよかった","quiz":{"level":"N4","japanese":"日本に来てよかったです。","german":"I'm glad I came to Japan.","start":4,"answer":"てよかった","acceptedAnswers":["てよかった"],"distractors":[{"text":"たよかった","reason":"よかった attaches to the て-form, not to the た-form."},{"text":"てよいかった","reason":"The past of いい/よい is よかった."},{"text":"てがよかった","reason":"No particle が goes between the て-form and よかった."}],"promptKana":"にほんにき＿＿＿です。"}}},{"japanese":"間に合ってよかった！","romaji":"Ma ni atte yokatta!","german":"Thank goodness I made it in time!"},{"japanese":"大きなけがじゃなくてよかったですね。","romaji":"Ōki na kega ja nakute yokatta desu ne.","german":"It's a good thing it wasn't a serious injury."}],"notes":"Contrast: 行ってよかった (I went – luckily) vs. 行けばよかった (I didn't go – too bad). Often used to show sympathy: 無事でよかったですね (I'm so glad everything turned out all right). With a negative: 雨が降らなくてよかった (good thing it didn't rain).","related":["n4-ba-yokatta","te-form"]},
{"id":"n4-you-to-omou","pattern":"～(よ)うと思う","level":"N4","category":"Verben","meaning":"I'm planning to …; I'm thinking of …","explanation":"Volitional form + と思う expresses your own intention: \"I'm planning to …\". ～ようと思います sounds like a decision made at the moment of speaking, ～ようと思っています like a plan you've had for a while. It is softer and more personal than ～つもりだ.","formation":"Verb (volitional form: ～よう / ～おう) + と思う / と思っている","examples":[{"japanese":"夏休みに北海道へ行こうと思っています。","romaji":"Natsuyasumi ni Hokkaidō e ikō to omotte imasu.","german":"I'm thinking of going to Hokkaidō during the summer vacation.","cloze":{"start":9,"answer":"こうと思っています","quiz":{"level":"N4","japanese":"夏休みに北海道へ行こうと思っています。","german":"I'm thinking of going to Hokkaidō during the summer vacation.","start":9,"answer":"こうと思っています","acceptedAnswers":["こうと思っています","こうと思います","こうと思う","くつもりです"],"distractors":[{"text":"こうに思っています","reason":"The content of a thought is linked with と, not に."},{"text":"かろうと思っています","reason":"The volitional form of 行く is 行こう; ～かろう belongs to い-adjectives."},{"text":"こうと思ってあります","reason":"思う forms the continuing state with ている, not てある."}],"promptKana":"なつやすみにほっかいどうへい＿＿＿。"}}},{"japanese":"今年こそたばこをやめようと思う。","romaji":"Kotoshi koso tabako o yameyō to omou.","german":"This year I'm finally going to quit smoking."},{"japanese":"電話しようと思ったら、ちょうど友達から電話が来た。","romaji":"Denwa shiyō to omottara, chōdo tomodachi kara denwa ga kita.","german":"Just as I was about to make a call, a friend called me."}],"notes":"Only for your own intention. About third parties: 彼は留学しようと思っているらしい. ～つもりだ sounds firmer and more planned, ～ようと思う more like a thought or a fresh decision. ～ようと思ったら often means \"just as I was about to …\". Related: ～ようとする (to try, to be about to).","related":["n4-volitional","tsumori","n4-you-to-suru"]},
{"id":"n4-shika-nai-option","pattern":"～しかない (einzige Möglichkeit)","level":"N4","category":"Satzstrukturen","meaning":"to have no choice but to …","explanation":"Verb in the dictionary form + しかない means that only one option is left: \"the only thing to do is …\". It sounds resigned or determined. Unlike noun + しか～ない (only X), here a whole action comes before しか.","formation":"Verb (dictionary form) + しかない / しかありません","examples":[{"japanese":"終電がもうないから、タクシーで帰るしかない。","romaji":"Shūden ga mō nai kara, takushī de kaeru shika nai.","german":"There are no more trains, so I have no choice but to take a taxi home.","cloze":{"start":17,"answer":"しかない","quiz":{"level":"N4","japanese":"終電がもうないから、タクシーで帰るしかない。","german":"There are no more trains, so I have no choice but to take a taxi home.","start":17,"answer":"しかない","acceptedAnswers":["しかない","しかありません","ほかない","よりほかない"],"distractors":[{"text":"だけない","reason":"だけ does not combine with ない to mean \"no choice but\"."},{"text":"しかある","reason":"しか always requires a negative form."},{"text":"しかしない","reason":"After the dictionary form comes しかない; しかしない is ungrammatical here."}],"promptKana":"しゅうでんがもうないから、タクシーでかえる＿＿＿。"}}},{"japanese":"誰も手伝ってくれないなら、一人でやるしかありません。","romaji":"Dare mo tetsudatte kurenai nara, hitori de yaru shika arimasen.","german":"If nobody will help me, I'll just have to do it alone."},{"japanese":"ここまで来たら、もう頑張るしかないね。","romaji":"Koko made kitara, mō ganbaru shika nai ne.","german":"Now that we've come this far, all we can do is keep going."}],"notes":"Comparison: noun + しか～ない (百円しかない = only 100 yen) vs. verb + しかない (待つしかない = all you can do is wait). More literary: ～ほかない / ～よりほかない (N3), even stronger: ～ざるを得ない. Positive and determined: やるしかない! = Time to get to it!","related":["shika-nai","n3-hoka-nai","n3-zaruwoenai"]},
{"id":"n4-indirect-question","pattern":"～か (indirekte Frage)","level":"N4","category":"Satzstrukturen","meaning":"embedded question (what / when / where …)","explanation":"A question with a question word can be embedded in a larger sentence: plain form + か + 知っている / わかる / 教えてください. This works like English embedded questions with \"what\", \"when\" or \"where\" (\"I don't know when it starts\"). For questions without a question word, use ～かどうか.","formation":"Question word … verb / い-adj (plain form) + か / … noun・な-adj (without だ) + か","examples":[{"japanese":"会議が何時に始まるか知っていますか。","romaji":"Kaigi ga nanji ni hajimaru ka shitte imasu ka.","german":"Do you know what time the meeting starts?","cloze":{"start":9,"answer":"か","quiz":{"level":"N4","japanese":"会議が何時に始まるか知っていますか。","german":"Do you know what time the meeting starts?","start":9,"answer":"か","acceptedAnswers":["か"],"distractors":[{"text":"かどうか","reason":"かどうか is only used for questions without a question word; here there's already 何時."},{"text":"と","reason":"と quotes statements; a question with a question word needs か."},{"text":"を","reason":"A verb in the plain form cannot take を directly."}],"promptKana":"かいぎがなんじにはじまる＿＿＿しっていますか。"}}},{"japanese":"どこで切符を買えばいいか教えてください。","romaji":"Doko de kippu o kaeba ii ka oshiete kudasai.","german":"Please tell me where I should buy a ticket."},{"japanese":"誰が来るか、まだわかりません。","romaji":"Dare ga kuru ka, mada wakarimasen.","german":"I don't know yet who's coming."}],"notes":"だ is dropped before か: 何が好きか (not *好きだか), 誰の傘か. A particle after か (を/が) is usually left out. The embedded part stays plain even in polite speech: not *何時に始まりますか知っていますか. Without a question word: 来るかどうかわからない.","related":["n4-ka-dou-ka","ka","n5-question-word-ka-mo"]},
{"id":"n3-tsuide-ni","pattern":"～ついでに","level":"N3","category":"Satzstrukturen","meaning":"while one is at it; taking the opportunity","explanation":"～ついでに means using an opportunity to get something else done on the side: \"while I'm at it, I'll also …\". The first action is the real purpose, the second a convenient extra. Very common with errands and trips.","formation":"Verb (dictionary form / た-form) + ついでに / noun + の + ついでに","examples":[{"japanese":"駅に行くついでに、この手紙を出してくれない？","romaji":"Eki ni iku tsuide ni, kono tegami o dashite kurenai?","german":"Since you're going to the station anyway, could you mail this letter for me?","cloze":{"start":4,"answer":"ついでに","quiz":{"level":"N3","japanese":"駅に行くついでに、この手紙を出してくれない？","german":"Since you're going to the station anyway, could you mail this letter for me?","start":4,"answer":"ついでに","acceptedAnswers":["ついでに"],"distractors":[{"text":"ながら","reason":"ながら requires the verb stem (行きながら) and expresses simultaneity."},{"text":"とたんに","reason":"とたんに follows the た-form and means \"the very moment\"."},{"text":"しだい","reason":"次第 follows the verb stem (行き次第) and means \"as soon as\"."}]}}},{"japanese":"買い物のついでに、郵便局にも寄った。","romaji":"Kaimono no tsuide ni, yūbinkyoku ni mo yotta.","german":"While I was out shopping, I also stopped by the post office."},{"japanese":"大阪へ出張したついでに、京都の友達に会ってきた。","romaji":"Ōsaka e shutchō shita tsuide ni, Kyōto no tomodachi ni atte kita.","german":"While I was on a business trip to Osaka, I also went to see a friend in Kyōto."}],"notes":"Both actions are intended, but the second is secondary. ～ながら, by contrast, links two simultaneous activities without a main and a secondary purpose. ～がてら (N1) is more literary and usually follows movement such as 散歩. As a noun: ついでがあったら… (if you get the chance).","related":["nagara","n1-gatera"]},
{"id":"n3-nante-nanka","pattern":"～なんて / ～なんか","level":"N3","category":"Partikel","meaning":"the likes of …; (dismissive, humble, surprised)","explanation":"なんて and なんか highlight a word and give it an emotional coloring: contempt (宿題なんか), modesty (私なんか) or surprise (～なんて！). なんか is the casual form of など; only なんて can take up and comment on a whole sentence.","formation":"Noun + なんか / なんて; sentence (plain form) + なんて; なんて + noun = \"such a …\"","examples":[{"japanese":"私なんかには、そんな難しい仕事はできません。","romaji":"Watashi nanka ni wa, sonna muzukashii shigoto wa dekimasen.","german":"Someone like me could never do such a difficult job.","cloze":{"start":1,"answer":"なんか","quiz":{"level":"N3","japanese":"私なんかには、そんな難しい仕事はできません。","german":"Someone like me could never do such a difficult job.","start":1,"answer":"なんか","acceptedAnswers":["なんか","など"],"distractors":[{"text":"こそ","reason":"こそ cannot come before には and would emphasize \"precisely me\"."},{"text":"さえ","reason":"The order would be 私にさえ; 私さえには is ungrammatical."},{"text":"しか","reason":"しか has to come after the particle (私にしか) and means \"only me\"."}]}}},{"japanese":"彼が会社を辞めるなんて、信じられない。","romaji":"Kare ga kaisha o yameru nante, shinjirarenai.","german":"Him quitting the company – I can't believe it!"},{"japanese":"宿題なんか、もうやりたくない！","romaji":"Shukudai nanka, mō yaritakunai!","german":"I really don't feel like doing homework anymore!"}],"notes":"Three uses: (1) dismissive: 野菜なんか嫌い, (2) humble: 私なんかまだまだです, (3) surprised or indignant about a situation: ～なんて！ Used neutrally, なんか can also give examples (≈ など): お茶なんかどう？ Said about other people, the dismissive coloring can easily come across as rude.","related":["n4-nado","n4-toka"]},
{"id":"n3-tatte-datte","pattern":"～たって / ～だって","level":"N3","category":"Satzstrukturen","meaning":"even if (colloquial)","explanation":"～たって is the colloquial form of ～ても: \"even if\". It is formed from the た-form (走ったって, 高くたって); after nouns and な-adjectives it becomes ～だって. Typical of lively conversation, often with frustration or defiance.","formation":"Verb (た-form) + って / い-adj: ～くたって / な-adj・noun + だって","examples":[{"japanese":"今から走ったって、もう間に合わないよ。","romaji":"Ima kara hashittatte, mō ma ni awanai yo.","german":"Even if you run now, you won't make it.","cloze":{"start":5,"answer":"たって","quiz":{"level":"N3","japanese":"今から走ったって、もう間に合わないよ。","german":"Even if you run now, you won't make it.","start":5,"answer":"たって","acceptedAnswers":["たって","ても"],"distractors":[{"text":"だって","reason":"だって follows nouns and な-adjectives; the verb needs the た-form + って."},{"text":"たっても","reason":"たって already contains the meaning of ても; たっても doubles it and is wrong."},{"text":"たでも","reason":"でも cannot attach to the た-form."}]}}},{"japanese":"いくら高くたって、欲しいものは買う。","romaji":"Ikura takakutatte, hoshii mono wa kau.","german":"No matter how expensive it is, I buy what I want."},{"japanese":"いくら静かだって、駅から遠い部屋は嫌だ。","romaji":"Ikura shizuka datte, eki kara tōi heya wa iya da.","german":"However quiet it may be, I don't want an apartment far from the station."}],"notes":"Equivalent to ～ても (N4), but sounds much more casual – avoid it in essays and polite speech. Often with いくら / どんなに (no matter how much) or 何度 (no matter how often). Noun + だって can also mean \"too, even\" (私だって行きたい = I want to go too!), and だって at the start of a sentence means a defiant \"but, because\".","related":["temo","n3-to-shitemo","n3-tatoe-temo"]},
{"id":"n3-to-suru-to","pattern":"～とすれば / ～とすると","level":"N3","category":"Satzstrukturen","meaning":"assuming that …; if that's true, then …","explanation":"～とすると and ～とすれば set up an assumption and draw a conclusion from it: \"If we assume that …, then …\". The following clause is usually an assessment or guess, not an action.","formation":"Verb / い-adj (plain form) + とすると・とすれば / noun・な-adj + だ + とすると・とすれば","examples":[{"japanese":"彼の話が本当だとすると、大変なことになる。","romaji":"Kare no hanashi ga hontō da to suru to, taihen na koto ni naru.","german":"If what he says is true, we're in serious trouble.","cloze":{"start":7,"answer":"とすると","quiz":{"level":"N3","japanese":"彼の話が本当だとすると、大変なことになる。","german":"If what he says is true, we're in serious trouble.","start":7,"answer":"とすると","acceptedAnswers":["とすると","とすれば","としたら"],"distractors":[{"text":"とは","reason":"とは expresses surprise or a definition and does not introduce a conclusion."},{"text":"ところで","reason":"ところで follows the た-form (～たところで) and means \"even if …, it's no use\"."},{"text":"にしては","reason":"にしては does not come after だ and means \"considering (that)\"."}]}}},{"japanese":"毎日三時間勉強するとすれば、一か月で九十時間になる。","romaji":"Mainichi san-jikan benkyō suru to sureba, ikkagetsu de kyūjū-jikan ni naru.","german":"If you study three hours every day, that makes ninety hours in a month."},{"japanese":"「山田さんは来週から休みだそうですよ。」「とすると、この仕事は誰がやるんですか。」","romaji":"\"Yamada-san wa raishū kara yasumi da sō desu yo.\" \"To suru to, kono shigoto wa dare ga yaru n desu ka.\"","german":"\"I hear Mr. Yamada is off starting next week.\" \"Then who's going to do this work?\""}],"notes":"Almost the same as ～としたら (N2), which sounds a bit more hypothetical. ～としても, by contrast, means \"even if\" (concession). At the start of a sentence as a conjunction: とすると / とすれば = \"so then …\". For simple everyday conditions followed by an action, ～なら is more natural: 雨なら、傘を持っていこう.","related":["n2-to-shitara","n3-to-shitemo","n4-nara"]},
{"id":"n3-ni-yori-ni-yoru","pattern":"～により / ～による","level":"N3","category":"Partikel","meaning":"due to, by (written); depending on","explanation":"～により is the written form of ～によって and appears in the news and in announcements, especially for causes: 大雪により (due to heavy snow). ～による comes before a noun: 台風による被害. The meanings are the same as for によって.","formation":"Noun + により + clause / noun + による + noun","examples":[{"japanese":"大雪により、電車が止まっています。","romaji":"Ōyuki ni yori, densha ga tomatte imasu.","german":"Trains are stopped due to heavy snow.","cloze":{"start":2,"answer":"により","quiz":{"level":"N3","japanese":"大雪により、電車が止まっています。","german":"Trains are stopped due to heavy snow.","start":2,"answer":"により","acceptedAnswers":["により","によって","で","のため"],"distractors":[{"text":"による","reason":"による must come before a noun; before a clause you need により or によって."},{"text":"によると","reason":"によると names a source of information (\"according to\"), not a cause."},{"text":"に対して","reason":"に対して means \"toward, in contrast to\" and gives no reason for the stoppage."}]}}},{"japanese":"台風による被害は予想より大きかった。","romaji":"Taifū ni yoru higai wa yosō yori ōkikatta.","german":"The damage caused by the typhoon was greater than expected."},{"japanese":"ルールは国により異なる。","romaji":"Rūru wa kuni ni yori kotonaru.","german":"The rules differ from country to country."}],"notes":"Register: で (spoken: 事故で遅れた) – によって (neutral) – により (written, announcements). Before a noun it's always による: 専門家による説明. Don't confuse it with ～によると (according to a source). A typical platform announcement: 人身事故により、運転を見合わせております.","related":["n4-ni-yotte","n4-ni-yoru-to"]},
{"id":"n3-tate","pattern":"～たて","level":"N3","category":"Verben","meaning":"freshly …, just … (焼きたて)","explanation":"Verb stem + たて describes something that has just been made or done and is therefore still fresh: 焼きたてのパン (freshly baked bread). It is only usual with certain typical verbs, especially for food, and sounds positive.","formation":"Verb stem (ます-form without ます) + たて + の + noun / + たてだ","examples":[{"japanese":"焼きたてのパンはとてもおいしい。","romaji":"Yakitate no pan wa totemo oishii.","german":"Freshly baked bread is really delicious.","cloze":{"start":2,"answer":"たて","quiz":{"level":"N3","japanese":"焼きたてのパンはとてもおいしい。","german":"Freshly baked bread is really delicious.","start":2,"answer":"たて","acceptedAnswers":["たて"],"distractors":[{"text":"ばかり","reason":"ばかり needs the た-form (焼いたばかり), not the verb stem."},{"text":"ぶり","reason":"～ぶり describes a manner or a time interval, not freshness."},{"text":"がち","reason":"～がち means \"tends to\" and doesn't fit bread."}]}}},{"japanese":"入社したての頃は、毎日緊張していた。","romaji":"Nyūsha shitate no koro wa, mainichi kinchō shite ita.","german":"When I had just joined the company, I was nervous every day."},{"japanese":"「ペンキ塗りたて」と書いてあるから、触らないで。","romaji":"\"Penki nuritate\" to kaite aru kara, sawaranaide.","german":"It says \"Wet paint,\" so don't touch it."}],"notes":"Typical words: 焼きたて, 揚げたて, 炊きたて (rice), できたて, 取れたて (freshly harvested), 生まれたて, 入社したて. ～たばかり (N4) is the general \"just did\" and works with any verb; たて stresses the freshness of the result. Counterpart: ～かけ (half-done, started).","related":["n4-tabakari","n4-kakeru"]},
{"id":"n3-to-iu-yori","pattern":"～というより","level":"N3","category":"Satzstrukturen","meaning":"rather than …; not so much … as …","explanation":"～というより corrects or refines a description: \"It's not so much A as B.\" You concede that A isn't entirely wrong but consider B more accurate. The second part often contains むしろ (rather).","formation":"Noun / な-adj (without だ) / verb・い-adj (plain form) + というより (むしろ) + B","examples":[{"japanese":"今日は暖かいというより、暑いくらいだ。","romaji":"Kyō wa atatakai to iu yori, atsui kurai da.","german":"Today it's not so much warm as almost hot.","cloze":{"start":6,"answer":"というより","quiz":{"level":"N3","japanese":"今日は暖かいというより、暑いくらいだ。","german":"Today it's not so much warm as almost hot.","start":6,"answer":"というより","acceptedAnswers":["というより","と言うより","というよりは"],"distractors":[{"text":"によって","reason":"によって cannot come directly after an い-adjective."},{"text":"にとって","reason":"にとって follows a noun and means \"for someone\"."},{"text":"としては","reason":"としては follows a noun (\"as …\"), not an adjective."}]}}},{"japanese":"彼は友達というより、家族のような存在だ。","romaji":"Kare wa tomodachi to iu yori, kazoku no yō na sonzai da.","german":"He's less a friend than something like family."},{"japanese":"この本は勉強になるというより、読んでいて楽しい。","romaji":"Kono hon wa benkyō ni naru to iu yori, yonde ite tanoshii.","german":"This book is less educational than simply fun to read."}],"notes":"Often strengthened: AというよりむしろB. Difference from ～より (AはBより高い): there, two things are compared; with というより, two descriptions of the same thing. Don't confuse it with ～どころか (far from it, rather the opposite). In conversation also at the start of a sentence: というより… = \"Or rather …\".","related":["yori","n3-dokoro-ka"]},
{"id":"n3-to-ieba","pattern":"～といえば / ～というと","level":"N3","category":"Satzstrukturen","meaning":"speaking of …; when you think of …","explanation":"～といえば and ～というと take up a topic and name the first thing that comes to mind: \"When you think of …, then …\". In conversation, といえば also introduces a change of topic (\"Speaking of …\"). というと can additionally ask for clarification: \"You mean …?\"","formation":"Noun + といえば / というと (/ といったら)","examples":[{"japanese":"日本の冬といえば、やっぱり温泉ですね。","romaji":"Nihon no fuyu to ieba, yappari onsen desu ne.","german":"When you think of winter in Japan, it's hot springs, of course.","cloze":{"start":4,"answer":"といえば","quiz":{"level":"N3","japanese":"日本の冬といえば、やっぱり温泉ですね。","german":"When you think of winter in Japan, it's hot springs, of course.","start":4,"answer":"といえば","acceptedAnswers":["といえば","というと","といったら","と言えば"],"distractors":[{"text":"によって","reason":"によって means \"depending on\" or \"by\"; here, though, a typical example is being named."},{"text":"にしては","reason":"にしては expresses surprise at a deviation and contradicts やっぱり."},{"text":"というのに","reason":"というのに means \"even though\" and needs a whole clause before it."}]}}},{"japanese":"「来週、京都に行くんだ。」「京都というと、お寺がたくさんある所だね。」","romaji":"\"Raishū, Kyōto ni iku n da.\" \"Kyōto to iu to, otera ga takusan aru tokoro da ne.\"","german":"\"I'm going to Kyōto next week.\" \"Kyōto – that's the place with lots of temples, right?\""},{"japanese":"旅行といえば、夏休みはどこか行くの？","romaji":"Ryokō to ieba, natsuyasumi wa dokoka iku no?","german":"Speaking of travel, are you going anywhere over the summer vacation?"}],"notes":"といえば = spontaneous association, or \"speaking of\" when changing the topic. というと also works as a follow-up question: 「というと？」 = \"Meaning?\". The variant といったら often emphasizes a strong feeling. Don't confuse them with ～といっても (even though one says …, N2) or ～というのは (definition).","related":["n4-toiu","n2-to-itte-mo","n3-to-iu-no-wa"]},
{"id":"n3-to-itta","pattern":"～といった","level":"N3","category":"Partikel","meaning":"such as, like (examples before a noun)","explanation":"AやBといったC gives examples of a group: \"C such as A and B\". The list isn't complete; it shows typical members. It sounds slightly more elevated than など and is often used in descriptions, the news and presentations.","formation":"Noun (や / とか / 、) noun + といった + noun","examples":[{"japanese":"この店では、すしや天ぷらといった日本料理が食べられる。","romaji":"Kono mise de wa, sushi ya tenpura to itta Nihon ryōri ga taberareru.","german":"At this restaurant you can eat Japanese dishes such as sushi and tempura.","cloze":{"start":12,"answer":"といった","quiz":{"level":"N3","japanese":"この店では、すしや天ぷらといった日本料理が食べられる。","german":"At this restaurant you can eat Japanese dishes such as sushi and tempura.","start":12,"answer":"といった","acceptedAnswers":["といった","などの","のような","みたいな"],"distractors":[{"text":"といって","reason":"といって is a verb form and cannot modify a noun like 日本料理."},{"text":"といっても","reason":"といっても means \"even though one says\" and needs a following clause, not a noun."},{"text":"にとって","reason":"にとって means \"for someone\" and makes no sense here."}]}}},{"japanese":"サッカーや野球といったスポーツが好きです。","romaji":"Sakkā ya yakyū to itta supōtsu ga suki desu.","german":"I like sports such as soccer and baseball."},{"japanese":"英語、中国語、韓国語といった言語を話せるスタッフがいます。","romaji":"Eigo, Chūgokugo, Kankokugo to itta gengo o hanaseru sutaffu ga imasu.","german":"We have staff who can speak languages such as English, Chinese and Korean."}],"notes":"Difference from など: など can stand on its own (本などを買った), while といった always needs a noun after it that names the group. Don't confuse it with ～という (called: 田中という人) or the past tense 言った (said). Colloquial: AとかBみたいなC.","related":["n4-nado","n4-toiu","n4-toka"]},
{"id":"n3-masu-you-ni","pattern":"～ますように","level":"N3","category":"Satzstrukturen","meaning":"may …; I hope … (wish, prayer)","explanation":"～ますように expresses a wish or prayer whose fulfillment is out of your hands: \"May …\". Typical at shrines, on Tanabata wish slips and in greetings. The ます-form is kept even when you're talking to yourself.","formation":"Verb (ます-form) + ように / negative: ～ませんように","examples":[{"japanese":"試験に合格できますように。","romaji":"Shiken ni gōkaku dekimasu yō ni.","german":"Please let me pass the exam!","cloze":{"start":7,"answer":"ますように","quiz":{"level":"N3","japanese":"試験に合格できますように。","german":"Please let me pass the exam!","start":7,"answer":"ますように","acceptedAnswers":["ますように"],"distractors":[{"text":"ませんように","reason":"ませんように wishes for the opposite: not passing the exam."},{"text":"たいように","reason":"たい cannot combine with ように to form a wish."},{"text":"ますようだ","reason":"ようだ (apparently) follows the plain form, not ます."}]}}},{"japanese":"明日は雨が降りませんように。","romaji":"Ashita wa ame ga furimasen yō ni.","german":"I hope it doesn't rain tomorrow!"},{"japanese":"新しい一年が皆さんにとって良い年になりますように。","romaji":"Atarashii ichinen ga minasan ni totte yoi toshi ni narimasu yō ni.","german":"May the new year be a good one for all of you."}],"notes":"Not for things you control yourself: *毎日勉強しますように – use ～ようにする or ～つもりだ for that. Common on cards: 早く良くなりますように (Get well soon). Related: ～ように (purpose, N4) and ～ように言う (telling someone to do something, N3).","related":["n4-you-ni-purpose","n3-you-ni-to"]},
{"id":"n3-ki-ga-suru","pattern":"～気がする","level":"N3","category":"Satzstrukturen","meaning":"I have a feeling that …","explanation":"～気がする expresses a vague, intuitive impression: \"I have a feeling that …\" or \"Somehow it seems to me that …\". It is less certain and more personal than ～と思う and is useful for voicing an opinion cautiously. With nouns: ～ような気がする.","formation":"Verb / い-adj (plain form) + 気がする / な-adj + な + 気がする / noun + の + ような気がする","examples":[{"japanese":"この人、どこかで会ったことがある気がする。","romaji":"Kono hito, dokoka de atta koto ga aru ki ga suru.","german":"I feel like I've met this person somewhere before.","cloze":{"start":16,"answer":"気がする","quiz":{"level":"N3","japanese":"この人、どこかで会ったことがある気がする。","german":"I feel like I've met this person somewhere before.","start":16,"answer":"気がする","acceptedAnswers":["気がする","ような気がする","気がします"],"distractors":[{"text":"気にする","reason":"気にする means \"to worry about\" and cannot take a clause as its content."},{"text":"気がある","reason":"気がある means \"to be interested\" and doesn't fit a guess."},{"text":"気をする","reason":"Feelings take が with する, not を."}]}}},{"japanese":"最近、時間がたつのが早い気がします。","romaji":"Saikin, jikan ga tatsu no ga hayai ki ga shimasu.","german":"Lately I feel like time goes by so fast."},{"japanese":"今日は何でもできそうな気がする。","romaji":"Kyō wa nan demo dekisō na ki ga suru.","german":"Today I feel like I could do anything."}],"notes":"Describes your own impression; about others: ～気がするらしい. Don't confuse it with 気にする (to worry about), 気になる (to be on one's mind) and ～気がない (to not feel like it). Compared with ～と思う, 気がする is more intuitive and less reasoned.","related":["n4-ga-suru","to-omoimasu","n4-you-da"]},
{"id":"n3-sei-ka","pattern":"～せいか","level":"N3","category":"Satzstrukturen","meaning":"perhaps because …; maybe due to …","explanation":"～せいか gives a presumed reason, usually for something unpleasant: \"perhaps because …\". The speaker isn't sure whether the reason really applies. Unlike ～せいで, which clearly names a cause or puts the blame, ～せいか stays cautious.","formation":"Verb / い-adj (plain form) + せいか / な-adj + な + せいか / noun + の + せいか","examples":[{"japanese":"寝不足のせいか、今日は頭が痛い。","romaji":"Nebusoku no sei ka, kyō wa atama ga itai.","german":"Maybe it's from lack of sleep, but I have a headache today.","cloze":{"start":4,"answer":"せいか","quiz":{"level":"N3","japanese":"寝不足のせいか、今日は頭が痛い。","german":"Maybe it's from lack of sleep, but I have a headache today.","start":4,"answer":"せいか","acceptedAnswers":["せいか","ためか"],"distractors":[{"text":"せいに","reason":"せいに belongs to せいにする (to blame) and does not introduce a reason."},{"text":"くせに","reason":"くせに means a reproachful \"even though\" and doesn't fit a reason."},{"text":"ついでに","reason":"ついでに means \"while one is at it\" and names no cause."}]}}},{"japanese":"年のせいか、最近疲れやすくなった。","romaji":"Toshi no sei ka, saikin tsukareyasuku natta.","german":"Maybe it's my age, but lately I get tired easily."},{"japanese":"気のせいか、彼女は今日元気がないように見える。","romaji":"Ki no sei ka, kanojo wa kyō genki ga nai yō ni mieru.","german":"Maybe it's just my imagination, but she seems down today."}],"notes":"Set phrase: 気のせい (one's imagination), 気のせいか = \"maybe it's just my imagination\". Occasionally also used for neutral or positive results (薬を飲んだせいか、よく眠れた), then without any sense of blame. Comparison: ～せいで (certain cause, negative), ～おかげで (certain cause, positive), ～せいか / ～ためか / ～からか (presumed cause).","related":["n4-sei-de","n4-okage-de"]},
{"id":"n3-ni-kagiru","pattern":"～に限る","level":"N3","category":"Satzstrukturen","meaning":"nothing beats …; … is best","explanation":"～に限る expresses the personal conviction that something is the best choice: \"When it comes to …, nothing beats …\". It is often preceded by a situation (暑い日は…). It is a subjective recommendation from experience, not an objective fact.","formation":"Noun + に限る / verb (dictionary form / ない-form) + に限る","examples":[{"japanese":"暑い日は冷たいビールに限る。","romaji":"Atsui hi wa tsumetai bīru ni kagiru.","german":"On hot days, nothing beats a cold beer.","cloze":{"start":10,"answer":"に限る","quiz":{"level":"N3","japanese":"暑い日は冷たいビールに限る。","german":"On hot days, nothing beats a cold beer.","start":10,"answer":"に限る","acceptedAnswers":["に限る","が一番だ","が一番"],"distractors":[{"text":"に限って","reason":"に限って (\"of all times\") cannot come at the end of a sentence."},{"text":"に限らず","reason":"に限らず (\"not only\") requires a following clause."},{"text":"にすぎない","reason":"にすぎない (\"merely, just\") belittles the beer instead of recommending it."}]}}},{"japanese":"風邪をひいたときは、早く寝るに限る。","romaji":"Kaze o hiita toki wa, hayaku neru ni kagiru.","german":"When you have a cold, the best thing is to go to bed early."},{"japanese":"面倒なことには関わらないに限る。","romaji":"Mendō na koto ni wa kakawaranai ni kagiru.","german":"It's best to stay out of troublesome matters."}],"notes":"Similar-looking forms have other meanings: ～に限って (of all times, N2), ～に限らず (not only, N2), ～に限り (only for: 先着百名に限り). ～に限る is always a personal recommendation at the end of a sentence. More matter-of-fact: ～のが一番だ.","related":["n2-ni-kagitte","n2-ni-kagirazu","ichiban"]},
{"id":"n3-ba-hodo","pattern":"～ば～ほど","level":"N3","category":"Satzstrukturen","meaning":"the more …, the more …","explanation":"～ば～ほど links two changes: \"The more A, the more B.\" The same word appears twice – first in the ば-form, then in the dictionary form before ほど. The second part of the sentence describes what changes to the same degree.","formation":"Verb (ば-form) + verb (dictionary form) + ほど / い-adj: ～ければ + ～い + ほど / な-adj: ～なら + ～な + ほど","examples":[{"japanese":"練習すればするほど上手になります。","romaji":"Renshū sureba suru hodo jōzu ni narimasu.","german":"The more you practice, the better you get.","cloze":{"start":2,"answer":"すればするほど","quiz":{"level":"N3","japanese":"練習すればするほど上手になります。","german":"The more you practice, the better you get.","start":2,"answer":"すればするほど","acceptedAnswers":["すればするほど","するほど","すればするだけ"],"distractors":[{"text":"したらするほど","reason":"The construction requires the ば-form, not たら."},{"text":"すればしたほど","reason":"The dictionary form comes before ほど, not the た-form."},{"text":"すればするまで","reason":"まで (\"until\") doesn't give \"the more …, the more\"."}]}}},{"japanese":"駅に近ければ近いほど、家賃は高くなる。","romaji":"Eki ni chikakereba chikai hodo, yachin wa takaku naru.","german":"The closer to the station, the higher the rent."},{"japanese":"説明は簡単なら簡単なほどいい。","romaji":"Setsumei wa kantan nara kantan na hodo ii.","german":"The simpler an explanation is, the better."}],"notes":"The ば part can be left out: 練習するほど上手になる. With な-adjectives: ～なら～なほど (formal: ～であればあるほど). Typical mistakes: putting the second verb in the た-form, or using たら instead of ば. ～ほど on its own (N4) can also express an extent: 泣きたいほど (so much that …).","related":["n4-hodo-p","n4-ba","n4-adj-ba"]},
{"id":"n3-tara-ii-ba-ii","pattern":"～たらいい / ～ばいい","level":"N3","category":"Satzstrukturen","meaning":"you should …; what should I do?","explanation":"～たらいい and ～ばいい give advice: \"It's best to …\" or \"All you have to do is …\". In questions like どうしたらいいですか / どうすればいいですか, you ask for advice. ばいい often stresses that a simple solution is enough; たらいい sounds a bit more conversational.","formation":"Verb (たら-form) + いい / verb (ば-form) + いい; question: question word + ～たら / ～ば + いいですか","examples":[{"japanese":"駅までどうやって行けばいいですか。","romaji":"Eki made dō yatte ikeba ii desu ka.","german":"What's the best way to get to the station?","cloze":{"start":10,"answer":"ばいい","quiz":{"level":"N3","japanese":"駅までどうやって行けばいいですか。","german":"What's the best way to get to the station?","start":10,"answer":"ばいい","acceptedAnswers":["ばいい"],"distractors":[{"text":"ばいいのに","reason":"ばいいのに expresses regret or reproach and cannot be used with ですか."},{"text":"たいい","reason":"The ば-form is missing between 行け and いい; たいい is not a form."},{"text":"るいい","reason":"行けるいい is ungrammatical; advice needs ～ばいい."}]}}},{"japanese":"わからないことがあったら、先生に聞いたらいいよ。","romaji":"Wakaranai koto ga attara, sensei ni kiitara ii yo.","german":"If there's something you don't understand, just ask the teacher."},{"japanese":"財布をなくしてしまった。どうしたらいいんだろう。","romaji":"Saifu o nakushite shimatta. Dō shitara ii n darō.","german":"I've lost my wallet. What on earth should I do?"}],"notes":"Giving advice: ～たらいい / ～ばいい (neutral), ～といい (friendly recommendation), ～たほうがいい (clear advice, often with a warning). ～ばいい can also sound dismissive: 嫌ならやめればいい (If you don't like it, just quit). With のに it turns into regret or reproach: ～ばいいのに (N3).","related":["n4-ta-hou-ga-ii","n4-tara-dou","n3-ba-ii-noni"]},
{"id":"n3-tatoe-temo","pattern":"たとえ～ても","level":"N3","category":"Satzstrukturen","meaning":"even if (emphatic)","explanation":"たとえ signals early in the sentence that a concession with ～ても will follow: \"Even if …, (nothing changes)\". It sounds determined or solemn and is often used for hypothetical or extreme cases. The actual grammar is carried by ～ても / ～でも.","formation":"たとえ + verb (て-form) + も / い-adj (～くても) / な-adj・noun + でも (or だとしても)","examples":[{"japanese":"たとえ反対されても、私はこの仕事を続けます。","romaji":"Tatoe hantai sarete mo, watashi wa kono shigoto o tsuzukemasu.","german":"Even if people oppose me, I will keep doing this job.","cloze":{"start":0,"answer":"たとえ","quiz":{"level":"N3","japanese":"たとえ反対されても、私はこの仕事を続けます。","german":"Even if people oppose me, I will keep doing this job.","start":0,"answer":"たとえ","acceptedAnswers":["たとえ","いくら","どんなに","たとい"],"distractors":[{"text":"たぶん","reason":"たぶん (\"probably\") doesn't fit a concession with ても."},{"text":"ぜひ","reason":"ぜひ is used with wishes and requests, not with \"even if\"."},{"text":"まるで","reason":"まるで (\"as if\") requires ～ようだ or ～みたい."}]}}},{"japanese":"たとえ雨でも、試合は行われます。","romaji":"Tatoe ame demo, shiai wa okonawaremasu.","german":"Even if it rains, the game will be held."},{"japanese":"たとえ冗談だとしても、そんなことを言ってはいけない。","romaji":"Tatoe jōdan da to shite mo, sonna koto o itte wa ikenai.","german":"Even if it's just a joke, you shouldn't say something like that."}],"notes":"たとえ alone doesn't change the grammar – what matters is ～ても / ～でも / ～としても at the end of the clause. もし goes with ～たら / ～ば (if), while たとえ is the typical signal word for ～ても (even if). Colloquial: たとえ～たって. Elevated: たとえ～であろうと.","related":["temo","n3-to-shitemo","n3-tatte-datte"]},
{"id":"n3-no-dewa-nai-ka","pattern":"～のではないか / ～んじゃないか","level":"N3","category":"Satzstrukturen","meaning":"isn't it the case that …? (cautious guess)","explanation":"～のではないか expresses a cautious guess or opinion: \"Couldn't it be that …?\" Although the form looks negative, it affirms the statement. It is often followed by と思う or と心配する. In conversation: ～んじゃないか / ～んじゃない？","formation":"Verb / い-adj (plain form) + のではないか / noun・な-adj + な + のではないか; spoken: ～んじゃないか","examples":[{"japanese":"この計画は少し無理なのではないでしょうか。","romaji":"Kono keikaku wa sukoshi muri na no de wa nai deshō ka.","german":"Isn't this plan a bit unrealistic?","cloze":{"start":10,"answer":"のではないでしょうか","quiz":{"level":"N3","japanese":"この計画は少し無理なのではないでしょうか。","german":"Isn't this plan a bit unrealistic?","start":10,"answer":"のではないでしょうか","acceptedAnswers":["のではないでしょうか","のではないか","んじゃないでしょうか","のではありませんか"],"distractors":[{"text":"のではありません","reason":"Without か, the statement becomes a real negation (\"it's not that\") instead of a guess."},{"text":"ではないでしょうか","reason":"の is missing after 無理な; な cannot come directly before では."},{"text":"のはないでしょうか","reason":"The form requires では; のは does not express a guess."}]}}},{"japanese":"彼女はもう帰ったんじゃないかな。","romaji":"Kanojo wa mō kaetta n ja nai ka na.","german":"I think she's probably gone home already."},{"japanese":"明日の試合は中止になるのではないかと心配している。","romaji":"Ashita no shiai wa chūshi ni naru no de wa nai ka to shinpai shite iru.","german":"I'm worried that tomorrow's game might be canceled."}],"notes":"Difference: ～のではないか (guess, affirmative) vs. ～のではない (real negation: \"it's not that …\"). ～のではないでしょうか is a popular, polite way to state your own opinion in discussions without sounding too direct. Colloquially with rising intonation: ～んじゃない？","related":["n-desu","deshou","n3-wake-dewa-nai","n3-jan"]},
{"id":"n3-to-iu-no-wa","pattern":"～というのは","level":"N3","category":"Satzstrukturen","meaning":"… means …; what is called … is …","explanation":"～というのは takes up a word or statement as the topic in order to explain or define it: \"X – that means …\". It is often followed by ～のことだ or ～という意味だ. At the start of a sentence, というのは also introduces a reason: \"The reason is that …\".","formation":"Noun / sentence (plain form) + というのは + explanation (～のことだ / ～という意味だ / ～からだ)","examples":[{"japanese":"「積ん読」というのは、買った本を読まずに積んでおくことです。","romaji":"\"Tsundoku\" to iu no wa, katta hon o yomazu ni tsunde oku koto desu.","german":"\"Tsundoku\" means buying books and leaving them piled up unread.","cloze":{"start":5,"answer":"というのは","quiz":{"level":"N3","japanese":"「積ん読」というのは、買った本を読まずに積んでおくことです。","german":"\"Tsundoku\" means buying books and leaving them piled up unread.","start":5,"answer":"というのは","acceptedAnswers":["というのは","とは","って","と言うのは"],"distractors":[{"text":"によって","reason":"によって (\"by, depending on\") does not introduce a definition."},{"text":"というのに","reason":"というのに means \"even though\" and gives no explanation here."},{"text":"にとって","reason":"にとって (\"for someone\") doesn't fit an explanation of a term."}]}}},{"japanese":"「就活」というのは、就職活動の略です。","romaji":"\"Shūkatsu\" to iu no wa, shūshoku katsudō no ryaku desu.","german":"\"Shūkatsu\" is short for job hunting."},{"japanese":"明日は休みます。というのは、母が入院したからです。","romaji":"Ashita wa yasumimasu. To iu no wa, haha ga nyūin shita kara desu.","german":"I'll be absent tomorrow. The reason is that my mother has been admitted to the hospital."}],"notes":"For definitions it is similar to ～とは (written) and ～って (spoken). As a conjunction at the start of a sentence: というのは… ～からだ (you see, because). Don't confuse it with ～というと (association) or ～ということだ (that means / apparently).","related":["n4-toiu","n4-tte","n1-towa","n3-to-ieba"]},
{"id":"n3-kesshite-nai","pattern":"決して～ない","level":"N3","category":"Satzstrukturen","meaning":"never, by no means","explanation":"決して strengthens a negative into \"never, by no means\". It sounds serious and emphatic and often appears in promises, warnings and assurances. In everyday speech it sounds rather written or solemn; casually you say 絶対(に)～ない.","formation":"決して + verb (ない / ません) / adj (～くない / ～ではない) / ～てはいけない","examples":[{"japanese":"このことは決して誰にも言いません。","romaji":"Kono koto wa kesshite dare ni mo iimasen.","german":"I will never tell anyone about this.","cloze":{"start":5,"answer":"決して","quiz":{"level":"N3","japanese":"このことは決して誰にも言いません。","german":"I will never tell anyone about this.","start":5,"answer":"決して","acceptedAnswers":["決して","けっして","絶対に","絶対"],"distractors":[{"text":"必ず","reason":"必ず (\"certainly\") is used with positive statements, not before a negative."},{"text":"ぜひ","reason":"ぜひ is used with wishes and requests and doesn't fit a promise to keep quiet."},{"text":"まるで","reason":"まるで (\"as if\") requires a comparison with ～ようだ."}]}}},{"japanese":"この川は危ないので、決して泳いではいけません。","romaji":"Kono kawa wa abunai node, kesshite oyoide wa ikemasen.","german":"This river is dangerous, so never swim in it!"},{"japanese":"日本語は決して簡単ではないが、とても楽しい。","romaji":"Nihongo wa kesshite kantan de wa nai ga, totemo tanoshii.","german":"Japanese is by no means easy, but it's a lot of fun."}],"notes":"決して is only used with a negative or a prohibition – *決して行きます is wrong. 絶対(に), on the other hand, works both ways (絶対行く / 絶対行かない). Scale of intensifiers: 全然～ない (not at all, casual), 少しも / ちっとも～ない (not a bit), 決して～ない (never, serious).","related":["n5-zenzen-nai","n5-amari-nai"]},
{"id":"n4-nakya-nakucha","pattern":"～なきゃ / ～なくちゃ","level":"N4","category":"Satzstrukturen","meaning":"must (colloquial)","explanation":"～なきゃ is the spoken short form of ～なければ, and ～なくちゃ that of ～なくては. Usually the following いけない／ならない is dropped: 行かなきゃ = \"I have to go\". Only used in conversation with friends and family.","formation":"Verb (ない-form: ない → なきゃ / なくちゃ) (+ いけない / ならない)","examples":[{"japanese":"もう十時だ。そろそろ帰らなきゃ。","romaji":"Mō jūji da. Sorosoro kaeranakya.","german":"It's already ten. I should get going home.","cloze":{"start":12,"answer":"なきゃ","quiz":{"level":"N4","japanese":"もう十時だ。そろそろ帰らなきゃ。","german":"It's already ten. I should get going home.","start":12,"answer":"なきゃ","acceptedAnswers":["なきゃ","なくちゃ","ないと"],"distractors":[{"text":"ない","reason":"帰らない means \"I won't go home\" – a negation, not an obligation."},{"text":"なくてもいい","reason":"なくてもいい means \"don't have to\" and contradicts the hint about the late hour."},{"text":"れる","reason":"帰られる is passive/potential and expresses no necessity."}],"promptKana":"もうじゅうじだ。そろそろかえら＿＿＿。"}}},{"japanese":"明日までにレポートを書かなくちゃいけない。","romaji":"Ashita made ni repōto o kakanakucha ikenai.","german":"I have to write the report by tomorrow."},{"japanese":"あ、牛乳を買わなきゃ。","romaji":"A, gyūnyū o kawanakya.","german":"Oh, I have to buy milk."}],"notes":"Register from formal to casual: なければならない > なくてはいけない > ないといけない > なきゃ／なくちゃ. Opposite: ～なくてもいい (don't have to). Don't confuse it with ～ちゃいけない (must not).","related":["n4-nakute-wa-ikenai","nakereba-naranai","n4-nai-to-ikenai","n4-cha-ikenai"]},
{"id":"n3-jan","pattern":"～じゃん","level":"N3","category":"Satzstrukturen","meaning":"…, right? / …, see! (colloquial)","explanation":"じゃん is a very casual contraction of じゃないか. You use it to seek agreement or to point out something obvious – often with surprise or a slight reproach. It originally comes from the area around Yokohama and is now widespread nationwide among younger people.","formation":"Verb / い-adj (plain form) + じゃん; noun / な-adj + じゃん","examples":[{"japanese":"この服、かわいいじゃん。","romaji":"Kono fuku, kawaii jan.","german":"This outfit is so cute!","cloze":{"start":8,"answer":"じゃん","quiz":{"level":"N3","japanese":"この服、かわいいじゃん。","german":"This outfit is so cute!","start":8,"answer":"じゃん","acceptedAnswers":["じゃん","じゃない","じゃないか"],"distractors":[{"text":"だ","reason":"い-adjectives don't take だ: かわいいだ is ungrammatical."},{"text":"でした","reason":"かわいいでした is ungrammatical; the polite past would be かわいかったです."},{"text":"じゃなかった","reason":"じゃなかった is a real past negative and doesn't fit the compliment."}]}}},{"japanese":"だから言ったじゃん！","romaji":"Dakara itta jan!","german":"See, I told you!"},{"japanese":"明日休みじゃん。遊びに行こうよ。","romaji":"Ashita yasumi jan. Asobi ni ikō yo.","german":"We're off tomorrow, right? Let's go out and have some fun!"}],"notes":"Only among friends; rude toward superiors. More polite equivalent: ～じゃないですか. Despite the form, it's not a negation: かわいいじゃん means \"it's cute, isn't it\", not \"it isn't cute\".","related":["n3-no-dewa-nai-ka","ja-nai"]},
{"id":"n3-tteba","pattern":"～ってば","level":"N3","category":"Satzstrukturen","meaning":"…, I told you! (impatient emphasis)","explanation":"ってば (from って言えば) gives impatient emphasis to a statement or request: you're repeating something the other person doesn't want to hear. After names it expresses affectionate annoyance.","formation":"Sentence (plain form) / request + ってば; name + ってば","examples":[{"japanese":"大丈夫だってば。心配しないで。","romaji":"Daijōbu da tteba. Shinpai shinaide.","german":"I'm fine, I told you! Don't worry.","cloze":{"start":4,"answer":"ってば","quiz":{"level":"N3","japanese":"大丈夫だってば。心配しないで。","german":"I'm fine, I told you! Don't worry.","start":4,"answer":"ってば","acceptedAnswers":["ってば","ったら"],"distractors":[{"text":"ければ","reason":"ければ is the conditional of い-adjectives and cannot follow だ."},{"text":"っても","reason":"だっても is ungrammatical; the concessive would be でも."},{"text":"ってた","reason":"ってた reports a past remark (\"said\") and adds no emphasis."}]}}},{"japanese":"早くしてってば！","romaji":"Hayaku shite tteba!","german":"Hurry up already!"},{"japanese":"もう、お母さんってば、また同じこと言ってる。","romaji":"Mō, okāsan tteba, mata onaji koto itteru.","german":"Geez, Mom, you're saying the same thing again."}],"notes":"Very colloquial and emotional; only used with people close to you. After people it is almost the same as ～ったら (N2). Don't confuse it with the conditional ～ば.","related":["n2-ttara","n4-tte"]},
{"id":"n3-te-iru-baai-janai","pattern":"～ている場合じゃない","level":"N3","category":"Satzstrukturen","meaning":"now is not the time to …","explanation":"Literally \"it is not a situation in which one does …\". You state that an action is inappropriate under the circumstances because something more urgent needs attention.","formation":"Verb (て-form) + いる + 場合じゃない / 場合ではない","examples":[{"japanese":"寝ている場合じゃない。もう出かける時間だ！","romaji":"Nete iru baai ja nai. Mō dekakeru jikan da!","german":"This is no time to be sleeping – it's time to go!","cloze":{"start":1,"answer":"ている場合じゃない","quiz":{"level":"N3","japanese":"寝ている場合じゃない。もう出かける時間だ！","german":"This is no time to be sleeping – it's time to go!","start":1,"answer":"ている場合じゃない","acceptedAnswers":["ている場合じゃない","ている場合ではない","てる場合じゃない"],"distractors":[{"text":"てもいい","reason":"寝てもいい permits sleeping and contradicts the following sentence."},{"text":"たほうがいい","reason":"寝たほうがいい advises sleeping – the opposite of the intended statement."},{"text":"ているところだ","reason":"寝ているところだ only describes that you're sleeping right now and doesn't express that it's inappropriate."}]}}},{"japanese":"テストは明日だから、ゲームをしている場合ではありません。","romaji":"Tesuto wa ashita dakara, gēmu o shite iru baai de wa arimasen.","german":"The test is tomorrow, so this is no time to be playing games."},{"japanese":"笑っている場合じゃないよ。本当に困っているんだから。","romaji":"Waratte iru baai ja nai yo. Hontō ni komatte iru n dakara.","german":"This is no laughing matter – I'm really in trouble."}],"notes":"More formal: ～ている場合ではない. Related to ～どころではない (N3), which stresses that something is not possible at all under the circumstances. In conversation often shortened: 寝てる場合じゃない.","related":["n3-dokoro-dewa-nai"]},
{"id":"n2-wo-moto-ni","pattern":"～をもとに","level":"N2","category":"Partikel","meaning":"based on, on the basis of","explanation":"をもとに expresses that something serves as the basis, source or starting point for something else. Often used with creative works or decisions.","formation":"Noun + をもとに(して) / をもとにした + noun","examples":[{"japanese":"この映画は実話をもとに作られた。","cloze":{"start":7,"answer":"をもとに","quiz":{"level":"N2","japanese":"この映画は実話をもとに作られた。","german":"This movie was made based on a true story.","start":7,"answer":"をもとに","acceptedAnswers":["をもとに","に基づいて"],"distractors":[{"text":"をもとを","reason":"The basis is linked to 作られた with に."},{"text":"にもとで","reason":"The fixed combination is をもとに."},{"text":"をもとの","reason":"の requires a following noun here."}]}},"romaji":"Kono eiga wa jitsuwa wo moto ni tsukurareta.","german":"This movie was made based on a true story."},{"japanese":"アンケートの結果をもとに改善策を考えた。","cloze":{"start":8,"answer":"をもとに"},"romaji":"Ankēto no kekka wo moto ni kaizen-saku wo kangaeta.","german":"We came up with improvement measures based on the survey results."}],"notes":"Similar to に基づいて, but をもとに is somewhat more casual.","related":["n3-ni-motozuite"]},
{"id":"n2-ni-hanshite","pattern":"～に反して","level":"N2","category":"Partikel","meaning":"contrary to, against","explanation":"に反して expresses that something goes against what was expected or planned, or against a rule. The result is different from what was expected.","formation":"Noun + に反して / に反する + noun / に反した + noun","examples":[{"japanese":"予想に反して、試合に勝った。","cloze":{"start":2,"answer":"に反して","quiz":{"level":"N2","japanese":"予想に反して、試合に勝った。","german":"Contrary to expectations, we won the game.","start":2,"answer":"に反して","acceptedAnswers":["に反して"],"distractors":[{"text":"に反した","reason":"The attributive form does not connect to the following clause here."},{"text":"に反します","reason":"The polite finite form does not link the clauses here."},{"text":"を反して","reason":"反する requires に for what it refers to."}]}},"romaji":"Yosō ni hanshite, shiai ni katta.","german":"Contrary to expectations, we won the game."},{"japanese":"親の期待に反する行動を取った。","romaji":"Oya no kitai ni hansuru kōdō wo totta.","german":"He acted against his parents' expectations."}],"notes":"","related":[]},
{"id":"n2-ni-kagitte","pattern":"～に限って","level":"N2","category":"Partikel","meaning":"of all (people/times), only when","explanation":"に限って expresses surprise or frustration that something unexpected happens with one particular person or in one particular situation, of all things.","formation":"Noun + に限って","examples":[{"japanese":"傘を持っていない日に限って雨が降る。","cloze":{"start":9,"answer":"に限って","quiz":{"level":"N2","japanese":"傘を持っていない日に限って雨が降る。","german":"It always rains on the very days I don't have an umbrella with me.","start":9,"answer":"に限って","acceptedAnswers":["に限って"],"distractors":[{"text":"に限った","reason":"The attributive form does not connect to 雨が降る here."},{"text":"を限って","reason":"The reference to 日 requires に here."},{"text":"に限ります","reason":"The finite form ends the sentence instead of linking the circumstance."}]}},"romaji":"Kasa wo motte inai hi ni kagitte ame ga furu.","german":"It always rains on the very days I don't have an umbrella with me."},{"japanese":"うちの子に限ってそんなことはしない。","cloze":{"start":4,"answer":"に限って"},"romaji":"Uchi no ko ni kagitte sonna koto wa shinai.","german":"My child, of all people, would never do such a thing."}],"notes":"Often used with negative surprise or irony.","related":["n2-ni-kagirazu","n3-ni-kagiru","n2-ni-kagiri"]},
{"id":"n2-ni-kagirazu","pattern":"～に限らず","level":"N2","category":"Partikel","meaning":"not limited to, not only","explanation":"に限らず expresses that something applies not just to one particular thing but to others as well. Broader than だけでなく.","formation":"Noun + に限らず","examples":[{"japanese":"この問題は日本に限らず、世界中で起きている。","cloze":{"start":7,"answer":"に限らず","quiz":{"level":"N2","japanese":"この問題は日本に限らず、世界中で起きている。","german":"This problem isn't limited to Japan; it's happening all over the world.","start":7,"answer":"に限らず","acceptedAnswers":["に限らず"],"distractors":[{"text":"に限る","reason":"This limits the problem to Japan, the very opposite."},{"text":"に限った","reason":"This asserts a limitation instead of denying it."},{"text":"を限らず","reason":"The scope is marked with に."}]}},"romaji":"Kono mondai wa Nihon ni kagirazu, sekaijū de okite iru.","german":"This problem isn't limited to Japan; it's happening all over the world."},{"japanese":"男性に限らず女性も参加できる。","cloze":{"start":2,"answer":"に限らず"},"romaji":"Dansei ni kagirazu josei mo sanka dekiru.","german":"Not only men but also women can take part."}],"notes":"","related":["n2-ni-kagitte","n3-o-towazu","n3-ni-kagiru","n2-wo-nozoite","n2-ni-kagiri"]},
{"id":"n2-wo-megutte","pattern":"～をめぐって","level":"N2","category":"Partikel","meaning":"over, concerning (dispute/discussion)","explanation":"をめぐって is used when there is a discussion, a dispute or differing opinions about a topic.","formation":"Noun + をめぐって / をめぐる + noun","examples":[{"japanese":"土地の所有権をめぐって争いが起きた。","cloze":{"start":6,"answer":"をめぐって","quiz":{"level":"N2","japanese":"土地の所有権をめぐって争いが起きた。","german":"A dispute broke out over ownership of the land.","start":6,"answer":"をめぐって","acceptedAnswers":["をめぐって","に関して"],"distractors":[{"text":"をめぐった","reason":"The attributive form does not connect to 争いが起きた here."},{"text":"にめぐって","reason":"The point of dispute takes を here."},{"text":"をめぐります","reason":"The finite form does not link the subject of the dispute here."}]}},"romaji":"Tochi no shoyūken wo megutte arasoi ga okita.","german":"A dispute broke out over ownership of the land."},{"japanese":"この問題をめぐる議論は続いている。","romaji":"Kono mondai wo meguru giron wa tsuzuite iru.","german":"The debate over this issue continues."}],"notes":"Always implies disagreement or conflict.","related":["n3-ni-kanshite"]},
{"id":"n2-ni-atatte","pattern":"～にあたって","level":"N2","category":"Partikel","meaning":"on the occasion of, upon","explanation":"にあたって is used to introduce an important event or special occasion on which special measures are taken or words are spoken.","formation":"Noun / verb (dictionary form) + にあたって / にあたり / にあたっての + noun","examples":[{"japanese":"新年にあたって、目標を立てた。","cloze":{"start":2,"answer":"にあたって","quiz":{"level":"N2","japanese":"新年にあたって、目標を立てた。","german":"At the start of the new year, I set myself some goals.","start":2,"answer":"にあたって","acceptedAnswers":["にあたって","に際して"],"distractors":[{"text":"にあたった","reason":"The attributive form does not connect to 目標を立てた here."},{"text":"をあたって","reason":"The occasion is marked with に here."},{"text":"にあたります","reason":"The finite form ends the sentence instead of linking the occasion."}]}},"romaji":"Shinnen ni atatte, mokuhyō wo tateta.","german":"At the start of the new year, I set myself some goals."},{"japanese":"出発にあたり、皆様にお礼を申し上げます。","romaji":"Shuppatsu ni atari, minasama ni orei wo mōshiagemasu.","german":"On the occasion of our departure, I would like to express my thanks to all of you."}],"notes":"Formal; common in speeches and on official occasions.","related":["n1-ni-sakidatte","n3-sai-ni","n2-ni-saishite","n2-ni-mukete"]},
{"id":"n2-ni-kuwaete","pattern":"～に加えて","level":"N2","category":"Partikel","meaning":"in addition to, besides","explanation":"に加えて expresses that something more is added to something already there. It emphasizes the addition.","formation":"Noun + に加えて / に加え","examples":[{"japanese":"日本語に加えて、中国語も勉強している。","cloze":{"start":3,"answer":"に加えて","quiz":{"level":"N2","japanese":"日本語に加えて、中国語も勉強している。","german":"In addition to Japanese, I'm also studying Chinese.","start":3,"answer":"に加えて","acceptedAnswers":["に加えて"],"distractors":[{"text":"に加えた","reason":"The attributive form does not link 中国語も here."},{"text":"を加えて","reason":"This makes Japanese the thing being added instead of the starting point of the addition."},{"text":"に加えるます","reason":"ます is not attached to the dictionary form."}]}},"romaji":"Nihongo ni kuwaete, Chūgokugo mo benkyō shite iru.","german":"In addition to Japanese, I'm also studying Chinese."},{"japanese":"雨に加え、強い風も吹いている。","romaji":"Ame ni kuwae, tsuyoi kaze mo fuite iru.","german":"In addition to the rain, there's a strong wind blowing too."}],"notes":"","related":["n2-ue-ni"]},
{"id":"n2-no-moto-de","pattern":"～のもとで","level":"N2","category":"Partikel","meaning":"under (guidance/conditions/influence)","explanation":"のもとで expresses that something happens under certain conditions or under someone's guidance or influence.","formation":"Noun + のもとで / のもとに","examples":[{"japanese":"有名な教授のもとで研究を行った。","cloze":{"start":5,"answer":"のもとで","quiz":{"level":"N2","japanese":"有名な教授のもとで研究を行った。","german":"I did research under a famous professor.","start":5,"answer":"のもとで","acceptedAnswers":["のもとで"],"distractors":[{"text":"のもとを","reason":"The setting of the research requires で here."},{"text":"のもとの","reason":"の requires a following noun instead of 研究を行った."},{"text":"をもとで","reason":"The link to the professor requires の."}]}},"romaji":"Yūmei na kyōju no moto de kenkyū wo okonatta.","german":"I did research under a famous professor."},{"japanese":"厳しい条件のもとで働いている。","cloze":{"start":5,"answer":"のもとで"},"romaji":"Kibishii jōken no moto de hataraite iru.","german":"I'm working under harsh conditions."}],"notes":"","related":[]},
{"id":"n2-nuki-de","pattern":"～抜きで","level":"N2","category":"Partikel","meaning":"without, leaving out","explanation":"抜きで expresses that something is left out or excluded. Something takes place without a particular element.","formation":"Noun + 抜きで / 抜きに / 抜きの + noun","examples":[{"japanese":"冗談抜きで話しましょう。","cloze":{"start":2,"answer":"抜きで","quiz":{"level":"N2","japanese":"冗談抜きで話しましょう。","german":"Let's talk without joking around (seriously).","start":2,"answer":"抜きで","acceptedAnswers":["抜きで","なしで"],"distractors":[{"text":"抜くで","reason":"で is not attached to 抜く here."},{"text":"抜きの","reason":"The attributive form requires a noun."},{"text":"抜きます","reason":"This ends the sentence instead of modifying 話しましょう."}]}},"romaji":"Jōdan nuki de hanashimashō.","german":"Let's talk without joking around (seriously)."},{"japanese":"朝食抜きで出かけた。","cloze":{"start":2,"answer":"抜きで"},"romaji":"Chōshoku nuki de dekaketa.","german":"I went out without breakfast."}],"notes":"を抜きにして is an alternative form.","related":["n2-nuki-ni-shite"]},
{"id":"n2-ue-ni","pattern":"～上に","level":"N2","category":"Satzstrukturen","meaning":"in addition to, on top of that, moreover","explanation":"上に expresses that something more is added to an existing quality or situation. Often used when piling up positive or negative points.","formation":"Verb/い-adj + 上に / な-adj + な上に / noun + の上に / である上に","examples":[{"japanese":"この店は安い上に、おいしい。","cloze":{"start":6,"answer":"上に","quiz":{"level":"N2","japanese":"この店は安い上に、おいしい。","german":"This restaurant is cheap, and on top of that, the food is good.","start":6,"answer":"上に","acceptedAnswers":["上に"],"distractors":[{"text":"上を","reason":"The additive connection is 上に."},{"text":"上な","reason":"上 does not need a な connection here."},{"text":"上でした","reason":"The past-tense copula does not link the qualities here."}]}},"romaji":"Kono mise wa yasui ue ni, oishii.","german":"This restaurant is cheap, and on top of that, the food is good."},{"japanese":"雨が降った上に、風も強くなった。","cloze":{"start":5,"answer":"上に"},"romaji":"Ame ga futta ue ni, kaze mo tsuyoku natta.","german":"It rained, and on top of that, the wind got stronger."}],"notes":"Similar to し, but more formal. It strengthens the list.","related":["n3-ue-de","n2-ni-kuwaete"]},
{"id":"n2-ue-wa","pattern":"～上は","level":"N2","category":"Satzstrukturen","meaning":"now that, since … (then)","explanation":"上は expresses that, given an existing fact or decision, one should act accordingly. It implies determination.","formation":"Verb-た形 / verb (dictionary form) + 上は","examples":[{"japanese":"引き受けた上は、最後までやるつもりだ。","cloze":{"start":5,"answer":"上は","quiz":{"level":"N2","japanese":"引き受けた上は、最後までやるつもりだ。","german":"Now that I've taken it on, I intend to see it through to the end.","start":5,"answer":"上は","acceptedAnswers":["上は","以上は","からには"],"distractors":[{"text":"上を","reason":"を does not form a conditional connection here."},{"text":"上な","reason":"な does not link to the following clause here."},{"text":"上でした","reason":"This ends the sentence instead of linking the obligation."}]}},"romaji":"Hikiuketa ue wa, saigo made yaru tsumori da.","german":"Now that I've taken it on, I intend to see it through to the end."},{"japanese":"約束した上は、守らなければならない。","cloze":{"start":4,"answer":"上は"},"romaji":"Yakusoku shita ue wa, mamoranakereba naranai.","german":"Once you've made a promise, you have to keep it."}],"notes":"Similar to からには and 以上は.","related":["n3-kara-niwa","n2-ijou-wa","n1-temae"]},
{"id":"n2-sue-ni","pattern":"～末に","level":"N2","category":"Satzstrukturen","meaning":"after a long …, at the end of, finally","explanation":"末に expresses that after a long process, a lot of effort or deliberation, a result was finally reached.","formation":"Verb-た形 + 末(に) / noun + の末(に)","examples":[{"japanese":"長い話し合いの末に、合意に達した。","cloze":{"start":7,"answer":"末に","quiz":{"level":"N2","japanese":"長い話し合いの末に、合意に達した。","german":"After long discussions, an agreement was reached.","start":7,"answer":"末に","acceptedAnswers":["末に","後に"],"distractors":[{"text":"末を","reason":"を does not link the eventual result here."},{"text":"末な","reason":"末 is not a な-adjective here."},{"text":"末ます","reason":"ます cannot be attached directly to 末."}]}},"romaji":"Nagai hanashiai no sue ni, gōi ni tasshita.","german":"After long discussions, an agreement was reached."},{"japanese":"悩んだ末に、転職を決めた。","cloze":{"start":3,"answer":"末に"},"romaji":"Nayanda sue ni, tenshoku wo kimeta.","german":"After much agonizing, I decided to change jobs."}],"notes":"Emphasizes the long, hard process before the result.","related":["n2-ageku"]},
{"id":"n2-ippou-de","pattern":"～一方で","level":"N2","category":"Satzstrukturen","meaning":"on the other hand, while, on one hand … on the other","explanation":"一方で contrasts two opposing aspects or situations that exist at the same time.","formation":"Verb (dictionary form) / い-adj + 一方で / noun + の一方で / な-adj + な一方で","examples":[{"japanese":"便利になった一方で、新しい問題も生まれた。","cloze":{"start":6,"answer":"一方で","quiz":{"level":"N2","japanese":"便利になった一方で、新しい問題も生まれた。","german":"While things became more convenient, new problems also arose.","start":6,"answer":"一方で","acceptedAnswers":["一方で"],"distractors":[{"text":"一方を","reason":"を does not form a contrastive connection here."},{"text":"一方な","reason":"な does not link the two developments here."},{"text":"一方ます","reason":"ます cannot be attached to the noun 一方."}]}},"romaji":"Benri ni natta ippō de, atarashii mondai mo umareta.","german":"While things became more convenient, new problems also arose."},{"japanese":"彼は厳しい一方で、優しい面もある。","cloze":{"start":5,"answer":"一方で"},"romaji":"Kare wa kibishii ippō de, yasashii men mo aru.","german":"He's strict, but on the other hand he also has a gentle side."},{"japanese":"便利になる一方で、危険も増えている。","romaji":"Benri ni naru ippō de, kiken mo fueteiru.","german":"While things are becoming more convenient, the dangers are increasing too."},{"japanese":"彼は優しい一方で、厳しい面もある。","romaji":"Kare wa yasashii ippō de, kibishii men mo aru.","german":"He's kind, but he also has a strict side."}],"notes":"","related":["n3-hanmen","n2-ippou-da"],"legacyIds":["n3-ippou-de"]},
{"id":"n2-ippou-da","pattern":"～一方だ","level":"N2","category":"Satzstrukturen","meaning":"more and more, increasingly, steadily","explanation":"一方だ expresses that a trend or change keeps on continuing in one direction, mostly in a negative context.","formation":"Verb (dictionary form) + 一方だ","examples":[{"japanese":"物価は上がる一方だ。","cloze":{"start":6,"answer":"一方だ","quiz":{"level":"N2","japanese":"物価は上がる一方だ。","german":"Prices just keep rising.","start":6,"answer":"一方だ","acceptedAnswers":["一方だ","ばかりだ"],"distractors":[{"text":"一方を","reason":"The statement is left without a closing predicate."},{"text":"一方な","reason":"The attributive な-form does not end the sentence."},{"text":"一方ます","reason":"ます is not attached directly to 一方."}]}},"romaji":"Bukka wa agaru ippō da.","german":"Prices just keep rising."},{"japanese":"地球の環境は悪くなる一方だ。","cloze":{"start":10,"answer":"一方だ"},"romaji":"Chikyū no kankyō wa waruku naru ippō da.","german":"The global environment just keeps getting worse."}],"notes":"Often used for negative trends, but can also be positive.","related":["n2-ippou-de","n2-bakari-da"]},
{"id":"n2-to-tomo-ni","pattern":"～とともに","level":"N2","category":"Satzstrukturen","meaning":"together with, along with, as well as","explanation":"とともに has three meanings: 1) together with (a person/thing), 2) at the same time as a change, 3) as well as, and also.","formation":"Noun + とともに / verb (dictionary form) + とともに","examples":[{"japanese":"家族とともに幸せな時間を過ごした。","cloze":{"start":2,"answer":"とともに","quiz":{"level":"N2","japanese":"家族とともに幸せな時間を過ごした。","german":"I spent a happy time together with my family.","start":2,"answer":"とともに","acceptedAnswers":["とともに","と一緒に"],"distractors":[{"text":"とともを","reason":"を does not form an accompaniment phrase here."},{"text":"とともの","reason":"The attributive form requires a noun."},{"text":"とともます","reason":"ます cannot be attached to ととも."}]}},"romaji":"Kazoku to tomo ni shiawase na jikan wo sugoshita.","german":"I spent a happy time together with my family."},{"japanese":"技術の発展とともに、生活も変わった。","cloze":{"start":5,"answer":"とともに"},"romaji":"Gijutsu no hatten to tomo ni, seikatsu mo kawatta.","german":"Along with the development of technology, our lives have changed too."}],"notes":"","related":["n2-to-douji-ni"]},
{"id":"n2-to-douji-ni","pattern":"～と同時に","level":"N2","category":"Satzstrukturen","meaning":"at the same time as, simultaneously","explanation":"と同時に expresses that two things happen at exactly the same time, or that something has two qualities at once.","formation":"Verb (dictionary form) / verb-た形 / noun + と同時に","examples":[{"japanese":"ベルが鳴ると同時に、生徒たちが教室を飛び出した。","cloze":{"start":5,"answer":"と同時に","quiz":{"level":"N2","japanese":"ベルが鳴ると同時に、生徒たちが教室を飛び出した。","german":"The moment the bell rang, the students rushed out of the classroom.","start":5,"answer":"と同時に","acceptedAnswers":["と同時に","やいなや"],"distractors":[{"text":"と同時を","reason":"を does not link simultaneous events here."},{"text":"と同時な","reason":"な does not link a following clause here."},{"text":"と同時ます","reason":"ます cannot be attached to 同時."}]}},"romaji":"Beru ga naru to dōji ni, seitotachi ga kyōshitsu wo tobidashita.","german":"The moment the bell rang, the students rushed out of the classroom."},{"japanese":"彼は医者であると同時に、作家でもある。","cloze":{"start":7,"answer":"と同時に"},"romaji":"Kare wa isha de aru to dōji ni, sakka de mo aru.","german":"He is a doctor and at the same time also a writer."}],"notes":"","related":["n2-to-tomo-ni"]},
{"id":"n2-wa-mochiron","pattern":"～はもちろん","level":"N2","category":"Satzstrukturen","meaning":"of course, not to mention","explanation":"はもちろん highlights that something goes without saying and adds that further things apply as well.","formation":"Noun + はもちろん(、noun + も)","examples":[{"japanese":"日本語はもちろん、英語も話せる。","cloze":{"start":3,"answer":"はもちろん","quiz":{"level":"N2","japanese":"日本語はもちろん、英語も話せる。","german":"He can speak Japanese, of course, but English too.","start":3,"answer":"はもちろん","acceptedAnswers":["はもちろん","はもとより"],"distractors":[{"text":"はもちろんな","reason":"もちろん does not form an attributive な-connection here."},{"text":"はもちろんを","reason":"を cannot be attached to the emphasis here."},{"text":"はもちろんます","reason":"ます cannot be attached directly to もちろん."}]}},"romaji":"Nihongo wa mochiron, Eigo mo hanaseru.","german":"He can speak Japanese, of course, but English too."},{"japanese":"週末はもちろん、平日も忙しい。","cloze":{"start":2,"answer":"はもちろん"},"romaji":"Shūmatsu wa mochiron, heijitsu mo isogashii.","german":"I'm busy on weekends, of course, but on weekdays too."}],"notes":"","related":["n2-wa-motoyori","n3-bakari-ka","n2-wa-tomokaku","n2-wa-iu-made-mo-nai"]},
{"id":"n2-wa-motoyori","pattern":"～はもとより","level":"N2","category":"Satzstrukturen","meaning":"not to mention; naturally … and beyond that","explanation":"はもとより is the more formal version of はもちろん. It stresses that something goes without saying and that further things come on top of it.","formation":"Noun + はもとより","examples":[{"japanese":"彼は国内はもとより、海外でも有名だ。","cloze":{"start":4,"answer":"はもとより","quiz":{"level":"N2","japanese":"彼は国内はもとより、海外でも有名だ。","german":"He is famous not only at home but abroad as well.","start":4,"answer":"はもとより","acceptedAnswers":["はもとより","はもちろん"],"distractors":[{"text":"はもとよりな","reason":"な does not link the two areas here."},{"text":"はもとよりを","reason":"を does not link 海外でも here."},{"text":"はもとよります","reason":"ます cannot be attached to もとより in this way."}]}},"romaji":"Kare wa kokunai wa motoyori, kaigai de mo yūmei da.","german":"He is famous not only at home but abroad as well."},{"japanese":"この病院は設備はもとより、スタッフの質も高い。","cloze":{"start":7,"answer":"はもとより"},"romaji":"Kono byōin wa setsubi wa motoyori, sutaffu no shitsu mo takai.","german":"This hospital has not only good facilities but also highly qualified staff."}],"notes":"More formal than はもちろん. Mainly used in written language.","related":["n2-wa-mochiron"]},
{"id":"n2-ijou-wa","pattern":"～以上(は)","level":"N2","category":"Satzstrukturen","meaning":"now that, as long as","explanation":"以上は expresses that, given an existing fact, one must act accordingly. Similar to からには.","formation":"Verb (dictionary form) / verb-た形 + 以上(は)","examples":[{"japanese":"学生である以上、勉強するべきだ。","romaji":"Gakusei de aru ijō, benkyō suru beki da.","german":"As long as you're a student, you should study."},{"japanese":"引き受けた以上は、責任を持ってやる。","cloze":{"start":5,"answer":"以上は","quiz":{"level":"N2","japanese":"引き受けた以上は、責任を持ってやる。","german":"Now that I've taken it on, I'll do it responsibly.","start":5,"answer":"以上は","acceptedAnswers":["以上は","上は","からには"],"distractors":[{"text":"以上を","reason":"を does not form a condition of obligation here."},{"text":"以上な","reason":"な does not link to the following clause here."},{"text":"以上ます","reason":"ます cannot be attached to 以上."}]}},"romaji":"Hikiuketa ijō wa, sekinin wo motte yaru.","german":"Now that I've taken it on, I'll do it responsibly."},{"japanese":"引き受けた以上は責任を持つ。","romaji":"Hikiuketa ijō wa sekinin o motsu.","german":"Now that I've taken it on, I'll take responsibility for it."}],"notes":"","related":["n3-kara-niwa","n2-ue-wa","n1-temae"],"legacyIds":["n3-ijou-wa"]},
{"id":"n2-irai","pattern":"～以来","level":"N2","category":"Satzstrukturen","meaning":"since, ever since","explanation":"以来 expresses that a state has continued since a certain point in time or event. It emphasizes the duration since then.","formation":"Verb-て形 + 以来 / noun + 以来","examples":[{"japanese":"日本に来て以来、毎日日本語を使っている。","cloze":{"start":5,"answer":"以来","quiz":{"level":"N2","japanese":"日本に来て以来、毎日日本語を使っている。","german":"Ever since I came to Japan, I've been using Japanese every day.","start":5,"answer":"以来","acceptedAnswers":["以来"],"distractors":[{"text":"以前","reason":"This refers to before coming, not since."},{"text":"以外","reason":"This means outside of or except, not since."},{"text":"以内","reason":"This refers to a time limit or boundary, not the start of an ongoing state."}]}},"romaji":"Nihon ni kite irai, mainichi Nihongo wo tsukatte iru.","german":"Ever since I came to Japan, I've been using Japanese every day."},{"japanese":"卒業以来、彼とは会っていない。","cloze":{"start":2,"answer":"以来"},"romaji":"Sotsugyō irai, kare to wa atte inai.","german":"I haven't seen him since graduation."}],"notes":"The state continues up to the present.","related":[]},
{"id":"n2-tokoro-ni","pattern":"～ところに","level":"N2","category":"Satzstrukturen","meaning":"just as, at the very moment when","explanation":"ところに describes something unexpected happening at a particular moment (in the middle of an action, or just before or after it).","formation":"Verb-ている / verb-た / verb-よう としている + ところに","examples":[{"japanese":"出かけようとしたところに、友達が来た。","cloze":{"start":8,"answer":"ところに","quiz":{"level":"N2","japanese":"出かけようとしたところに、友達が来た。","german":"Just as I was about to go out, a friend came over.","start":8,"answer":"ところに","acceptedAnswers":["ところに","ところへ"],"distractors":[{"text":"ところをに","reason":"Two such case particles cannot be combined here."},{"text":"ところな","reason":"な does not link 友達が来た here."},{"text":"ところます","reason":"ます cannot be attached to ところ."}]}},"romaji":"Dekakeyō to shita tokoro ni, tomodachi ga kita.","german":"Just as I was about to go out, a friend came over."},{"japanese":"寝ているところに電話がかかってきた。","cloze":{"start":4,"answer":"ところに"},"romaji":"Nete iru tokoro ni denwa ga kakatte kita.","german":"A phone call came while I was sleeping."}],"notes":"ところを = catching or interrupting someone in the middle of something.","related":["n3-ta-tokoro","n2-tokoro-wo-miru-to"]},
{"id":"n2-mono-dakara","pattern":"～ものだから / ～もんだから","level":"N2","category":"Satzstrukturen","meaning":"because, since (as an excuse/explanation)","explanation":"ものだから gives a reason and is often used as an excuse or justification. The speaker explains why something happened.","formation":"Verb/い-adj + ものだから / な-adj + な + ものだから / noun + な + ものだから","examples":[{"japanese":"道が混んでいたものだから、遅れてしまいました。","cloze":{"start":7,"answer":"ものだから","quiz":{"level":"N2","japanese":"道が混んでいたものだから、遅れてしまいました。","german":"The roads were congested, so I ended up being late.","start":7,"answer":"ものだから","acceptedAnswers":["ものだから","ので","から"],"distractors":[{"text":"ものをから","reason":"を and から do not form a reason connection here."},{"text":"ものだます","reason":"ます cannot be attached to the copula だ."},{"text":"ものなから","reason":"The nominal reason connection is ものだから."}]}},"romaji":"Michi ga konde ita mono dakara, okurete shimaimashita.","german":"The roads were congested, so I ended up being late."},{"japanese":"あまりにおいしかったものだから、食べすぎた。","cloze":{"start":10,"answer":"ものだから"},"romaji":"Amari ni oishikatta mono dakara, tabesugita.","german":"It was so delicious that I ate too much."},{"japanese":"急いでいたものだから、忘れ物をした。","romaji":"Isoide ita mono dakara, wasuremono o shita.","german":"I was in a hurry, so I forgot something."},{"japanese":"初めてだったもんだから、失敗してしまった。","romaji":"Hajimete datta mon dakara, shippai shite shimatta.","german":"It was my first time, so I messed up."}],"notes":"Colloquially also もんだから. Justifying tone.","related":["n3-mono-no","node","n3-mono-da","n1-koto-tote"],"legacyIds":["n3-mono-dakara"]},
{"id":"n2-koto-dakara","pattern":"～ことだから","level":"N2","category":"Satzstrukturen","meaning":"since it's (someone), knowing (someone)","explanation":"ことだから is used to express a guess or expectation based on a person's known character.","formation":"Noun + の + ことだから","examples":[{"japanese":"真面目な田中さんのことだから、きっと時間通りに来るだろう。","cloze":{"start":9,"answer":"ことだから","quiz":{"level":"N2","japanese":"真面目な田中さんのことだから、きっと時間通りに来るだろう。","german":"Knowing how conscientious Mr. Tanaka is, he'll surely come on time.","start":9,"answer":"ことだから","acceptedAnswers":["ことだから"],"distractors":[{"text":"ことをから","reason":"を does not form a reason connection with から here."},{"text":"ことだます","reason":"ます cannot be attached to だ."},{"text":"ことなから","reason":"The nominal reason connection is ことだから."}]}},"romaji":"Majime na Tanaka-san no koto dakara, kitto jikan dōri ni kuru darō.","german":"Knowing how conscientious Mr. Tanaka is, he'll surely come on time."},{"japanese":"あの人のことだから、また遅刻するに違いない。","cloze":{"start":4,"answer":"ことだから"},"romaji":"Ano hito no koto dakara, mata chikoku suru ni chigai nai.","german":"Knowing that person, they're bound to be late again."}],"notes":"Based on the person's known character.","related":["n2-koto-dashi"]},
{"id":"n2-koto-wa-nai","pattern":"～ことはない","level":"N2","category":"Satzstrukturen","meaning":"there's no need to, one doesn't have to","explanation":"ことはない reassures the listener: there's no reason to worry or no need to do something.","formation":"Verb (dictionary form) + ことはない","examples":[{"japanese":"そんなに心配することはないよ。","cloze":{"start":8,"answer":"ことはない","quiz":{"level":"N2","japanese":"そんなに心配することはないよ。","german":"There's no need to worry so much.","start":8,"answer":"ことはない","acceptedAnswers":["ことはない"],"distractors":[{"text":"ことはある","reason":"This asserts that something occurs instead of a lack of necessity."},{"text":"ことはないます","reason":"ない is not made polite by attaching ます."},{"text":"ことをない","reason":"ない does not take an object particle here."}]}},"romaji":"Sonna ni shinpai suru koto wa nai yo.","german":"There's no need to worry so much."},{"japanese":"急ぐことはない、まだ時間がある。","cloze":{"start":2,"answer":"ことはない"},"romaji":"Isogu koto wa nai, mada jikan ga aru.","german":"There's no need to hurry; we still have time."}],"notes":"Reassuring function. Similar to ～なくてもいい.","related":["n2-hodo-no-koto-dewa-nai"]},
{"id":"n2-wake-ga-nai","pattern":"～わけがない","level":"N2","category":"Satzstrukturen","meaning":"there's no way that, it's impossible that","explanation":"わけがない expresses a strong negation: it is absolutely impossible, or there's no logical reason, for something to be so.","formation":"Verb (dictionary form) / い-adj + わけがない / な-adj + な + わけがない","examples":[{"japanese":"彼がそんなことをするわけがない。","cloze":{"start":10,"answer":"わけがない","quiz":{"level":"N2","japanese":"彼がそんなことをするわけがない。","german":"There's no way he would do something like that.","start":10,"answer":"わけがない","acceptedAnswers":["わけがない","はずがない"],"distractors":[{"text":"わけがある","reason":"This asserts that there is a reason instead of rejecting the possibility."},{"text":"わけがないます","reason":"ない does not take an attached ます."},{"text":"わけをない","reason":"The negation needs が here, not を."}]}},"romaji":"Kare ga sonna koto wo suru wake ga nai.","german":"There's no way he would do something like that."},{"japanese":"こんな簡単な問題が分からないわけがない。","cloze":{"start":14,"answer":"わけがない"},"romaji":"Konna kantan na mondai ga wakaranai wake ga nai.","german":"There's no way anyone could fail to understand such an easy question."}],"notes":"Colloquially: わけない. Shows the speaker's strong conviction.","related":["n4-wake-ni-ikanai","n3-wake-dewa-nai"]},
{"id":"n2-to-iu-wake-dewa-nai","pattern":"～というわけではない","level":"N2","category":"Satzstrukturen","meaning":"that doesn't mean that; it's not that","explanation":"というわけではない denies an obvious conclusion. You correct a misunderstanding or a hasty assumption.","formation":"Sentence (plain form) + というわけではない","examples":[{"japanese":"日本に住んでいるからといって、日本語が完璧というわけではない。","cloze":{"start":21,"answer":"というわけではない","quiz":{"level":"N2","japanese":"日本に住んでいるからといって、日本語が完璧というわけではない。","german":"Just because you live in Japan doesn't mean your Japanese is perfect.","start":21,"answer":"というわけではない","acceptedAnswers":["というわけではない"],"distractors":[{"text":"というわけだ","reason":"This confirms the conclusion instead of qualifying it."},{"text":"というわけではないます","reason":"ない does not take an attached ます."},{"text":"というわけをない","reason":"The nominal negation requires ではない."}]}},"romaji":"Nihon ni sunde iru kara to itte, Nihongo ga kanpeki to iu wake dewa nai.","german":"Just because you live in Japan doesn't mean your Japanese is perfect."},{"japanese":"反対しているというわけではないが、もう少し考えたい。","cloze":{"start":6,"answer":"というわけではない"},"romaji":"Hantai shite iru to iu wake dewa nai ga, mō sukoshi kangaetai.","german":"It's not that I'm against it, but I'd like to think about it a little more."}],"notes":"Extended form of わけではない. Especially used with conclusions.","related":["n3-wake-dewa-nai"]},
{"id":"n2-ni-suginai","pattern":"～に過ぎない / ～にすぎない","level":"N2","category":"Satzstrukturen","meaning":"nothing more than, only, merely","explanation":"にすぎない downplays the importance of something. It expresses that something is less important, or less, than one might think.","formation":"Verb (dictionary form) / noun + にすぎない","examples":[{"japanese":"これは私の個人的な意見にすぎない。","cloze":{"start":11,"answer":"にすぎない","quiz":{"level":"N2","japanese":"これは私の個人的な意見にすぎない。","german":"This is merely my personal opinion.","start":11,"answer":"にすぎない","acceptedAnswers":["にすぎない"],"distractors":[{"text":"にすぎる","reason":"This does not create the limiting meaning \"merely\"."},{"text":"にすぎないます","reason":"ない does not take an attached ます."},{"text":"をすぎない","reason":"The link to the noun requires に here."}]}},"romaji":"Kore wa watashi no kojinteki na iken ni suginai.","german":"This is merely my personal opinion."},{"japanese":"まだ始まったにすぎない。","cloze":{"start":6,"answer":"にすぎない"},"romaji":"Mada hajimatta ni suginai.","german":"It has only just begun, nothing more."},{"japanese":"それは噂に過ぎない。","romaji":"Sore wa uwasa ni suginai.","german":"That's nothing more than a rumor."},{"japanese":"私は学生に過ぎません。","romaji":"Watashi wa gakusei ni sugimasen.","german":"I'm just a student."}],"notes":"A modest or understating expression.","related":["n2-ni-hoka-naranai","dake","shika-nai","n2-uchi-ni-hairanai"],"legacyIds":["n3-ni-suginai"]},
{"id":"n2-ni-hoka-naranai","pattern":"～にほかならない","level":"N2","category":"Satzstrukturen","meaning":"nothing other than, precisely","explanation":"にほかならない strongly emphasizes that something is exactly that and nothing else. It expresses conviction and emphasis.","formation":"Noun + にほかならない / ～からにほかならない","examples":[{"japanese":"成功したのは、努力の結果にほかならない。","cloze":{"start":12,"answer":"にほかならない","quiz":{"level":"N2","japanese":"成功したのは、努力の結果にほかならない。","german":"Our success is nothing other than the result of hard work.","start":12,"answer":"にほかならない","acceptedAnswers":["にほかならない"],"distractors":[{"text":"にほかなる","reason":"This negates the identification instead of expressing \"nothing other than\"."},{"text":"にほかなりますない","reason":"The polite negative is not formed with ますない."},{"text":"をほかならない","reason":"The fixed identification requires に."}]}},"romaji":"Seikō shita no wa, doryoku no kekka ni hoka naranai.","german":"Our success is nothing other than the result of hard work."},{"japanese":"それは彼の才能にほかならない。","cloze":{"start":7,"answer":"にほかならない"},"romaji":"Sore wa kare no sainō ni hoka naranai.","german":"That is nothing other than his talent."}],"notes":"Very formal and emphatic.","related":["n2-ni-suginai"]},
{"id":"n2-kara-miru-to","pattern":"～からみると","level":"N2","category":"Satzstrukturen","meaning":"from the standpoint of, from the perspective of","explanation":"からみると gives the perspective from which one views or judges a situation. Similar to からすると.","formation":"Noun + からみると / からみれば / からみて","examples":[{"japanese":"専門家からみると、この問題は簡単だ。","cloze":{"start":3,"answer":"からみると","quiz":{"level":"N2","japanese":"専門家からみると、この問題は簡単だ。","german":"From an expert's point of view, this problem is simple.","start":3,"answer":"からみると","acceptedAnswers":["からみると","から見れば","からすると"],"distractors":[{"text":"からみるを","reason":"を does not form a viewpoint condition here."},{"text":"からみるます","reason":"ます is not attached to 見る."},{"text":"からみればな","reason":"な cannot be attached to this conditional form."}]}},"romaji":"Senmonka kara miru to, kono mondai wa kantan da.","german":"From an expert's point of view, this problem is simple."},{"japanese":"結果からみて、この方法は効果的だった。","romaji":"Kekka kara mite, kono hōhō wa kōkateki datta.","german":"Judging from the results, this method was effective."}],"notes":"","related":["n1-kara-suru-to","n2-kara-iu-to"]},
{"id":"n2-ni-shite-mo","pattern":"～にしても","level":"N2","category":"Satzstrukturen","meaning":"even if, even though, even for","explanation":"にしても concedes a possibility but says that the outcome still doesn't change, or expresses that something is surprising.","formation":"Verb (dictionary form) / noun + にしても","examples":[{"japanese":"忙しいにしても、食事はきちんと取るべきだ。","cloze":{"start":3,"answer":"にしても","quiz":{"level":"N2","japanese":"忙しいにしても、食事はきちんと取るべきだ。","german":"Even if you're busy, you should eat properly.","start":3,"answer":"にしても","acceptedAnswers":["にしても","としても"],"distractors":[{"text":"にしてを","reason":"を does not form a concessive connection here."},{"text":"にするも","reason":"The connection requires the て-form before も."},{"text":"にしますも","reason":"The polite form is not combined with も here."}]}},"romaji":"Isogashii ni shite mo, shokuji wa kichinto toru beki da.","german":"Even if you're busy, you should eat properly."},{"japanese":"冗談にしても、ひどすぎる。","cloze":{"start":2,"answer":"にしても"},"romaji":"Jōdan ni shite mo, hidosugiru.","german":"Even as a joke, that's going too far."}],"notes":"","related":["n3-to-shitemo","n3-ni-shite-wa"]},
{"id":"n2-amari","pattern":"～あまり","level":"N2","category":"Satzstrukturen","meaning":"out of too much, out of sheer","explanation":"あまり expresses that a feeling or state is so extreme that it leads to an (often unusual) result.","formation":"Verb (dictionary form) / verb-た形 + あまり / noun + の + あまり","examples":[{"japanese":"嬉しさのあまり、泣いてしまった。","cloze":{"start":4,"answer":"あまり","quiz":{"level":"N2","japanese":"嬉しさのあまり、泣いてしまった。","german":"I cried out of sheer happiness.","start":4,"answer":"あまり","acceptedAnswers":["あまり"],"distractors":[{"text":"あまりを","reason":"を does not link a cause-and-effect clause here."},{"text":"あまりな","reason":"な does not connect with 泣いてしまった here."},{"text":"あまります","reason":"ます cannot be attached to the noun あまり."}]}},"romaji":"Ureshisa no amari, naite shimatta.","german":"I cried out of sheer happiness."},{"japanese":"考えすぎたあまり、眠れなくなった。","cloze":{"start":5,"answer":"あまり"},"romaji":"Kangaesugita amari, nemurenaku natta.","german":"I thought about it so much that I couldn't sleep."}],"notes":"Often used with emotions or intense states.","related":[]},
{"id":"n2-dake-ni","pattern":"～だけに","level":"N2","category":"Satzstrukturen","meaning":"precisely because, as one would expect","explanation":"だけに expresses that a result matches exactly what one would expect given the circumstances – \"precisely because\" the condition is what it is.","formation":"Verb/い-adj/な-adj/noun + だけに","examples":[{"japanese":"さすが有名なレストランだけに、料理がおいしい。","cloze":{"start":11,"answer":"だけに","quiz":{"level":"N2","japanese":"さすが有名なレストランだけに、料理がおいしい。","german":"As you'd expect from a famous restaurant, the food is delicious.","start":11,"answer":"だけに","acceptedAnswers":["だけに","だけあって"],"distractors":[{"text":"だけをに","reason":"を and に do not form a joint connection here."},{"text":"だけな","reason":"な does not link the explanatory following clause here."},{"text":"だけます","reason":"ます cannot be attached to だけ."}]}},"romaji":"Sasuga yūmei na resutoran dake ni, ryōri ga oishii.","german":"As you'd expect from a famous restaurant, the food is delicious."},{"japanese":"期待が大きかっただけに、失望も大きかった。","cloze":{"start":8,"answer":"だけに"},"romaji":"Kitai ga ōkikatta dake ni, shitsubō mo ōkikatta.","german":"Precisely because our expectations were so high, the disappointment was just as great."}],"notes":"","related":["n2-dake-atte"]},
{"id":"n2-dake-atte","pattern":"～だけあって","level":"N2","category":"Satzstrukturen","meaning":"as one would expect, just as expected","explanation":"だけあって expresses recognition: the result matches what you would expect based on a known quality. Positive tone.","formation":"Verb/い-Adj/な-Adj/Noun + だけあって","examples":[{"japanese":"10年も日本に住んでいただけあって、日本語がペラペラだ。","cloze":{"start":12,"answer":"だけあって","quiz":{"level":"N2","japanese":"10年も日本に住んでいただけあって、日本語がペラペラだ。","german":"As you'd expect from someone who has lived in Japan for 10 years, he speaks fluent Japanese.","start":12,"answer":"だけあって","acceptedAnswers":["だけあって","だけに"],"distractors":[{"text":"だけある","reason":"The dictionary form does not link the following clause here."},{"text":"だけあった","reason":"The attributive past form does not link the following clause here."},{"text":"だけあります","reason":"The finite form ends the sentence instead of attaching the reason."}]}},"romaji":"Jūnen mo Nihon ni sunde ita dake atte, Nihongo ga perapera da.","german":"As you'd expect from someone who has lived in Japan for 10 years, he speaks fluent Japanese."},{"japanese":"プロだけあって、さすがに上手だ。","cloze":{"start":2,"answer":"だけあって"},"romaji":"Puro dake atte, sasuga ni jōzu da.","german":"As you'd expect from a professional, he's really good."},{"japanese":"彼はプロだけあって、仕事が速い。","romaji":"Kare wa puro dake atte, shigoto ga hayai.","german":"As you'd expect from a professional, he works fast."},{"japanese":"高いだけあって、品質は良い。","romaji":"Takai dake atte, hinshitsu wa yoi.","german":"It's expensive, but the quality is correspondingly good."}],"notes":"Always positive/appreciative. Similar to だけに, but more strongly appreciative.","related":["n2-dake-ni","kara-because"],"legacyIds":["n1-dakeatte"]},
{"id":"n2-ni-kakete-wa","pattern":"～にかけては","level":"N2","category":"Satzstrukturen","meaning":"when it comes to ..., as far as ... is concerned","explanation":"にかけては emphasizes that someone is especially good or outstanding in a particular area.","formation":"Noun + にかけては","examples":[{"japanese":"料理にかけては、彼の右に出る者はいない。","cloze":{"start":2,"answer":"にかけては","quiz":{"level":"N2","japanese":"料理にかけては、彼の右に出る者はいない。","german":"When it comes to cooking, there's no one who can beat him.","start":2,"answer":"にかけては","acceptedAnswers":["にかけては"],"distractors":[{"text":"をかけては","reason":"This makes cooking the object of かける instead of the area of skill."},{"text":"にかけるは","reason":"は cannot attach to the dictionary form here."},{"text":"にかけますは","reason":"は cannot attach to the polite form here."}]}},"romaji":"Ryōri ni kakete wa, kare no migi ni deru mono wa inai.","german":"When it comes to cooking, there's no one who can beat him."},{"japanese":"スピードにかけては、彼女がチーム一だ。","cloze":{"start":4,"answer":"にかけては"},"romaji":"Supīdo ni kakete wa, kanojo ga chīmu ichi da.","german":"When it comes to speed, she's the best on the team."}],"notes":"Always positive; highlights a strength.","related":[]},
{"id":"n2-koto-ka","pattern":"～ことか","level":"N2","category":"Satzstrukturen","meaning":"how very ...! (exclamation)","explanation":"ことか expresses strong emotion: admiration, surprise or longing. A rhetorical exclamation.","formation":"どんなに / どれほど / 何度 + Verb/Adj + ことか","examples":[{"japanese":"どんなに嬉しかったことか。","cloze":{"start":9,"answer":"ことか","quiz":{"level":"N2","japanese":"どんなに嬉しかったことか。","german":"How happy I was!","start":9,"answer":"ことか","acceptedAnswers":["ことか"],"distractors":[{"text":"ことを","reason":"The object particle does not complete this exclamation."},{"text":"ことな","reason":"な does not form a closing exclamation here."},{"text":"ことます","reason":"ます cannot be attached directly to こと."}]}},"romaji":"Donna ni ureshikatta koto ka.","german":"How happy I was!"},{"japanese":"何度やめようと思ったことか。","cloze":{"start":10,"answer":"ことか"},"romaji":"Nando yameyō to omotta koto ka.","german":"How many times I thought about quitting!"}],"notes":"Often combined with どんなに, どれほど, 何度.","related":["n2-mono-ka","n2-koto-ni-wa"]},
{"id":"n2-mono-ka","pattern":"～ものか / ～もんか","level":"N2","category":"Satzstrukturen","meaning":"no way!, never!","explanation":"ものか expresses strong negation or determination. The speaker flatly refuses.","formation":"Verb dictionary form / い-Adj + ものか / もんか (colloquial)","examples":[{"japanese":"あんな店に二度と行くものか。","cloze":{"start":10,"answer":"ものか","quiz":{"level":"N2","japanese":"あんな店に二度と行くものか。","german":"I'm never going to a shop like that again!","start":10,"answer":"ものか","acceptedAnswers":["ものか","もんか"],"distractors":[{"text":"ものだ","reason":"This states a typical characteristic instead of a firm refusal."},{"text":"ものをます","reason":"ます cannot be attached to this particle combination."},{"text":"ものなか","reason":"The rhetorical question uses ものか without な."}]}},"romaji":"Anna mise ni nido to iku mono ka.","german":"I'm never going to a shop like that again!"},{"japanese":"負けるもんか！","romaji":"Makeru mon ka!","german":"There's no way I'm going to lose!"},{"japanese":"あんな所に二度と行くものか。","romaji":"Anna tokoro ni nido to iku mono ka.","german":"I'm never going to a place like that again!"}],"notes":"Colloquial: もんか. Strong emotional rejection.","related":["n2-koto-ka"],"legacyIds":["n3-mono-ka"]},
{"id":"n2-ka-to-omottara","pattern":"～かと思ったら","level":"N2","category":"Satzstrukturen","meaning":"just when I thought, no sooner than","explanation":"かと思ったら expresses that a situation changes surprisingly quickly. No sooner did you think A than B was already happening.","formation":"Verb-た形 + かと思ったら / かと思うと","examples":[{"japanese":"泣いていたかと思ったら、もう笑っている。","cloze":{"start":5,"answer":"かと思ったら","quiz":{"level":"N2","japanese":"泣いていたかと思ったら、もう笑っている。","german":"One moment he was crying, and now he's already laughing.","start":5,"answer":"かと思ったら","acceptedAnswers":["かと思ったら"],"distractors":[{"text":"かを思ったら","reason":"The content of the thought needs と."},{"text":"かと思うたら","reason":"The past conditional of 思う is 思ったら."},{"text":"かと思いますたら","reason":"The conditional is not formed with ますたら."}]}},"romaji":"Naite ita ka to omottara, mō waratte iru.","german":"One moment he was crying, and now he's already laughing."},{"japanese":"晴れたかと思ったら、また雨が降り出した。","cloze":{"start":3,"answer":"かと思ったら"},"romaji":"Hareta ka to omottara, mata ame ga furidashita.","german":"Just when I thought it had cleared up, it started raining again."}],"notes":"Emphasizes the quick, surprising change.","related":["n3-totan"]},
{"id":"n2-ka-no-you-ni","pattern":"～かのように","level":"N2","category":"Satzstrukturen","meaning":"as if, as though","explanation":"かのように describes something that does not match reality but looks or feels that way. A comparison with a hypothetical situation.","formation":"Verb/い-Adj/な-Adj + である + かのように / Noun + である + かのように","examples":[{"japanese":"彼は何も知らないかのように振る舞った。","cloze":{"start":8,"answer":"かのように","quiz":{"level":"N2","japanese":"彼は何も知らないかのように振る舞った。","german":"He acted as if he knew nothing.","start":8,"answer":"かのように","acceptedAnswers":["かのように"],"distractors":[{"text":"かのようを","reason":"を does not form an adverbial comparison here."},{"text":"かのような","reason":"The attributive form requires a noun instead of 振る舞った."},{"text":"かのようます","reason":"ます cannot be attached directly to よう."}]}},"romaji":"Kare wa nani mo shiranai ka no yō ni furumatta.","german":"He acted as if he knew nothing."},{"japanese":"まるで夢であるかのような出来事だった。","romaji":"Marude yume de aru ka no yō na dekigoto datta.","german":"It was an event that seemed almost like a dream."}],"notes":"Often combined with まるで. Literary/formal.","related":["n2-mo-douzen"]},
{"id":"n2-wo-keiki-ni","pattern":"～を契機に","level":"N2","category":"Satzstrukturen","meaning":"taking ... as an occasion, as a turning point","explanation":"を契機に describes an event that served as a turning point or trigger for an important change. More formal than をきっかけに.","formation":"Noun + を契機に(して) / を契機として","examples":[{"japanese":"震災を契機に、防災意識が高まった。","cloze":{"start":2,"answer":"を契機に","quiz":{"level":"N2","japanese":"震災を契機に、防災意識が高まった。","german":"The earthquake disaster prompted a rise in disaster-preparedness awareness.","start":2,"answer":"を契機に","acceptedAnswers":["を契機に","をきっかけに"],"distractors":[{"text":"を契機を","reason":"The phrase marking the occasion ends with に."},{"text":"に契機に","reason":"The starting point needs を here."},{"text":"を契機な","reason":"契機 does not form a な-connection here."}]}},"romaji":"Shinsai wo keiki ni, bōsai ishiki ga takamatta.","german":"The earthquake disaster prompted a rise in disaster-preparedness awareness."},{"japanese":"結婚を契機に、生活を見直した。","cloze":{"start":2,"answer":"を契機に"},"romaji":"Kekkon wo keiki ni, seikatsu wo minaoshita.","german":"He took his marriage as an occasion to rethink his life."}],"notes":"More formal than をきっかけに. Often used for social changes.","related":["n3-o-kikkake-ni"]},
{"id":"n2-ni-todomarazu","pattern":"～にとどまらず","level":"N2","category":"Satzstrukturen","meaning":"not limited to, going beyond ...","explanation":"にとどまらず expresses that something does not stop at one point but spreads beyond it.","formation":"Noun + にとどまらず","examples":[{"japanese":"この問題は一国にとどまらず、世界全体に影響を与えている。","cloze":{"start":7,"answer":"にとどまらず","quiz":{"level":"N2","japanese":"この問題は一国にとどまらず、世界全体に影響を与えている。","german":"This problem is not limited to one country; it is affecting the whole world.","start":7,"answer":"にとどまらず","acceptedAnswers":["にとどまらず","に限らず"],"distractors":[{"text":"にとどまる","reason":"This asserts a limitation instead of going beyond it."},{"text":"にとどまった","reason":"This asserts a limitation in the past."},{"text":"をとどまらず","reason":"With とどまる, the scope needs に."}]}},"romaji":"Kono mondai wa ikkoku ni todomarazu, sekai zentai ni eikyō wo ataete iru.","german":"This problem is not limited to one country; it is affecting the whole world."},{"japanese":"彼の活躍は国内にとどまらず、海外にも広がっている。","cloze":{"start":7,"answer":"にとどまらず"},"romaji":"Kare no katsuyaku wa kokunai ni todomarazu, kaigai ni mo hirogatte iru.","german":"His activities go beyond his home country and are spreading abroad as well."}],"notes":"Formal. Similar to に限らず, but emphasizes spreading.","related":["n2-ni-kagirazu"]},
{"id":"n2-kagiri-dewa","pattern":"～限りでは","level":"N2","category":"Satzstrukturen","meaning":"as far as (I know/can see)","explanation":"限りでは limits a statement to the scope of your own knowledge or perception.","formation":"Verb dictionary form / Verb-た形 + 限りでは","examples":[{"japanese":"私が知っている限りでは、彼は独身だ。","cloze":{"start":7,"answer":"限りでは","quiz":{"level":"N2","japanese":"私が知っている限りでは、彼は独身だ。","german":"As far as I know, he's single.","start":7,"answer":"限りでは","acceptedAnswers":["限りでは","限り"],"distractors":[{"text":"限りを","reason":"を does not limit the scope of knowledge here."},{"text":"限りな","reason":"な does not link a following clause here."},{"text":"限ります","reason":"ます cannot be attached to the noun 限り here."}]}},"romaji":"Watashi ga shitte iru kagiri dewa, kare wa dokushin da.","german":"As far as I know, he's single."},{"japanese":"調べた限りでは、問題はなさそうだ。","cloze":{"start":3,"answer":"限りでは"},"romaji":"Shirabeta kagiri dewa, mondai wa nasasō da.","german":"As far as I've been able to find out, there doesn't seem to be any problem."}],"notes":"Limits the statement to your own knowledge.","related":["n3-kagiri"]},
{"id":"n2-to-shitara","pattern":"～としたら","level":"N2","category":"Satzstrukturen","meaning":"supposing that, if","explanation":"としたら sets up a hypothetical assumption and asks what would happen or be true in that case.","formation":"Verb/い-Adj/な-Adj/Noun + だ + としたら / とすれば / とすると","examples":[{"japanese":"もし宝くじが当たったとしたら、何に使う？","cloze":{"start":10,"answer":"としたら","quiz":{"level":"N2","japanese":"もし宝くじが当たったとしたら、何に使う？","german":"Supposing you won the lottery, what would you spend it on?","start":10,"answer":"としたら","acceptedAnswers":["としたら","とすれば","とすると"],"distractors":[{"text":"をしたら","reason":"The assumed statement needs と."},{"text":"とするたら","reason":"The conditional form of する is したら."},{"text":"としますたら","reason":"The conditional is not formed with ますたら."}]}},"romaji":"Moshi takarakuji ga atatta to shitara, nani ni tsukau?","german":"Supposing you won the lottery, what would you spend it on?"},{"japanese":"彼の言うことが本当だとしたら、大変なことだ。","cloze":{"start":10,"answer":"としたら"},"romaji":"Kare no iu koto ga hontō da to shitara, taihen na koto da.","german":"If what he says is true, that's a serious matter."}],"notes":"としたら/とすれば/とすると are largely interchangeable.","related":["n3-to-shitemo","n3-to-suru-to"]},
{"id":"n2-te-kara-to-iu-mono","pattern":"～てからというもの","level":"N2","category":"Satzstrukturen","meaning":"ever since (emphasizing the change)","explanation":"てからというもの emphasizes that a noticeable, lasting change has taken place since a particular event.","formation":"Verb-て形 + からというもの","examples":[{"japanese":"子供が生まれてからというもの、毎日が忙しい。","cloze":{"start":6,"answer":"てからというもの","quiz":{"level":"N2","japanese":"子供が生まれてからというもの、毎日が忙しい。","german":"Ever since our child was born, every day has been hectic.","start":6,"answer":"てからというもの","acceptedAnswers":["てからというもの","て以来"],"distractors":[{"text":"てからをいうもの","reason":"The set phrase links the expression with と."},{"text":"てからというものます","reason":"ます cannot be attached directly to もの."},{"text":"てからというものな","reason":"な does not link a following clause here."}]}},"romaji":"Kodomo ga umarete kara to iu mono, mainichi ga isogashii.","german":"Ever since our child was born, every day has been hectic."},{"japanese":"日本に来てからというもの、和食ばかり食べている。","cloze":{"start":4,"answer":"てからというもの"},"romaji":"Nihon ni kite kara to iu mono, washoku bakari tabete iru.","german":"Ever since I came to Japan, I've been eating nothing but Japanese food."}],"notes":"Stronger and more emotional than ～て以来.","related":["n2-irai"]},
{"id":"n2-te-hajimete","pattern":"～て初めて / ～てはじめて","level":"N3","category":"Satzstrukturen","meaning":"only after, for the first time through","explanation":"てはじめて expresses that you only recognize or understand something for the first time through an experience.","formation":"Verb-て形 + はじめて","examples":[{"japanese":"病気になってはじめて、健康のありがたさが分かった。","cloze":{"start":5,"answer":"てはじめて","quiz":{"level":"N3","japanese":"病気になってはじめて、健康のありがたさが分かった。","german":"It was only when I got sick that I understood the value of good health.","start":5,"answer":"てはじめて","acceptedAnswers":["てはじめて"],"distractors":[{"text":"たはじめて","reason":"The link to the moment of first realization needs the て-form."},{"text":"てはじめた","reason":"The past form does not connect with 健康のありがたさが分かった here."},{"text":"てはじめます","reason":"The finite polite form ends the sentence."}]}},"romaji":"Byōki ni natte hajimete, kenkō no arigatasa ga wakatta.","german":"It was only when I got sick that I understood the value of good health."},{"japanese":"日本に来てはじめて、本物の寿司を食べた。","cloze":{"start":4,"answer":"てはじめて"},"romaji":"Nihon ni kite hajimete, honmono no sushi wo tabeta.","german":"It was only after coming to Japan that I ate real sushi."},{"japanese":"日本に来て初めて寿司を食べた。","romaji":"Nihon ni kite hajimete sushi o tabeta.","german":"I ate sushi for the first time after coming to Japan."},{"japanese":"失って初めて大切さに気づいた。","romaji":"Ushinatte hajimete taisetsusa ni kizuita.","german":"Only after losing it did I realize how important it was."}],"notes":"","related":["n3-te-koso"],"legacyIds":["n3-te-hajimete"]},
{"id":"n2-to-itte-mo","pattern":"～といっても","level":"N2","category":"Satzstrukturen","meaning":"even though one says, although (qualification)","explanation":"といっても qualifies a previous statement: what was said is true, but it is not as extreme as you might think.","formation":"Sentence (plain) + といっても","examples":[{"japanese":"日本語ができるといっても、挨拶程度です。","cloze":{"start":7,"answer":"といっても","quiz":{"level":"N2","japanese":"日本語ができるといっても、挨拶程度です。","german":"I can speak Japanese, but only enough for greetings.","start":7,"answer":"といっても","acceptedAnswers":["といっても"],"distractors":[{"text":"をいっても","reason":"The quoted content needs と."},{"text":"というも","reason":"The concessive link needs 言っても."},{"text":"といいますも","reason":"も is not attached to the polite form here."}]}},"romaji":"Nihongo ga dekiru to itte mo, aisatsu teido desu.","german":"I can speak Japanese, but only enough for greetings."},{"japanese":"広いといっても、6畳しかない。","cloze":{"start":2,"answer":"といっても"},"romaji":"Hiroi to itte mo, rokujō shika nai.","german":"It may be called spacious, but it's only six tatami mats."}],"notes":"Corrects a possible exaggeration in the previous statement.","related":["n2-to-wa-ie","n3-to-ieba"]},
{"id":"n2-to-wa-ie","pattern":"～とはいえ","level":"N2","category":"Satzstrukturen","meaning":"although, even though it is true that","explanation":"とはいえ concedes a fact but adds contrasting or qualifying information. More formal than けど.","formation":"Sentence (plain) + とはいえ / Noun + とはいえ","examples":[{"japanese":"春とはいえ、まだ寒い日がある。","cloze":{"start":1,"answer":"とはいえ","quiz":{"level":"N2","japanese":"春とはいえ、まだ寒い日がある。","german":"Although it's spring, there are still cold days.","start":1,"answer":"とはいえ","acceptedAnswers":["とはいえ","だけれども"],"distractors":[{"text":"をはいえ","reason":"The quoting link needs と."},{"text":"とはいいます","reason":"The finite polite form does not form a concessive link here."},{"text":"とはいえな","reason":"な cannot be attached to this combination."}]}},"romaji":"Haru to wa ie, mada samui hi ga aru.","german":"Although it's spring, there are still cold days."},{"japanese":"合格したとはいえ、油断はできない。","cloze":{"start":4,"answer":"とはいえ"},"romaji":"Gōkaku shita to wa ie, yudan wa dekinai.","german":"Although I passed, I can't let my guard down."}],"notes":"Formal written language.","related":["n2-to-itte-mo","n3-mono-no","n2-to-wa-iu-mono-no"]},
{"id":"n2-nagara-mo","pattern":"～ながらも","level":"N2","category":"Satzstrukturen","meaning":"although, despite","explanation":"ながらも expresses a contradiction: despite a certain quality or situation, something contrary exists. Emphasizes the contrast.","formation":"Verb ます-stem + ながらも / い-Adj + ながらも / Noun + ながらも","examples":[{"japanese":"小さいながらも、居心地のいい部屋だ。","cloze":{"start":3,"answer":"ながらも","quiz":{"level":"N2","japanese":"小さいながらも、居心地のいい部屋だ。","german":"Although it's small, it's a cozy room.","start":3,"answer":"ながらも","acceptedAnswers":["ながらも","けれども"],"distractors":[{"text":"ながらを","reason":"を does not form a concessive link here."},{"text":"ながらます","reason":"ます cannot be attached to ながら."},{"text":"ながらな","reason":"な does not link to 居心地のいい部屋だ here."}]}},"romaji":"Chiisai nagara mo, igokochi no ii heya da.","german":"Although it's small, it's a cozy room."},{"japanese":"残念ながらも、今回は参加できない。","cloze":{"start":2,"answer":"ながらも"},"romaji":"Zannen nagara mo, konkai wa sanka dekinai.","german":"Unfortunately, I can't take part this time."}],"notes":"ながら (simultaneously) vs. ながらも (although): a difference in meaning!","related":["n3-mono-no"]},
{"id":"n2-nuki-ni-shite","pattern":"～ぬきにして","level":"N2","category":"Satzstrukturen","meaning":"leaving ... aside, without","explanation":"ぬきにして expresses that you deliberately leave out or set aside a particular aspect.","formation":"Noun + (は)ぬきにして / ぬきにしても","examples":[{"japanese":"冗談はぬきにして、真面目に話しましょう。","cloze":{"start":3,"answer":"ぬきにして","quiz":{"level":"N2","japanese":"冗談はぬきにして、真面目に話しましょう。","german":"Joking aside, let's talk seriously.","start":3,"answer":"ぬきにして","acceptedAnswers":["ぬきにして","抜きにして"],"distractors":[{"text":"ぬきをして","reason":"The expression uses ぬきにする."},{"text":"ぬきにする","reason":"The dictionary form does not link the following clause here."},{"text":"ぬきにします","reason":"The finite polite form ends the sentence."}]}},"romaji":"Jōdan wa nuki ni shite, majime ni hanashimashō.","german":"Joking aside, let's talk seriously."},{"japanese":"お世辞ぬきにして、本当に素晴らしい作品だ。","cloze":{"start":3,"answer":"ぬきにして"},"romaji":"Oseji nuki ni shite, hontō ni subarashii sakuhin da.","german":"No flattery: it really is a wonderful work."}],"notes":"","related":["n2-nuki-de","n2-wo-nozoite"]},
{"id":"n2-wo-motte","pattern":"～をもって","level":"N2","category":"Satzstrukturen","meaning":"with, by means of (formal); hereby","explanation":"をもって is used in formal contexts: 1) with a means/method, 2) as of a certain point in time (deadline).","formation":"Noun + をもって","examples":[{"japanese":"本日をもって、このサービスを終了いたします。","cloze":{"start":2,"answer":"をもって","quiz":{"level":"N2","japanese":"本日をもって、このサービスを終了いたします。","german":"As of today, we will be discontinuing this service.","start":2,"answer":"をもって","acceptedAnswers":["をもって"],"distractors":[{"text":"をもつて","reason":"The て-form of 持つ is 持って, with a small っ."},{"text":"をもちます","reason":"The finite form does not form a link marking the end point in time here."},{"text":"にをもって","reason":"に and を cannot appear together here."}]}},"romaji":"Honjitsu wo motte, kono sābisu wo shūryō itashimasu.","german":"As of today, we will be discontinuing this service."},{"japanese":"誠意をもって対応する。","cloze":{"start":2,"answer":"をもって"},"romaji":"Seii wo motte taiō suru.","german":"To respond with sincerity."}],"notes":"Very formal, often in announcements and business language.","related":[]},
{"id":"n2-ni-ataru","pattern":"～に当たる","level":"N2","category":"Satzstrukturen","meaning":"to correspond to, to be equivalent to","explanation":"に当たる expresses that something corresponds to a certain category or is equivalent to a certain concept.","formation":"Noun + に当たる","examples":[{"japanese":"日本の「お盆」は、ドイツの「Allerheiligen」に当たる。","cloze":{"start":28,"answer":"に当たる","quiz":{"level":"N2","japanese":"日本の「お盆」は、ドイツの「Allerheiligen」に当たる。","german":"Japan's \"Obon\" corresponds to Germany's \"Allerheiligen\" (All Saints' Day).","start":28,"answer":"に当たる","acceptedAnswers":["に当たる","に相当する"],"distractors":[{"text":"に当たりまする","reason":"る cannot be attached to ます."},{"text":"に当たないます","reason":"The verb form is not built this way."},{"text":"に当たらない","reason":"This negates the stated correspondence."}]}},"romaji":"Nihon no \"Obon\" wa, Doitsu no \"Allerheiligen\" ni ataru.","german":"Japan's \"Obon\" corresponds to Germany's \"Allerheiligen\" (All Saints' Day)."},{"japanese":"彼女は社長の娘に当たる。","cloze":{"start":7,"answer":"に当たる"},"romaji":"Kanojo wa shachō no musume ni ataru.","german":"She is the company president's daughter (she stands in that relationship to him)."}],"notes":"","related":[]},
{"id":"n2-to-iu-koto-da","pattern":"～ということだ","level":"N2","category":"Satzstrukturen","meaning":"I hear that; that means","explanation":"ということだ has two meanings: 1) hearsay (I've heard that), 2) conclusion (so that means).","formation":"Sentence (plain) + ということだ","examples":[{"japanese":"彼は来月結婚するということだ。","cloze":{"start":8,"answer":"ということだ","quiz":{"level":"N2","japanese":"彼は来月結婚するということだ。","german":"I hear he's getting married next month.","start":8,"answer":"ということだ","acceptedAnswers":["ということだ","そうだ"],"distractors":[{"text":"をいうことだ","reason":"The reported content takes と."},{"text":"ということます","reason":"ます cannot be attached directly to こと."},{"text":"ということな","reason":"The attributive な-form does not end the sentence here."}]}},"romaji":"Kare wa raigetsu kekkon suru to iu koto da.","german":"I hear he's getting married next month."},{"japanese":"つまり、全員賛成だということですね。","romaji":"Tsumari, zen'in sansei da to iu koto desu ne.","german":"So that means everyone agrees, right?"}],"notes":"Hearsay or logical conclusion, depending on context.","related":["n3-to-iu-mono-da","n2-to-no-koto-da"]},
{"id":"n2-to-iu-mono-dewa-nai","pattern":"～というものではない","level":"N2","category":"Satzstrukturen","meaning":"it is not necessarily the case that","explanation":"というものではない rejects a simplified or absolute statement. Reality is more complex.","formation":"Verb plain form / い-Adj / な-Adj + というものではない","examples":[{"japanese":"お金があれば幸せだというものではない。","cloze":{"start":9,"answer":"というものではない","quiz":{"level":"N2","japanese":"お金があれば幸せだというものではない。","german":"Having money doesn't automatically make you happy.","start":9,"answer":"というものではない","acceptedAnswers":["というものではない","というわけではない"],"distractors":[{"text":"というものだ","reason":"This confirms the equation instead of rejecting it."},{"text":"というものではないます","reason":"ない does not take an attached ます."},{"text":"をいうものではない","reason":"The quoted content needs と."}]}},"romaji":"Okane ga areba shiawase da to iu mono dewa nai.","german":"Having money doesn't automatically make you happy."},{"japanese":"たくさん食べればいいというものではない。","cloze":{"start":10,"answer":"というものではない"},"romaji":"Takusan tabereba ii to iu mono dewa nai.","german":"Eating a lot isn't necessarily a good thing."}],"notes":"Corrects an overly simple view.","related":["n3-to-iu-mono-da","n2-mono-dewa-nai"]},
{"id":"n2-te-bakari-wa-irarenai","pattern":"～てばかりはいられない","level":"N2","category":"Satzstrukturen","meaning":"can't just keep doing ..., have to act differently","explanation":"てばかりはいられない expresses that you cannot remain in a state forever and have to take action.","formation":"Verb-て形 + ばかりはいられない / ばかりもいられない","examples":[{"japanese":"泣いてばかりはいられない。前に進まなくては。","cloze":{"start":2,"answer":"てばかりはいられない","quiz":{"level":"N2","japanese":"泣いてばかりはいられない。前に進まなくては。","german":"I can't just keep crying. I have to move forward.","start":2,"answer":"てばかりはいられない","acceptedAnswers":["てばかりはいられない"],"distractors":[{"text":"てばかりはいられます","reason":"This affirms that it is possible to just keep crying."},{"text":"てばかりはいられないます","reason":"ない does not take an attached ます."},{"text":"たばかりはいられない","reason":"After 泣い, this ongoing action needs the て-connection."}]}},"romaji":"Naite bakari wa irarenai. Mae ni susumanakute wa.","german":"I can't just keep crying. I have to move forward."},{"japanese":"遊んでばかりはいられない、そろそろ仕事を始めよう。","romaji":"Asonde bakari wa irarenai, sorosoro shigoto wo hajimeyō.","german":"I can't just keep playing around; I should start working soon."}],"notes":"","related":["n2-te-wa-irarenai"]},
{"id":"n2-nai-mono-ka","pattern":"～ないものか","level":"N2","category":"Satzstrukturen","meaning":"isn't there some way to, can't one somehow","explanation":"ないものか expresses a strong wish that something might be possible. The speaker is desperately looking for a solution.","formation":"Verb-ない形 + ものか / ものだろうか","examples":[{"japanese":"もっと簡単にできないものか。","cloze":{"start":8,"answer":"ないものか","quiz":{"level":"N2","japanese":"もっと簡単にできないものか。","german":"Can't this be done more easily somehow?","start":8,"answer":"ないものか","acceptedAnswers":["ないものか"],"distractors":[{"text":"ないものをます","reason":"ます cannot be attached to this particle combination."},{"text":"ないものなか","reason":"The wishful question uses ものか without な."},{"text":"ないものかます","reason":"ます cannot be attached to the question particle."}]}},"romaji":"Motto kantan ni dekinai mono ka.","german":"Can't this be done more easily somehow?"},{"japanese":"何とかならないものだろうか。","romaji":"Nantoka naranai mono darō ka.","german":"Isn't there something that can be done about it?"},{"japanese":"何とか解決できないものか。","romaji":"Nantoka kaiketsu dekinai mono ka.","german":"Isn't there some way to solve this?"},{"japanese":"もっと簡単にできないものだろうか。","romaji":"Motto kantan ni dekinai mono darō ka.","german":"Couldn't this be done more easily somehow?"}],"notes":"Rhetorical; expresses frustration and a wish.","related":[],"legacyIds":["n1-naimonoka2"]},
{"id":"n2-ni-kotaete","pattern":"～にこたえて","level":"N2","category":"Satzstrukturen","meaning":"in response to, in order to meet","explanation":"にこたえて expresses that you respond to an expectation, request or demand and meet it.","formation":"Noun + にこたえて / にこたえる + Noun","examples":[{"japanese":"お客様の声にこたえて、新商品を開発した。","cloze":{"start":5,"answer":"にこたえて","quiz":{"level":"N2","japanese":"お客様の声にこたえて、新商品を開発した。","german":"In response to our customers' feedback, we developed a new product.","start":5,"answer":"にこたえて","acceptedAnswers":["にこたえて","に応じて"],"distractors":[{"text":"をこたえて","reason":"The cause of the response needs に here."},{"text":"にこたえた","reason":"The attributive form does not link the following clause here."},{"text":"にこたえます","reason":"The finite form ends the sentence instead of attaching the cause."}]}},"romaji":"Okyakusama no koe ni kotaete, shin-shōhin wo kaihatsu shita.","german":"In response to our customers' feedback, we developed a new product."},{"japanese":"期待にこたえるよう、頑張ります。","romaji":"Kitai ni kotaeru yō, ganbarimasu.","german":"I'll do my best to live up to your expectations."}],"notes":"","related":["n3-ni-ojite"]},
{"id":"n2-ni-seyo","pattern":"～にせよ/にしろ","level":"N2","category":"Satzstrukturen","meaning":"even if, whether ... or","explanation":"にせよ/にしろ acknowledges different possibilities but says the outcome stays the same in any case.","formation":"Verb plain form / Noun + にせよ / にしろ / AにせよBにせよ","examples":[{"japanese":"賛成にせよ反対にせよ、意見を言ってください。","romaji":"Sansei ni seyo hantai ni seyo, iken wo itte kudasai.","german":"Whether you're for or against it, please give your opinion."},{"japanese":"理由が何にしろ、遅刻はよくない。","cloze":{"start":4,"answer":"にしろ","quiz":{"level":"N2","japanese":"理由が何にしろ、遅刻はよくない。","german":"Whatever the reason, being late is not good.","start":4,"answer":"にしろ","acceptedAnswers":["にしろ","にせよ","にしても"],"distractors":[{"text":"にするも","reason":"The concessive link needs にしろ or にしても here."},{"text":"をしろ","reason":"This makes 何 the object of a command instead of expressing \"whatever\"."},{"text":"にしります","reason":"The verb form is not built this way."}]}},"romaji":"Riyū ga nani ni shiro, chikoku wa yokunai.","german":"Whatever the reason, being late is not good."}],"notes":"にせよ is more formal, にしろ is more colloquial.","related":["n2-ni-shite-mo"]},
{"id":"n2-zu-niwa-irarenai","pattern":"～ずにはいられない","level":"N2","category":"Verben","meaning":"can't help but, can't help doing","explanation":"ずにはいられない expresses that you cannot suppress a feeling or impulse. You do it involuntarily.","formation":"Verb ない-stem + ずにはいられない (する → せずにはいられない)","examples":[{"japanese":"この映画を見ると、泣かずにはいられない。","cloze":{"start":11,"answer":"ずにはいられない","quiz":{"level":"N2","japanese":"この映画を見ると、泣かずにはいられない。","german":"Whenever I watch this movie, I can't help crying.","start":11,"answer":"ずにはいられない","acceptedAnswers":["ずにはいられない"],"distractors":[{"text":"ずにはいられる","reason":"This affirms that it is possible to hold back the tears."},{"text":"ずにはいられないます","reason":"ない does not take an attached ます."},{"text":"ずをはいられない","reason":"The set combination needs に."}]}},"romaji":"Kono eiga wo miru to, nakazuni wa irarenai.","german":"Whenever I watch this movie, I can't help crying."},{"japanese":"彼の冗談を聞くと、笑わずにはいられない。","cloze":{"start":11,"answer":"ずにはいられない"},"romaji":"Kare no jōdan wo kiku to, warawazuni wa irarenai.","german":"Whenever I hear his jokes, I can't help laughing."}],"notes":"More emotional than ざるを得ない. Refers to feelings/impulses.","related":["n3-zaruwoenai"]},
{"id":"n2-te-shou-ga-nai","pattern":"～てしょうがない","level":"N2","category":"Verben","meaning":"can't help it, extremely","explanation":"てしょうがない expresses that a feeling is so strong that you can't do anything about it. More colloquial than てならない.","formation":"Verb-て形 / い-Adj-くて + しょうがない / な-Adj + で + しょうがない","examples":[{"japanese":"お腹が空いてしょうがない。","cloze":{"start":5,"answer":"てしょうがない","quiz":{"level":"N2","japanese":"お腹が空いてしょうがない。","german":"I'm so hungry I can't stand it.","start":5,"answer":"てしょうがない","acceptedAnswers":["てしょうがない","て仕方がない","てたまらない"],"distractors":[{"text":"てしょうをない","reason":"ない needs が here instead of を."},{"text":"てしょうがないます","reason":"ない does not take an attached ます."},{"text":"たしょうがない","reason":"The connection after 空い needs the て-form."}]}},"romaji":"Onaka ga suite shō ga nai.","german":"I'm so hungry I can't stand it."},{"japanese":"気になってしょうがない。","cloze":{"start":4,"answer":"てしょうがない"},"romaji":"Ki ni natte shō ga nai.","german":"I can't stop thinking about it."}],"notes":"しかたがない is the more formal version. Colloquial: しょうがない.","related":["n3-te-tamaranai","n1-ttara-nai"]},
{"id":"n2-uru-enai","pattern":"～得る/～得ない","level":"N2","category":"Verben","meaning":"to be possible / to be impossible","explanation":"得る (うる/える) expresses that something is possible, 得ない (えない) that it is impossible. Formal.","formation":"Verb ます-stem + 得る(うる/える) / 得ない(えない)","examples":[{"japanese":"そんなことはあり得ない。","cloze":{"start":8,"answer":"得ない","quiz":{"level":"N2","japanese":"そんなことはあり得ない。","german":"That kind of thing is impossible.","start":8,"answer":"得ない","acceptedAnswers":["得ない","えない"],"distractors":[{"text":"得る","reason":"This asserts possibility instead of impossibility."},{"text":"得ないます","reason":"ない does not take an attached ます."},{"text":"得ませんない","reason":"This combines two incompatible negative endings."}]}},"romaji":"Sonna koto wa arienai.","german":"That kind of thing is impossible."},{"japanese":"十分に起こり得ることだ。","cloze":{"start":6,"answer":"得る"},"romaji":"Jūbun ni okoriuru koto da.","german":"It's something that could quite possibly happen."},{"japanese":"十分起こり得ることだ。","romaji":"Jūbun okoriuru koto da.","german":"It's entirely possible that this could happen."}],"notes":"得る can be read うる or える. 得ない is always read えない.","related":["n4-potential"],"legacyIds":["n3-uru-enai"]},
{"id":"n2-kiru","pattern":"～きる/きれる/きれない","level":"N3","category":"Verben","meaning":"to do completely / to manage to / to be unable to finish","explanation":"きる expresses that an action is carried out completely or all the way to the end. きれない means you cannot manage to do it completely.","formation":"Verb ます-stem + きる / きれる / きれない","examples":[{"japanese":"マラソンを走りきった。","romaji":"Marason wo hashirikitta.","german":"I ran the marathon all the way to the end."},{"japanese":"食べきれないほどの料理が出た。","cloze":{"start":2,"answer":"きれない","quiz":{"level":"N3","japanese":"食べきれないほどの料理が出た。","german":"So much food was served that we couldn't finish it.","start":2,"answer":"きれない","acceptedAnswers":["きれない"],"distractors":[{"text":"きれる","reason":"This affirms that you can eat everything."},{"text":"きれないます","reason":"ない does not take an attached ます."},{"text":"きりませんない","reason":"The negative polite form is not combined with ない again."}]}},"romaji":"Tabekirenai hodo no ryōri ga deta.","german":"So much food was served that we couldn't finish it."},{"japanese":"マラソンを走り切った。","romaji":"Marason o hashiri kitta.","german":"I ran the whole marathon."},{"japanese":"全部使い切ってしまった。","romaji":"Zenbu tsukai kitte shimatta.","german":"I've completely used it all up."}],"notes":"きる = completely; きれない = can't be done completely.","related":["n3-nuku","n4-owaru","te-shimau"],"legacyIds":["n4-kiru"]},
{"id":"n2-mai","pattern":"～まい","level":"N2","category":"Verben","meaning":"will not, probably not, won't","explanation":"まい expresses: 1) a strong intention not to do something (determination), 2) a guess that something will probably not happen.","formation":"Verb dictionary form + まい (group 1) / Verb ます-stem + まい (group 2) / するまい, 来まい","examples":[{"japanese":"二度とあんな失敗はするまい。","cloze":{"start":11,"answer":"まい","quiz":{"level":"N2","japanese":"二度とあんな失敗はするまい。","german":"I will never make a mistake like that again.","start":11,"answer":"まい","acceptedAnswers":["まい"],"distractors":[{"text":"ました","reason":"するました wrongly combines the dictionary form with a polite ending."},{"text":"ません","reason":"The polite negative is しません, not するません."},{"text":"ない","reason":"The negative is しない, not するない."}]}},"romaji":"Nido to anna shippai wa surumai.","german":"I will never make a mistake like that again."},{"japanese":"彼はもう来るまい。","cloze":{"start":6,"answer":"まい"},"romaji":"Kare wa mō kurumai.","german":"He probably won't come anymore."}],"notes":"Somewhat old-fashioned/literary. Everyday language: ～ないだろう.","related":[]},
{"id":"n2-te-wa-irarenai","pattern":"～てはいられない","level":"N2","category":"Verben","meaning":"can't keep on, can't afford to","explanation":"てはいられない expresses that you cannot continue a certain state because the situation does not allow it.","formation":"Verb-て形 + はいられない / てもいられない","examples":[{"japanese":"いつまでも待ってはいられない。","cloze":{"start":7,"answer":"てはいられない","quiz":{"level":"N2","japanese":"いつまでも待ってはいられない。","german":"I can't wait forever.","start":7,"answer":"てはいられない","acceptedAnswers":["てはいられない"],"distractors":[{"text":"てはいられる","reason":"This affirms that it is possible to keep waiting."},{"text":"てはいられないます","reason":"ない does not take an attached ます."},{"text":"たはいられない","reason":"After 待っ, this connection needs the て-form."}]}},"romaji":"Itsu made mo matte wa irarenai.","german":"I can't wait forever."},{"japanese":"のんびりしてはいられない、締め切りが近い。","cloze":{"start":5,"answer":"てはいられない"},"romaji":"Nonbiri shite wa irarenai, shimekiri ga chikai.","german":"I can't afford to take it easy; the deadline is close."}],"notes":"","related":["n2-te-bakari-wa-irarenai"]},
{"id":"n2-you-to-shinai","pattern":"～ようとしない","level":"N2","category":"Verben","meaning":"won't (even try to), refuses to","explanation":"ようとしない expresses that someone does not even make an attempt to do something. Critical undertone.","formation":"Verb-よう形 + としない","examples":[{"japanese":"子供が野菜を食べようとしない。","cloze":{"start":8,"answer":"ようとしない","quiz":{"level":"N2","japanese":"子供が野菜を食べようとしない。","german":"The child won't eat vegetables (won't even try).","start":8,"answer":"ようとしない","acceptedAnswers":["ようとしない"],"distractors":[{"text":"ようをしない","reason":"The attempted action is linked with と."},{"text":"ようとしますない","reason":"The negative is not formed with ますない."},{"text":"ようとする","reason":"This asserts an attempt instead of its absence."}]}},"romaji":"Kodomo ga yasai wo tabeyō to shinai.","german":"The child won't eat vegetables (won't even try)."},{"japanese":"彼は自分の間違いを認めようとしない。","cloze":{"start":11,"answer":"ようとしない"},"romaji":"Kare wa jibun no machigai wo mitomeyō to shinai.","german":"He won't even admit his mistake."}],"notes":"Implies criticism of the lack of will.","related":["n4-you-to-suru","n2-mo-shinai"]},
{"id":"n2-ni-kakawaru","pattern":"～にかかわる","level":"N2","category":"Verben","meaning":"to concern, to be related to, to be at stake","explanation":"にかかわる expresses that something is closely connected with an important matter or affects it.","formation":"Noun + にかかわる","examples":[{"japanese":"命にかかわる問題だ。","cloze":{"start":1,"answer":"にかかわる","quiz":{"level":"N2","japanese":"命にかかわる問題だ。","german":"It's a matter of life and death.","start":1,"answer":"にかかわる","acceptedAnswers":["にかかわる"],"distractors":[{"text":"をかかわる","reason":"The affected area needs に."},{"text":"にかかわり","reason":"The stem form cannot modify 問題 attributively here."},{"text":"にかかわりまする","reason":"る cannot be attached to ます."}]}},"romaji":"Inochi ni kakawaru mondai da.","german":"It's a matter of life and death."},{"japanese":"会社の信用にかかわる事態だ。","cloze":{"start":5,"answer":"にかかわる"},"romaji":"Kaisha no shin'yō ni kakawaru jitai da.","german":"It's a situation that affects the company's reputation."}],"notes":"Often used with serious, important topics.","related":["n2-ni-kakatte-iru"]},
{"id":"n2-mamire","pattern":"～まみれ","level":"N1","category":"Adjektive","meaning":"covered with, full of (negative)","explanation":"まみれ is attached to nouns and forms a な-adjective describing something covered or soiled with an unpleasant substance. Almost always has a negative connotation; for positive meanings, ～だらけ (more neutral) or ～いっぱい is used.","formation":"Noun + まみれ (+ の/だ/な)","examples":[{"japanese":"子供たちが泥まみれになって遊んでいた。","cloze":{"start":6,"answer":"まみれ","quiz":{"level":"N1","japanese":"子供たちが泥まみれになって遊んでいた。","german":"The children were playing, covered in mud.","start":6,"answer":"まみれ","acceptedAnswers":["まみれ","だらけ"],"distractors":[{"text":"まみれを","reason":"An object particle cannot come before になって here."},{"text":"まみれな","reason":"まみれなになって combines the forms incorrectly."},{"text":"まみれます","reason":"ます cannot be attached directly to まみれ."}]}},"romaji":"Kodomotachi ga doro-mamire ni natte asonde ita.","german":"The children were playing, covered in mud."},{"japanese":"汗まみれのシャツを洗濯した。","cloze":{"start":1,"answer":"まみれ"},"romaji":"Ase-mamire no shatsu o sentaku shita.","german":"I washed the sweat-soaked shirt."},{"japanese":"泥まみれになって遊んだ。","romaji":"Doro mamire ni natte asonda.","german":"We played until we were covered in mud."},{"japanese":"血まみれで倒れていた。","romaji":"Chi mamire de taorete ita.","german":"He was lying collapsed, covered in blood."}],"notes":"Typical combinations: 泥まみれ (covered in mud), 汗まみれ (covered in sweat), 血まみれ (covered in blood), 借金まみれ (deep in debt). Don't confuse with ～だらけ, which can also be used for countable things.","related":["n3-darake","n2-zukume"],"legacyIds":["n1-mamire"]},
{"id":"n2-zukume","pattern":"～ずくめ","level":"N1","category":"Adjektive","meaning":"nothing but, all, only","explanation":"ずくめ is attached to nouns and forms a な-adjective expressing that something consists exclusively or entirely of a particular thing. Unlike ～だらけ (chaotic/negative), ずくめ can be either positive or neutral.","formation":"Noun + ずくめ (+ の/だ)","examples":[{"japanese":"今日はいいことずくめの一日だった。","cloze":{"start":7,"answer":"ずくめ","quiz":{"level":"N1","japanese":"今日はいいことずくめの一日だった。","german":"Today was a day full of nothing but good things.","start":7,"answer":"ずくめ","acceptedAnswers":["ずくめ","ばかり"],"distractors":[{"text":"ずくめを","reason":"を does not fit before the following modifier の一日."},{"text":"ずくめな","reason":"な and の cannot attach together here."},{"text":"ずくめます","reason":"ます cannot be attached directly to ずくめ."}]}},"romaji":"Kyō wa ii koto zukume no ichinichi datta.","german":"Today was a day full of nothing but good things."},{"japanese":"黒ずくめの男が立っていた。","cloze":{"start":1,"answer":"ずくめ"},"romaji":"Kuro-zukume no otoko ga tatte ita.","german":"A man dressed all in black was standing there."},{"japanese":"今日は良いことずくめだった。","romaji":"Kyō wa yoi koto zukume datta.","german":"Nothing but good things happened today."},{"japanese":"黒ずくめの服を着ている。","romaji":"Kuro zukume no fuku wo kite iru.","german":"He's dressed entirely in black."}],"notes":"Common combinations: 黒ずくめ (all in black), いいことずくめ (nothing but good things), ルールずくめ (full of rules), 異例ずくめ (one exception after another).","related":["n3-darake","n2-mamire"],"legacyIds":["n1-zukume"]},
{"id":"n2-meku","pattern":"～めく","level":"N1","category":"Adjektive","meaning":"to become ~-like, to look/sound like ~","explanation":"めく is a suffix that is attached to certain nouns and forms a godan verb (めく → めいた → めいて). It expresses that something takes on the character or atmosphere of the noun. The number of combinations is limited: you cannot freely attach it to just any noun.","formation":"Noun + めく (→ めいた + Noun / めいて)","examples":[{"japanese":"風が暖かくなり、春めいてきた。","romaji":"Kaze ga atatakaku nari, haru-meite kita.","german":"The wind grew warmer, and spring was in the air.","cloze":{"start":9,"answer":"めいてきた","quiz":{"level":"N1","japanese":"風が暖かくなり、春めいてきた。","german":"The wind grew warmer, and spring was in the air.","start":9,"answer":"めいてきた","acceptedAnswers":["めいてきた"],"distractors":[{"text":"めいてこなかった","reason":"This negates the spring-like change that has taken place."},{"text":"めくました","reason":"ます is not attached to the dictionary form."},{"text":"めいてきたます","reason":"ます is not attached to the completed past form."}]}}},{"japanese":"彼の皮肉めいた言い方が気になった。","romaji":"Kare no hiniku-meita iikata ga ki ni natta.","german":"His ironic-sounding way of putting things bothered me."},{"japanese":"春めいた陽気になってきた。","romaji":"Harumei ta yōki ni natte kita.","german":"The weather has started to feel like spring."},{"japanese":"彼の話は謎めいている。","romaji":"Kare no hanashi wa nazomeite iru.","german":"His story seems mysterious."}],"notes":"Common combinations: 春めく (to become spring-like), 皮肉めく (to sound ironic), 謎めく (to seem mysterious), 冗談めく (to sound like a joke). Careful: it cannot be combined freely!","related":["n4-rashii","n4-ppoi"],"legacyIds":["n1-meku"]},
{"id":"n2-kaneru","pattern":"～かねる / ～かねない","level":"N2","category":"Adjektive","meaning":"cannot / could well happen","explanation":"かねる has two forms with opposite meanings: ～かねる means \"cannot, is unable to\" (a polite way of declining). ～かねない means \"it cannot be ruled out that\" (a warning of a negative outcome). Both are attached to the verb stem (ます-stem).","formation":"Verb ます-stem + かねる / かねない","examples":[{"japanese":"その要求にはお応えしかねます。","romaji":"Sono yōkyū ni wa okotae shikanemasu.","german":"I'm afraid we are unable to meet that demand."},{"japanese":"このまま放置すれば事故を起こしかねない。","cloze":{"start":15,"answer":"かねない","quiz":{"level":"N2","japanese":"このまま放置すれば事故を起こしかねない。","german":"If this is left as it is, it could well cause an accident.","start":15,"answer":"かねない","acceptedAnswers":["かねない"],"distractors":[{"text":"かねないます","reason":"ない does not take an attached ます."},{"text":"かねないました","reason":"The past form is not built with ないました."},{"text":"かねまする","reason":"る cannot be attached to ます."}]}},"romaji":"Kono mama hōchi sureba jiko o okoshi kanenai.","german":"If this is left as it is, it could well cause an accident."},{"japanese":"その要望にはお応えしかねます。","romaji":"Sono yōbō ni wa okotae shikanemasu.","german":"I'm afraid we are unable to accommodate that request."},{"japanese":"賛成しかねる意見だ。","romaji":"Sansei shikaneru iken da.","german":"It's an opinion I can't agree with."},{"japanese":"このままでは事故になりかねない。","romaji":"Kono mama de wa jiko ni narikanenai.","german":"At this rate, it could lead to an accident."},{"japanese":"誤解を招きかねない発言だ。","romaji":"Gokai o manekikanenai hatsugen da.","german":"It's a remark that could cause misunderstandings."}],"notes":"かねる → polite refusal (ビジネス). かねない → warning about a negative possibility. With かねない, only for negative/undesirable outcomes.","related":["n2-uru-enai","n3-osore-ga-aru"],"legacyIds":["n3-kaneru","n3-kanenai"]},
{"id":"n2-ageku","pattern":"～あげく","level":"N2","category":"Satzstrukturen","meaning":"after a long ..., in the end (with a bad outcome)","explanation":"あげく describes how a long, often laborious or nerve-racking process ends in a usually negative or unwanted result. Common in storytelling and complaints; intensified as あげくの果てに (\"to top it all off\").","formation":"Verb (た-form) + あげく(に) / Noun + の + あげく(に)","examples":[{"japanese":"散々迷ったあげく、結局何も買わなかった。","romaji":"Sanzan mayotta ageku, kekkyoku nani mo kawanakatta.","german":"After going back and forth for ages, I ended up not buying anything.","cloze":{"start":5,"answer":"あげく","quiz":{"level":"N2","japanese":"散々迷ったあげく、結局何も買わなかった。","german":"After going back and forth for ages, I ended up not buying anything.","start":5,"answer":"あげく","acceptedAnswers":["あげく","あげくに","末","末に"],"distractors":[{"text":"うちに","reason":"うちに does not follow the た-form and does not mark an end point after long hesitation."},{"text":"とたん","reason":"とたん describes a sudden event immediately afterward and does not fit with 散々 and 結局."},{"text":"ついでに","reason":"ついでに means \"while you're at it\" and makes no sense with the disappointing result."}]}}},{"japanese":"彼は上司と口論したあげく、会社を辞めてしまった。","romaji":"Kare wa jōshi to kōron shita ageku, kaisha o yamete shimatta.","german":"After arguing with his boss, he ended up quitting the company."},{"japanese":"長時間の議論のあげく、計画は白紙に戻された。","romaji":"Chōjikan no giron no ageku, keikaku wa hakushi ni modosareta.","german":"After a long discussion, the plan was eventually scrapped."}],"notes":"Unlike ～末に, which can be neutral or even positive (悩んだ末に決めた), あげく is almost always negatively colored and sounds disappointed or annoyed. The main clause describes a result that has already happened; あげく is not suitable for intentions or requests.","related":["n2-sue-ni"]},
{"id":"n2-ni-saishite","pattern":"～に際して","level":"N2","category":"Partikel","meaning":"on the occasion of, at the time of (a special occasion)","explanation":"に際して marks a special, usually one-time occasion at or before which something is done: an opening, signing a contract, a departure. Very formal; typical of speeches, instructions and announcements. に際し is even more written-style.","formation":"Noun + に際して / に際し / に際しての + Noun; Verb (dictionary form) + に際して","examples":[{"japanese":"ご利用に際して、以下の注意事項をお読みください。","romaji":"Goriyō ni saishite, ika no chūi jikō o oyomi kudasai.","german":"Before using this, please read the following precautions.","cloze":{"start":3,"answer":"に際して","quiz":{"level":"N2","japanese":"ご利用に際して、以下の注意事項をお読みください。","german":"Before using this, please read the following precautions.","start":3,"answer":"に際して","acceptedAnswers":["に際して","に際し","にあたって","にあたり","の際は","の際には"],"distractors":[{"text":"に対して","reason":"に対して marks a counterpart or a contrast, not an occasion."},{"text":"にわたって","reason":"にわたって requires a span of time or space; ご利用 is not a span."},{"text":"に応じて","reason":"に応じて means \"in accordance with\"; the precautions do not depend on the extent of use."}]}}},{"japanese":"留学するに際して、両親とよく話し合った。","romaji":"Ryūgaku suru ni saishite, ryōshin to yoku hanashiatta.","german":"Before going to study abroad, I had a long talk with my parents."},{"japanese":"新工場の開設に際し、市長が挨拶を述べた。","romaji":"Shin-kōjō no kaisetsu ni saishi, shichō ga aisatsu o nobeta.","german":"At the opening of the new factory, the mayor gave a speech."}],"notes":"Similar to ～にあたって, but even more formal and more strongly tied to the moment of the occasion; にあたって tends to emphasize preparing for a task. ～際に is more neutral and can also be used for everyday things (お降りの際に). For routine actions like 食事に際して, に際して sounds exaggerated.","related":["n3-sai-ni","n2-ni-atatte"]},
{"id":"n2-ni-tsuke","pattern":"～につけ / ～につけて","level":"N2","category":"Satzstrukturen","meaning":"every time; whether ... or ...","explanation":"につけ expresses that a certain trigger repeatedly brings up the same feeling or thought, especially with 見る・聞く・思う. Set phrase: 何かにつけて (\"at every opportunity\"). As AにつけBにつけ, it means \"whether A or B, in either case\".","formation":"Verb (dictionary form) + につけ(て) / Noun + につけ(て); Aにつけ Bにつけ (pairs of opposites)","examples":[{"japanese":"この写真を見るにつけ、故郷のことが思い出される。","romaji":"Kono shashin o miru ni tsuke, kokyō no koto ga omoidasareru.","german":"Whenever I look at this photo, I'm reminded of my hometown.","cloze":{"start":7,"answer":"につけ","quiz":{"level":"N2","japanese":"この写真を見るにつけ、故郷のことが思い出される。","german":"Whenever I look at this photo, I'm reminded of my hometown.","start":7,"answer":"につけ","acceptedAnswers":["につけ","につけて","たびに","たび"],"distractors":[{"text":"とたん","reason":"とたん requires the た-form (見たとたん) and describes a single moment, not a repetition."},{"text":"あげく","reason":"あげく follows the た-form and marks a bad end result, not a recurring memory."},{"text":"ものの","reason":"ものの is concessive (\"although ..., still\"); there is no contrast between the photo and the memory."}]}}},{"japanese":"彼は何かにつけて文句を言う。","romaji":"Kare wa nani ka ni tsukete monku o iu.","german":"He complains at every opportunity."},{"japanese":"雨につけ風につけ、母は畑の心配をしている。","romaji":"Ame ni tsuke kaze ni tsuke, haha wa hatake no shinpai o shite iru.","german":"Rain or wind, my mother is always worrying about the field."}],"notes":"Unlike ～たびに, which neutrally counts each repetition, につけ almost always links the trigger with an inner reaction (思い出す, 感じる, 心配になる); with pure actions like 行くにつけ it sounds unnatural. Don't confuse it with ～につれて (proportional change: 年をとるにつれて).","related":["n3-tabi-ni","n3-ni-tsurete"]},
{"id":"n2-wa-tomokaku","pattern":"～はともかく","level":"N2","category":"Partikel","meaning":"leaving aside, ... aside","explanation":"はともかく deliberately sets one point aside in order to highlight the more important one: \"X may be as it may; what matters is Y.\" Often used in evaluations (見た目はともかく味はいい). Neutral to slightly colloquial; はともかくとして is somewhat more formal.","formation":"Noun + はともかく(として); question clause + か(どうか) + はともかく","examples":[{"japanese":"見た目はともかく、味はとてもいい。","romaji":"Mitame wa tomokaku, aji wa totemo ii.","german":"Looks aside, it tastes really good.","cloze":{"start":3,"answer":"はともかく","quiz":{"level":"N2","japanese":"見た目はともかく、味はとてもいい。","german":"Looks aside, it tastes really good.","start":3,"answer":"はともかく","acceptedAnswers":["はともかく","はともかくとして","はさておき"],"distractors":[{"text":"はおろか","reason":"はおろか escalates to an extreme and requires も/さえ, usually with a negative; that does not fit 味はとてもいい."},{"text":"につき","reason":"につき gives a formal reason (\"due to\"); the looks are not the reason for the taste."},{"text":"をめぐって","reason":"をめぐって requires a dispute or discussion in the main clause."}]}}},{"japanese":"結果はともかく、最後まで頑張ったことが大切だ。","romaji":"Kekka wa tomokaku, saigo made ganbatta koto ga taisetsu da.","german":"Regardless of the result, what matters is that you kept going until the end."},{"japanese":"実現できるかどうかはともかく、アイデアとしては面白い。","romaji":"Jitsugen dekiru ka dō ka wa tomokaku, aidea to shite wa omoshiroi.","german":"Whether or not it can actually be done, it's an interesting idea."}],"notes":"～はさておき (N1) is very similar but is used more often to change the subject (それはさておき). ～はもちろん, by contrast, means \"not only X but also Y\" and includes X, whereas はともかく sets X aside. ～ならともかく means \"if it were X, that would be one thing\".","related":["n1-wasateoite","n2-wa-mochiron","n2-wa-betsu-to-shite"]},
{"id":"n2-mo-kamawazu","pattern":"～もかまわず","level":"N2","category":"Satzstrukturen","meaning":"without caring about ..., regardless of","explanation":"もかまわず describes someone doing something without regard for something one would normally pay attention to: other people's eyes, costs, rain. Usually critical, from the speaker's point of view about third parties. It follows nouns or clauses nominalized with の.","formation":"Noun + もかまわず / Verb (plain form) + の + もかまわず","examples":[{"japanese":"彼女は人目もかまわず、大声で泣き出した。","romaji":"Kanojo wa hitome mo kamawazu, ōgoe de nakidashita.","german":"Without caring who was watching, she burst out crying loudly.","cloze":{"start":5,"answer":"もかまわず","quiz":{"level":"N2","japanese":"彼女は人目もかまわず、大声で泣き出した。","german":"Without caring who was watching, she burst out crying loudly.","start":5,"answer":"もかまわず","acceptedAnswers":["もかまわず","も気にせず","を気にせず"],"distractors":[{"text":"を問わず","reason":"を問わず is used with categories such as age or gender, not with something you should be considerate of."},{"text":"に沿って","reason":"に沿って means \"along, in line with\"; you don't cry in line with other people's looks."},{"text":"に応じて","reason":"に応じて means \"in accordance with\" and contradicts the inconsiderate behavior."}]}}},{"japanese":"雨に濡れるのもかまわず、子どもたちは外で遊び続けた。","romaji":"Ame ni nureru no mo kamawazu, kodomotachi wa soto de asobitsuzuketa.","german":"Not caring that they were getting wet in the rain, the children kept playing outside."},{"japanese":"周りの迷惑もかまわず、電車の中で大声で電話する人がいる。","romaji":"Mawari no meiwaku mo kamawazu, densha no naka de ōgoe de denwa suru hito ga iru.","german":"There are people who talk loudly on the phone on the train with no regard for how they bother others."}],"notes":"Unlike ～にもかかわらず (\"although, despite\"), which neutrally states a contrast, もかまわず emphasizes a person's lack of consideration. ～を問わず (\"regardless of categories such as age\") contains no judgment. ～をよそに (N1) is similar but more written-style.","related":["n3-ni-mo-kakawarazu","n1-wo-yoso-ni"]},
{"id":"n2-yara-yara","pattern":"～やら～やら","level":"N2","category":"Partikel","meaning":"among other things ... and ...; partly ..., partly ...","explanation":"やら～やら lists examples from a jumbled set and suggests there was more besides, often with a sense of chaos, stress or mixed emotions (嬉しいやら恥ずかしいやら). Used in speech and writing; more emotional than ～とか～とか.","formation":"Noun / Verb (dictionary form) / い-adjective + やら, Noun / Verb / い-adjective + やら","examples":[{"japanese":"引っ越しの準備やら仕事やらで、毎日忙しい。","romaji":"Hikkoshi no junbi yara shigoto yara de, mainichi isogashii.","german":"What with getting ready for the move, work and so on, I'm busy every day.","cloze":{"start":7,"answer":"やら","quiz":{"level":"N2","japanese":"引っ越しの準備やら仕事やらで、毎日忙しい。","german":"What with getting ready for the move, work and so on, I'm busy every day.","start":7,"answer":"やら","acceptedAnswers":["やら","や"],"distractors":[{"text":"ばかりか","reason":"ばかりか requires も or まで in the second part, not a parallel やら."},{"text":"どころか","reason":"どころか turns an expectation into its opposite; here, burdens are simply being listed."},{"text":"につき","reason":"につき is a formal reason and cannot be part of a list."}]}}},{"japanese":"嬉しいやら恥ずかしいやら、複雑な気持ちだった。","romaji":"Ureshii yara hazukashii yara, fukuzatsu na kimochi datta.","german":"I was partly happy and partly embarrassed: a mixed feeling."},{"japanese":"泣くやら叫ぶやら、会場は大騒ぎになった。","romaji":"Naku yara sakebu yara, kaijō wa ōsawagi ni natta.","german":"People were crying and shouting; the hall was in an uproar."}],"notes":"～とか～とか is more neutral and more colloquial; ～たり～たり lists actions without an emotional undertone. With やら～やら, by contrast, there is almost always a sense of \"it was all too much / all over the place\". A single やら after question words (何やら, どこへやら), on the other hand, means \"somehow, somewhere\".","related":["n4-toka","tari-tari","n2-to-iu-ka-to-iu-ka"]},
{"id":"n2-kurai-nara","pattern":"～くらいなら / ～ぐらいなら","level":"N2","category":"Satzstrukturen","meaning":"rather than ..., I'd sooner ...","explanation":"くらいなら contrasts a highly undesirable option with another that the speaker prefers: \"Rather than do X, I'd sooner do Y.\" The main clause usually contains ほうがいい, ～たい or ましだ. Expresses a strong personal aversion; used in speech and writing.","formation":"Verb (dictionary form) + くらいなら / ぐらいなら + ～ほうがいい・ましだ・～たい","examples":[{"japanese":"あんな会社に戻るくらいなら、転職したほうがましだ。","romaji":"Anna kaisha ni modoru kurai nara, tenshoku shita hō ga mashi da.","german":"Rather than go back to a company like that, I'd be better off changing jobs.","cloze":{"start":8,"answer":"くらいなら","quiz":{"level":"N2","japanese":"あんな会社に戻るくらいなら、転職したほうがましだ。","german":"Rather than go back to a company like that, I'd be better off changing jobs.","start":8,"answer":"くらいなら","acceptedAnswers":["くらいなら","ぐらいなら","よりは","より"],"distractors":[{"text":"ものなら","reason":"ものなら expresses a wish that can hardly be fulfilled (\"if only I could\") and does not fit ましだ."},{"text":"からには","reason":"からには means \"now that ..., (I must) see it through\" and contradicts the wish not to go back."},{"text":"ばかりに","reason":"ばかりに names the cause of a regrettable result, not a comparison of two options."}]}}},{"japanese":"途中でやめるくらいなら、最初からやらないほうがいい。","romaji":"Tochū de yameru kurai nara, saisho kara yaranai hō ga ii.","german":"If you're going to quit halfway, you're better off not starting at all."},{"japanese":"人に頼むぐらいなら、自分でやりたい。","romaji":"Hito ni tanomu gurai nara, jibun de yaritai.","german":"Rather than ask someone else, I'd prefer to do it myself."}],"notes":"Unlike the neutral ～より(は)～ほうがいい, くらいなら expresses strong rejection of the first option (\"that would be the very last thing\"). Don't confuse it with ～ものなら (unrealistic condition: 戻れるものなら戻りたい) or with plain くらい (\"about, to such an extent\").","related":["n3-kurai-gurai","n1-mononara"]},
{"id":"n2-koto-dashi","pattern":"～ことだし","level":"N2","category":"Satzstrukturen","meaning":"since (after all) ..., so","explanation":"ことだし names one of several possible reasons that justifies the following decision, request or suggestion: \"Since ..., let's ...\". Friendly and colloquial; the main clause often contains ～(よ)う, ～ましょう, ～ませんか or ～ことにする.","formation":"Verb / い-adjective (plain form) + ことだし / な-adjective + な + ことだし / Noun + である + ことだし","examples":[{"japanese":"雨も止んだことだし、そろそろ出かけようか。","romaji":"Ame mo yanda koto da shi, sorosoro dekakeyō ka.","german":"Now that the rain has stopped, shall we get going?","cloze":{"start":5,"answer":"ことだし","quiz":{"level":"N2","japanese":"雨も止んだことだし、そろそろ出かけようか。","german":"Now that the rain has stopped, shall we get going?","start":5,"answer":"ことだし","acceptedAnswers":["ことだし","し","から","ので"],"distractors":[{"text":"ことに","reason":"ことに only follows emotion words (驚いたことに) and does not give a reason for a suggestion."},{"text":"ことなく","reason":"ことなく requires the dictionary form and means \"without ...ing\"."},{"text":"ものの","reason":"ものの is concessive and cannot be followed by a suggestion like 出かけようか."}]}}},{"japanese":"皆そろったことだし、会議を始めましょう。","romaji":"Mina sorotta koto da shi, kaigi o hajimemashō.","german":"Since everyone is here, let's start the meeting."},{"japanese":"天気もいいことだし、散歩にでも行きませんか。","romaji":"Tenki mo ii koto da shi, sanpo ni demo ikimasen ka.","german":"The weather is nice, so why don't we go for a walk or something?"}],"notes":"Compared with plain ～し, ことだし sounds softer and more considered. ～ことだから (彼のことだから), by contrast, bases a guess on a person's character. The main clause of a ことだし construction is almost never a plain statement of fact, but a decision, suggestion or request.","related":["n4-shi","n2-koto-dakara"]},
{"id":"n2-ta-mono-dewa-nai","pattern":"～たものではない","level":"N2","category":"Verben","meaning":"one can't possibly ...; is unbearable","explanation":"たものではない (colloquially たもんじゃない) is a strongly negative judgment: something is so bad that you can't even bring yourself to do it, e.g. eat it or look at it. Usually used with the potential form (食べられた, 見られた). Emotional, mostly spoken language.","formation":"Verb (potential form, た-form) + ものではない / もんじゃない","examples":[{"japanese":"この料理は辛すぎて、とても食べられたものではない。","romaji":"Kono ryōri wa karasugite, totemo taberareta mono de wa nai.","german":"This dish is so spicy that it's impossible to eat.","cloze":{"start":17,"answer":"たものではない","quiz":{"level":"N2","japanese":"この料理は辛すぎて、とても食べられたものではない。","german":"This dish is so spicy that it's impossible to eat.","start":17,"answer":"たものではない","acceptedAnswers":["たものではない","たもんじゃない","たものじゃない"],"distractors":[{"text":"たものだ","reason":"たものだ recalls the past (\"I often used to ...\") and contradicts 辛すぎて."},{"text":"たばかりだ","reason":"たばかりだ means \"just did\" and does not fit とても and the judgment about the spiciness."},{"text":"たどころではない","reason":"どころではない follows the dictionary form or a noun, not the た-form."}]}}},{"japanese":"彼の字は汚くて、読めたものではない。","romaji":"Kare no ji wa kitanakute, yometa mono de wa nai.","german":"His handwriting is so messy that it's impossible to read."},{"japanese":"こんな下手な歌、人に聞かせられたもんじゃない。","romaji":"Konna heta na uta, hito ni kikaserareta mon ja nai.","german":"I can't possibly let anyone hear a song sung this badly."}],"notes":"Don't confuse it with ～ものではない without た (dictionary form), which expresses a norm (\"one shouldn't do that\": 人の悪口を言うものではない). たものではない is a subjective judgment about poor quality. Stronger and more emotional than ～わけがない or ～っこない.","related":["n2-mono-dewa-nai","n3-kkonai"]},
{"id":"n2-ka-nai-ka-no-uchi-ni","pattern":"～か～ないかのうちに","level":"N2","category":"Satzstrukturen","meaning":"no sooner ... than, (almost) at the same moment","explanation":"か～ないかのうちに describes the second action starting when the first has only just been completed (or not quite yet): \"No sooner had ... than ...\". The same verb appears twice. Written and narrative style; the main clause is usually in the past.","formation":"Verb (dictionary form/た-form) + か + the same verb (ない-form) + かのうちに","examples":[{"japanese":"ベルが鳴るか鳴らないかのうちに、生徒たちは教室を飛び出した。","romaji":"Beru ga naru ka naranai ka no uchi ni, seitotachi wa kyōshitsu o tobidashita.","german":"The bell had barely started ringing when the students rushed out of the classroom.","cloze":{"start":5,"answer":"か鳴らないかのうちに","quiz":{"level":"N2","japanese":"ベルが鳴るか鳴らないかのうちに、生徒たちは教室を飛び出した。","german":"The bell had barely started ringing when the students rushed out of the classroom.","start":5,"answer":"か鳴らないかのうちに","acceptedAnswers":["か鳴らないかのうちに"],"distractors":[{"text":"か鳴らないうちに","reason":"The construction needs the second か before のうちに."},{"text":"か鳴らないかのあまり","reason":"あまり expresses an excess (\"out of sheer ...\"), not closeness in time."},{"text":"か鳴らないかのたびに","reason":"たびに marks repetition (\"every time\"), not a single moment."}]}}},{"japanese":"彼は横になるかならないかのうちに眠ってしまった。","romaji":"Kare wa yoko ni naru ka naranai ka no uchi ni nemutte shimatta.","german":"He had barely lain down before he fell asleep."},{"japanese":"電車が止まったか止まらないかのうちに、乗客がドアに押し寄せた。","romaji":"Densha ga tomatta ka tomaranai ka no uchi ni, jōkyaku ga doa ni oshiyoseta.","german":"The train had barely come to a stop when the passengers surged toward the doors."}],"notes":"Compared with ～たとたん (something surprising happens immediately afterward), か～ないかのうちに emphasizes that the first action has not even been fully completed. ～や否や (N1) is even more written-style. The main clause contains neither an intention nor a request.","related":["n3-totan","n1-ya-inaya"]},
{"id":"n2-ni-soui-nai","pattern":"～に相違ない","level":"N2","category":"Satzstrukturen","meaning":"without a doubt, certainly","explanation":"に相違ない expresses a firm conviction based on evidence: \"It cannot be otherwise.\" Same meaning as ～に違いない, but clearly more written-style and stiffer; typical of reports, crime novels, news and formal letters.","formation":"Verb / い-adjective (plain form) + に相違ない / な-adjective・Noun + (である) + に相違ない","examples":[{"japanese":"現場に残された指紋から見て、犯人は彼に相違ない。","romaji":"Genba ni nokosareta shimon kara mite, hannin wa kare ni sōi nai.","german":"Judging from the fingerprints left at the scene, he is without a doubt the culprit.","cloze":{"start":18,"answer":"に相違ない","quiz":{"level":"N2","japanese":"現場に残された指紋から見て、犯人は彼に相違ない。","german":"Judging from the fingerprints left at the scene, he is without a doubt the culprit.","start":18,"answer":"に相違ない","acceptedAnswers":["に相違ない","に違いない","に決まっている"],"distractors":[{"text":"に過ぎない","reason":"に過ぎない plays something down (\"merely\") and does not express certainty."},{"text":"にかかわらず","reason":"にかかわらず means \"regardless of\" and cannot end a sentence."},{"text":"に越したことはない","reason":"に越したことはない means \"it would be best to\" and does not fit a conclusion drawn from evidence."}]}}},{"japanese":"彼の実力なら、合格するに相違ない。","romaji":"Kare no jitsuryoku nara, gōkaku suru ni sōi nai.","german":"With his ability, he is certain to pass."},{"japanese":"両者の間には何らかの取引があったに相違ない。","romaji":"Ryōsha no aida ni wa nanraka no torihiki ga atta ni sōi nai.","german":"There must without a doubt have been some kind of deal between the two parties."}],"notes":"In content it is like ～に違いない (N3), but in everyday conversation に相違ない sounds stilted. ～に決まっている, by contrast, is colloquial and more subjective. On official forms you come across the related formula 上記の通り相違ありません (\"The above information is correct\").","related":["n3-ni-chigainai","n3-ni-kimatte-iru"]},
{"id":"n2-ni-mukete","pattern":"～に向けて","level":"N2","category":"Partikel","meaning":"toward, in preparation for; aimed at","explanation":"に向けて names a goal that an action is directed toward: in time (the Olympics, an exam), in content (a solution, reconstruction) or as an addressee (若者に向けて発信する). Common in the news, speeches and corporate language; attributively as に向けた + Noun.","formation":"Noun + に向けて / に向け / に向けた + Noun","examples":[{"japanese":"来月の試合に向けて、毎日練習している。","romaji":"Raigetsu no shiai ni mukete, mainichi renshū shite iru.","german":"I'm practicing every day for next month's match.","cloze":{"start":5,"answer":"に向けて","quiz":{"level":"N2","japanese":"来月の試合に向けて、毎日練習している。","german":"I'm practicing every day for next month's match.","start":5,"answer":"に向けて","acceptedAnswers":["に向けて","に向け","に備えて"],"distractors":[{"text":"にわたって","reason":"にわたって requires a span of time or space; a single match is not a span."},{"text":"に沿って","reason":"に沿って means \"along, in line with\" (a plan, a guideline), not \"in preparation for an event\"."},{"text":"に反して","reason":"に反して means \"contrary to\" and makes no sense with the training."}]}}},{"japanese":"政府は問題の解決に向けて、新たな対策を発表した。","romaji":"Seifu wa mondai no kaiketsu ni mukete, arata na taisaku o happyō shita.","german":"The government announced new measures toward solving the problem."},{"japanese":"社長は社員に向けてメッセージを送った。","romaji":"Shachō wa shain ni mukete messēji o okutta.","german":"The company president sent a message to the employees."}],"notes":"～に向かって tends to describe a physical direction or stance (海に向かって叫ぶ), whereas に向けて describes a goal being pursued or a target group. ～向け (N3) is a suffix for target groups (子供向けの本) and attaches directly to the noun without に.","related":["n3-muke","n2-ni-atatte"]},
{"id":"n2-wo-nozoite","pattern":"～を除いて","level":"N2","category":"Partikel","meaning":"except, with the exception of","explanation":"を除いて explicitly excludes one case: \"all/always, just not X\". More formal than ～以外(は) and common in rules, announcements, weather reports and statistics. Often used with all-inclusive statements such as 全員, 毎日 or with a negative. Attributively: を除く + Noun.","formation":"Noun + を除いて / を除き / を除く + Noun / を除けば","examples":[{"japanese":"日曜日を除いて、毎日営業しています。","romaji":"Nichiyōbi o nozoite, mainichi eigyō shite imasu.","german":"We're open every day except Sunday.","cloze":{"start":3,"answer":"を除いて","quiz":{"level":"N2","japanese":"日曜日を除いて、毎日営業しています。","german":"We're open every day except Sunday.","start":3,"answer":"を除いて","acceptedAnswers":["を除いて","を除き","以外","以外は"],"distractors":[{"text":"を問わず","reason":"を問わず is used with a category (曜日を問わず), not with a single day."},{"text":"に限って","reason":"に限って singles out one case as \"of all times / only\" and contradicts 毎日."},{"text":"をめぐって","reason":"をめぐって requires a dispute or discussion, not opening hours."}]}}},{"japanese":"一人を除いて、全員が賛成した。","romaji":"Hitori o nozoite, zen'in ga sansei shita.","german":"Everyone agreed except for one person."},{"japanese":"一部の地域を除き、明日は晴れるでしょう。","romaji":"Ichibu no chiiki o nozoki, ashita wa hareru deshō.","german":"Except for some areas, it will probably be sunny tomorrow."}],"notes":"Same meaning as ～以外(は), but more formal. ～を抜きにして (N2) means \"without taking X into account / including X\" and emphasizes leaving out an element that would normally be needed, not an exception to a rule. を除けば often introduces a qualification: 値段を除けば完璧だ.","related":["n2-nuki-ni-shite","n2-ni-kagirazu","n2-wa-betsu-to-shite"]},
{"id":"n2-wo-hajime-to-suru","pattern":"～をはじめとする / ～をはじめとして","level":"N2","category":"Partikel","meaning":"first and foremost ..., starting with ... (and others)","explanation":"をはじめとする names a representative or especially important example and implies a larger group: \"X and many others\". Attributively before nouns (をはじめとする + Noun), adverbially as をはじめとして. More formal than ～をはじめ; typical of the news, speeches and corporate texts.","formation":"Noun + をはじめとする / をはじめとした + Noun; Noun + をはじめとして、～","examples":[{"japanese":"東京をはじめとする大都市では、家賃が上がり続けている。","romaji":"Tōkyō o hajime to suru daitoshi de wa, yachin ga agaritsuzukete iru.","german":"In big cities, Tokyo first and foremost, rents keep going up.","cloze":{"start":2,"answer":"をはじめとする","quiz":{"level":"N2","japanese":"東京をはじめとする大都市では、家賃が上がり続けている。","german":"In big cities, Tokyo first and foremost, rents keep going up.","start":2,"answer":"をはじめとする","acceptedAnswers":["をはじめとする","をはじめとした","などの"],"distractors":[{"text":"を中心に","reason":"Before a noun, を中心とする would be needed; を中心に is adverbial."},{"text":"をめぐって","reason":"をめぐって (\"over, concerning\" a dispute) cannot come directly before 大都市."},{"text":"をはじめて","reason":"はじめて means \"for the first time\" and does not link an example to a noun."}]}}},{"japanese":"校長先生をはじめとして、多くの先生方が卒業式に出席した。","romaji":"Kōchō-sensei o hajime to shite, ōku no sensei-gata ga sotsugyōshiki ni shusseki shita.","german":"Led by the principal, many teachers attended the graduation ceremony."},{"japanese":"寿司をはじめとする日本料理は、海外でも人気が高い。","romaji":"Sushi o hajime to suru Nihon ryōri wa, kaigai de mo ninki ga takai.","german":"Japanese food, sushi above all, is very popular abroad too."}],"notes":"～をはじめ (N3) is the shorter, slightly less formal form with the same meaning. The example named must be typical of or outstanding in the group. Difference from ～を中心に: that describes a spatial or thematic center, not the first member of a list.","related":["n3-o-hajime","n3-o-chushin-ni"]},
{"id":"n2-te-miseru","pattern":"～てみせる","level":"N2","category":"Verben","meaning":"to demonstrate; to show everyone, to be determined to","explanation":"てみせる means 1) to demonstrate something or to put on a show of an attitude, 2) to announce with strong determination that you will manage something: \"I'll prove it to you!\". Meaning 2 uses the dictionary form, often with 必ず or きっと.","formation":"Verb (て-form) + みせる","examples":[{"japanese":"次の試験では必ず合格してみせる。","romaji":"Tsugi no shiken de wa kanarazu gōkaku shite miseru.","german":"I'm definitely going to pass the next exam: I'll show everyone.","cloze":{"start":11,"answer":"てみせる","quiz":{"level":"N2","japanese":"次の試験では必ず合格してみせる。","german":"I'm definitely going to pass the next exam: I'll show everyone.","start":11,"answer":"てみせる","acceptedAnswers":["てみせる","てみせます"],"distractors":[{"text":"てある","reason":"てある requires a transitive verb and describes a state, not a resolution."},{"text":"ておく","reason":"ておく means \"to do in advance\" and does not fit passing an exam."},{"text":"てばかりいる","reason":"てばかりいる describes a constant habit and does not fit 次の試験 and 必ず."}]}}},{"japanese":"先生は実際に料理を作ってみせた。","romaji":"Sensei wa jissai ni ryōri o tsukutte miseta.","german":"The teacher actually demonstrated how to cook the dish."},{"japanese":"彼は平気な顔をしてみせたが、本当は怖かったはずだ。","romaji":"Kare wa heiki na kao o shite miseta ga, hontō wa kowakatta hazu da.","german":"He put on a calm face, but he must really have been scared."}],"notes":"Don't confuse it with ～てみる (\"to try\"): with てみる the outcome is open, whereas てみせる in meaning 2 is a self-confident announcement to others. The determination meaning is limited to the first person; みせる always presupposes an (imagined) audience.","related":["te-miru"]},
{"id":"n2-ni-shitara","pattern":"～にしたら / ～にすれば","level":"N2","category":"Partikel","meaning":"from the point of view of, for (someone)","explanation":"にしたら/にすれば puts itself in the position of a person or group and describes their feelings or point of view: \"For X, this is (surely) ...\". Usually about other people, often with a guess (だろう). Neutral; にしてみれば emphasizes putting yourself in their shoes even more strongly.","formation":"Noun (person/group) + にしたら / にすれば / にしてみれば","examples":[{"japanese":"子どもにしたら、毎日の塾は大変だろう。","romaji":"Kodomo ni shitara, mainichi no juku wa taihen darō.","german":"For the kids, going to cram school every day must be tough.","cloze":{"start":3,"answer":"にしたら","quiz":{"level":"N2","japanese":"子どもにしたら、毎日の塾は大変だろう。","german":"For the kids, going to cram school every day must be tough.","start":3,"answer":"にしたら","acceptedAnswers":["にしたら","にすれば","にしてみれば","にしてみたら","にとって","にとっては"],"distractors":[{"text":"にしては","reason":"にしては expresses a departure from expectations (\"considering they're kids\"), not a point of view."},{"text":"に対して","reason":"に対して marks a counterpart; the cram school is not being evaluated toward the children."},{"text":"にかけては","reason":"にかけては requires a field in which someone excels."}]}}},{"japanese":"親にすれば、子どもの将来が一番の心配なのだ。","romaji":"Oya ni sureba, kodomo no shōrai ga ichiban no shinpai na no da.","german":"For parents, their children's future is simply their biggest worry."},{"japanese":"観光客にしたら便利なサービスでも、住民にとっては迷惑な場合がある。","romaji":"Kankōkyaku ni shitara benri na sābisu de mo, jūmin ni totte wa meiwaku na baai ga aru.","german":"Even a service that's convenient for tourists can be a nuisance for local residents."}],"notes":"～にとって describes a general evaluation (important/difficult for X) and is used for things and people; にしたら emphasizes empathizing with a person and is almost only used with people. Don't confuse it with ～にしては (\"for, considering that ...\") or with ～としたら (hypothetical condition).","related":["n4-ni-totte","n1-kara-suru-to"]},
{"id":"n2-nai-kagiri","pattern":"～ないかぎり / ～ない限り","level":"N2","category":"Satzstrukturen","meaning":"unless, as long as ... not","explanation":"ないかぎり names the only condition under which a situation would change: \"As long as X doesn't happen, Y stays the same.\" The main clause usually describes something negative or unchanging. Neutral to formal; typical in warnings, rules and assessments.","formation":"Verb (ない-form) + かぎり / 限り; Noun + でない限り","examples":[{"japanese":"本人が努力しないかぎり、成績は上がらない。","romaji":"Honnin ga doryoku shinai kagiri, seiseki wa agaranai.","german":"Unless he makes an effort himself, his grades won't improve.","cloze":{"start":6,"answer":"ないかぎり","quiz":{"level":"N2","japanese":"本人が努力しないかぎり、成績は上がらない。","german":"Unless he makes an effort himself, his grades won't improve.","start":6,"answer":"ないかぎり","acceptedAnswers":["ないかぎり","ない限り","なければ","ないと","ないことには"],"distractors":[{"text":"ないものの","reason":"ないものの is concessive (\"although not ..., still\"); there is no contrast between not making an effort and poor grades."},{"text":"ないとたん","reason":"とたん requires the た-form of an affirmative verb and describes a moment, not a condition."},{"text":"ないついでに","reason":"ついでに links a side action to a main action; not doing something offers no \"opportunity\"."}]}}},{"japanese":"雨が降らない限り、試合は予定通り行われる。","romaji":"Ame ga furanai kagiri, shiai wa yotei-dōri okonawareru.","german":"Unless it rains, the match will go ahead as planned."},{"japanese":"緊急の場合でない限り、この番号には電話しないでください。","romaji":"Kinkyū no baai de nai kagiri, kono bangō ni wa denwa shinaide kudasai.","german":"Please don't call this number unless it's an emergency."}],"notes":"～ないことには (N3) is similar, but there the main clause is almost always negative (\"without X, it won't work\"). ないかぎり can also have a positive main clause (雨が降らない限り行われる). The affirmative ～限り (N3), by contrast, means \"as long as / as far as\": 元気な限り働きたい.","related":["n3-kagiri","n3-nai-koto-ni-wa"]},
{"id":"n2-koto-ni-wa","pattern":"～ことに(は)","level":"N2","category":"Satzstrukturen","meaning":"to my (surprise/delight ...)","explanation":"ことに(は) puts the speaker's feeling first, before the actual fact follows: 驚いたことに = \"To my surprise ...\". Only with emotion adjectives or verbs (嬉しい, 残念な, 驚いた, 困った). Rather written, but also common in speeches and narratives.","formation":"い-adjective + ことに(は) / な-adjective + な + ことに(は) / Verb (た-form) + ことに(は)","examples":[{"japanese":"驚いたことに、彼はもう結婚していた。","romaji":"Odoroita koto ni, kare wa mō kekkon shite ita.","german":"To my surprise, he was already married.","cloze":{"start":3,"answer":"ことに","quiz":{"level":"N2","japanese":"驚いたことに、彼はもう結婚していた。","german":"To my surprise, he was already married.","start":3,"answer":"ことに","acceptedAnswers":["ことに","ことには"],"distractors":[{"text":"ことで","reason":"ことで names a cause or a means; the surprise did not cause the marriage."},{"text":"ことから","reason":"ことから draws a conclusion from a fact, not from a feeling."},{"text":"ことなく","reason":"ことなく requires the dictionary form and means \"without ...ing\"."}]}}},{"japanese":"残念なことに、そのコンサートは中止になった。","romaji":"Zannen na koto ni, sono konsāto wa chūshi ni natta.","german":"Unfortunately, the concert was canceled."},{"japanese":"嬉しいことには、娘が第一志望の大学に合格した。","romaji":"Ureshii koto ni wa, musume ga daiichi shibō no daigaku ni gōkaku shita.","german":"To my delight, my daughter passed the entrance exam for the university that was her first choice."}],"notes":"The construction always expresses the speaker's attitude, not that of a third person. Don't confuse it with ～ことか (N2, exclamation: どんなに嬉しいことか) or with ～ことにする/～ことになる. In English it often corresponds to an adverb like \"unfortunately\", \"fortunately\" or \"surprisingly\".","related":["n2-koto-ka"]},
{"id":"n2-uchi-ni-hairanai","pattern":"～うちに入らない","level":"N2","category":"Satzstrukturen","meaning":"doesn't count as, can hardly be called","explanation":"うちに入らない downplays something: it doesn't meet the criteria to count as X: \"That's not really X at all.\" Often used with amounts or achievements (料理, 運動, 残業), modestly or dismissively. Colloquial; うち here means \"circle, range\".","formation":"Noun + の + うちに入らない / い-adjective・Verb (dictionary form) + うちに入らない","examples":[{"japanese":"30分歩くくらいでは、運動のうちに入らない。","romaji":"Sanjuppun aruku kurai de wa, undō no uchi ni hairanai.","german":"Just walking for 30 minutes doesn't count as exercise.","cloze":{"start":14,"answer":"うちに入らない","quiz":{"level":"N2","japanese":"30分歩くくらいでは、運動のうちに入らない。","german":"Just walking for 30 minutes doesn't count as exercise.","start":14,"answer":"うちに入らない","acceptedAnswers":["うちに入らない","うちには入らない"],"distractors":[{"text":"うちに入る","reason":"The affirmative form contradicts くらいでは (\"only this little\")."},{"text":"に過ぎない","reason":"に過ぎない comes directly after the noun, not after の."},{"text":"最中だ","reason":"最中だ means \"right in the middle of\" and does not fit the evaluation with くらいでは."}]}}},{"japanese":"私の料理なんて、料理のうちに入りません。","romaji":"Watashi no ryōri nante, ryōri no uchi ni hairimasen.","german":"What I make can hardly be called cooking."},{"japanese":"この程度の寒さは、寒いうちに入らない。","romaji":"Kono teido no samusa wa, samui uchi ni hairanai.","german":"Cold like this doesn't even count as cold."}],"notes":"Unlike ～に過ぎない (\"nothing more than\"), which classifies something matter-of-factly, うちに入らない expresses that something doesn't even reach the threshold of a category. Don't confuse it with ～うちに (N3, \"while, as long as\": 若いうちに).","related":["n2-ni-suginai","n3-uchi-ni"]},
{"id":"n2-kara-iu-to","pattern":"～からいうと / ～からいえば / ～からいって","level":"N2","category":"Partikel","meaning":"from the standpoint of ..., judging by","explanation":"からいうと names the yardstick or standpoint from which a judgment is made: experience, position, data, field of expertise. \"Seen from X, ...\". Neutral to formal; からいって sounds somewhat more categorical. It does not come directly after people (not: 私からいうと).","formation":"Noun + からいうと / からいえば / からいって","examples":[{"japanese":"私の立場からいうと、その案には賛成できない。","romaji":"Watashi no tachiba kara iu to, sono an ni wa sansei dekinai.","german":"From my position, I can't agree with that proposal.","cloze":{"start":4,"answer":"からいうと","quiz":{"level":"N2","japanese":"私の立場からいうと、その案には賛成できない。","german":"From my position, I can't agree with that proposal.","start":4,"answer":"からいうと","acceptedAnswers":["からいうと","からいえば","からいって","から言うと","から言えば","からすると","からすれば","から見ると","から見れば"],"distractors":[{"text":"によると","reason":"によると names a source of information (\"according to\"), not a standpoint for your own judgment."},{"text":"をめぐって","reason":"をめぐって requires a point of dispute, not a yardstick for judgment."},{"text":"にかけては","reason":"にかけては requires a field in which someone is especially good."}]}}},{"japanese":"実力からいえば、彼がチームで一番だ。","romaji":"Jitsuryoku kara ieba, kare ga chīmu de ichiban da.","german":"In terms of ability, he's the best on the team."},{"japanese":"このデータからいって、計画が失敗する可能性は高い。","romaji":"Kono dēta kara itte, keikaku ga shippai suru kanōsei wa takai.","german":"Judging from this data, there's a high chance the plan will fail."}],"notes":"～からすると/～から見ると are almost interchangeable, but can also come directly after people (私からすると). からいうと, by contrast, requires an abstract standpoint (立場, 点, 経験). Don't confuse it with ～によると (\"according to\"), which names a source of information, not a yardstick for judgment.","related":["n1-kara-suru-to","n2-kara-miru-to"]},
{"id":"n2-bakari-da","pattern":"～ばかりだ","level":"N2","category":"Verben","meaning":"just keeps getting (worse), keeps increasing","explanation":"ばかりだ after a verb of change describes a development that keeps going relentlessly in one direction, almost always for the worse: 悪くなるばかりだ. The speaker sounds worried or resigned. Neutral to written; also in news style.","formation":"Verb (dictionary form, verb of change) + ばかりだ","examples":[{"japanese":"薬を飲んでいるのに、症状は悪くなるばかりだ。","romaji":"Kusuri o nonde iru no ni, shōjō wa waruku naru bakari da.","german":"Even though I'm taking medicine, my symptoms just keep getting worse.","cloze":{"start":17,"answer":"ばかりだ","quiz":{"level":"N2","japanese":"薬を飲んでいるのに、症状は悪くなるばかりだ。","german":"Even though I'm taking medicine, my symptoms just keep getting worse.","start":17,"answer":"ばかりだ","acceptedAnswers":["ばかりだ","一方だ"],"distractors":[{"text":"べきだ","reason":"べきだ expresses an obligation; symptoms are not \"supposed\" to get worse."},{"text":"ことはない","reason":"ことはない means \"there's no need to\" and makes no sense with のに."},{"text":"つもりだ","reason":"つもりだ expresses an intention; symptoms have no will."}]}}},{"japanese":"この町の人口は減るばかりだ。","romaji":"Kono machi no jinkō wa heru bakari da.","german":"This town's population just keeps shrinking."},{"japanese":"話し合いは進まず、両国の対立は深まるばかりだった。","romaji":"Hanashiai wa susumazu, ryōkoku no tairitsu wa fukamaru bakari datta.","german":"The talks made no progress, and the conflict between the two countries only kept deepening."}],"notes":"Almost synonymous with ～一方だ, but ばかりだ is even more firmly tied to negative developments; 一方だ can also be neutral (利用者は増える一方だ). Don't confuse it with ～ばかり (N4, \"only, nothing but\"), ～たばかり (\"just did\") or ～んばかり (N1, \"as if about to\").","related":["n2-ippou-da","n4-bakari-p"]},
{"id":"n2-mo-nara-mo","pattern":"～も～なら～も","level":"N2","category":"Satzstrukturen","meaning":"X is no better than Y; both are equally (bad)","explanation":"AもAならBもB criticizes two parties equally: \"A is no better than B\"; both are in the wrong. In the fixed form, the same noun is repeated (親も親なら子も子だ). Colloquial and clearly reproachful.","formation":"Noun A + も + Noun A + なら + Noun B + も + Noun B + だ","examples":[{"japanese":"約束を破る夫も夫なら、黙っている妻も妻だ。","romaji":"Yakusoku o yaburu otto mo otto nara, damatte iru tsuma mo tsuma da.","german":"The husband breaks his promises, but the wife who says nothing about it is no better.","cloze":{"start":8,"answer":"なら","quiz":{"level":"N2","japanese":"約束を破る夫も夫なら、黙っている妻も妻だ。","german":"The husband breaks his promises, but the wife who says nothing about it is no better.","start":8,"answer":"なら","acceptedAnswers":["なら","だし"],"distractors":[{"text":"から","reason":"から cannot attach to the repetition 夫も夫; the copula is missing."},{"text":"ほど","reason":"ほど marks a degree and does not link two equal reproaches."},{"text":"ばかりか","reason":"ばかりか escalates from one member to the next instead of judging both equally."}]}}},{"japanese":"親も親なら子も子で、二人とも挨拶ひとつしない。","romaji":"Oya mo oya nara ko mo ko de, futari tomo aisatsu hitotsu shinai.","german":"The parent is no better than the child: neither of them even says hello."},{"japanese":"売る方も売る方なら、買う方も買う方だ。","romaji":"Uru hō mo uru hō nara, kau hō mo kau hō da.","german":"The people selling it are no better than the people buying it."}],"notes":"Don't confuse it with ～も～ば～も (neutral listing: 歌も歌えば踊りもする), which can also be positive. も～なら～も is almost always a reproach aimed at both sides. Similar in meaning, but more neutral: どっちもどっちだ (\"both are equally to blame\").","related":["n2-mo-ba-mo","n1-to-ii-to-ii"]},
{"id":"n2-mono-dewa-nai","pattern":"～ものではない / ～もんじゃない","level":"N2","category":"Satzstrukturen","meaning":"one doesn't do that, one shouldn't","explanation":"ものではない after the dictionary form states a general norm or rule of life: \"That's not something you do.\" Often used as a warning or piece of advice from older people to younger ones. In speech often もんじゃない; it sounds preachy.","formation":"Verb (dictionary form) + ものではない / もんじゃない","examples":[{"japanese":"人の悪口を言うものではない。","romaji":"Hito no waruguchi o iu mono de wa nai.","german":"You shouldn't speak ill of others.","cloze":{"start":7,"answer":"ものではない","quiz":{"level":"N2","japanese":"人の悪口を言うものではない。","german":"You shouldn't speak ill of others.","start":7,"answer":"ものではない","acceptedAnswers":["ものではない","もんじゃない","ものじゃない","べきではない"],"distractors":[{"text":"ものなら","reason":"ものなら introduces a condition and cannot end the sentence."},{"text":"ものの","reason":"ものの is concessive and requires a following main clause."},{"text":"ものだから","reason":"ものだから gives a reason and requires a following main clause."}]}}},{"japanese":"夜遅くに一人で出歩くもんじゃないよ。","romaji":"Yoru osoku ni hitori de dearuku mon ja nai yo.","german":"You shouldn't go out alone late at night."},{"japanese":"他人の手紙を勝手に読むものではありません。","romaji":"Tanin no tegami o katte ni yomu mono de wa arimasen.","german":"One should not read other people's letters without permission."}],"notes":"～べきではない expresses a rather logical or moral obligation, ものではない a generally accepted custom (\"that's not done\"). Don't confuse it with ～たものではない (\"can't possibly\": 食べられたものではない) or ～というものではない (\"not necessarily\").","related":["n3-mono-da","n2-to-iu-mono-dewa-nai","n2-ta-mono-dewa-nai"]},
{"id":"n2-ni-tsuki","pattern":"～につき","level":"N2","category":"Partikel","meaning":"due to (formal); per, each","explanation":"につき has two meanings: 1) a formal reason on signs, notices and announcements (工事中につき = \"due to construction work\"), 2) distribution, \"per, each\" (一人につき3枚). The first meaning is typically written and official; in conversation you say ～ので or ～のため.","formation":"Noun + につき (reason); quantity/Noun + につき + amount (per)","examples":[{"japanese":"本日は定休日につき、お休みさせていただきます。","romaji":"Honjitsu wa teikyūbi ni tsuki, oyasumi sasete itadakimasu.","german":"Today is our regular day off, so we are closed.","cloze":{"start":6,"answer":"につき","quiz":{"level":"N2","japanese":"本日は定休日につき、お休みさせていただきます。","german":"Today is our regular day off, so we are closed.","start":6,"answer":"につき","acceptedAnswers":["につき","のため"],"distractors":[{"text":"について","reason":"について means \"about, regarding\" and does not give a reason for the closure."},{"text":"に対して","reason":"に対して marks a counterpart or a contrast, not a reason."},{"text":"にかけて","reason":"にかけて requires a period of time (～から～にかけて)."}]}}},{"japanese":"参加費は一人につき千円です。","romaji":"Sankahi wa hitori ni tsuki sen'en desu.","german":"The participation fee is 1,000 yen per person."},{"japanese":"工事中につき、この道は通行止めです。","romaji":"Kōji-chū ni tsuki, kono michi wa tsūkōdome desu.","german":"This road is closed due to construction work."}],"notes":"Don't confuse it with ～について (\"about, regarding\"). As a reason, につき only follows nouns and sounds official; for personal reasons in everyday life it sounds stiff. In the meaning \"per\", it is interchangeable with ～あたり (一人あたり).","related":["n4-ni-tsuite","n1-yue-ni"]},
{"id":"n2-ni-kagiri","pattern":"～に限り","level":"N2","category":"Partikel","meaning":"only, exclusively (for)","explanation":"に限り explicitly limits a rule or offer to a particular group, time or condition: \"only for X\". Typical in advertising, notices and terms and conditions (本日に限り). Formal; the main clause usually describes a benefit or an exception.","formation":"Noun + に限り / に限って (in this meaning)","examples":[{"japanese":"本日に限り、全品二割引きとなります。","romaji":"Honjitsu ni kagiri, zenpin niwaribiki to narimasu.","german":"Today only, everything is 20% off.","cloze":{"start":2,"answer":"に限り","quiz":{"level":"N2","japanese":"本日に限り、全品二割引きとなります。","german":"Today only, everything is 20% off.","start":2,"answer":"に限り","acceptedAnswers":["に限り","に限って","だけ"],"distractors":[{"text":"にわたって","reason":"にわたって requires a span of time; a single day is not a span."},{"text":"にかけて","reason":"にかけて requires a period with a starting point (～から～にかけて)."},{"text":"に先立って","reason":"に先立って means \"prior to\"; the discount does not apply before today."}]}}},{"japanese":"先着50名様に限り、記念品を差し上げます。","romaji":"Senchaku gojū-mei-sama ni kagiri, kinenhin o sashiagemasu.","german":"Only the first 50 people will receive a commemorative gift."},{"japanese":"会員の方に限り、駐車場を無料でご利用いただけます。","romaji":"Kaiin no kata ni kagiri, chūshajō o muryō de goriyō itadakemasu.","german":"Only members can use the parking lot free of charge."}],"notes":"Distinguish it from ～に限って in the sense of \"of all times\" (忙しい日に限って…): there, annoyance comes through; with に限り it doesn't. ～に限らず is the opposite (\"not only\"). ～に限る at the end of a sentence means something else again: \"there's nothing like\".","related":["n2-ni-kagitte","n2-ni-kagirazu"]},
{"id":"n2-zu-jimai","pattern":"～ずじまい","level":"N2","category":"Verben","meaning":"ended up not (doing) after all","explanation":"ずじまい describes how you intended to do something, or should have, but never did it right up to the end, and the opportunity is now gone. It sounds regretful or disappointed. Usually as ずじまいだった or ずじまいで; する becomes せずじまい.","formation":"Verb (ない-stem) + ずじまい (する → せずじまい)","examples":[{"japanese":"旅行中は忙しくて、結局彼に会えずじまいだった。","romaji":"Ryokō-chū wa isogashikute, kekkyoku kare ni aezu jimai datta.","german":"I was so busy during the trip that I never got to see him in the end.","cloze":{"start":15,"answer":"ずじまい","quiz":{"level":"N2","japanese":"旅行中は忙しくて、結局彼に会えずじまいだった。","german":"I was so busy during the trip that I never got to see him in the end.","start":15,"answer":"ずじまい","acceptedAnswers":["ずじまい","ないまま"],"distractors":[{"text":"ずにはいられない","reason":"ずにはいられない (\"can't help but\") contradicts the meaning, and だった cannot attach directly to いられない."},{"text":"ずにすむ","reason":"ずにすむ expresses relief (\"didn't have to\") and does not come before だった."},{"text":"ざるを得ない","reason":"ざるを得ない (\"have no choice but to\") fits neither the meaning nor the position before だった."}]}}},{"japanese":"せっかく買ったのに、一度も着ずじまいの服がたくさんある。","romaji":"Sekkaku katta no ni, ichido mo kizu jimai no fuku ga takusan aru.","german":"I have lots of clothes that I went to the trouble of buying but never wore even once."},{"japanese":"忘れ物の持ち主は、わからずじまいだった。","romaji":"Wasuremono no mochinushi wa, wakarazu jimai datta.","german":"Who the forgotten items belonged to was never found out."}],"notes":"～ないまま is neutral (\"without\"), whereas ずじまい emphasizes that the chance is gone for good and sounds regretful. Don't confuse it with ～ずにすむ (N4, \"don't have to, be spared\"), which expresses relief. じまい comes from しまう (\"to finish\").","related":["n4-mama","n4-te-sumu"]},
{"id":"n2-te-made","pattern":"～てまで","level":"N2","category":"Satzstrukturen","meaning":"even going so far as to ...; at the cost of","explanation":"てまで expresses that someone resorts to an extreme or inappropriate means to reach a goal: \"even going as far as X\". The speaker often views this critically or asks whether it is worth it (～てまで～たくない). Neutral, spoken and written.","formation":"Verb (て-form) + まで","examples":[{"japanese":"借金してまで、ブランド品を買いたくはない。","romaji":"Shakkin shite made, burando-hin o kaitaku wa nai.","german":"I don't want to buy designer goods if it means going into debt.","cloze":{"start":3,"answer":"てまで","quiz":{"level":"N2","japanese":"借金してまで、ブランド品を買いたくはない。","german":"I don't want to buy designer goods if it means going into debt.","start":3,"answer":"てまで","acceptedAnswers":["てまで"],"distractors":[{"text":"てこそ","reason":"てこそ (\"only when\") positively highlights a necessary condition and does not fit the refusal."},{"text":"てばかり","reason":"てばかり requires a following いる and describes a habit."},{"text":"たきり","reason":"たきり (\"not since\") makes no sense with the sentence expressing a wish."}]}}},{"japanese":"彼は徹夜してまで、その仕事を仕上げた。","romaji":"Kare wa tetsuya shite made, sono shigoto o shiageta.","german":"He even stayed up all night to finish that job."},{"japanese":"人をだましてまで、お金を稼ぎたいとは思わない。","romaji":"Hito o damashite made, okane o kasegitai to wa omowanai.","german":"I don't want to make money if it means deceiving people."}],"notes":"With nouns, plain まで is used (\"even\": 子どもまで知っている). てまで, by contrast, emphasizes the price you pay. ～てでも is similar but expresses determination more (\"whatever it takes\": 借金してでも行きたい), while てまで often comes with a negative or criticism.","related":["temo","n4-sae","n2-te-demo"]},
{"id":"n2-to-no-koto-da","pattern":"～とのことだ","level":"N2","category":"Satzstrukturen","meaning":"I hear that; (someone) says to tell you that","explanation":"とのことだ passes on information or a message you have received: \"I've been told that ...\". More polite and more formal than ～そうだ (伝聞); typical in business communication, emails and when passing on messages (田中さんから、遅れるとのことです).","formation":"Sentence (plain form) + とのことだ / とのことです","examples":[{"japanese":"部長は会議に少し遅れるとのことです。","romaji":"Buchō wa kaigi ni sukoshi okureru to no koto desu.","german":"The department manager says he'll be a little late for the meeting.","cloze":{"start":11,"answer":"とのことです","quiz":{"level":"N2","japanese":"部長は会議に少し遅れるとのことです。","german":"The department manager says he'll be a little late for the meeting.","start":11,"answer":"とのことです","acceptedAnswers":["とのことです","そうです","ということです"],"distractors":[{"text":"ことです","reason":"ことです without との expresses advice (\"you should\"), not a passed-on message."},{"text":"ようにです","reason":"ように cannot be closed directly with です."},{"text":"とのことで","reason":"とのことで requires a following clause and cannot end the sentence."}]}}},{"japanese":"天気予報によると、明日は大雪になるとのことだ。","romaji":"Tenki yohō ni yoru to, ashita wa ōyuki ni naru to no koto da.","german":"According to the weather forecast, there will be heavy snow tomorrow."},{"japanese":"先方から、資料を明日までに送ってほしいとのことでした。","romaji":"Senpō kara, shiryō o ashita made ni okutte hoshii to no koto deshita.","german":"The other party said they would like us to send the documents by tomorrow."}],"notes":"Unlike ～そうだ (hearsay), とのこと can also pass on requests and messages word for word and sounds more formal. ～ということだ (N2) can also express a conclusion (\"that means, so\"); とのことだ is only used for passing things on.","related":["n4-sou-hearsay","n2-to-iu-koto-da","n2-toka-denbun"]},
{"id":"n2-ka-to-iu-to","pattern":"～かというと / ～かといえば","level":"N2","category":"Satzstrukturen","meaning":"if you ask whether ...; whether ... – (not necessarily)","explanation":"かというと takes up an obvious question or conclusion in order to answer it – often to deny it: \"Does that mean ...? Not necessarily.\" With question words (なぜかというと) it introduces an explanation. Neutral; common in argumentation.","formation":"Sentence (plain form) / question-word sentence + かというと / かといえば; often + そうではない・～わけではない","examples":[{"japanese":"高い店がおいしいかというと、必ずしもそうではない。","romaji":"Takai mise ga oishii ka to iu to, kanarazushimo sō de wa nai.","german":"Are expensive restaurants always good? Not necessarily.","cloze":{"start":8,"answer":"かというと","quiz":{"level":"N2","japanese":"高い店がおいしいかというと、必ずしもそうではない。","german":"Are expensive restaurants always good? Not necessarily.","start":8,"answer":"かというと","acceptedAnswers":["かというと","かといえば","かといったら"],"distractors":[{"text":"からといって","reason":"からといって requires a conclusion in the main clause; here, however, そうではない answers a question."},{"text":"かのように","reason":"かのように (\"as if\") compares with an appearance and does not fit そうではない."},{"text":"かどうか","reason":"かどうか forms an embedded question that requires a predicate such as わからない."}]}}},{"japanese":"なぜ遅れたかというと、電車が止まっていたからだ。","romaji":"Naze okureta ka to iu to, densha ga tomatte ita kara da.","german":"Why was I late? Because the trains had stopped."},{"japanese":"彼が嫌いかといえば、そういうわけでもない。","romaji":"Kare ga kirai ka to ieba, sō iu wake de mo nai.","german":"Do I dislike him? That's not quite it either."}],"notes":"～からといって (N3) directly rejects a wrong conclusion (\"just because ...\"); かというと first poses the question explicitly and then answers it. After なぜ/どうして, ～からだ almost always follows. Do not confuse with ～というと (\"speaking of ...\").","related":["n3-kara-toitte","n3-wake-dewa-nai"]},
{"id":"n2-mo-douzen","pattern":"～も同然だ","level":"N2","category":"Satzstrukturen","meaning":"as good as, practically","explanation":"も同然だ expresses that something is not yet formally the case but in fact might as well be: \"It's as good as won.\" Stronger and more vivid than ～と同じだ. Neutral; often in conversation and in sports and business reports. Attributive: も同然の + noun.","formation":"Noun + も同然だ / Verb (た-form) + も同然だ; Noun + も同然の + Noun","examples":[{"japanese":"ここまで来れば、優勝したも同然だ。","romaji":"Koko made kureba, yūshō shita mo dōzen da.","german":"Now that we've come this far, we've as good as won the title.","cloze":{"start":12,"answer":"も同然だ","quiz":{"level":"N2","japanese":"ここまで来れば、優勝したも同然だ。","german":"Now that we've come this far, we've as good as won the title.","start":12,"answer":"も同然だ","acceptedAnswers":["も同然だ","も同然"],"distractors":[{"text":"ばかりだ","reason":"たばかりだ means \"have only just\" and does not fit the condition ここまで来れば."},{"text":"ことはない","reason":"たことはない (\"have never\") contradicts the confident conclusion."},{"text":"にすぎない","reason":"にすぎない (\"merely\") downplays the victory and does not fit the conclusion."}]}}},{"japanese":"彼とは十年以上一緒に暮らしていて、家族も同然だ。","romaji":"Kare to wa jūnen ijō issho ni kurashite ite, kazoku mo dōzen da.","german":"We've lived together for over ten years – he's practically family."},{"japanese":"この車は古すぎて、ただも同然の値段で売られていた。","romaji":"Kono kuruma wa furusugite, tada mo dōzen no nedan de urarete ita.","german":"The car was so old that it was being sold for next to nothing."}],"notes":"～のようだ/～みたいだ only compare outward appearance (\"like\"); も同然, by contrast, claims that the difference practically no longer matters. ～に等しい means the same but is more literary. ～かのようだ (N2) describes an appearance that does not match reality.","related":["n2-ka-no-you-ni"]},
{"id":"n2-you-dewa","pattern":"～ようでは","level":"N2","category":"Satzstrukturen","meaning":"if (you're already) ..., then (it's hopeless)","explanation":"ようでは (colloquially ようじゃ) presents an undesirable behavior or a bad state as a condition and draws a negative result from it: \"If you already fail at this, it's hopeless.\" Critical and admonishing; often used by superiors.","formation":"Verb (dictionary form/ない-form/ている-form) + ようでは / ようじゃ + negative consequence","examples":[{"japanese":"こんな簡単な問題が解けないようでは、合格は難しい。","romaji":"Konna kantan na mondai ga tokenai yō de wa, gōkaku wa muzukashii.","german":"If you can't even solve a simple problem like this, passing will be tough.","cloze":{"start":13,"answer":"ようでは","quiz":{"level":"N2","japanese":"こんな簡単な問題が解けないようでは、合格は難しい。","german":"If you can't even solve a simple problem like this, passing will be tough.","start":13,"answer":"ようでは","acceptedAnswers":["ようでは","ようじゃ","のでは","ようなら"],"distractors":[{"text":"ように","reason":"ように expresses a purpose or request (\"so that\") and makes no sense here."},{"text":"ようがない","reason":"ようがない follows the ます-stem (解きようがない), not the ない-form."},{"text":"ようでも","reason":"ようでも (\"even if it seems so\") is concessive and contradicts the conclusion."}]}}},{"japanese":"毎朝遅刻するようでは、社会人として失格だ。","romaji":"Maiasa chikoku suru yō de wa, shakaijin to shite shikkaku da.","german":"Someone who's late every morning is a failure as a working adult."},{"japanese":"そんなことで泣いているようじゃ、この先やっていけないよ。","romaji":"Sonna koto de naite iru yō ja, kono saki yatte ikenai yo.","german":"If you're crying over something like that, you won't make it from here on."}],"notes":"Unlike neutral ～ば/～たら, ようでは contains a judgment: the behavior is criticized as inadequate. The main clause is practically always negative (困る, 無理だ, だめだ). Do not confuse with ～ようではないか (N1, \"let's ...\") or ～ようで (\"it seems, and ...\").","related":["n4-nara","n3-nai-koto-ni-wa"]},
{"id":"n2-wo-kanete","pattern":"～を兼ねて","level":"N2","category":"Partikel","meaning":"also serving as, combined with","explanation":"を兼ねて expresses that one action serves several purposes at the same time: \"a trip to the bakery that doubles as a walk\". Often AとBを兼ねて. Neutral to polite; common in letters, invitations and company events. Attributive: を兼ねた + noun.","formation":"Noun + を兼ねて / を兼ねた + Noun; Noun A + と + Noun B + を兼ねて","examples":[{"japanese":"散歩を兼ねて、駅前のパン屋まで歩いて行った。","romaji":"Sanpo o kanete, ekimae no pan'ya made aruite itta.","german":"I walked to the bakery in front of the station – partly as a stroll.","cloze":{"start":2,"answer":"を兼ねて","quiz":{"level":"N2","japanese":"散歩を兼ねて、駅前のパン屋まで歩いて行った。","german":"I walked to the bakery in front of the station – partly as a stroll.","start":2,"answer":"を兼ねて","acceptedAnswers":["を兼ねて","をかねて","も兼ねて"],"distractors":[{"text":"をめぐって","reason":"をめぐって requires a dispute or a discussion."},{"text":"を問わず","reason":"を問わず requires a category (年齢を問わず), not a purpose."},{"text":"に反して","reason":"に反して means \"contrary to\" and makes no sense with the walk."}]}}},{"japanese":"新年会と歓迎会を兼ねて、食事会を開いた。","romaji":"Shinnenkai to kangeikai o kanete, shokujikai o hiraita.","german":"We held a dinner that served as both a New Year party and a welcome party."},{"japanese":"趣味と実益を兼ねた仕事を探している。","romaji":"Shumi to jitsueki o kaneta shigoto o sagashite iru.","german":"I'm looking for a job that combines my hobby with practical benefit."}],"notes":"～ついでに (N3) describes a side action that happens to present itself; を兼ねて names a purpose that is intended at the same time. ～がてら (N1) is similar but more literary and mostly used with verbs of motion. Also written をかねて.","related":["n1-gatera","n1-katagata"]},
{"id":"n2-mo-shinai","pattern":"～もしない","level":"N2","category":"Verben","meaning":"not even (do)","explanation":"もしない stresses, with indignation or disappointment, that someone does not even attempt something that would be a matter of course: \"He didn't even look at it.\" も goes between the ます-stem and しない. Judgmental, mostly about other people; polite もしません, connective もせず(に).","formation":"Verb (ます-stem) + もしない / もしないで / もせず(に)","examples":[{"japanese":"彼は私の話を聞きもしないで、反対した。","romaji":"Kare wa watashi no hanashi o kiki mo shinai de, hantai shita.","german":"He objected without even listening to what I had to say.","cloze":{"start":8,"answer":"もしないで","quiz":{"level":"N2","japanese":"彼は私の話を聞きもしないで、反対した。","german":"He objected without even listening to what I had to say.","start":8,"answer":"もしないで","acceptedAnswers":["もしないで","もせずに","もせず","さえしないで"],"distractors":[{"text":"さえして","reason":"The affirmative form (\"even listened\") contradicts \"without listening\"."},{"text":"がちで","reason":"がち describes a tendency and does not combine meaningfully with a one-time objection."},{"text":"ぬいて","reason":"ぬく means \"to see something through to the end\" and contradicts \"without listening\"."}]}}},{"japanese":"息子は私が作った料理を食べもしない。","romaji":"Musuko wa watashi ga tsukutta ryōri o tabe mo shinai.","german":"My son won't even eat the food I cook."},{"japanese":"彼女はこちらを見もせずに、部屋を出て行った。","romaji":"Kanojo wa kochira o mi mo sezu ni, heya o dete itta.","german":"She left the room without even looking our way."}],"notes":"Plain ～ない only states a fact; もしない additionally expresses criticism or disappointment. ～ようとしない (N2) stresses a lack of will over a longer period, もしない the failure to do even the simplest things. ～さえしない means the same but is even more emphatic.","related":["n2-you-to-shinai","n4-sae"]},
{"id":"n2-buru","pattern":"～ぶる","level":"N2","category":"Verben","meaning":"to act like, to pretend to be","explanation":"ぶる forms verbs meaning \"to (overly) present oneself as X\": 偉ぶる (to act important), 上品ぶる (to act refined), 知ったかぶり (pretending to know). Always pejorative: someone fakes a quality or shows it off. Conjugates like a godan verb.","formation":"Noun / い-adjective (stem) / な-adjective (stem) + ぶる (ぶって, ぶらない ...)","examples":[{"japanese":"彼は少し出世しただけで、すぐに偉ぶる。","romaji":"Kare wa sukoshi shusse shita dake de, sugu ni eraburu.","german":"He's only moved up a little, and he's already putting on airs.","cloze":{"start":16,"answer":"ぶる","quiz":{"level":"N2","japanese":"彼は少し出世しただけで、すぐに偉ぶる。","german":"He's only moved up a little, and he's already putting on airs.","start":16,"answer":"ぶる","acceptedAnswers":["ぶる","そうにする"],"distractors":[{"text":"がる","reason":"偉がる is not a common form; がる describes the feelings of third persons, not showing off."},{"text":"っぽい","reason":"偉っぽい is uncommon, and っぽい cannot be used with すぐに like a verb."},{"text":"めく","reason":"めく means \"to show signs of something\" (春めく) and does not combine with 偉."}]}}},{"japanese":"彼女はいつも上品ぶっているが、本当は気さくな人だ。","romaji":"Kanojo wa itsumo jōhin butte iru ga, hontō wa kisaku na hito da.","german":"She always acts so refined, but she's actually a very easygoing person."},{"japanese":"知らないくせに、知ったかぶりをするのはやめなさい。","romaji":"Shiranai kuse ni, shittakaburi o suru no wa yamenasai.","german":"Stop pretending you know when you don't."}],"notes":"～がる (N4) describes the feelings or wishes of third persons as they show outwardly (寒がる), without reproach. ～ぶる, by contrast, implies fakeness or showing off. ～っぽい (N4) means \"seems like, tends to\" and is not necessarily negative.","related":["n4-garu","n4-ppoi"]},
{"id":"n2-jou","pattern":"～上（じょう）","level":"N2","category":"Partikel","meaning":"from the standpoint of, in terms of, -wise","explanation":"上（じょう） as a suffix on Sino-Japanese nouns means \"from the standpoint of, as far as X is concerned\": 法律上 (legally), 健康上 (health-wise), 教育上 (educationally). Formal and very common in the news, administration and business. Continues with の + noun or with は/も.","formation":"Noun (usually Sino-Japanese) + 上 / 上は / 上の + Noun","examples":[{"japanese":"健康上の理由で、会社を辞めることにした。","romaji":"Kenkō-jō no riyū de, kaisha o yameru koto ni shita.","german":"I decided to leave the company for health reasons.","cloze":{"start":2,"answer":"上","quiz":{"level":"N2","japanese":"健康上の理由で、会社を辞めることにした。","german":"I decided to leave the company for health reasons.","start":2,"answer":"上","acceptedAnswers":["上"],"distractors":[{"text":"的","reason":"的 forms a な-adjective and requires な before a noun (健康的な), not の."},{"text":"向き","reason":"向き means \"suitable for\"; a \"reason suitable for health\" makes no sense."},{"text":"気味","reason":"気味 means \"slightly, a touch of\" and does not follow 健康."}]}}},{"japanese":"契約上、この情報は外部に公開できません。","romaji":"Keiyaku-jō, kono jōhō wa gaibu ni kōkai dekimasen.","german":"Under the contract, we cannot disclose this information to outside parties."},{"japanese":"その映画は、子どもの教育上よくないと言われている。","romaji":"Sono eiga wa, kodomo no kyōiku-jō yokunai to iwarete iru.","german":"That movie is said to be bad for children from an educational standpoint."}],"notes":"Do not confuse with ～上で (N3, \"when/after\"), ～上は (N2, \"now that\") or ～上に (N2, \"in addition\"), which are read うえ. ～的 (N3), by contrast, forms な-adjectives (\"-al, -ic\"); 上 forms adverbial phrases or, with の, noun modifiers.","related":["n3-teki","n3-ue-de"]},
{"id":"n2-tai-mono-da","pattern":"～たいものだ / ～てほしいものだ","level":"N2","category":"Satzstrukturen","meaning":"I would (really) like to ...; I do hope","explanation":"たいものだ and てほしいものだ intensify a wish and give it a reflective, often solemn tone: \"That is something I would truly wish for.\" Common with long-term wishes or with hopes directed at people in general. Often もんだ in speech.","formation":"Verb (ます-stem) + たいものだ / Verb (て-form) + ほしいものだ","examples":[{"japanese":"一度でいいから、オーロラを見てみたいものだ。","romaji":"Ichido de ii kara, ōrora o mite mitai mono da.","german":"Even just once, I'd really love to see the northern lights.","cloze":{"start":16,"answer":"たいものだ","quiz":{"level":"N2","japanese":"一度でいいから、オーロラを見てみたいものだ。","german":"Even just once, I'd really love to see the northern lights.","start":16,"answer":"たいものだ","acceptedAnswers":["たいものだ","たいもんだ","たい","たいなあ"],"distractors":[{"text":"たものだ","reason":"たものだ recalls the past (\"often used to\") and contradicts 一度でいいから."},{"text":"たがる","reason":"たがる describes a third person's wish, not one's own."},{"text":"たことがある","reason":"A statement about experience does not fit 一度でいいから (\"even just once\")."}]}}},{"japanese":"子どもたちには、自分の夢を大切にしてほしいものだ。","romaji":"Kodomotachi ni wa, jibun no yume o taisetsu ni shite hoshii mono da.","german":"I truly hope the children will cherish their own dreams."},{"japanese":"早く平和な世の中になってほしいものです。","romaji":"Hayaku heiwa na yo no naka ni natte hoshii mono desu.","german":"I do hope the world becomes a peaceful place soon."}],"notes":"The ものだ forms (N3) have several functions: norm (するものだ), reminiscence (したものだ) and amazement. たいものだ belongs to the emotional meaning and must not be confused with the reminiscence form ～たものだ (\"I often used to ...\"). It is unsuitable for spontaneous, concrete wishes (水が飲みたい).","related":["n3-mono-da","n4-tehoshii"]},
{"id":"n2-wo-to-shite","pattern":"～を～として / ～を～とする","level":"N2","category":"Partikel","meaning":"X as Y (to set, to regard)","explanation":"を～として/とする specifies what role or function something has: \"to take X as Y, to make X the Y\" – for example 目標, 目的, 条件, テーマ. Formal; common in rules, plans, reports and the news. Attributive: を～とする / とした + noun.","formation":"Noun A + を + Noun B + として / とする / とした + Noun","examples":[{"japanese":"彼は日本語の教師になることを目標として、毎日勉強している。","romaji":"Kare wa Nihongo no kyōshi ni naru koto o mokuhyō to shite, mainichi benkyō shite iru.","german":"He studies every day with the goal of becoming a Japanese teacher.","cloze":{"start":16,"answer":"として","quiz":{"level":"N2","japanese":"彼は日本語の教師になることを目標として、毎日勉強している。","german":"He studies every day with the goal of becoming a Japanese teacher.","start":16,"answer":"として","acceptedAnswers":["として","にして","とし"],"distractors":[{"text":"について","reason":"について cannot follow ～を目標; the verb that governs を is missing."},{"text":"に対して","reason":"に対して cannot attach to an object marked with を."},{"text":"によって","reason":"によって (\"by, depending on\") cannot attach to an object marked with を."}]}}},{"japanese":"このイベントは、地域の活性化を目的とする。","romaji":"Kono ibento wa, chiiki no kasseika o mokuteki to suru.","german":"The purpose of this event is to revitalize the region."},{"japanese":"環境問題をテーマとした講演会が開かれた。","romaji":"Kankyō mondai o tēma to shita kōenkai ga hirakareta.","german":"A lecture on the theme of environmental problems was held."}],"notes":"Plain ～として (N4) marks a role of the subject (教師として働く). In を～として, by contrast, an object is explicitly declared to be something. ～を中心として and ～をはじめとして are fixed variants of this pattern.","related":["n4-toshite","n3-o-chushin-ni"]},
{"id":"n2-ni-mo-hodo-ga-aru","pattern":"～にもほどがある","level":"N2","category":"Satzstrukturen","meaning":"there are limits; ... really goes too far","explanation":"にもほどがある criticizes something for exceeding the tolerable limit: \"Even X has its limits!\" – for example with jokes, cheekiness or carelessness. Strongly emotional and reproachful; mostly spoken, but also written in comments and letters to the editor.","formation":"Noun / い-adjective (dictionary form) / な-adjective (stem) + にもほどがある","examples":[{"japanese":"三時間も遅れてくるなんて、失礼にもほどがある。","romaji":"Sanjikan mo okurete kuru nante, shitsurei ni mo hodo ga aru.","german":"Showing up three hours late – that's outrageously rude!","cloze":{"start":15,"answer":"にもほどがある","quiz":{"level":"N2","japanese":"三時間も遅れてくるなんて、失礼にもほどがある。","german":"Showing up three hours late – that's outrageously rude!","start":15,"answer":"にもほどがある","acceptedAnswers":["にもほどがある","にも程がある"],"distractors":[{"text":"に越したことはない","reason":"に越したことはない (\"it would be best\") recommends something and does not fit the indignation."},{"text":"に限る","reason":"に限る (\"nothing beats\") recommends something; rudeness is not being recommended."},{"text":"にかけては","reason":"にかけては requires a field of expertise and a main clause about special abilities."}]}}},{"japanese":"冗談にもほどがあるよ。","romaji":"Jōdan ni mo hodo ga aru yo.","german":"There's a limit to joking around!"},{"japanese":"いくら安いからといって、品質が悪いにもほどがある。","romaji":"Ikura yasui kara to itte, hinshitsu ga warui ni mo hodo ga aru.","german":"Cheap or not, quality this bad is going too far."}],"notes":"～すぎる only describes an excess; にもほどがある adds the speaker's indignation. ～極まりない (N1) belongs to written language and mainly follows Sino-Japanese な-adjectives (失礼極まりない). Do not confuse with ～ほど (N4, degree/comparison).","related":["sugiru","n1-kiwamarinai"]},
{"id":"n2-to-mieru","pattern":"～とみえる / ～とみえて","level":"N2","category":"Satzstrukturen","meaning":"apparently, evidently (judging by signs)","explanation":"とみえる infers a guess from an observed fact: \"Evidently ...\" The clue is usually stated directly. Literary/narrative in style; with とみえて, the guess and the observed result are linked (\"apparently ..., since ...\").","formation":"Sentence (plain form) + とみえる / とみえて / とみえ","examples":[{"japanese":"彼は何かいいことがあったとみえて、朝からずっと機嫌がいい。","romaji":"Kare wa nani ka ii koto ga atta to miete, asa kara zutto kigen ga ii.","german":"Something good must have happened to him – he's been in a good mood all morning.","cloze":{"start":12,"answer":"とみえて","quiz":{"level":"N2","japanese":"彼は何かいいことがあったとみえて、朝からずっと機嫌がいい。","german":"Something good must have happened to him – he's been in a good mood all morning.","start":12,"answer":"とみえて","acceptedAnswers":["とみえて","とみえ","らしく","ようで"],"distractors":[{"text":"としても","reason":"としても (\"even if\") concedes an assumption; the good mood would then be illogical."},{"text":"とはいえ","reason":"とはいえ (\"although ..., still\") requires a contrast; a good mood after something nice is not one."},{"text":"ばかりに","reason":"ばかりに names the cause of a regrettable result; a good mood is not regrettable."}]}}},{"japanese":"子どもたちはよほど疲れたとみえる。ぐっすり眠っている。","romaji":"Kodomotachi wa yohodo tsukareta to mieru. Gussuri nemutte iru.","german":"The children must be really tired. They're sound asleep."},{"japanese":"夜中に雨が降ったとみえて、道がぬれている。","romaji":"Yonaka ni ame ga futta to miete, michi ga nurete iru.","german":"It must have rained during the night – the road is wet."}],"notes":"～らしい / ～ようだ (N4) are neutral forms of conjecture; とみえる puts more stress on the visible clue and sounds more written. Unlike ～そうだ (appearance), とみえる follows complete sentences, often in the past. Do not confuse with the verb 見える (\"to be visible\").","related":["n4-rashii","n4-you-da"]},
{"id":"n2-nari-ni","pattern":"～なりに / ～なりの","level":"N2","category":"Satzstrukturen","meaning":"in one's own way, within one's means","explanation":"なりに acknowledges that someone acts in their own way within the (limited) scope of their abilities, age or position: \"Children worry in their own way.\" Often with 自分なり, 子どもなり, 私なり. Attributive: なりの + noun. Neutral to approving.","formation":"Noun / Verb・い-adjective (plain form) + なりに / なりの + Noun","examples":[{"japanese":"子どもは子どもなりに、家族のことを心配している。","romaji":"Kodomo wa kodomo nari ni, kazoku no koto o shinpai shite iru.","german":"Children, too, worry about the family in their own way.","cloze":{"start":7,"answer":"なりに","quiz":{"level":"N2","japanese":"子どもは子どもなりに、家族のことを心配している。","german":"Children, too, worry about the family in their own way.","start":7,"answer":"なりに","acceptedAnswers":["なりに"],"distractors":[{"text":"にしては","reason":"にしては expects a deviation from the norm; \"children for children\" makes no comparison."},{"text":"ばかりに","reason":"ばかりに names the cause of a regrettable result and does not fit the repetition 子どもは子ども."},{"text":"をめぐって","reason":"をめぐって requires a point of dispute and does not fit 心配している."}]}}},{"japanese":"私なりに一生懸命考えた結果です。","romaji":"Watashi nari ni isshōkenmei kangaeta kekka desu.","german":"This is the result of my thinking it over as hard as I could, in my own way."},{"japanese":"安い店には安いなりの良さがある。","romaji":"Yasui mise ni wa yasui nari no yosa ga aru.","german":"Cheap shops have their own particular merits."}],"notes":"～にしては (\"considering that\") expresses surprise at a deviation; なりに, by contrast, expresses recognition within limits. ～らしく means \"as befits X\" (an ideal image), なりに \"as well as X can\". Do not confuse with ～なり (N1, \"as soon as\") or ～なり～なり (\"either ... or\").","related":["n3-ni-shite-wa","n1-nari"]},
{"id":"n2-ni-yotte-wa","pattern":"～によっては","level":"N2","category":"Partikel","meaning":"depending on ... (in some cases)","explanation":"によっては highlights that under certain circumstances a particular, often unexpected or unfavorable result can occur: \"Depending on the case, it may even be ...\" Typical: 場合によっては, 人によっては. Neutral to formal; popular in notices and business texts.","formation":"Noun + によっては","examples":[{"japanese":"天候によっては、試合が中止になることもあります。","romaji":"Tenkō ni yotte wa, shiai ga chūshi ni naru koto mo arimasu.","german":"Depending on the weather, the game may be canceled.","cloze":{"start":2,"answer":"によっては","quiz":{"level":"N2","japanese":"天候によっては、試合が中止になることもあります。","german":"Depending on the weather, the game may be canceled.","start":2,"answer":"によっては","acceptedAnswers":["によっては","次第では","によって"],"distractors":[{"text":"にとっては","reason":"にとっては requires an affected person or group; the weather does not judge anything."},{"text":"に対しては","reason":"に対しては marks a counterpart; the game is not canceled toward the weather."},{"text":"にしては","reason":"にしては expresses a deviation from expectations, not a condition."}]}}},{"japanese":"人によっては、この薬で眠くなる場合がある。","romaji":"Hito ni yotte wa, kono kusuri de nemuku naru baai ga aru.","german":"For some people, this medicine can cause drowsiness."},{"japanese":"場合によっては、契約を見直す必要がある。","romaji":"Baai ni yotte wa, keiyaku o minaosu hitsuyō ga aru.","german":"Depending on the circumstances, we may need to revise the contract."}],"notes":"Plain ～によって (N4, \"depending on\") describes general differences (国によって文化が違う); によっては singles out an individual case and often ends with ～こともある / ～場合がある. ～次第では is similar in meaning but stresses more strongly that the result depends on the factor.","related":["n4-ni-yotte","n3-shidai","n2-you-ni-yotte-wa"]},
{"id":"n2-to-wa-iu-mono-no","pattern":"～とはいうものの / ～というものの","level":"N2","category":"Satzstrukturen","meaning":"although ..., still; even though it is said that","explanation":"とはいうものの concedes a fact or statement and immediately qualifies it: \"It's true that ..., but in reality ...\". Also common at the start of a sentence as a conjunction. Written language and speeches; somewhat more formal than ～といっても.","formation":"Noun / Sentence (plain form) + とはいうものの / というものの; sentence-initial: とはいうものの、～","examples":[{"japanese":"春とはいうものの、まだ朝晩は寒い。","romaji":"Haru to wa iu mono no, mada asaban wa samui.","german":"It may be spring, but mornings and evenings are still cold.","cloze":{"start":1,"answer":"とはいうものの","quiz":{"level":"N2","japanese":"春とはいうものの、まだ朝晩は寒い。","german":"It may be spring, but mornings and evenings are still cold.","start":1,"answer":"とはいうものの","acceptedAnswers":["とはいうものの","というものの","とはいえ","といっても","とはいっても"],"distractors":[{"text":"というより","reason":"というより corrects a description (\"rather than\"); \"spring rather than cold\" makes no sense."},{"text":"からといって","reason":"After a noun, だからといって would be needed, and the main clause would have to deny a conclusion."},{"text":"とすれば","reason":"とすれば (\"assuming that\") is hypothetical and contradicts the actual cold."}]}}},{"japanese":"日本に10年住んでいるとはいうものの、敬語はいまだに難しい。","romaji":"Nihon ni jūnen sunde iru to wa iu mono no, keigo wa imada ni muzukashii.","german":"Although I've lived in Japan for ten years, I still find keigo difficult."},{"japanese":"ダイエットを始めた。とはいうものの、甘いものはやめられない。","romaji":"Daietto o hajimeta. To wa iu mono no, amai mono wa yamerarenai.","german":"I've started a diet. That said, I can't give up sweets."}],"notes":"Very close to ～とはいえ (N2); とはいえ is more concise and somewhat more literary. ～ものの (N3) comes directly after a sentence without と(は)いう and concedes a fact of one's own. ～といっても rather stresses that something is less than expected (\"a vacation – but only two days\").","related":["n2-to-wa-ie","n3-mono-no"]},
{"id":"n2-te-wa-naranai","pattern":"～てはならない","level":"N2","category":"Verben","meaning":"must not (formal)","explanation":"てはならない expresses a strict prohibition or a moral duty to refrain from something: \"This must not happen.\" More formal and more general than ～てはいけない – typical of laws, rules, speeches and editorials. In speech it sounds solemn or preachy.","formation":"Verb (て-form) + はならない / はなりません","examples":[{"japanese":"この悲劇を決して忘れてはならない。","romaji":"Kono higeki o kesshite wasurete wa naranai.","german":"We must never forget this tragedy.","cloze":{"start":10,"answer":"てはならない","quiz":{"level":"N2","japanese":"この悲劇を決して忘れてはならない。","german":"We must never forget this tragedy.","start":10,"answer":"てはならない","acceptedAnswers":["てはならない","てはいけない","てはなりません"],"distractors":[{"text":"てもかまわない","reason":"決して requires a negation; てもかまわない gives permission."},{"text":"てたまらない","reason":"てたまらない expresses an unbearable feeling and does not fit 決して."},{"text":"てばかりいる","reason":"決して requires a negation; てばかりいる describes a habit."}]}}},{"japanese":"会議の内容を外部に漏らしてはならない。","romaji":"Kaigi no naiyō o gaibu ni morashite wa naranai.","german":"The content of the meeting must not be leaked to outsiders."},{"japanese":"人の命を軽く扱ってはならない。","romaji":"Hito no inochi o karuku atsukatte wa naranai.","german":"Human life must not be treated lightly."}],"notes":"Easily confused with ～てならない (N3, without は): 心配でならない means \"I'm terribly worried\" and expresses an uncontrollable feeling. てはならない, by contrast, is a prohibition. In everyday life ～てはいけない is enough; てはならない sounds like a principle.","related":["n4-tewa-ikenai","n3-te-naranai"]},
{"id":"n2-neba-naranai","pattern":"～ねばならない / ～ねばならぬ","level":"N2","category":"Verben","meaning":"must (written language)","explanation":"ねばならない is the written, somewhat old-fashioned equivalent of ～なければならない: \"absolutely must\". It sounds determined and solemn; typical of speeches, editorials, literature and mottos. ねばならぬ sounds even more archaic. する becomes せねばならない.","formation":"Verb (ない-stem) + ねばならない / ねばならぬ (する → せねばならない)","examples":[{"japanese":"我々はこの問題に真剣に取り組まねばならない。","romaji":"Wareware wa kono mondai ni shinken ni torikumaneba naranai.","german":"We must tackle this problem seriously.","cloze":{"start":15,"answer":"ねばならない","quiz":{"level":"N2","japanese":"我々はこの問題に真剣に取り組まねばならない。","german":"We must tackle this problem seriously.","start":15,"answer":"ねばならない","acceptedAnswers":["ねばならない","ねばならぬ","なければならない","なくてはならない"],"distractors":[{"text":"ないならない","reason":"ならない cannot attach directly to the ない-form; なければ or ねば is needed."},{"text":"ねばなる","reason":"The obligation construction requires the negative form ならない."},{"text":"ずじまいだ","reason":"ずじまいだ regrets a missed chance (\"in the end, never\") and does not express an obligation."}]}}},{"japanese":"約束は守らねばならない。","romaji":"Yakusoku wa mamoraneba naranai.","german":"Promises must be kept."},{"japanese":"明日までにこの報告書を完成させねばならない。","romaji":"Ashita made ni kono hōkokusho o kansei saseneba naranai.","german":"I must finish this report by tomorrow."}],"notes":"Same meaning as ～なければならない (N5), but with a literary, determined ring – in casual conversation it sounds theatrical. ～ざるを得ない (N2), on the other hand, means \"cannot help but\", i.e. a reluctant necessity. Note: する becomes せねば, not しねば.","related":["nakereba-naranai","n3-zaruwoenai"]},
{"id":"n2-ttara","pattern":"～ったら","level":"N2","category":"Partikel","meaning":"(annoyed) as for ...; honestly, ...!","explanation":"ったら takes up a familiar person as the topic, someone the speaker is annoyed, puzzled or amused by: \"My mother, honestly – she's always ...\". Also used as an exclamation after a name (お母さんったら！). Very colloquial, typical among family and friends.","formation":"Noun (usually a person) + ったら","examples":[{"japanese":"うちの母ったら、何度言っても同じ話ばかりするの。","romaji":"Uchi no haha ttara, nando itte mo onaji hanashi bakari suru no.","german":"My mom, honestly – no matter how many times I tell her, she keeps telling the same stories.","cloze":{"start":4,"answer":"ったら","quiz":{"level":"N2","japanese":"うちの母ったら、何度言っても同じ話ばかりするの。","german":"My mom, honestly – no matter how many times I tell her, she keeps telling the same stories.","start":4,"answer":"ったら","acceptedAnswers":["ったら","ときたら","って"],"distractors":[{"text":"ばかりか","reason":"ばかりか requires an escalation with も in the following clause, not a topic."},{"text":"につき","reason":"につき is an official way of giving a reason (\"due to\") and does not fit a complaint about one's mother."},{"text":"をめぐって","reason":"をめぐって requires a dispute over something; the mother is the topic here, not the point of dispute."}]}}},{"japanese":"田中さんったら、また会議の時間を間違えたみたい。","romaji":"Tanaka-san ttara, mata kaigi no jikan o machigaeta mitai.","german":"That Tanaka, honestly – it looks like he got the meeting time wrong again."},{"japanese":"もう、お兄ちゃんったら！","romaji":"Mō, oniichan ttara!","german":"Geez, big brother, honestly!"}],"notes":"～ときたら (N1) is similar, but almost always sharply critical and somewhat cruder; ったら can also sound affectionately exasperated. Do not confuse with the conditional ～たら or with ～ったら for emphasis in requests (早くしてったら！ \"come on, hurry up!\").","related":["n1-to-kitara","n4-tte","n3-tteba","n1-ttara-nai"]},
{"id":"n2-toka-denbun","pattern":"～とか（伝聞）","level":"N2","category":"Satzstrukturen","meaning":"supposedly, from what I've heard","explanation":"Sentence-final とか passes on information one has heard, tentatively and in passing: \"He's getting married, I hear.\" The speaker keeps a slight distance from whether it is true. Colloquial, but also common in polite conversation (～とかで / ～とか聞きました).","formation":"Sentence (plain form) + とか / とかで / とか聞いた","examples":[{"japanese":"田中さん、来月結婚するとか。","romaji":"Tanaka-san, raigetsu kekkon suru to ka.","german":"I hear Mr. Tanaka is getting married next month.","cloze":{"start":11,"answer":"とか","quiz":{"level":"N2","japanese":"田中さん、来月結婚するとか。","german":"I hear Mr. Tanaka is getting married next month.","start":11,"answer":"とか","acceptedAnswers":["とか","そうだ","らしい","って","そうです"],"distractors":[{"text":"ことか","reason":"ことか is an exclamation of amazement (どんなに～ことか) and does not pass on news."},{"text":"ことに","reason":"ことに requires an emotion word before it and a clause after it."},{"text":"ばかりか","reason":"ばかりか requires a following clause with も and cannot end the sentence."}]}}},{"japanese":"部長は風邪で休むとかで、今日の会議は延期になった。","romaji":"Buchō wa kaze de yasumu to ka de, kyō no kaigi wa enki ni natta.","german":"Apparently the department manager is off with a cold, so today's meeting was postponed."},{"japanese":"今年の夏は例年より暑くなるとか。","romaji":"Kotoshi no natsu wa reinen yori atsuku naru to ka.","german":"They say this summer is going to be hotter than usual."}],"notes":"～そうだ (伝聞, N4) passes on hearsay matter-of-factly; とか sounds vaguer and more casual, almost like \"or something\". Do not confuse with listing ～とか～とか (N4, \"for example ... and ...\"). ～とのことだ is the formal, precise equivalent.","related":["n4-sou-hearsay","n2-to-no-koto-da"]},
{"id":"n2-tokoro-wo-miru-to","pattern":"～ところを見ると / ～ところからすると","level":"N2","category":"Satzstrukturen","meaning":"judging from the fact that ...; inferring from that","explanation":"ところを見ると infers a guess from a concrete observation: \"The way he's smiling, it must have gone well.\" The main clause usually ends with らしい, ようだ, に違いない or だろう. Neutral; spoken and written.","formation":"Verb / い-adjective (plain form) + ところを見ると / ところからすると; main clause with らしい・ようだ・に違いない","examples":[{"japanese":"嬉しそうな顔をしているところを見ると、試験に合格したらしい。","romaji":"Ureshisō na kao o shite iru tokoro o miru to, shiken ni gōkaku shita rashii.","german":"Judging by how happy he looks, he seems to have passed the exam.","cloze":{"start":11,"answer":"ところを見ると","quiz":{"level":"N2","japanese":"嬉しそうな顔をしているところを見ると、試験に合格したらしい。","german":"Judging by how happy he looks, he seems to have passed the exam.","start":11,"answer":"ところを見ると","acceptedAnswers":["ところを見ると","ところからすると","ところから見ると","ところをみると"],"distractors":[{"text":"ところに","reason":"ところに (\"just as\") requires an event that comes along, not a guess."},{"text":"ところで","reason":"In this meaning ところで follows the た-form (\"even if\") and does not fit らしい."},{"text":"くせに","reason":"くせに (\"even though\", reproachful) requires a contrast; being happy and passing do not contradict each other."}]}}},{"japanese":"電気が消えているところを見ると、もう誰もいないようだ。","romaji":"Denki ga kiete iru tokoro o miru to, mō dare mo inai yō da.","german":"Since the lights are off, it looks like no one is here anymore."},{"japanese":"何も言わないところからすると、彼は反対なのだろう。","romaji":"Nani mo iwanai tokoro kara suru to, kare wa hantai na no darō.","german":"Judging from the fact that he says nothing, he's probably against it."}],"notes":"～からすると (N2) names a general basis for a judgment (話し方からすると); ところを見ると requires a concretely observed action or situation. Do not confuse with ～ところを (N1, apologetic: お忙しいところを) or ～ところに (\"just as\").","related":["n1-kara-suru-to","n2-tokoro-ni"]},
{"id":"n2-mo-ba-mo","pattern":"～も～ば～も","level":"N2","category":"Satzstrukturen","meaning":"both ... and; sometimes ..., sometimes","explanation":"AもVばBもV lines up two facts of the same kind, usually to stress versatility or contrasts: \"He sings, and he dances too.\" Common in the fixed form ～もあれば～もある (\"there are ... and there are also ...\"). Neutral to slightly elevated; in conversation and in texts.","formation":"Noun A + も + Verb/Adjective (ば-form) + Noun B + も + Verb/Adjective; fixed: ～もあれば～もある","examples":[{"japanese":"人生には、いい時もあれば悪い時もある。","romaji":"Jinsei ni wa, ii toki mo areba warui toki mo aru.","german":"In life there are good times and bad times.","cloze":{"start":9,"answer":"あれば","quiz":{"level":"N2","japanese":"人生には、いい時もあれば悪い時もある。","german":"In life there are good times and bad times.","start":9,"answer":"あれば","acceptedAnswers":["あれば","あるし","あり"],"distractors":[{"text":"あるどころか","reason":"どころか reverses an expectation; here good and bad times stand side by side as equals."},{"text":"あるくせに","reason":"くせに is reproachful (\"even though\") and does not fit a neutral piece of life wisdom."},{"text":"あるあまり","reason":"あまり (\"out of sheer\") requires a feeling or an excess as the cause."}]}}},{"japanese":"彼は歌も歌えば、ダンスもする。","romaji":"Kare wa uta mo utaeba, dansu mo suru.","german":"He sings, and he dances too."},{"japanese":"この店は値段も安ければ、味もいい。","romaji":"Kono mise wa nedan mo yasukereba, aji mo ii.","german":"At this place the prices are low, and the food is good too."}],"notes":"Unlike the conditional ～ば, ば here expresses no condition but links two parallel statements. ～も～し～も (N4) means the same but is more colloquial. ～も～なら～も (N2) looks similar but is a reproach aimed at both sides.","related":["n4-shi","n2-mo-nara-mo"]},
{"id":"n2-wa-betsu-to-shite","pattern":"～は別として / ～は別にして","level":"N2","category":"Partikel","meaning":"apart from, except for","explanation":"は別として takes a point or case out of the following statement: \"X aside, ... holds true\". Unlike with はともかく, X is not dismissed as unimportant but treated as a special case. Neutral to formal; often with question clauses (～かどうかは別として).","formation":"Noun + は別として / は別にして; question clause + か(どうか) + は別として","examples":[{"japanese":"一部の専門家は別として、この問題を知る人はほとんどいない。","romaji":"Ichibu no senmonka wa betsu to shite, kono mondai o shiru hito wa hotondo inai.","german":"Apart from a few specialists, hardly anyone knows about this problem.","cloze":{"start":6,"answer":"は別として","quiz":{"level":"N2","japanese":"一部の専門家は別として、この問題を知る人はほとんどいない。","german":"Apart from a few specialists, hardly anyone knows about this problem.","start":6,"answer":"は別として","acceptedAnswers":["は別として","は別にして","を除いて","を除けば","以外"],"distractors":[{"text":"はもちろん","reason":"はもちろん includes the specialists (\"of course, and also\") and contradicts ほとんどいない."},{"text":"に限って","reason":"に限って singles out the specialists as \"of all people\" and makes no sense with the rest of the sentence."},{"text":"をはじめ","reason":"をはじめ names the first example of a group that then does something together, not an exception."}]}}},{"japanese":"好きか嫌いかは別として、この仕事はやらなければならない。","romaji":"Suki ka kirai ka wa betsu to shite, kono shigoto wa yaranakereba naranai.","german":"Whether you like it or not, this job has to be done."},{"japanese":"値段は別にして、デザインは申し分ない。","romaji":"Nedan wa betsu ni shite, dezain wa mōshibun nai.","german":"Price aside, the design is flawless."}],"notes":"Close to ～はともかく: はともかく puts X aside as secondary, は別として objectively sets X apart as a special case. ～を除いて (N2) excludes an element from a set even more formally and typically appears with universal statements (全員, 毎日).","related":["n2-wa-tomokaku","n2-wo-nozoite"]},
{"id":"n2-ni-kakatte-iru","pattern":"～にかかっている","level":"N2","category":"Satzstrukturen","meaning":"to depend on, to rest on","explanation":"にかかっている expresses that a result depends decisively on one factor or person: \"Success depends on your effort.\" It stresses the responsibility and weight of that factor. Neutral; common in speeches, sports and business, often with ～かどうかは.","formation":"Noun + にかかっている; question clause + か(どうか) + にかかっている","examples":[{"japanese":"試合に勝てるかどうかは、選手たちの努力にかかっている。","romaji":"Shiai ni kateru ka dō ka wa, senshutachi no doryoku ni kakatte iru.","german":"Whether we can win the match depends on the players' efforts.","cloze":{"start":19,"answer":"にかかっている","quiz":{"level":"N2","japanese":"試合に勝てるかどうかは、選手たちの努力にかかっている。","german":"Whether we can win the match depends on the players' efforts.","start":19,"answer":"にかかっている","acceptedAnswers":["にかかっている","次第だ","次第である","によって決まる"],"distractors":[{"text":"に過ぎない","reason":"に過ぎない (\"merely\") downplays something and does not name a dependence."},{"text":"に違いない","reason":"に違いない expresses a guess; \"whether we win is surely the players' effort\" makes no sense."},{"text":"にわたる","reason":"にわたる requires a span of time or space."}]}}},{"japanese":"会社の将来は、この新製品が売れるかどうかにかかっている。","romaji":"Kaisha no shōrai wa, kono shin-seihin ga ureru ka dō ka ni kakatte iru.","german":"The company's future depends on whether this new product sells."},{"japanese":"合格できるかどうかは、これからの一か月にかかっている。","romaji":"Gōkaku dekiru ka dō ka wa, kore kara no ikkagetsu ni kakatte iru.","german":"Whether you pass depends on the coming month."}],"notes":"～次第だ means the same but is more concise (努力次第だ). ～によって (N4) neutrally describes a dependence or variation (国によって違う); にかかっている stresses that everything hinges on this one factor. Do not confuse with ～にかかわる (N2, \"to concern, to be at stake\": 命にかかわる).","related":["n3-shidai","n2-ni-kakawaru"]},
{"id":"n2-hodo-no-koto-dewa-nai","pattern":"～ほどのことではない / ～ほどのことはない","level":"N2","category":"Satzstrukturen","meaning":"not serious enough to ...; not worth making a fuss about","explanation":"ほどのことではない states that something is not serious or important enough to justify a certain (exaggerated) reaction: \"It's not so bad that you'd need to see a doctor.\" Reassuring or downplaying; spoken and written.","formation":"Verb (dictionary form) + ほどのことではない / ほどのことはない; Noun + ほどのことではない","examples":[{"japanese":"ちょっとした風邪だから、病院に行くほどのことではない。","romaji":"Chotto shita kaze da kara, byōin ni iku hodo no koto de wa nai.","german":"It's just a slight cold – not bad enough that I need to go to the hospital.","cloze":{"start":17,"answer":"ほどのことではない","quiz":{"level":"N2","japanese":"ちょっとした風邪だから、病院に行くほどのことではない。","german":"It's just a slight cold – not bad enough that I need to go to the hospital.","start":17,"answer":"ほどのことではない","acceptedAnswers":["ほどのことではない","ほどのことはない","ほどではない","ことはない"],"distractors":[{"text":"ことになる","reason":"ことになる (\"it ends up that\") contradicts ちょっとした風邪だから."},{"text":"しかない","reason":"しかない (\"there's no choice but\") contradicts the slight cold."},{"text":"べきだ","reason":"べきだ calls for a hospital visit and does not fit the reason \"only a slight cold\"."}]}}},{"japanese":"心配するほどのことはないよ。すぐに治るから。","romaji":"Shinpai suru hodo no koto wa nai yo. Sugu ni naoru kara.","german":"It's nothing to worry about. It'll heal quickly."},{"japanese":"わざわざ謝りに来るほどのことではありませんよ。","romaji":"Wazawaza ayamari ni kuru hodo no koto de wa arimasen yo.","german":"There's really no need to come all the way here to apologize."}],"notes":"～ことはない (N2) says directly \"there's no need\"; ほどのことではない justifies this with the minor importance of the matter. ～までもない (N1), by contrast, means \"it's unnecessary because it's obvious anyway\" (言うまでもない), not \"too insignificant\".","related":["n2-koto-wa-nai","n1-made-mo-nai"]},
{"id":"n2-te-demo","pattern":"～てでも","level":"N2","category":"Satzstrukturen","meaning":"even if one has to ...; at any cost","explanation":"てでも expresses strong determination: to reach a goal, one is ready to use even an extreme means – \"if need be, even ...\". The main clause usually contains a wish or intention (～たい, ～つもりだ, ～なければならない). Spoken and written.","formation":"Verb (て-form) + でも + wish / intention / obligation","examples":[{"japanese":"借金をしてでも、この店を続けたい。","romaji":"Shakkin o shite demo, kono mise o tsuzuketai.","german":"I want to keep this shop going, even if I have to borrow money.","cloze":{"start":4,"answer":"てでも","quiz":{"level":"N2","japanese":"借金をしてでも、この店を続けたい。","german":"I want to keep this shop going, even if I have to borrow money.","start":4,"answer":"てでも","acceptedAnswers":["てでも"],"distractors":[{"text":"たきり","reason":"たきり (\"and since then no longer\") makes no sense with the wish to keep going."},{"text":"たあげく","reason":"あげく describes a bad result that has already occurred and cannot end with a wish (～たい)."},{"text":"たとたん","reason":"とたん requires an event that happened immediately, not a wish in the main clause."}]}}},{"japanese":"どんなことをしてでも、家族を守るつもりだ。","romaji":"Donna koto o shite demo, kazoku o mamoru tsumori da.","german":"I intend to protect my family, whatever it takes."},{"japanese":"徹夜してでも、明日までにこの資料を仕上げなければならない。","romaji":"Tetsuya shite demo, ashita made ni kono shiryō o shiagenakereba naranai.","german":"Even if I have to stay up all night, I've got to finish these documents by tomorrow."}],"notes":"Counterpart of ～てまで: てまで often appears with criticism or negation (\"I wouldn't go that far\"), てでも with a positive intention (\"I'd even ... for that\"). Do not confuse with ～ても (N4, \"even if\"), which only concedes without expressing determination.","related":["n2-te-made","temo"]},
{"id":"n2-you-ni-yotte-wa","pattern":"～ようによっては","level":"N2","category":"Satzstrukturen","meaning":"depending on how one ...; from a certain angle","explanation":"ようによっては expresses that a matter can look completely different depending on how one views or approaches it: \"Depending on how you look at it, this is actually an opportunity.\" Mostly with 考える, 見る, やる; the main clause often contains a surprising view.","formation":"Verb (ます-stem) + ようによっては","examples":[{"japanese":"考えようによっては、この失敗もいい経験だ。","romaji":"Kangaeyō ni yotte wa, kono shippai mo ii keiken da.","german":"Depending on how you look at it, even this failure is a good experience.","cloze":{"start":2,"answer":"ようによっては","quiz":{"level":"N2","japanese":"考えようによっては、この失敗もいい経験だ。","german":"Depending on how you look at it, even this failure is a good experience.","start":2,"answer":"ようによっては","acceptedAnswers":["ようによっては","方によっては"],"distractors":[{"text":"ようがなく","reason":"ようがなく (\"with no way to\") contradicts the positive reinterpretation in the main clause."},{"text":"ようにも","reason":"ようにも requires the volitional form and a negation (考えようにも考えられない)."},{"text":"ようとして","reason":"ようとして (\"while trying to\") does not fit an evaluation like いい経験だ."}]}}},{"japanese":"やりようによっては、もっと早く終わらせることができる。","romaji":"Yariyō ni yotte wa, motto hayaku owaraseru koto ga dekiru.","german":"Depending on how you go about it, you can finish it faster."},{"japanese":"見ようによっては、彼の発言は失礼とも取れる。","romaji":"Miyō ni yotte wa, kare no hatsugen wa shitsurei to mo toreru.","german":"Depending on how you see it, his remark could also be taken as rude."}],"notes":"The noun ～よう (ます-stem + よう) means \"way, manner\", as in ～ようがない (\"there's no way to\"). ～によっては (N2) follows ordinary nouns (場合によっては); ようによっては refers specifically to the way of doing or thinking. Same meaning: 考え方によっては.","related":["n2-ni-yotte-wa","n3-you-ga-nai"]},
{"id":"n2-wa-iu-made-mo-nai","pattern":"～は言うまでもない / ～は言うまでもなく","level":"N2","category":"Satzstrukturen","meaning":"it goes without saying; not to mention","explanation":"は言うまでもない states that something is so obvious that it really wouldn't need to be mentioned. As は言うまでもなく it links something self-evident with a further example: \"X of course, and also Y\". Formal; typical in speeches and essays.","formation":"Noun + は言うまでもない / は言うまでもなく; Sentence + の / こと + は言うまでもない","examples":[{"japanese":"健康が大切なのは言うまでもない。","romaji":"Kenkō ga taisetsu na no wa iu made mo nai.","german":"It goes without saying that health is important.","cloze":{"start":7,"answer":"は言うまでもない","quiz":{"level":"N2","japanese":"健康が大切なのは言うまでもない。","german":"It goes without saying that health is important.","start":7,"answer":"は言うまでもない","acceptedAnswers":["は言うまでもない","はいうまでもない","は言うまでもありません","はもちろんだ"],"distractors":[{"text":"はともかく","reason":"はともかく requires a following main clause and cannot end the sentence."},{"text":"は言うまでもなく","reason":"The connective form requires a continuation with a further example."},{"text":"はずがない","reason":"はずがない cannot follow the topic marker は and would negate the statement."}]}}},{"japanese":"彼は英語は言うまでもなく、フランス語も話せる。","romaji":"Kare wa Eigo wa iu made mo naku, Furansugo mo hanaseru.","german":"He can speak French, not to mention English."},{"japanese":"地震の際には、火の始末が重要であることは言うまでもない。","romaji":"Jishin no sai ni wa, hi no shimatsu ga jūyō de aru koto wa iu made mo nai.","german":"It goes without saying that in an earthquake it is important to make sure any fires are put out."}],"notes":"The general form ～までもない (N1) means \"there's no need to ...\" and occurs with many verbs (説明するまでもない); は言うまでもない is the fixed, very common expression derived from it. ～はもちろん (N2) means the same as は言うまでもなく but is less formal.","related":["n1-made-mo-nai","n2-wa-mochiron"]},
{"id":"n2-to-iu-ka-to-iu-ka","pattern":"～というか～というか","level":"N2","category":"Satzstrukturen","meaning":"... or ..., or rather; how shall I put it","explanation":"というか～というか lines up two spontaneous descriptions because neither alone seems accurate enough: \"It was – bold, or maybe reckless.\" Expresses hesitation or amazement; the sentence often ends with a summarizing judgment. Colloquial.","formation":"Noun / な-adjective (stem) / Verb・い-adjective (plain form) + というか + same + というか","examples":[{"japanese":"彼の行動は大胆というか無謀というか、とにかく驚いた。","romaji":"Kare no kōdō wa daitan to iu ka mubō to iu ka, tonikaku odoroita.","german":"His behavior was bold, or maybe reckless – anyway, I was stunned.","cloze":{"start":7,"answer":"というか","quiz":{"level":"N2","japanese":"彼の行動は大胆というか無謀というか、とにかく驚いた。","german":"His behavior was bold, or maybe reckless – anyway, I was stunned.","start":7,"answer":"というか","acceptedAnswers":["というか","っていうか"],"distractors":[{"text":"にしろ","reason":"にしろ～にしろ would have to appear in both parts; mixed with というか it is ungrammatical."},{"text":"だけに","reason":"After a な-adjective, だけに would need な (大胆なだけに), and it gives a reason, not a description."},{"text":"からといって","reason":"After a な-adjective, だからといって would be needed, and it requires a negated conclusion."}]}}},{"japanese":"あの店の料理は、懐かしいというか素朴というか、何だかほっとする味だ。","romaji":"Ano mise no ryōri wa, natsukashii to iu ka soboku to iu ka, nandaka hotto suru aji da.","german":"The food at that place is nostalgic, or maybe simple – somehow it's a comforting taste."},{"japanese":"驚いたというか、あきれたというか、言葉が出なかった。","romaji":"Odoroita to iu ka, akireta to iu ka, kotoba ga denakatta.","german":"I was surprised, or maybe appalled – either way, I was at a loss for words."}],"notes":"～やら～やら (N2) lists several things or feelings side by side (\"what with ... and ...\"); というか～というか searches for the right description of a single thing. A single ～というか makes a vague correction (\"or rather\"), similar to ～というより. More formal: ～といおうか～といおうか.","related":["n2-yara-yara"]},
{"id":"n1-kara-shite","pattern":"～からして","level":"N1","category":"Partikel","meaning":"judging just from ..., starting with","explanation":"からして expresses that even the first or most obvious example is enough to make a judgment. Often has negative connotations. It stresses that the very first sign already says something about the whole.","formation":"Noun + からして","examples":[{"japanese":"彼は態度からして失礼だ。","cloze":{"start":4,"answer":"からして","quiz":{"level":"N1","japanese":"彼は態度からして失礼だ。","german":"Starting with his attitude, he's rude.","start":4,"answer":"からして","acceptedAnswers":["からして"],"distractors":[{"text":"からする","reason":"The dictionary form does not connect with 失礼だ here."},{"text":"からします","reason":"The finite form ends the sentence."},{"text":"からした","reason":"The attributive past form does not fit before 失礼だ here."}]}},"romaji":"Kare wa taido kara shite shitsurei da.","german":"Starting with his attitude, he's rude."},{"japanese":"この店は外観からして高そうだ。","cloze":{"start":6,"answer":"からして"},"romaji":"Kono mise wa gaikan kara shite takasō da.","german":"Just from the outside, this shop looks expensive."}],"notes":"Do not confuse with からすると (standpoint). からして stresses the first sign.","related":["n1-kara-suru-to"]},
{"id":"n1-kara-suru-to","pattern":"～からすると/～からすれば","level":"N2","category":"Partikel","meaning":"from the standpoint of ..., judging from","explanation":"からすると/からすれば expresses that something is judged from a particular perspective or on the basis of certain information. It is used to state a conclusion or opinion based on a point of view.","formation":"Noun + からすると/からすれば","examples":[{"japanese":"彼の様子からすると、何か問題があるようだ。","cloze":{"start":4,"answer":"からすると","quiz":{"level":"N2","japanese":"彼の様子からすると、何か問題があるようだ。","german":"Judging from the way he's acting, there seems to be some kind of problem.","start":4,"answer":"からすると","acceptedAnswers":["からすると","からすれば","から見ると"],"distractors":[{"text":"からするを","reason":"を does not form a link for drawing a conclusion here."},{"text":"からするます","reason":"ます requires the stem し."},{"text":"からすればな","reason":"な cannot be attached to the conditional."}]}},"romaji":"Kare no yōsu kara suru to, nanika mondai ga aru yō da.","german":"Judging from the way he's acting, there seems to be some kind of problem."},{"japanese":"経験からすれば、この方法が一番効果的だ。","cloze":{"start":2,"answer":"からすれば"},"romaji":"Keiken kara sureba, kono hōhō ga ichiban kōkateki da.","german":"Based on experience, this method is the most effective."},{"japanese":"私からすると、この計画は無理がある。","romaji":"Watashi kara suru to, kono keikaku wa muri ga aru.","german":"From my point of view, this plan is unrealistic."},{"japanese":"外見からすると、彼は30歳くらいだろう。","romaji":"Gaiken kara suru to, kare wa sanjussai kurai darō.","german":"Judging by his appearance, he's probably around 30."}],"notes":"Similar to から見ると, but more formal and often used for conclusions.","related":["n1-kara-shite","n2-kara-miru-to","n2-ni-shitara","n2-kara-iu-to","n2-tokoro-wo-miru-to"],"legacyIds":["n2-kara-suru-to"]},
{"id":"n1-tari-tomo-nai","pattern":"～たりとも～ない","level":"N1","category":"Partikel","meaning":"not even a single","explanation":"たりとも～ない is a very emphatic negation stressing that not even the smallest amount or number is acceptable. It is often used with words such as 一人、一つ、一日 and has a formal, literary tone.","formation":"Counter + たりとも + negation","examples":[{"japanese":"一日たりとも休むことはできない。","romaji":"Ichinichi tari tomo yasumu koto wa dekinai.","german":"I can't take even a single day off.","cloze":{"start":2,"answer":"たりとも","quiz":{"level":"N1","japanese":"一日たりとも休むことはできない。","german":"I can't take even a single day off.","start":2,"answer":"たりとも","acceptedAnswers":["たりとも"],"distractors":[{"text":"たりを","reason":"を does not express emphasis on a minimal amount here."},{"text":"たりな","reason":"な does not connect with 休むことはできない here."},{"text":"たりです","reason":"The copula does not form a connection here."}]}}},{"japanese":"一人たりとも見逃すわけにはいかない。","romaji":"Hitori tari tomo minogasu wake ni wa ikanai.","german":"We can't let even a single person slip past us."}],"notes":"Very formal and emphatic. Used mainly in written or formal language.","related":["n1-desura","n4-sae","n1-nari-tomo"]},
{"id":"n1-de-are","pattern":"～であれ","level":"N1","category":"Partikel","meaning":"even if, whether","explanation":"であれ expresses that something holds regardless of the circumstances or conditions. It can be used on its own or in the form であれ～であれ. This structure has a formal, written character.","formation":"Noun + であれ / interrogative + であれ","examples":[{"japanese":"誰であれ、ルールを守らなければならない。","cloze":{"start":1,"answer":"であれ","quiz":{"level":"N1","japanese":"誰であれ、ルールを守らなければならない。","german":"Whoever it may be, they must follow the rules.","start":1,"answer":"であれ","acceptedAnswers":["であれ","でも"],"distractors":[{"text":"であるを","reason":"を cannot attach to である here."},{"text":"であれな","reason":"な cannot attach to the concessive form here."},{"text":"でありまする","reason":"る cannot be attached to ます."}]}},"romaji":"Dare de are, rūru o mamora nakereba naranai.","german":"Whoever it may be, they must follow the rules."},{"japanese":"どんな理由であれ、暴力は許されない。","cloze":{"start":5,"answer":"であれ"},"romaji":"Donna riyū de are, bōryoku wa yurusarenai.","german":"Whatever the reason, violence cannot be tolerated."}],"notes":"Often used with interrogatives such as 誰、何、どんな. Very formal.","related":["n1-de-are-de-are","n3-to-shitemo"]},
{"id":"n1-de-are-de-are","pattern":"～であれ～であれ","level":"N1","category":"Partikel","meaning":"whether ... or ..., no matter whether","explanation":"であれ～であれ expresses that something holds regardless of which of several alternatives applies. It stresses that the result or consequence is the same in all cases. This form is very formal and is used mainly in written language.","formation":"Noun + であれ + Noun + であれ","examples":[{"japanese":"昼であれ夜であれ、いつでも連絡してください。","romaji":"Hiru de are yoru de are, itsu demo renraku shite kudasai.","german":"Day or night, please contact me anytime.","cloze":{"start":1,"answer":"であれ","quiz":{"level":"N1","japanese":"昼であれ夜であれ、いつでも連絡してください。","german":"Day or night, please contact me anytime.","start":1,"answer":"であれ","acceptedAnswers":["であれ"],"distractors":[{"text":"であるを","reason":"を cannot attach to である here."},{"text":"であれな","reason":"な cannot attach to the concessive form here."},{"text":"でありまする","reason":"る cannot be attached to ます."}]}}},{"japanese":"男性であれ女性であれ、平等に扱うべきだ。","romaji":"Dansei de are josei de are, byōdō ni atsukau beki da.","german":"Whether male or female, people should be treated equally."}],"notes":"More formal than ～でも～でも. Preferred in official contexts.","related":["n1-de-are","n3-toshite-mo"]},
{"id":"n1-desura","pattern":"～ですら","level":"N1","category":"Partikel","meaning":"even","explanation":"ですら is an emphatic particle expressing that even something unexpected or extreme is the case. It is stronger than でさえ and is used to express surprise or emphasis. It often introduces an extreme example.","formation":"Noun + ですら","examples":[{"japanese":"子供ですらできることが、彼にはできない。","cloze":{"start":2,"answer":"ですら","quiz":{"level":"N1","japanese":"子供ですらできることが、彼にはできない。","german":"He can't do what even a child can do.","start":2,"answer":"ですら","acceptedAnswers":["ですら","でも","さえ"],"distractors":[{"text":"ですらな","reason":"な does not connect to できること here."},{"text":"ですらを","reason":"を cannot attach to the emphasis here."},{"text":"ですらます","reason":"ます cannot be attached to すら."}]}},"romaji":"Kodomo desura dekiru koto ga, kare ni wa dekinai.","german":"He can't do what even a child can do."},{"japanese":"親ですら彼の行動を理解できなかった。","cloze":{"start":1,"answer":"ですら"},"romaji":"Oya desura kare no kōdō o rikai dekinakatta.","german":"Even his parents couldn't understand his behavior."}],"notes":"More formal and emphatic than でさえ. Not common in colloquial speech.","related":["n4-sae","n1-tari-tomo-nai"]},
{"id":"n1-to-mo-naru-to","pattern":"～ともなると/～ともなれば","level":"N1","category":"Partikel","meaning":"when it comes to; once one reaches the point of","explanation":"ともなると/ともなれば expresses that at a certain high level, status or stage, special circumstances or expectations apply. It stresses that the situation or status is not ordinary and therefore has special consequences.","formation":"Noun + ともなると/ともなれば","examples":[{"japanese":"社長ともなると、責任も重くなる。","cloze":{"start":2,"answer":"ともなると","quiz":{"level":"N1","japanese":"社長ともなると、責任も重くなる。","german":"Once you're a company president, your responsibilities get heavier too.","start":2,"answer":"ともなると","acceptedAnswers":["ともなると","ともなれば"],"distractors":[{"text":"ともなるを","reason":"を does not form a condition here."},{"text":"ともなるます","reason":"ます requires the stem なり."},{"text":"ともなればな","reason":"な cannot be attached to the conditional."}]}},"romaji":"Shachō to mo naru to, sekinin mo omoku naru.","german":"Once you're a company president, your responsibilities get heavier too."},{"japanese":"プロともなれば、毎日の練習が欠かせない。","cloze":{"start":2,"answer":"ともなれば"},"romaji":"Puro to mo nareba, mainichi no renshū ga kakasenai.","german":"When you're a professional, daily practice is essential."}],"notes":"Stresses a special status or level. Often interchangeable with になると, but ともなると is more emphatic.","related":["n1-to-areba"]},
{"id":"n1-nara-de-wa","pattern":"～ならでは","level":"N1","category":"Partikel","meaning":"only possible with, unique to","explanation":"ならでは expresses that something is characteristic of, or only possible for, a particular person, place or thing. It stresses uniqueness or distinctiveness. This construction is often used to highlight positive, unique qualities.","formation":"Noun + ならでは (+ の + Noun)","examples":[{"japanese":"これは京都ならではの料理だ。","cloze":{"start":5,"answer":"ならでは","quiz":{"level":"N1","japanese":"これは京都ならではの料理だ。","german":"This is a dish you can only find in Kyoto.","start":5,"answer":"ならでは","acceptedAnswers":["ならでは"],"distractors":[{"text":"ならではな","reason":"The following の connection does not allow an extra な."},{"text":"ならではを","reason":"を does not fit before の料理 here."},{"text":"ならではます","reason":"ます cannot be attached to ならでは."}]}},"romaji":"Kore wa Kyōto nara de wa no ryōri da.","german":"This is a dish you can only find in Kyoto."},{"japanese":"彼ならではのアイデアだ。","cloze":{"start":1,"answer":"ならでは"},"romaji":"Kare nara de wa no aidea da.","german":"That's an idea only he could come up with."}],"notes":"Positive connotation. Stresses uniqueness and special qualities.","related":["n2-ni-kagitte","n1-wo-oite-hoka-ni-nai"]},
{"id":"n1-ni-atte","pattern":"～にあって","level":"N1","category":"Partikel","meaning":"in the situation of","explanation":"にあって expresses that something happens in a special or extraordinary situation. It is used to highlight the context or circumstances in which something takes place. This construction is very formal and is used mainly in written language.","formation":"Noun + にあって","examples":[{"japanese":"困難な状況にあっても、希望を失わない。","cloze":{"start":5,"answer":"にあって","quiz":{"level":"N1","japanese":"困難な状況にあっても、希望を失わない。","german":"Even in difficult circumstances, one does not lose hope.","start":5,"answer":"にあって","acceptedAnswers":["にあって","であって"],"distractors":[{"text":"にあった","reason":"Before も, this concession uses the て-form."},{"text":"にある","reason":"Before も, the て-form is used here."},{"text":"にあります","reason":"The finite form does not fit before も here."}]}},"romaji":"Konnan na jōkyō ni atte mo, kibō o ushinawanai.","german":"Even in difficult circumstances, one does not lose hope."},{"japanese":"このような危機にあって、団結が必要だ。","cloze":{"start":7,"answer":"にあって"},"romaji":"Kono yō na kiki ni atte, danketsu ga hitsuyō da.","german":"In a crisis like this, unity is essential."}],"notes":"Very formal. Used for extraordinary or special situations.","related":["n3-ni-oite","n1-to-atte"]},
{"id":"n1-ni-shite","pattern":"～にして","level":"N1","category":"Partikel","meaning":"only at/with; and at the same time","explanation":"にして has several meanings: 1) It expresses that something is only reached at a certain point or level. 2) It can also mean that someone or something has two qualities or roles at the same time. This construction is very formal and literary.","formation":"Noun + にして","examples":[{"japanese":"彼は作家にして画家でもある。","cloze":{"start":4,"answer":"にして","quiz":{"level":"N1","japanese":"彼は作家にして画家でもある。","german":"He is a writer and at the same time also a painter.","start":4,"answer":"にして","acceptedAnswers":["にして","であり"],"distractors":[{"text":"にする","reason":"The dictionary form does not connect with 画家でもある here."},{"text":"にします","reason":"The finite form does not form a listing connection here."},{"text":"にした","reason":"The attributive past form does not form a listing connection here."}]}},"romaji":"Kare wa sakka ni shite gaka demo aru.","german":"He is a writer and at the same time also a painter."},{"japanese":"50歳にして初めて成功を収めた。","cloze":{"start":3,"answer":"にして"},"romaji":"Gojussai ni shite hajimete seikō o osameta.","german":"Only at the age of 50 did he achieve success for the first time."}],"notes":"Very formal and literary. Has different nuances depending on context.","related":["n1-de-are","n1-to-mo-naru-to"]},
{"id":"n1-ni-sokushite","pattern":"～にそくして/～に即して","level":"N1","category":"Partikel","meaning":"in accordance with, in line with","explanation":"にそくして/に即して expresses that something is done in accordance with certain rules, principles or reality. It stresses that one strictly follows or adheres to something. This expression is formal and is often used in business or academic contexts.","formation":"Noun + にそくして/に即して","examples":[{"japanese":"現実に即して計画を立てる必要がある。","cloze":{"start":2,"answer":"に即して","quiz":{"level":"N1","japanese":"現実に即して計画を立てる必要がある。","german":"We need to make plans that are grounded in reality.","start":2,"answer":"に即して","acceptedAnswers":["に即して","に基づいて"],"distractors":[{"text":"を即して","reason":"The standard of reference requires に."},{"text":"に即した","reason":"The attributive form does not fit before 計画を立てる here."},{"text":"に即します","reason":"The finite form does not form a connection here."}]}},"romaji":"Genjitsu ni sokushite keikaku o tateru hitsuyō ga aru.","german":"We need to make plans that are grounded in reality."},{"japanese":"規則に即して処理してください。","cloze":{"start":2,"answer":"に即して"},"romaji":"Kisoku ni sokushite shori shite kudasai.","german":"Please handle this in accordance with the regulations."}],"notes":"Formal. Stresses strict conformity with rules or reality.","related":["n3-ni-shitagatte","n2-wo-motte"]},
{"id":"n1-ni-taeru","pattern":"～にたえる/～にたえない","level":"N1","category":"Partikel","meaning":"to be worthy of / unbearable","explanation":"にたえる has two opposite meanings: 1) In the positive form it means that something is worth it (鑑賞に堪える = worth viewing). 2) In the negative form (にたえない) it means that something is unbearable or that one cannot bear something. The context determines the meaning.","formation":"Noun + にたえる/にたえない","examples":[{"japanese":"この作品は鑑賞に堪える名作だ。","romaji":"Kono sakuhin wa kanshō ni taeru meisaku da.","german":"This work is a masterpiece worthy of appreciation.","cloze":{"start":7,"answer":"に堪える","quiz":{"level":"N1","japanese":"この作品は鑑賞に堪える名作だ。","german":"This work is a masterpiece worthy of appreciation.","start":7,"answer":"に堪える","acceptedAnswers":["に堪える","に値する"],"distractors":[{"text":"に堪え","reason":"The stem form cannot modify 名作 attributively here."},{"text":"に堪えるます","reason":"ます is not attached to the dictionary form."},{"text":"に堪えない","reason":"This denies that the work is worth viewing."}]}}},{"japanese":"この痛みは耐えるに堪えない。","romaji":"Kono itami wa taeru ni taenai.","german":"This pain is unbearable."}],"notes":"Very formal. The meaning depends heavily on context (positive vs. negative).","related":["n2-ni-ataru","n1-ni-taru"]},
{"id":"n1-ni-hikikae","pattern":"～にひきかえ","level":"N1","category":"Partikel","meaning":"in contrast to","explanation":"にひきかえ is used to highlight a strong contrast between two things. It expresses that, in contrast to one thing, another is very different. It often expresses a negative judgment or disappointment about the contrast.","formation":"Noun/Sentence + にひきかえ","examples":[{"japanese":"兄は真面目なのにひきかえ、弟は怠け者だ。","cloze":{"start":7,"answer":"にひきかえ","quiz":{"level":"N1","japanese":"兄は真面目なのにひきかえ、弟は怠け者だ。","german":"In contrast to the older brother, who is conscientious, the younger brother is lazy.","start":7,"answer":"にひきかえ","acceptedAnswers":["にひきかえ","に対して"],"distractors":[{"text":"をひきかえ","reason":"The point of comparison requires に here."},{"text":"にひきかえるます","reason":"ます is not attached to the dictionary form."},{"text":"にひきかえな","reason":"な does not link the contrast here."}]}},"romaji":"Ani wa majime na no ni hikikae, otōto wa namakemono da.","german":"In contrast to the older brother, who is conscientious, the younger brother is lazy."},{"japanese":"去年の好成績にひきかえ、今年は不振だ。","cloze":{"start":6,"answer":"にひきかえ"},"romaji":"Kyonen no kōseiseki ni hikikae, kotoshi wa fushin da.","german":"In contrast to last year's good results, this year has been sluggish."}],"notes":"Often has a negative connotation. Stresses an undesirable contrast.","related":["n4-ni-taishite","noni"]},
{"id":"n1-ni-mo-mashite","pattern":"～にもまして","level":"N1","category":"Partikel","meaning":"even more than","explanation":"にもまして expresses that something is even more or stronger than another state or point of comparison. It is used to stress an increase or a surpassing. This expression is formal and often used in written language.","formation":"Noun + にもまして","examples":[{"japanese":"今年は去年にもまして暑い夏だった。","cloze":{"start":5,"answer":"にもまして","quiz":{"level":"N1","japanese":"今年は去年にもまして暑い夏だった。","german":"This year's summer was even hotter than last year's.","start":5,"answer":"にもまして","acceptedAnswers":["にもまして"],"distractors":[{"text":"にもましました","reason":"The finite past form does not form a comparative connection here."},{"text":"にもますて","reason":"The て-form of 増す is 増して."},{"text":"にもましてな","reason":"な cannot be attached here."}]}},"romaji":"Kotoshi wa kyonen ni mo mashite atsui natsu datta.","german":"This year's summer was even hotter than last year's."},{"japanese":"彼女は誰にもまして努力家だ。","cloze":{"start":4,"answer":"にもまして"},"romaji":"Kanojo wa dare ni mo mashite doryokuka da.","german":"She works harder than anyone else."}],"notes":"Formal. Stresses an increase or a surpassing in a comparison.","related":["yori","n1-mo-saru-koto-nagara"]},
{"id":"n1-nomi-narazu","pattern":"～のみならず","level":"N1","category":"Partikel","meaning":"not only","explanation":"のみならず is a formal expression meaning \"not only\". It is used to express that something goes beyond the point mentioned and includes additional aspects. This construction is used mainly in formal written language.","formation":"Noun/Verb-辞書形/い-adjective + のみならず","examples":[{"japanese":"彼は日本語のみならず、中国語も話せる。","cloze":{"start":5,"answer":"のみならず","quiz":{"level":"N1","japanese":"彼は日本語のみならず、中国語も話せる。","german":"He can speak not only Japanese but also Chinese.","start":5,"answer":"のみならず","acceptedAnswers":["のみならず","だけでなく"],"distractors":[{"text":"のみならずな","reason":"な cannot be attached to this connection here."},{"text":"のみならずを","reason":"を does not form an additive connection here."},{"text":"のみならずます","reason":"ます cannot be attached to ず."}]}},"romaji":"Kare wa nihongo nomi narazu, chūgokugo mo hanaseru.","german":"He can speak not only Japanese but also Chinese."},{"japanese":"この製品は品質が良いのみならず、価格も手頃だ。","cloze":{"start":10,"answer":"のみならず"},"romaji":"Kono seihin wa hinshitsu ga yoi nomi narazu, kakaku mo tegoro da.","german":"This product is not only of good quality but also reasonably priced."}],"notes":"Very formal. Used mainly in written language.","related":["n4-dake-de-naku","n2-ni-todomarazu"]},
{"id":"n1-wa-oroka","pattern":"～はおろか","level":"N1","category":"Partikel","meaning":"let alone","explanation":"はおろか expresses that not even the simpler or more basic thing is possible, let alone the more difficult or advanced one. It is used to stress that not even a lower level is reached. The construction follows the pattern: harder/higher はおろか easier/lower not ... either.","formation":"Noun + はおろか","examples":[{"japanese":"彼は漢字はおろか、ひらがなも読めない。","cloze":{"start":4,"answer":"はおろか","quiz":{"level":"N1","japanese":"彼は漢字はおろか、ひらがなも読めない。","german":"He can't even read hiragana, let alone kanji.","start":4,"answer":"はおろか","acceptedAnswers":["はおろか"],"distractors":[{"text":"はおろかを","reason":"を does not form an escalating connection here."},{"text":"はおろかます","reason":"ます cannot be attached directly to おろか."},{"text":"はおろかな","reason":"The attributive form does not connect to ひらがなも読めない here."}]}},"romaji":"Kare wa kanji wa oroka, hiragana mo yomenai.","german":"He can't even read hiragana, let alone kanji."},{"japanese":"忙しくて、旅行はおろか映画を見る時間もない。","cloze":{"start":7,"answer":"はおろか"},"romaji":"Isogashikute, ryokō wa oroka eiga o miru jikan mo nai.","german":"I'm so busy that I don't even have time to see a movie, let alone travel."}],"notes":"Stresses that even the simpler thing is not possible. The harder thing is mentioned first.","related":["n3-dokoro-ka","n1-mo-saru-koto-nagara"]},
{"id":"n1-mo-saru-koto-nagara","pattern":"～もさることながら","level":"N1","category":"Partikel","meaning":"not only ... but also","explanation":"もさることながら expresses that while the first point mentioned is important or remarkable, the following point is even more important or remarkable. It is used to highlight two aspects, with the emphasis on the second. This construction is very formal.","formation":"Noun + もさることながら","examples":[{"japanese":"彼の学歴もさることながら、実務経験が豊富だ。","cloze":{"start":4,"answer":"もさることながら","quiz":{"level":"N1","japanese":"彼の学歴もさることながら、実務経験が豊富だ。","german":"Not only is his academic background impressive, he also has a wealth of practical experience.","start":4,"answer":"もさることながら","acceptedAnswers":["もさることながら"],"distractors":[{"text":"もさることをながら","reason":"を cannot come before ながら here."},{"text":"もさることながらな","reason":"な cannot be attached to this connection."},{"text":"もさることながらます","reason":"ます cannot be attached to ながら."}]}},"romaji":"Kare no gakureki mo saru koto nagara, jitsumu keiken ga hōfu da.","german":"Not only is his academic background impressive, he also has a wealth of practical experience."},{"japanese":"味もさることながら、この店は雰囲気が素晴らしい。","cloze":{"start":1,"answer":"もさることながら"},"romaji":"Aji mo saru koto nagara, kono mise wa fun'iki ga subarashii.","german":"Not only the food but also the atmosphere of this restaurant is wonderful."}],"notes":"Very formal. Stresses the second point more than the first.","related":["n1-nomi-narazu","n1-ni-mo-mashite"]},
{"id":"n1-yue-ni","pattern":"～ゆえに","level":"N1","category":"Partikel","meaning":"because of, due to","explanation":"ゆえに is a very formal and literary way of expressing a reason or cause. It corresponds to English \"because of\" or \"due to\" and is used mainly in formal written language. It gives the sentence a serious, elevated tone.","formation":"Noun + ゆえに / な-adjective-である + ゆえに / い-adjective + ゆえに","examples":[{"japanese":"若さゆえの過ちだった。","romaji":"Wakasa yue no ayamachi datta.","german":"It was a mistake born of youth."},{"japanese":"経験不足ゆえに、失敗してしまった。","cloze":{"start":4,"answer":"ゆえに","quiz":{"level":"N1","japanese":"経験不足ゆえに、失敗してしまった。","german":"I failed because of a lack of experience.","start":4,"answer":"ゆえに","acceptedAnswers":["ゆえに","のために"],"distractors":[{"text":"ゆえを","reason":"を does not form a link expressing a reason here."},{"text":"ゆえな","reason":"な does not connect the following clause here."},{"text":"ゆえます","reason":"ます cannot be attached to ゆえ."}]}},"romaji":"Keiken busoku yue ni, shippai shite shimatta.","german":"I failed because of a lack of experience."}],"notes":"Very formal and literary. Used mainly in written language.","related":["node","n2-ni-hoka-naranai","n2-ni-tsuki"]},
{"id":"n1-wo-oite-hoka-ni-nai","pattern":"～をおいてほかにない","level":"N1","category":"Partikel","meaning":"there is nothing/no one other than","explanation":"をおいてほかにない emphatically expresses that there is no choice or alternative other than the person or thing mentioned. It stresses that only this one option comes into question. This expression is very formal and is often used to stress the absolute suitability or necessity of something.","formation":"Noun + をおいてほかにない","examples":[{"japanese":"この仕事は彼をおいてほかにない。","cloze":{"start":6,"answer":"をおいてほかにない","quiz":{"level":"N1","japanese":"この仕事は彼をおいてほかにない。","german":"There is no one but him for this job.","start":6,"answer":"をおいてほかにない","acceptedAnswers":["をおいてほかにない"],"distractors":[{"text":"をおいてほかにある","reason":"This asserts that there are other possibilities instead of exclusivity."},{"text":"をおいてほかにないます","reason":"ない does not take an attached ます."},{"text":"をおいてほかをない","reason":"ない does not require an object particle here."}]}},"romaji":"Kono shigoto wa kare o oite hoka ni nai.","german":"There is no one but him for this job."},{"japanese":"今この問題を解決できるのは、あなたをおいてほかにない。","cloze":{"start":17,"answer":"をおいてほかにない"},"romaji":"Ima kono mondai o kaiketsu dekiru no wa, anata o oite hoka ni nai.","german":"No one but you can solve this problem now."}],"notes":"Very emphatic. Stresses uniqueness or absolute suitability.","related":["n1-nara-de-wa","shika-nai"]},
{"id":"n1-wo-kawakiri-ni","pattern":"～を皮切りに / ～を皮切りとして","level":"N1","category":"Partikel","meaning":"starting with","explanation":"を皮切りに expresses that something is the starting point or beginning of a series of events or activities. It is used to show that further events follow after the first. This construction is often used in the context of tours, event series or developments.","formation":"Noun + を皮切りに","examples":[{"japanese":"東京を皮切りに、全国ツアーを行う。","cloze":{"start":2,"answer":"を皮切りに","quiz":{"level":"N1","japanese":"東京を皮切りに、全国ツアーを行う。","german":"Starting in Tokyo, we'll hold a nationwide tour.","start":2,"answer":"を皮切りに","acceptedAnswers":["を皮切りに"],"distractors":[{"text":"を皮切りを","reason":"The expression connects with に."},{"text":"に皮切りに","reason":"The starting point requires を."},{"text":"を皮切ります","reason":"ます cannot be attached directly to 皮切り."}]}},"romaji":"Tōkyō o kawakiri ni, zenkoku tsuā o okonau.","german":"Starting in Tokyo, we'll hold a nationwide tour."},{"japanese":"この事件を皮切りに、様々な問題が明るみに出た。","cloze":{"start":4,"answer":"を皮切りに"},"romaji":"Kono jiken o kawakiri ni, samazama na mondai ga akarumi ni deta.","german":"Starting with this incident, various problems came to light."},{"japanese":"この事件を皮切りに、様々な問題が明らかになった。","romaji":"Kono jiken wo kawakiri ni, samazama na mondai ga akiraka ni natta.","german":"Beginning with this incident, various problems became apparent."}],"notes":"Often used for tours, event series or developments.","related":["n3-o-hajime","n1-wo-hete"],"legacyIds":["n1-wokawakiritoshite"]},
{"id":"n1-wo-hete","pattern":"～を経て","level":"N1","category":"Partikel","meaning":"via, through (process/time)","explanation":"を経て expresses that something has gone through a particular process, period or series of stages. It stresses the course or development over time or space. This construction is often used to describe historical developments, career paths or journeys.","formation":"Noun + を経て","examples":[{"japanese":"長い議論を経て、ようやく合意に達した。","cloze":{"start":4,"answer":"を経て","quiz":{"level":"N1","japanese":"長い議論を経て、ようやく合意に達した。","german":"After long discussions, we finally reached an agreement.","start":4,"answer":"を経て","acceptedAnswers":["を経て"],"distractors":[{"text":"を経た","reason":"The attributive form does not connect the following clause here."},{"text":"を経ます","reason":"The finite form does not form a connection here."},{"text":"に経て","reason":"The stage gone through requires を."}]}},"romaji":"Nagai giron o hete, yōyaku gōi ni tasshita.","german":"After long discussions, we finally reached an agreement."},{"japanese":"彼は様々な職を経て、今の地位についた。","cloze":{"start":6,"answer":"を経て"},"romaji":"Kare wa samazama na shoku o hete, ima no chii ni tsuita.","german":"After going through various jobs, he arrived at his current position."}],"notes":"Stresses the process or development over time. Formal.","related":["n3-o-tsujite","n1-wo-kawakiri-ni"]},
{"id":"n1-wo-mono-tomo-sezu-ni","pattern":"～をものともせずに","level":"N1","category":"Partikel","meaning":"in defiance of, despite","explanation":"をものともせずに expresses that someone acts resolutely despite difficulties, obstacles or adverse circumstances, without letting them have any effect. It stresses strong will and the determination not to be held back by problems. This construction often has an admiring connotation.","formation":"Noun + をものともせずに","examples":[{"japanese":"彼は困難をものともせずに挑戦し続けた。","cloze":{"start":4,"answer":"をものともせずに","quiz":{"level":"N1","japanese":"彼は困難をものともせずに挑戦し続けた。","german":"Undaunted by the difficulties, he kept taking on challenges.","start":4,"answer":"をものともせずに","acceptedAnswers":["をものともせずに"],"distractors":[{"text":"をものともせずを","reason":"を does not form an adverbial connection here."},{"text":"をものともしないました","reason":"The polite past is not formed with ないました."},{"text":"をものともせずな","reason":"な cannot be attached here."}]}},"romaji":"Kare wa konnan o mono tomo sezu ni chōsen shi tsuzuketa.","german":"Undaunted by the difficulties, he kept taking on challenges."},{"japanese":"嵐をものともせずに出発した。","cloze":{"start":1,"answer":"をものともせずに"},"romaji":"Arashi o mono tomo sezu ni shuppatsu shita.","german":"They set off in defiance of the storm."}],"notes":"Stresses determination and strong will. Often with an admiring connotation.","related":["n3-ni-mo-kakawarazu","n1-wo-yoso-ni"]},
{"id":"n1-wo-yoso-ni","pattern":"～をよそに","level":"N1","category":"Partikel","meaning":"regardless of, ignoring","explanation":"をよそに expresses that someone does something without regard for the feelings, expectations or situation of others. It stresses that the action runs counter to what is expected or wished. This construction often has a critical or negative connotation.","formation":"Noun + をよそに","examples":[{"japanese":"親の心配をよそに、彼は危険な仕事を続けている。","cloze":{"start":4,"answer":"をよそに","quiz":{"level":"N1","japanese":"親の心配をよそに、彼は危険な仕事を続けている。","german":"Ignoring his parents' worries, he keeps doing dangerous work.","start":4,"answer":"をよそに","acceptedAnswers":["をよそに"],"distractors":[{"text":"をよそを","reason":"The expression connects with に."},{"text":"をよそな","reason":"な does not form an adverbial connection here."},{"text":"をよそます","reason":"ます cannot be attached to よそ."}]}},"romaji":"Oya no shinpai o yoso ni, kare wa kiken na shigoto o tsuzukete iru.","german":"Ignoring his parents' worries, he keeps doing dangerous work."},{"japanese":"周囲の反対をよそに、彼女は計画を実行した。","cloze":{"start":5,"answer":"をよそに"},"romaji":"Shūi no hantai o yoso ni, kanojo wa keikaku o jikkō shita.","german":"Ignoring the opposition of those around her, she carried out her plan."}],"notes":"Often with a critical or negative connotation. Stresses a lack of consideration.","related":["n3-ni-mo-kakawarazu","n1-wo-mono-tomo-sezu-ni","n2-mo-kamawazu"]},
{"id":"n1-wo-yoginaku-sareru","pattern":"～を余儀なくされる","level":"N1","category":"Partikel","meaning":"to be forced to","explanation":"を余儀なくされる expresses that one is forced by external circumstances or necessity to do something one does not actually want to do. It stresses that there is no choice and that one has to act against one's will. This construction is often used in formal or official contexts.","formation":"Noun + を余儀なくされる","examples":[{"japanese":"台風のため、イベントの中止を余儀なくされた。","romaji":"Taifū no tame, ibento no chūshi o yoginaku sareta.","german":"Because of the typhoon, we were forced to cancel the event.","cloze":{"start":13,"answer":"を余儀なくされた","quiz":{"level":"N1","japanese":"台風のため、イベントの中止を余儀なくされた。","german":"Because of the typhoon, we were forced to cancel the event.","start":13,"answer":"を余儀なくされた","acceptedAnswers":["を余儀なくされた"],"distractors":[{"text":"を余儀なくされるました","reason":"The polite past requires the verb stem."},{"text":"を余儀なくされませんない","reason":"The negative endings cannot be combined like this."},{"text":"を余儀なくされたます","reason":"ます cannot be attached to the plain past form."}]}}},{"japanese":"経営難により、工場の閉鎖を余儀なくされた。","romaji":"Keiei nan ni yori, kōjō no heisa o yoginaku sareta.","german":"Due to financial difficulties, we were forced to close the factory."}],"notes":"Formal. Stresses reluctant necessity due to external circumstances.","related":["n3-zaruwoenai","n4-wake-ni-ikanai"]},
{"id":"n1-wo-kagiri-ni","pattern":"～を限りに","level":"N1","category":"Partikel","meaning":"as of (as an end point)","explanation":"を限りに expresses that something ends at a certain point in time and does not continue afterward. It marks a clear end point or conclusion. This construction is often used in official announcements to proclaim the end of something.","formation":"Point in time/Noun + を限りに","examples":[{"japanese":"今日を限りに、タバコをやめる。","cloze":{"start":2,"answer":"を限りに","quiz":{"level":"N1","japanese":"今日を限りに、タバコをやめる。","german":"As of today, I'm quitting smoking.","start":2,"answer":"を限りに","acceptedAnswers":["を限りに"],"distractors":[{"text":"を限りを","reason":"The time limit connects with に."},{"text":"に限りに","reason":"The fixed expression requires を at the beginning."},{"text":"を限りな","reason":"な does not form a temporal connection here."}]}},"romaji":"Kyō o kagiri ni, tabako o yameru.","german":"As of today, I'm quitting smoking."},{"japanese":"今月を限りに、この店は閉店します。","cloze":{"start":2,"answer":"を限りに"},"romaji":"Kongetsu o kagiri ni, kono mise wa heiten shimasu.","german":"This store will close at the end of this month."}],"notes":"Used for official announcements that something is ending. Marks a clear end point.","related":["n2-wo-motte","n3-o-kikkake-ni"]},
{"id":"n1-wo-fumaete","pattern":"～を踏まえて","level":"N1","category":"Partikel","meaning":"based on, in light of","explanation":"を踏まえて expresses that one does something taking into account, or on the basis of, certain information, experiences or circumstances. It stresses that one incorporates the factors mentioned into one's considerations or actions. This construction is often used in formal or business contexts.","formation":"Noun + を踏まえて","examples":[{"japanese":"過去の経験を踏まえて、新しい計画を立てた。","cloze":{"start":5,"answer":"を踏まえて","quiz":{"level":"N1","japanese":"過去の経験を踏まえて、新しい計画を立てた。","german":"Based on past experience, we drew up a new plan.","start":5,"answer":"を踏まえて","acceptedAnswers":["を踏まえて"],"distractors":[{"text":"を踏まえた","reason":"The attributive form does not connect the following clause here."},{"text":"を踏まえます","reason":"The finite form does not form a connection here."},{"text":"に踏まえて","reason":"The basis taken into account requires を."}]}},"romaji":"Kako no keiken o fumaete, atarashii keikaku o tateta.","german":"Based on past experience, we drew up a new plan."},{"japanese":"調査結果を踏まえて、対策を検討する。","cloze":{"start":4,"answer":"を踏まえて"},"romaji":"Chōsa kekka o fumaete, taisaku o kentō suru.","german":"Based on the survey results, we will consider countermeasures."}],"notes":"Formal. Used in business and official contexts.","related":["n3-ni-motozuite","n1-ni-sokushite"]},
{"id":"n1-to-atte","pattern":"～とあって","level":"N1","category":"Partikel","meaning":"since, because (special circumstance)","explanation":"とあって expresses that a certain situation or reaction occurs because of a special or extraordinary circumstance. It stresses that the reason mentioned is special or unusual and therefore has a corresponding consequence. This construction is often used to describe special events or circumstances.","formation":"Noun + とあって / Sentence + とあって","examples":[{"japanese":"有名歌手のコンサートとあって、会場は満員だった。","cloze":{"start":10,"answer":"とあって","quiz":{"level":"N1","japanese":"有名歌手のコンサートとあって、会場は満員だった。","german":"Since it was a concert by a famous singer, the venue was packed.","start":10,"answer":"とあって","acceptedAnswers":["とあって","なので"],"distractors":[{"text":"とあった","reason":"The attributive past form does not form a causal connection here."},{"text":"とあります","reason":"The finite form does not form a causal connection here."},{"text":"をあって","reason":"The expression of reason requires と."}]}},"romaji":"Yūmei kashu no konsāto to atte, kaijō wa man'in datta.","german":"Since it was a concert by a famous singer, the venue was packed."},{"japanese":"初売りとあって、朝から大勢の客が集まった。","cloze":{"start":3,"answer":"とあって"},"romaji":"Hatsuuri to atte, asa kara ōzei no kyaku ga atsumatta.","german":"Since it was the first sale of the New Year, crowds of customers gathered from early morning."}],"notes":"Stresses special or extraordinary circumstances as the reason.","related":["node","n1-ni-atte"]},
{"id":"n1-to-areba","pattern":"～とあれば","level":"N1","category":"Partikel","meaning":"if it is the case that, if it's for","explanation":"とあれば expresses that if a certain condition or situation arises, one is prepared to do whatever is necessary. It stresses determination or readiness to act under the circumstances mentioned. This construction is often used to express strong motivation or commitment.","formation":"Noun/の + とあれば","examples":[{"japanese":"子供のためとあれば、何でもする。","cloze":{"start":5,"answer":"とあれば","quiz":{"level":"N1","japanese":"子供のためとあれば、何でもする。","german":"If it's for my child, I'll do anything.","start":5,"answer":"とあれば","acceptedAnswers":["とあれば","なら"],"distractors":[{"text":"とあるれば","reason":"The conditional of ある is あれば."},{"text":"をあれば","reason":"The assumed statement requires と."},{"text":"とありますば","reason":"The conditional is not formed with ますば."}]}},"romaji":"Kodomo no tame to areba, nan demo suru.","german":"If it's for my child, I'll do anything."},{"japanese":"会社の存続がかかっているとあれば、協力せざるを得ない。","cloze":{"start":12,"answer":"とあれば"},"romaji":"Kaisha no sonzoku ga kakatte iru to areba, kyōryoku sezaru o enai.","german":"If the company's survival is at stake, we have no choice but to cooperate."}],"notes":"Stresses determination or readiness under certain circumstances.","related":["n1-to-atte","n4-nara"]},
{"id":"n1-to-ii-to-ii","pattern":"～といい～といい","level":"N1","category":"Partikel","meaning":"both ... and","explanation":"といい～といい is used to list several aspects or examples that all share a common evaluation or quality. It stresses that both one and the other apply. This construction is often used to give an overall assessment.","formation":"Noun + といい + Noun + といい","examples":[{"japanese":"彼は性格といい、能力といい、完璧だ。","romaji":"Kare wa seikaku to ii, nōryoku to ii, kanpeki da.","german":"Both in personality and in ability, he is perfect.","cloze":{"start":4,"answer":"といい","quiz":{"level":"N1","japanese":"彼は性格といい、能力といい、完璧だ。","german":"Both in personality and in ability, he is perfect.","start":4,"answer":"といい","acceptedAnswers":["といい"],"distractors":[{"text":"をいい","reason":"The listing expression uses と."},{"text":"といいまする","reason":"る cannot be attached to ます."},{"text":"といいな","reason":"な does not form a parallel evaluative connection here."}]}}},{"japanese":"この町は景色といい、食べ物といい、素晴らしい。","romaji":"Kono machi wa keshiki to ii, tabemono to ii, subarashii.","german":"Both the scenery and the food in this town are wonderful."}],"notes":"Used to stress several positive (or negative) aspects.","related":["mo","n1-de-are-de-are","n2-mo-nara-mo"]},
{"id":"n1-to-iedomo","pattern":"～といえども","level":"N1","category":"Partikel","meaning":"although, even if","explanation":"といえども is a very formal way of saying \"although\" or \"even if\". It is used to express that even under the circumstances mentioned, or despite a certain quality, something else is the case. This construction has a literary, elevated tone.","formation":"Noun + といえども / Verb/Adjective + といえども","examples":[{"japanese":"いくら天才といえども、努力なしでは成功できない。","cloze":{"start":5,"answer":"といえども","quiz":{"level":"N1","japanese":"いくら天才といえども、努力なしでは成功できない。","german":"However much of a genius one may be, one cannot succeed without effort.","start":5,"answer":"といえども","acceptedAnswers":["といえども","でも"],"distractors":[{"text":"をいえども","reason":"The quoting connection requires と."},{"text":"といえどもな","reason":"な cannot be attached here."},{"text":"といえどもます","reason":"ます cannot be attached to ども."}]}},"romaji":"Ikura tensai to iedomo, doryoku nashi de wa seikō dekinai.","german":"However much of a genius one may be, one cannot succeed without effort."},{"japanese":"子供といえども、人権は尊重されるべきだ。","cloze":{"start":2,"answer":"といえども"},"romaji":"Kodomo to iedomo, jinken wa sonchō sareru beki da.","german":"Even though they are children, their human rights should be respected."}],"notes":"Very formal and literary. Used mainly in written language.","related":["n3-to-shitemo","n1-de-are"]},
{"id":"n1-to-kitara","pattern":"～ときたら","level":"N1","category":"Partikel","meaning":"as for (negative)","explanation":"ときたら is used to express criticism or dissatisfaction about someone or something. It highlights a topic one wants to complain about. This construction always has a negative or critical connotation and is used in spoken language.","formation":"Noun + ときたら","examples":[{"japanese":"うちの息子ときたら、勉強もしないでゲームばかりだ。","cloze":{"start":5,"answer":"ときたら","quiz":{"level":"N1","japanese":"うちの息子ときたら、勉強もしないでゲームばかりだ。","german":"As for my son, he doesn't study and does nothing but play games.","start":5,"answer":"ときたら","acceptedAnswers":["ときたら"],"distractors":[{"text":"をきたら","reason":"The highlighted topic requires と."},{"text":"とくるたら","reason":"The conditional of 来る is 来たら."},{"text":"ときますたら","reason":"The conditional is not formed with ますたら."}]}},"romaji":"Uchi no musuko to kitara, benkyō mo shinai de gēmu bakari da.","german":"As for my son, he doesn't study and does nothing but play games."},{"japanese":"最近の若者ときたら、礼儀を知らない。","cloze":{"start":5,"answer":"ときたら"},"romaji":"Saikin no wakamono to kitara, reigi o shiranai.","german":"As for young people these days, they have no manners."}],"notes":"Always has a negative or critical connotation. Colloquial.","related":["n1-taruya","n4-nado","n2-ttara"]},
{"id":"n1-to-mo-arou","pattern":"～ともあろう","level":"N1","category":"Partikel","meaning":"someone of the caliber of","explanation":"ともあろう is used to express surprise or disappointment that someone with a certain status or position has done something unexpected or inappropriate. It stresses that, because of their position, more would have been expected of that person. This construction often has a critical connotation.","formation":"Noun + ともあろう (+ 者が/人が/方が)","examples":[{"japanese":"先生ともあろう人が、そんな間違いをするとは。","cloze":{"start":2,"answer":"ともあろう","quiz":{"level":"N1","japanese":"先生ともあろう人が、そんな間違いをするとは。","german":"To think that a teacher, of all people, would make such a mistake!","start":2,"answer":"ともあろう","acceptedAnswers":["ともあろう"],"distractors":[{"text":"ともあろうな","reason":"No extra な comes before 人 here."},{"text":"ともありまする","reason":"る cannot be attached to ます."},{"text":"ともあるう","reason":"The presumptive form of ある is あろう."}]}},"romaji":"Sensei to mo arō hito ga, sonna machigai o suru to wa.","german":"To think that a teacher, of all people, would make such a mistake!"},{"japanese":"社長ともあろう者が、約束を破るなんて信じられない。","cloze":{"start":2,"answer":"ともあろう"},"romaji":"Shachō to mo arō mono ga, yakusoku o yaburu nante shinjirarenai.","german":"It's unbelievable that someone in the position of company president would break a promise."}],"notes":"Expresses surprise or criticism. Stresses behavior that is inappropriate for the person's status.","related":["noni","n1-to-kitara"]},
{"id":"n1-tote","pattern":"～とて","level":"N1","category":"Partikel","meaning":"even if, even","explanation":"とて is a literary, archaic form meaning 'even if' or 'even'. It is used to express that even in an extreme case something is not possible or does not hold. This construction is found mainly in literary texts or very formal language.","formation":"Noun + とて","examples":[{"japanese":"いくら金持ちとて、幸せとは限らない。","cloze":{"start":6,"answer":"とて","quiz":{"level":"N1","japanese":"いくら金持ちとて、幸せとは限らない。","german":"However rich you may be, that doesn't necessarily mean you're happy.","start":6,"answer":"とて","acceptedAnswers":["とて","でも","といえども"],"distractors":[{"text":"とてを","reason":"を does not form a concessive link here."},{"text":"とてな","reason":"な cannot be attached here."},{"text":"とてます","reason":"ます cannot be attached directly to とて."}]}},"romaji":"Ikura kanemochi tote, shiawase to wa kagiranai.","german":"However rich you may be, that doesn't necessarily mean you're happy."},{"japanese":"親とて、子供の全てを知ることはできない。","cloze":{"start":1,"answer":"とて"},"romaji":"Oya tote, kodomo no subete o shiru koto wa dekinai.","german":"Even parents cannot know everything about their children."}],"notes":"Very literary and archaic. Hardly used in modern colloquial speech.","related":["n1-to-iedomo","n1-de-are"]},
{"id":"n1-ni-ataranai","pattern":"～にあたらない","level":"N1","category":"Partikel","meaning":"not worth, no reason to","explanation":"にあたらない expresses that something is not worth doing, or that there is no reason to behave in a certain way. It is often used to say that a worry, fear or effort is unnecessary. This construction is formal.","formation":"Verb 辞書形 + にあたらない / Noun + にあたらない","examples":[{"japanese":"そんなことで驚くにあたらない。","cloze":{"start":8,"answer":"にあたらない","quiz":{"level":"N1","japanese":"そんなことで驚くにあたらない。","german":"Something like that is nothing to be surprised about.","start":8,"answer":"にあたらない","acceptedAnswers":["にあたらない"],"distractors":[{"text":"にあたらないます","reason":"ない does not take an attached ます."},{"text":"にあたるません","reason":"ません is not attached to the dictionary form."},{"text":"にあたらないました","reason":"The polite past is not formed with ないました."}]}},"romaji":"Sonna koto de odoroku ni ataranai.","german":"Something like that is nothing to be surprised about."},{"japanese":"心配するにあたらない。すぐに解決する。","cloze":{"start":4,"answer":"にあたらない"},"romaji":"Shinpai suru ni ataranai. Sugu ni kaiketsu suru.","german":"There is no need to worry. It will be resolved soon."}],"notes":"Formal. Used to express that an action or emotion is unnecessary.","related":["n1-ni-taeru","nakutemo-ii"]},
{"id":"n1-ni-kagitta-koto-de-wa-nai","pattern":"～にかぎったことではない","level":"N1","category":"Partikel","meaning":"not limited to","explanation":"にかぎったことではない expresses that something is not limited to one particular case, person or situation, but applies more generally. It is used to show that a problem or characteristic is more widespread than first assumed.","formation":"Noun + にかぎったことではない","examples":[{"japanese":"この問題は日本にかぎったことではない。","cloze":{"start":7,"answer":"にかぎったことではない","quiz":{"level":"N1","japanese":"この問題は日本にかぎったことではない。","german":"This problem is not limited to Japan.","start":7,"answer":"にかぎったことではない","acceptedAnswers":["にかぎったことではない","に限らない"],"distractors":[{"text":"にかぎったことだ","reason":"This would confirm that it is limited to Japan."},{"text":"にかぎったことではないます","reason":"ない does not take an attached ます."},{"text":"にかぎったことをない","reason":"Negating a noun requires ではない."}]}},"romaji":"Kono mondai wa Nihon ni kagitta koto de wa nai.","german":"This problem is not limited to Japan."},{"japanese":"若者にかぎったことではないが、最近マナーが悪くなっている。","cloze":{"start":2,"answer":"にかぎったことではない"},"romaji":"Wakamono ni kagitta koto de wa nai ga, saikin manā ga waruku natte iru.","german":"It's not limited to young people, but manners have been getting worse lately."}],"notes":"Used to show that something applies more generally than assumed.","related":["n4-dake-de-naku","n2-ni-todomarazu"]},
{"id":"n1-ni-taru","pattern":"～に足る","level":"N1","category":"Partikel","meaning":"to be worth, worthy","explanation":"に足る expresses that something is worth doing or worthy of being done or received. It emphasizes the value or quality of something. In the negative form (に足りない) it means that something is not worth it or not worthy. This construction is very formal.","formation":"Verb 辞書形/Noun + に足る","examples":[{"japanese":"この映画は見るに足る作品だ。","cloze":{"start":7,"answer":"に足る","quiz":{"level":"N1","japanese":"この映画は見るに足る作品だ。","german":"This film is a work worth seeing.","start":7,"answer":"に足る","acceptedAnswers":["に足る","に値する"],"distractors":[{"text":"に足り","reason":"The stem form cannot modify 作品 attributively here."},{"text":"に足るます","reason":"ます is not attached to the dictionary form."},{"text":"に足らない","reason":"This negates that it is worth watching."}]}},"romaji":"Kono eiga wa miru ni taru sakuhin da.","german":"This film is a work worth seeing."},{"japanese":"彼は信頼に足る人物だ。","cloze":{"start":4,"answer":"に足る"},"romaji":"Kare wa shinrai ni taru jinbutsu da.","german":"He is a person worthy of trust."},{"japanese":"これは信頼に足る情報だ。","romaji":"Kore wa shinrai ni taru jōhō da.","german":"This is trustworthy information."},{"japanese":"彼の業績は称賛に足るものだ。","romaji":"Kare no gyōseki wa shōsan ni taru mono da.","german":"His achievements are praiseworthy."}],"notes":"Very formal. Emphasizes value or worthiness.","related":["n1-ni-taeru","n1-nihajinai"],"legacyIds":["n1-nitaru"]},
{"id":"n1-ikan-ni-yorazu","pattern":"～いかんによらず","level":"N1","category":"Partikel","meaning":"regardless of, irrespective of","explanation":"いかんによらず expresses that something applies regardless of particular circumstances, conditions or manner. It emphasizes that the factors mentioned have no influence on the outcome or decision. This construction is very formal and is often used in official contexts.","formation":"Noun + のいかんによらず","examples":[{"japanese":"理由のいかんによらず、暴力は許されない。","cloze":{"start":3,"answer":"いかんによらず","quiz":{"level":"N1","japanese":"理由のいかんによらず、暴力は許されない。","german":"Regardless of the reason, violence cannot be tolerated.","start":3,"answer":"いかんによらず","acceptedAnswers":["いかんによらず","いかんにかかわらず"],"distractors":[{"text":"いかんによる","reason":"This makes the statement depend on the reason instead of being independent of it."},{"text":"いかんをよらず","reason":"The reference requires に."},{"text":"いかんによらずな","reason":"な cannot be attached here."}]}},"romaji":"Riyū no ikan ni yorazu, bōryoku wa yurusarenai.","german":"Regardless of the reason, violence cannot be tolerated."},{"japanese":"年齢のいかんによらず、誰でも参加できる。","cloze":{"start":3,"answer":"いかんによらず"},"romaji":"Nenrei no ikan ni yorazu, dare demo sanka dekiru.","german":"Regardless of age, anyone can take part."}],"notes":"Very formal. Used in official documents and announcements.","related":["n3-ni-kakawarazu","n1-ikan-de-wa","n1-ikansen"]},
{"id":"n1-ikan-de-wa","pattern":"～いかんでは/～いかんによっては","level":"N1","category":"Partikel","meaning":"depending on","explanation":"いかんでは/いかんによっては expresses that the result or consequence depends on how something is or how it is done. It emphasizes that different circumstances can lead to different results. This construction is very formal.","formation":"Noun + のいかんでは/のいかんによっては","examples":[{"japanese":"やり方いかんでは、成功する可能性もある。","cloze":{"start":3,"answer":"いかんでは","quiz":{"level":"N1","japanese":"やり方いかんでは、成功する可能性もある。","german":"Depending on how it's done, there is also a chance of success.","start":3,"answer":"いかんでは","acceptedAnswers":["いかんでは","次第では"],"distractors":[{"text":"いかんを","reason":"を does not form a dependent condition here."},{"text":"いかんな","reason":"な cannot connect the following clause here."},{"text":"いかんます","reason":"ます cannot be attached directly to いかん."}]}},"romaji":"Yarikata ikan de wa, seikō suru kanōsei mo aru.","german":"Depending on how it's done, there is also a chance of success."},{"japanese":"条件のいかんによっては、契約を見直す必要がある。","cloze":{"start":3,"answer":"いかんによっては"},"romaji":"Jōken no ikan ni yotte wa, keiyaku o minaosu hitsuyō ga aru.","german":"Depending on the conditions, the contract will need to be reviewed."}],"notes":"Very formal. Emphasizes that the result depends on the circumstances.","related":["n4-ni-yotte","n1-ikan-ni-yorazu","n1-ikansen"]},
{"id":"n1-no-itari","pattern":"～の至り","level":"N1","category":"Partikel","meaning":"height of (honor, etc.)","explanation":"の至り expresses the height or extreme of a feeling or state. It is used mainly with positive emotions such as honor, joy or gratitude, but can also appear with negative emotions. This construction is very formal and polite.","formation":"Noun + の至り","examples":[{"japanese":"このような賞をいただき、光栄の至りです。","cloze":{"start":14,"answer":"の至り","quiz":{"level":"N1","japanese":"このような賞をいただき、光栄の至りです。","german":"It is the greatest honor to receive an award like this.","start":14,"answer":"の至り","acceptedAnswers":["の至り"],"distractors":[{"text":"の至ります","reason":"The finite verb form does not fit before です here."},{"text":"を至り","reason":"This intensifying expression links the noun with の."},{"text":"の至りな","reason":"There is no な before です here."}]}},"romaji":"Kono yō na shō o itadaki, kōei no itari desu.","german":"It is the greatest honor to receive an award like this."},{"japanese":"皆様にご心配をおかけして、恐縮の至りです。","cloze":{"start":15,"answer":"の至り"},"romaji":"Minasama ni go-shinpai o okake shite, kyōshuku no itari desu.","german":"I am deeply sorry to have caused you all such worry."}],"notes":"Very formal and polite. Used mainly in formal speeches.","related":["n1-no-kiwami","n3-koto-da"]},
{"id":"n1-no-kiwami","pattern":"～の極み","level":"N1","category":"Partikel","meaning":"height of, extreme of","explanation":"の極み expresses the absolute height or extreme of a feeling or state. It is used with both positive and negative emotions and emphasizes intensity. This construction is very formal and literary.","formation":"Noun + の極み","examples":[{"japanese":"彼の行動は無礼の極みだ。","cloze":{"start":7,"answer":"の極み","quiz":{"level":"N1","japanese":"彼の行動は無礼の極みだ。","german":"His behavior is the height of rudeness.","start":7,"answer":"の極み","acceptedAnswers":["の極み"],"distractors":[{"text":"を極み","reason":"This intensifying expression links the noun with の."},{"text":"の極みます","reason":"ます cannot be attached directly to 極み."},{"text":"の極みな","reason":"There is no な before だ here."}]}},"romaji":"Kare no kōdō wa burei no kiwami da.","german":"His behavior is the height of rudeness."},{"japanese":"このような栄誉を受けるとは、喜びの極みです。","cloze":{"start":16,"answer":"の極み"},"romaji":"Kono yō na eiyo o ukeru to wa, yorokobi no kiwami desu.","german":"To receive such an honor is the height of joy."}],"notes":"Very formal and literary. Emphasizes the extreme intensity of a feeling.","related":["n1-no-itari","n1-kiwamarinai"]},
{"id":"n1-zu-ni-wa-okanai","pattern":"～ずにはおかない","level":"N1","category":"Verben","meaning":"inevitably, cannot help but","explanation":"Expresses that an action or event will inevitably occur, or that one cannot help doing something. This structure emphasizes the inevitability of an action. Often used to express strong emotions or reactions.","formation":"Verb ない-stem + ずにはおかない (する→せずにはおかない)","examples":[{"japanese":"この映画は見る人を感動させずにはおかない。","cloze":{"start":13,"answer":"ずにはおかない","quiz":{"level":"N1","japanese":"この映画は見る人を感動させずにはおかない。","german":"This film cannot fail to move those who see it.","start":13,"answer":"ずにはおかない","acceptedAnswers":["ずにはおかない"],"distractors":[{"text":"ずにはおかないます","reason":"ない does not take an attached ます."},{"text":"ずにはおくません","reason":"ません is not attached to the dictionary form."},{"text":"ずにはおかないました","reason":"The polite past is not formed with ないました."}]}},"romaji":"Kono eiga wa miru hito wo kandō sasezuni wa okanai.","german":"This film cannot fail to move those who see it."},{"japanese":"彼の演説は聴衆を驚かせずにはおかなかった。","romaji":"Kare no enzetsu wa chōshū o odorokasezu ni wa okanakatta.","german":"His speech could not fail to astonish the audience."}],"notes":"Formal and literary. The form with する is せずにはおかない.","related":["n1-nai-de-wa-okanai","n1-zu-ni-wa-sumanai"]},
{"id":"n1-nai-de-wa-okanai","pattern":"～ないではおかない","level":"N1","category":"Verben","meaning":"cannot help but (variant)","explanation":"Alternative form of ずにはおかない that expresses the same meaning of inevitability. This form is somewhat less formal, but still elevated language. Used to emphasize that something will inevitably happen.","formation":"Verb ない-form + ではおかない","examples":[{"japanese":"この事実は世間を騒がせないではおかない。","cloze":{"start":11,"answer":"ないではおかない","quiz":{"level":"N1","japanese":"この事実は世間を騒がせないではおかない。","german":"This fact is bound to cause an uproar among the public.","start":11,"answer":"ないではおかない","acceptedAnswers":["ないではおかない"],"distractors":[{"text":"ないではおかないます","reason":"ない does not take an attached ます."},{"text":"ないではおくません","reason":"ません is not attached to the dictionary form."},{"text":"ないではおかないました","reason":"The polite past is not formed with ないました."}]}},"romaji":"Kono jijitsu wa seken wo sawagasenai de wa okanai.","german":"This fact is bound to cause an uproar among the public."},{"japanese":"彼女の美しさは人々を魅了しないではおかない。","cloze":{"start":13,"answer":"ないではおかない"},"romaji":"Kanojo no utsukushisa wa hitobito wo miryō shinai de wa okanai.","german":"Her beauty cannot fail to captivate people."}],"notes":"Synonym of ずにはおかない. The two forms are interchangeable.","related":["n1-zu-ni-wa-okanai","n1-nai-de-wa-sumanai"]},
{"id":"n1-zu-ni-wa-sumanai","pattern":"～ずにはすまない","level":"N1","category":"Verben","meaning":"absolutely must, cannot avoid","explanation":"Expresses that one absolutely must do something in order to set a situation right or live up to one's responsibility. This structure emphasizes moral obligation or social necessity. Often used when one feels guilty or has to make amends.","formation":"Verb ない-stem + ずにはすまない (する→せずにはすまない)","examples":[{"japanese":"約束を破ってしまったので、謝らずにはすまない。","cloze":{"start":15,"answer":"ずにはすまない","quiz":{"level":"N1","japanese":"約束を破ってしまったので、謝らずにはすまない。","german":"I broke my promise, so I absolutely have to apologize.","start":15,"answer":"ずにはすまない","acceptedAnswers":["ずにはすまない"],"distractors":[{"text":"ずにはすむ","reason":"This would claim that one could get by without apologizing."},{"text":"ずにはすまないます","reason":"ない does not take an attached ます."},{"text":"ずをはすまない","reason":"This fixed combination requires に."}]}},"romaji":"Yakusoku wo yabutte shimatta node, ayamarazu ni wa sumanai.","german":"I broke my promise, so I absolutely have to apologize."},{"japanese":"彼に迷惑をかけたから、お詫びをせずにはすまない。","cloze":{"start":16,"answer":"ずにはすまない"},"romaji":"Kare ni meiwaku wo kaketa kara, owabi wo sezu ni wa sumanai.","german":"I caused him trouble, so I absolutely have to apologize to him."}],"notes":"Emphasizes moral or social obligation more strongly than ずにはおかない.","related":["n1-zu-ni-wa-okanai","n1-nai-de-wa-sumanai"]},
{"id":"n1-nai-de-wa-sumanai","pattern":"～ないではすまない","level":"N1","category":"Verben","meaning":"absolutely must (variant)","explanation":"Alternative form of ずにはすまない with an identical meaning. Expresses that something has to be done in order to resolve a situation or take responsibility. This form is somewhat more common in modern language than the ず form.","formation":"Verb ない-form + ではすまない","examples":[{"japanese":"この問題は説明しないではすまない。","cloze":{"start":8,"answer":"ないではすまない","quiz":{"level":"N1","japanese":"この問題は説明しないではすまない。","german":"This problem absolutely has to be explained.","start":8,"answer":"ないではすまない","acceptedAnswers":["ないではすまない"],"distractors":[{"text":"ないではすむ","reason":"This would claim that one could get by without an explanation."},{"text":"ないではすまないます","reason":"ない does not take an attached ます."},{"text":"ないをはすまない","reason":"This fixed combination requires で."}]}},"romaji":"Kono mondai wa setsumei shinai de wa sumanai.","german":"This problem absolutely has to be explained."},{"japanese":"責任者として、辞職しないではすまないだろう。","cloze":{"start":10,"answer":"ないではすまない"},"romaji":"Sekininsha toshite, jishoku shinai de wa sumanai darō.","german":"As the person in charge, there will probably be no way around resigning."}],"notes":"Synonym of ずにはすまない. The two forms are interchangeable.","related":["n1-zu-ni-wa-sumanai","n1-nai-de-wa-okanai"]},
{"id":"n1-te-yamanai","pattern":"～てやまない","level":"N1","category":"Verben","meaning":"sincerely wish, never cease to","explanation":"Expresses a deep, unceasing wish or strong feeling that does not let up. This very formal structure is used mainly in written language. Often combined with verbs such as 願う (to wish), 祈る (to pray), 望む (to hope).","formation":"Verb て-form + やまない","examples":[{"japanese":"皆様のご健康とご多幸を願ってやみません。","romaji":"Minasama no go-kenkō to go-takō wo negatte yamimasen.","german":"I sincerely wish you all good health and happiness."},{"japanese":"世界平和を祈ってやまない。","cloze":{"start":7,"answer":"てやまない","quiz":{"level":"N1","japanese":"世界平和を祈ってやまない。","german":"I pray unceasingly for world peace.","start":7,"answer":"てやまない","acceptedAnswers":["てやまない"],"distractors":[{"text":"たやまない","reason":"After 祈っ, this expression requires the て-form."},{"text":"てやまないます","reason":"ない does not take an attached ます."},{"text":"てやむません","reason":"ません is not attached to the dictionary form."}]}},"romaji":"Sekai heiwa wo inotte yamanai.","german":"I pray unceasingly for world peace."},{"japanese":"世界の平和を願って止まない。","romaji":"Sekai no heiwa o negatte yamanai.","german":"I never cease to wish for world peace."},{"japanese":"彼の成功を祈って止みません。","romaji":"Kare no seikō wo inotte yamimasen.","german":"I pray fervently for his success."}],"notes":"Very formal; often used in speeches, greetings or written addresses.","related":["n4-tsuzukeru"],"legacyIds":["n1-te-yamanu"]},
{"id":"n1-katagata","pattern":"～かたがた","level":"N1","category":"Verben","meaning":"taking the opportunity, at the same time","explanation":"Expresses that one does two things at once or combines one purpose with another. This formal structure is used to show that one is using an opportunity to achieve two goals. Common in polite or business correspondence.","formation":"Noun + かたがた / Verb ます-stem + かたがた","examples":[{"japanese":"お礼かたがた、ご挨拶に伺いました。","cloze":{"start":2,"answer":"かたがた","quiz":{"level":"N1","japanese":"お礼かたがた、ご挨拶に伺いました。","german":"I came by to thank you and, at the same time, to pay my respects.","start":2,"answer":"かたがた","acceptedAnswers":["かたがた","がてら"],"distractors":[{"text":"かたがたを","reason":"を does not form a connecting link here."},{"text":"かたがたな","reason":"な cannot be attached here."},{"text":"かたがたます","reason":"ます cannot be attached directly to かたがた."}]}},"romaji":"Orei katagata, go-aisatsu ni ukagaimashita.","german":"I came by to thank you and, at the same time, to pay my respects."},{"japanese":"散歩かたがた、買い物に出かけた。","cloze":{"start":2,"answer":"かたがた"},"romaji":"Sanpo katagata, kaimono ni dekaketa.","german":"I went out shopping and took a walk at the same time."}],"notes":"Formal and polite. Often used in business letters or formal situations.","related":["n1-gatera","n2-wo-kanete"]},
{"id":"n1-gatera","pattern":"～がてら","level":"N1","category":"Verben","meaning":"while (doing), on the occasion of","explanation":"Similar to かたがた; expresses that one carries out a main activity and does something else on the side. This structure emphasizes that the second action accompanies or supplements the first. The main activity comes before がてら.","formation":"Noun + がてら / Verb ます-stem + がてら","examples":[{"japanese":"散歩がてら、郵便局に寄ってきた。","cloze":{"start":2,"answer":"がてら","quiz":{"level":"N1","japanese":"散歩がてら、郵便局に寄ってきた。","german":"I stopped by the post office while I was out for a walk.","start":2,"answer":"がてら","acceptedAnswers":["がてら","かたがた"],"distractors":[{"text":"がてらを","reason":"を does not form a link expressing an accompanying circumstance here."},{"text":"がてらな","reason":"な cannot be attached here."},{"text":"がてらます","reason":"ます cannot be attached directly to がてら."}]}},"romaji":"Sanpo gatera, yūbinkyoku ni yotte kita.","german":"I stopped by the post office while I was out for a walk."},{"japanese":"買い物がてら、友達に会ってきた。","cloze":{"start":3,"answer":"がてら"},"romaji":"Kaimono gatera, tomodachi ni atte kita.","german":"I met up with a friend while I was out shopping."}],"notes":"Somewhat less formal than かたがた. The main activity comes before がてら.","related":["n1-katagata","n3-tsuide-ni","n2-wo-kanete"]},
{"id":"n1-katawara","pattern":"～かたわら","level":"N1","category":"Verben","meaning":"besides, on the side","explanation":"Expresses that one carries out two activities in parallel, one being the main occupation and the other a side activity. This structure is used to describe parallel or simultaneous activities. Often used in the context of a job and a side activity.","formation":"Noun + のかたわら / Verb 辞書形 + かたわら","examples":[{"japanese":"彼は会社員のかたわら、小説を書いている。","cloze":{"start":6,"answer":"かたわら","quiz":{"level":"N1","japanese":"彼は会社員のかたわら、小説を書いている。","german":"Alongside his job as an office worker, he also writes novels.","start":6,"answer":"かたわら","acceptedAnswers":["かたわら"],"distractors":[{"text":"かたわらを","reason":"を does not form a link for a side activity here."},{"text":"かたわらな","reason":"な cannot be attached here."},{"text":"かたわらます","reason":"ます cannot be attached directly to かたわら."}]}},"romaji":"Kare wa kaishain no katawara, shōsetsu wo kaite iru.","german":"Alongside his job as an office worker, he also writes novels."},{"japanese":"働くかたわら、大学で勉強している。","cloze":{"start":2,"answer":"かたわら"},"romaji":"Hataraku katawara, daigaku de benkyō shite iru.","german":"Alongside my job, I study at university."}],"notes":"Emphasizes the simultaneity of two ongoing activities, not just one-off actions.","related":["n1-katagata","n1-gatera"]},
{"id":"n1-shimatsu-da","pattern":"～始末だ","level":"N1","category":"Verben","meaning":"to end up (negative)","explanation":"Expresses that a situation leads to a regrettable or negative outcome. This structure emphasizes that things have become so bad that an undesirable result has occurred. Used only for negative situations.","formation":"Verb 辞書形/た-form + 始末だ","examples":[{"japanese":"借金が増えて、家を売る始末だ。","cloze":{"start":11,"answer":"始末だ","quiz":{"level":"N1","japanese":"借金が増えて、家を売る始末だ。","german":"My debts kept growing, and now it has come to selling the house.","start":11,"answer":"始末だ","acceptedAnswers":["始末だ"],"distractors":[{"text":"始末を","reason":"The object particle does not complete the statement."},{"text":"始末な","reason":"The attributive form does not end the sentence."},{"text":"始末ます","reason":"ます cannot be attached directly to 始末."}]}},"romaji":"Shakkin ga fuete, ie wo uru shimatsu da.","german":"My debts kept growing, and now it has come to selling the house."},{"japanese":"彼は遅刻ばかりして、ついにクビになる始末だった。","cloze":{"start":18,"answer":"始末だ"},"romaji":"Kare wa chikoku bakari shite, tsui ni kubi ni naru shimatsu datta.","german":"He was constantly late, and in the end it came to him being fired."},{"japanese":"お金を使いすぎて、借金をする始末だ。","romaji":"Okane wo tsukaisugite, shakkin wo suru shimatsu da.","german":"I spent too much money and ended up even having to borrow."},{"japanese":"彼は遅刻ばかりで、ついにクビになる始末だった。","romaji":"Kare wa chikoku bakari de, tsui ni kubi ni naru shimatsu datta.","german":"He was always late and in the end even got fired."}],"notes":"Exclusively for negative situations. Expresses regret or criticism.","related":["n2-sue-ni","n4-you-ni-naru"],"legacyIds":["n1-shimatsuda"]},
{"id":"n1-sobireru","pattern":"～そびれる","level":"N1","category":"Verben","meaning":"to miss the chance to","explanation":"Expresses that one missed the opportunity to do something even though one intended to. This structure emphasizes that one did not do something because the right moment had passed. Often associated with a feeling of regret.","formation":"Verb ます-stem + そびれる","examples":[{"japanese":"聞きたいことがあったのに、聞きそびれてしまった。","romaji":"Kikitai koto ga atta noni, kikisobirete shimatta.","german":"There was something I wanted to ask, but I missed my chance.","cloze":{"start":15,"answer":"そびれて","quiz":{"level":"N1","japanese":"聞きたいことがあったのに、聞きそびれてしまった。","german":"There was something I wanted to ask, but I missed my chance.","start":15,"answer":"そびれて","acceptedAnswers":["そびれて"],"distractors":[{"text":"そびれた","reason":"しまった requires the て-connection."},{"text":"そびれる","reason":"しまった requires the て-connection."},{"text":"そびれます","reason":"The finite polite form does not fit before しまった."}]}}},{"japanese":"朝ご飯を食べそびれて、お腹が空いた。","romaji":"Asa gohan wo tabesobirete, onaka ga suita.","german":"I missed my chance to eat breakfast, so I'm hungry."}],"notes":"Often implies regret over the missed opportunity.","related":["te-shimau"]},
{"id":"n1-te-shikaru-beki","pattern":"～て然るべき / ～てしかるべき","level":"N1","category":"Verben","meaning":"should, it would be appropriate","explanation":"Expresses that something would be natural, appropriate or expected. This formal structure is used to say that something should be as reason or morality demands. Often used in critical or evaluative contexts.","formation":"Verb て-form + 然るべき + Noun","examples":[{"japanese":"この問題について、政府は説明して然るべきだ。","cloze":{"start":15,"answer":"て然るべき","quiz":{"level":"N1","japanese":"この問題について、政府は説明して然るべきだ。","german":"The government ought to give a proper explanation of this problem.","start":15,"answer":"て然るべき","acceptedAnswers":["て然るべき"],"distractors":[{"text":"た然るべき","reason":"This expression requires the て-connection."},{"text":"て然るべく","reason":"The adverbial form does not fit before だ here."},{"text":"て然るべきな","reason":"No additional な comes before だ here."}]}},"romaji":"Kono mondai ni tsuite, seifu wa setsumei shite shikaru beki da.","german":"The government ought to give a proper explanation of this problem."},{"japanese":"彼は責任者として謝罪して然るべき立場にある。","cloze":{"start":11,"answer":"て然るべき"},"romaji":"Kare wa sekininsha toshite shazai shite shikaru beki tachiba ni aru.","german":"As the person responsible, he is in a position where he ought to apologize."},{"japanese":"このような問題は早急に対処してしかるべきだ。","romaji":"Kono yō na mondai wa sakkyū ni taisho shite shikaru beki da.","german":"Problems like this should naturally be dealt with promptly."},{"japanese":"彼には感謝してしかるべきだ。","romaji":"Kare ni wa kansha shite shikaru beki da.","german":"It would only be right to thank him."}],"notes":"Very formal and literary. 然る (しかる) means 'to be so, to be appropriate'.","related":["n4-beki-da","n4-hazu-da"],"legacyIds":["n1-teshikarubeki"]},
{"id":"n1-te-nao","pattern":"～てなお","level":"N1","category":"Verben","meaning":"even after that still, still nevertheless","explanation":"Expresses that even after something has been done or has happened, a state or situation continues to exist. This structure emphasizes the persistence or stubbornness of a state despite previous actions. Used to express surprise or admiration.","formation":"Verb て-form + なお","examples":[{"japanese":"何度も失敗してなお、彼は諦めなかった。","cloze":{"start":6,"answer":"てなお","quiz":{"level":"N1","japanese":"何度も失敗してなお、彼は諦めなかった。","german":"Even after failing many times, he still did not give up.","start":6,"answer":"てなお","acceptedAnswers":["てなお","ても"],"distractors":[{"text":"たなお","reason":"This connecting expression requires the て-form."},{"text":"てなおな","reason":"な cannot be attached here."},{"text":"てなおます","reason":"ます cannot be attached directly to なお."}]}},"romaji":"Nando mo shippai shite nao, kare wa akiramenakatta.","german":"Even after failing many times, he still did not give up."},{"japanese":"説明を聞いてなお、理解できない。","cloze":{"start":5,"answer":"てなお"},"romaji":"Setsumei wo kiite nao, rikai dekinai.","german":"Even after hearing the explanation, I still can't understand it."}],"notes":"Emphasizes the continuation of a state despite counteracting factors.","related":["temo"]},
{"id":"n1-de-wa-aru-mai-shi","pattern":"～ではあるまいし","level":"N1","category":"Verben","meaning":"it's not as if","explanation":"Expresses that a situation or behavior is inappropriate because it does not correspond to the extreme situation mentioned. This structure is used to criticize something or argue that it is exaggerated or uncalled for. Often carries a sense of dissatisfaction or criticism.","formation":"Noun + ではあるまいし / Verb 辞書形 + のではあるまいし","examples":[{"japanese":"子供ではあるまいし、そんなことで泣くな。","cloze":{"start":2,"answer":"ではあるまいし","quiz":{"level":"N1","japanese":"子供ではあるまいし、そんなことで泣くな。","german":"You're not a child anymore, so don't cry over something like that.","start":2,"answer":"ではあるまいし","acceptedAnswers":["ではあるまいし","ではないし"],"distractors":[{"text":"ではあるませんし","reason":"ません is not attached to the dictionary form."},{"text":"ではあるまいしな","reason":"な cannot be attached here."},{"text":"ではあるまいますし","reason":"ます cannot be attached to まい."}]}},"romaji":"Kodomo de wa aru mai shi, sonna koto de naku na.","german":"You're not a child anymore, so don't cry over something like that."},{"japanese":"戦争ではあるまいし、そこまでする必要はない。","cloze":{"start":2,"answer":"ではあるまいし"},"romaji":"Sensō de wa aru mai shi, soko made suru hitsuyō wa nai.","german":"It's not as if this were a war; there's no need to go that far."}],"notes":"Expresses criticism or dissatisfaction. Implies that the behavior is excessive.","related":["n3-wake-dewa-nai","n3-mono-da"]},
{"id":"n1-to-aimatte","pattern":"～と相まって","level":"N1","category":"Verben","meaning":"together with, coupled with","explanation":"Expresses that two or more factors work together and produce a particular result. This structure emphasizes that different elements reinforce each other. Used in formal or analytical contexts to describe causes or factors.","formation":"Noun + と相まって","examples":[{"japanese":"好天と相まって、売り上げが伸びた。","cloze":{"start":2,"answer":"と相まって","quiz":{"level":"N1","japanese":"好天と相まって、売り上げが伸びた。","german":"Coupled with the good weather, sales went up.","start":2,"answer":"と相まって","acceptedAnswers":["と相まって"],"distractors":[{"text":"を相まって","reason":"The factor that works together with the other requires と."},{"text":"と相まった","reason":"The attributive past does not form a link here."},{"text":"と相まります","reason":"The finite form does not form a link here."}]}},"romaji":"Kōten to aimatte, uriage ga nobita.","german":"Coupled with the good weather, sales went up."},{"japanese":"彼の努力と才能が相まって、成功を収めた。","romaji":"Kare no doryoku to sainō ga aimatte, seikō wo osameta.","german":"His effort together with his talent led to success."}],"notes":"Formal. Emphasizes the interplay of several positive or negative factors.","related":["n2-ni-kuwaete","n1-to-atte"]},
{"id":"n1-tomosureba-tomosuru-to","pattern":"～ともすれば/～ともすると","level":"N1","category":"Verben","meaning":"to tend to, to easily end up","explanation":"Expresses that one easily gets into a certain (usually negative) situation or tends toward a certain behavior. This structure is used to describe a tendency or susceptibility. Often followed by negative consequences or states.","formation":"ともすれば / ともすると (no conjugation needed)","examples":[{"japanese":"忙しいと、ともすれば健康を害しがちだ。","cloze":{"start":5,"answer":"ともすれば","quiz":{"level":"N1","japanese":"忙しいと、ともすれば健康を害しがちだ。","german":"When you're busy, you easily tend to damage your health.","start":5,"answer":"ともすれば","acceptedAnswers":["ともすれば","ともすると"],"distractors":[{"text":"ともすればを","reason":"を does not form an adverbial expression of tendency here."},{"text":"ともすればな","reason":"な cannot be attached here."},{"text":"ともするます","reason":"ます requires the stem し."}]}},"romaji":"Isogashii to, tomosureba kenkō wo gaishi gachi da.","german":"When you're busy, you easily tend to damage your health."},{"japanese":"一人でいると、ともすると悲観的になる。","cloze":{"start":7,"answer":"ともすると"},"romaji":"Hitori de iru to, tomosuru to hikanteki ni naru.","german":"When you're alone, you easily become pessimistic."}],"notes":"ともすれば and ともすると are interchangeable. Mostly used with negative tendencies.","related":["n4-gachi","n4-yasui"]},
{"id":"n1-naku-mo-nai","pattern":"～なくもない","level":"N1","category":"Verben","meaning":"not entirely impossible, somewhat","explanation":"Expresses a weak affirmation by using a double negative. This structure means that something is possible, but with reservations or only to a small degree. Used to express cautious or reserved agreement.","formation":"い-adjective-く + もない / Verb ない-form + くもない / Noun + でなくもない","examples":[{"japanese":"彼の言うことも分からなくもない。","cloze":{"start":10,"answer":"なくもない","quiz":{"level":"N1","japanese":"彼の言うことも分からなくもない。","german":"What he says is not entirely incomprehensible.","start":10,"answer":"なくもない","acceptedAnswers":["なくもない"],"distractors":[{"text":"なくもないます","reason":"ない does not take an attached ます."},{"text":"なくもないました","reason":"The polite past is not formed with ないました."},{"text":"なくもないな","reason":"The attributive な-form does not end the sentence here."}]}},"romaji":"Kare no iu koto mo wakaranaku mo nai.","german":"What he says is not entirely incomprehensible."},{"japanese":"その提案を受け入れられなくもない。","cloze":{"start":11,"answer":"なくもない"},"romaji":"Sono teian wo ukeirerare naku mo nai.","german":"It's not impossible for me to accept that proposal."}],"notes":"Expresses reserved or cautious agreement. Weaker than a direct affirmation.","related":["n3-nai-koto-wa-nai"]},
{"id":"n1-ni-itaru","pattern":"～に至る","level":"N1","category":"Verben","meaning":"to reach the point of","explanation":"Expresses that a situation has reached a certain point or state, often after a long process. This formal structure is used to describe reaching an end point or conclusion. Can be used for both positive and negative developments.","formation":"Noun + に至る / Verb 辞書形 + に至る","examples":[{"japanese":"長年の研究の末、成功に至った。","romaji":"Naganen no kenkyū no sue, seikō ni itatta.","german":"After many years of research, success was finally achieved.","cloze":{"start":10,"answer":"に至った","quiz":{"level":"N1","japanese":"長年の研究の末、成功に至った。","german":"After many years of research, success was finally achieved.","start":10,"answer":"に至った","acceptedAnswers":["に至った"],"distractors":[{"text":"に至らなかった","reason":"This negates that success was reached."},{"text":"に至るました","reason":"The polite past requires the stem 至り."},{"text":"に至りた","reason":"The plain past is 至った."}]}}},{"japanese":"事態は最悪の状況に至っている。","romaji":"Jitai wa saiaku no jōkyō ni itatte iru.","german":"The situation has reached its worst point."}],"notes":"Formal. Emphasizes the process leading up to a certain state.","related":["n1-ni-itatte-wa","n4-ni-yotte"]},
{"id":"n1-ni-itatte-wa","pattern":"～に至っては","level":"N1","category":"Verben","meaning":"as for ... (extreme case)","explanation":"Used to highlight an extreme case or a particularly notable example. This structure emphasizes that the example mentioned is especially striking or extreme compared with others. Often followed by a surprising or extreme statement.","formation":"Noun + に至っては","examples":[{"japanese":"最近の若者は本を読まない。彼に至っては、漫画すら読まない。","cloze":{"start":14,"answer":"に至っては","quiz":{"level":"N1","japanese":"最近の若者は本を読まない。彼に至っては、漫画すら読まない。","german":"Young people these days don't read books. As for him, he doesn't even read manga.","start":14,"answer":"に至っては","acceptedAnswers":["に至っては"],"distractors":[{"text":"に至るは","reason":"は does not attach to the dictionary form here."},{"text":"に至りますは","reason":"は does not attach to the polite form here."},{"text":"を至っては","reason":"The highlighted case requires に."}]}},"romaji":"Saikin no wakamono wa hon wo yomanai. Kare ni itatte wa, manga sura yomanai.","german":"Young people these days don't read books. As for him, he doesn't even read manga."},{"japanese":"今年の夏は暑い。先週に至っては、40度を超えた。","cloze":{"start":10,"answer":"に至っては"},"romaji":"Kotoshi no natsu wa atsui. Senshū ni itatte wa, 40-do wo koeta.","german":"This summer is hot. Last week, it even went above 40 degrees."}],"notes":"Highlights an extreme or notable case. Often used with negative examples.","related":["n1-ni-itaru","n3-ni-oite"]},
{"id":"n1-ni-koshita-koto-wa-nai","pattern":"～に越したことはない","level":"N1","category":"Verben","meaning":"nothing is better than","explanation":"Expresses that something is the best option or the most ideal state. This structure is used to express a recommendation or preference. Literally means 'there is nothing that goes beyond it'.","formation":"Verb 辞書形/ない-form + に越したことはない / い-adjective + に越したことはない","examples":[{"japanese":"健康が一番だ。病気にならないに越したことはない。","cloze":{"start":14,"answer":"に越したことはない","quiz":{"level":"N1","japanese":"健康が一番だ。病気にならないに越したことはない。","german":"Health comes first. Nothing is better than not getting sick.","start":14,"answer":"に越したことはない","acceptedAnswers":["に越したことはない"],"distractors":[{"text":"に越したことはないます","reason":"ない does not take an attached ます."},{"text":"に越したことをない","reason":"ない does not need an object particle here."},{"text":"に越すたことはない","reason":"The plain past of 越す is 越した."}]}},"romaji":"Kenkō ga ichiban da. Byōki ni naranai ni koshita koto wa nai.","german":"Health comes first. Nothing is better than not getting sick."},{"japanese":"安全のためには、早く帰るに越したことはない。","cloze":{"start":12,"answer":"に越したことはない"},"romaji":"Anzen no tame ni wa, hayaku kaeru ni koshita koto wa nai.","german":"For safety's sake, it's best to go home early."}],"notes":"Expresses that something is the best or most ideal option.","related":["hou-ga-ii","n3-kagiri"]},
{"id":"n1-ni-sakidatte","pattern":"～に先立って/～に先立ち","level":"N2","category":"Verben","meaning":"before, prior to","explanation":"Expresses that something happens before an important event. This formal structure is used to express temporal priority or preparation. Often used in official announcements or formal contexts.","formation":"Noun + に先立って/に先立ち / Verb 辞書形 + に先立って/に先立ち","examples":[{"japanese":"開会式に先立って、リハーサルが行われた。","cloze":{"start":3,"answer":"に先立って","quiz":{"level":"N2","japanese":"開会式に先立って、リハーサルが行われた。","german":"Prior to the opening ceremony, a rehearsal was held.","start":3,"answer":"に先立って","acceptedAnswers":["に先立って"],"distractors":[{"text":"を先立って","reason":"The time reference requires に."},{"text":"に先立った","reason":"The attributive past does not form a link here."},{"text":"に先立ちます","reason":"The finite form does not form a link here."}]}},"romaji":"Kaikaisiki ni sakidatte, rihāsaru ga okonawareta.","german":"Prior to the opening ceremony, a rehearsal was held."},{"japanese":"新製品の発売に先立ち、記者会見を開きます。","cloze":{"start":6,"answer":"に先立ち"},"romaji":"Shinseihin no hatsubai ni sakidachi, kisha kaiken wo hirakimasu.","german":"Prior to the launch of the new product, we will hold a press conference."},{"japanese":"発売に先立ち、サンプルを配布した。","romaji":"Hatsubai ni sakidachi, sanpuru wo haifu shita.","german":"Before the release, samples were distributed."}],"notes":"Formal. に先立って and に先立ち are interchangeable, with に先立ち being somewhat more formal.","related":["mae-ni"],"legacyIds":["n2-ni-sakidatte"]},
{"id":"n1-ba-koso","pattern":"～ばこそ","level":"N1","category":"Verben","meaning":"precisely because","explanation":"Strongly emphasizes the reason for something, often with an emotional tone. This structure is used to underline that something happens specifically or solely because of a particular reason. Often expresses gratitude, pride or deep conviction.","formation":"Verb ば-form + こそ / い-adjective-ければ + こそ / な-adjective/Noun + であればこそ","examples":[{"japanese":"あなたを信頼すればこそ、この仕事を任せるのです。","cloze":{"start":8,"answer":"ばこそ","quiz":{"level":"N1","japanese":"あなたを信頼すればこそ、この仕事を任せるのです。","german":"It's precisely because I trust you that I'm entrusting you with this work.","start":8,"answer":"ばこそ","acceptedAnswers":["ばこそ"],"distractors":[{"text":"ばこそを","reason":"を does not form a link expressing a reason here."},{"text":"ばこそな","reason":"な cannot be attached here."},{"text":"ばこそます","reason":"ます cannot be attached directly to こそ."}]}},"romaji":"Anata wo shinrai sureba koso, kono shigoto wo makaseru no desu.","german":"It's precisely because I trust you that I'm entrusting you with this work."},{"japanese":"苦労があればこそ、成功の喜びも大きい。","cloze":{"start":5,"answer":"ばこそ"},"romaji":"Kurō ga areba koso, seikō no yorokobi mo ōkii.","german":"It's precisely because there were hardships that the joy of success is all the greater."}],"notes":"Very emphatic. Strongly emphasizes the causal connection.","related":["n3-kara-koso","n3-te-koso"]},
{"id":"n1-ba-sore-made-da","pattern":"～ばそれまでだ/～たらそれまでだ","level":"N1","category":"Verben","meaning":"if ..., then it's over","explanation":"Expresses that if something happens, everything is over or all efforts were in vain. This structure is used to describe a situation that is irreversible or final. Often carries a sense of resignation or warning.","formation":"Verb ば-form + それまでだ / Verb たら-form + それまでだ","examples":[{"japanese":"試験に落ちればそれまでだ。","cloze":{"start":6,"answer":"ばそれまでだ","quiz":{"level":"N1","japanese":"試験に落ちればそれまでだ。","german":"If I fail the exam, that's the end of it.","start":6,"answer":"ばそれまでだ","acceptedAnswers":["ばそれまでだ"],"distractors":[{"text":"ばそれまでを","reason":"The object particle does not end the sentence."},{"text":"ばそれまでな","reason":"The attributive form does not end the sentence."},{"text":"ばそれまでもます","reason":"ます cannot be attached to も."}]}},"romaji":"Shiken ni ochireba sore made da.","german":"If I fail the exam, that's the end of it."},{"japanese":"諦めたらそれまでだ。最後まで頑張ろう。","cloze":{"start":2,"answer":"たらそれまでだ"},"romaji":"Akirametara sore made da. Saigo made ganbarō.","german":"If we give up, it's all over. Let's hang in there until the end."}],"notes":"Expresses finality or resignation. Warns of irreversible consequences.","related":["tara","n4-ba"]},
{"id":"n1-bekarazu","pattern":"～べからず","level":"N1","category":"Verben","meaning":"must not, shall not (prohibition)","explanation":"Very formal and strong prohibition used mainly in written rules and regulations. This archaic structure is not common in modern spoken language. Often seen on signs or in official documents.","formation":"Verb 辞書形 + べからず","examples":[{"japanese":"立入るべからず。","cloze":{"start":3,"answer":"べからず","quiz":{"level":"N1","japanese":"立入るべからず。","german":"No entry.","start":3,"answer":"べからず","acceptedAnswers":["べからず"],"distractors":[{"text":"べし","reason":"This calls for entering instead of prohibiting it."},{"text":"べからずます","reason":"ます cannot be attached to ず."},{"text":"べからずない","reason":"ない cannot be attached to this classical negative form."}]}},"romaji":"Tachiiru bekarazu.","german":"No entry."},{"japanese":"他人に迷惑をかけるべからず。","cloze":{"start":9,"answer":"べからず"},"romaji":"Tanin ni meiwaku wo kakeru bekarazu.","german":"One must not cause trouble for others."}],"notes":"Very formal and archaic. Mainly found on signs or in written rules.","related":["n4-beki-da","n4-tewa-ikenai"]},
{"id":"n1-beku","pattern":"～べく","level":"N1","category":"Verben","meaning":"in order to, with the aim of","explanation":"Expresses a purpose or intention, often in formal or literary contexts. This structure is a more formal alternative to ために. Used to describe that something is done with a particular goal.","formation":"Verb 辞書形 + べく (する→すべく)","examples":[{"japanese":"成功すべく、努力を続けている。","cloze":{"start":3,"answer":"べく","quiz":{"level":"N1","japanese":"成功すべく、努力を続けている。","german":"I keep working hard in order to succeed.","start":3,"answer":"べく","acceptedAnswers":["べく"],"distractors":[{"text":"べき","reason":"The attributive form does not form a purpose link here."},{"text":"べからず","reason":"This expresses a prohibition instead of an intention."},{"text":"べくます","reason":"ます cannot be attached to べく."}]}},"romaji":"Seikō subeku, doryoku wo tsudzukete iru.","german":"I keep working hard in order to succeed."},{"japanese":"真実を明らかにすべく、調査を開始した。","cloze":{"start":8,"answer":"べく"},"romaji":"Shinjitsu wo akiraka ni subeku, chōsa wo kaishi shita.","german":"An investigation was launched in order to uncover the truth."}],"notes":"Formal and literary. する becomes すべく.","related":["n4-tame-ni","n4-beki-da"]},
{"id":"n1-beku-mo-nai","pattern":"～べくもない","level":"N1","category":"Verben","meaning":"cannot possibly","explanation":"Expresses that something is completely impossible or cannot be achieved. This very formal structure emphasizes absolute impossibility. Often used to express that something is far out of reach.","formation":"Verb 辞書形 + べくもない (する→すべくもない)","examples":[{"japanese":"彼の才能は私などが及ぶべくもない。","cloze":{"start":11,"answer":"べくもない","quiz":{"level":"N1","japanese":"彼の才能は私などが及ぶべくもない。","german":"His talent is something someone like me could not possibly match.","start":11,"answer":"べくもない","acceptedAnswers":["べくもない"],"distractors":[{"text":"べくもないます","reason":"ない does not take an attached ます."},{"text":"べくもないました","reason":"The polite past is not formed with ないました."},{"text":"べくをない","reason":"The expression requires も instead of を."}]}},"romaji":"Kare no sainō wa watashi nado ga oyobu beku mo nai.","german":"His talent is something someone like me could not possibly match."},{"japanese":"この問題は素人が解決すべくもない。","cloze":{"start":11,"answer":"べくもない"},"romaji":"Kono mondai wa shirōto ga kaiketsu subeku mo nai.","german":"This problem cannot possibly be solved by an amateur."}],"notes":"Very formal. Emphasizes absolute impossibility.","related":["n1-beku","n2-wake-ga-nai"]},
{"id":"n1-majiki","pattern":"～まじき","level":"N1","category":"Verben","meaning":"unforgivable for, unworthy","explanation":"Expresses that something is morally unacceptable or unworthy. This very formal and archaic structure is used to express strong moral condemnation. Mainly found in literary or very formal contexts.","formation":"Verb 辞書形 + まじき + Noun","examples":[{"japanese":"教師にあるまじき行為だ。","cloze":{"start":5,"answer":"まじき","quiz":{"level":"N1","japanese":"教師にあるまじき行為だ。","german":"That is behavior unworthy of a teacher.","start":5,"answer":"まじき","acceptedAnswers":["まじき"],"distractors":[{"text":"まじく","reason":"The adverbial form cannot modify 行為 attributively here."},{"text":"まじきな","reason":"No additional な comes before 行為 here."},{"text":"まじきます","reason":"ます cannot be attached directly to まじき."}]}},"romaji":"Kyōshi ni aru majiki kōi da.","german":"That is behavior unworthy of a teacher."},{"japanese":"人として許すまじき罪を犯した。","cloze":{"start":6,"answer":"まじき"},"romaji":"Hito toshite yurusu majiki tsumi wo okashita.","german":"He committed a crime that is unforgivable for a human being."}],"notes":"Very formal and archaic. Expresses strong moral condemnation.","related":["n1-bekarazu","n4-beki-da"]},
{"id":"n1-made-da","pattern":"～までだ/～までのことだ","level":"N1","category":"Verben","meaning":"then there's nothing left but to","explanation":"Expresses that if a condition is not met, one will simply do something else. This structure is used to express an alternative solution or a fallback plan. Often carries a sense of resignation or pragmatism.","formation":"Verb 辞書形 + までだ/までのことだ","examples":[{"japanese":"彼が来なければ、一人で行くまでだ。","cloze":{"start":13,"answer":"までだ","quiz":{"level":"N1","japanese":"彼が来なければ、一人で行くまでだ。","german":"If he doesn't come, I'll just go alone.","start":13,"answer":"までだ","acceptedAnswers":["までだ"],"distractors":[{"text":"までを","reason":"The object particle does not end the sentence."},{"text":"までな","reason":"The attributive form does not end the sentence."},{"text":"までもます","reason":"ます cannot be attached directly to も."}]}},"romaji":"Kare ga konakereba, hitori de iku made da.","german":"If he doesn't come, I'll just go alone."},{"japanese":"だめなら、諦めるまでのことだ。","cloze":{"start":8,"answer":"までのことだ"},"romaji":"Dame nara, akirameru made no koto da.","german":"If it doesn't work out, I'll have no choice but to give up."}],"notes":"Expresses a pragmatic or resigned attitude.","related":["shika-nai","dake"]},
{"id":"n1-made-mo-nai","pattern":"～までもない","level":"N1","category":"Verben","meaning":"there is no need to","explanation":"Expresses that something is so obvious or simple that there is no need to do it. This structure emphasizes that an action is superfluous. Can also mean that something goes without saying.","formation":"Verb 辞書形 + までもない","examples":[{"japanese":"そんなことは言うまでもない。","cloze":{"start":8,"answer":"までもない","quiz":{"level":"N1","japanese":"そんなことは言うまでもない。","german":"There's no need to say something like that (it goes without saying).","start":8,"answer":"までもない","acceptedAnswers":["までもない"],"distractors":[{"text":"までもないます","reason":"ない does not take an attached ます."},{"text":"までもないました","reason":"The polite past is not formed with ないました."},{"text":"までをない","reason":"The expression requires も instead of を."}]}},"romaji":"Sonna koto wa iu made mo nai.","german":"There's no need to say something like that (it goes without saying)."},{"japanese":"説明するまでもなく、みんな理解している。","romaji":"Setsumei suru made mo naku, minna rikai shite iru.","german":"Everyone understands it without any need for an explanation."}],"notes":"Emphasizes that something is self-evident or superfluous.","related":["nakutemo-ii","n1-made-da","n2-hodo-no-koto-dewa-nai","n2-wa-iu-made-mo-nai","n1-nai-made-mo"]},
{"id":"n1-mono-wo","pattern":"～ものを","level":"N1","category":"Verben","meaning":"although, but (regret)","explanation":"Expresses regret or dissatisfaction about a situation that could have been different. This structure is used to show that reality does not match expectations. Often placed at the end of a sentence, with a sense of disappointment.","formation":"Verb 辞書形/た-form + ものを / い-adjective + ものを","examples":[{"japanese":"早く言ってくれればよかったものを。","cloze":{"start":13,"answer":"ものを","quiz":{"level":"N1","japanese":"早く言ってくれればよかったものを。","german":"If only you had told me sooner (but you didn't).","start":13,"answer":"ものを","acceptedAnswers":["ものを"],"distractors":[{"text":"ものます","reason":"ます cannot be attached directly to もの."},{"text":"ものをます","reason":"ます cannot be attached to the particle を."},{"text":"ものなを","reason":"This exclamatory expression does not take な."}]}},"romaji":"Hayaku itte kurereba yokatta mono wo.","german":"If only you had told me sooner (but you didn't)."},{"japanese":"謝れば許してもらえたものを、意地を張って損をした。","cloze":{"start":10,"answer":"ものを"},"romaji":"Ayamareba yurushite moraeta mono wo, iji wo hatte son wo shita.","german":"If I had apologized, I would have been forgiven, but I was stubborn and lost out."}],"notes":"Expresses regret over a missed opportunity or a bad decision.","related":["noni","n4-ba-yokatta"]},
{"id":"n1-ya-inaya","pattern":"～や否や","level":"N1","category":"Verben","meaning":"no sooner than, as soon as","explanation":"Expresses that one action follows immediately after another. This formal structure emphasizes the immediacy and speed of the consecutive events. Used mainly in written language.","formation":"Verb 辞書形 + や否や","examples":[{"japanese":"家に帰るや否や、電話が鳴った。","cloze":{"start":4,"answer":"や否や","quiz":{"level":"N1","japanese":"家に帰るや否や、電話が鳴った。","german":"No sooner had I got home than the phone rang.","start":4,"answer":"や否や","acceptedAnswers":["や否や","なり"],"distractors":[{"text":"や否やな","reason":"な cannot be attached here."},{"text":"や否やを","reason":"を does not form a time link here."},{"text":"や否やます","reason":"ます cannot be attached directly to や否や."}]}},"romaji":"Ie ni kaeru ya inaya, denwa ga natta.","german":"No sooner had I got home than the phone rang."},{"japanese":"試験が終わるや否や、学生たちは教室を飛び出した。","cloze":{"start":6,"answer":"や否や"},"romaji":"Shiken ga owaru ya inaya, gakuseitachi wa kyōshitsu wo tobidashita.","german":"As soon as the exam was over, the students rushed out of the classroom."}],"notes":"Formal and literary. Emphasizes the immediate succession of two events.","related":["n3-totan","n2-ka-nai-ka-no-uchi-ni","n1-ga-hayai-ka"]},
{"id":"n1-you-ga-you-to","pattern":"～ようが/～ようと","level":"N1","category":"Verben","meaning":"no matter how/what one does","explanation":"Expresses that no matter what happens or is done, the result stays the same. This structure is used to emphasize that something holds under all circumstances. Often used in the form AようがBようが.","formation":"Verb 意向形 + が/と / Verb 意向形 + が + Verb 意向形 + が","examples":[{"japanese":"雨が降ろうが降るまいが、試合は行われる。","romaji":"Ame ga furō ga furu mai ga, shiai wa okonawareru.","german":"Whether it rains or not, the match will be held."},{"japanese":"何をしようと、結果は変わらない。","cloze":{"start":3,"answer":"ようと","quiz":{"level":"N1","japanese":"何をしようと、結果は変わらない。","german":"Whatever you do, the result won't change.","start":3,"answer":"ようと","acceptedAnswers":["ようと","ようが"],"distractors":[{"text":"ようを","reason":"The concessive volitional form does not combine with を."},{"text":"ようます","reason":"ます cannot be attached to the volitional form."},{"text":"ようとな","reason":"な cannot be attached here."}]}},"romaji":"Nani wo shiyō to, kekka wa kawaranai.","german":"Whatever you do, the result won't change."}],"notes":"ようが and ようと are interchangeable. Often in the form AようがBようが.","related":["temo","n1-tomo"]},
{"id":"n1-you-ni-mo-nai","pattern":"～ようにも～ない","level":"N1","category":"Verben","meaning":"even if one wanted to, one can't","explanation":"Expresses that one would like to do something but cannot for objective reasons. This structure emphasizes impossibility despite the wish or intention. Used to express frustration or helplessness.","formation":"Verb 意向形 + にも + Verb 可能形-ない","examples":[{"japanese":"お金がなくて、買おうにも買えない。","romaji":"Okane ga nakute, kaō ni mo kaenai.","german":"I have no money, so even if I wanted to buy it, I couldn't.","cloze":{"start":7,"answer":"買おうにも買えない","quiz":{"level":"N1","japanese":"お金がなくて、買おうにも買えない。","german":"I have no money, so even if I wanted to buy it, I couldn't.","start":7,"answer":"買おうにも買えない","acceptedAnswers":["買おうにも買えない"],"distractors":[{"text":"買おうにも買える","reason":"This affirms that buying is possible."},{"text":"買おうにも買えないます","reason":"ない does not take an attached ます."},{"text":"買ううにも買えない","reason":"The volitional form of 買う is 買おう."}]}}},{"japanese":"電話番号を知らないので、連絡しようにもできない。","romaji":"Denwa bangō wo shiranai node, renraku shiyō ni mo dekinai.","german":"I don't know the phone number, so I can't get in touch even if I want to."}],"notes":"Emphasizes impossibility despite the wish or intention.","related":[]},
{"id":"n1-wo-motte-shite-mo","pattern":"～をもってしても","level":"N1","category":"Verben","meaning":"even with","explanation":"Expresses that even with a particular means or under a particular condition, something cannot be achieved. This formal structure emphasizes that a normally effective means is not enough in this case. Used to underline the difficulty or impossibility of something.","formation":"Noun + をもってしても","examples":[{"japanese":"現代の科学をもってしても、この病気は治せない。","cloze":{"start":5,"answer":"をもってしても","quiz":{"level":"N1","japanese":"現代の科学をもってしても、この病気は治せない。","german":"Even with modern science, this disease cannot be cured.","start":5,"answer":"をもってしても","acceptedAnswers":["をもってしても"],"distractors":[{"text":"をもってするも","reason":"The concessive link requires しても."},{"text":"をもってしますも","reason":"も does not attach to the polite form here."},{"text":"をもってしてを","reason":"を does not form a concessive link here."}]}},"romaji":"Gendai no kagaku wo motte shite mo, kono byōki wa naosenai.","german":"Even with modern science, this disease cannot be cured."},{"japanese":"彼の努力をもってしても、優勝は難しいだろう。","cloze":{"start":4,"answer":"をもってしても"},"romaji":"Kare no doryoku wo motte shite mo, yūshō wa muzukashii darō.","german":"Even with his efforts, winning the championship will probably be difficult."}],"notes":"Very formal. Emphasizes that something is not possible despite a powerful means.","related":["temo","n2-wo-motte"]},
{"id":"n1-n-ga-tame-ni","pattern":"～んがために","level":"N1","category":"Verben","meaning":"in order to (formal)","explanation":"Very formal version of ために that expresses a purpose or intention. This archaic structure is used mainly in literary or very formal contexts. Emphasizes the seriousness or importance of the goal.","formation":"Verb ない-stem + んがために (する→せんがために)","examples":[{"japanese":"成功せんがために、彼は全てを犠牲にした。","cloze":{"start":3,"answer":"んがために","quiz":{"level":"N1","japanese":"成功せんがために、彼は全てを犠牲にした。","german":"He sacrificed everything in order to succeed.","start":3,"answer":"んがために","acceptedAnswers":["んがために"],"distractors":[{"text":"んがためを","reason":"The purpose link is completed with に."},{"text":"んがためな","reason":"な cannot be attached here."},{"text":"んがためます","reason":"ます cannot be attached directly to ため."}]}},"romaji":"Seikō sen ga tame ni, kare wa subete wo gisei ni shita.","german":"He sacrificed everything in order to succeed."},{"japanese":"真実を知らんがために、彼女は調査を続けた。","cloze":{"start":5,"answer":"んがために"},"romaji":"Shinjitsu wo shiran ga tame ni, kanojo wa chōsa wo tsudzuketa.","german":"She continued the investigation in order to learn the truth."}],"notes":"Very formal and archaic. する becomes せんがために. Literary style.","related":["n4-tame-ni","n1-beku"]},
{"id":"n1-n-bakari-ni","pattern":"～んばかり(に)","level":"N1","category":"Verben","meaning":"as if about to","explanation":"Expresses that something looks or feels as if it is about to happen. This structure is used to describe an intense or extreme situation vividly. Emphasizes the immediacy or intensity of a state.","formation":"Verb ない-stem + んばかりに (する→せんばかりに) / Verb た-form + ばかりに","examples":[{"japanese":"彼は今にも泣かんばかりの顔をしていた。","romaji":"Kare wa ima ni mo nakan bakari no kao wo shite ita.","german":"He had a look on his face as if he were about to cry at any moment.","cloze":{"start":7,"answer":"んばかりの","quiz":{"level":"N1","japanese":"彼は今にも泣かんばかりの顔をしていた。","german":"He had a look on his face as if he were about to cry at any moment.","start":7,"answer":"んばかりの","acceptedAnswers":["んばかりの"],"distractors":[{"text":"んばかりに","reason":"The adverbial form does not modify 顔 attributively here."},{"text":"んばかりを","reason":"を cannot connect attributively to 顔 here."},{"text":"んばかります","reason":"ます cannot be attached directly to ばかり."}]}}},{"japanese":"群衆は喜びに溢れんばかりだった。","romaji":"Gunshū wa yorokobi ni afuren bakari datta.","german":"The crowd was so full of joy it seemed about to overflow."},{"japanese":"今にも泣き出さんばかりの顔をしていた。","romaji":"Ima ni mo nakidasan bakari no kao wo shite ita.","german":"He had a look on his face as if he were about to burst into tears at any moment."},{"japanese":"飛び上がらんばかりに喜んだ。","romaji":"Tobiagaran bakari ni yorokonda.","german":"He was so happy he practically jumped for joy."}],"notes":"Literary and vivid. する becomes せんばかりに.","related":["n4-sou-appearance","n4-bakari-p","n4-you-da"],"legacyIds":["n1-nbakari"]},
{"id":"n1-ga-saigo-tara-saigo","pattern":"～が最後/～たら最後","level":"N1","category":"Verben","meaning":"once ..., there's no going back","explanation":"Expresses that once something happens, an irreversible or extreme consequence follows. This structure emphasizes finality and often negative consequences. Used to warn of serious or irreversible consequences.","formation":"Verb 辞書形/た-form + が最後 / Verb たら-form + 最後","examples":[{"japanese":"彼に秘密を話したが最後、すぐに広まってしまう。","cloze":{"start":8,"answer":"が最後","quiz":{"level":"N1","japanese":"彼に秘密を話したが最後、すぐに広まってしまう。","german":"Once you tell him a secret, it spreads right away.","start":8,"answer":"が最後","acceptedAnswers":["が最後"],"distractors":[{"text":"が最後を","reason":"を does not form a conditional link here."},{"text":"が最後な","reason":"な cannot be attached here."},{"text":"が最後ます","reason":"ます cannot be attached directly to 最後."}]}},"romaji":"Kare ni himitsu wo hanashita ga saigo, sugu ni hiromatte shimau.","german":"Once you tell him a secret, it spreads right away."},{"japanese":"あの道に入ったら最後、二度と戻れない。","cloze":{"start":6,"answer":"たら最後"},"romaji":"Ano michi ni haittara saigo, nido to modorenai.","german":"Once you go down that road, you can never come back."},{"japanese":"この薬を飲んだが最後、二度と元には戻れない。","romaji":"Kono kusuri wo nonda ga saigo, nido to moto ni wa modorenai.","german":"Once you take this medicine, there's no going back to how things were."},{"japanese":"彼と喧嘩したが最後、もう仲直りできない。","romaji":"Kare to kenka shita ga saigo, mō nakanaori dekinai.","german":"Once you've had a fight with him, you can never make up."}],"notes":"Emphasizes irreversible, often negative consequences. A warning about a point of no return.","related":["n1-ba-sore-made-da"],"legacyIds":["n1-ta-ga-saigo"]},
{"id":"n1-koto-nashi-ni","pattern":"～ことなしに","level":"N1","category":"Verben","meaning":"without (doing)","explanation":"Formal expression meaning 'without doing something'. This structure is used to express that something is achieved without carrying out a particular action. Often found in literary or academic texts.","formation":"Verb 辞書形 + ことなしに","examples":[{"japanese":"努力することなしに、成功は得られない。","cloze":{"start":4,"answer":"ことなしに","quiz":{"level":"N1","japanese":"努力することなしに、成功は得られない。","german":"Without making an effort, you cannot achieve success.","start":4,"answer":"ことなしに","acceptedAnswers":["ことなしに","ことなく"],"distractors":[{"text":"ことありに","reason":"This does not form the negative condition 'without effort'."},{"text":"ことなしを","reason":"を does not form a link expressing an accompanying circumstance here."},{"text":"ことなしな","reason":"な cannot be attached here."}]}},"romaji":"Doryoku suru koto nashi ni, seikō wa erarenai.","german":"Without making an effort, you cannot achieve success."},{"japanese":"彼は一言も言うことなしに、部屋を出て行った。","cloze":{"start":7,"answer":"ことなしに"},"romaji":"Kare wa hitokoto mo iu koto nashi ni, heya wo dete itta.","german":"He left the room without saying a single word."}],"notes":"Formal and literary. A more formal alternative to ないで or ずに.","related":["n1-nashi-ni-nakushite","naide"]},
{"id":"n1-nashi-ni-nakushite","pattern":"～なしに/～なくして","level":"N1","category":"Verben","meaning":"without","explanation":"Expresses that something is not possible without a particular condition or element. This structure emphasizes the necessity or indispensability of something. Often used in formal or emphatic contexts.","formation":"Noun + なしに/なくして / Verb 辞書形 + ことなしに","examples":[{"japanese":"努力なしに成功はない。","cloze":{"start":2,"answer":"なしに","quiz":{"level":"N1","japanese":"努力なしに成功はない。","german":"Without effort there is no success.","start":2,"answer":"なしに","acceptedAnswers":["なしに","なくして"],"distractors":[{"text":"なしを","reason":"を does not form a link expressing an accompanying circumstance here."},{"text":"なしな","reason":"な cannot be attached here."},{"text":"なします","reason":"ます cannot be attached directly to なし."}]}},"romaji":"Doryoku nashi ni seikō wa nai.","german":"Without effort there is no success."},{"japanese":"平和なくして発展はありえない。","cloze":{"start":2,"answer":"なくして"},"romaji":"Heiwa nakushite hatten wa arienai.","german":"Without peace, development is impossible."}],"notes":"なくして is more emphatic than なしに. Both emphasize indispensability.","related":["n1-koto-nashi-ni","n1-nakushite"]},
{"id":"n1-tokoro-wo","pattern":"～ところを","level":"N1","category":"Verben","meaning":"although just then (interrupted)","explanation":"Expresses that someone is or was just in the middle of doing something when they were interrupted or something else happened. This structure is often used to express an apology or gratitude. Emphasizes the timing of the interruption.","formation":"Verb 辞書形/ている-form/た-form + ところを","examples":[{"japanese":"お忙しいところを、お時間をいただきありがとうございます。","cloze":{"start":4,"answer":"ところを","quiz":{"level":"N1","japanese":"お忙しいところを、お時間をいただきありがとうございます。","german":"Thank you for taking the time, even though you're busy.","start":4,"answer":"ところを","acceptedAnswers":["ところを"],"distractors":[{"text":"ところな","reason":"な does not connect the following clause here."},{"text":"ところます","reason":"ます cannot be attached directly to ところ."},{"text":"ところをます","reason":"ます cannot be attached to を."}]}},"romaji":"Oisogashii tokoro wo, ojikan wo itadaki arigatō gozaimasu.","german":"Thank you for taking the time, even though you're busy."},{"japanese":"休んでいるところを邪魔してすみません。","cloze":{"start":5,"answer":"ところを"},"romaji":"Yasunde iru tokoro wo jama shite sumimasen.","german":"I'm sorry to disturb you while you're resting."}],"notes":"Often used in polite apologies or expressions of thanks.","related":["n4-tokoro-da","n3-sai-ni"]},
{"id":"n1-ka-to-omoikiya","pattern":"～かと思いきや","level":"N1","category":"Verben","meaning":"just when one thought","explanation":"Expresses that something unexpected happens just when one had expected something else. This structure emphasizes the contrast between expectation and reality. Used to describe surprises or sudden twists.","formation":"Verb 辞書形/た-form + かと思いきや / い-adjective + かと思いきや","examples":[{"japanese":"雨が降るかと思いきや、急に晴れた。","cloze":{"start":4,"answer":"かと思いきや","quiz":{"level":"N1","japanese":"雨が降るかと思いきや、急に晴れた。","german":"Just when I thought it was going to rain, it suddenly cleared up.","start":4,"answer":"かと思いきや","acceptedAnswers":["かと思いきや"],"distractors":[{"text":"かを思いきや","reason":"The content of the thought requires と."},{"text":"かと思いきやな","reason":"な cannot be attached here."},{"text":"かと思いきやます","reason":"ます cannot be attached to きや."}]}},"romaji":"Ame ga furu ka to omoikiya, kyū ni hareta.","german":"Just when I thought it was going to rain, it suddenly cleared up."},{"japanese":"彼は怒っているかと思いきや、笑い出した。","cloze":{"start":7,"answer":"かと思いきや"},"romaji":"Kare wa okotte iru ka to omoikiya, waraidashita.","german":"Just when I thought he was angry, he burst out laughing."}],"notes":"Emphasizes unexpected twists or contrasts between expectation and reality.","related":["n2-ka-to-omottara"]},
{"id":"n1-te-wa-kanawanai","pattern":"～てはかなわない","level":"N1","category":"Verben","meaning":"it is unbearable","explanation":"Expresses that a situation is so unpleasant or burdensome that one cannot stand it. This structure is used to express strong dissatisfaction or complaints. Emphasizes how unbearable a state is.","formation":"Verb て-form + はかなわない / い-adjective-くて + はかなわない","examples":[{"japanese":"隣の部屋がうるさくてはかなわない。","cloze":{"start":9,"answer":"てはかなわない","quiz":{"level":"N1","japanese":"隣の部屋がうるさくてはかなわない。","german":"The room next door is so noisy it's unbearable.","start":9,"answer":"てはかなわない","acceptedAnswers":["てはかなわない"],"distractors":[{"text":"てはかなわないます","reason":"ない does not take an attached ます."},{"text":"てはかなうません","reason":"ません is not attached to the dictionary form."},{"text":"たはかなわない","reason":"The connection after うるさく requires て."}]}},"romaji":"Tonari no heya ga urusakute wa kanawanai.","german":"The room next door is so noisy it's unbearable."},{"japanese":"毎日残業させられてはかなわない。","cloze":{"start":8,"answer":"てはかなわない"},"romaji":"Mainichi zangyō saserarete wa kanawanai.","german":"Being made to work overtime every day is unbearable."}],"notes":"Expresses a strong complaint or dissatisfaction about a situation.","related":["n3-te-tamaranai","n1-ni-taenai"]},
{"id":"n1-ni-katakunai","pattern":"～にかたくない","level":"N1","category":"Verben","meaning":"it is not hard to","explanation":"Expresses that something is easy to imagine, understand or predict. This formal structure is used to say that one can easily imagine something. Used mainly in written language.","formation":"Verb 辞書形 + にかたくない (推察、想像、理解 etc.)","examples":[{"japanese":"彼の気持ちは想像にかたくない。","cloze":{"start":8,"answer":"にかたくない","quiz":{"level":"N1","japanese":"彼の気持ちは想像にかたくない。","german":"His feelings are not hard to imagine.","start":8,"answer":"にかたくない","acceptedAnswers":["にかたくない"],"distractors":[{"text":"にかたくないます","reason":"ない does not take an attached ます."},{"text":"にかたくないました","reason":"The polite past is not formed with ないました."},{"text":"をかたくない","reason":"This expression links the act of imagining with に."}]}},"romaji":"Kare no kimochi wa sōzō ni katakunai.","german":"His feelings are not hard to imagine."},{"japanese":"その結果は予想にかたくない。","cloze":{"start":7,"answer":"にかたくない"},"romaji":"Sono kekka wa yosō ni katakunai.","german":"That result is not hard to predict."}],"notes":"Formal and literary. Mostly used with 想像、推察、予測 etc.","related":["n4-yasui"]},
{"id":"n1-ni-soku-suru","pattern":"～に即する","level":"N1","category":"Verben","meaning":"in accordance with, according to","explanation":"Expresses that something conforms to a rule, a principle or reality. This formal structure is used to emphasize conformity or appropriateness. Common in academic or business contexts.","formation":"Noun + に即する/に即して/に即した","examples":[{"japanese":"実情に即した対策を立てる必要がある。","romaji":"Jitsujō ni sokushita taisaku wo tateru hitsuyō ga aru.","german":"It is necessary to draw up measures that match the actual situation.","cloze":{"start":2,"answer":"に即した","quiz":{"level":"N1","japanese":"実情に即した対策を立てる必要がある。","german":"It is necessary to draw up measures that match the actual situation.","start":2,"answer":"に即した","acceptedAnswers":["に即した","に即する"],"distractors":[{"text":"に即し","reason":"The stem form cannot modify 対策 attributively here."},{"text":"に即しまする","reason":"る cannot be attached to ます."},{"text":"を即した","reason":"The standard being followed requires に."}]}}},{"japanese":"法律に即して判断すべきだ。","romaji":"Hōritsu ni sokushite handan subeki da.","german":"Judgments should be made in accordance with the law."}],"notes":"Formal. Used in business, legal or academic contexts.","related":["n3-ni-motozuite"]},
{"id":"n1-te-wa-habakaranai","pattern":"～てはばからない","level":"N1","category":"Verben","meaning":"not hesitate to","explanation":"Expresses that someone says or does something without restraint or shame. This structure is often used to describe excessive self-confidence or brazenness. It can have a positive (bold) or negative (presumptuous) connotation.","formation":"Verb て-form + はばからない","examples":[{"japanese":"彼は自分が一番だと言ってはばからない。","cloze":{"start":11,"answer":"てはばからない","quiz":{"level":"N1","japanese":"彼は自分が一番だと言ってはばからない。","german":"He doesn't hesitate to say that he's the best.","start":11,"answer":"てはばからない","acceptedAnswers":["てはばからない"],"distractors":[{"text":"たはばからない","reason":"The connection after 言っ requires the て-form."},{"text":"てはばからないます","reason":"ない does not take an attached ます."},{"text":"てはばかるません","reason":"ません is not attached to the dictionary form."}]}},"romaji":"Kare wa jibun ga ichiban da to itte habakaranai.","german":"He doesn't hesitate to say that he's the best."},{"japanese":"彼女は堂々と自分の意見を述べてはばからない。","cloze":{"start":14,"answer":"てはばからない"},"romaji":"Kanojo wa dōdō to jibun no iken wo nobete habakaranai.","german":"She doesn't shy away from stating her opinion openly."}],"notes":"Can be admiring or critical, depending on the context. Emphasizes a lack of restraint.","related":["temo-ii"]},
{"id":"n1-wo-kinji-enai","pattern":"～を禁じ得ない","level":"N1","category":"Verben","meaning":"cannot help (feeling)","explanation":"Expresses that one cannot suppress a strong feeling. This formal structure is used to describe involuntary emotional reactions. Used mainly with emotion words such as 感動 (being moved), 驚き (surprise), 怒り (anger).","formation":"Emotion noun + を禁じ得ない","examples":[{"japanese":"彼の勇気には感動を禁じ得ない。","cloze":{"start":8,"answer":"を禁じ得ない","quiz":{"level":"N1","japanese":"彼の勇気には感動を禁じ得ない。","german":"I cannot help being moved by his courage.","start":8,"answer":"を禁じ得ない","acceptedAnswers":["を禁じ得ない"],"distractors":[{"text":"を禁じ得ないます","reason":"ない does not take an attached ます."},{"text":"を禁じ得ないました","reason":"The polite past is not formed with ないました."},{"text":"に禁じ得ない","reason":"The feeling that cannot be suppressed requires を."}]}},"romaji":"Kare no yūki ni wa kandō wo kinji enai.","german":"I cannot help being moved by his courage."},{"japanese":"この結果には驚きを禁じ得ない。","cloze":{"start":8,"answer":"を禁じ得ない"},"romaji":"Kono kekka ni wa odoroki wo kinji enai.","german":"I cannot help being surprised by this result."}],"notes":"Very formal. Used mainly with nouns of emotion.","related":["n1-zu-ni-wa-okanai","n2-zu-niwa-irarenai"]},
{"id":"n1-ni-taenai","pattern":"～に堪えない","level":"N1","category":"Verben","meaning":"unbearable / unworthy","explanation":"Has two meanings: 1) a feeling is so strong that one cannot hold it back; 2) something is unbearable or unworthy. This formal structure is interpreted differently depending on the context. With emotion nouns it often means 'cannot hold back'.","formation":"Emotion noun + に堪えない / Verb 辞書形 + に堪えない","examples":[{"japanese":"彼の死は悲しみに堪えない。","cloze":{"start":7,"answer":"に堪えない","quiz":{"level":"N1","japanese":"彼の死は悲しみに堪えない。","german":"His death fills me with unbearable sadness.","start":7,"answer":"に堪えない","acceptedAnswers":["に堪えない"],"distractors":[{"text":"に堪えないます","reason":"ない does not take an attached ます."},{"text":"に堪えないました","reason":"The polite past is not formed with ないました."},{"text":"を堪えない","reason":"This fixed emotional expression requires に."}]}},"romaji":"Kare no shi wa kanashimi ni taenai.","german":"His death fills me with unbearable sadness."},{"japanese":"この光景は見るに堪えない。","cloze":{"start":7,"answer":"に堪えない"},"romaji":"Kono kōkei wa miru ni taenai.","german":"This sight is unbearable to look at."}],"notes":"Two meanings: 1) cannot hold back a feeling, 2) to be unbearable.","related":["n1-te-wa-kanawanai","n1-wo-kinji-enai"]},
{"id":"n1-wo-yoginaku-saseru","pattern":"～を余儀なくさせる","level":"N1","category":"Verben","meaning":"to force to (active)","explanation":"Expresses that external circumstances force someone to do something. This formal structure emphasizes that there is no other choice. Often used in news or formal reports to describe involuntary actions.","formation":"Noun + を余儀なくさせる / Verb 辞書形 + ことを余儀なくさせる","examples":[{"japanese":"台風は多くの人々に避難を余儀なくさせた。","romaji":"Taifū wa ōku no hitobito ni hinan wo yoginaku saseta.","german":"The typhoon forced many people to evacuate.","cloze":{"start":11,"answer":"を余儀なくさせた","quiz":{"level":"N1","japanese":"台風は多くの人々に避難を余儀なくさせた。","german":"The typhoon forced many people to evacuate.","start":11,"answer":"を余儀なくさせた","acceptedAnswers":["を余儀なくさせた"],"distractors":[{"text":"を余儀なくさせるました","reason":"The polite past requires the verb stem."},{"text":"を余儀なくさせたます","reason":"ます cannot be attached to the plain past."},{"text":"を余儀なくさせませんない","reason":"The negative endings cannot be combined like this."}]}}},{"japanese":"不況は会社に人員削減を余儀なくさせている。","romaji":"Fukyō wa kaisha ni jin'in sakugen wo yoginaku sasete iru.","german":"The recession is forcing the company to cut staff."}],"notes":"Formal. Active form of を余儀なくされる. Emphasizes external compulsion.","related":["n1-wo-yoginaku-sareru","n4-saserareru"]},
{"id":"n1-towa","pattern":"～とは","level":"N1","category":"Satzstrukturen","meaning":"that ... (surprise/definition)","explanation":"Expresses surprise, indignation or disbelief about a fact. Also used to define something or explain what something means.","formation":"Sentence + とは\nフレーズ + とは","examples":[{"japanese":"彼がそんなことをするとは思わなかった。","cloze":{"start":10,"answer":"とは","quiz":{"level":"N1","japanese":"彼がそんなことをするとは思わなかった。","german":"I never thought he would do something like that.","start":10,"answer":"とは","acceptedAnswers":["とは","と"],"distractors":[{"text":"をは","reason":"The content of the thought requires と instead of を."},{"text":"とはな","reason":"な cannot be attached here."},{"text":"とはます","reason":"ます cannot be attached to は."}]}},"romaji":"Kare ga sonna koto wo suru to wa omowanakatta.","german":"I never thought he would do something like that."},{"japanese":"まさか彼女が辞めるとは驚きだ。","cloze":{"start":9,"answer":"とは"},"romaji":"Masaka kanojo ga yameru to wa odoroki da.","german":"It's a surprise that she's actually quitting."}],"notes":"The 'は' after 'と' emphasizes the statement and often expresses astonishment.","related":["n1-tomo","n4-nado","n3-to-iu-no-wa"]},
{"id":"n1-tobakarini","pattern":"～とばかりに","level":"N1","category":"Satzstrukturen","meaning":"as if to say, as though","explanation":"Describes an action or state as if the person were saying or expressing something specific. The actual words are not spoken, but the action conveys this meaning.","formation":"普通形 + とばかりに\nフレーズ + とばかりに","examples":[{"japanese":"彼は「任せろ」とばかりに胸をたたいた。","cloze":{"start":7,"answer":"とばかりに","quiz":{"level":"N1","japanese":"彼は「任せろ」とばかりに胸をたたいた。","german":"He thumped his chest as if to say, 'Leave it to me.'","start":7,"answer":"とばかりに","acceptedAnswers":["とばかりに"],"distractors":[{"text":"とばかりを","reason":"を does not form an adverbial link here."},{"text":"とばかりな","reason":"な does not connect to 胸をたたいた here."},{"text":"とばかります","reason":"ます cannot be attached directly to ばかり."}]}},"romaji":"Kare wa \"makasero\" to bakari ni mune o tataita.","german":"He thumped his chest as if to say, 'Leave it to me.'"},{"japanese":"子供たちは待ってましたとばかりに外へ飛び出した。","cloze":{"start":11,"answer":"とばかりに"},"romaji":"Kodomotachi wa mattemashita to bakari ni soto e tobidashita.","german":"The children rushed outside as if they had been waiting for this moment."}],"notes":"Often used with verbs of movement or with gestures.","related":["n2-ka-no-you-ni","n4-you-ni-purpose"]},
{"id":"n1-tomonaku-tomonashini","pattern":"～ともなく/ともなしに","level":"N1","category":"Satzstrukturen","meaning":"without any particular intention","explanation":"Expresses that an action is carried out without a clear intention or particular goal. The person acts unconsciously or aimlessly.","formation":"Verb ます-form + ともなく/ともなしに\n聞く → 聞くともなく","examples":[{"japanese":"テレビを見るともなく見ていた。","cloze":{"start":6,"answer":"ともなく","quiz":{"level":"N1","japanese":"テレビを見るともなく見ていた。","german":"I was absent-mindedly watching TV without really paying attention.","start":6,"answer":"ともなく","acceptedAnswers":["ともなく","ともなしに"],"distractors":[{"text":"ともないます","reason":"ない does not take an attached ます."},{"text":"ともなくな","reason":"な cannot be attached here."},{"text":"ともなくを","reason":"を does not form a link expressing an accompanying circumstance here."}]}},"romaji":"Terebi wo miru to mo naku mite ita.","german":"I was absent-mindedly watching TV without really paying attention."},{"japanese":"空を眺めるともなしに眺めていた。","cloze":{"start":5,"answer":"ともなしに"},"romaji":"Sora wo nagameru to mo nashi ni nagamete ita.","german":"I was gazing at the sky without really looking at it."},{"japanese":"どこともなく歩き続けた。","romaji":"Doko to mo naku aruki tsuzuketa.","german":"I kept walking with no particular destination."},{"japanese":"何ともなく彼女のことを思い出した。","romaji":"Nani to mo naku kanojo no koto wo omoidashita.","german":"For no particular reason, I found myself remembering her."}],"notes":"Emphasizes the absence of intention or awareness.","related":[],"legacyIds":["n1-tomonaku2"]},
{"id":"n1-naimonodemonai","pattern":"～ないものでもない","level":"N1","category":"Satzstrukturen","meaning":"it's not that one couldn't","explanation":"A double negative expressing that something is possible, albeit with reservations. There is a certain possibility or willingness.","formation":"Verb ない-form + ものでもない","examples":[{"japanese":"頼まれれば、手伝わないものでもない。","cloze":{"start":9,"answer":"ないものでもない","quiz":{"level":"N1","japanese":"頼まれれば、手伝わないものでもない。","german":"If I'm asked, it's not as if I wouldn't help.","start":9,"answer":"ないものでもない","acceptedAnswers":["ないものでもない"],"distractors":[{"text":"ないものでもないます","reason":"ない does not take an attached ます."},{"text":"ないものでもないました","reason":"The polite past is not formed with ないました."},{"text":"ないものをない","reason":"This expression requires the nominal connection でも."}]}},"romaji":"Tanomarereba, tetsudawanai mono de mo nai.","german":"If I'm asked, it's not as if I wouldn't help."},{"japanese":"条件次第では、考えないものでもない。","cloze":{"start":9,"answer":"ないものでもない"},"romaji":"Jōken shidai de wa, kangaenai mono demo nai.","german":"Depending on the conditions, it's not out of the question that I'll consider it."}],"notes":"Expresses reserved agreement or a reserved possibility.","related":["n1-naku-mo-nai","n3-nai-koto-wa-nai"]},
{"id":"n1-nakushite","pattern":"～なくして(は)","level":"N1","category":"Satzstrukturen","meaning":"without ... (it is impossible)","explanation":"Expresses that something is an indispensable condition. Without this condition, the result cannot be achieved.","formation":"Noun + なくして(は)\nVerb ない-form (く) + なくして(は)","examples":[{"japanese":"努力なくして成功はない。","romaji":"Doryoku nakushite seikō wa nai.","german":"Without effort there is no success.","cloze":{"start":2,"answer":"なくして","quiz":{"level":"N1","japanese":"努力なくして成功はない。","german":"Without effort there is no success.","start":2,"answer":"なくして","acceptedAnswers":["なくして","なしに"],"distractors":[{"text":"なくする","reason":"The dictionary form does not form a negative link expressing an accompanying circumstance here."},{"text":"なくします","reason":"The finite form does not form a link here."},{"text":"なくしてな","reason":"な cannot be attached here."}]}}},{"japanese":"信頼なくしては、良い関係は築けない。","romaji":"Shinrai nakushite wa, yoi kankei wa kizukenai.","german":"Without trust, you can't build a good relationship."}],"notes":"A formal expression, often used in speeches or written language.","related":["n1-nashi-ni-nakushite","n3-nai-koto-ni-wa"]},
{"id":"n1-naraizashirazu","pattern":"～ならいざしらず","level":"N1","category":"Satzstrukturen","meaning":"if it were ..., that might be one thing, but","explanation":"Concedes that something would be understandable in one case, but expresses that it is not acceptable or understandable in the present case.","formation":"Noun + ならいざしらず\n普通形 + ならいざしらず","examples":[{"japanese":"子供ならいざしらず、大人がそんなことをするとは。","cloze":{"start":2,"answer":"ならいざしらず","quiz":{"level":"N1","japanese":"子供ならいざしらず、大人がそんなことをするとは。","german":"If it were a child, that would be one thing, but for an adult to do something like that!","start":2,"answer":"ならいざしらず","acceptedAnswers":["ならいざしらず"],"distractors":[{"text":"ならいざしらずな","reason":"な cannot be attached here."},{"text":"ならいざしらずを","reason":"を does not form a contrastive link here."},{"text":"ならいざしらずます","reason":"ます cannot be attached to ず."}]}},"romaji":"Kodomo nara iza shirazu, otona ga sonna koto wo suru to wa.","german":"If it were a child, that would be one thing, but for an adult to do something like that!"},{"japanese":"昔ならいざしらず、今の時代にそれは通用しない。","cloze":{"start":1,"answer":"ならいざしらず"},"romaji":"Mukashi nara iza shirazu, ima no jidai ni sore wa tsūyō shinai.","german":"In the old days that might have been fine, but in this day and age it won't work."}],"notes":"Expresses a strong contrast between two situations.","related":["n1-naramad ashimo"]},
{"id":"n1-nari","pattern":"～なり","level":"N1","category":"Satzstrukturen","meaning":"as soon as, the moment","explanation":"Expresses that one action follows immediately after another. Often with a surprising or unexpected result.","formation":"Verb 辞書形 + なり\nVerb た-form + なり","examples":[{"japanese":"家に帰るなり、ベッドに倒れ込んだ。","cloze":{"start":4,"answer":"なり","quiz":{"level":"N1","japanese":"家に帰るなり、ベッドに倒れ込んだ。","german":"As soon as I got home, I collapsed onto the bed.","start":4,"answer":"なり","acceptedAnswers":["なり","や否や"],"distractors":[{"text":"なりまする","reason":"る cannot be attached to ます."},{"text":"なりな","reason":"な cannot be attached here."},{"text":"なりを","reason":"を does not form a time link here."}]}},"romaji":"Ie ni kaeru nari, beddo ni taorekon da.","german":"As soon as I got home, I collapsed onto the bed."},{"japanese":"彼は会議室に入るなり、怒鳴り始めた。","cloze":{"start":8,"answer":"なり"},"romaji":"Kare wa kaigishitsu ni hairu nari, donari hajimeta.","german":"The moment he entered the conference room, he started shouting."}],"notes":"More literary than やいなや; emphasizes immediacy.","related":["n1-ya-inaya","n3-totan","n1-sobakara","n2-nari-ni","n1-ga-hayai-ka"]},
{"id":"n1-nari-nari","pattern":"～なり～なり","level":"N1","category":"Satzstrukturen","meaning":"either ... or ... (suggestions)","explanation":"Gives examples or alternatives that serve as possibilities. The speaker suggests choosing one of several options.","formation":"Verb 辞書形 + なり + Verb 辞書形 + なり\nNoun + なり + Noun + なり","examples":[{"japanese":"電話するなりメールするなりして連絡してください。","romaji":"Denwa suru nari mēru suru nari shite renraku shite kudasai.","german":"Please get in touch, whether by phone or by email.","cloze":{"start":4,"answer":"なり","quiz":{"level":"N1","japanese":"電話するなりメールするなりして連絡してください。","german":"Please get in touch, whether by phone or by email.","start":4,"answer":"なり","acceptedAnswers":["なり"],"distractors":[{"text":"なりを","reason":"を does not form a link for alternatives here."},{"text":"なりな","reason":"な cannot be attached here."},{"text":"なりまする","reason":"る cannot be attached to ます."}]}}},{"japanese":"本を読むなり音楽を聴くなりして時間を過ごした。","romaji":"Hon wo yomu nari ongaku wo kiku nari shite jikan wo sugoshita.","german":"I passed the time reading books or listening to music."}],"notes":"Expresses that there are several equally valid options.","related":["n4-toka","ka","n1-nari-tomo"]},
{"id":"n1-niaramajiki","pattern":"～にあるまじき","level":"N1","category":"Satzstrukturen","meaning":"unworthy of, inappropriate for","explanation":"Expresses that an action or behavior is inappropriate or unworthy for a particular position or role. A very formal and critical expression.","formation":"Noun + にあるまじき + Noun","examples":[{"japanese":"それは教師にあるまじき行為だ。","cloze":{"start":5,"answer":"にあるまじき","quiz":{"level":"N1","japanese":"それは教師にあるまじき行為だ。","german":"That is behavior unworthy of a teacher.","start":5,"answer":"にあるまじき","acceptedAnswers":["にあるまじき"],"distractors":[{"text":"にあるまじく","reason":"The adverbial form cannot modify 行為 attributively here."},{"text":"にあるまじきな","reason":"No additional な comes before 行為 here."},{"text":"にあるまじきます","reason":"ます cannot be attached directly to まじき."}]}},"romaji":"Sore wa kyōshi ni arumajiki kōi da.","german":"That is behavior unworthy of a teacher."},{"japanese":"医者にあるまじき発言をした。","cloze":{"start":2,"answer":"にあるまじき"},"romaji":"Isha ni arumajiki hatsugen o shita.","german":"He made a remark inappropriate for a doctor."}],"notes":"Very formal; often used in criticism or official statements.","related":[]},
{"id":"n1-nikakotsukete","pattern":"～にかこつけて","level":"N1","category":"Satzstrukturen","meaning":"under the pretext of","explanation":"Expresses that someone uses a pretext or excuse to do something they actually want to do. The reason given is not the real reason.","formation":"Noun + にかこつけて\nVerb 辞書形/た-form + のにかこつけて","examples":[{"japanese":"仕事にかこつけて、彼女に会いに行った。","cloze":{"start":2,"answer":"にかこつけて","quiz":{"level":"N1","japanese":"仕事にかこつけて、彼女に会いに行った。","german":"Under the pretext of work, I went to see her.","start":2,"answer":"にかこつけて","acceptedAnswers":["にかこつけて"],"distractors":[{"text":"をかこつけて","reason":"In this expression the pretext requires に."},{"text":"にかこつけた","reason":"The attributive past does not form a link here."},{"text":"にかこつけます","reason":"The finite form does not form a link here."}]}},"romaji":"Shigoto ni kakotsukete, kanojo ni ai ni itta.","german":"Under the pretext of work, I went to see her."},{"japanese":"体調不良にかこつけて、会議を欠席した。","cloze":{"start":4,"answer":"にかこつけて"},"romaji":"Taichō furyō ni kakotsukete, kaigi wo kesseki shita.","german":"Under the pretext of feeling unwell, I skipped the meeting."}],"notes":"Often has a negative connotation, implying dishonesty.","related":[]},
{"id":"n1-nikamakete","pattern":"～にかまけて","level":"N1","category":"Satzstrukturen","meaning":"to be distracted by, to be absorbed in","explanation":"Expresses that one is so busy with something that one neglects other important things. Has a negative connotation.","formation":"Noun + にかまけて","examples":[{"japanese":"遊びにかまけて、勉強を怠った。","cloze":{"start":2,"answer":"にかまけて","quiz":{"level":"N1","japanese":"遊びにかまけて、勉強を怠った。","german":"I got caught up in having fun and neglected my studies.","start":2,"answer":"にかまけて","acceptedAnswers":["にかまけて"],"distractors":[{"text":"をかまけて","reason":"The thing one is occupied with requires に."},{"text":"にかまけた","reason":"The attributive past does not form a link here."},{"text":"にかまけます","reason":"The finite form does not form a link here."}]}},"romaji":"Asobi ni kamakete, benkyō wo okotatta.","german":"I got caught up in having fun and neglected my studies."},{"japanese":"仕事にかまけて、家族との時間を持たなかった。","cloze":{"start":2,"answer":"にかまけて"},"romaji":"Shigoto ni kamakete, kazoku to no jikan wo motanakatta.","german":"I was so wrapped up in work that I didn't spend time with my family."}],"notes":"Implies criticism of or regret about the neglect.","related":[]},
{"id":"n1-nishitehajimete","pattern":"～にして初めて","level":"N1","category":"Satzstrukturen","meaning":"only when/after, only through","explanation":"Emphasizes that something only becomes possible or apparent after a certain event or under certain circumstances. Underlines the importance of the precondition.","formation":"Noun + にして初めて\nVerb て-form + にして初めて","examples":[{"japanese":"失敗にして初めて、その大切さが分かった。","cloze":{"start":2,"answer":"にして初めて","quiz":{"level":"N1","japanese":"失敗にして初めて、その大切さが分かった。","german":"Only through failure did I understand how important it was.","start":2,"answer":"にして初めて","acceptedAnswers":["にして初めて"],"distractors":[{"text":"にして初めた","reason":"The finite past does not form a link here."},{"text":"にして初めます","reason":"The finite polite form does not form a link here."},{"text":"にする初めて","reason":"The connection requires the て-form."}]}},"romaji":"Shippai ni shite hajimete, sono taisetsusa ga wakatta.","german":"Only through failure did I understand how important it was."},{"japanese":"親になって初めて、親の気持ちが理解できた。","romaji":"Oya ni natte hajimete, oya no kimochi ga rikai dekita.","german":"Only when I became a parent could I understand how my parents felt."}],"notes":"Emphasizes the turning point or the decisive realization.","related":["n2-te-hajimete"]},
{"id":"n1-nisura","pattern":"～にすら","level":"N1","category":"Satzstrukturen","meaning":"even to, even for","explanation":"Emphasizes that something applies even in an unexpected or extreme case. Stronger than a simple 'さえ'.","formation":"Noun + にすら","examples":[{"japanese":"彼は親にすら本当のことを言わなかった。","cloze":{"start":3,"answer":"にすら","quiz":{"level":"N1","japanese":"彼は親にすら本当のことを言わなかった。","german":"He didn't tell the truth even to his parents.","start":3,"answer":"にすら","acceptedAnswers":["にすら","にさえ","にも"],"distractors":[{"text":"にすらを","reason":"を cannot follow the recipient marker here."},{"text":"にすらな","reason":"な cannot be attached here."},{"text":"にすらます","reason":"ます cannot be attached to すら."}]}},"romaji":"Kare wa oya ni sura hontō no koto wo iwanakatta.","german":"He didn't tell the truth even to his parents."},{"japanese":"この問題は専門家にすら解けない。","cloze":{"start":8,"answer":"にすら"},"romaji":"Kono mondai wa senmonka ni sura tokenai.","german":"Even experts can't solve this problem."}],"notes":"More literary and formal than さえ or でさえ.","related":["n1-sura","n1-desura"]},
{"id":"n1-ninaku","pattern":"～にない","level":"N1","category":"Satzstrukturen","meaning":"unusual for, rare in","explanation":"Expresses that something is unusual or atypical for a person or group. Emphasizes how exceptional it is.","formation":"Noun + にない + Noun","examples":[{"japanese":"彼にない真剣な表情だった。","cloze":{"start":1,"answer":"にない","quiz":{"level":"N1","japanese":"彼にない真剣な表情だった。","german":"It was an unusually serious expression for him.","start":1,"answer":"にない","acceptedAnswers":["にない"],"distractors":[{"text":"にないます","reason":"ない does not take an attached ます."},{"text":"にないな","reason":"No additional な comes before 真剣な here."},{"text":"をない","reason":"ない does not require an object particle here."}]}},"romaji":"Kare ni nai shinken na hyōjō datta.","german":"It was an unusually serious expression for him."},{"japanese":"彼女にない優しさを見せた。","cloze":{"start":2,"answer":"にない"},"romaji":"Kanojo ni nai yasashisa wo miseta.","german":"She showed a kindness that was untypical of her."}],"notes":"Emphasizes the contrast with normal behavior or the normal state.","related":["n4-rashii-adj","n1-niaramajiki"]},
{"id":"n1-nioyo banai","pattern":"～には及ばない","level":"N1","category":"Satzstrukturen","meaning":"there is no need, not necessary","explanation":"Expresses that something is not necessary or that one does not have to do something. Often used to reassure someone or dispel concerns.","formation":"Verb 辞書形 + には及ばない\nNoun + には及ばない","examples":[{"japanese":"心配するには及ばない。","cloze":{"start":4,"answer":"には及ばない","quiz":{"level":"N1","japanese":"心配するには及ばない。","german":"There's no need to worry.","start":4,"answer":"には及ばない","acceptedAnswers":["には及ばない"],"distractors":[{"text":"には及ばないます","reason":"ない does not take an attached ます."},{"text":"には及ぶません","reason":"ません is not attached to the dictionary form."},{"text":"には及ばないました","reason":"The polite past is not formed with ないました."}]}},"romaji":"Shinpai suru ni wa oyobanai.","german":"There's no need to worry."},{"japanese":"謝罪には及びません。","romaji":"Shazai ni wa oyobimasen.","german":"There is no need for an apology."}],"notes":"A formal expression, often used in polite contexts.","related":["nakutemo-ii","n2-koto-wa-nai"]},
{"id":"n1-niiwasereb a","pattern":"～に言わせれば","level":"N1","category":"Satzstrukturen","meaning":"if you ask ..., in the opinion of","explanation":"Introduces the opinion or perspective of a particular person. Emphasizes that this is that person's subjective view.","formation":"Person + に言わせれば\nPerson + に言わせると","examples":[{"japanese":"専門家に言わせれば、これは危険だそうだ。","cloze":{"start":3,"answer":"に言わせれば","quiz":{"level":"N1","japanese":"専門家に言わせれば、これは危険だそうだ。","german":"If you ask the experts, this is apparently dangerous.","start":3,"answer":"に言わせれば","acceptedAnswers":["に言わせれば"],"distractors":[{"text":"に言わせるれば","reason":"The conditional is 言わせれば."},{"text":"を言わせれば","reason":"The person whose judgment is given requires に here."},{"text":"に言わせますば","reason":"The conditional is not formed with ますば."}]}},"romaji":"Senmonka ni iwasereba, kore wa kiken da sō da.","german":"If you ask the experts, this is apparently dangerous."},{"japanese":"彼女に言わせれば、私が悪いらしい。","cloze":{"start":2,"answer":"に言わせれば"},"romaji":"Kanojo ni iwasereba, watashi ga warui rashii.","german":"According to her, it's apparently my fault."}],"notes":"Can be used to distance oneself from the opinion expressed.","related":["n4-ni-yoru-to","n2-kara-miru-to"]},
{"id":"n1-kiwamarinai","pattern":"～極まりない/極まる","level":"N1","category":"Satzstrukturen","meaning":"extremely, utterly, most","explanation":"Expresses that something has reached an extreme degree. Often used with na-adjectives to express strong feelings or states.","formation":"な-adjective + 極まりない/極まる\nNoun + 極まりない/極まる","examples":[{"japanese":"それは失礼極まりない行為だ。","cloze":{"start":5,"answer":"極まりない","quiz":{"level":"N1","japanese":"それは失礼極まりない行為だ。","german":"That is extremely rude behavior.","start":5,"answer":"極まりない","acceptedAnswers":["極まりない","極まる"],"distractors":[{"text":"極まりないます","reason":"ない does not take an attached ます."},{"text":"極まりないな","reason":"No additional な comes before 行為 here."},{"text":"極まりなく","reason":"The adverbial form does not modify 行為 attributively here."}]}},"romaji":"Sore wa shitsurei kiwamarinai kōi da.","german":"That is extremely rude behavior."},{"japanese":"危険極まる状況に陥った。","cloze":{"start":2,"answer":"極まる"},"romaji":"Kiken kiwamaru jōkyō ni ochiitta.","german":"We ended up in an extremely dangerous situation."},{"japanese":"危険極まりない計画だ。","cloze":{"start":2,"answer":"極まりない"},"romaji":"Kiken kiwamarinai keikaku da.","german":"It's an extremely dangerous plan."},{"japanese":"不便極まりない場所に住んでいる。","cloze":{"start":2,"answer":"極まりない"},"romaji":"Fuben kiwamarinai basho ni sunde iru.","german":"I live in an extremely inconvenient place."}],"notes":"A very formal expression, often used in written language.","related":["n1-kagirida","n2-ni-mo-hodo-ga-aru","n1-ttara-nai"],"legacyIds":["n1-kiwamari-nai"]},
{"id":"n1-sura","pattern":"～すら","level":"N1","category":"Satzstrukturen","meaning":"even","explanation":"Emphasizes that something applies even in an unexpected case. More literary and formal than さえ.","formation":"Noun + すら","examples":[{"japanese":"彼は名前すら覚えていない。","cloze":{"start":4,"answer":"すら","quiz":{"level":"N1","japanese":"彼は名前すら覚えていない。","german":"He doesn't even remember the name.","start":4,"answer":"すら","acceptedAnswers":["すら","さえ","も"],"distractors":[{"text":"すらをな","reason":"This particle combination does not connect to 覚えていない here."},{"text":"すらな","reason":"な cannot be attached here."},{"text":"すらます","reason":"ます cannot be attached directly to すら."}]}},"romaji":"Kare wa namae sura oboete inai.","german":"He doesn't even remember the name."},{"japanese":"水すら飲めない状況だった。","cloze":{"start":1,"answer":"すら"},"romaji":"Mizu sura nomenai jōkyō datta.","german":"It was a situation where you couldn't even drink water."}],"notes":"Literary style, often used in written language.","related":["n4-sae","n1-desura","mo"]},
{"id":"n1-dani","pattern":"～だに","level":"N1","category":"Satzstrukturen","meaning":"merely (thinking of it)","explanation":"A very literary expression emphasizing that merely imagining something provokes a strong reaction. Used almost exclusively in written language.","formation":"Verb 辞書形 + だに\nNoun + だに","examples":[{"japanese":"想像するだに恐ろしい。","cloze":{"start":4,"answer":"だに","quiz":{"level":"N1","japanese":"想像するだに恐ろしい。","german":"Just imagining it is terrifying.","start":4,"answer":"だに","acceptedAnswers":["だに"],"distractors":[{"text":"だにを","reason":"を does not form an adverbial link here."},{"text":"だにな","reason":"な cannot be attached here."},{"text":"だにます","reason":"ます cannot be attached directly to だに."}]}},"romaji":"Sōzō suru dani osoroshii.","german":"Just imagining it is terrifying."},{"japanese":"思い出すだに腹が立つ。","cloze":{"start":4,"answer":"だに"},"romaji":"Omoidasu dani hara ga tatsu.","german":"Just remembering it makes me angry."}],"notes":"Very literary and archaic; rare in modern language.","related":["n1-sura","n4-sae"]},
{"id":"n1-taru","pattern":"～たる","level":"N1","category":"Satzstrukturen","meaning":"as (position/status)","explanation":"Expresses a person's status or position. Used to emphasize the duties or expectations associated with that position.","formation":"Noun + たる + Noun","examples":[{"japanese":"教師たる者、生徒の模範でなければならない。","cloze":{"start":2,"answer":"たる","quiz":{"level":"N1","japanese":"教師たる者、生徒の模範でなければならない。","german":"Anyone who is a teacher must be a role model for their students.","start":2,"answer":"たる","acceptedAnswers":["たる","である"],"distractors":[{"text":"たりまする","reason":"る cannot be attached to ます."},{"text":"たるな","reason":"No additional な comes before 者 here."},{"text":"たるを","reason":"を cannot connect attributively to 者 here."}]}},"romaji":"Kyōshi taru mono, seito no mohan de nakereba naranai.","german":"Anyone who is a teacher must be a role model for their students."},{"japanese":"リーダーたる者、責任を持つべきだ。","cloze":{"start":4,"answer":"たる"},"romaji":"Rīdā taru mono, sekinin wo motsu beki da.","german":"Anyone who is a leader should take responsibility."}],"notes":"Very formal; often used in moral or philosophical statements.","related":["desu","n4-toshite"]},
{"id":"n1-taruya","pattern":"～たるや","level":"N1","category":"Satzstrukturen","meaning":"as for ... (emphatic)","explanation":"Emphatically highlights a particular topic, often followed by an extreme description or evaluation. A very literary expression.","formation":"Noun + たるや","examples":[{"japanese":"その美しさたるや、言葉では表せない。","cloze":{"start":5,"answer":"たるや","quiz":{"level":"N1","japanese":"その美しさたるや、言葉では表せない。","german":"As for its beauty, it is beyond words.","start":5,"answer":"たるや","acceptedAnswers":["たるや"],"distractors":[{"text":"たるやな","reason":"な cannot be attached here."},{"text":"たるやを","reason":"を does not form a topic link here."},{"text":"たるやます","reason":"ます cannot be attached directly to たるや."}]}},"romaji":"Sono utsukushisa taruya, kotoba de wa arawasenai.","german":"As for its beauty, it is beyond words."},{"japanese":"彼の怠慢たるや、目に余るものがある。","cloze":{"start":4,"answer":"たるや"},"romaji":"Kare no taiman taruya, me ni amaru mono ga aru.","german":"As for his negligence, it is beyond what can be tolerated."}],"notes":"Very literary and formal; not used in modern colloquial speech.","related":["n1-to-kitara"]},
{"id":"n1-tsu-tsu","pattern":"～つ～つ","level":"N1","category":"Satzstrukturen","meaning":"alternately (two actions)","explanation":"A very literary and archaic expression describing two actions being performed alternately. Used almost exclusively in classical texts.","formation":"Verb ます-stem + つ + Verb ます-stem + つ","examples":[{"japanese":"行きつ戻りつしながら進んだ。","romaji":"Ikitsu modoritsu shinagara susunda.","german":"We moved on, going back and forth.","cloze":{"start":0,"answer":"行きつ戻りつ","quiz":{"level":"N1","japanese":"行きつ戻りつしながら進んだ。","german":"We moved on, going back and forth.","start":0,"answer":"行きつ戻りつ","acceptedAnswers":["行きつ戻りつ"],"distractors":[{"text":"行くつ戻るつ","reason":"つ attaches to the verb stems 行き and 戻り."},{"text":"行きつ戻りますつ","reason":"つ does not attach to the polite form."},{"text":"行ったつ戻ったつ","reason":"The expression uses verb stems, not past forms."}]}}},{"japanese":"泣きつ笑いつ、感情が揺れ動いた。","romaji":"Nakitsu waraitsu, kanjō ga yure ugoita.","german":"Now crying, now laughing, emotions swung back and forth."}],"notes":"Very archaic; hardly used in modern language.","related":["tari-tari","nagara"]},
{"id":"n1-denakutena ndarou","pattern":"～でなくてなんだろう","level":"N1","category":"Satzstrukturen","meaning":"if not X, then what; nothing other than X","explanation":"A rhetorical question that strongly emphasizes that something is definitely the case. Expresses conviction or indignation.","formation":"Noun + でなくてなんだろう\nな-adjective + でなくてなんだろう","examples":[{"japanese":"これが奇跡でなくてなんだろう。","cloze":{"start":5,"answer":"でなくてなんだろう","quiz":{"level":"N1","japanese":"これが奇跡でなくてなんだろう。","german":"If this isn't a miracle, what is?","start":5,"answer":"でなくてなんだろう","acceptedAnswers":["でなくてなんだろう"],"distractors":[{"text":"でなくてなんだろうます","reason":"ます cannot attach to だろう."},{"text":"でなくてなんをだろう","reason":"を cannot stand before だろう here."},{"text":"でないてなんだろう","reason":"The connective form of ない is なくて."}]}},"romaji":"Kore ga kiseki de nakute nan darō.","german":"If this isn't a miracle, what is?"},{"japanese":"それは裏切りでなくてなんだろうか。","cloze":{"start":6,"answer":"でなくてなんだろう"},"romaji":"Sore wa uragiri de nakute nan darō ka.","german":"If that isn't betrayal, what is?"}],"notes":"Expresses strong conviction or rhetorical emphasis.","related":["n2-ni-hoka-naranai"]},
{"id":"n1-dewaaru maika","pattern":"～ではあるまいか","level":"N1","category":"Satzstrukturen","meaning":"isn't it the case that; could it not be that","explanation":"Expresses a cautious supposition or speculation. The speaker believes that something is probably the case.","formation":"普通形 + のではあるまいか\nNoun/な-adjective + ではあるまいか","examples":[{"japanese":"彼が犯人ではあるまいか。","cloze":{"start":4,"answer":"ではあるまいか","quiz":{"level":"N1","japanese":"彼が犯人ではあるまいか。","german":"Might he not be the culprit?","start":4,"answer":"ではあるまいか","acceptedAnswers":["ではあるまいか"],"distractors":[{"text":"ではあるまいかます","reason":"ます cannot attach to the question particle."},{"text":"ではあるまいなか","reason":"The rhetorical question does not need な."},{"text":"ではあるませんか","reason":"ません does not attach to the dictionary form."}]}},"romaji":"Kare ga hannin de wa arumai ka.","german":"Might he not be the culprit?"},{"japanese":"これが最善の方法ではあるまいか。","cloze":{"start":8,"answer":"ではあるまいか"},"romaji":"Kore ga saizen no hōhō de wa arumai ka.","german":"Isn't this the best way?"}],"notes":"A formal, literary expression, often found in written language.","related":[]},
{"id":"n1-tomo","pattern":"～とも","level":"N1","category":"Satzstrukturen","meaning":"even if, even though (literary)","explanation":"A literary expression for \"even if\" or \"even though\". Used mainly in formal or literary texts.","formation":"Verb 辞書形 + とも\nい-adjective + とも","examples":[{"japanese":"雨が降ろうとも、行きます。","cloze":{"start":5,"answer":"とも","quiz":{"level":"N1","japanese":"雨が降ろうとも、行きます。","german":"Even if it rains, I will go.","start":5,"answer":"とも","acceptedAnswers":["とも","と"],"distractors":[{"text":"ともを","reason":"を does not form a concessive link here."},{"text":"ともな","reason":"な cannot be attached here."},{"text":"ともます","reason":"ます cannot attach directly to とも."}]}},"romaji":"Ame ga furō tomo, ikimasu.","german":"Even if it rains, I will go."},{"japanese":"困難であろうとも、挑戦する。","cloze":{"start":6,"answer":"とも"},"romaji":"Konnan de arō tomo, chōsen suru.","german":"Even if it is difficult, I will take on the challenge."}],"notes":"Very literary; rare in spoken language.","related":["temo","n1-de-are"]},
{"id":"n1-naitomok agiranai","pattern":"～ないとも限らない","level":"N1","category":"Satzstrukturen","meaning":"it's not impossible that; it could be that","explanation":"A double negative expressing that something is possible, even if it seems unlikely. Leaves room for possibility.","formation":"Verb ない-form + とも限らない","examples":[{"japanese":"彼が来ないとも限らない。","cloze":{"start":3,"answer":"ないとも限らない","quiz":{"level":"N1","japanese":"彼が来ないとも限らない。","german":"It's not impossible that he'll come.","start":3,"answer":"ないとも限らない","acceptedAnswers":["ないとも限らない"],"distractors":[{"text":"ないとも限らないます","reason":"ない does not take an attached ます."},{"text":"ないとも限るません","reason":"ません does not attach to the dictionary form."},{"text":"ないとも限らないました","reason":"The polite past is not formed with ないました."}]}},"romaji":"Kare ga konai to mo kagiranai.","german":"It's not impossible that he'll come."},{"japanese":"失敗しないとも限らないから、注意が必要だ。","cloze":{"start":3,"answer":"ないとも限らない"},"romaji":"Shippai shinai to mo kagiranai kara, chūi ga hitsuyō da.","german":"We might fail, so we need to be careful."}],"notes":"Expresses cautious possibility or a warning.","related":["kamoshirenai"]},
{"id":"n1-naramad ashimo","pattern":"～ならまだしも","level":"N1","category":"Satzstrukturen","meaning":"if it were ..., it would still be understandable, but","explanation":"Concedes that something would be understandable or acceptable in one case, but expresses that this does not apply to the case at hand.","formation":"Noun + ならまだしも\n普通形 + ならまだしも","examples":[{"japanese":"若者ならまだしも、大人がそんなことをするとは。","cloze":{"start":2,"answer":"ならまだしも","quiz":{"level":"N1","japanese":"若者ならまだしも、大人がそんなことをするとは。","german":"If it were a young person, it would be understandable, but for an adult to do something like that!","start":2,"answer":"ならまだしも","acceptedAnswers":["ならまだしも"],"distractors":[{"text":"ならまだしもな","reason":"な cannot be attached here."},{"text":"ならまだしもを","reason":"を does not form a contrastive link here."},{"text":"ならまだしもます","reason":"ます cannot attach to も."}]}},"romaji":"Wakamono nara madashimo, otona ga sonna koto wo suru to wa.","german":"If it were a young person, it would be understandable, but for an adult to do something like that!"},{"japanese":"一度ならまだしも、何度も同じ失敗をするのは問題だ。","cloze":{"start":2,"answer":"ならまだしも"},"romaji":"Ichido nara madashimo, nando mo onaji shippai wo suru no wa mondai da.","german":"Once would be understandable, but making the same mistake again and again is a problem."}],"notes":"Expresses a contrast with mild criticism.","related":["n1-naraizashirazu"]},
{"id":"n1-nishitatokoro de","pattern":"～にしたところで/にしたって","level":"N1","category":"Satzstrukturen","meaning":"even if, even though","explanation":"Expresses that even under the assumed condition, the result would be no different. Emphasizes that the condition makes no difference.","formation":"Noun + にしたところで/にしたって\n普通形 + にしたところで","examples":[{"japanese":"彼にしたところで、この問題は解けないだろう。","cloze":{"start":1,"answer":"にしたところで","quiz":{"level":"N1","japanese":"彼にしたところで、この問題は解けないだろう。","german":"Even he probably couldn't solve this problem.","start":1,"answer":"にしたところで","acceptedAnswers":["にしたところで","にしても"],"distractors":[{"text":"にしたところをで","reason":"を and で cannot be combined like this here."},{"text":"にしたところな","reason":"な does not form a concessive link here."},{"text":"にしたところます","reason":"ます cannot attach directly to ところ."}]}},"romaji":"Kare ni shita tokoro de, kono mondai wa tokenai darō.","german":"Even he probably couldn't solve this problem."},{"japanese":"今から出発したって、間に合わない。","romaji":"Ima kara shuppatsu shitatte, maniawanai.","german":"Even if we leave now, we won't make it in time."}],"notes":"Emphasizes the futility or unchangeability of the result.","related":["n2-ni-shite-mo","n3-to-shitemo"]},
{"id":"n1-nihajinai","pattern":"～に恥じない","level":"N1","category":"Satzstrukturen","meaning":"worthy of, living up to","explanation":"Expresses that someone or something is worthy and lives up to expectations or a reputation. A positive expression.","formation":"Noun + に恥じない","examples":[{"japanese":"彼はその称号に恥じない活躍をした。","cloze":{"start":6,"answer":"に恥じない","quiz":{"level":"N1","japanese":"彼はその称号に恥じない活躍をした。","german":"He performed in a way worthy of that title.","start":6,"answer":"に恥じない","acceptedAnswers":["に恥じない"],"distractors":[{"text":"に恥じないます","reason":"ない does not take an attached ます."},{"text":"に恥じないな","reason":"No extra な comes before 活躍 here."},{"text":"を恥じない","reason":"を makes the title the object of being ashamed instead of the standard for a worthy performance."}]}},"romaji":"Kare wa sono shōgō ni hajinai katsuyaku wo shita.","german":"He performed in a way worthy of that title."},{"japanese":"チャンピオンの名に恥じない戦いぶりだった。","cloze":{"start":8,"answer":"に恥じない"},"romaji":"Chanpion no na ni hajinai tatakaibu ri datta.","german":"It was a fight worthy of the name of champion."}],"notes":"A positive expression that emphasizes worthiness.","related":["n1-ni-taru"]},
{"id":"n1-waiun ioyobazu","pattern":"～は言うに及ばず","level":"N1","category":"Satzstrukturen","meaning":"not to mention, let alone","explanation":"Expresses that something is obvious or self-evident and does not need to be mentioned specifically. Then emphasizes additional examples.","formation":"Noun + は言うに及ばず","examples":[{"japanese":"彼は英語は言うに及ばず、フランス語も話せる。","cloze":{"start":4,"answer":"は言うに及ばず","quiz":{"level":"N1","japanese":"彼は英語は言うに及ばず、フランス語も話せる。","german":"He can speak French, not to mention English.","start":4,"answer":"は言うに及ばず","acceptedAnswers":["は言うに及ばず","はもちろん"],"distractors":[{"text":"は言うに及ばずな","reason":"な cannot be attached here."},{"text":"は言うに及ばずを","reason":"を does not form an additive link here."},{"text":"は言うに及ばずます","reason":"ます cannot attach to ず."}]}},"romaji":"Kare wa eigo wa iu ni oyobazu, furansugo mo hanaseru.","german":"He can speak French, not to mention English."},{"japanese":"東京は言うに及ばず、地方でも人気がある。","cloze":{"start":2,"answer":"は言うに及ばず"},"romaji":"Tōkyō wa iu ni oyobazu, chihō demo ninki ga aru.","german":"It is popular in the regions too, not to mention Tokyo."}],"notes":"A very formal expression, often found in written language.","related":["n2-wa-mochiron"]},
{"id":"n1-wasateoite","pattern":"～はさておき/はさておいて","level":"N1","category":"Satzstrukturen","meaning":"setting aside, leaving aside","explanation":"Temporarily sets a topic aside in order to talk about something else. Signals a change of topic.","formation":"Noun + はさておき/はさておいて","examples":[{"japanese":"冗談はさておき、本題に入りましょう。","cloze":{"start":2,"answer":"はさておき","quiz":{"level":"N1","japanese":"冗談はさておき、本題に入りましょう。","german":"Joking aside, let's get to the main topic.","start":2,"answer":"はさておき","acceptedAnswers":["はさておき"],"distractors":[{"text":"はさておいた","reason":"The attributive past does not form a link here."},{"text":"はさておきます","reason":"The finite form does not form a link here."},{"text":"はさておきな","reason":"な cannot be attached here."}]}},"romaji":"Jōdan wa sateoki, hondai ni hairimashō.","german":"Joking aside, let's get to the main topic."},{"japanese":"お金の話はさておいて、まず計画を立てよう。","cloze":{"start":4,"answer":"はさておいて"},"romaji":"Okane no hanashi wa sateoite, mazu keikaku wo tateyō.","german":"Leaving money aside, let's make a plan first."}],"notes":"Useful for changing the topic or setting priorities.","related":["n2-wa-tomokaku"]},
{"id":"n1-bakarikamade","pattern":"～ばかりか～まで","level":"N1","category":"Satzstrukturen","meaning":"not only ... but even","explanation":"Emphasizes that, in addition to one thing, something even more surprising or extreme comes on top. Strengthens the statement.","formation":"Noun + ばかりか + Noun + まで\n普通形 + ばかりか～まで","examples":[{"japanese":"彼は日本語ばかりか、中国語まで話せる。","romaji":"Kare wa nihongo bakari ka, chūgokugo made hanaseru.","german":"He can speak not only Japanese but even Chinese.","cloze":{"start":5,"answer":"ばかりか","quiz":{"level":"N1","japanese":"彼は日本語ばかりか、中国語まで話せる。","german":"He can speak not only Japanese but even Chinese.","start":5,"answer":"ばかりか","acceptedAnswers":["ばかりか","だけでなく"],"distractors":[{"text":"ばかりかを","reason":"を does not form an additive link here."},{"text":"ばかりかな","reason":"な cannot be attached here."},{"text":"ばかりかます","reason":"ます cannot attach to か."}]}}},{"japanese":"彼女は勉強ばかりか、スポーツまで得意だ。","romaji":"Kanojo wa benkyō bakari ka, supōtsu made tokui da.","german":"She is good not only at studying but even at sports."}],"notes":"Emphasizes the additional, surprising information.","related":["n4-dake-de-naku","n3-bakari-ka"]},
{"id":"n1-hitoridake denaku","pattern":"～ひとり～だけでなく","level":"N1","category":"Satzstrukturen","meaning":"not only ... alone","explanation":"Emphasizes that something is not limited to a single person or thing but affects others as well.","formation":"Noun + ひとり + だけでなく\nNoun + のみならず","examples":[{"japanese":"これは彼ひとりの問題だけでなく、全員の問題だ。","romaji":"Kore wa kare hitori no mondai dake de naku, zen'in no mondai da.","german":"This is not just his problem alone, but everyone's problem.","cloze":{"start":4,"answer":"ひとりの問題だけでなく","quiz":{"level":"N1","japanese":"これは彼ひとりの問題だけでなく、全員の問題だ。","german":"This is not just his problem alone, but everyone's problem.","start":4,"answer":"ひとりの問題だけでなく","acceptedAnswers":["ひとりの問題だけでなく","ひとりの問題だけではなく"],"distractors":[{"text":"ひとりの問題だけでないく","reason":"The adverbial form of ない is なく."},{"text":"ひとりの問題だけでなくな","reason":"な cannot be attached here."},{"text":"ひとりの問題だけでなくを","reason":"を does not form a contrastive link here."}]}}},{"japanese":"日本ひとりだけでなく、アジア全体の課題だ。","romaji":"Nihon hitori dake de naku, Ajia zentai no kadai da.","german":"This is not just Japan's challenge alone, but one for all of Asia."}],"notes":"Emphasizes extension beyond a single unit.","related":["n4-dake-de-naku","n1-nomi-narazu"]},
{"id":"n1-mono-explanation","pattern":"～もの (Erklärung)","level":"N1","category":"Satzstrukturen","meaning":"after all, because (explanation/justification)","explanation":"Gives an explanation or justification for an action or situation. Often expresses a subjective reason.","formation":"普通形 + もの\n普通形 + もん (colloquial)","examples":[{"japanese":"行きたくないもの。","romaji":"Ikitakunai mono.","german":"I just don't want to go.","cloze":{"start":6,"answer":"もの","quiz":{"level":"N1","japanese":"行きたくないもの。","german":"I just don't want to go.","start":6,"answer":"もの","acceptedAnswers":["もの","もん"],"distractors":[{"text":"ものます","reason":"ます cannot attach directly to もの."},{"text":"ものなです","reason":"No な comes before です here."},{"text":"ものをます","reason":"ます cannot attach to を."}]}}},{"japanese":"疲れているんだもの、休みたい。","romaji":"Tsukarete irun da mono, yasumitai.","german":"I'm tired, after all, so I want to rest."}],"notes":"Often used by women and children; sounds slightly defiant.","related":["kara-because","node"]},
{"id":"n1-monogaaru","pattern":"～ものがある","level":"N1","category":"Satzstrukturen","meaning":"there is something (special) about it","explanation":"Expresses that something has a certain quality or leaves an impression that is hard to describe. Often used for emotional or aesthetic impressions.","formation":"Verb 辞書形 + ものがある\nい-adjective + ものがある","examples":[{"japanese":"彼の演奏には心を打つものがある。","cloze":{"start":10,"answer":"ものがある","quiz":{"level":"N1","japanese":"彼の演奏には心を打つものがある。","german":"There is something about his playing that touches the heart.","start":10,"answer":"ものがある","acceptedAnswers":["ものがある"],"distractors":[{"text":"ものをある","reason":"ある needs が here, not を."},{"text":"ものがあるます","reason":"ます needs the stem あり."},{"text":"ものがない","reason":"This negates the moving quality."}]}},"romaji":"Kare no ensō ni wa kokoro wo utsu mono ga aru.","german":"There is something about his playing that touches the heart."},{"japanese":"この絵には考えさせられるものがある。","cloze":{"start":12,"answer":"ものがある"},"romaji":"Kono e ni wa kangaesaserareru mono ga aru.","german":"There is something about this painting that makes you think."}],"notes":"Expresses a subjective, often positive impression.","related":[]},
{"id":"n1-monotoshite","pattern":"～ものとして","level":"N1","category":"Satzstrukturen","meaning":"on the assumption that, as if","explanation":"Expresses that you take something as given or true and act accordingly. Often in formal or official contexts.","formation":"普通形 + ものとして\nNoun + (である) + ものとして","examples":[{"japanese":"彼が来ないものとして、計画を進めよう。","cloze":{"start":5,"answer":"ものとして","quiz":{"level":"N1","japanese":"彼が来ないものとして、計画を進めよう。","german":"Let's go ahead with the plan on the assumption that he won't come.","start":5,"answer":"ものとして","acceptedAnswers":["ものとして"],"distractors":[{"text":"ものとする","reason":"The dictionary form does not form an assumption link here."},{"text":"ものとします","reason":"The finite form does not form a link here."},{"text":"ものをして","reason":"The assumption expression requires と."}]}},"romaji":"Kare ga konai mono to shite, keikaku wo susumeyō.","german":"Let's go ahead with the plan on the assumption that he won't come."},{"japanese":"この件は解決したものとして処理する。","cloze":{"start":8,"answer":"ものとして"},"romaji":"Kono ken wa kaiketsu shita mono to shite shori suru.","german":"We will treat this matter as resolved."}],"notes":"Often used in business or formal situations.","related":["n4-toshite"]},
{"id":"n1-mononara","pattern":"～ものなら","level":"N2","category":"Satzstrukturen","meaning":"if one could, if it were possible","explanation":"Expresses a strong wish, often implying that it is difficult or impossible. Also used for hypothetical negative consequences.","formation":"Verb 辞書形 + ものなら\nできる + ものなら","examples":[{"japanese":"できるものなら、やり直したい。","romaji":"Dekiru mono nara, yari naoshitai.","german":"If I could, I'd like to do it over.","cloze":{"start":3,"answer":"ものなら","quiz":{"level":"N2","japanese":"できるものなら、やり直したい。","german":"If I could, I'd like to do it over.","start":3,"answer":"ものなら","acceptedAnswers":["ものなら","なら"],"distractors":[{"text":"ものだなら","reason":"The noun-based condition does not need an extra だ."},{"text":"ものをなら","reason":"を cannot come before the condition here."},{"text":"ものますなら","reason":"ます cannot attach directly to もの."}]}}},{"japanese":"嘘をついたものなら、ただでは済まない。","romaji":"Uso wo tsuita mono nara, tada de wa sumanai.","german":"If you were to lie, you wouldn't get away with it."},{"japanese":"戻れるものなら、学生時代に戻りたい。","romaji":"Modoreru mono nara, gakusei jidai ni modoritai.","german":"If I could go back, I'd like to return to my student days."}],"notes":"Can express a wish or a warning, depending on context.","related":["tara","n4-nara","n3-mono-no","n2-kurai-nara"],"legacyIds":["n2-mono-nara"]},
{"id":"n1-ya","pattern":"～や","level":"N1","category":"Satzstrukturen","meaning":"as soon as (literary)","explanation":"A very literary expression meaning \"as soon as\" or \"no sooner ... than\". Used almost exclusively in written language.","formation":"Verb 辞書形 + や","examples":[{"japanese":"彼は私を見るや、逃げ出した。","cloze":{"start":6,"answer":"や","quiz":{"level":"N1","japanese":"彼は私を見るや、逃げ出した。","german":"The moment he saw me, he ran off.","start":6,"answer":"や","acceptedAnswers":["や","や否や","なり"],"distractors":[{"text":"やを","reason":"を does not form a temporal link here."},{"text":"やな","reason":"な cannot be attached here."},{"text":"やます","reason":"ます cannot attach directly to や."}]}},"romaji":"Kare wa watashi wo miru ya, nigedashita.","german":"The moment he saw me, he ran off."},{"japanese":"その知らせを聞くや、彼女は泣き出した。","cloze":{"start":8,"answer":"や"},"romaji":"Sono shirase wo kiku ya, kanojo wa nakidashita.","german":"As soon as she heard the news, she started to cry."}],"notes":"Very literary and archaic; rare in modern language.","related":["n1-ya-inaya","n1-nari","n3-totan"]},
{"id":"n1-youdewanaika","pattern":"～ようではないか","level":"N1","category":"Satzstrukturen","meaning":"let us; shall we not","explanation":"Encouragement or a call to a group to do something together. Often in speeches or formal addresses.","formation":"Verb 意向形 + ではないか\nVerb 意向形 + じゃないか","examples":[{"japanese":"みんなで力を合わせて頑張ろうではないか。","romaji":"Minna de chikara wo awasete ganbarō de wa nai ka.","german":"Let us all join forces and do our best!","cloze":{"start":10,"answer":"頑張ろうではないか","quiz":{"level":"N1","japanese":"みんなで力を合わせて頑張ろうではないか。","german":"Let us all join forces and do our best!","start":10,"answer":"頑張ろうではないか","acceptedAnswers":["頑張ろうではないか","頑張ろうじゃないか"],"distractors":[{"text":"頑張るうではないか","reason":"The volitional form is 頑張ろう."},{"text":"頑張ろうではないますか","reason":"ない does not take an attached ます."},{"text":"頑張ろうではないかます","reason":"ます cannot attach to the question particle."}]}}},{"japanese":"この機会に挑戦してみようではありませんか。","romaji":"Kono kikai ni chōsen shite miyō de wa arimasen ka.","german":"Shall we not seize this opportunity and give it a try?"}],"notes":"Often used in inspiring speeches or appeals.","related":["mashou","n4-volitional"]},
{"id":"n1-kagirida","pattern":"～限りだ","level":"N1","category":"Satzstrukturen","meaning":"extremely, deeply (feeling)","explanation":"Expresses an extreme feeling or state. Often used with adjectives of emotion.","formation":"い-adjective + 限りだ\nな-adjective + な + 限りだ","examples":[{"japanese":"彼の成功は喜ばしい限りだ。","cloze":{"start":9,"answer":"限りだ","quiz":{"level":"N1","japanese":"彼の成功は喜ばしい限りだ。","german":"His success is truly gratifying.","start":9,"answer":"限りだ","acceptedAnswers":["限りだ"],"distractors":[{"text":"限りを","reason":"The object particle does not end the sentence."},{"text":"限りな","reason":"The attributive form does not end the sentence."},{"text":"限ります","reason":"ます cannot attach directly to the noun 限り here."}]}},"romaji":"Kare no seikō wa yorokobashii kagiri da.","german":"His success is truly gratifying."},{"japanese":"このような結果になって、残念な限りです。","romaji":"Kono yō na kekka ni natte, zannen na kagiri desu.","german":"It is deeply regrettable that things turned out this way."}],"notes":"Expresses strong feelings or evaluations.","related":["n1-kiwamarinai"]},
{"id":"n1-gayueni","pattern":"～がゆえに/が故に","level":"N1","category":"Satzstrukturen","meaning":"precisely because, due to","explanation":"A very formal expression for \"because\" or \"due to\". Emphasizes causality and is used mainly in written language.","formation":"普通形 + がゆえに\nNoun + (である) + がゆえに","examples":[{"japanese":"若さゆえの過ちだった。","romaji":"Wakasa yue no ayamachi datta.","german":"It was a mistake born of youth."},{"japanese":"経験不足であるがゆえに、失敗した。","cloze":{"start":7,"answer":"がゆえに","quiz":{"level":"N1","japanese":"経験不足であるがゆえに、失敗した。","german":"Precisely because I lacked experience, I failed.","start":7,"answer":"がゆえに","acceptedAnswers":["がゆえに","ために"],"distractors":[{"text":"がゆえを","reason":"The causal link is completed with に."},{"text":"がゆえな","reason":"な does not form a causal link here."},{"text":"がゆえます","reason":"ます cannot attach directly to ゆえ."}]}},"romaji":"Keiken busoku de aru ga yue ni, shippai shita.","german":"Precisely because I lacked experience, I failed."}],"notes":"Very formal and literary; rare in spoken language.","related":["n4-tame-ni","kara-because","node"]},
{"id":"n1-kosoare","pattern":"～こそあれ","level":"N1","category":"Satzstrukturen","meaning":"admittedly ... but; if anything ... but never","explanation":"Concedes that something goes in one direction, but rules out the opposite. A very literary expression.","formation":"Noun + こそあれ\nVerb ます-form + こそすれ","examples":[{"japanese":"増えこそあれ、減ることはない。","cloze":{"start":2,"answer":"こそあれ","quiz":{"level":"N1","japanese":"増えこそあれ、減ることはない。","german":"It may increase, but it will never decrease.","start":2,"answer":"こそあれ","acceptedAnswers":["こそあれ"],"distractors":[{"text":"こそあるを","reason":"を cannot connect to ある here."},{"text":"こそあれな","reason":"な cannot be attached here."},{"text":"こそありまする","reason":"る cannot attach to ます."}]}},"romaji":"Fue koso are, heru koto wa nai.","german":"It may increase, but it will never decrease."},{"japanese":"彼女は怒りこそすれ、喜ぶことはないだろう。","romaji":"Kanojo wa okori koso sure, yorokobu koto wa nai darō.","german":"If anything, she will get angry; she certainly won't be pleased."}],"notes":"Very literary; not in common use in modern colloquial language.","related":["n4-koto-wa-ga","n3-to-shitemo"]},
{"id":"n1-kososure","pattern":"～こそすれ","level":"N1","category":"Satzstrukturen","meaning":"if anything (this way), but never the opposite","explanation":"Similar to こそあれ; emphasizes that something tends in one direction but is definitely not the opposite. Very literary.","formation":"Verb ます-form + こそすれ","examples":[{"japanese":"困難は増しこそすれ、減りはしない。","cloze":{"start":5,"answer":"こそすれ","quiz":{"level":"N1","japanese":"困難は増しこそすれ、減りはしない。","german":"The difficulties will increase, if anything, rather than decrease.","start":5,"answer":"こそすれ","acceptedAnswers":["こそすれ"],"distractors":[{"text":"こそするを","reason":"を cannot connect to する here."},{"text":"こそすれな","reason":"な cannot be attached here."},{"text":"こそしまする","reason":"る cannot attach to ます."}]}},"romaji":"Konnan wa mashi koso sure, heri wa shinai.","german":"The difficulties will increase, if anything, rather than decrease."},{"japanese":"彼の態度は硬化しこそすれ、軟化しない。","cloze":{"start":8,"answer":"こそすれ"},"romaji":"Kare no taido wa kōka shi koso sure, nanka shinai.","german":"His attitude is hardening, if anything, rather than softening."}],"notes":"Very literary and formal; archaic style.","related":["n1-kosoare","n4-koto-wa-ga"]},
{"id":"n1-sobakara","pattern":"～そばから","level":"N1","category":"Satzstrukturen","meaning":"no sooner ... than again; as soon as ... right away again","explanation":"Expresses that immediately after something has been done, the opposite or something negative happens. Emphasizes futility.","formation":"Verb 辞書形/た-form + そばから","examples":[{"japanese":"掃除したそばから、また散らかす。","cloze":{"start":4,"answer":"そばから","quiz":{"level":"N1","japanese":"掃除したそばから、また散らかす。","german":"No sooner have I cleaned up than they make a mess again.","start":4,"answer":"そばから","acceptedAnswers":["そばから"],"distractors":[{"text":"そばからを","reason":"を does not form a temporal link here."},{"text":"そばからな","reason":"な cannot be attached here."},{"text":"そばからます","reason":"ます cannot attach directly to から."}]}},"romaji":"Sōji shita soba kara, mata chirakasu.","german":"No sooner have I cleaned up than they make a mess again."},{"japanese":"覚えたそばから忘れてしまう。","cloze":{"start":3,"answer":"そばから"},"romaji":"Oboeta soba kara wasurete shimau.","german":"As soon as I learn something, I forget it again."}],"notes":"Often expresses frustration about repeated negative events.","related":["n3-totan","n1-nari"]},
{"id":"n1-dakemashi","pattern":"～だけまし","level":"N1","category":"Satzstrukturen","meaning":"at least better than, at least","explanation":"Expresses that a situation is not ideal, but at least better than an alternative. Emphasizes the positive in a negative situation.","formation":"普通形 + だけまし\nNoun + だけまし","examples":[{"japanese":"少しでももらえるだけましだ。","cloze":{"start":8,"answer":"だけまし","quiz":{"level":"N1","japanese":"少しでももらえるだけましだ。","german":"Getting even a little is better than nothing.","start":8,"answer":"だけまし","acceptedAnswers":["だけまし"],"distractors":[{"text":"だけましな","reason":"No な comes before だ here."},{"text":"だけましを","reason":"を does not fit before だ here."},{"text":"だけまします","reason":"ます cannot attach directly to まし."}]}},"romaji":"Sukoshi demo moraeru dake mashi da.","german":"Getting even a little is better than nothing."},{"japanese":"怪我がなかっただけましだった。","cloze":{"start":7,"answer":"だけまし"},"romaji":"Kega ga nakatta dake mashi datta.","german":"At least nobody was hurt."}],"notes":"Expresses relief despite negative circumstances.","related":[]},
{"id":"n1-dearouto","pattern":"～であろうと","level":"N1","category":"Satzstrukturen","meaning":"even if it were ..., even if","explanation":"Expresses that something applies regardless of the circumstances. A very formal expression.","formation":"Noun + であろうと\n疑問詞 + であろうと","examples":[{"japanese":"誰であろうと、ルールは守らなければならない。","cloze":{"start":1,"answer":"であろうと","quiz":{"level":"N1","japanese":"誰であろうと、ルールは守らなければならない。","german":"Whoever it is, they must follow the rules.","start":1,"answer":"であろうと","acceptedAnswers":["であろうと","であっても","であれ"],"distractors":[{"text":"であるうと","reason":"The volitional form of ある is あろう."},{"text":"であろうを","reason":"The concessive connection requires と, not を."},{"text":"であろうとな","reason":"な cannot be attached here."}]}},"romaji":"Dare de arō to, rūru wa mamoranakereba naranai.","german":"Whoever it is, they must follow the rules."},{"japanese":"どんな困難であろうと、諦めない。","cloze":{"start":5,"answer":"であろうと"},"romaji":"Donna konnan de arō to, akiramenai.","german":"However difficult it may be, I won't give up."}],"notes":"Very formal; often found in written language.","related":["n1-de-are","temo"]},
{"id":"n1-temosashitsukaenai","pattern":"～ても差し支えない","level":"N1","category":"Satzstrukturen","meaning":"it's no problem if, it's fine to","explanation":"A formal expression that grants permission or consent. Expresses that something is acceptable and causes no problems.","formation":"Verb て-form + も差し支えない","examples":[{"japanese":"ここで写真を撮っても差し支えありません。","romaji":"Koko de shashin wo totte mo sashitsukae arimasen.","german":"You may take photos here without any problem."},{"japanese":"明日来ても差し支えない。","cloze":{"start":3,"answer":"ても差し支えない","quiz":{"level":"N1","japanese":"明日来ても差し支えない。","german":"It's fine if you come tomorrow.","start":3,"answer":"ても差し支えない","acceptedAnswers":["ても差し支えない","ても構わない"],"distractors":[{"text":"ても差し支えないます","reason":"ない does not take an attached ます."},{"text":"ても差し支えるません","reason":"ません does not attach to the dictionary form."},{"text":"ても差し支えないました","reason":"The polite past is not formed with ないました."}]}},"romaji":"Ashita kite mo sashitsukae nai.","german":"It's fine if you come tomorrow."}],"notes":"Very formal; often in business or official contexts.","related":["temo-ii"]},
{"id":"n1-toattewa","pattern":"～とあっては","level":"N1","category":"Satzstrukturen","meaning":"if it is the case that, under these circumstances","explanation":"Expresses that, under certain special circumstances, a corresponding reaction or action is natural or unavoidable.","formation":"普通形 + とあっては\nNoun + とあっては","examples":[{"japanese":"社長の命令とあっては、断れない。","cloze":{"start":5,"answer":"とあっては","quiz":{"level":"N1","japanese":"社長の命令とあっては、断れない。","german":"If it's an order from the company president, I can't refuse.","start":5,"answer":"とあっては","acceptedAnswers":["とあっては"],"distractors":[{"text":"とあるは","reason":"は does not connect to the dictionary form here."},{"text":"とありますは","reason":"は does not connect to the polite form here."},{"text":"とあってを","reason":"を does not form a conditional link here."}]}},"romaji":"Shachō no meirei to atte wa, kotowarenai.","german":"If it's an order from the company president, I can't refuse."},{"japanese":"このような状況とあっては、仕方がない。","cloze":{"start":7,"answer":"とあっては"},"romaji":"Kono yō na jōkyō to atte wa, shikata ga nai.","german":"Under these circumstances, it can't be helped."}],"notes":"Emphasizes the inevitability or naturalness of the reaction.","related":["n1-to-mo-naru-to","n4-toshite"]},
{"id":"n1-toiumono","pattern":"～というもの","level":"N1","category":"Satzstrukturen","meaning":"the whole time, ever since","explanation":"Emphasizes that a state has continued without interruption over a longer period. Often used with time expressions.","formation":"Time expression + というもの","examples":[{"japanese":"あれ以来というもの、彼とは会っていない。","cloze":{"start":4,"answer":"というもの","quiz":{"level":"N1","japanese":"あれ以来というもの、彼とは会っていない。","german":"Ever since then, I haven't seen him at all.","start":4,"answer":"というもの","acceptedAnswers":["というもの"],"distractors":[{"text":"をいうもの","reason":"The quoting connection requires と."},{"text":"というものな","reason":"な cannot be attached here."},{"text":"というものます","reason":"ます cannot attach directly to もの."}]}},"romaji":"Are irai to iu mono, kare to wa atte inai.","german":"Ever since then, I haven't seen him at all."},{"japanese":"この一週間というもの、雨ばかりだ。","cloze":{"start":5,"answer":"というもの"},"romaji":"Kono isshūkan to iu mono, ame bakari da.","german":"This whole past week, it's been nothing but rain."}],"notes":"Emphasizes continuity over the entire period.","related":["n4-aida-ni"]},
{"id":"n1-toittatokoroda","pattern":"～といったところだ","level":"N1","category":"Satzstrukturen","meaning":"about, roughly, at best","explanation":"Gives a rough estimate or assessment. Often expresses that something is modest or limited.","formation":"Number/amount + といったところだ\n普通形 + といったところだ","examples":[{"japanese":"参加者は30人といったところだ。","cloze":{"start":7,"answer":"といったところだ","quiz":{"level":"N1","japanese":"参加者は30人といったところだ。","german":"There are about 30 participants, I'd say.","start":7,"answer":"といったところだ","acceptedAnswers":["といったところだ"],"distractors":[{"text":"といったところを","reason":"The object particle does not end the sentence."},{"text":"といったところな","reason":"The attributive form does not end the sentence."},{"text":"といったところます","reason":"ます cannot attach directly to ところ."}]}},"romaji":"Sankasha wa sanjuunin to itta tokoro da.","german":"There are about 30 participants, I'd say."},{"japanese":"彼の実力はせいぜい中級といったところだ。","cloze":{"start":11,"answer":"といったところだ"},"romaji":"Kare no jitsuryoku wa seizei chūkyū to itta tokoro da.","german":"His ability is intermediate level at best."}],"notes":"Often expresses a modest or realistic assessment.","related":["n3-kurai-gurai"]},
{"id":"n1-toshitatokorode","pattern":"～としたところで","level":"N1","category":"Satzstrukturen","meaning":"even supposing, even assuming","explanation":"Hypothetically assumes that something is the case, and then shows that the result would still be no different.","formation":"普通形 + としたところで\nNoun + としたところで","examples":[{"japanese":"今から急いだとしたところで、間に合わない。","cloze":{"start":6,"answer":"としたところで","quiz":{"level":"N1","japanese":"今から急いだとしたところで、間に合わない。","german":"Even if we hurried now, we wouldn't make it in time.","start":6,"answer":"としたところで","acceptedAnswers":["としたところで","としても"],"distractors":[{"text":"としたところをで","reason":"を and で cannot be combined like this here."},{"text":"としたところな","reason":"な does not form a concessive link here."},{"text":"としたところます","reason":"ます cannot attach directly to ところ."}]}},"romaji":"Ima kara isoida to shita tokoro de, maniawanai.","german":"Even if we hurried now, we wouldn't make it in time."},{"japanese":"彼に頼んだとしたところで、助けてくれないだろう。","cloze":{"start":5,"answer":"としたところで"},"romaji":"Kare ni tanonda to shita tokoro de, tasukete kurenai darō.","german":"Even if we asked him, he probably wouldn't help us."}],"notes":"Emphasizes the futility or unchangeability of the result.","related":["n3-to-shitemo","n3-ta-tokoro-de"]},
{"id":"n1-tomiruya","pattern":"～とみるや","level":"N1","category":"Satzstrukturen","meaning":"as soon as one sees/notices that","explanation":"Expresses that an action follows immediately after noticing or seeing something. Emphasizes the speed of the reaction.","formation":"Verb 辞書形/た-form + とみるや","examples":[{"japanese":"彼は私を見るや、走り去った。","romaji":"Kare wa watashi wo miru ya, hashiri satta.","german":"As soon as he saw me, he ran off."},{"japanese":"チャンスとみるや、すぐに行動に移した。","cloze":{"start":4,"answer":"とみるや","quiz":{"level":"N1","japanese":"チャンスとみるや、すぐに行動に移した。","german":"As soon as he saw a chance, he took action immediately.","start":4,"answer":"とみるや","acceptedAnswers":["とみるや"],"distractors":[{"text":"をみるや","reason":"Classifying what one sees requires と."},{"text":"とみるやな","reason":"な cannot be attached here."},{"text":"とみるやます","reason":"ます cannot attach directly to や."}]}},"romaji":"Chansu to miru ya, sugu ni kōdō ni utsushita.","german":"As soon as he saw a chance, he took action immediately."}],"notes":"A literary expression; emphasizes a quick reaction.","related":["n1-ya","n1-ya-inaya","n1-nari"]},
{"id":"n1-jimita","pattern":"～じみた / ～じみる","level":"N1","category":"Adjektive","meaning":"like ..., -ish (usually negative or pejorative)","explanation":"Expresses that something seems or looks like something else, often with a negative or critical connotation. Used to express that something comes across as inappropriate or unpleasant. じみた is used before nouns, じみる as a verb.","formation":"名詞 + じみた + 名詞\n名詞 + じみる","examples":[{"japanese":"説教じみた話はやめてください。","cloze":{"start":2,"answer":"じみた","quiz":{"level":"N1","japanese":"説教じみた話はやめてください。","german":"Please stop the preachy talk.","start":2,"answer":"じみた","acceptedAnswers":["じみた"],"distractors":[{"text":"じみ","reason":"The stem form does not modify 話 attributively here."},{"text":"じみるました","reason":"The polite past requires the stem じみ."},{"text":"じみたな","reason":"No extra な comes before 話 here."}]}},"romaji":"Sekkyō jimita hanashi wa yamete kudasai.","german":"Please stop the preachy talk."},{"japanese":"彼の服装は年寄りじみている。","romaji":"Kare no fukusō wa toshiyori jimite iru.","german":"His clothes look old-fashioned / like an old man's."},{"japanese":"愚痴じみたことを言うな。","cloze":{"start":2,"answer":"じみた"},"romaji":"Guchi jimita koto wo iu na.","german":"Don't say such whiny things."}],"notes":"Usually has a negative connotation. Expresses that something seems unsuitable or inappropriate.","related":["n4-ppoi","n2-meku","n1-gamashii"]},
{"id":"n1-gamashii","pattern":"～がましい","level":"N1","category":"Adjektive","meaning":"presumptuous, seeming like ..., coming across as inappropriately ...","explanation":"Expresses that something or someone comes across as something inappropriate or presumptuous. Has a negative connotation and indicates that the behavior or appearance does not suit the situation. A critical expression.","formation":"名詞 + がましい\n名詞 + がましく","examples":[{"japanese":"わざとらしい、わざとがましい演技だ。","cloze":{"start":10,"answer":"がましい","quiz":{"level":"N1","japanese":"わざとらしい、わざとがましい演技だ。","german":"It's an affected, contrived performance.","start":10,"answer":"がましい","acceptedAnswers":["がましい"],"distractors":[{"text":"がましく","reason":"The adverbial form does not modify 演技 attributively here."},{"text":"がましいな","reason":"The い-adjective takes no な before 演技."},{"text":"がましいます","reason":"ます cannot attach directly to the adjective."}]}},"romaji":"Wazatorashii, wazato gamashii engi da.","german":"It's an affected, contrived performance."},{"japanese":"押し付けがましい態度は好きではない。","cloze":{"start":4,"answer":"がましい"},"romaji":"Oshitsuke gamashii taido wa suki dewa nai.","german":"I don't like pushy attitudes."},{"japanese":"恩着せがましいことを言うな。","cloze":{"start":3,"answer":"がましい"},"romaji":"Onkise gamashii koto wo iu na.","german":"Don't say things as if you expect me to be grateful."}],"notes":"Strongly negative connotation. Used to criticize inappropriate or presumptuous behavior.","related":["n1-jimita","n4-ppoi"]},
{"id":"n1-gatai","pattern":"～がたい / ～難い","level":"N3","category":"Adjektive","meaning":"hard to ..., hardly possible to ..., difficult to ...","explanation":"Expresses that something is difficult or hardly possible to do. More formal than にくい and often used in written language. Emphasizes the objective difficulty or impossibility of an action.","formation":"動詞ます形 + がたい\n動詞ます形 + 難い","examples":[{"japanese":"彼の説明は理解しがたい。","cloze":{"start":8,"answer":"がたい","quiz":{"level":"N3","japanese":"彼の説明は理解しがたい。","german":"His explanation is hard to understand.","start":8,"answer":"がたい","acceptedAnswers":["がたい","にくい"],"distractors":[{"text":"がたいます","reason":"ます cannot attach directly to the adjective."},{"text":"がたくです","reason":"The adverbial form does not fit before です here."},{"text":"がたかったい","reason":"The past form ends in かった without an extra い."}]}},"romaji":"Kare no setsumei wa rikai shigatai.","german":"His explanation is hard to understand."},{"japanese":"許しがたい行為だ。","cloze":{"start":2,"answer":"がたい"},"romaji":"Yurushi gatai kōi da.","german":"It is an unforgivable act."},{"japanese":"信じがたい話だが、本当らしい。","cloze":{"start":2,"answer":"がたい"},"romaji":"Shinji gatai hanashi da ga, hontō rashii.","german":"It's a hard-to-believe story, but it seems to be true."},{"japanese":"彼の行動は理解しがたい。","romaji":"Kare no kōdō wa rikai shigatai.","german":"His behavior is hard to understand."},{"japanese":"忘れがたい思い出だ。","romaji":"Wasuregatai omoide da.","german":"It's an unforgettable memory."}],"notes":"More formal than にくい. Often used in written language or formal situations.","related":["n4-nikui","n2-kaneru","n3-zurai"],"legacyIds":["n3-gatai"]},
{"id":"n1-ge","pattern":"～げ / ～気","level":"N2","category":"Adjektive","meaning":"seeming ..., looking as if ..., -ish (feeling)","explanation":"Used to express the outward impression or appearance of a state or feeling. Turns adjectives into nouns that describe the appearance. Often combined with verbs of perception.","formation":"イ形容詞語幹 + げ\nナ形容詞語幹 + げ\n名詞 + げ + な/に","examples":[{"japanese":"彼は寂しげな表情をしていた。","cloze":{"start":4,"answer":"げ","quiz":{"level":"N2","japanese":"彼は寂しげな表情をしていた。","german":"He had a lonely look on his face.","start":4,"answer":"げ","acceptedAnswers":["げ"],"distractors":[{"text":"げな","reason":"The following な would be doubled, which is not allowed."},{"text":"げを","reason":"を does not fit before な表情 here."},{"text":"げます","reason":"ます cannot attach directly to げ."}]}},"romaji":"Kare wa sabishi ge na hyōjō wo shite ita.","german":"He had a lonely look on his face."},{"japanese":"彼女は嬉しげに話していた。","cloze":{"start":5,"answer":"げ"},"romaji":"Kanojo wa ureshi ge ni hanashite ita.","german":"She was talking with an air of happiness."},{"japanese":"意味ありげな視線を送った。","cloze":{"start":4,"answer":"げ"},"romaji":"Imi ari ge na shisen wo okutta.","german":"He gave a meaningful look."},{"japanese":"彼女は悲しげな顔をしていた。","romaji":"Kanojo wa kanashige na kao o shiteita.","german":"She had a sad-looking face."},{"japanese":"子供たちは楽しげに遊んでいる。","romaji":"Kodomotachi wa tanoshige ni asondeiru.","german":"The children are playing merrily."}],"notes":"Used to describe the outward appearance of feelings or states. げな before nouns, げに as an adverb.","related":["n4-sou-appearance","n4-rashii","n2-meku"],"legacyIds":["n3-ge"]},
{"id":"n1-kai-ga-aru","pattern":"～甲斐がある / ～甲斐がない","level":"N1","category":"Adjektive","meaning":"it is worth ...ing / it is not worth ...ing; worth the effort","explanation":"Expresses whether an action or effort was or is worthwhile. 甲斐がある means that the effort bears fruit, while 甲斐がない means that the effort was in vain. Used to assess the value or benefit of an effort.","formation":"動詞辞書形/た形 + 甲斐がある/ない\n名詞 + の甲斐がある/ない","examples":[{"japanese":"一生懸命勉強した甲斐があって、合格できた。","romaji":"Isshōkenmei benkyō shita kai ga atte, gōkaku dekita.","german":"All my hard work studying paid off, and I passed.","cloze":{"start":8,"answer":"甲斐があって","quiz":{"level":"N1","japanese":"一生懸命勉強した甲斐があって、合格できた。","german":"All my hard work studying paid off, and I passed.","start":8,"answer":"甲斐があって","acceptedAnswers":["甲斐があって"],"distractors":[{"text":"甲斐をあって","reason":"ある needs が here, not を."},{"text":"甲斐があった","reason":"The attributive past does not form a link here."},{"text":"甲斐があります","reason":"The finite form does not form a link here."}]}}},{"japanese":"説得した甲斐がなかった。","romaji":"Settoku shita kai ga nakatta.","german":"My efforts to persuade them were in vain."},{"japanese":"生き甲斐を見つけることが大切だ。","romaji":"Iki gai wo mitsukeru koto ga taisetsu da.","german":"It is important to find a purpose in life."}],"notes":"Often used to assess in retrospect whether an effort was successful. 〜甲斐 can also be used on its own (生き甲斐, やり甲斐).","related":["n1-ni-taru"]},
{"id":"n1-gotoki","pattern":"～ごとき / ～ごとく / ～如き / ～如く","level":"N1","category":"Adjektive","meaning":"like ..., as ..., such as ... (literary)","explanation":"A literary expression for comparisons. ごとき is used before nouns, ごとく as an adverb. Very formal; used mainly in written language, literature or formal speeches. Can also be used pejoratively.","formation":"名詞 + ごとき/ごとく\n動詞辞書形 + ごとき/ごとく\nイ形容詞 + ごとき/ごとく","examples":[{"japanese":"嵐のごとく去って行った。","cloze":{"start":2,"answer":"ごとく","quiz":{"level":"N1","japanese":"嵐のごとく去って行った。","german":"He left like a storm.","start":2,"answer":"ごとく","acceptedAnswers":["ごとく","ように"],"distractors":[{"text":"ごとき","reason":"The attributive form does not modify 去って行った adverbially here."},{"text":"ごとくな","reason":"な cannot be attached here."},{"text":"ごとくます","reason":"ます cannot attach directly to ごとく."}]}},"romaji":"Arashi no gotoku satte itta.","german":"He left like a storm."},{"japanese":"私ごとき者が意見を言うのは恐れ多い。","cloze":{"start":1,"answer":"ごとき"},"romaji":"Watashi gotoki mono ga iken wo iu no wa osore ōi.","german":"It is presumptuous for someone like me to give an opinion."},{"japanese":"火を見るごとく明らかだ。","cloze":{"start":4,"answer":"ごとく"},"romaji":"Hi wo miru gotoku akiraka da.","german":"It is as clear as seeing fire (crystal clear)."},{"japanese":"嵐のごとく現れて、すぐに去った。","romaji":"Arashi no gotoku arawarete, sugu ni satta.","german":"He appeared like a storm and left again right away."},{"japanese":"彼は鬼神のごとき強さを見せた。","romaji":"Kare wa kijin no gotoki tsuyosa wo miseta.","german":"He showed demon-like strength."}],"notes":"Very literary and formal. In modern everyday language, ような is used instead. Can also be humble or pejorative.","related":["n4-you-na","n2-ka-no-you-ni","n4-you-ni-purpose"],"legacyIds":["n1-gotoku-gotoki"]},
{"id":"n1-nagara-no","pattern":"～ながらに / ～ながらの","level":"N1","category":"Adjektive","meaning":"in the state of ..., as always, typical of ..., despite ...","explanation":"Expresses that something keeps its original or characteristic state. Used to emphasize that something is in its natural or customary state. Can also express a contrast or an unexpected combination.","formation":"名詞 + ながらの + 名詞\nイ形容詞 + ながらの + 名詞\n動詞辞書形 + ながらの + 名詞","examples":[{"japanese":"ありのままの姿、生まれながらの才能。","cloze":{"start":11,"answer":"ながらの","quiz":{"level":"N1","japanese":"ありのままの姿、生まれながらの才能。","german":"One's true self as it is, a talent one is born with.","start":11,"answer":"ながらの","acceptedAnswers":["ながらの"],"distractors":[{"text":"ながらを","reason":"を cannot link to 才能 as a modifier here."},{"text":"ながらます","reason":"ます cannot attach directly to ながら."},{"text":"ながらのな","reason":"No extra な comes after の before 才能."}]}},"romaji":"Ari no mama no sugata, umare nagara no sainō.","german":"One's true self as it is, a talent one is born with."},{"japanese":"昔ながらの製法で作られている。","cloze":{"start":1,"answer":"ながらの"},"romaji":"Mukashi nagara no seihō de tsukurarete iru.","german":"It is made using the traditional method."},{"japanese":"彼女は学生ながらの新鮮な視点を持っている。","cloze":{"start":5,"answer":"ながらの"},"romaji":"Kanojo wa gakusei nagara no shinsen na shiten wo motte iru.","german":"She has the fresh perspective typical of a student."},{"japanese":"彼は生まれながらの才能を持っている。","romaji":"Kare wa umarenagara no sainō wo motte iru.","german":"He has a natural-born talent."}],"notes":"Used to emphasize the original or characteristic state. Often used with time references such as 昔 (the old days).","related":["n4-mama","n4-rashii"],"legacyIds":["n1-nagarani-nagarano"]},
{"id":"n1-ga-hayai-ka","pattern":"～が早いか","level":"N1","category":"Satzstrukturen","meaning":"no sooner ... than; the very moment that","explanation":"Describes how, immediately after one action, the next one already happens, almost at the same time. Written language; for actual events, usually past ones, not for wishes or requests.","formation":"Verb (dictionary form / た-form) + が早いか","examples":[{"japanese":"子どもたちはベルが鳴るが早いか、教室を飛び出した。","romaji":"Kodomotachi wa beru ga naru ga hayai ka, kyōshitsu o tobidashita.","german":"No sooner had the bell rung than the children rushed out of the classroom.","cloze":{"start":11,"answer":"が早いか","quiz":{"level":"N1","japanese":"子どもたちはベルが鳴るが早いか、教室を飛び出した。","german":"No sooner had the bell rung than the children rushed out of the classroom.","start":11,"answer":"が早いか","acceptedAnswers":["が早いか","や否や","やいなや","なり"],"distractors":[{"text":"ばかりか","reason":"ばかりか means \"not only ... but also\" and does not express a sequence in time."},{"text":"くせに","reason":"くせに (\"even though\") contains a reproach, not an immediate sequence."},{"text":"ものなら","reason":"ものなら (\"if ... at all\") is hypothetical and does not fit an actual event."}]}}},{"japanese":"彼は給料をもらうが早いか、全部使ってしまった。","romaji":"Kare wa kyūryō o morau ga hayai ka, zenbu tsukatte shimatta.","german":"No sooner had he received his salary than he spent all of it."},{"japanese":"店が開くが早いか、客が一斉に入ってきた。","romaji":"Mise ga aku ga hayai ka, kyaku ga issei ni haitte kita.","german":"The moment the shop opened, customers poured in all at once."}],"notes":"Similar in meaning to ～や否や and ～なり (both N1) as well as ～たとたん (N3). が早いか puts particular emphasis on speed. The second clause is not in the volitional or imperative mood.","related":["n1-ya-inaya","n1-nari","n3-totan"]},
{"id":"n1-kirai-ga-aru","pattern":"～きらいがある","level":"N1","category":"Satzstrukturen","meaning":"tends (undesirably) to ...","explanation":"Expresses an undesirable tendency of a person or group. Critical, detached and written in style; きらい (嫌い) is usually written in hiragana here.","formation":"Verb (dictionary form / ない-form) + きらいがある; Noun + の + きらいがある","examples":[{"japanese":"彼は物事を悪い方に考えるきらいがある。","romaji":"Kare wa monogoto o warui hō ni kangaeru kirai ga aru.","german":"He tends to look on the dark side of things.","cloze":{"start":12,"answer":"きらいがある","quiz":{"level":"N1","japanese":"彼は物事を悪い方に考えるきらいがある。","german":"He tends to look on the dark side of things.","start":12,"answer":"きらいがある","acceptedAnswers":["きらいがある","傾向がある"],"distractors":[{"text":"ことがある","reason":"考えることがある only means \"sometimes thinks that way\" and does not express a criticized tendency."},{"text":"わけがない","reason":"わけがない (\"it's impossible that\") contradicts the statement."},{"text":"べきだ","reason":"べきだ (\"should\") expresses an obligation, not a tendency."}]}}},{"japanese":"最近の若者は活字離れのきらいがあると言われる。","romaji":"Saikin no wakamono wa katsuji banare no kirai ga aru to iwareru.","german":"It is said that young people these days tend to read less and less."},{"japanese":"この政府は問題を先送りにするきらいがある。","romaji":"Kono seifu wa mondai o sakiokuri ni suru kirai ga aru.","german":"This government tends to put off problems."}],"notes":"Only for negative tendencies. More neutral: ～傾向がある (tendency); more everyday: ～がち (N3). Do not confuse with 嫌い (to dislike).","related":["n4-gachi"]},
{"id":"n1-gurumi","pattern":"～ぐるみ","level":"N1","category":"Satzstrukturen","meaning":"together with; ... as a whole","explanation":"After a noun, ぐるみ means \"all together, ... included\". Typical in set combinations such as 家族ぐるみ (the whole family), 町ぐるみ (the whole town) or 会社ぐるみ (the whole company, often in scandals).","formation":"Noun + ぐるみ (+ で / + の + Noun)","examples":[{"japanese":"隣の家とは家族ぐるみで付き合っています。","romaji":"Tonari no ie to wa kazoku gurumi de tsukiatte imasu.","german":"Our whole family is on friendly terms with the family next door.","cloze":{"start":7,"answer":"ぐるみ","quiz":{"level":"N1","japanese":"隣の家とは家族ぐるみで付き合っています。","german":"Our whole family is on friendly terms with the family next door.","start":7,"answer":"ぐるみ","acceptedAnswers":["ぐるみ"],"distractors":[{"text":"まみれ","reason":"まみれ means \"covered all over with\" (dirt, sweat) and does not fit with family."},{"text":"だらけ","reason":"だらけ means \"full of\" (usually something negative) and does not describe a community."},{"text":"ずくめ","reason":"ずくめ means \"consisting only of\" (黒ずくめ) and does not fit with people."}]}}},{"japanese":"これは会社ぐるみの不正だった。","romaji":"Kore wa kaisha gurumi no fusei datta.","german":"That was fraud involving the entire company."},{"japanese":"町ぐるみで祭りの準備をしている。","romaji":"Machi gurumi de matsuri no junbi o shite iru.","german":"The whole town is preparing for the festival."}],"notes":"Only common with a few nouns (家族, 町, 村, 地域, 会社, 組織). 会社ぐるみ and 組織ぐるみ often carry a note of criticism. Do not confuse with ～ごと (together with, e.g. 皮ごと食べる) or ぬいぐるみ (stuffed toy).","related":[]},
{"id":"n1-nai-made-mo","pattern":"～ないまでも","level":"N1","category":"Satzstrukturen","meaning":"even if not ..., at least ...","explanation":"You concede that a high degree is not reached, but expect at least a lower one. The second part often contains せめて or 少なくとも, or a recommendation (～べきだ, ～たほうがいい).","formation":"Verb (ない-form) + までも","examples":[{"japanese":"毎日とは言わないまでも、週に一度は運動したほうがいい。","romaji":"Mainichi to wa iwanai made mo, shū ni ichido wa undō shita hō ga ii.","german":"Even if not every day, you should exercise at least once a week.","cloze":{"start":6,"answer":"ないまでも","quiz":{"level":"N1","japanese":"毎日とは言わないまでも、週に一度は運動したほうがいい。","german":"Even if not every day, you should exercise at least once a week.","start":6,"answer":"ないまでも","acceptedAnswers":["ないまでも","ないにしても","ないにせよ"],"distractors":[{"text":"ないばかりか","reason":"ないばかりか intensifies (\"not only not ...\") instead of conceding."},{"text":"ないからには","reason":"からには gives grounds for an obligation and concedes nothing."},{"text":"ないことには","reason":"ないことには (\"unless ...\") requires a negative result in the second part."}]}}},{"japanese":"優勝できないまでも、せめて決勝には進みたい。","romaji":"Yūshō dekinai made mo, semete kesshō ni wa susumitai.","german":"Even if we can't win, we at least want to make it to the final."},{"japanese":"謝らないまでも、説明ぐらいはするべきだ。","romaji":"Ayamaranai made mo, setsumei gurai wa suru beki da.","german":"Even if he won't apologize, he should at least explain."}],"notes":"Often as ～とは言わないまでも (\"I won't go as far as to say ..., but\"). Despite the similar form, it has a different meaning from ～までもない (N1, \"not necessary\").","related":["n1-made-mo-nai"]},
{"id":"n1-nari-tomo","pattern":"～なりとも","level":"N1","category":"Satzstrukturen","meaning":"at least; even if only (a little)","explanation":"After expressions for a small amount (少し, 一目, 多少, わずか), なりとも means \"even if it is only ...\". Written in style and polite; often in requests and wishes.","formation":"Noun / quantity + なりとも","examples":[{"japanese":"少しなりともお役に立てれば幸いです。","romaji":"Sukoshi nari tomo oyaku ni tatereba saiwai desu.","german":"I would be glad if I could be of even a little help to you.","cloze":{"start":2,"answer":"なりとも","quiz":{"level":"N1","japanese":"少しなりともお役に立てれば幸いです。","german":"I would be glad if I could be of even a little help to you.","start":2,"answer":"なりとも","acceptedAnswers":["なりとも","でも"],"distractors":[{"text":"たりとも","reason":"たりとも goes with a negative (\"not in the least\") and does not fit a wish."},{"text":"ばかりか","reason":"ばかりか (\"not only ... but also\") makes no sense here."},{"text":"ずくめ","reason":"ずくめ (\"consisting only of\") cannot follow 少し."}]}}},{"japanese":"一目なりとも会いたい。","romaji":"Hitome nari tomo aitai.","german":"I want to see them, even if only for a moment."},{"japanese":"多少なりとも経験のある方を募集しています。","romaji":"Tashō nari tomo keiken no aru kata o boshū shite imasu.","german":"We are looking for people with at least some experience."}],"notes":"Formulaic in 多少なりとも and 少しなりとも. Same meaning but more everyday: ～でも (少しでも). Do not confuse with ～たりとも～ない (\"not even ...\") or ～なり～なり (\"either ... or\").","related":["n1-tari-tomo-nai","n1-nari-nari"]},
{"id":"n1-ttara-nai","pattern":"～ったらない","level":"N1","category":"Satzstrukturen","meaning":"indescribably, extremely (feeling)","explanation":"After words for a feeling or impression, ったらない means \"so much that it cannot be described\". Colloquial; more written: ～といったらない.","formation":"い-adj (dictionary form) + ったらない; Noun (often ending in ～さ) + といったらない","examples":[{"japanese":"一人で夜道を歩くのは怖いったらない。","romaji":"Hitori de yomichi o aruku no wa kowai ttara nai.","german":"Walking alone on the street at night is incredibly scary.","cloze":{"start":12,"answer":"ったらない","quiz":{"level":"N1","japanese":"一人で夜道を歩くのは怖いったらない。","german":"Walking alone on the street at night is incredibly scary.","start":12,"answer":"ったらない","acceptedAnswers":["ったらない","ったらありゃしない","といったらない"],"distractors":[{"text":"ことはない","reason":"怖いことはない means \"there's no need to be afraid\", the opposite."},{"text":"わけがない","reason":"わけがない (\"can't possibly ...\") denies the feeling instead of intensifying it."},{"text":"ほどではない","reason":"ほどではない (\"not that much\") weakens instead of intensifying."}]}}},{"japanese":"満員電車で転んで、恥ずかしいったらなかった。","romaji":"Man'in densha de koronde, hazukashii ttara nakatta.","german":"I fell over on a packed train; it was so embarrassing."},{"japanese":"彼の自慢話のしつこさといったらない。","romaji":"Kare no jiman banashi no shitsukosa to ittara nai.","german":"His bragging is unbearably relentless."}],"notes":"Mostly for negative feelings (怖い, 寂しい, 腹立たしい), less often positive ones (うれしいったらない). Do not confuse with ～ったら (N2), which singles out a person with annoyance. Similar: ～極まりない (N1, written) and ～てしょうがない (N2).","related":["n2-ttara","n1-kiwamarinai","n2-te-shou-ga-nai"]},
{"id":"n1-koto-tote","pattern":"～こととて","level":"N1","category":"Satzstrukturen","meaning":"since (after all) ...; because ... (apologetic)","explanation":"A written-style reason, usually to ask for leniency or to apologize: because the circumstances are such, what follows is understandable. Sounds old-fashioned and polite.","formation":"Verb (plain form) / な-adj + な / Noun + の + こととて","examples":[{"japanese":"慣れないこととて、ご迷惑をおかけしました。","romaji":"Narenai koto tote, gomeiwaku o okake shimashita.","german":"Being unaccustomed to this, I have caused you trouble.","cloze":{"start":4,"answer":"こととて","quiz":{"level":"N1","japanese":"慣れないこととて、ご迷惑をおかけしました。","german":"Being unaccustomed to this, I have caused you trouble.","start":4,"answer":"こととて","acceptedAnswers":["こととて","ので","ものだから"],"distractors":[{"text":"ことなく","reason":"ことなく (\"without ...\") gives no reason."},{"text":"ことか","reason":"ことか is an exclamation (\"how much!\") and cannot introduce a subordinate clause."},{"text":"ことには","reason":"慣れないことには means \"unless one gets used to it\" and requires a negative consequence, not an apology."}]}}},{"japanese":"子どものしたこととて、どうか許してやってください。","romaji":"Kodomo no shita koto tote, dōka yurushite yatte kudasai.","german":"It was only a child's doing, so please forgive him."},{"japanese":"急なこととて、十分な準備ができませんでした。","romaji":"Kyū na koto tote, jūbun na junbi ga dekimasen deshita.","german":"Because it was so sudden, we could not prepare sufficiently."}],"notes":"Almost only in apologies and formal letters; also with the classical negative: 慣れぬこととて. Everyday: ～ので／～ものだから. Do not confuse with ～とて on its own (\"even, too\", 私とて).","related":["n2-mono-dakara"]},
{"id":"n1-temae","pattern":"～手前","level":"N1","category":"Satzstrukturen","meaning":"since one has (already) ... (and must save face)","explanation":"手前 (literally \"in front of oneself\") justifies an action out of concern for one's own standing: because you have said or done something, or are in front of others, you have no other choice.","formation":"Verb (dictionary form / た-form) + 手前; Noun + の + 手前","examples":[{"japanese":"手伝うと約束した手前、今さら断れない。","romaji":"Tetsudau to yakusoku shita temae, imasara kotowarenai.","german":"Since I promised to help, I can't back out now.","cloze":{"start":8,"answer":"手前","quiz":{"level":"N1","japanese":"手伝うと約束した手前、今さら断れない。","german":"Since I promised to help, I can't back out now.","start":8,"answer":"手前","acceptedAnswers":["手前","以上","以上は","からには"],"distractors":[{"text":"くせに","reason":"くせに (\"even though\") reproaches others and does not justify a compulsion."},{"text":"とたん","reason":"とたん (\"the moment that\") is purely temporal."},{"text":"ついでに","reason":"ついでに (\"while one is at it\") does not fit a compulsion."}]}}},{"japanese":"子どもの手前、親が約束を破るわけにはいかない。","romaji":"Kodomo no temae, oya ga yakusoku o yaburu wake ni wa ikanai.","german":"In front of their children, parents can't break a promise."},{"japanese":"「絶対に勝つ」と言った手前、負けるわけにはいかない。","romaji":"\"Zettai ni katsu\" to itta temae, makeru wake ni wa ikanai.","german":"Having said \"I'll definitely win\", I can't afford to lose."}],"notes":"The second part usually expresses a compulsion: ～わけにはいかない, ～なければならない, ～しかない. Related: ～以上(は) and ～上は (N2), which give reasons more neutrally. As a noun, 手前 also means \"just before, on this side of\" (駅の手前).","related":["n2-ijou-wa","n2-ue-wa"]},
{"id":"n1-ikansen","pattern":"いかんせん","level":"N1","category":"Satzstrukturen","meaning":"unfortunately (nothing can be done)","explanation":"An introductory adverb: you would like to, but the circumstances unfortunately do not allow it. Written style; from classical 如何せん, \"what can one do\".","formation":"(positive clause + が／けれど,) いかんせん + obstacle","examples":[{"japanese":"手伝いたいのだが、いかんせん時間がない。","romaji":"Tetsudaitai no da ga, ikansen jikan ga nai.","german":"I'd like to help, but unfortunately I don't have the time.","cloze":{"start":9,"answer":"いかんせん","quiz":{"level":"N1","japanese":"手伝いたいのだが、いかんせん時間がない。","german":"I'd like to help, but unfortunately I don't have the time.","start":9,"answer":"いかんせん","acceptedAnswers":["いかんせん","残念ながら","あいにく"],"distractors":[{"text":"いかにも","reason":"いかにも (\"truly, very typical\") affirms and does not introduce an obstacle."},{"text":"せっかく","reason":"せっかく (\"specially, going to the trouble\") does not fit before an obstacle such as lack of time."},{"text":"さすがに","reason":"さすがに (\"as expected; still not\") does not fit an introduction expressing regret."}]}}},{"japanese":"計画はいいが、いかんせん予算が足りない。","romaji":"Keikaku wa ii ga, ikansen yosan ga tarinai.","german":"The plan is good, but unfortunately the budget isn't enough."},{"japanese":"この店の料理はおいしいが、いかんせん値段が高すぎる。","romaji":"Kono mise no ryōri wa oishii ga, ikansen nedan ga takasugiru.","german":"The food at this restaurant is delicious, but unfortunately it's far too expensive."}],"notes":"Usually follows a が／けれど clause that names the positive point. Also written in kanji: 如何せん. Do not confuse with ～いかんで／～いかんによらず (N1, \"depending on\"), which go back to the same 如何.","related":["n1-ikan-de-wa","n1-ikan-ni-yorazu"]},
{"id":"keigo-sonkeigo-oninaru","pattern":"お～になる","level":"N4","category":"Keigo","subcategory":"尊敬語","meaning":"general respectful verb form","explanation":"お～になる is the standard respectful (尊敬語) verb form, used to describe the actions of a person higher in the hierarchy. It expresses respect toward the person performing the action.","formation":"お + Verb (ます-stem) + になる","examples":[{"japanese":"先生はもうお帰りになりました。","romaji":"Sensei wa mō okaeri ni narimashita.","german":"The teacher has already gone home.","cloze":{"start":5,"answer":"お帰りになりました","quiz":{"level":"N4","japanese":"先生はもうお帰りになりました。","german":"The teacher has already gone home.","start":5,"answer":"お帰りになりました","acceptedAnswers":["お帰りになりました","帰られました"],"distractors":[{"text":"お帰りをなりました","reason":"The honorific construction uses に."},{"text":"お帰りになりませんでした","reason":"This negates going home."},{"text":"お帰るになりました","reason":"お～になる uses the verb stem."}],"promptKana":"せんせいはもう＿＿＿。"}}},{"japanese":"社長はこの本をお読みになりましたか。","romaji":"Shachō wa kono hon o oyomi ni narimashita ka.","german":"Did the company president read this book?"},{"japanese":"どうぞお座りになってください。","romaji":"Dōzo osuwari ni natte kudasai.","german":"Please have a seat."}],"notes":"Cannot be used with verbs that already have their own respectful form (e.g. いらっしゃる instead of お行きになる). Used only for other people's actions, never for your own.","related":["keigo-sonkeigo-reraru","keigo-kenjougo-osuru","n3-keigo-sonkei"]},
{"id":"keigo-sonkeigo-reraru","pattern":"～れる・られる","level":"N4","category":"Keigo","subcategory":"尊敬語","meaning":"passive form as a respectful expression","explanation":"The passive form (～れる / ～られる) can also be used as a respectful way of speaking. It is less formal than お～になる but very common in everyday use.","formation":"五段動詞: ～あ段 + れる ／ 一段動詞: ～stem + られる","examples":[{"japanese":"部長は何時に来られますか。","romaji":"Buchō wa nanji ni koraremasu ka.","german":"What time will the department manager be coming?","cloze":{"start":6,"answer":"来られます","quiz":{"level":"N4","japanese":"部長は何時に来られますか。","german":"What time will the department manager be coming?","start":6,"answer":"来られます","acceptedAnswers":["来られます","いらっしゃいます","お越しになります"],"distractors":[{"text":"来るられます","reason":"The honorific form of 来る is 来られます."},{"text":"来られるます","reason":"ます does not follow the dictionary form."},{"text":"来られました","reason":"This asks about the past instead of the upcoming arrival."}],"promptKana":"ぶちょうはなんじに＿＿＿か。"}}},{"japanese":"先生はもう帰られました。","romaji":"Sensei wa mō kaeraremashita.","german":"The teacher has already gone home."},{"japanese":"社長はこの件について話されました。","romaji":"Shachō wa kono ken ni tsuite hanasaremashita.","german":"The company president spoke about this matter."}],"notes":"Can be confused with the passive. Context determines the meaning. Compared with お～になる, this form is somewhat less formal but easier to form.","related":["keigo-sonkeigo-oninaru","keigo-kenjougo-osuru"]},
{"id":"keigo-sonkeigo-irassharu","pattern":"いらっしゃる","level":"N4","category":"Keigo","subcategory":"尊敬語","meaning":"respectful form of いる / ある / 行く / 来る","explanation":"いらっしゃる is the special respectful form of the verbs いる (to be, to be present), 行く (to go) and 来る (to come). It is used to talk about where a respected person is or about their coming and going.","formation":"Directly replaces いる / ある / 行く / 来る (ます-form: いらっしゃいます)","examples":[{"japanese":"田中先生はいらっしゃいますか。","romaji":"Tanaka-sensei wa irasshaimasu ka.","german":"Is Tanaka-sensei in?","cloze":{"start":5,"answer":"いらっしゃいます","quiz":{"level":"N4","japanese":"田中先生はいらっしゃいますか。","german":"Is Tanaka-sensei in?","start":5,"answer":"いらっしゃいます","acceptedAnswers":["いらっしゃいます","おいでになります"],"distractors":[{"text":"いらっしゃるます","reason":"The polite form is いらっしゃいます."},{"text":"いらっしゃいませんた","reason":"This is not a verb form."},{"text":"いらっしゃいました","reason":"This asks about past rather than current presence."}],"promptKana":"たなかせんせいは＿＿＿か。"}}},{"japanese":"明日のパーティーにいらっしゃいますか。","romaji":"Ashita no pātī ni irasshaimasu ka.","german":"Will you be coming to the party tomorrow?"},{"japanese":"お客様がいらっしゃいました。","romaji":"Okyakusama ga irasshaimashita.","german":"The customer/guest has arrived."}],"notes":"One of the most important keigo verbs. The imperative form いらっしゃいませ is used as a greeting in shops. The ます-form is いらっしゃいます (not いらっしゃります).","related":["keigo-kenjougo-mairu","keigo-kenjougo-oru","n3-keigo-sonkei"]},
{"id":"keigo-sonkeigo-ossharu","pattern":"おっしゃる","level":"N4","category":"Keigo","subcategory":"尊敬語","meaning":"respectful form of 言う (to say)","explanation":"おっしゃる is the special respectful form of 言う (to say). It is used when describing what a person higher in the hierarchy has said.","formation":"Directly replaces 言う (ます-form: おっしゃいます)","examples":[{"japanese":"先生がおっしゃったとおりにします。","romaji":"Sensei ga osshatta tōri ni shimasu.","german":"I will do as the teacher said.","cloze":{"start":3,"answer":"おっしゃった","quiz":{"level":"N4","japanese":"先生がおっしゃったとおりにします。","german":"I will do as the teacher said.","start":3,"answer":"おっしゃった","acceptedAnswers":["おっしゃった","言われた"],"distractors":[{"text":"おっしゃりました","reason":"The plain form is needed before とおり here; besides, the polite form is おっしゃいました."},{"text":"おっしゃるた","reason":"This is not a past form."},{"text":"おっしゃらなかった","reason":"This denies that the teacher said it."}],"promptKana":"せんせいが＿＿＿とおりにします。"}}},{"japanese":"部長は何とおっしゃいましたか。","romaji":"Buchō wa nan to osshaimashita ka.","german":"What did the department manager say?"}],"notes":"The past form is おっしゃった (not おっしゃいった). The ます-form is おっしゃいます. Frequently used in business situations.","related":["keigo-kenjougo-mousu","keigo-kenjougo-moushiageru"]},
{"id":"keigo-sonkeigo-meshiagaru","pattern":"召し上がる","level":"N3","category":"Keigo","subcategory":"尊敬語","meaning":"respectful form of 食べる / 飲む (to eat / to drink)","explanation":"召し上がる is the special respectful form of 食べる (to eat) and 飲む (to drink). It is used to talk respectfully about a higher-ranking person eating or drinking.","formation":"Directly replaces 食べる / 飲む (ます-form: 召し上がります)","examples":[{"japanese":"どうぞ召し上がってください。","romaji":"Dōzo meshiagatte kudasai.","german":"Please help yourself. / Please eat/drink.","cloze":{"start":3,"answer":"召し上がって","quiz":{"level":"N3","japanese":"どうぞ召し上がってください。","german":"Please help yourself. / Please eat/drink.","start":3,"answer":"召し上がって","acceptedAnswers":["召し上がって"],"distractors":[{"text":"召し上がった","reason":"ください requires the て-form."},{"text":"召し上がります","reason":"The ます-form does not fit before ください."},{"text":"召し上がらないで","reason":"This asks the person not to eat."}]}}},{"japanese":"コーヒーを召し上がりますか。","romaji":"Kōhī o meshiagarimasu ka.","german":"Would you like some coffee?"},{"japanese":"社長はもう昼食を召し上がりました。","romaji":"Shachō wa mō chūshoku o meshiagarimashita.","german":"The company president has already had lunch."}],"notes":"Very polite and respectful. In less formal situations お食べになる can also be used, but 召し上がる is the preferred form in business contexts.","related":["keigo-kenjougo-itadaku"]},
{"id":"keigo-sonkeigo-goranninaru","pattern":"ご覧になる","level":"N3","category":"Keigo","subcategory":"尊敬語","meaning":"respectful form of 見る (to see/look)","explanation":"ご覧になる is the special respectful form of 見る (to see). It is used to describe respectfully that a higher-ranking person looks at or reads something.","formation":"ご覧 + になる (ます-form: ご覧になります)","examples":[{"japanese":"この資料をご覧になりましたか。","romaji":"Kono shiryō o goran ni narimashita ka.","german":"Have you looked at these documents?","cloze":{"start":5,"answer":"ご覧になりました","quiz":{"level":"N3","japanese":"この資料をご覧になりましたか。","german":"Have you looked at these documents?","start":5,"answer":"ご覧になりました","acceptedAnswers":["ご覧になりました"],"distractors":[{"text":"ご覧をなりました","reason":"The honorific expression uses に."},{"text":"ご覧になるました","reason":"This is not a polite past."},{"text":"ご覧になりる","reason":"This is not a verb form."}]}}},{"japanese":"どうぞご覧ください。","romaji":"Dōzo goran kudasai.","german":"Please take a look."}],"notes":"ご覧ください is the shortened and very common polite form for \"please look\". You often see it in museums, in presentations and in business emails.","related":["keigo-kenjougo-haikensuru"]},
{"id":"keigo-sonkeigo-gozonji","pattern":"ご存じ","level":"N3","category":"Keigo","subcategory":"尊敬語","meaning":"respectful form of 知っている (to know)","explanation":"ご存じ is the respectful form of 知っている (to know). It is used as a noun or na-adjective to ask or say respectfully whether a higher-ranking person knows something.","formation":"ご存じ + です / ですか (negative: ご存じない / ご存じありません)","examples":[{"japanese":"この言葉をご存じですか。","cloze":{"start":5,"answer":"ご存じ","quiz":{"level":"N3","japanese":"この言葉をご存じですか。","german":"Do you know this word?","start":5,"answer":"ご存じ","acceptedAnswers":["ご存じ","ご存知"],"distractors":[{"text":"ご存じます","reason":"存じ, as a nominal honorific form, does not take ます before です here."},{"text":"ご存じな","reason":"No な comes before です here."},{"text":"ご存じを","reason":"を cannot stand before です here."}]}},"romaji":"Kono kotoba o gozonji desu ka.","german":"Do you know this word?"},{"japanese":"ご存じのとおり、来月から新しいルールが始まります。","cloze":{"start":0,"answer":"ご存じ"},"romaji":"Gozonji no tōri, raigetsu kara atarashii rūru ga hajimarimasu.","german":"As you know, new rules take effect from next month."}],"notes":"Strictly speaking, ご存じ is a noun, but it is used like a stative verb. The spelling ご存知 (with 知) also exists, but ご存じ is the standard spelling.","related":["keigo-kenjougo-zonjiru","keigo-kenjougo-zonjiageru"]},
{"id":"keigo-sonkeigo-nasaru","pattern":"なさる","level":"N3","category":"Keigo","subcategory":"尊敬語","meaning":"respectful form of する (to do)","explanation":"なさる is the special respectful form of する (to do). It is used to talk respectfully about the actions of a higher-ranking person.","formation":"Directly replaces する (ます-form: なさいます) ／ お + Noun + なさる","examples":[{"japanese":"何をなさいますか。","romaji":"Nani o nasaimasu ka.","german":"What would you like to do?","cloze":{"start":2,"answer":"なさいます","quiz":{"level":"N3","japanese":"何をなさいますか。","german":"What would you like to do?","start":2,"answer":"なさいます","acceptedAnswers":["なさいます"],"distractors":[{"text":"なさるます","reason":"The polite form is なさいます."},{"text":"なさいますた","reason":"This is not a verb form."},{"text":"なさるでした","reason":"This is not a polite verb form."}]}}},{"japanese":"先生は研究をなさっています。","romaji":"Sensei wa kenkyū o nasatte imasu.","german":"The professor is doing research."},{"japanese":"お好きなようになさってください。","romaji":"Osuki na yō ni nasatte kudasai.","german":"Please do as you like."}],"notes":"The imperative form なさい is also used for instructions to children or subordinates (e.g. 早くしなさい). The ます-form is なさいます (not なさります).","related":["keigo-kenjougo-itasu"]},
{"id":"keigo-sonkeigo-kudasaru","pattern":"くださる","level":"N4","category":"Keigo","subcategory":"尊敬語","meaning":"respectful form of くれる (to give, to me/us)","explanation":"くださる is the respectful form of くれる and expresses that a higher-ranking person gives something to the speaker or the speaker's group, or does something for them. It emphasizes the recipient's gratitude.","formation":"Directly replaces くれる (ます-form: くださいます)","examples":[{"japanese":"先生が辞書をくださいました。","romaji":"Sensei ga jisho o kudasaimashita.","german":"The teacher gave me a dictionary.","cloze":{"start":6,"answer":"くださいました","quiz":{"level":"N4","japanese":"先生が辞書をくださいました。","german":"The teacher gave me a dictionary.","start":6,"answer":"くださいました","acceptedAnswers":["くださいました"],"distractors":[{"text":"くださるました","reason":"The polite past is くださいました."},{"text":"くださいませんでした","reason":"This negates the gift."},{"text":"くださりますた","reason":"This is not a polite past form."}],"promptKana":"せんせいがじしょを＿＿＿。"}}},{"japanese":"部長がアドバイスをくださいました。","romaji":"Buchō ga adobaisu o kudasaimashita.","german":"The department manager gave me some advice."}],"notes":"The imperative form ください (please give / please do) is the most frequently used form of this verb. The ます-form is くださいます (not くださります).","related":["keigo-kenjougo-sashiageru","keigo-kenjougo-itadaku","keigo-sonkeigo-okudasaru"]},
{"id":"keigo-sonkeigo-okudasaru","pattern":"お～くださる","level":"N3","category":"Keigo","subcategory":"尊敬語","meaning":"respectful request form / thanks for an action","explanation":"お～くださる is used to express respectfully that a higher-ranking person does something for the speaker, or to make a polite request. It combines the respectful prefix お with くださる.","formation":"お + Verb (ます-stem) + くださる ／ お + Verb (ます-stem) + ください","examples":[{"japanese":"お待ちくださいませ。","romaji":"Omachi kudasaimase.","german":"Please wait. (very polite)","cloze":{"start":0,"answer":"お待ちください","quiz":{"level":"N3","japanese":"お待ちくださいませ。","german":"Please wait. (very polite)","start":0,"answer":"お待ちください","acceptedAnswers":["お待ちください"],"distractors":[{"text":"お待つください","reason":"The honorific request requires the verb stem."},{"text":"お待ちくださる","reason":"ませ requires the polite stem form before it."},{"text":"お待ちくださいた","reason":"This is not a request form."}]}}},{"japanese":"先生がお教えくださいました。","romaji":"Sensei ga ooshie kudasaimashita.","german":"The teacher kindly taught me."},{"japanese":"ご連絡くださりありがとうございます。","romaji":"Gorenraku kudasari arigatō gozaimasu.","german":"Thank you very much for getting in touch."}],"notes":"お～ください is the most common form in everyday language. お～くださいませ sounds even more polite and is used in the service industry. With Sino-Japanese words, ご is used instead of お (e.g. ご確認ください).","related":["keigo-sonkeigo-kudasaru","keigo-kenjougo-osuru"]},
{"id":"keigo-kenjougo-osuru","pattern":"お～する / お～いたす","level":"N4","category":"Keigo","subcategory":"謙譲語","meaning":"general humble verb form","explanation":"お～する, or the even humbler form お～いたす, is the standard humble (謙譲語) verb form. It is used to lower one's own actions in relation to a higher-ranking person.","formation":"お + Verb (ます-stem) + する / いたす ／ ご + Sino-Japanese noun + する / いたす","examples":[{"japanese":"お荷物をお持ちします。","romaji":"Onimotsu o omochi shimasu.","german":"I'll carry your luggage for you.","cloze":{"start":4,"answer":"お持ちします","quiz":{"level":"N4","japanese":"お荷物をお持ちします。","german":"I'll carry your luggage for you.","start":4,"answer":"お持ちします","acceptedAnswers":["お持ちします","お持ちいたします"],"distractors":[{"text":"お持つします","reason":"お～する needs the verb stem 持ち."},{"text":"お持ちしません","reason":"This negates the carrying."},{"text":"お持ちするます","reason":"The polite ending is します."}],"promptKana":"おにもつを＿＿＿。"}}},{"japanese":"後ほどご連絡いたします。","romaji":"Nochihodo gorenraku itashimasu.","german":"I will contact you later."},{"japanese":"ご案内いたします。","romaji":"Goannai itashimasu.","german":"Let me show you the way."}],"notes":"お～いたす is humbler than お～する. With Sino-Japanese words, ご is used instead of お (e.g. ご説明する). Used only for your own actions that affect another person.","related":["keigo-sonkeigo-oninaru","keigo-kenjougo-itasu","n3-keigo-kenjou"]},
{"id":"keigo-kenjougo-mairu","pattern":"参る","level":"N4","category":"Keigo","subcategory":"謙譲語","meaning":"humble form of 行く / 来る (to go / to come)","explanation":"参る is the special humble (謙譲語) form of 行く (to go) and 来る (to come). It is used to express one's own movement humbly toward a higher-ranking person.","formation":"Directly replaces 行く / 来る (ます-form: 参ります)","examples":[{"japanese":"すぐに参ります。","romaji":"Sugu ni mairimasu.","german":"I'll be right there.","cloze":{"start":3,"answer":"参ります","quiz":{"level":"N4","japanese":"すぐに参ります。","german":"I'll be right there.","start":3,"answer":"参ります","acceptedAnswers":["参ります"],"distractors":[{"text":"参るます","reason":"The polite form is 参ります."},{"text":"参りません","reason":"This negates coming."},{"text":"参りました","reason":"This reports the past instead of coming right away."}],"promptKana":"すぐに＿＿＿。"}}},{"japanese":"明日、御社に参ります。","romaji":"Ashita, onsha ni mairimasu.","german":"I will come to your company tomorrow."},{"japanese":"タクシーで参りました。","romaji":"Takushī de mairimashita.","german":"I came by taxi."}],"notes":"参る is also used colloquially to mean \"to give up\" or \"to be worn out\" (参った！= I give up!). In a keigo context it is exclusively the humble form of 行く/来る.","related":["keigo-sonkeigo-irassharu","keigo-kenjougo-ukagau","n3-keigo-kenjou"]},
{"id":"keigo-kenjougo-mousu","pattern":"申す","level":"N4","category":"Keigo","subcategory":"謙譲語","meaning":"humble form of 言う (to say)","explanation":"申す is the humble (謙譲語) form of 言う (to say). It is used to express humbly that you yourself are saying something, especially in self-introductions and general statements.","formation":"Directly replaces 言う (ます-form: 申します)","examples":[{"japanese":"田中と申します。","romaji":"Tanaka to mōshimasu.","german":"My name is Tanaka.","cloze":{"start":3,"answer":"申します","quiz":{"level":"N4","japanese":"田中と申します。","german":"My name is Tanaka.","start":3,"answer":"申します","acceptedAnswers":["申します","いいます"],"distractors":[{"text":"申すます","reason":"The polite form is 申します."},{"text":"申しません","reason":"This negates giving the name."},{"text":"申すでした","reason":"This is not a polite verb form."}],"promptKana":"たなかと＿＿＿。"}}},{"japanese":"一言申してもよろしいでしょうか。","romaji":"Hitokoto mōshite mo yoroshii deshō ka.","german":"May I say a word?"}],"notes":"申す is less formal than 申し上げる. In self-introductions on the phone or in business, ～と申します is the standard form. 申す can also be used as 丁重語 (courteous language) without specific reference to a higher-ranking person.","related":["keigo-sonkeigo-ossharu","keigo-kenjougo-moushiageru"]},
{"id":"keigo-kenjougo-moushiageru","pattern":"申し上げる","level":"N3","category":"Keigo","subcategory":"謙譲語","meaning":"very humble form of 言う (to say/tell)","explanation":"申し上げる is the most formal humble form of 言う. It is used when telling something directly to a higher-ranking person and expresses the greatest humility.","formation":"Directly replaces 言う (ます-form: 申し上げます)","examples":[{"japanese":"一つ申し上げたいことがあります。","romaji":"Hitotsu mōshiagetai koto ga arimasu.","german":"There is one thing I would like to tell you.","cloze":{"start":2,"answer":"申し上げたい","quiz":{"level":"N3","japanese":"一つ申し上げたいことがあります。","german":"There is one thing I would like to tell you.","start":2,"answer":"申し上げたい","acceptedAnswers":["申し上げたい"],"distractors":[{"text":"申し上げたいな","reason":"たい modifies こと without な."},{"text":"申し上げるたい","reason":"たい follows the verb stem."},{"text":"申し上げたくない","reason":"This negates the wish to tell."}]}}},{"japanese":"お礼を申し上げます。","romaji":"Orei o mōshiagemasu.","german":"I would like to express my thanks."},{"japanese":"心よりお詫び申し上げます。","romaji":"Kokoro yori owabi mōshiagemasu.","german":"I sincerely apologize."}],"notes":"申し上げる is more formal than 申す and is used especially in business letters, emails and formal speeches. Common set expressions: お礼を申し上げる, お詫び申し上げる, お願い申し上げる.","related":["keigo-sonkeigo-ossharu","keigo-kenjougo-mousu"]},
{"id":"keigo-kenjougo-itadaku","pattern":"いただく","level":"N4","category":"Keigo","subcategory":"謙譲語","meaning":"humble form of もらう / 食べる / 飲む","explanation":"いただく is the humble (謙譲語) form of もらう (to receive) as well as of 食べる (to eat) and 飲む (to drink). It expresses gratitude and humility when receiving or consuming something.","formation":"Directly replaces もらう / 食べる / 飲む (ます-form: いただきます)","examples":[{"japanese":"いただきます。","romaji":"Itadakimasu.","german":"Thank you for the food (said before eating). (lit.: I humbly receive.)","cloze":{"start":0,"answer":"いただきます","quiz":{"level":"N4","japanese":"いただきます。","german":"Thank you for the food (said before eating). (lit.: I humbly receive.)","start":0,"answer":"いただきます","acceptedAnswers":["いただきます"],"distractors":[{"text":"いただくます","reason":"The polite form is いただきます."},{"text":"いただきません","reason":"This negates receiving instead of starting the meal."},{"text":"いただくでした","reason":"This is not a polite verb form."}],"promptKana":"＿＿＿。"}}},{"japanese":"先生にこの本をいただきました。","romaji":"Sensei ni kono hon o itadakimashita.","german":"I received this book from the teacher."},{"japanese":"お茶をいただけますか。","romaji":"Ocha o itadakemasu ka.","german":"Could I have some tea?"}],"notes":"いただきます before a meal is one of the best-known Japanese expressions. ～ていただく is an important construction for expressing humbly that someone does something for you.","related":["keigo-sonkeigo-meshiagaru","keigo-sonkeigo-kudasaru","keigo-teinei-itadakemasenka"]},
{"id":"keigo-kenjougo-haikensuru","pattern":"拝見する","level":"N3","category":"Keigo","subcategory":"謙譲語","meaning":"humble form of 見る (to see/look at)","explanation":"拝見する is the humble (謙譲語) form of 見る (to see). The kanji 拝 means \"to bow\" and therefore expresses special deference. It is used when looking at something that belongs to a higher-ranking person.","formation":"拝見 + する (ます-form: 拝見します / 拝見いたします)","examples":[{"japanese":"お名刺を拝見してもよろしいですか。","romaji":"Omeishi o haiken shite mo yoroshii desu ka.","german":"May I have a look at your business card?","cloze":{"start":4,"answer":"拝見して","quiz":{"level":"N3","japanese":"お名刺を拝見してもよろしいですか。","german":"May I have a look at your business card?","start":4,"answer":"拝見して","acceptedAnswers":["拝見して"],"distractors":[{"text":"拝見した","reason":"もよろしい requires the て-form before it."},{"text":"拝見します","reason":"The ます-form does not fit before も."},{"text":"拝見する","reason":"The dictionary form does not fit before もよろしい."}]}}},{"japanese":"資料を拝見いたしました。","romaji":"Shiryō o haiken itashimashita.","german":"I have looked through the documents."}],"notes":"拝見する is often raised further with いたす to 拝見いたす. Similar expressions with 拝: 拝読する (to read, humble), 拝借する (to borrow, humble), 拝聴する (to listen, humble).","related":["keigo-sonkeigo-goranninaru"]},
{"id":"keigo-kenjougo-zonjiru","pattern":"存じる","level":"N3","category":"Keigo","subcategory":"謙譲語","meaning":"humble form of 知る / 思う (to know / to think)","explanation":"存じる is the humble (謙譲語) form of 知る (to know) and 思う (to think, to believe). It is used to express humbly that you know something or hold an opinion.","formation":"Directly replaces 知る / 思う (ます-form: 存じます / 存じております)","examples":[{"japanese":"その件は存じております。","romaji":"Sono ken wa zonjite orimasu.","german":"I am aware of that matter.","cloze":{"start":4,"answer":"存じております","quiz":{"level":"N3","japanese":"その件は存じております。","german":"I am aware of that matter.","start":4,"answer":"存じております","acceptedAnswers":["存じております"],"distractors":[{"text":"存じておるます","reason":"The polite form is おります."},{"text":"存じておりません","reason":"This negates the knowing."},{"text":"存じるております","reason":"存じる forms the て-form 存じて."}]}}},{"japanese":"私もそのように存じます。","romaji":"Watashi mo sono yō ni zonjimasu.","german":"I think so too."},{"japanese":"存じません。","romaji":"zonjimasen.","german":"I don't know. (humble)"}],"notes":"存じる refers to things and facts. For people, 存じ上げる is used. 存じております is the usual business form for \"I know\".","related":["keigo-sonkeigo-gozonji","keigo-kenjougo-zonjiageru"]},
{"id":"keigo-kenjougo-zonjiageru","pattern":"存じ上げる","level":"N2","category":"Keigo","subcategory":"謙譲語","meaning":"humble form of 知っている (to know someone)","explanation":"存じ上げる is the humbler form of 存じる and is mainly used to express humbly that you know a person. It is more respectful than 存じる.","formation":"Directly replaces 知っている (for people) (ます-form: 存じ上げております)","examples":[{"japanese":"山田先生のことは存じ上げております。","romaji":"Yamada-sensei no koto wa zonjiagete orimasu.","german":"I know Professor Yamada.","cloze":{"start":8,"answer":"存じ上げております","quiz":{"level":"N2","japanese":"山田先生のことは存じ上げております。","german":"I know Professor Yamada.","start":8,"answer":"存じ上げております","acceptedAnswers":["存じ上げております"],"distractors":[{"text":"存じ上げておりません","reason":"This denies knowing the person."},{"text":"存じ上げるおります","reason":"おります needs the て-connection."},{"text":"存じ上げておりますた","reason":"The polite past ends in ました."}]}}},{"japanese":"お名前はかねてより存じ上げております。","romaji":"Onamae wa kanete yori zonjiagete orimasu.","german":"I have known your name for a long time."}],"notes":"存じ上げる is mainly used for people, while 存じる tends to be used for things and facts. The negative 存じ上げません is a polite way of saying that you don't know someone.","related":["keigo-sonkeigo-gozonji","keigo-kenjougo-zonjiru"]},
{"id":"keigo-kenjougo-itasu","pattern":"いたす","level":"N4","category":"Keigo","subcategory":"謙譲語","meaning":"humble form of する (to do)","explanation":"いたす is the humble (謙譲語) form of する (to do). It is used to express one's own actions humbly toward a higher-ranking person.","formation":"Directly replaces する (ます-form: いたします)","examples":[{"japanese":"私がいたします。","romaji":"Watashi ga itashimasu.","german":"I will do it.","cloze":{"start":2,"answer":"いたします","quiz":{"level":"N4","japanese":"私がいたします。","german":"I will do it.","start":2,"answer":"いたします","acceptedAnswers":["いたします","します"],"distractors":[{"text":"いたすます","reason":"The polite form is いたします."},{"text":"いたしません","reason":"This negates doing it."},{"text":"いたすでした","reason":"This is not a polite verb form."}],"promptKana":"わたしが＿＿＿。"}}},{"japanese":"確認いたします。","romaji":"Kakunin itashimasu.","german":"I will check."},{"japanese":"失礼いたします。","romaji":"Shitsurei itashimasu.","german":"Excuse me (for disturbing you). / Goodbye."}],"notes":"いたす is also used as 丁重語 (courteous language) without specific reference to a higher-ranking person, e.g. in public announcements or formal notices. 失礼いたします is one of the most common business phrases.","related":["keigo-sonkeigo-nasaru","keigo-kenjougo-osuru"]},
{"id":"keigo-kenjougo-sashiageru","pattern":"差し上げる","level":"N3","category":"Keigo","subcategory":"謙譲語","meaning":"humble form of あげる (to give)","explanation":"差し上げる is the humble (謙譲語) form of あげる (to give). It is used to express humbly that you give something to a higher-ranking person.","formation":"Directly replaces あげる (ます-form: 差し上げます)","examples":[{"japanese":"先生にお花を差し上げました。","romaji":"Sensei ni ohana o sashiagemashita.","german":"I presented the teacher with flowers.","cloze":{"start":6,"answer":"差し上げました","quiz":{"level":"N3","japanese":"先生にお花を差し上げました。","german":"I presented the teacher with flowers.","start":6,"answer":"差し上げました","acceptedAnswers":["差し上げました"],"distractors":[{"text":"差し上げるました","reason":"This is not a polite past."},{"text":"差し上げませんでした","reason":"This negates the presenting."},{"text":"差し上げますた","reason":"This is not a past form."}]}}},{"japanese":"何か差し上げましょうか。","romaji":"Nanika sashiagemashō ka.","german":"May I offer you something?"},{"japanese":"お土産を差し上げたいのですが。","romaji":"Omiyage o sashiagetai no desu ga.","german":"I would like to give you a souvenir."}],"notes":"差し上げる can seem excessive when used in everyday situations. ～て差し上げる (doing something for someone) can sound condescending and should be used with care.","related":["keigo-sonkeigo-kudasaru","keigo-kenjougo-itadaku"]},
{"id":"keigo-kenjougo-ukagau","pattern":"伺う","level":"N4","category":"Keigo","subcategory":"謙譲語","meaning":"humble form of 行く / 聞く / 訪ねる","explanation":"伺う is the humble (謙譲語) form of 行く (to go), 聞く (to ask, to hear) and 訪ねる (to visit). It is used to express humbly that you visit someone, ask something or hear about something.","formation":"Directly replaces 行く / 聞く / 訪ねる (ます-form: 伺います)","examples":[{"japanese":"明日、お伺いしてもよろしいですか。","romaji":"Ashita, oukagai shite mo yoroshii desu ka.","german":"May I visit you tomorrow?","cloze":{"start":3,"answer":"お伺いして","quiz":{"level":"N4","japanese":"明日、お伺いしてもよろしいですか。","german":"May I visit you tomorrow?","start":3,"answer":"お伺いして","acceptedAnswers":["お伺いして","伺って"],"distractors":[{"text":"お伺いした","reason":"The て-form is needed before もよろしい here."},{"text":"お伺いします","reason":"The ます-form does not fit before もよろしい."},{"text":"お伺いする","reason":"The dictionary form does not fit before もよろしい."}],"promptKana":"あした、＿＿＿もよろしいですか。"}}},{"japanese":"一つ伺いたいのですが。","romaji":"Hitotsu ukagaitai no desu ga.","german":"There's one thing I'd like to ask."},{"japanese":"お話は伺っております。","romaji":"Ohanashi wa ukagatte orimasu.","german":"I have already heard about it."}],"notes":"伺う is one of the most versatile keigo verbs, since it can replace three different verbs. お伺いする is a double honorific form that is frequently used in practice.","related":["keigo-sonkeigo-irassharu","keigo-kenjougo-mairu"]},
{"id":"keigo-kenjougo-oru","pattern":"おる","level":"N4","category":"Keigo","subcategory":"謙譲語","meaning":"humble form of いる (to be, to be present)","explanation":"おる is the humble (謙譲語) form of いる (to be, to be present). It is used to talk humbly about your own whereabouts or state.","formation":"Directly replaces いる (ます-form: おります) ／ ～ております (humble progressive form)","examples":[{"japanese":"田中はただいま外出しております。","romaji":"Tanaka wa tadaima gaishutsu shite orimasu.","german":"Tanaka is out of the office at the moment.","cloze":{"start":11,"answer":"おります","quiz":{"level":"N4","japanese":"田中はただいま外出しております。","german":"Tanaka is out of the office at the moment.","start":11,"answer":"おります","acceptedAnswers":["おります","います"],"distractors":[{"text":"おるます","reason":"The polite form is おります."},{"text":"おりました","reason":"This reports the past instead of current absence."},{"text":"おりません","reason":"This negates being out."}],"promptKana":"たなかはただいまがいしゅつして＿＿＿。"}}},{"japanese":"東京に住んでおります。","romaji":"Tōkyō ni sunde orimasu.","german":"I live in Tokyo."},{"japanese":"お待ちしておりました。","romaji":"Omachi shite orimashita.","german":"We have been expecting you."}],"notes":"～ております is the humble form of ～ています and is used very frequently in business. On the phone, your own side is always described with おる, the other side with いらっしゃる.","related":["keigo-sonkeigo-irassharu"]},
{"id":"keigo-teinei-degozaimasu","pattern":"～でございます","level":"N3","category":"Keigo","subcategory":"丁寧語","meaning":"very polite form of です (to be)","explanation":"～でございます is the highest level of politeness for です. It belongs to 丁寧語 (polite language) and is used in very formal situations, in customer service and in business contexts.","formation":"Noun / な-adjective + でございます ／ い-adjective (く-form) + ございます","examples":[{"japanese":"こちらが会議室でございます。","cloze":{"start":7,"answer":"でございます","quiz":{"level":"N3","japanese":"こちらが会議室でございます。","german":"This is the conference room.","start":7,"answer":"でございます","acceptedAnswers":["でございます"],"distractors":[{"text":"でござるます","reason":"The polite form is ございます."},{"text":"でございません","reason":"This denies identifying the room."},{"text":"をございます","reason":"The copula starts with で here."}]}},"romaji":"Kochira ga kaigishitsu de gozaimasu.","german":"This is the conference room."},{"japanese":"お手洗いはあちらでございます。","cloze":{"start":8,"answer":"でございます"},"romaji":"Otearai wa achira de gozaimasu.","german":"The restroom is over there."},{"japanese":"ありがとうございます。","romaji":"Arigatō gozaimasu.","german":"Thank you very much."}],"notes":"ありがとうございます actually contains ございます (from ある). With い-adjectives: 早い → 早うございます (archaic, rare). でございます is frequently used in hotels, restaurants and customer service.","related":["keigo-kenjougo-oru","keigo-kenjougo-itasu"]},
{"id":"keigo-teinei-itadakemasenka","pattern":"～ていただけませんか","level":"N3","category":"Keigo","subcategory":"丁寧語","meaning":"very polite request form (Could you please ...?)","explanation":"～ていただけませんか is a very polite request form that uses the humble form いただく in the negative potential. It is more polite than ～てくれませんか or ～てもらえませんか.","formation":"Verb (て-form) + いただけませんか ／ いただけないでしょうか (even more polite)","examples":[{"japanese":"もう少しゆっくり話していただけませんか。","cloze":{"start":10,"answer":"ていただけませんか","quiz":{"level":"N3","japanese":"もう少しゆっくり話していただけませんか。","german":"Could you please speak a little more slowly?","start":10,"answer":"ていただけませんか","acceptedAnswers":["ていただけませんか"],"distractors":[{"text":"たいただけませんか","reason":"いただく follows the て-form."},{"text":"ていただけるませんか","reason":"This is not a polite verb form."},{"text":"ていただけませんた","reason":"This is not a question form."}]}},"romaji":"Mō sukoshi yukkuri hanashite itadakemasen ka.","german":"Could you please speak a little more slowly?"},{"japanese":"この書類を確認していただけないでしょうか。","romaji":"Kono shorui o kakunin shite itadakenai deshō ka.","german":"Would it be possible for you to check this document?"},{"japanese":"お名前を教えていただけませんか。","cloze":{"start":6,"answer":"ていただけませんか"},"romaji":"Onamae o oshiete itadakemasen ka.","german":"Could you please tell me your name?"}],"notes":"Politeness levels of requests: ～てくれ < ～てください < ～てくれませんか < ～ていただけませんか < ～ていただけないでしょうか. The last form is the most polite and is used for very formal requests.","related":["keigo-kenjougo-itadaku","keigo-teinei-sasete-itadaku","n4-te-itadakemasenka"]},
{"id":"keigo-teinei-sasete-itadaku","pattern":"～させていただく","level":"N3","category":"Keigo","subcategory":"丁寧語","meaning":"humble permission form (Allow me to ...)","explanation":"～させていただく combines the causative (～させる) with the humble form いただく and expresses that you humbly ask for permission to do something. It implies gratitude for the permission granted.","formation":"Verb (させ-form) + ていただく (ます-form: ～させていただきます)","examples":[{"japanese":"本日は休ませていただきます。","romaji":"Honjitsu wa yasumasete itadakimasu.","german":"With your permission, I will take today off.","cloze":{"start":3,"answer":"休ませていただきます","quiz":{"level":"N3","japanese":"本日は休ませていただきます。","german":"With your permission, I will take today off.","start":3,"answer":"休ませていただきます","acceptedAnswers":["休ませていただきます"],"distractors":[{"text":"休ませたいただきます","reason":"いただく follows the て-form."},{"text":"休ませていただきません","reason":"This negates the announced day off."},{"text":"休むさせていただきます","reason":"The causative form is 休ませる."}]}}},{"japanese":"私が説明させていただきます。","romaji":"Watashi ga setsumei sasete itadakimasu.","german":"Allow me to explain."},{"japanese":"確認させていただいてもよろしいでしょうか。","romaji":"Kakunin sasete itadaite mo yoroshii deshō ka.","german":"Would it be all right if I checked this?"}],"notes":"This form is very common in modern Japanese, but is also often overused. Language purists criticize its inflationary use (e.g. on TV shows: 歌わせていただきます). Correct use presupposes that permission from another person actually exists.","related":["keigo-kenjougo-itadaku","keigo-teinei-itadakemasenka"]},
{"id":"keigo-business-oisogashii","pattern":"お忙しいところ恐れ入りますが","level":"N2","category":"Keigo","subcategory":"ビジネス敬語","meaning":"I'm sorry to trouble you when you are busy","explanation":"お忙しいところ恐れ入りますが is a fixed business courtesy formula used before a request. It shows consideration for the other person's time and introduces a request respectfully.","formation":"お忙しいところ恐れ入りますが + request/inquiry","examples":[{"japanese":"お忙しいところ恐れ入りますが、ご確認いただけますでしょうか。","cloze":{"start":0,"answer":"お忙しいところ恐れ入りますが","quiz":{"level":"N2","japanese":"お忙しいところ恐れ入りますが、ご確認いただけますでしょうか。","german":"I'm sorry to trouble you when you're busy, but could you please check this?","start":0,"answer":"お忙しいところ恐れ入りますが","acceptedAnswers":["お忙しいところ恐れ入りますが","お忙しいところ恐縮ですが"],"distractors":[{"text":"お忙しいところ恐れ入るますが","reason":"ます requires the verb stem 入り."},{"text":"お忙しいところ恐れ入りますを","reason":"を does not link the request to the introduction here."},{"text":"お忙しいところ恐れ入りますな","reason":"な does not form a link to the request here."}]}},"romaji":"Oisogashii tokoro osoreirimasu ga, gokakunin itadakemasu deshō ka.","german":"I'm sorry to trouble you when you're busy, but could you please check this?"},{"japanese":"お忙しいところ恐れ入りますが、少々お時間をいただけませんか。","cloze":{"start":0,"answer":"お忙しいところ恐れ入りますが"},"romaji":"Oisogashii tokoro osoreirimasu ga, shōshō ojikan o itadakemasen ka.","german":"Sorry to bother you when you're busy, but could you spare me a little of your time?"}],"notes":"This formula is especially common in business emails and phone calls. Variants: お忙しい中 (onaka), ご多忙のところ. 恐れ入ります on its own means \"excuse me\" or \"thank you very much\" and is an important business phrase.","related":["keigo-teinei-itadakemasenka","keigo-business-osewani"]},
{"id":"keigo-business-osewani","pattern":"お世話になっております","level":"N3","category":"Keigo","subcategory":"ビジネス敬語","meaning":"business greeting formula (thank you for your continued support)","explanation":"お世話になっております is the most important business greeting formula in Japan. It is used at the beginning of emails, phone calls and meetings with business partners and expresses gratitude for the existing business relationship.","formation":"お世話になっております (fixed formula, invariable) ／ variant: いつもお世話になっております","examples":[{"japanese":"いつもお世話になっております。ABC株式会社の田中です。","cloze":{"start":3,"answer":"お世話になっております","quiz":{"level":"N3","japanese":"いつもお世話になっております。ABC株式会社の田中です。","german":"Thank you as always for your support. This is Tanaka from ABC Corporation.","start":3,"answer":"お世話になっております","acceptedAnswers":["お世話になっております"],"distractors":[{"text":"お世話になっておるます","reason":"The polite form is おります."},{"text":"お世話をなっております","reason":"The expression uses に."},{"text":"お世話になっておりません","reason":"This negates the ongoing support."}]}},"romaji":"Itsumo osewa ni natte orimasu. ABC kabushiki gaisha no Tanaka desu.","german":"Thank you as always for your support. This is Tanaka from ABC Corporation."},{"japanese":"お世話になっております。先日の件について連絡いたしました。","cloze":{"start":0,"answer":"お世話になっております"},"romaji":"Osewa ni natte orimasu. Senjitsu no ken ni tsuite renraku itashimashita.","german":"Thank you for your continued support. I am getting in touch about the matter from the other day."},{"japanese":"大変お世話になりました。","romaji":"Taihen osewa ni narimashita.","german":"Thank you so much for everything you have done for me. (when saying goodbye)"}],"notes":"This formula is used almost automatically at the beginning of every business email or phone call. On first contact, you say instead: 初めまして or お世話になります (future form). 大変お世話になりました is used when saying goodbye or at the end of the year.","related":["keigo-teinei-degozaimasu","keigo-business-oisogashii"]},
{"id":"keigo-sonkeigo-okudasai","pattern":"お～ください","level":"N4","category":"Keigo","subcategory":"尊敬語","meaning":"polite request / instruction","explanation":"お～ください is the basic polite request form in Japanese. You put お in front of the verb stem (ます-form without ます) and add ください. This form is used to ask someone respectfully for something. It is one of the first keigo forms learners should get to know.","formation":"お + verb stem (ます-form without ます) + ください","examples":[{"japanese":"こちらにお座りください。","romaji":"Kochira ni osuwari kudasai.","german":"Please have a seat here.","cloze":{"start":4,"answer":"お座りください","quiz":{"level":"N4","japanese":"こちらにお座りください。","german":"Please have a seat here.","start":4,"answer":"お座りください","acceptedAnswers":["お座りください","お掛けください","座ってください"],"distractors":[{"text":"お座るください","reason":"The request uses the stem 座り."},{"text":"お座りません","reason":"This is not a correct request."},{"text":"お座りくださいました","reason":"This reports the past instead of asking the person to sit."}],"promptKana":"こちらに＿＿＿。"}}},{"japanese":"少々お待ちください。","romaji":"Shōshō omachi kudasai.","german":"Please wait a moment."},{"japanese":"お気をつけてお帰りください。","romaji":"Oki wo tsukete okaeri kudasai.","german":"Please take care on your way home."}],"notes":"This is one of the most frequently used keigo forms in everyday life. With Sino-Japanese words, the prefix ご is used instead of お (e.g. ご連絡ください).","related":["keigo-sonkeigo-kudasaru","keigo-sonkeigo-oninaru"]},
{"id":"keigo-sonkeigo-teirassharu","pattern":"～ていらっしゃる","level":"N3","category":"Keigo","subcategory":"尊敬語","meaning":"respectful progressive form (someone is doing something right now)","explanation":"～ていらっしゃる is the sonkeigo (respectful) form of ～ている. You use it to describe the ongoing state or current action of a person you are showing respect to. Here いらっしゃる replaces いる in the て-form construction.","formation":"Verb て-form + いらっしゃる (いらっしゃいます in the ます-form)","examples":[{"japanese":"社長は今、会議室で待っていらっしゃいます。","romaji":"Shachō wa ima, kaigishitsu de matte irasshaimasu.","german":"The company president is waiting in the conference room right now.","cloze":{"start":9,"answer":"待っていらっしゃいます","quiz":{"level":"N3","japanese":"社長は今、会議室で待っていらっしゃいます。","german":"The company president is waiting in the conference room right now.","start":9,"answer":"待っていらっしゃいます","acceptedAnswers":["待っていらっしゃいます"],"distractors":[{"text":"待ったいらっしゃいます","reason":"Here いらっしゃる follows the て-form."},{"text":"待っていらっしゃいません","reason":"This negates the waiting."},{"text":"待っていらっしゃるます","reason":"The polite form is いらっしゃいます."}]}}},{"japanese":"先生はもう帰っていらっしゃいますか。","romaji":"Sensei wa mō kaette irasshaimasu ka.","german":"Is the teacher back already?"},{"japanese":"お客様はロビーでお待ちになっていらっしゃいます。","romaji":"Okyakusama wa robī de omachi ni natte irasshaimasu.","german":"The guest is waiting in the lobby."}],"notes":"This form sounds more natural and more polite than the ～ている form. In spoken language, いらっしゃる is often shortened to いらっしゃいます.","related":["keigo-sonkeigo-irassharu","keigo-sonkeigo-oninaru"]},
{"id":"keigo-sonkeigo-omieninaru","pattern":"お見えになる","level":"N2","category":"Keigo","subcategory":"尊敬語","meaning":"to appear; to arrive (respectful)","explanation":"お見えになる is an especially polite sonkeigo form used when a respected person appears or arrives. It is the respectful counterpart of 来る (to come) or 現れる (to appear) and is often used in business, especially when customers or important guests arrive.","formation":"お見えになる (fixed expression, conjugated like a godan verb)","examples":[{"japanese":"山田部長がお見えになりました。","romaji":"Yamada buchō ga omie ni narimashita.","german":"Department Manager Yamada has arrived.","cloze":{"start":5,"answer":"お見えになりました","quiz":{"level":"N2","japanese":"山田部長がお見えになりました。","german":"Department Manager Yamada has arrived.","start":5,"answer":"お見えになりました","acceptedAnswers":["お見えになりました","お越しになりました"],"distractors":[{"text":"お見えになるました","reason":"The polite past is formed with なりました."},{"text":"お見えになりた","reason":"The plain past of なる is なった."},{"text":"お見えになりませんでした","reason":"This negates the arrival."}]}}},{"japanese":"お客様がお見えになったら、すぐにお通しください。","romaji":"Okyakusama ga omie ni nattara, sugu ni otōshi kudasai.","german":"When the customer arrives, please show them in right away."},{"japanese":"先生はまだお見えになっていません。","romaji":"Sensei wa mada omie ni natte imasen.","german":"The teacher has not arrived yet."}],"notes":"お見えになる is used especially often at reception desks and in the hotel industry. It sounds more formal than いらっしゃる.","related":["keigo-sonkeigo-irassharu","keigo-sonkeigo-okoshininaru"]},
{"id":"keigo-sonkeigo-okoshininaru","pattern":"お越しになる","level":"N2","category":"Keigo","subcategory":"尊敬語","meaning":"to come; to come over (respectful)","explanation":"お越しになる is an elegant sonkeigo form of 来る (to come). It is used to describe respectfully that a person of higher status is coming or visiting a place. This form is especially common in business language and in formal invitations.","formation":"お越しになる (fixed expression) / お越しください (as a request)","examples":[{"japanese":"先生は何時にお越しになりましたか。","romaji":"Sensei wa nanji ni okoshi ni narimashita ka.","german":"What time did the teacher come?","cloze":{"start":6,"answer":"お越しになりました","quiz":{"level":"N2","japanese":"先生は何時にお越しになりましたか。","german":"What time did the teacher come?","start":6,"answer":"お越しになりました","acceptedAnswers":["お越しになりました","お見えになりました","いらっしゃいました"],"distractors":[{"text":"お越しになるました","reason":"The polite past is なりました."},{"text":"お越しになりた","reason":"The plain past of なる is なった."},{"text":"お越しにならないました","reason":"The polite negative is not formed with ないました."}]}}},{"japanese":"ぜひ弊社にお越しください。","romaji":"Zehi heisha ni okoshi kudasai.","german":"Please do come and visit our company."},{"japanese":"遠方からお越しになったお客様には駐車場をご用意しております。","romaji":"Enpō kara okoshi ni natta okyakusama ni wa chūshajō wo goyōi shite orimasu.","german":"We have prepared parking for guests who have come from far away."}],"notes":"お越しください is used very often in event invitations and business emails. The combination お越しいただく is an especially polite hybrid of sonkeigo and kenjōgo.","related":["keigo-sonkeigo-irassharu","keigo-sonkeigo-omieninaru","keigo-sonkeigo-oideninaru"]},
{"id":"keigo-sonkeigo-oideninaru","pattern":"おいでになる","level":"N2","category":"Keigo","subcategory":"尊敬語","meaning":"to go; to come; to be (respectful)","explanation":"おいでになる is a versatile sonkeigo form that serves as the respectful version of 行く (to go), 来る (to come) and いる (to be). Which meaning is intended becomes clear from the context. This form is used especially in refined conversation.","formation":"おいでになる (fixed expression, conjugated as a godan verb)","examples":[{"japanese":"明日の会議においでになりますか。","romaji":"Ashita no kaigi ni oide ni narimasu ka.","german":"Will you be coming to tomorrow's meeting?","cloze":{"start":6,"answer":"おいでになります","quiz":{"level":"N2","japanese":"明日の会議においでになりますか。","german":"Will you be coming to tomorrow's meeting?","start":6,"answer":"おいでになります","acceptedAnswers":["おいでになります","いらっしゃいます","お越しになります"],"distractors":[{"text":"おいでになるます","reason":"ます needs the stem なり."},{"text":"おいでになりますた","reason":"The polite past ends in ました."},{"text":"おいでにならないます","reason":"ない does not take ます attached to it."}]}}},{"japanese":"社長は今、東京においでになります。","romaji":"Shachō wa ima, Tōkyō ni oide ni narimasu.","german":"The company president is currently in Tokyo."},{"japanese":"どちらへおいでになりますか。","romaji":"Dochira e oide ni narimasu ka.","german":"Where are you going?"}],"notes":"Depending on context, おいでになる can replace three different verbs (行く、来る、いる). It sounds somewhat softer and less formal than いらっしゃる, but is still considered full-fledged sonkeigo.","related":["keigo-sonkeigo-irassharu","keigo-sonkeigo-okoshininaru"]},
{"id":"keigo-sonkeigo-omotomeninaru","pattern":"お求めになる","level":"N2","category":"Keigo","subcategory":"尊敬語","meaning":"to buy; to purchase (respectful)","explanation":"お求めになる is the sonkeigo form of 買う (to buy). It is used to talk respectfully about a purchase made by a customer or a person of higher status. This form is especially common in retail, department stores and customer service.","formation":"お求めになる (お + 求め + になる)","examples":[{"japanese":"こちらの商品はどちらでお求めになりましたか。","romaji":"Kochira no shōhin wa dochira de omotome ni narimashita ka.","german":"Where did you purchase this product?","cloze":{"start":11,"answer":"お求めになりました","quiz":{"level":"N2","japanese":"こちらの商品はどちらでお求めになりましたか。","german":"Where did you purchase this product?","start":11,"answer":"お求めになりました","acceptedAnswers":["お求めになりました","お買いになりました"],"distractors":[{"text":"お求めになるました","reason":"The polite past is なりました."},{"text":"お求めになりた","reason":"The plain past of なる is なった."},{"text":"お求めにならないます","reason":"ない does not take ます attached to it."}]}}},{"japanese":"お求めになりやすい価格でご提供しております。","romaji":"Omotome ni nariyasui kakaku de goteikyō shite orimasu.","german":"We offer it at a price that makes it easy to buy."},{"japanese":"この商品はオンラインでもお求めになれます。","romaji":"Kono shōhin wa onrain de mo omotome ni naremasu.","german":"You can also purchase this product online."}],"notes":"In department stores and upscale shops, お求めになる is used as standard instead of 買う. The shorter form お求めください is often used in advertising materials.","related":["keigo-sonkeigo-oninaru","keigo-sonkeigo-goriyouninaru"]},
{"id":"keigo-sonkeigo-goriyouninaru","pattern":"ご利用になる","level":"N3","category":"Keigo","subcategory":"尊敬語","meaning":"to use; to make use of (respectful)","explanation":"ご利用になる is the sonkeigo form of 利用する (to use). Because 利用 is a Sino-Japanese word, the prefix ご is used instead of お. You come across this form very often in public announcements, shops and service businesses.","formation":"ご利用になる / ご利用ください (as a request)","examples":[{"japanese":"エレベーターをご利用になりますか。","romaji":"Erebētā wo goriyō ni narimasu ka.","german":"Would you like to use the elevator?","cloze":{"start":7,"answer":"ご利用になります","quiz":{"level":"N3","japanese":"エレベーターをご利用になりますか。","german":"Would you like to use the elevator?","start":7,"answer":"ご利用になります","acceptedAnswers":["ご利用になります"],"distractors":[{"text":"ご利用をなります","reason":"The honorific expression uses に."},{"text":"ご利用になるます","reason":"This is not a polite form."},{"text":"ご利用になりますた","reason":"This is not a verb form."}]}}},{"japanese":"当サービスをご利用いただきありがとうございます。","romaji":"Tō sābisu wo goriyō itadaki arigatō gozaimasu.","german":"Thank you for using our service."},{"japanese":"ご自由にご利用ください。","romaji":"Gojiyū ni goriyō kudasai.","german":"Please feel free to use it."}],"notes":"You hear ご利用ください all the time on trains, at airports and in shops. It is one of the most frequent sonkeigo forms in everyday Japanese life.","related":["keigo-sonkeigo-oninaru","keigo-sonkeigo-okudasai"]},
{"id":"keigo-kenjougo-haishakusuru","pattern":"拝借する","level":"N2","category":"Keigo","subcategory":"謙譲語","meaning":"to borrow (humble)","explanation":"拝借する (はいしゃくする) is the kenjōgo form of 借りる (to borrow). The kanji 拝 expresses humility and reverence. You use this form when you yourself borrow something from a person of higher status, lowering your own action and thereby showing respect indirectly.","formation":"拝借する (fixed verb, conjugated like する)","examples":[{"japanese":"お手洗いを拝借してもよろしいでしょうか。","romaji":"Otearai wo haishaku shite mo yoroshii deshō ka.","german":"Might I use your restroom?","cloze":{"start":5,"answer":"拝借して","quiz":{"level":"N2","japanese":"お手洗いを拝借してもよろしいでしょうか。","german":"Might I use your restroom?","start":5,"answer":"拝借して","acceptedAnswers":["拝借して","お借りして"],"distractors":[{"text":"拝借した","reason":"The て-form comes before もよろしい."},{"text":"拝借する","reason":"The て-form comes before もよろしい."},{"text":"拝借します","reason":"The finite polite form does not fit before もよろしい."}]}}},{"japanese":"少々お時間を拝借できますでしょうか。","romaji":"Shōshō ojikan wo haishaku dekimasu deshō ka.","german":"Could I borrow a little of your time?"},{"japanese":"こちらの資料を拝借いたします。","romaji":"Kochira no shiryō wo haishaku itashimasu.","german":"I will humbly borrow these documents."}],"notes":"拝借する is used not only for physical objects but also abstractly (e.g. お時間を拝借する = to be allowed to take up someone's time). With いたします at the end it becomes even more polite.","related":["keigo-kenjougo-haikensuru","keigo-kenjougo-haidokusuru"]},
{"id":"keigo-kenjougo-haidokusuru","pattern":"拝読する","level":"N2","category":"Keigo","subcategory":"謙譲語","meaning":"to read (humble)","explanation":"拝読する (はいどくする) is the kenjōgo form of 読む (to read). It is used to say humbly that you have read something written or sent by a respected person. The kanji 拝 signals humility.","formation":"拝読する (fixed verb, conjugated like する)","examples":[{"japanese":"先生のご著書を拝読いたしました。","romaji":"Sensei no gochosho wo haidoku itashimashita.","german":"I have read your book (humble).","cloze":{"start":7,"answer":"拝読いたしました","quiz":{"level":"N2","japanese":"先生のご著書を拝読いたしました。","german":"I have read your book (humble).","start":7,"answer":"拝読いたしました","acceptedAnswers":["拝読いたしました","読ませていただきました"],"distractors":[{"text":"拝読いたしませんでした","reason":"This negates the reading."},{"text":"拝読いたすました","reason":"ます needs the stem いたし."},{"text":"拝読いたしましたます","reason":"The polite endings cannot be doubled."}]}}},{"japanese":"メールを拝読しました。ご提案について検討いたします。","romaji":"Mēru wo haidoku shimashita. Goteian ni tsuite kentō itashimasu.","german":"I have read your email. I will consider your proposal."},{"japanese":"報告書を拝読し、大変勉強になりました。","romaji":"Hōkokusho wo haidoku shi, taihen benkyō ni narimashita.","german":"I read the report and learned a great deal from it."}],"notes":"拝読する belongs to the group of 拝～する kenjōgo verbs (拝見する、拝借する、拝読する). They all express that you carry out the action humbly toward a person of higher status.","related":["keigo-kenjougo-haikensuru","keigo-kenjougo-haishakusuru"]},
{"id":"keigo-kenjougo-omenikakaru","pattern":"お目にかかる","level":"N2","category":"Keigo","subcategory":"謙譲語","meaning":"to meet (humble)","explanation":"お目にかかる is the kenjōgo form of 会う (to meet). Literally it means something like \"to come before the eyes (of a respected person)\". You use this form to express your own act of meeting humbly and thereby show respect to the other person.","formation":"お目にかかる (fixed expression, conjugated as a godan verb)","examples":[{"japanese":"お目にかかれて光栄です。","romaji":"Ome ni kakarete kōei desu.","german":"It is an honor to meet you.","cloze":{"start":0,"answer":"お目にかかれて","quiz":{"level":"N2","japanese":"お目にかかれて光栄です。","german":"It is an honor to meet you.","start":0,"answer":"お目にかかれて","acceptedAnswers":["お目にかかれて","お会いできて"],"distractors":[{"text":"お目にかかれた","reason":"The finite past does not connect with 光栄です here."},{"text":"お目にかかるます","reason":"ます needs the stem かかり."},{"text":"お目にかかれます","reason":"The finite polite form does not connect with 光栄です here."}]}}},{"japanese":"またお目にかかれる日を楽しみにしております。","romaji":"Mata ome ni kakareru hi wo tanoshimi ni shite orimasu.","german":"I look forward to the day we meet again."},{"japanese":"以前、パーティーでお目にかかったことがございます。","romaji":"Izen, pātī de ome ni kakatta koto ga gozaimasu.","german":"We have met once before, at a party."}],"notes":"お目にかかる is more formal than お会いする and is used especially at first meetings or in very polite contexts. The phrase お目にかかれて光栄です is a classic greeting formula.","related":["keigo-kenjougo-ukagau","keigo-kenjougo-omenikakeru"]},
{"id":"keigo-kenjougo-omenikakeru","pattern":"お目にかける","level":"N2","category":"Keigo","subcategory":"謙譲語","meaning":"to show; to present (humble)","explanation":"お目にかける is the kenjōgo form of 見せる (to show). Literally it means \"to offer to the eyes (of a respected person)\". You use this form when you humbly show or present something to a person of higher status.","formation":"お目にかける (fixed expression, conjugated as an ichidan verb)","examples":[{"japanese":"新しいデザインをお目にかけたいと思います。","romaji":"Atarashii dezain wo ome ni kaketai to omoimasu.","german":"I would like to show you the new design."},{"japanese":"恥ずかしい作品ですが、お目にかけます。","romaji":"Hazukashii sakuhin desu ga, ome ni kakemasu.","german":"It is an embarrassing piece of work, but let me show it to you."},{"japanese":"近いうちに完成品をお目にかけることができると存じます。","cloze":{"start":9,"answer":"お目にかける","quiz":{"level":"N2","japanese":"近いうちに完成品をお目にかけることができると存じます。","german":"I believe I will be able to show you the finished product soon.","start":9,"answer":"お目にかける","acceptedAnswers":["お目にかける","ご覧に入れる"],"distractors":[{"text":"お目にかけます","reason":"The plain verb form comes before こと."},{"text":"お目にかけて","reason":"The て-form cannot modify こと attributively here."},{"text":"お目にかけるます","reason":"ます is not attached to かける."}]}},"romaji":"Chikai uchi ni kansei-hin wo ome ni kakeru koto ga dekiru to zonjimasu.","german":"I believe I will be able to show you the finished product soon."}],"notes":"お目にかける is the counterpart of お目にかかる (to meet). かける = to offer, かかる = to meet. These two forms are often confused, so it is important to know the difference.","related":["keigo-kenjougo-omenikakaru","keigo-kenjougo-haikensuru"]},
{"id":"keigo-kenjougo-uketamawaru","pattern":"承る","level":"N2","category":"Keigo","subcategory":"謙譲語","meaning":"to receive; to hear; to accept (humble)","explanation":"承る (うけたまわる) is a very formal kenjōgo form that serves as the humble version of 聞く (to hear), 受ける (to receive) and 引き受ける (to take on). It is often used in customer service and in formal business situations to express that you are taking an order, a request or information.","formation":"承る (fixed verb, conjugated as a godan verb)","examples":[{"japanese":"ご注文を承りました。","romaji":"Gochūmon wo uketamawarimashita.","german":"I have taken your order.","cloze":{"start":4,"answer":"承りました","quiz":{"level":"N2","japanese":"ご注文を承りました。","german":"I have taken your order.","start":4,"answer":"承りました","acceptedAnswers":["承りました","お受けしました"],"distractors":[{"text":"承りませんでした","reason":"This negates taking the order."},{"text":"承るました","reason":"The polite past needs the stem 承り."},{"text":"承りましたます","reason":"The polite endings cannot be doubled."}]}}},{"japanese":"ご予約を承ります。お名前をお願いいたします。","romaji":"Goyoyaku wo uketamawarimasu. Onamae wo onegai itashimasu.","german":"I will take your reservation. May I have your name, please?"},{"japanese":"ご用件を承りましょうか。","romaji":"Goyōken wo uketamawari mashō ka.","german":"May I ask what this is regarding?"}],"notes":"承る is one of the most formal kenjōgo verbs and is used especially in the service industry. It sounds more professional than お聞きする or お受けする.","related":["keigo-kenjougo-itadaku","keigo-kenjougo-choudaisuru"]},
{"id":"keigo-kenjougo-kashikomarimashita","pattern":"かしこまりました","level":"N3","category":"Keigo","subcategory":"謙譲語","meaning":"certainly; understood (very polite)","explanation":"かしこまりました is the most polite way to say \"understood\" or \"certainly\". It is used in customer service, hotels, restaurants and formal business situations. It is considerably more formal than 分かりました and shows that you respectfully accept the instruction or request.","formation":"かしこまりました (fixed form, past form of かしこまる)","examples":[{"japanese":"かしこまりました。すぐにお持ちいたします。","cloze":{"start":0,"answer":"かしこまりました","quiz":{"level":"N3","japanese":"かしこまりました。すぐにお持ちいたします。","german":"Certainly. I will bring it right away.","start":0,"answer":"かしこまりました","acceptedAnswers":["かしこまりました"],"distractors":[{"text":"かしこまるました","reason":"The polite past is かしこまりました."},{"text":"かしこまりますた","reason":"This is not a verb form."},{"text":"かしこまりません","reason":"This refuses the request instead of accepting it."}]}},"romaji":"Kashikomarimashita. Sugu ni omochi itashimasu.","german":"Certainly. I will bring it right away."},{"japanese":"かしこまりました。変更を承ります。","cloze":{"start":0,"answer":"かしこまりました"},"romaji":"Kashikomarimashita. Henkō wo uketamawarimasu.","german":"Understood. I will take care of the change."},{"japanese":"14時にご予約ですね。かしこまりました。","cloze":{"start":11,"answer":"かしこまりました"},"romaji":"Jūyo-ji ni goyoyaku desu ne. Kashikomarimashita.","german":"A reservation for 2 p.m., correct? Certainly."}],"notes":"The politeness levels for \"understood\" are: 分かった → 分かりました → 承知しました → かしこまりました. かしこまりました is the highest level and is used almost exclusively by service staff toward customers.","related":["keigo-kenjougo-uketamawaru","keigo-kenjougo-itasu"]},
{"id":"keigo-kenjougo-choudaisuru","pattern":"頂戴する","level":"N2","category":"Keigo","subcategory":"謙譲語","meaning":"to receive; to accept (humble)","explanation":"頂戴する (ちょうだいする) is a formal kenjōgo form of もらう (to get/receive). It expresses humbly that you receive something from a person of higher status. Compared with いただく, 頂戴する sounds somewhat more formal still and is often used in business and in the restaurant industry.","formation":"頂戴する (fixed verb, conjugated like する) / 頂戴いたす (even more polite)","examples":[{"japanese":"お名刺を頂戴できますでしょうか。","romaji":"Omeishi wo chōdai dekimasu deshō ka.","german":"Might I have your business card?","cloze":{"start":4,"answer":"頂戴できます","quiz":{"level":"N2","japanese":"お名刺を頂戴できますでしょうか。","german":"Might I have your business card?","start":4,"answer":"頂戴できます","acceptedAnswers":["頂戴できます","いただけます"],"distractors":[{"text":"頂戴できるます","reason":"ます is not attached to the dictionary form."},{"text":"頂戴できますた","reason":"The polite past ends in ました."},{"text":"頂戴できないました","reason":"The polite negative is not formed with ないました."}]}}},{"japanese":"お時間を頂戴し、ありがとうございます。","romaji":"Ojikan wo chōdai shi, arigatō gozaimasu.","german":"Thank you for giving me your time."},{"japanese":"ご意見を頂戴したく、ご連絡いたしました。","romaji":"Goiken wo chōdai shitaku, gorenraku itashimashita.","german":"I am contacting you because I would like to hear your opinion."}],"notes":"頂戴 is also used as a standalone word without する in children's language (ちょうだい = please give me). In business, お名刺を頂戴できますか is a standard formula when exchanging business cards.","related":["keigo-kenjougo-itadaku","keigo-kenjougo-uketamawaru"]},
{"id":"keigo-business-shitsureiitashimasu","pattern":"失礼いたします","level":"N3","category":"Keigo","subcategory":"ビジネス敬語","meaning":"excuse me; I'll take my leave (formal)","explanation":"失礼いたします is a versatile formal phrase used in various situations: when entering or leaving a room, when hanging up the phone, when interrupting an activity or when saying goodbye. いたします is the kenjōgo form of します and makes the phrase especially polite.","formation":"失礼いたします (fixed phrase) / 失礼いたしました (past: apology for something that already happened)","examples":[{"japanese":"お先に失礼いたします。","cloze":{"start":3,"answer":"失礼いたします","quiz":{"level":"N3","japanese":"お先に失礼いたします。","german":"Excuse me for leaving before you. (said when leaving work for the day)","start":3,"answer":"失礼いたします","acceptedAnswers":["失礼いたします"],"distractors":[{"text":"失礼いたすます","reason":"The polite form is いたします."},{"text":"失礼いたしません","reason":"This negates the leave-taking."},{"text":"失礼いたしますた","reason":"This is not a verb form."}]}},"romaji":"Osaki ni shitsurei itashimasu.","german":"Excuse me for leaving before you. (said when leaving work for the day)"},{"japanese":"それでは、失礼いたします。","cloze":{"start":5,"answer":"失礼いたします"},"romaji":"Sore dewa, shitsurei itashimasu.","german":"Well then, goodbye. (as a farewell on the phone)"},{"japanese":"失礼いたします。書類をお届けに参りました。","cloze":{"start":0,"answer":"失礼いたします"},"romaji":"Shitsurei itashimasu. Shorui wo otodoke ni mairimashita.","german":"Excuse me for disturbing you. I have come to deliver the documents."}],"notes":"お先に失礼いたします is the standard phrase when you leave the office before your colleagues. On the phone, you say 失礼いたします before hanging up. The past form 失礼いたしました is used as an apology for a rudeness already committed.","related":["keigo-kenjougo-itasu","keigo-business-osoreirimasuga"]},
{"id":"keigo-business-osoreirimasuga","pattern":"恐れ入りますが","level":"N2","category":"Keigo","subcategory":"ビジネス敬語","meaning":"excuse me, but... / I'm sorry, but...","explanation":"恐れ入りますが is a polite introductory phrase (クッション言葉) used before a request, a question or a potentially unwelcome matter. It softens what follows and shows consideration for the other person. This form is indispensable in Japanese business life.","formation":"恐れ入りますが + request/question/matter","examples":[{"japanese":"恐れ入りますが、お名前をもう一度お聞かせいただけますか。","cloze":{"start":0,"answer":"恐れ入りますが","quiz":{"level":"N2","japanese":"恐れ入りますが、お名前をもう一度お聞かせいただけますか。","german":"Excuse me, but could you tell me your name once more?","start":0,"answer":"恐れ入りますが","acceptedAnswers":["恐れ入りますが","恐縮ですが"],"distractors":[{"text":"恐れ入るますが","reason":"ます needs the stem 入り."},{"text":"恐れ入りますを","reason":"を cannot connect to the following request here."},{"text":"恐れ入りますな","reason":"な does not connect with the following request here."}]}},"romaji":"Osore irimasu ga, onamae wo mō ichido okikase itadakemasu ka.","german":"Excuse me, but could you tell me your name once more?"},{"japanese":"恐れ入りますが、こちらにご記入いただけますでしょうか。","cloze":{"start":0,"answer":"恐れ入りますが"},"romaji":"Osore irimasu ga, kochira ni gokinyū itadakemasu deshō ka.","german":"I'm sorry, but could you fill this in here?"},{"japanese":"恐れ入りますが、少々お待ちいただけますか。","cloze":{"start":0,"answer":"恐れ入りますが"},"romaji":"Osore irimasu ga, shōshō omachi itadakemasu ka.","german":"Excuse me, but could you wait a moment?"}],"notes":"恐れ入りますが belongs to the so-called クッション言葉 (cushion words), which are used in Japanese to soften requests and questions. Other cushion words are: お手数ですが、申し訳ございませんが.","related":["keigo-business-otesuu","keigo-teinei-itadakemasenka"]},
{"id":"keigo-business-yoroshiku","pattern":"よろしくお願いいたします","level":"N4","category":"Keigo","subcategory":"ビジネス敬語","meaning":"I humbly ask for your kind consideration (formal closing phrase)","explanation":"よろしくお願いいたします is the formal version of よろしくお願いします and one of the most important phrases in Japanese business life. It is used as a closing phrase in emails, in first introductions, after requests and in almost all business communication. いたします (kenjōgo of します) makes the phrase especially respectful.","formation":"よろしくお願いいたします (fixed formula) / 何卒よろしくお願いいたします (even more formal)","examples":[{"japanese":"今後ともよろしくお願いいたします。","cloze":{"start":4,"answer":"よろしくお願いいたします","quiz":{"level":"N4","japanese":"今後ともよろしくお願いいたします。","german":"I ask for your continued kind support.","start":4,"answer":"よろしくお願いいたします","acceptedAnswers":["よろしくお願いいたします","よろしくお願いします"],"distractors":[{"text":"よろしくお願いするます","reason":"The polite form is お願いします."},{"text":"よろしくお願いをいたすます","reason":"いたすます is not a polite verb form."},{"text":"よろしくお願いいたしません","reason":"This negates the request."}],"promptKana":"こんごとも＿＿＿。"}},"romaji":"Kongo tomo yoroshiku onegai itashimasu.","german":"I ask for your continued kind support."},{"japanese":"ご対応のほど、何卒よろしくお願いいたします。","cloze":{"start":9,"answer":"よろしくお願いいたします"},"romaji":"Gotaiō no hodo, nanitozo yoroshiku onegai itashimasu.","german":"I sincerely ask you to kindly deal with this matter."},{"japanese":"引き続きよろしくお願いいたします。","cloze":{"start":4,"answer":"よろしくお願いいたします"},"romaji":"Hikitsuzuki yoroshiku onegai itashimasu.","german":"I ask for your continued valued cooperation."}],"notes":"Almost every business email in Japan ends with a variation of よろしくお願いいたします. With 何卒 (nanitozo) in front, the request becomes more urgent and more formal. This phrase has no direct English equivalent.","related":["keigo-business-osewani","keigo-kenjougo-itasu"]},
{"id":"keigo-business-gokakunin","pattern":"ご確認ください","level":"N3","category":"Keigo","subcategory":"ビジネス敬語","meaning":"please confirm; please check","explanation":"ご確認ください is a polite request asking the recipient to check or confirm something. It is used very often in business emails and documents. The prefix ご in front of the Sino-Japanese word 確認 makes the phrase respectful.","formation":"ご確認ください / ご確認いただけますでしょうか (even more polite, as a question)","examples":[{"japanese":"添付ファイルをご確認ください。","cloze":{"start":7,"answer":"ご確認ください","quiz":{"level":"N3","japanese":"添付ファイルをご確認ください。","german":"Please check the attached file.","start":7,"answer":"ご確認ください","acceptedAnswers":["ご確認ください"],"distractors":[{"text":"ご確認くださる","reason":"This is a statement instead of a request."},{"text":"ご確認くださいた","reason":"This is not a request form."},{"text":"ご確認くださいませんでした","reason":"This negates a past check instead of asking for one."}]}},"romaji":"Tenpu fairu wo gokakunin kudasai.","german":"Please check the attached file."},{"japanese":"スケジュールをご確認いただけますでしょうか。","romaji":"Sukejūru wo gokakunin itadakemasu deshō ka.","german":"Could you please check the schedule?"},{"japanese":"以下の内容をご確認の上、ご返信ください。","romaji":"Ika no naiyō wo gokakunin no ue, gohenshin kudasai.","german":"Please check the following and reply."}],"notes":"ご確認ください is one of the most frequent phrases in business emails. The more polite question form ご確認いただけますでしょうか is used when you do not want to ask the recipient directly.","related":["keigo-sonkeigo-okudasai","keigo-business-gosashuu"]},
{"id":"keigo-business-gokentou","pattern":"ご検討いただければ幸いです","level":"N2","category":"Keigo","subcategory":"ビジネス敬語","meaning":"I would be grateful if you could consider it","explanation":"ご検討いただければ幸いです is an extremely polite request asking the recipient to consider a proposal or an offer. The combination of ご検討 (consideration), いただければ (if I could receive the favor) and 幸いです (it would be a joy) produces a phrase that combines maximum politeness with modesty.","formation":"ご検討いただければ幸いです / ご検討いただけますと幸いです (variant)","examples":[{"japanese":"こちらの企画をご検討いただければ幸いです。","cloze":{"start":7,"answer":"ご検討いただければ幸いです","quiz":{"level":"N2","japanese":"こちらの企画をご検討いただければ幸いです。","german":"I would be grateful if you could consider this plan.","start":7,"answer":"ご検討いただければ幸いです","acceptedAnswers":["ご検討いただければ幸いです"],"distractors":[{"text":"ご検討いただければ幸いを","reason":"を cannot end the request."},{"text":"ご検討いただければ幸います","reason":"ます cannot be attached directly to 幸い."},{"text":"ご検討いただけるれば幸いです","reason":"The conditional is いただければ."}]}},"romaji":"Kochira no kikaku wo gokentō itadakereba saiwai desu.","german":"I would be grateful if you could consider this plan."},{"japanese":"お見積もりをお送りいたしますので、ご検討いただければ幸いです。","cloze":{"start":17,"answer":"ご検討いただければ幸いです"},"romaji":"Omitsumori wo ookuriitashimasu node, gokentō itadakereba saiwai desu.","german":"I am sending you the quote; I would be grateful if you could consider it."},{"japanese":"前向きにご検討いただければ幸いに存じます。","romaji":"Maemuki ni gokentō itadakereba saiwai ni zonjimasu.","german":"I would be most grateful if you could give it favorable consideration."}],"notes":"This phrase is often used at the end of business proposals and offers. The variant with 存じます instead of です at the end sounds even more humble. 前向きに (positively/favorably) is often added to encourage a positive consideration.","related":["keigo-kenjougo-itadaku","keigo-kenjougo-zonjiru"]},
{"id":"keigo-business-nokenni","pattern":"～の件につきまして","level":"N2","category":"Keigo","subcategory":"ビジネス敬語","meaning":"regarding the matter of... / concerning...","explanation":"～の件につきまして is the formal business version of ～について (regarding). つきまして is the ます-form of the formal verb つく (to relate to) in the て-form. This phrase is used to introduce the subject of a business message.","formation":"Noun + の件につきまして / Noun + につきまして","examples":[{"japanese":"先日のお見積もりの件につきまして、ご連絡いたします。","cloze":{"start":8,"answer":"の件につきまして","quiz":{"level":"N2","japanese":"先日のお見積もりの件につきまして、ご連絡いたします。","german":"I am contacting you regarding the quote from the other day.","start":8,"answer":"の件につきまして","acceptedAnswers":["の件につきまして","の件について"],"distractors":[{"text":"の件につきます","reason":"The finite form cannot be connected with ご連絡いたします here."},{"text":"の件をつきまして","reason":"The reference requires に."},{"text":"の件につくまして","reason":"まして is not attached to the dictionary form."}]}},"romaji":"Senjitsu no omitsumori no ken ni tsukimashite, gorenraku itashimasu.","german":"I am contacting you regarding the quote from the other day."},{"japanese":"来月の会議の件につきまして、ご相談がございます。","cloze":{"start":5,"answer":"の件につきまして"},"romaji":"Raigetsu no kaigi no ken ni tsukimashite, gosōdan ga gozaimasu.","german":"Regarding next month's meeting, there is something I would like to discuss with you."},{"japanese":"納期の変更につきまして、お詫び申し上げます。","romaji":"Nōki no henkō ni tsukimashite, owabi mōshiagemasu.","german":"Regarding the change in the delivery date, I would like to offer my apologies."}],"notes":"～の件につきまして is especially common in email subject lines and at the start of business messages. The shorter form ～につきまして can also be used without 件.","related":["keigo-business-osewani","keigo-kenjougo-moushiageru"]},
{"id":"keigo-business-gofumeina","pattern":"ご不明な点がございましたら","level":"N2","category":"Keigo","subcategory":"ビジネス敬語","meaning":"should you have any questions; if anything is unclear","explanation":"ご不明な点がございましたら is a polite standard phrase that signals to the recipient that you are available for follow-up questions. ございましたら is the formal version of あったら (if there is). This phrase is typically used at the end of business emails or explanations.","formation":"ご不明な点がございましたら + お気軽にお問い合わせください (or similar)","examples":[{"japanese":"ご不明な点がございましたら、お気軽にお問い合わせください。","cloze":{"start":0,"answer":"ご不明な点がございましたら","quiz":{"level":"N2","japanese":"ご不明な点がございましたら、お気軽にお問い合わせください。","german":"Should you have any questions, please do not hesitate to contact us.","start":0,"answer":"ご不明な点がございましたら","acceptedAnswers":["ご不明な点がございましたら","ご不明な点がありましたら"],"distractors":[{"text":"ご不明な点がございますたら","reason":"The conditional is ございましたら."},{"text":"ご不明な点をごございましたら","reason":"を and ご do not form an existence construction here."},{"text":"ご不明な点がございましてたら","reason":"The て-form is not combined with たら."}]}},"romaji":"Gofumei na ten ga gozaimashitara, okigaru ni otoiawase kudasai.","german":"Should you have any questions, please do not hesitate to contact us."},{"japanese":"ご不明な点がございましたら、担当の佐藤までご連絡ください。","cloze":{"start":0,"answer":"ご不明な点がございましたら"},"romaji":"Gofumei na ten ga gozaimashitara, tantō no Satō made gorenraku kudasai.","german":"If anything is unclear, please contact Satō, who is in charge."},{"japanese":"ご不明な点がございましたら、何なりとお申し付けください。","cloze":{"start":0,"answer":"ご不明な点がございましたら"},"romaji":"Gofumei na ten ga gozaimashitara, nan nari to omōshitsuke kudasai.","german":"Should you have any questions at all, please do not hesitate to let us know."}],"notes":"This phrase is almost obligatory in business emails and typically comes shortly before the closing formula. Variants are: ご質問がございましたら (if you have questions) and ご不明点等ございましたら (if anything is unclear or the like).","related":["keigo-business-okigaruni","keigo-teinei-degozaimasu"]},
{"id":"keigo-business-toriisogi","pattern":"取り急ぎご連絡いたします","level":"N2","category":"Keigo","subcategory":"ビジネス敬語","meaning":"I am contacting you in haste; a quick, urgent note","explanation":"取り急ぎご連絡いたします is a standard business phrase used when you want to pass on important information quickly without following the usual elaborate politeness structure. 取り急ぎ means \"in haste\" or \"hurriedly\" and at the same time apologizes for the brevity of the message.","formation":"取り急ぎ + ご連絡いたします / ご報告いたします / お知らせいたします","examples":[{"japanese":"取り急ぎご連絡いたします。会議の日程が変更になりました。","cloze":{"start":0,"answer":"取り急ぎご連絡いたします","quiz":{"level":"N2","japanese":"取り急ぎご連絡いたします。会議の日程が変更になりました。","german":"A quick note to let you know: the date of the meeting has changed.","start":0,"answer":"取り急ぎご連絡いたします","acceptedAnswers":["取り急ぎご連絡いたします"],"distractors":[{"text":"取り急ぎご連絡いたしません","reason":"This negates making contact."},{"text":"取り急ぎご連絡いたすます","reason":"ます needs the stem いたし."},{"text":"取り急ぎご連絡いたしまする","reason":"る cannot be attached to ます."}]}},"romaji":"Toriisogi gorenraku itashimasu. Kaigi no nittei ga henkō ni narimashita.","german":"A quick note to let you know: the date of the meeting has changed."},{"japanese":"取り急ぎご報告まで。","romaji":"Toriisogi gohōkoku made.","german":"Just a quick report for now."},{"japanese":"詳細は後ほどお送りいたしますが、取り急ぎお知らせいたします。","romaji":"Shōsai wa nochihodo ookuriitashimasu ga, toriisogi oshirase itashimasu.","german":"I will send you the details later, but I wanted to let you know quickly in advance."}],"notes":"取り急ぎ is often used as an apology for a short email. The shortened form 取り急ぎご報告まで (just a quick report) is also used frequently and is somewhat more informal.","related":["keigo-business-osewani","keigo-kenjougo-itasu"]},
{"id":"keigo-business-otesuu","pattern":"お手数をおかけしますが","level":"N2","category":"Keigo","subcategory":"ビジネス敬語","meaning":"I'm sorry for the trouble, but...","explanation":"お手数をおかけしますが is a polite cushion word (クッション言葉) used before a request that may cause the recipient trouble or effort. お手数 means \"trouble/effort\" and おかけする is the humble form of かける (to cause). This phrase shows consideration and gratitude for the other person's effort.","formation":"お手数をおかけしますが + request / お手数ですが + request (shorter)","examples":[{"japanese":"お手数をおかけしますが、書類にご署名をお願いいたします。","cloze":{"start":0,"answer":"お手数をおかけしますが","quiz":{"level":"N2","japanese":"お手数をおかけしますが、書類にご署名をお願いいたします。","german":"Sorry for the trouble, but I would ask you to sign the documents.","start":0,"answer":"お手数をおかけしますが","acceptedAnswers":["お手数をおかけしますが"],"distractors":[{"text":"お手数をおかけするますが","reason":"ます needs the stem し."},{"text":"お手数をおかけしますを","reason":"を does not connect the request here."},{"text":"お手数をおかけしますな","reason":"な does not connect the introduction with the request here."}]}},"romaji":"Otesū wo okake shimasu ga, shorui ni goshomei wo onegai itashimasu.","german":"Sorry for the trouble, but I would ask you to sign the documents."},{"japanese":"お手数ですが、再度ご確認いただけますでしょうか。","romaji":"Otesū desu ga, saido gokakunin itadakemasu deshō ka.","german":"I'm sorry for the trouble, but could you please check it once more?"},{"japanese":"お手数をおかけして申し訳ございませんが、ご対応をお願いいたします。","romaji":"Otesū wo okake shite mōshiwake gozaimasen ga, gotaiō wo onegai itashimasu.","german":"I apologize for the trouble and ask you to kindly take care of this."}],"notes":"お手数をおかけしますが is one of the most common cushion words in business emails. It is used before practically any request that creates work for the recipient. The shorter form お手数ですが is also very widespread.","related":["keigo-business-osoreirimasuga","keigo-business-oisogashii"]},
{"id":"keigo-business-gosashuu","pattern":"ご査収ください","level":"N1","category":"Keigo","subcategory":"ビジネス敬語","meaning":"please examine and accept","explanation":"ご査収ください (ごさしゅうください) is a very formal phrase used mainly in business emails when you are sending documents, files or papers. 査収 literally means \"to examine and accept\". It asks the recipient to check what was sent and accept it.","formation":"ご査収ください / ご査収のほどよろしくお願いいたします (even more formal)","examples":[{"japanese":"請求書を添付いたしましたので、ご査収ください。","cloze":{"start":15,"answer":"ご査収ください","quiz":{"level":"N1","japanese":"請求書を添付いたしましたので、ご査収ください。","german":"I have attached the invoice; please review it.","start":15,"answer":"ご査収ください","acceptedAnswers":["ご査収ください"],"distractors":[{"text":"ご査収するください","reason":"ください is not attached to する."},{"text":"ご査収くださいまする","reason":"る cannot be attached to ます."},{"text":"ご査収くださるました","reason":"The polite past needs the verb stem."}]}},"romaji":"Seikyūsho wo tenpu itashimashita node, gosashū kudasai.","german":"I have attached the invoice; please review it."},{"japanese":"報告書をお送りいたします。ご査収のほどよろしくお願いいたします。","romaji":"Hōkokusho wo ookuriitashimasu. Gosashū no hodo yoroshiku onegai itashimasu.","german":"I am sending you the report. Please kindly review it."},{"japanese":"契約書を同封いたしましたので、ご査収くださいますようお願い申し上げます。","cloze":{"start":15,"answer":"ご査収ください"},"romaji":"Keiyakusho wo dōfū itashimashita node, gosashū kudasaimasu yō onegai mōshiagemasu.","german":"I have enclosed the contract; I respectfully ask you to review and accept it."}],"notes":"ご査収ください is used almost exclusively in written business communication and sounds unnatural in spoken language. It is one of the most formal phrases for sending something in Japanese.","related":["keigo-business-gokakunin","keigo-business-goryoushou"]},
{"id":"keigo-business-goryoushou","pattern":"ご了承ください","level":"N2","category":"Keigo","subcategory":"ビジネス敬語","meaning":"please understand; please accept","explanation":"ご了承ください (ごりょうしょうください) is used to ask the recipient politely for understanding or acceptance of a situation that may not be ideal. 了承 means \"consent/understanding\". This phrase is often used when announcing a restriction, change or inconvenience.","formation":"ご了承ください / ご了承いただけますようお願いいたします (even more polite)","examples":[{"japanese":"あらかじめご了承ください。","cloze":{"start":5,"answer":"ご了承ください","quiz":{"level":"N2","japanese":"あらかじめご了承ください。","german":"Please understand this in advance.","start":5,"answer":"ご了承ください","acceptedAnswers":["ご了承ください","ご了承願います"],"distractors":[{"text":"ご了承くださる","reason":"A statement about granting does not form the request here."},{"text":"ご了承くださいまする","reason":"る cannot be attached to ます."},{"text":"ご了承くださるください","reason":"ください is not attached to the dictionary form."}]}},"romaji":"Arakajime goryōshō kudasai.","german":"Please understand this in advance."},{"japanese":"在庫切れの場合はご了承ください。","cloze":{"start":8,"answer":"ご了承ください"},"romaji":"Zaiko-gire no baai wa goryōshō kudasai.","german":"Please understand if the item is out of stock."},{"japanese":"工事のため、騒音が発生いたします。ご了承いただけますようお願いいたします。","romaji":"Kōji no tame, sōon ga hassei itashimasu. Goryōshō itadakemasu yō onegai itashimasu.","german":"There will be noise due to construction work. We ask for your understanding."}],"notes":"ご了承ください is found very often on notice signs, in terms and conditions and in notifications. It is often used together with あらかじめ (in advance). Not to be confused with ご容赦ください, which contains a stronger apology.","related":["keigo-business-goyousha","keigo-business-osoreirimasuga"]},
{"id":"keigo-business-goyousha","pattern":"ご容赦ください","level":"N1","category":"Keigo","subcategory":"ビジネス敬語","meaning":"please forgive; please excuse","explanation":"ご容赦ください (ごようしゃください) is a very formal apology phrase that is stronger than ご了承ください. 容赦 means \"leniency/forgiveness\". You use this phrase when asking forgiveness for an omission, an inconvenience or a mistake. It expresses deeper regret than other forms of apology.","formation":"ご容赦ください / 何卒ご容赦くださいますようお願い申し上げます (very formal)","examples":[{"japanese":"ご返信が遅れましたこと、ご容赦ください。","cloze":{"start":12,"answer":"ご容赦ください","quiz":{"level":"N1","japanese":"ご返信が遅れましたこと、ご容赦ください。","german":"Please forgive the late reply.","start":12,"answer":"ご容赦ください","acceptedAnswers":["ご容赦ください"],"distractors":[{"text":"ご容赦するください","reason":"ください is not attached to する."},{"text":"ご容赦くださいまする","reason":"る cannot be attached to ます."},{"text":"ご容赦くださるました","reason":"The polite past needs the verb stem."}]}},"romaji":"Gohenshin ga okuremashita koto, goyōsha kudasai.","german":"Please forgive the late reply."},{"japanese":"突然のご連絡をお許しください。何卒ご容赦くださいますようお願い申し上げます。","cloze":{"start":17,"answer":"ご容赦ください"},"romaji":"Totsuzen no gorenraku wo oyurushi kudasai. Nanitozo goyōsha kudasaimasu yō onegai mōshiagemasu.","german":"Please excuse me for contacting you so suddenly. I earnestly ask for your forgiveness."},{"japanese":"ご不便をおかけいたしますが、何卒ご容赦ください。","cloze":{"start":16,"answer":"ご容赦ください"},"romaji":"Gofuben wo okake itashimasu ga, nanitozo goyōsha kudasai.","german":"We apologize for the inconvenience and kindly ask for your forgiveness."}],"notes":"ご容赦ください is often combined with 何卒 (nanitozo = earnestly) to strengthen the urgency of the request. This phrase is more formal and more apologetic than ご了承ください.","related":["keigo-business-goryoushou","keigo-bikago-moushiwake"]},
{"id":"keigo-business-okigaruni","pattern":"お気軽にお問い合わせください","level":"N3","category":"Keigo","subcategory":"ビジネス敬語","meaning":"please do not hesitate to contact us","explanation":"お気軽にお問い合わせください is an inviting standard phrase that signals to the recipient that they can get in touch without any worries. お気軽に means \"freely/casually\" and お問い合わせ is the polite form of 問い合わせ (inquiry). This phrase is often used at the end of business emails and on websites.","formation":"お気軽に + お問い合わせください / ご連絡ください / お申し付けください","examples":[{"japanese":"ご質問がございましたら、お気軽にお問い合わせください。","cloze":{"start":12,"answer":"お気軽にお問い合わせください","quiz":{"level":"N3","japanese":"ご質問がございましたら、お気軽にお問い合わせください。","german":"If you have any questions, please do not hesitate to contact us.","start":12,"answer":"お気軽にお問い合わせください","acceptedAnswers":["お気軽にお問い合わせください"],"distractors":[{"text":"お気軽にお問い合わせるください","reason":"ください does not follow the dictionary form here."},{"text":"お気軽にお問い合わせくださいた","reason":"This is not a request form."},{"text":"お問い合わせにならないでください","reason":"This explicitly asks people not to make inquiries."}]}},"romaji":"Goshitsumon ga gozaimashitara, okigaru ni otoiawase kudasai.","german":"If you have any questions, please do not hesitate to contact us."},{"japanese":"お気軽にご連絡ください。お待ちしております。","romaji":"Okigaru ni gorenraku kudasai. Omachi shite orimasu.","german":"Please feel free to contact us. We look forward to hearing from you."},{"japanese":"何かございましたら、お気軽にお申し付けください。","romaji":"Nanika gozaimashitara, okigaru ni omōshitsuke kudasai.","german":"If there is anything at all, please do not hesitate to let us know."}],"notes":"This phrase is everywhere on Japanese websites, in brochures and in business emails. It corresponds to the English \"Don't hesitate to contact us\" and is less formal than other business phrases.","related":["keigo-business-gofumeina","keigo-sonkeigo-okudasai"]},
{"id":"keigo-business-saseteitadakitaku","pattern":"～させていただきたく存じます","level":"N1","category":"Keigo","subcategory":"ビジネス敬語","meaning":"I would humbly like to be allowed to...","explanation":"～させていただきたく存じます is one of the most polite forms in Japanese for expressing an action you intend to take. It combines させていただく (to be allowed to) with たく (to want) and 存じます (to think, kenjōgo). This triple humble form is used in very formal business situations.","formation":"Verb させ-form + ていただきたく存じます","examples":[{"japanese":"来週、ご訪問させていただきたく存じます。","cloze":{"start":6,"answer":"させていただきたく存じます","quiz":{"level":"N1","japanese":"来週、ご訪問させていただきたく存じます。","german":"I would like to pay you a visit next week, if I may.","start":6,"answer":"させていただきたく存じます","acceptedAnswers":["させていただきたく存じます"],"distractors":[{"text":"させるいただきたく存じます","reason":"いただく needs the て-connection."},{"text":"させていただきたいく存じます","reason":"The adverbial form of たい is たく."},{"text":"させていただきたく存じるます","reason":"ます needs the verb stem."}]}},"romaji":"Raishū, gohōmon sasete itadakitaku zonjimasu.","german":"I would like to pay you a visit next week, if I may."},{"japanese":"企画の詳細についてご説明させていただきたく存じます。","cloze":{"start":12,"answer":"させていただきたく存じます"},"romaji":"Kikaku no shōsai ni tsuite gosetsumei sasete itadakitaku zonjimasu.","german":"I would like to be allowed to explain the details of the project to you."},{"japanese":"一度お打ち合わせの機会をいただきたく存じます。","romaji":"Ichido ouchiawase no kikai wo itadakitaku zonjimasu.","german":"I would like to have the opportunity to meet with you once."}],"notes":"This form is sometimes criticized as excessively polite (過剰敬語), but it is quite common in Japanese business culture, especially when addressing customers or people of higher status. The slightly shorter form ～させていただきたいと思います is a less formal alternative.","related":["keigo-teinei-sasete-itadaku","keigo-kenjougo-zonjiru"]},
{"id":"keigo-teinei-goitadaku","pattern":"お/ご～いただく","level":"N3","category":"Keigo","subcategory":"丁寧語","meaning":"to receive the favor of someone doing something","explanation":"お/ご～いただく is an important keigo construction that expresses that you receive the favor of a respected person doing something for you. With native Japanese verbs you use お + verb stem + いただく, with Sino-Japanese words ご + noun + いただく. This form is more humble than お/ご～くださる.","formation":"お + verb stem + いただく / ご + Sino-Japanese noun + いただく","examples":[{"japanese":"お忙しい中、お越しいただきありがとうございます。","romaji":"Oisogashii naka, okoshi itadaki arigatō gozaimasu.","german":"Thank you for coming despite your busy schedule."},{"japanese":"ご理解いただければ幸いです。","romaji":"Gorikai itadakereba saiwai desu.","german":"I would be grateful for your understanding."},{"japanese":"資料をお送りいただけますでしょうか。","cloze":{"start":3,"answer":"お","quiz":{"level":"N3","japanese":"資料をお送りいただけますでしょうか。","german":"Could you send me the documents?","start":3,"answer":"お","acceptedAnswers":["お"],"distractors":[{"text":"ご","reason":"送り is a native Japanese verb stem and forms お送り here."},{"text":"に","reason":"に does not form the humble verb-stem construction."},{"text":"を","reason":"An extra を does not fit between 資料を and 送り."}]}},"romaji":"Shiryō wo ookuriitadakemasu deshō ka.","german":"Could you send me the documents?"}],"notes":"お/ご～いただく and お/ご～くださる have similar meanings but a different perspective: いただく emphasizes humbly receiving (kenjōgo), くださる emphasizes the other person's generous giving (sonkeigo). In practice, いただく is used more often.","related":["keigo-kenjougo-itadaku","keigo-sonkeigo-okudasaru"]},
{"id":"keigo-teinei-kanemasu","pattern":"～かねます","level":"N2","category":"Keigo","subcategory":"丁寧語","meaning":"to be unfortunately unable to; to regret being unable to","explanation":"～かねます is a polite form of refusal used to express that you unfortunately cannot do something. It sounds softer and more diplomatic than ～できません. This form is used especially in customer service and in business refusals to phrase the refusal respectfully.","formation":"Verb stem (ます-form without ます) + かねます","examples":[{"japanese":"申し訳ございませんが、その件につきましてはお答えいたしかねます。","cloze":{"start":27,"answer":"かねます","quiz":{"level":"N2","japanese":"申し訳ございませんが、その件につきましてはお答えいたしかねます。","german":"I am very sorry, but I am unable to answer regarding that matter.","start":27,"answer":"かねます","acceptedAnswers":["かねます"],"distractors":[{"text":"かねません","reason":"This means \"could well happen\" and reverses the refusal."},{"text":"かねるます","reason":"ます is not attached to the dictionary form."},{"text":"かねますた","reason":"The polite past ends in ました."}]}},"romaji":"Mōshiwake gozaimasen ga, sono ken ni tsukimashite wa okotae itashikanemasu.","german":"I am very sorry, but I am unable to answer regarding that matter."},{"japanese":"ご要望には応じかねます。","cloze":{"start":7,"answer":"かねます"},"romaji":"Goyōbō ni wa ōjikanemasu.","german":"We are unfortunately unable to comply with your request."},{"japanese":"この価格ではお引き受けいたしかねます。","cloze":{"start":14,"answer":"かねます"},"romaji":"Kono kakaku de wa ohikiuke itashikanemasu.","german":"We are unfortunately unable to accept the job at this price."}],"notes":"～かねます is an indirect refusal and is considered more polite than ～できません. In Japanese business life direct refusals are avoided, which is why this form is very important. Not to be confused with ～かねません, which expresses a possibility.","related":["keigo-teinei-kanemasen","keigo-business-osoreirimasuga"]},
{"id":"keigo-teinei-kanemasen","pattern":"～かねません","level":"N2","category":"Keigo","subcategory":"丁寧語","meaning":"it could happen that... / there is a risk that...","explanation":"～かねません expresses that a (usually negative) possibility exists. Despite its similar form to ～かねます, it has a completely different meaning: while ～かねます means \"cannot\", ～かねません means \"it could well happen\". The double negation (かね + ません) results in an affirmation of the possibility.","formation":"Verb stem (ます-form without ます) + かねません / かねない (informal)","examples":[{"japanese":"このまま放置すると、大きな問題になりかねません。","cloze":{"start":18,"answer":"かねません","quiz":{"level":"N2","japanese":"このまま放置すると、大きな問題になりかねません。","german":"If we leave it like this, it could turn into a big problem.","start":18,"answer":"かねません","acceptedAnswers":["かねません"],"distractors":[{"text":"かねます","reason":"This expresses inability instead of an impending risk."},{"text":"かねるません","reason":"ません is not attached to the dictionary form."},{"text":"かねませんない","reason":"The negative ending is not combined with ない a second time."}]}},"romaji":"Kono mama hōchi suru to, ōkina mondai ni narikanemasen.","german":"If we leave it like this, it could turn into a big problem."},{"japanese":"誤解を招きかねませんので、慎重に対応してください。","cloze":{"start":5,"answer":"かねません"},"romaji":"Gokai wo manekikanemasen node, shinchō ni taiō shite kudasai.","german":"This could lead to misunderstandings, so please handle it carefully."},{"japanese":"納期に間に合わなくなりかねません。","cloze":{"start":11,"answer":"かねません"},"romaji":"Nōki ni ma ni awanaku narikanemasen.","german":"There is a risk that we will not be able to meet the delivery deadline."}],"notes":"～かねません is almost always used for negative possibilities (problems, risks, dangers). It would be unnatural to use it for positive possibilities. The difference between ～かねます (cannot) and ～かねません (could happen) is a common stumbling block for learners.","related":["keigo-teinei-kanemasu"]},
{"id":"keigo-kenjougo-odenwasashiageru","pattern":"お電話を差し上げる","level":"N2","category":"Keigo","subcategory":"謙譲語","meaning":"to call (humble); to make a phone call (humble)","explanation":"お電話を差し上げる is the kenjōgo form of 電話をかける (to call). 差し上げる (さしあげる) is the humble form of あげる (to give) and expresses that you \"offer\" the act of calling to a person of higher status. This form is used in business communication.","formation":"お電話を差し上げる / お電話いたす (alternative)","examples":[{"japanese":"後ほどお電話を差し上げます。","romaji":"Nochihodo odenwa wo sashiagemasu.","german":"I will call you later.","cloze":{"start":3,"answer":"お電話を差し上げます","quiz":{"level":"N2","japanese":"後ほどお電話を差し上げます。","german":"I will call you later.","start":3,"answer":"お電話を差し上げます","acceptedAnswers":["お電話を差し上げます","お電話いたします"],"distractors":[{"text":"お電話を差し上げません","reason":"This negates the announced call."},{"text":"お電話を差し上げるます","reason":"ます is not attached to the dictionary form."},{"text":"お電話を差し上げまする","reason":"る cannot be attached to ます."}]}}},{"japanese":"明日の午前中にお電話を差し上げてもよろしいでしょうか。","romaji":"Ashita no gozenchū ni odenwa wo sashiagete mo yoroshii deshō ka.","german":"Might I call you tomorrow morning?"},{"japanese":"折り返しお電話を差し上げますので、少々お待ちください。","romaji":"Orikaeshi odenwa wo sashiagemasu node, shōshō omachi kudasai.","german":"I will call you back, so please wait a moment."}],"notes":"Recently there has been debate about whether お電話を差し上げる is appropriate, since 差し上げる (to give) implies that the call is a gift. Some consider the alternative お電話いたします more neutral. Both forms are nevertheless accepted in business.","related":["keigo-kenjougo-sashiageru","keigo-kenjougo-itasu"]},
{"id":"keigo-bikago-goenryonaku","pattern":"ご遠慮なく","level":"N3","category":"Keigo","subcategory":"尊敬語","meaning":"without hesitation; without holding back (please)","explanation":"ご遠慮なく is an inviting phrase that encourages the other person to act without inhibition or reserve. 遠慮 means \"reserve/restraint\" and なく is the negation. With the polite prefix ご it becomes a respectful invitation to feel at ease.","formation":"ご遠慮なく + verb (ください / お申し付けください etc.)","examples":[{"japanese":"ご遠慮なくお召し上がりください。","cloze":{"start":0,"answer":"ご遠慮なく","quiz":{"level":"N3","japanese":"ご遠慮なくお召し上がりください。","german":"Please help yourself without holding back.","start":0,"answer":"ご遠慮なく","acceptedAnswers":["ご遠慮なく","遠慮なく"],"distractors":[{"text":"ご遠慮して","reason":"This asks for restraint instead of helping oneself freely."},{"text":"ご遠慮ないで","reason":"The fixed adverbial form is ご遠慮なく."},{"text":"ご遠慮なくの","reason":"の cannot come before the request here."}]}},"romaji":"Goenryo naku omeshiagari kudasai.","german":"Please help yourself without holding back."},{"japanese":"何かございましたら、ご遠慮なくおっしゃってください。","cloze":{"start":10,"answer":"ご遠慮なく"},"romaji":"Nanika gozaimashitara, goenryo naku osshatte kudasai.","german":"If there is anything at all, please do not hesitate to say so."},{"japanese":"ご遠慮なくお使いください。","cloze":{"start":0,"answer":"ご遠慮なく"},"romaji":"Goenryo naku otsukai kudasai.","german":"Please feel free to use it."}],"notes":"ご遠慮なく is often used in restaurants, when entertaining guests and in customer service. The phrase reflects Japanese culture, in which guests often hesitate out of politeness. With ご遠慮なく you encourage them to give up this reserve.","related":["keigo-sonkeigo-meshiagaru","keigo-business-okigaruni"]},
{"id":"keigo-bikago-moushiwake","pattern":"申し訳ございません","level":"N3","category":"Keigo","subcategory":"丁寧語","meaning":"there is no excuse; I am deeply sorry","explanation":"申し訳ございません is the most formal standard apology in Japanese. 申し訳 literally means \"excuse/justification\" and ございません is the keigo negative of ある. Literally, the phrase says: \"There is no excuse (for my behavior)\". It is considerably more formal than すみません or ごめんなさい.","formation":"申し訳ございません (fixed phrase) / 大変申し訳ございません (stronger) / 誠に申し訳ございません (strongest)","examples":[{"japanese":"お待たせして、大変申し訳ございません。","cloze":{"start":9,"answer":"申し訳ございません","quiz":{"level":"N3","japanese":"お待たせして、大変申し訳ございません。","german":"I am terribly sorry to have kept you waiting.","start":9,"answer":"申し訳ございません","acceptedAnswers":["申し訳ございません","申し訳ありません"],"distractors":[{"text":"申し訳ござるません","reason":"The polite negative form is ございません."},{"text":"申し訳ございませんた","reason":"This is not a verb form."},{"text":"申し訳がないません","reason":"Two negative endings cannot be combined like this."}]}},"romaji":"Omatase shite, taihen mōshiwake gozaimasen.","german":"I am terribly sorry to have kept you waiting."},{"japanese":"ご迷惑をおかけし、誠に申し訳ございません。","cloze":{"start":11,"answer":"申し訳ございません"},"romaji":"Gomeiwaku wo okake shi, makoto ni mōshiwake gozaimasen.","german":"I sincerely apologize for causing you trouble."},{"japanese":"申し訳ございません。ただいま在庫を切らしております。","cloze":{"start":0,"answer":"申し訳ございません"},"romaji":"Mōshiwake gozaimasen. Tadaima zaiko wo kirashite orimasu.","german":"I am very sorry. We are currently out of stock."}],"notes":"The levels of intensity are: 申し訳ございません → 大変申し訳ございません → 誠に申し訳ございません. In the less formal variant, ございません is replaced by ありません. In business, this phrase is expected for every mistake or inconvenience.","related":["keigo-business-goyousha","keigo-business-osoreirimasuga"]},
{"id":"keigo-bikago-omataseitashimashita","pattern":"お待たせいたしました","level":"N3","category":"Keigo","subcategory":"謙譲語","meaning":"sorry to have kept you waiting; thank you for your patience","explanation":"お待たせいたしました is a polite phrase used when you have kept someone waiting. It combines お待たせする (to make someone wait) with いたしました (kenjōgo past of しました). You hear this phrase constantly in restaurants, shops, on the phone and in all service situations.","formation":"お待たせいたしました (fixed phrase) / 大変お待たせいたしました (after a longer wait)","examples":[{"japanese":"お待たせいたしました。ご注文の品をお持ちしました。","cloze":{"start":0,"answer":"お待たせいたしました","quiz":{"level":"N3","japanese":"お待たせいたしました。ご注文の品をお持ちしました。","german":"Sorry to have kept you waiting. Here is your order.","start":0,"answer":"お待たせいたしました","acceptedAnswers":["お待たせいたしました"],"distractors":[{"text":"お待たせいたしませんでした","reason":"This negates having caused the wait."},{"text":"お待たせいたすました","reason":"This is not a polite past form."},{"text":"お待たせいたしますた","reason":"This is not a verb form."}]}},"romaji":"Omatase itashimashita. Gochūmon no shina wo omochi shimashita.","german":"Sorry to have kept you waiting. Here is your order."},{"japanese":"大変お待たせいたしました。お席にご案内いたします。","cloze":{"start":2,"answer":"お待たせいたしました"},"romaji":"Taihen omatase itashimashita. Oseki ni goannai itashimasu.","german":"Thank you very much for your patience. I will show you to your seat."},{"japanese":"お電話お待たせいたしました。営業部の鈴木でございます。","cloze":{"start":3,"answer":"お待たせいたしました"},"romaji":"Odenwa omatase itashimashita. Eigyōbu no Suzuki de gozaimasu.","german":"Sorry to have kept you waiting on the phone. This is Suzuki from the sales department."}],"notes":"In Japan, お待たせいたしました is said reflexively, even if the wait was very short. The less formal version is お待たせしました (without いた). 大変 is added when the wait was longer than usual.","related":["keigo-kenjougo-itasu","keigo-business-shitsureiitashimasu"]},
{"id":"keigo-sonkeigo-tamawaru","pattern":"賜る（たまわる）","level":"N1","category":"Keigo","subcategory":"尊敬語","meaning":"to receive (respectful); to graciously grant","explanation":"賜る is a very elevated sonkeigo form that can mean both \"to receive from a person of higher status\" and \"to graciously grant\". In modern business language it is used mainly in fixed expressions, especially in formal letters, speeches and on ceremonial occasions.","formation":"賜る (godan verb) ／ お/ご～賜る ／ ～を賜りますよう","examples":[{"japanese":"ご指導を賜りますよう、お願い申し上げます。","romaji":"Goshidō wo tamawarimasu yō, onegai mōshiagemasu.","german":"I respectfully ask for your guidance.","cloze":{"start":4,"answer":"賜ります","quiz":{"level":"N1","japanese":"ご指導を賜りますよう、お願い申し上げます。","german":"I respectfully ask for your guidance.","start":4,"answer":"賜ります","acceptedAnswers":["賜ります","いただきます"],"distractors":[{"text":"賜るます","reason":"ます needs the stem 賜り."},{"text":"賜りまする","reason":"る cannot be attached to ます."},{"text":"賜りないました","reason":"The polite negative is not formed with ないました."}]}}},{"japanese":"温かいお言葉を賜り、誠にありがとうございます。","romaji":"Atatakai okotoba wo tamawari, makoto ni arigatō gozaimasu.","german":"Thank you sincerely for your kind words."},{"japanese":"ご出席を賜りたく、ご案内申し上げます。","romaji":"Goshusseki wo tamawaritaku, goannai mōshiagemasu.","german":"We respectfully invite you and request the honor of your attendance."}],"notes":"賜る is one of the most elevated keigo verbs and is often found in letters of invitation, speeches of thanks and official documents. In everyday business communication it seems excessive, but it is appropriate on ceremonial occasions.","related":["keigo-kenjougo-itadaku","keigo-sonkeigo-kudasaru"]},
{"id":"keigo-sonkeigo-ooseninaru","pattern":"仰せになる（おおせになる）","level":"N1","category":"Keigo","subcategory":"尊敬語","meaning":"to command; to say (highest respect)","explanation":"仰せになる is the highest sonkeigo form of 言う (to say) and expresses that a high-ranking person says or orders something. Today this form is used mainly in literary texts, historical contexts and very formal ceremonial situations.","formation":"仰せになる (fixed expression) ／ 仰せの通り (as you command)","examples":[{"japanese":"会長が仰せになったとおりに進めてください。","romaji":"Kaichō ga ōse ni natta tōri ni susumete kudasai.","german":"Please proceed exactly as the chairman has instructed.","cloze":{"start":3,"answer":"仰せになった","quiz":{"level":"N1","japanese":"会長が仰せになったとおりに進めてください。","german":"Please proceed exactly as the chairman has instructed.","start":3,"answer":"仰せになった","acceptedAnswers":["仰せになった","おっしゃった"],"distractors":[{"text":"仰せになり","reason":"The stem form does not modify とおり attributively here."},{"text":"仰せになるました","reason":"The polite past needs the stem なり."},{"text":"仰せになったな","reason":"No additional な comes before とおり here."}]}}},{"japanese":"仰せの通りにいたします。","romaji":"Ōse no tōri ni itashimasu.","german":"I will do exactly as you say."},{"japanese":"何なりと仰せつけください。","romaji":"Nan nari to ōsetsuke kudasai.","german":"Please command me in whatever you wish."}],"notes":"仰せ on its own is also used as a noun (= instruction/command). The form 仰せつける means \"to command/to order\". In modern language おっしゃる is the usual sonkeigo form of 言う; 仰せになる is more archaic and ceremonial.","related":["keigo-sonkeigo-ossharu","keigo-kenjougo-mousu"]},
{"id":"keigo-sonkeigo-asobasu","pattern":"お～遊ばす（おあそばす）","level":"N1","category":"Keigo","subcategory":"尊敬語","meaning":"to do (highest feminine respect)","explanation":"お～遊ばす is an extremely elevated sonkeigo form that is historically associated with the speech of aristocratic women (女性語). It is used to describe the actions of a very high-ranking person with the greatest respect. In modern language it is rare and considered archaic.","formation":"お + verb (ます-stem) + 遊ばす ／ ～遊ばせ (imperative)","examples":[{"japanese":"奥様はお出かけ遊ばしました。","romaji":"Okusama wa odekake asobashimashita.","german":"Madam has gone out.","cloze":{"start":3,"answer":"お出かけ遊ばしました","quiz":{"level":"N1","japanese":"奥様はお出かけ遊ばしました。","german":"Madam has gone out.","start":3,"answer":"お出かけ遊ばしました","acceptedAnswers":["お出かけ遊ばしました","お出かけになりました"],"distractors":[{"text":"お出かけ遊ばしませんでした","reason":"This negates the going out."},{"text":"お出かけ遊ばすました","reason":"The polite past needs the stem 遊ばし."},{"text":"お出かけ遊ばしましたます","reason":"The polite endings cannot be doubled."}]}}},{"japanese":"ごゆっくり遊ばせ。","romaji":"Goyukkuri asobase.","german":"Please take all the time you need. (very elevated)"},{"japanese":"何をお読み遊ばしていらっしゃいますか。","romaji":"Nani wo oyomi asobashite irasshaimasu ka.","german":"What are you reading? (highest respect)"}],"notes":"お～遊ばす was in use in refined women's speech until the postwar period. Today you hardly ever hear it, except in historical dramas or very traditional contexts. Knowing this form is useful for understanding classical Japanese literature.","related":["keigo-sonkeigo-oninaru","keigo-sonkeigo-nasaru"]},
{"id":"keigo-sonkeigo-nijukeigo","pattern":"二重敬語（にじゅうけいご）","level":"N1","category":"Keigo","subcategory":"尊敬語","meaning":"double keigo; double honorifics","explanation":"二重敬語 refers to the use of two keigo forms in a single verb construction. Although this is considered a grammatical error, some double keigo forms have become established in modern Japanese and are generally accepted, such as お召し上がりになる or お見えになる.","formation":"お + special sonkeigo verb + になる (e.g. お召し上がりになる) ／ special sonkeigo verb + れる/られる","examples":[{"japanese":"どうぞお召し上がりになってください。","romaji":"Dōzo omeshiagari ni natte kudasai.","german":"Please go ahead and eat/drink. (double keigo, but accepted)"},{"japanese":"先生がおっしゃられました。","romaji":"Sensei ga osshararemashita.","german":"The teacher said so. (double keigo, often heard, but strictly speaking incorrect)"},{"japanese":"ご覧になられましたか。","romaji":"Goran ni nararemashita ka.","german":"Have you seen it? (double keigo, widespread)"}],"notes":"The Japanese Council for Cultural Affairs (文化審議会) has classified some 二重敬語 forms as acceptable, including お召し上がりになる and お見えになる. Others, such as おっしゃられる, are considered errors but are widespread. For N1, recognizing and correctly assessing 二重敬語 is important.","related":["keigo-sonkeigo-oninaru","keigo-sonkeigo-meshiagaru"],"clozeExcludedReason":"Fehlervergleich: doppelte Ehrung nicht als korrekte Lückenantwort üben."},
{"id":"keigo-sonkeigo-goranninaru-kudasu","pattern":"ご～くださる (sino-japanisch)","level":"N1","category":"Keigo","subcategory":"尊敬語","meaning":"to be so kind as to do something (Sino-Japanese)","explanation":"ご + Sino-Japanese noun + くださる is the respectful form expressing that a person of higher status is so kind as to carry out an action for the speaker. It is the Sino-Japanese counterpart of お～くださる and is used in formal business and written contexts.","formation":"ご + Sino-Japanese noun + くださる / くださいますよう","examples":[{"japanese":"ご理解くださいますようお願い申し上げます。","romaji":"Gorikai kudasaimasu yō onegai mōshiagemasu.","german":"I respectfully ask for your understanding.","cloze":{"start":0,"answer":"ご理解くださいます","quiz":{"level":"N1","japanese":"ご理解くださいますようお願い申し上げます。","german":"I respectfully ask for your understanding.","start":0,"answer":"ご理解くださいます","acceptedAnswers":["ご理解くださいます"],"distractors":[{"text":"ご理解くださるます","reason":"ます needs the stem ください."},{"text":"ご理解くださいまする","reason":"る cannot be attached to ます."},{"text":"ご理解くださいますた","reason":"The polite past ends in ました."}]}}},{"japanese":"ご協力くださり、誠にありがとうございます。","romaji":"Gokyōryoku kudasari, makoto ni arigatō gozaimasu.","german":"Thank you very much for your kind cooperation."},{"japanese":"ご指導ご鞭撻を賜りますようお願い申し上げます。","romaji":"Goshidō gobentatsu wo tamawarimasu yō onegai mōshiagemasu.","german":"I respectfully ask for your guidance and encouragement."}],"notes":"ご指導ご鞭撻を賜りますよう is one of the most formal request formulas in Japanese and is often found in official welcoming speeches and New Year's greetings. ご鞭撻 (gobentatsu) literally means \"urging on with the whip\" and figuratively stands for encouragement.","related":["keigo-sonkeigo-okudasaru","keigo-sonkeigo-tamawaru"]},
{"id":"keigo-sonkeigo-oideninaru-meirei","pattern":"～なさいませ","level":"N1","category":"Keigo","subcategory":"尊敬語","meaning":"please do... (very polite request)","explanation":"～なさいませ is the most polite imperative form and is used in high-end customer service. It combines なさる (sonkeigo of する) with the polite imperative ending ませ. This form is often found in department stores, hotels and traditional Japanese businesses.","formation":"Verb (ます-stem) + なさいませ ／ お + verb stem + なさいませ","examples":[{"japanese":"いらっしゃいませ。どうぞお入りなさいませ。","cloze":{"start":15,"answer":"なさいませ","quiz":{"level":"N1","japanese":"いらっしゃいませ。どうぞお入りなさいませ。","german":"Welcome. Please come in.","start":15,"answer":"なさいませ","acceptedAnswers":["なさいませ","くださいませ"],"distractors":[{"text":"なさるませ","reason":"ませ is not attached to the dictionary form."},{"text":"なさいませる","reason":"る cannot be attached to ませ."},{"text":"なさいましたませ","reason":"The request is not attached to the past form."}]}},"romaji":"Irasshaimase. Dōzo ohairi nasaimase.","german":"Welcome. Please come in."},{"japanese":"ごゆっくりなさいませ。","cloze":{"start":5,"answer":"なさいませ"},"romaji":"Goyukkuri nasaimase.","german":"Please take all the time you need."},{"japanese":"お気をつけなさいませ。","cloze":{"start":5,"answer":"なさいませ"},"romaji":"Oki wo tsuke nasaimase.","german":"Please take care. (very polite)"}],"notes":"いらっしゃいませ is actually the ませ-form of いらっしゃる and the best-known use of this pattern. In department stores you regularly hear forms such as お選びなさいませ or お試しなさいませ.","related":["keigo-sonkeigo-nasaru","keigo-sonkeigo-okudasai"]},
{"id":"keigo-sonkeigo-rareru-bungo","pattern":"～給う（たまう）","level":"N1","category":"Keigo","subcategory":"尊敬語","meaning":"to do; to give (classical respect)","explanation":"～給う is a classical (文語) sonkeigo form that appears frequently in premodern Japanese literature. In modern language it occasionally turns up in literary texts, religious contexts and set expressions. It expresses the highest respect toward the person performing the action.","formation":"Verb (連用形) + 給う ／ ～たまえ (imperative; today: a collegial request)","examples":[{"japanese":"天は自ら助くる者を助け給う。","romaji":"Ten wa mizukara tasukuru mono o tasuke tamau.","german":"Heaven helps those who help themselves.","cloze":{"start":11,"answer":"給う","quiz":{"level":"N1","japanese":"天は自ら助くる者を助け給う。","german":"Heaven helps those who help themselves.","start":11,"answer":"給う","acceptedAnswers":["給う"],"distractors":[{"text":"給うます","reason":"ます is not attached to the dictionary form."},{"text":"給わないます","reason":"ない does not take ます attached to it."},{"text":"給わない","reason":"This negates Heaven's help."}]}}},{"japanese":"まあ聞き給え。","romaji":"Mā kiki tamae.","german":"Now, just listen. (slightly elevated, collegial tone)"},{"japanese":"神よ、我らを守り給え。","romaji":"Kami yo, warera wo mamori tamae.","german":"O God, protect us."}],"notes":"In modern colloquial language, ～たまえ is sometimes used as a slightly condescending but comradely request among equals (especially by older men). Religious use in prayers is the most living use of the classical form.","related":["keigo-sonkeigo-oninaru","keigo-sonkeigo-asobasu"]},
{"id":"keigo-sonkeigo-meshimasu","pattern":"召す（めす）","level":"N1","category":"Keigo","subcategory":"尊敬語","meaning":"to eat; to drink; to wear; to call (classical respect)","explanation":"召す is a versatile classical sonkeigo verb that serves as the respectful form of 食べる (to eat), 飲む (to drink), 着る (to put on), 呼ぶ (to call) and 乗る (to ride). In modern language it is found mainly in fixed expressions such as お召し物 (clothing, respectful).","formation":"召す (godan verb, ます-form: 召します)","examples":[{"japanese":"お風邪を召していらっしゃるのですか。","romaji":"Okaze wo meshite irassharu no desu ka.","german":"Have you caught a cold? (very polite)","cloze":{"start":4,"answer":"召して","quiz":{"level":"N1","japanese":"お風邪を召していらっしゃるのですか。","german":"Have you caught a cold? (very polite)","start":4,"answer":"召して","acceptedAnswers":["召して"],"distractors":[{"text":"召した","reason":"いらっしゃる needs the て-connection here."},{"text":"召す","reason":"いらっしゃる needs the て-connection here."},{"text":"召します","reason":"The finite form does not fit before いらっしゃる here."}]}}},{"japanese":"お召し物をお預かりいたします。","romaji":"Omeshimono wo oazukari itashimasu.","german":"Let me take your coat."},{"japanese":"お車をお召しになりますか。","romaji":"Okuruma wo omeshi ni narimasu ka.","german":"Will you be taking the car? (very polite)"}],"notes":"お召し物 (clothing, respectful) and お風邪を召す (to catch a cold, respectful) are the most common modern uses. 召し上がる (to eat/drink, respectful) is derived from 召す.","related":["keigo-sonkeigo-meshiagaru","keigo-sonkeigo-asobasu"]},
{"id":"keigo-sonkeigo-gorankudasai","pattern":"ご高覧（ごこうらん）","level":"N1","category":"Keigo","subcategory":"尊敬語","meaning":"to read; to look at (very respectful)","explanation":"ご高覧 is a very formal sonkeigo form of 見る (to see/read) used in business letters and formal invitations. 高覧 literally means \"high gaze\" and expresses the highest respect toward the reader or viewer.","formation":"ご高覧 + ください / いただく / 賜る","examples":[{"japanese":"ご高覧いただければ幸いです。","romaji":"Gokōran itadakereba saiwai desu.","german":"I would be grateful if you would kindly take a look at it.","cloze":{"start":0,"answer":"ご高覧","quiz":{"level":"N1","japanese":"ご高覧いただければ幸いです。","german":"I would be grateful if you would kindly take a look at it.","start":0,"answer":"ご高覧","acceptedAnswers":["ご高覧","ご覧"],"distractors":[{"text":"ご高覧をな","reason":"This particle combination does not fit before いただければ."},{"text":"ご高覧な","reason":"な does not fit before いただければ here."},{"text":"ご高覧ます","reason":"ます cannot be attached directly to 高覧."}]}}},{"japanese":"本書をご高覧賜りますようお願い申し上げます。","romaji":"Honsho wo gokōran tamawarimasu yō onegai mōshiagemasu.","german":"I respectfully ask that you read this book."},{"japanese":"企画書をご高覧ください。","romaji":"Kikakusho wo gokōran kudasai.","german":"Please take a look at the project proposal. (very formal)"}],"notes":"ご高覧 is used almost exclusively in very formal written communication. Similar elevated sonkeigo nouns are ご高配 (gracious consideration), ご厚意 (kind intention), ご高説 (learned opinion).","related":["keigo-sonkeigo-goranninaru","keigo-sonkeigo-tamawaru"]},
{"id":"keigo-sonkeigo-oanjiaremasenu","pattern":"ご高配（ごこうはい）","level":"N1","category":"Keigo","subcategory":"尊敬語","meaning":"gracious consideration; kind patronage","explanation":"ご高配 is a very formal sonkeigo noun that expresses the kind consideration or support of a person or organization of higher status. It is used in formal business letters, official notices and ceremonial greeting formulas.","formation":"ご高配 + を賜り / いただき + ありがとうございます ／ ご高配 + のほど + よろしくお願い申し上げます","examples":[{"japanese":"平素より格別のご高配を賜り、厚く御礼申し上げます。","romaji":"Heiso yori kakubetsu no gokōhai wo tamawari, atsuku onrei mōshiagemasu.","german":"We sincerely thank you for your continued special patronage.","cloze":{"start":7,"answer":"ご高配","quiz":{"level":"N1","japanese":"平素より格別のご高配を賜り、厚く御礼申し上げます。","german":"We sincerely thank you for your continued special patronage.","start":7,"answer":"ご高配","acceptedAnswers":["ご高配"],"distractors":[{"text":"ご高配な","reason":"な does not fit before を賜り here."},{"text":"ご高配ます","reason":"ます cannot be attached directly to 高配."},{"text":"ご高配を","reason":"The following を would be doubled, which is not allowed."}]}}},{"japanese":"今後ともご高配のほどよろしくお願い申し上げます。","romaji":"Kongo tomo gokōhai no hodo yoroshiku onegai mōshiagemasu.","german":"We ask for your continued kind support."},{"japanese":"皆様のご高配により、無事に完了いたしました。","romaji":"Minasama no gokōhai ni yori, buji ni kanryō itashimashita.","german":"Thanks to everyone's kind support, it was completed successfully."}],"notes":"平素より格別のご高配を賜り is one of the most standard opening formulas in formal Japanese business letters. It is more formal than お世話になっております and is used especially in official documents and corporate communication.","related":["keigo-sonkeigo-tamawaru","keigo-business-osewani"]},
{"id":"keigo-sonkeigo-ossharuhiniku","pattern":"ご笑覧（ごしょうらん）","level":"N1","category":"Keigo","subcategory":"尊敬語","meaning":"please look at it indulgently (humble request)","explanation":"ご笑覧 is an extremely polite form used to ask someone to look at your own work. 笑覧 literally means \"to look at with a smile\" and implies a request for indulgent consideration of your own (modestly presented) work. It is used in art, literature and formal invitations.","formation":"ご笑覧 + ください / いただければ幸いです","examples":[{"japanese":"拙作ではございますが、ご笑覧いただければ幸いです。","romaji":"Sessaku de wa gozaimasu ga, goshōran itadakereba saiwai desu.","german":"It is a humble piece of work, but I would be grateful if you would take a look at it.","cloze":{"start":11,"answer":"ご笑覧","quiz":{"level":"N1","japanese":"拙作ではございますが、ご笑覧いただければ幸いです。","german":"It is a humble piece of work, but I would be grateful if you would take a look at it.","start":11,"answer":"ご笑覧","acceptedAnswers":["ご笑覧","ご高覧"],"distractors":[{"text":"ご笑覧な","reason":"な does not fit before いただければ here."},{"text":"ご笑覧ます","reason":"ます cannot be attached directly to 笑覧."},{"text":"ご笑覧をな","reason":"This particle combination does not fit before いただければ."}]}}},{"japanese":"新作をご笑覧ください。","romaji":"Shinsaku wo goshōran kudasai.","german":"Please be so kind as to take a look at my new work."}],"notes":"ご笑覧 is often used together with 拙作 (my humble work) or 拙著 (my humble book). It shows the typically Japanese modesty of downplaying your own work while elevating the viewer.","related":["keigo-sonkeigo-gorankudasai","keigo-kenjougo-omenikakeru"]},
{"id":"keigo-kenjougo-tatematsuru","pattern":"奉る（たてまつる）","level":"N1","category":"Keigo","subcategory":"謙譲語","meaning":"to offer respectfully; to dedicate (classical)","explanation":"奉る is a classical (文語) kenjōgo form expressing that you humbly offer or dedicate something to a person of the very highest status. In modern language it is found in religious contexts, ceremonial acts and fixed expressions such as 謹んで申し上げ奉ります.","formation":"奉る (godan verb) ／ Verb (連用形) + 奉る (classical)","examples":[{"japanese":"神に祈りを奉る。","romaji":"Kami ni inori wo tatematsuru.","german":"I offer a prayer to the gods.","cloze":{"start":5,"answer":"奉る","quiz":{"level":"N1","japanese":"神に祈りを奉る。","german":"I offer a prayer to the gods.","start":5,"answer":"奉る","acceptedAnswers":["奉る"],"distractors":[{"text":"奉らない","reason":"This negates the offering."},{"text":"奉るます","reason":"ます needs the verb stem."},{"text":"奉るました","reason":"The polite past needs the verb stem."}]}}},{"japanese":"陛下にこの品を奉ります。","romaji":"Heika ni kono shina o tatematsurimasu.","german":"I respectfully present this item to His Majesty."},{"japanese":"謹んで新年のお慶びを申し上げ奉ります。","romaji":"Tsutsushinde shinnen no oyorokobi o mōshiage tatematsurimasu.","german":"I most respectfully extend my New Year's greetings."}],"notes":"奉る is archaic in modern everyday language, but alive in certain contexts: Shintō ceremonies (奉納 = ritual offering), New Year's greetings and imperial occasions. The form 謹んで～奉る is the most polite in the entire Japanese keigo system.","related":["keigo-sonkeigo-tamawaru","keigo-kenjougo-moushiageru"]},
{"id":"keigo-kenjougo-haichou","pattern":"拝聴する（はいちょうする）","level":"N1","category":"Keigo","subcategory":"謙譲語","meaning":"to listen (humble)","explanation":"拝聴する is the kenjōgo form of 聞く (to hear/listen). The kanji 拝 expresses humility. You use this form to say humbly that you are listening to a speech, a lecture or the words of a respected person.","formation":"拝聴する (fixed verb, conjugated like する) ／ 拝聴いたす (even more polite)","examples":[{"japanese":"先生のご講演を拝聴いたしました。","romaji":"Sensei no gokōen wo haichō itashimashita.","german":"I humbly listened to the professor's lecture.","cloze":{"start":7,"answer":"拝聴いたしました","quiz":{"level":"N1","japanese":"先生のご講演を拝聴いたしました。","german":"I humbly listened to the professor's lecture.","start":7,"answer":"拝聴いたしました","acceptedAnswers":["拝聴いたしました"],"distractors":[{"text":"拝聴いたしませんでした","reason":"This negates the listening."},{"text":"拝聴いたすました","reason":"The polite past needs the stem いたし."},{"text":"拝聴いたしましたます","reason":"The polite endings cannot be doubled."}]}}},{"japanese":"貴重なお話を拝聴できて光栄です。","romaji":"Kichō na ohanashi wo haichō dekite kōei desu.","german":"It is an honor to have heard your valuable words."},{"japanese":"ご意見を拝聴したく存じます。","romaji":"Goiken wo haichō shitaku zonjimasu.","german":"I would humbly like to hear your opinion."}],"notes":"拝聴する belongs to the group of 拝～する kenjōgo verbs alongside 拝見する、拝借する、拝読する. They all use the kanji 拝 (to bow) and express the utmost humility.","related":["keigo-kenjougo-haikensuru","keigo-kenjougo-haidokusuru"]},
{"id":"keigo-kenjougo-haijousuru","pattern":"拝受する（はいじゅする）","level":"N1","category":"Keigo","subcategory":"謙譲語","meaning":"to receive (humble, written)","explanation":"拝受する is a very formal kenjōgo form of 受け取る (to receive). It is used mainly in written business communication to humbly confirm receipt of documents, shipments or messages.","formation":"拝受する / 拝受いたしました (acknowledgment of receipt)","examples":[{"japanese":"資料を拝受いたしました。","romaji":"Shiryō wo haiju itashimashita.","german":"I have humbly received the materials.","cloze":{"start":3,"answer":"拝受いたしました","quiz":{"level":"N1","japanese":"資料を拝受いたしました。","german":"I have humbly received the materials.","start":3,"answer":"拝受いたしました","acceptedAnswers":["拝受いたしました"],"distractors":[{"text":"拝受いたしませんでした","reason":"This negates the receipt."},{"text":"拝受いたすました","reason":"The polite past needs the stem いたし."},{"text":"拝受いたしましたます","reason":"The polite endings cannot be doubled."}]}}},{"japanese":"ご送付いただいた書類を拝受いたしました。","romaji":"Gosōfu itadaita shorui wo haiju itashimashita.","german":"I have received the documents you sent."},{"japanese":"お見積もりを拝受し、社内で検討いたします。","romaji":"Omitsumori wo haiju shi, shanai de kentō itashimasu.","german":"I have received the quote and will review it internally."}],"notes":"拝受する is used almost exclusively in business emails and letters. It sounds more formal than いただきました and is the usual form for acknowledging receipt in Japanese business correspondence.","related":["keigo-kenjougo-itadaku","keigo-kenjougo-choudaisuru"]},
{"id":"keigo-kenjougo-tsutsushinde","pattern":"謹んで（つつしんで）","level":"N1","category":"Keigo","subcategory":"謙譲語","meaning":"respectfully; with the deepest respect","explanation":"謹んで is an adverb that expresses the highest respect and humility. It is used before formal acts such as apologies, congratulations and condolences and strengthens the humility of the statement that follows. It is indispensable in formal correspondence.","formation":"謹んで + verb (申し上げます / お詫び申し上げます / お祝い申し上げます)","examples":[{"japanese":"謹んでお詫び申し上げます。","romaji":"Tsutsushinde owabi mōshiagemasu.","german":"I offer my most humble apologies.","cloze":{"start":0,"answer":"謹んで","quiz":{"level":"N1","japanese":"謹んでお詫び申し上げます。","german":"I offer my most humble apologies.","start":0,"answer":"謹んで","acceptedAnswers":["謹んで"],"distractors":[{"text":"謹んだ","reason":"The attributive past does not form an adverbial connection here."},{"text":"謹みます","reason":"The finite form does not form a connection here."},{"text":"謹むで","reason":"The て-form of 謹む is 謹んで."}]}}},{"japanese":"謹んで新年のご挨拶を申し上げます。","romaji":"Tsutsushinde shinnen no goaisatsu wo mōshiagemasu.","german":"I respectfully extend my New Year's greetings."},{"japanese":"謹んでお悔やみ申し上げます。","romaji":"Tsutsushinde okuyami mōshiagemasu.","german":"Please accept my deepest condolences."}],"notes":"謹んで is found on New Year's cards (年賀状), in letters of condolence and in formal business letters. 謹賀新年 (Happy New Year, respectful) on New Year's cards contains the same kanji 謹.","related":["keigo-kenjougo-moushiageru","keigo-kenjougo-tatematsuru"]},
{"id":"keigo-kenjougo-guchimoushiageru","pattern":"愚見（ぐけん）/ 拙見（せっけん）","level":"N1","category":"Keigo","subcategory":"謙譲語","meaning":"my humble opinion (self-deprecation)","explanation":"愚見 and 拙見 are kenjōgo nouns with which you modestly call your own opinion a \"foolish view\" or \"clumsy view\". These forms of self-deprecation are typical of polite Japanese communication and appear in formal discussions and writing.","formation":"愚見 / 拙見 + ですが / ではございますが / を述べさせていただきます","examples":[{"japanese":"愚見ではございますが、この案が最適かと存じます。","romaji":"Guken de wa gozaimasu ga, kono an ga saiteki ka to zonjimasu.","german":"This is only my humble opinion, but I think this proposal is the best option.","cloze":{"start":0,"answer":"愚見","quiz":{"level":"N1","japanese":"愚見ではございますが、この案が最適かと存じます。","german":"This is only my humble opinion, but I think this proposal is the best option.","start":0,"answer":"愚見","acceptedAnswers":["愚見"],"distractors":[{"text":"愚見な","reason":"な does not fit before ではございますが here."},{"text":"愚見ます","reason":"ます cannot be attached directly to 愚見."},{"text":"愚見を","reason":"を does not fit before ではございますが here."}]}}},{"japanese":"拙見を述べさせていただきます。","romaji":"Sekken o nobesasete itadakimasu.","german":"Allow me to state my humble view."},{"japanese":"愚見ながら、再考の余地があると思われます。","romaji":"Guken nagara, saikō no yochi ga aru to omowaremasu.","german":"In my humble opinion, there seems to be room for reconsideration."}],"notes":"Similar self-deprecating forms: 拙著 (my humble book), 拙作 (my humble work), 愚息 (my foolish son = my son), 愚妻 (my foolish wife = my wife). Some of these forms are now outdated, but 愚見 and 拙見 are still used.","related":["keigo-kenjougo-zonjiru","keigo-kenjougo-tsutsushinde"]},
{"id":"keigo-kenjougo-heikou","pattern":"弊社（へいしゃ）/ 弊～","level":"N1","category":"Keigo","subcategory":"謙譲語","meaning":"our company (humble); our humble...","explanation":"弊社 is the humble term for your own company. The kanji 弊 means \"abuse/disadvantage\" and expresses self-deprecation. This form is indispensable in business correspondence and is the opposite of 御社/貴社 (your company, respectful).","formation":"弊社 (spoken/written) ／ 弊店 (our shop) ／ 弊局 (our office) ／ 弊誌 (our magazine)","examples":[{"japanese":"弊社の製品にご興味をお持ちいただき、ありがとうございます。","romaji":"Heisha no seihin ni gokyōmi wo omochi itadaki, arigatō gozaimasu.","german":"Thank you for your interest in our company's products.","cloze":{"start":0,"answer":"弊社","quiz":{"level":"N1","japanese":"弊社の製品にご興味をお持ちいただき、ありがとうございます。","german":"Thank you for your interest in our company's products.","start":0,"answer":"弊社","acceptedAnswers":["弊社","当社"],"distractors":[{"text":"御社","reason":"This refers to the other person's company instead of your own."},{"text":"貴社","reason":"This refers to the other person's company instead of your own."},{"text":"弊社な","reason":"な does not fit before の製品 here."}]}}},{"japanese":"弊社では、品質管理を徹底しております。","romaji":"Heisha de wa, hinshitsu kanri wo tettei shite orimasu.","german":"At our company, we are thorough about quality control."},{"japanese":"弊社の担当者より改めてご連絡いたします。","romaji":"Heisha no tantōsha yori aratamete gorenraku itashimasu.","german":"The person in charge at our company will contact you again."}],"notes":"In spoken business Japanese, 当社 (tōsha = our company) is also used, which sounds less humble but more neutral. 弊社 is the standard kenjōgo form in written communication. In emails to customers, 弊社 is almost always used.","related":["keigo-kenjougo-itasu","keigo-business-osewani"]},
{"id":"keigo-kenjougo-sesshou","pattern":"拙著（せっちょ）/ 拙稿（せっこう）","level":"N1","category":"Keigo","subcategory":"謙譲語","meaning":"my humble book; my humble manuscript","explanation":"拙著 and 拙稿 are kenjōgo nouns for your own literary or academic works. The kanji 拙 means \"clumsy/awkward\" and is a form of self-deprecation. You use these forms when mentioning your own work in conversation with others.","formation":"拙著 (my book) ／ 拙稿 (my manuscript) ／ 拙作 (my work) ／ 拙論 (my paper)","examples":[{"japanese":"拙著をお読みいただき、ありがとうございます。","romaji":"Setcho wo oyomi itadaki, arigatō gozaimasu.","german":"Thank you for reading my humble book.","cloze":{"start":0,"answer":"拙著","quiz":{"level":"N1","japanese":"拙著をお読みいただき、ありがとうございます。","german":"Thank you for reading my humble book.","start":0,"answer":"拙著","acceptedAnswers":["拙著"],"distractors":[{"text":"拙著な","reason":"な does not fit before をお読み here."},{"text":"拙著ます","reason":"ます cannot be attached directly to 拙著."},{"text":"拙著を","reason":"The following を would be doubled, which is not allowed."}]}}},{"japanese":"拙稿に目を通していただければ幸いです。","romaji":"Sekkō ni me wo tōshite itadakereba saiwai desu.","german":"I would be grateful if you would look over my humble manuscript."},{"japanese":"拙論ではございますが、ご参考になれば幸いです。","romaji":"Setsuron de wa gozaimasu ga, gosankō ni nareba saiwai desu.","german":"It is only my humble paper, but I hope it can serve as a reference."}],"notes":"These forms are used especially in academic and literary circles. In contrast, for other people's works you use respectful forms such as ご著書 (your book), ご高著 (your great book), 大著 (your extensive work).","related":["keigo-kenjougo-guchimoushiageru","keigo-kenjougo-haikensuru"]},
{"id":"keigo-kenjougo-onrei","pattern":"御礼申し上げる（おんれいもうしあげる）","level":"N1","category":"Keigo","subcategory":"謙譲語","meaning":"to express one's thanks (most respectful)","explanation":"御礼申し上げる is one of the most formal expressions of thanks in Japanese. It combines 御礼 (thanks, respectful) with 申し上げる (to say, humble). This form is used in official acknowledgments, business letters and on ceremonial occasions.","formation":"御礼 / お礼 + 申し上げます ／ 厚く御礼申し上げます (intensified)","examples":[{"japanese":"厚く御礼申し上げます。","romaji":"Atsuku onrei mōshiagemasu.","german":"I thank you most sincerely. (very formal)","cloze":{"start":2,"answer":"御礼申し上げます","quiz":{"level":"N1","japanese":"厚く御礼申し上げます。","german":"I thank you most sincerely. (very formal)","start":2,"answer":"御礼申し上げます","acceptedAnswers":["御礼申し上げます"],"distractors":[{"text":"御礼申し上げません","reason":"This negates the thanks."},{"text":"御礼申し上げるます","reason":"ます is not attached to the dictionary form."},{"text":"御礼申し上げまする","reason":"る cannot be attached to ます."}]}}},{"japanese":"ご協力いただきました皆様に、心より御礼申し上げます。","romaji":"Gokyōryoku itadakimashita minasama ni, kokoro yori onrei mōshiagemasu.","german":"I thank everyone who gave us their cooperation from the bottom of my heart."},{"japanese":"まずは略儀ながら、書面にて御礼申し上げます。","romaji":"Mazu wa ryakugi nagara, shomen nite onrei mōshiagemasu.","german":"For now, though it is only in writing, I would like to express my thanks."}],"notes":"厚く (warmly/sincerely) and 心より (from the heart) are common intensifiers. 略儀ながら (although it is only an informal way) is used when apologizing for thanking in writing rather than in person.","related":["keigo-kenjougo-moushiageru","keigo-kenjougo-tsutsushinde"]},
{"id":"keigo-kenjougo-sanjouitasu","pattern":"参上する（さんじょうする）","level":"N1","category":"Keigo","subcategory":"謙譲語","meaning":"to humbly go; to call on (someone)","explanation":"参上する is a very formal kenjōgo form of 行く (to go) / 訪ねる (to visit) that expresses that you respectfully go to a person of higher status. It sounds more formal than 参る and is used in elevated business language and on official occasions.","formation":"参上する (fixed verb, conjugated like する) ／ 参上いたす (even more polite)","examples":[{"japanese":"明日、御社に参上いたします。","romaji":"Ashita, onsha ni sanjō itashimasu.","german":"I will call at your company tomorrow.","cloze":{"start":6,"answer":"参上いたします","quiz":{"level":"N1","japanese":"明日、御社に参上いたします。","german":"I will call at your company tomorrow.","start":6,"answer":"参上いたします","acceptedAnswers":["参上いたします","伺います"],"distractors":[{"text":"参上いたしません","reason":"This negates the announced visit."},{"text":"参上いたすます","reason":"ます needs the stem いたし."},{"text":"参上いたしまする","reason":"る cannot be attached to ます."}]}}},{"japanese":"ただいま参上いたしました。","romaji":"Tadaima sanjō itashimashita.","german":"I have just arrived."},{"japanese":"お招きいただき、参上した次第でございます。","romaji":"Omaneki itadaki, sanjō shita shidai de gozaimasu.","german":"I have come in response to your kind invitation."}],"notes":"参上する is more formal than 参る and 伺う. In modern business language 伺う is used more often, but 参上する is found in official letters of invitation and on traditional occasions.","related":["keigo-kenjougo-mairu","keigo-kenjougo-ukagau"]},
{"id":"keigo-kenjougo-zoujisuru","pattern":"贈呈する（ぞうていする）","level":"N1","category":"Keigo","subcategory":"謙譲語","meaning":"to present formally; to give (formal)","explanation":"贈呈する is a very formal form of あげる (to give) or プレゼントする (to give as a present) used for official presentations. It expresses that you solemnly and respectfully present something to a person, e.g. an award, a gift or a certificate.","formation":"贈呈する (fixed verb) ／ ～を贈呈いたします","examples":[{"japanese":"記念品を贈呈いたします。","romaji":"Kinenhin wo zōtei itashimasu.","german":"We will now present a commemorative gift.","cloze":{"start":4,"answer":"贈呈いたします","quiz":{"level":"N1","japanese":"記念品を贈呈いたします。","german":"We will now present a commemorative gift.","start":4,"answer":"贈呈いたします","acceptedAnswers":["贈呈いたします"],"distractors":[{"text":"贈呈いたしません","reason":"This negates the announced presentation."},{"text":"贈呈いたすます","reason":"ます needs the stem いたし."},{"text":"贈呈いたしまする","reason":"る cannot be attached to ます."}]}}},{"japanese":"優勝者にトロフィーを贈呈いたします。","romaji":"Yūshōsha ni torofī wo zōtei itashimasu.","german":"We will now present the trophy to the winner."},{"japanese":"花束を贈呈させていただきます。","romaji":"Hanataba wo zōtei sasete itadakimasu.","german":"Allow me to present you with a bouquet of flowers."}],"notes":"贈呈する is used at ceremonies, award presentations and official occasions. Unlike 差し上げる, which is common in everyday business life, 贈呈する has a ceremonial character.","related":["keigo-kenjougo-sashiageru","keigo-kenjougo-tsutsushinde"]},
{"id":"keigo-kenjougo-haizensuru","pattern":"お持ちする / お持ちいたす","level":"N1","category":"Keigo","subcategory":"謙譲語","meaning":"to bring; to serve (humble, restaurant service)","explanation":"お持ちする is the kenjōgo form of 持っていく / 持ってくる: you bring something to the guest and present your own action humbly. お持ちいたします is one step more formal still. In restaurants and hotels, both forms are standard. 配膳する (\"serving food\"), on the other hand, is not keigo but a neutral technical term; it only becomes polite as 配膳させていただきます.","formation":"お + verb (ます-stem of 持つ) + する / いたす ／ お持ちしてもよろしいでしょうか","examples":[{"japanese":"お料理をお持ちいたしました。","romaji":"Oryōri wo omochi itashimashita.","german":"Here is your meal. (waiter's language)","cloze":{"start":4,"answer":"お持ちいたしました","quiz":{"level":"N1","japanese":"お料理をお持ちいたしました。","german":"Here is your meal. (waiter's language)","start":4,"answer":"お持ちいたしました","acceptedAnswers":["お持ちいたしました"],"distractors":[{"text":"お持ちいたしませんでした","reason":"This negates the bringing."},{"text":"お持ちいたすました","reason":"The polite past needs the stem いたし."},{"text":"お持ちいたしましたます","reason":"The polite endings cannot be doubled."}]}}},{"japanese":"デザートをお持ちしてもよろしいでしょうか。","romaji":"Dezāto wo omochi shite mo yoroshii deshō ka.","german":"May I bring you dessert?"},{"japanese":"お飲み物をお持ちいたします。少々お待ちくださいませ。","romaji":"Onomimono wo omochi itashimasu. Shōshō omachi kudasaimase.","german":"I will bring your drinks. Please wait a moment."}],"notes":"Japanese restaurants use keigo throughout. Standard phrases such as お持ちいたします, ご注文はお決まりでしょうか and お皿をお下げしてもよろしいでしょうか are part of the basic vocabulary of service staff.","related":["keigo-kenjougo-itasu","keigo-kenjougo-kashikomarimashita"]},
{"id":"keigo-teinei-yoroshiideshouka","pattern":"よろしいでしょうか","level":"N2","category":"Keigo","subcategory":"丁寧語","meaning":"would that be all right? / may I?","explanation":"よろしいでしょうか is the polite form of いいですか (is that OK?). よろしい is the formal version of いい (good/fine), and でしょうか turns it into an even more polite question. This form is used constantly in business and customer service.","formation":"よろしいでしょうか ／ ～してもよろしいでしょうか (asking permission)","examples":[{"japanese":"少々お時間をいただいてもよろしいでしょうか。","cloze":{"start":12,"answer":"よろしいでしょうか","quiz":{"level":"N2","japanese":"少々お時間をいただいてもよろしいでしょうか。","german":"Would it be all right if I took a little of your time?","start":12,"answer":"よろしいでしょうか","acceptedAnswers":["よろしいでしょうか","よろしいですか"],"distractors":[{"text":"よろしいなでしょうか","reason":"An i-adjective does not take な."},{"text":"よろしいますか","reason":"ます cannot be attached directly to よろしい."},{"text":"よろしかったいでしょうか","reason":"The past form ends in かった without an extra い."}]}},"romaji":"Shōshō ojikan wo itadaite mo yoroshii deshō ka.","german":"Would it be all right if I took a little of your time?"},{"japanese":"こちらの席でよろしいでしょうか。","cloze":{"start":6,"answer":"よろしいでしょうか"},"romaji":"Kochira no seki de yoroshii deshō ka.","german":"Is this seat all right for you?"},{"japanese":"明日の15時でよろしいでしょうか。","cloze":{"start":7,"answer":"よろしいでしょうか"},"romaji":"Ashita no jūgo-ji de yoroshii deshō ka.","german":"Would tomorrow at 3 p.m. be all right?"}],"notes":"よろしいでしょうか is the standard polite form for confirmation questions in business. It is more polite than いいですか but less roundabout than よろしゅうございますでしょうか (extremely formal and old-fashioned).","related":["keigo-teinei-itadakemasenka","keigo-teinei-degozaimasu"]},
{"id":"keigo-teinei-orimasu","pattern":"～ております","level":"N2","category":"Keigo","subcategory":"丁寧語","meaning":"humble progressive (I am / we are doing ...)","explanation":"～ております is the polite, humble progressive form that replaces ～ている. It combines the て-form with おります (the humble form of いる). In business it is the standard form for politely describing your own state or activity.","formation":"Verb (て-form) + おります","examples":[{"japanese":"承知しております。","cloze":{"start":3,"answer":"ております","quiz":{"level":"N2","japanese":"承知しております。","german":"I am aware. / I understand.","start":3,"answer":"ております","acceptedAnswers":["ております"],"distractors":[{"text":"たおります","reason":"Attaching おります requires the て-form."},{"text":"ておるます","reason":"ます requires the stem おり."},{"text":"ておりまする","reason":"る cannot be attached to ます."}]}},"romaji":"Shōchi shite orimasu.","german":"I am aware. / I understand."},{"japanese":"お待ちしております。","cloze":{"start":4,"answer":"ております"},"romaji":"Omachi shite orimasu.","german":"I look forward to seeing you. / I'll be waiting for you."},{"japanese":"現在、調査を進めております。","cloze":{"start":8,"answer":"ております"},"romaji":"Genzai, chōsa wo susumete orimasu.","german":"We are currently proceeding with the investigation."}],"notes":"～ております is the standard form on the phone and in emails when talking about yourself or your own company. 承知しております is the standard business reply for \"understood / I am aware.\"","related":["keigo-kenjougo-oru","keigo-teinei-degozaimasu"]},
{"id":"keigo-teinei-itashikatagozaimasen","pattern":"いたしかたございません","level":"N2","category":"Keigo","subcategory":"丁寧語","meaning":"it can't be helped / it is unavoidable (formal)","explanation":"いたしかたございません is the very formal version of 仕方がない (it can't be helped). いたしかた is the humble (kenjōgo) form of 仕方 (way/method), and ございません is the formal negative. This phrase is used in formal business situations to express regret about an unavoidable situation.","formation":"いたしかたございません / いたしかたないことですが (as a lead-in)","examples":[{"japanese":"規則ですので、いたしかたございません。","cloze":{"start":7,"answer":"いたしかたございません","quiz":{"level":"N2","japanese":"規則ですので、いたしかたございません。","german":"Since it is the rule, I'm afraid it can't be helped.","start":7,"answer":"いたしかたございません","acceptedAnswers":["いたしかたございません","仕方ございません"],"distractors":[{"text":"いたしかたございます","reason":"This affirms that something can be done instead of expressing that it is unavoidable."},{"text":"いたしかたござるません","reason":"ません is not attached to the dictionary form."},{"text":"いたしかたございませんない","reason":"The negative ending is not combined with ない a second time."}]}},"romaji":"Kisoku desu node, itashikata gozaimasen.","german":"Since it is the rule, I'm afraid it can't be helped."},{"japanese":"ご不便をおかけして申し訳ございませんが、安全上いたしかたございません。","cloze":{"start":23,"answer":"いたしかたございません"},"romaji":"Gofuben wo okake shite mōshiwake gozaimasen ga, anzen-jō itashikata gozaimasen.","german":"We apologize for the inconvenience, but it is unavoidable for safety reasons."},{"japanese":"天候によるものですので、いたしかたないかと存じます。","romaji":"Tenkō ni yoru mono desu node, itashikata nai ka to zonjimasu.","german":"Since it is due to the weather, I believe it can't be helped."}],"notes":"いたしかたございません is used especially when you have to explain to a customer or business partner why something is not possible. It sounds regretful but firm.","related":["keigo-teinei-kanemasu","keigo-bikago-moushiwake"]},
{"id":"keigo-teinei-gozaimasu","pattern":"ございます","level":"N2","category":"Keigo","subcategory":"丁寧語","meaning":"there is / exists (very polite)","explanation":"ございます is the most polite form of あります (there is). It belongs to 丁寧語 and is used to express the existence of something in a very polite way. This form is everywhere in customer service, in hotels and in upscale business language.","formation":"Noun + がございます ／ Noun + でございます (= to be)","examples":[{"japanese":"何かご質問はございますか。","cloze":{"start":6,"answer":"ございます","quiz":{"level":"N2","japanese":"何かご質問はございますか。","german":"Do you have any questions?","start":6,"answer":"ございます","acceptedAnswers":["ございます","あります"],"distractors":[{"text":"ござるます","reason":"The polite form is ございます."},{"text":"ございまする","reason":"る cannot be attached to ます."},{"text":"ございないます","reason":"The polite negative is ございません."}]}},"romaji":"Nanika goshitsumon wa gozaimasu ka.","german":"Do you have any questions?"},{"japanese":"こちらに駐車場がございます。","cloze":{"start":8,"answer":"ございます"},"romaji":"Kochira ni chūshajō ga gozaimasu.","german":"There is a parking lot here."},{"japanese":"お伝えしたいことがございます。","cloze":{"start":9,"answer":"ございます"},"romaji":"Otsutae shitai koto ga gozaimasu.","german":"There is something I would like to tell you."}],"notes":"ございます is the polite form of あります. ございます is not used for the existence of people (いらっしゃいます is used instead). The negative is ございません. With i-adjectives: 早い → 早うございます (rare today, except in ありがとうございます).","related":["keigo-teinei-degozaimasu","keigo-kenjougo-oru"]},
{"id":"keigo-teinei-itadakerebato","pattern":"～いただければと存じます","level":"N2","category":"Keigo","subcategory":"丁寧語","meaning":"I would be grateful if you could ... (very polite request)","explanation":"～いただければと存じます combines the conditional form of いただく with 存じます (to think, humble), producing an extremely polite way of making a request. The construction implies: \"If I could receive the favor of your ..., that would be my wish.\" It is often used in formal business emails.","formation":"Verb (て-form) + いただければと存じます ／ お/ご + Noun + いただければと存じます","examples":[{"japanese":"ご出席いただければと存じます。","cloze":{"start":3,"answer":"いただければと存じます","quiz":{"level":"N2","japanese":"ご出席いただければと存じます。","german":"I would be grateful if you could attend.","start":3,"answer":"いただければと存じます","acceptedAnswers":["いただければと存じます"],"distractors":[{"text":"いただけるればと存じます","reason":"The conditional is いただければ."},{"text":"いただければを存じます","reason":"The content of the thought requires と."},{"text":"いただければと存じるます","reason":"ます requires the verb stem."}]}},"romaji":"Goshusseki itadakereba to zonjimasu.","german":"I would be grateful if you could attend."},{"japanese":"ご意見をお聞かせいただければと存じます。","cloze":{"start":8,"answer":"いただければと存じます"},"romaji":"Goiken wo okikase itadakereba to zonjimasu.","german":"I would be grateful if you could let me hear your opinion."},{"japanese":"ご確認の上、ご返信いただければと存じます。","cloze":{"start":9,"answer":"いただければと存じます"},"romaji":"Gokakunin no ue, gohenshin itadakereba to zonjimasu.","german":"I would be grateful if you could check it and then reply."}],"notes":"This form is slightly less direct than ～いただけますでしょうか and slightly more polite than ～いただければ幸いです. It is used especially in business emails when you express a wish without asking for something directly.","related":["keigo-kenjougo-zonjiru","keigo-business-gokentou"]},
{"id":"keigo-teinei-moushiwakearumasenka","pattern":"～いただけますでしょうか","level":"N2","category":"Keigo","subcategory":"丁寧語","meaning":"would it be possible for you to ...? (very polite question)","explanation":"～いただけますでしょうか is one of the most polite question forms in Japanese. It combines the potential form of いただく with the polite conjectural form でしょうか. This three-layer politeness construction is used in formal business requests.","formation":"Verb (て-form) + いただけますでしょうか ／ お/ご + Noun + いただけますでしょうか","examples":[{"japanese":"資料をお送りいただけますでしょうか。","cloze":{"start":6,"answer":"いただけますでしょうか","quiz":{"level":"N2","japanese":"資料をお送りいただけますでしょうか。","german":"Would it be possible for you to send me the documents?","start":6,"answer":"いただけますでしょうか","acceptedAnswers":["いただけますでしょうか","いただけますか"],"distractors":[{"text":"いただけるますでしょうか","reason":"ます is not attached to the dictionary form."},{"text":"いただけまするでしょうか","reason":"る cannot be attached to ます."},{"text":"いただけないましたでしょうか","reason":"The polite negative is not formed with ないました."}]}},"romaji":"Shiryō wo ookuriitadakemasu deshō ka.","german":"Would it be possible for you to send me the documents?"},{"japanese":"ご都合のよい日時をお知らせいただけますでしょうか。","cloze":{"start":13,"answer":"いただけますでしょうか"},"romaji":"Gotsugō no yoi nichiji wo oshirase itadakemasu deshō ka.","german":"Could you let me know a date and time that suits you?"},{"japanese":"折り返しご連絡いただけますでしょうか。","cloze":{"start":7,"answer":"いただけますでしょうか"},"romaji":"Orikaeshi gorenraku itadakemasu deshō ka.","german":"Would it be possible for you to call me back?"}],"notes":"Politeness levels of requests: ～てくれますか < ～ていただけますか < ～ていただけませんか < ～ていただけますでしょうか. Some language purists consider ～いただけますでしょうか to be 二重敬語 (double keigo), but the form is firmly established in business practice.","related":["keigo-teinei-itadakemasenka","keigo-teinei-itadakerebato"]},
{"id":"keigo-teinei-nodesukedomo","pattern":"～のですが / ～のでございますが","level":"N2","category":"Keigo","subcategory":"丁寧語","meaning":"the thing is ... / I was wondering ... (polite lead-in)","explanation":"～のですが (or the even more polite ～のでございますが) is used to politely introduce a request, question or explanation. The が at the end signals that something more is to follow, which makes the statement indirect and therefore more polite. This form is fundamental to polite communication in Japanese.","formation":"Verb/Adjective + のですが / のでございますが ／ Noun + なのですが","examples":[{"japanese":"予約をしたいのですが。","cloze":{"start":6,"answer":"のですが","quiz":{"level":"N2","japanese":"予約をしたいのですが。","german":"I'd like to make a reservation...","start":6,"answer":"のですが","acceptedAnswers":["のですが","んですが","のですけれども"],"distractors":[{"text":"のますが","reason":"ます cannot be attached directly to の."},{"text":"なですが","reason":"たい requires の here, not な."},{"text":"のでだが","reason":"The explanatory construction does not use the combination のでだが."}]}},"romaji":"Yoyaku wo shitai no desu ga.","german":"I'd like to make a reservation..."},{"japanese":"少しお伺いしたいことがあるのですが。","cloze":{"start":13,"answer":"のですが"},"romaji":"Sukoshi oukagai shitai koto ga aru no desu ga.","german":"There's something I'd like to ask you..."},{"japanese":"お届け日の変更をお願いしたいのでございますが。","cloze":{"start":14,"answer":"のでございますが"},"romaji":"Otodoke-bi no henkō wo onegai shitai no de gozaimasu ga.","german":"I'd like to ask you to change the delivery date..."}],"notes":"Ending a sentence with が (without continuing it) is typically Japanese and expresses that the speaker leaves the situation open and gives the listener room to respond. It is one of the basic mechanisms of indirect communication in Japanese.","related":["keigo-teinei-itadakemasenka","keigo-teinei-yoroshiideshouka"]},
{"id":"keigo-teinei-shouchiitashimashita","pattern":"承知いたしました","level":"N2","category":"Keigo","subcategory":"丁寧語","meaning":"understood / duly noted (very polite)","explanation":"承知いたしました is a very formal way of answering \"understood\" and combines 承知 (knowledge/consent) with いたしました (the humble (kenjōgo) form of しました). In the politeness hierarchy it ranks between 分かりました and かしこまりました.","formation":"承知いたしました / 承知しました (slightly less formal)","examples":[{"japanese":"承知いたしました。すぐに対応いたします。","cloze":{"start":0,"answer":"承知いたしました","quiz":{"level":"N2","japanese":"承知いたしました。すぐに対応いたします。","german":"Understood. I will take care of it right away.","start":0,"answer":"承知いたしました","acceptedAnswers":["承知いたしました","かしこまりました"],"distractors":[{"text":"承知いたすました","reason":"The polite past requires the stem いたし."},{"text":"承知いたしましたます","reason":"Politeness endings cannot be doubled."},{"text":"承知いたしません","reason":"This negates the agreement."}]}},"romaji":"Shōchi itashimashita. Sugu ni taiō itashimasu.","german":"Understood. I will take care of it right away."},{"japanese":"日程の変更について承知いたしました。","cloze":{"start":9,"answer":"承知いたしました"},"romaji":"Nittei no henkō ni tsuite shōchi itashimashita.","german":"I have noted the change of schedule."},{"japanese":"ご要望の件、承知いたしました。","cloze":{"start":6,"answer":"承知いたしました"},"romaji":"Goyōbō no ken, shōchi itashimashita.","german":"Regarding your request: understood."}],"notes":"The politeness levels: 分かった → 分かりました → 承知しました → 承知いたしました → かしこまりました. 承知いたしました is the most common in everyday business, since かしこまりました tends to be reserved for customer service.","related":["keigo-kenjougo-kashikomarimashita","keigo-kenjougo-itasu"]},
{"id":"keigo-teinei-osoreirimasu","pattern":"恐れ入ります","level":"N2","category":"Keigo","subcategory":"丁寧語","meaning":"thank you very much / excuse me / I am honored","explanation":"恐れ入ります is a versatile polite phrase that expresses gratitude, apology or deference depending on the context. Literally it means \"I am frightened/overwhelmed\" and expresses that you feel unworthy of the other person's kindness or effort.","formation":"恐れ入ります (set phrase) ／ 恐れ入りますが (lead-in before a request)","examples":[{"japanese":"恐れ入ります。大変助かりました。","cloze":{"start":0,"answer":"恐れ入ります","quiz":{"level":"N2","japanese":"恐れ入ります。大変助かりました。","german":"I'm much obliged. You've been a great help.","start":0,"answer":"恐れ入ります","acceptedAnswers":["恐れ入ります","ありがとうございます"],"distractors":[{"text":"恐れ入るます","reason":"ます requires the stem 入り."},{"text":"恐れ入りまする","reason":"る cannot be attached to ます."},{"text":"恐れ入りますた","reason":"The polite past ends in ました."}]}},"romaji":"Osore irimasu. Taihen tasukarimashita.","german":"I'm much obliged. You've been a great help."},{"japanese":"恐れ入りますが、もう一度おっしゃっていただけますか。","cloze":{"start":0,"answer":"恐れ入ります"},"romaji":"Osore irimasu ga, mō ichido osshatte itadakemasu ka.","german":"Excuse me, but could you please say that once more?"},{"japanese":"お褒めいただき、恐れ入ります。","cloze":{"start":8,"answer":"恐れ入ります"},"romaji":"Ohome itadaki, osore irimasu.","german":"I'm honored by your praise."}],"notes":"恐れ入ります is used extremely often in business. Depending on the context, it can replace ありがとうございます and すみません while sounding more professional. The form with が at the end introduces a polite request.","related":["keigo-business-osoreirimasuga","keigo-bikago-moushiwake"]},
{"id":"keigo-teinei-saseteitadakuuses","pattern":"～させていただく (erweiterte Verwendungen)","level":"N2","category":"Keigo","subcategory":"丁寧語","meaning":"allow me to ... (various business contexts)","explanation":"In modern business Japanese, ～させていただく is used for various purposes: announcements, refusals, notices of changes and official statements. Although the form literally asks for permission, it is often used formulaically for one-sided announcements.","formation":"Verb (させ-form) + ていただきます ／ ～させていただくことになりました (announcing a decision)","examples":[{"japanese":"本日をもちまして閉店させていただきます。","romaji":"Honjitsu wo mochimashite heiten sasete itadakimasu.","german":"Please allow us to close the store as of today.","cloze":{"start":10,"answer":"させていただきます","quiz":{"level":"N2","japanese":"本日をもちまして閉店させていただきます。","german":"Please allow us to close the store as of today.","start":10,"answer":"させていただきます","acceptedAnswers":["させていただきます"],"distractors":[{"text":"させるいただきます","reason":"いただく requires the て-connection."},{"text":"させていただくます","reason":"ます requires the stem いただき."},{"text":"させていただきません","reason":"This negates the announced closure."}]}}},{"japanese":"価格を改定させていただくことになりました。","romaji":"Kakaku wo kaitei sasete itadaku koto ni narimashita.","german":"It has been decided that we will revise our prices."},{"japanese":"今回はご遠慮させていただきます。","romaji":"Konkai wa goenryo sasete itadakimasu.","german":"Allow me to decline this time."}],"notes":"The inflationary use of ～させていただく is a much-debated topic among those who care about the Japanese language. Although purists criticize that no real permission is involved (e.g. with store closures), the form is firmly anchored in everyday business. ご遠慮させていただきます is the standard way of declining.","related":["keigo-teinei-sasete-itadaku","keigo-teinei-kanemasu"]},
{"id":"keigo-teinei-gosoudan","pattern":"ご相談させていただきたく","level":"N2","category":"Keigo","subcategory":"丁寧語","meaning":"I would like to discuss something with you","explanation":"ご相談させていただきたく is a polite phrase for expressing a wish to consult or discuss something. It is often used in business emails to open a conversation and conveys that you value the other person's expertise or opinion.","formation":"ご相談させていただきたく + ご連絡いたしました / 存じます","examples":[{"japanese":"新プロジェクトについてご相談させていただきたく、ご連絡いたしました。","cloze":{"start":11,"answer":"ご相談させていただきたく","quiz":{"level":"N2","japanese":"新プロジェクトについてご相談させていただきたく、ご連絡いたしました。","german":"I am contacting you because I would like to discuss the new project with you.","start":11,"answer":"ご相談させていただきたく","acceptedAnswers":["ご相談させていただきたく"],"distractors":[{"text":"ご相談させていただきたいく","reason":"The adverbial form of たい is たく."},{"text":"ご相談させるいただきたく","reason":"いただく requires the て-connection."},{"text":"ご相談させていただくたく","reason":"たい is attached to the stem いただき."}]}},"romaji":"Shin purojekuto ni tsuite gosōdan sasete itadakitaku, gorenraku itashimashita.","german":"I am contacting you because I would like to discuss the new project with you."},{"japanese":"一点ご相談がございます。","romaji":"Itten gosōdan ga gozaimasu.","german":"There is one matter I would like to discuss with you."},{"japanese":"ご相談したいことがあるのですが、お時間をいただけますでしょうか。","romaji":"Gosōdan shitai koto ga aru no desu ga, ojikan wo itadakemasu deshō ka.","german":"There is something I'd like to discuss with you; could you spare me some time?"}],"notes":"ご相談 is one of the most common openers for requests in the business world. The form signals to the recipient that a discussion is wanted without sounding demanding.","related":["keigo-business-nokenni","keigo-teinei-itadakerebato"]},
{"id":"keigo-teinei-osoreirimashitsuki","pattern":"恐縮です（きょうしゅくです）","level":"N2","category":"Keigo","subcategory":"丁寧語","meaning":"I feel ashamed / I feel awkward (out of gratitude/guilt)","explanation":"恐縮です expresses that you feel ashamed or unworthy and is used both for gratitude and for apologies. 恐縮 literally means \"shrinking with fear.\" The phrase is slightly more formal than 恐れ入ります and is used especially in business correspondence.","formation":"恐縮です ／ 恐縮ですが (lead-in) ／ 恐縮に存じます (even more formal)","examples":[{"japanese":"お忙しいところ恐縮ですが、ご返信いただければ幸いです。","romaji":"Oisogashii tokoro kyōshuku desu ga, gohenshin itadakereba saiwai desu.","german":"I'm sorry to trouble you when you're busy, but I would be grateful for a reply.","cloze":{"start":7,"answer":"恐縮ですが","quiz":{"level":"N2","japanese":"お忙しいところ恐縮ですが、ご返信いただければ幸いです。","german":"I'm sorry to trouble you when you're busy, but I would be grateful for a reply.","start":7,"answer":"恐縮ですが","acceptedAnswers":["恐縮ですが","恐れ入りますが"],"distractors":[{"text":"恐縮ますが","reason":"ます cannot be attached directly to 恐縮."},{"text":"恐縮ですがを","reason":"を cannot be attached to this clause connection."},{"text":"恐縮なです","reason":"No な comes before the copula です here."}]}}},{"japanese":"大変恐縮ですが、日程の変更をお願いできますでしょうか。","romaji":"Taihen kyōshuku desu ga, nittei no henkō wo onegai dekimasu deshō ka.","german":"I'm terribly sorry to ask, but could I request a change of schedule?"},{"japanese":"わざわざお越しいただき、恐縮に存じます。","romaji":"Wazawaza okoshi itadaki, kyōshuku ni zonjimasu.","german":"I feel quite humbled (with gratitude) that you took the trouble to come all this way."}],"notes":"恐縮です is often combined with お忙しいところ or 大変. Unlike 恐れ入ります, 恐縮です has a stronger nuance of guilt. In emails, 恐縮ですが is a popular alternative to 恐れ入りますが.","related":["keigo-teinei-osoreirimasu","keigo-business-oisogashii"]},
{"id":"keigo-teinei-makotoni","pattern":"誠に（まことに）","level":"N2","category":"Keigo","subcategory":"丁寧語","meaning":"truly / sincerely / indeed (formal)","explanation":"誠に is a formal adverb used in business language and keigo to express sincerity and seriousness. It intensifies the expressions of thanks, apologies and other polite expressions that follow it, giving them a more formal tone.","formation":"誠に + ありがとうございます / 申し訳ございません / 恐縮です","examples":[{"japanese":"誠にありがとうございます。","romaji":"Makoto ni arigatō gozaimasu.","german":"I sincerely thank you.","cloze":{"start":0,"answer":"誠に","quiz":{"level":"N2","japanese":"誠にありがとうございます。","german":"I sincerely thank you.","start":0,"answer":"誠に","acceptedAnswers":["誠に","本当に"],"distractors":[{"text":"誠な","reason":"The adverbial expression is 誠に."},{"text":"誠を","reason":"を does not form an adverbial intensifier of the thanks here."},{"text":"誠ます","reason":"ます cannot be attached directly to 誠."}]}}},{"japanese":"誠に申し訳ございません。","romaji":"Makoto ni mōshiwake gozaimasen.","german":"I am truly and deeply sorry."},{"japanese":"誠に恐れ入りますが、ご対応をお願いいたします。","romaji":"Makoto ni osore irimasu ga, gotaiō wo onegai itashimasu.","german":"I'm truly sorry to trouble you, but I would ask you to take care of this."}],"notes":"誠に is the more formal alternative to 本当に (really). In business emails and letters, 誠に is preferred. 大変 (very) and 誠に can both be used as intensifiers, but 誠に sounds more sincere and more formal.","related":["keigo-bikago-moushiwake","keigo-teinei-osoreirimasu"]},
{"id":"keigo-bikago-otsukaresama","pattern":"お疲れ様でございます","level":"N2","category":"Keigo","subcategory":"美化語","meaning":"thank you for your hard work / good work (very formal)","explanation":"お疲れ様でございます is the most formal version of お疲れ様です, used as a greeting among colleagues and as acknowledgment of work done. The でございます form makes it particularly respectful; it is used toward superiors and in formal situations.","formation":"お疲れ様でございます (set phrase) ／ お疲れ様でした (after finishing a piece of work)","examples":[{"japanese":"お疲れ様でございます。本日の会議の議事録をお送りいたします。","cloze":{"start":0,"answer":"お疲れ様でございます","quiz":{"level":"N2","japanese":"お疲れ様でございます。本日の会議の議事録をお送りいたします。","german":"Thank you for your hard work. I am sending you the minutes of today's meeting.","start":0,"answer":"お疲れ様でございます","acceptedAnswers":["お疲れ様でございます","お疲れ様です"],"distractors":[{"text":"お疲れ様でござるます","reason":"The polite form is ございます."},{"text":"お疲れ様でございまする","reason":"る cannot be attached to ます."},{"text":"お疲れ様でございますた","reason":"The polite past ends in ました."}]}},"romaji":"Otsukaresama de gozaimasu. Honjitsu no kaigi no gijiroku wo ookuriitashimasu.","german":"Thank you for your hard work. I am sending you the minutes of today's meeting."},{"japanese":"長時間のご対応、お疲れ様でございました。","romaji":"Chōjikan no gotaiō, otsukaresama de gozaimashita.","german":"Thank you for your hard work in handling this for so long."},{"japanese":"お疲れ様でございます。田中でございますが、少々お時間よろしいでしょうか。","cloze":{"start":0,"answer":"お疲れ様でございます"},"romaji":"Otsukaresama de gozaimasu. Tanaka de gozaimasu ga, shōshō ojikan yoroshii deshō ka.","german":"Hello (internal greeting). This is Tanaka; would you have a moment?"}],"notes":"お疲れ様でございます is used as the standard opening in internal company emails (like お世話になっております with external contacts). Toward superiors, お疲れ様です is the minimum; ご苦労様です should only be used toward subordinates.","related":["keigo-teinei-degozaimasu","keigo-business-osewani"]},
{"id":"keigo-bikago-obi","pattern":"お/ご + Nomen (美化語)","level":"N2","category":"Keigo","subcategory":"美化語","meaning":"beautifying prefix for nouns","explanation":"美化語 refers to the use of the prefixes お (for native Japanese words) and ご (for Sino-Japanese words) to beautify words and make them sound more polite. Unlike respectful language (sonkeigo) and humble language (kenjōgo), 美化語 is not directed at a particular person but makes speech more elegant in general.","formation":"お + native Japanese word ／ ご + Sino-Japanese word","examples":[{"japanese":"お茶をお入れしましょうか。","romaji":"Ocha wo oire shimashō ka.","german":"Shall I make some tea?"},{"japanese":"お天気がよくなりましたね。","cloze":{"start":0,"answer":"お","quiz":{"level":"N2","japanese":"お天気がよくなりましたね。","german":"The weather has gotten nice, hasn't it?","start":0,"answer":"お","acceptedAnswers":["お"],"distractors":[{"text":"おを","reason":"An object particle cannot stand between the prefix and 天気."},{"text":"おな","reason":"な cannot stand between the prefix and 天気."},{"text":"おます","reason":"ます cannot be attached to the prefix."}]}},"romaji":"Otenki ga yoku narimashita ne.","german":"The weather has gotten nice, hasn't it?"},{"japanese":"ご飯ができましたよ。","romaji":"Gohan ga dekimashita yo.","german":"The meal is ready!"}],"notes":"Some words have お/ご so firmly built in that they are hardly used without it (お茶, ご飯, お金). For others it is optional and signals the level of politeness. Loanwords (katakana) normally do not take お/ご, with exceptions such as おトイレ (colloquial).","related":["keigo-bikago-goenryonaku","keigo-teinei-degozaimasu"]},
{"id":"keigo-bikago-keijou","pattern":"敬称（けいしょう）: 様・殿・各位","level":"N2","category":"Keigo","subcategory":"美化語","meaning":"polite forms of address and titles","explanation":"Japanese honorific titles (敬称) are an important part of the keigo system. 様 (sama) is the most polite general form of address, 殿 (dono) is used in official documents, and 各位 (kakui) addresses a group. Using these forms correctly is essential in business.","formation":"Name + 様 (standard) ／ Name + 殿 (official) ／ 各位 (to all)","examples":[{"japanese":"田中様、お電話ありがとうございます。","romaji":"Tanaka-sama, odenwa arigatō gozaimasu.","german":"Mr./Ms. Tanaka, thank you for your call.","cloze":{"start":2,"answer":"様","quiz":{"level":"N2","japanese":"田中様、お電話ありがとうございます。","german":"Mr./Ms. Tanaka, thank you for your call.","start":2,"answer":"様","acceptedAnswers":["様","さん"],"distractors":[{"text":"様を","reason":"The object particle does not make a form of address here."},{"text":"様な","reason":"The attributive particle does not fit the form of address here."},{"text":"様ます","reason":"ます cannot be attached directly to the honorific suffix."}]}}},{"japanese":"社員各位：本日の会議は中止となりました。","romaji":"Shain kakui: honjitsu no kaigi wa chūshi to narimashita.","german":"To all employees: today's meeting has been cancelled."},{"japanese":"人事部長殿","romaji":"Jinji buchō dono","german":"To the Head of the Human Resources Department (in official documents)"}],"notes":"様 is the safest choice in business correspondence. 殿 is mainly used in internal documents and certificates and is considered outdated in emails. 各位 replaces ～の皆様 in formal circulars. For outside companies: 御中 (onchū) for the company, 様 for individuals.","related":["keigo-teinei-degozaimasu","keigo-business-yoroshiku"]},
{"id":"keigo-business-denwataiou","pattern":"お電話ありがとうございます","level":"N2","category":"Keigo","subcategory":"ビジネス敬語","meaning":"thank you for calling (telephone etiquette)","explanation":"お電話ありがとうございます is the standard opening when answering business calls. It is used together with the company name and your own name. Japanese telephone etiquette has fixed formulas that every businessperson must master.","formation":"お電話ありがとうございます。[Company名]の[名前]でございます。","examples":[{"japanese":"お電話ありがとうございます。ABC商事の鈴木でございます。","cloze":{"start":0,"answer":"お電話ありがとうございます","quiz":{"level":"N2","japanese":"お電話ありがとうございます。ABC商事の鈴木でございます。","german":"Thank you for calling. This is Suzuki from ABC Trading.","start":0,"answer":"お電話ありがとうございます","acceptedAnswers":["お電話ありがとうございます"],"distractors":[{"text":"お電話ありがとうます","reason":"The polite form of thanks is ありがとうございます."},{"text":"お電話ありがとうございまする","reason":"る cannot be attached to ます."},{"text":"お電話ありがとうございますた","reason":"The polite past ends in ました."}]}},"romaji":"Odenwa arigatō gozaimasu. ABC shōji no Suzuki de gozaimasu.","german":"Thank you for calling. This is Suzuki from ABC Trading."},{"japanese":"お電話いただきありがとうございます。どのようなご用件でしょうか。","romaji":"Odenwa itadaki arigatō gozaimasu. Dono yō na goyōken deshō ka.","german":"Thank you for calling. How may I help you?"},{"japanese":"お電話ありがとうございます。ただいま担当者に代わりますので、少々お待ちください。","cloze":{"start":0,"answer":"お電話ありがとうございます"},"romaji":"Odenwa arigatō gozaimasu. Tadaima tantōsha ni kawarimasu node, shōshō omachi kudasai.","german":"Thank you for calling. I'll put you through to the person in charge, so please hold for a moment."}],"notes":"Japanese telephone etiquette follows fixed rules: 1) greet the caller with the company name, 2) ask what the call is about, 3) confirm the customer's name (お名前を頂戴できますか), 4) transfer the call or offer a callback. 恐れ入りますが is used as a cushion word before questions.","related":["keigo-business-osewani","keigo-kenjougo-odenwasashiageru"]},
{"id":"keigo-business-denwakawarimasu","pattern":"お電話代わりました","level":"N2","category":"Keigo","subcategory":"ビジネス敬語","meaning":"you've been put through / I'm taking over the call","explanation":"お電話代わりました is the standard phrase you say when you take over a call from a colleague. It signals to the caller that a new person is on the line and is followed by a self-introduction.","formation":"お電話代わりました + [Department]の[Name]でございます。","examples":[{"japanese":"お電話代わりました。営業部の山田でございます。","cloze":{"start":0,"answer":"お電話代わりました","quiz":{"level":"N2","japanese":"お電話代わりました。営業部の山田でございます。","german":"You've been put through. This is Yamada from the sales department.","start":0,"answer":"お電話代わりました","acceptedAnswers":["お電話代わりました"],"distractors":[{"text":"お電話代わるました","reason":"The polite past requires the stem 代わり."},{"text":"お電話代わりましたます","reason":"Politeness endings cannot be doubled."},{"text":"お電話代わりません","reason":"This negates the takeover of the call, which has already happened."}]}},"romaji":"Odenwa kawarimashita. Eigyōbu no Yamada de gozaimasu.","german":"You've been put through. This is Yamada from the sales department."},{"japanese":"お電話代わりました。担当の佐藤でございます。お待たせいたしました。","cloze":{"start":0,"answer":"お電話代わりました"},"romaji":"Odenwa kawarimashita. Tantō no Satō de gozaimasu. Omatase itashimashita.","german":"You've been put through. This is Satō, the person in charge. Sorry to keep you waiting."},{"japanese":"お電話代わりました。ご用件をお伺いいたします。","cloze":{"start":0,"answer":"お電話代わりました"},"romaji":"Odenwa kawarimashita. Goyōken wo oukagai itashimasu.","german":"You've been put through. I'll now take your inquiry."}],"notes":"This phrase is said automatically after the call has been put through. When you transfer a caller yourself, you say: ただいま担当に代わります (I'll put you through to the person in charge now) or 少々お待ちくださいませ (please wait a moment).","related":["keigo-business-denwataiou","keigo-bikago-omataseitashimashita"]},
{"id":"keigo-business-sayoudesuka","pattern":"左様でございますか","level":"N2","category":"Keigo","subcategory":"ビジネス敬語","meaning":"is that so? / oh, I see (very formal)","explanation":"左様でございますか is the most formal version of そうですか (is that so?). 左様 (さよう) is the formal equivalent of そう (so), and でございます raises it to the highest level of politeness. This phrase is used in upscale customer service and very formal business situations.","formation":"左様でございますか (as a confirmation / listening signal)","examples":[{"japanese":"左様でございますか。承知いたしました。","cloze":{"start":0,"answer":"左様でございますか","quiz":{"level":"N2","japanese":"左様でございますか。承知いたしました。","german":"Oh, I see. Understood.","start":0,"answer":"左様でございますか","acceptedAnswers":["左様でございますか","そうですか"],"distractors":[{"text":"左様ますか","reason":"ます cannot be attached directly to 左様."},{"text":"左様でござるますか","reason":"The polite form is ございます."},{"text":"左様でございまするか","reason":"る cannot be attached to ます."}]}},"romaji":"Sayō de gozaimasu ka. Shōchi itashimashita.","german":"Oh, I see. Understood."},{"japanese":"左様でございますか。それは大変失礼いたしました。","cloze":{"start":0,"answer":"左様でございますか"},"romaji":"Sayō de gozaimasu ka. Sore wa taihen shitsurei itashimashita.","german":"Is that so? Please accept my sincere apologies for that."},{"japanese":"左様でございますか。ただちに確認いたします。","cloze":{"start":0,"answer":"左様でございますか"},"romaji":"Sayō de gozaimasu ka. Tadachi ni kakunin itashimasu.","german":"I see. I will check right away."}],"notes":"左様でございますか is used mainly in the hotel industry, by airlines and in premium customer service. In ordinary business, そうでございますか or そうですか is enough. Knowing this form shows an N1-level understanding of the keigo system.","related":["keigo-teinei-degozaimasu","keigo-kenjougo-kashikomarimashita"]},
{"id":"keigo-business-goannainomailbun","pattern":"ご案内申し上げます","level":"N2","category":"Keigo","subcategory":"ビジネス敬語","meaning":"allow me to inform you (formal announcement)","explanation":"ご案内申し上げます is a formal opening phrase for official announcements, invitations and notices. It combines ご案内 (information/guidance) with 申し上げます (to say, humble) and is used in business circulars, letters of invitation and official notifications.","formation":"ご案内申し上げます ／ ～につきまして、ご案内いたします","examples":[{"japanese":"下記のとおりご案内申し上げます。","cloze":{"start":6,"answer":"ご案内申し上げます","quiz":{"level":"N2","japanese":"下記のとおりご案内申し上げます。","german":"Please allow us to inform you as follows.","start":6,"answer":"ご案内申し上げます","acceptedAnswers":["ご案内申し上げます","ご案内いたします"],"distractors":[{"text":"ご案内申し上げません","reason":"This negates the announced information."},{"text":"ご案内申し上げるます","reason":"ます is not attached to the dictionary form."},{"text":"ご案内申し上げまする","reason":"る cannot be attached to ます."}]}},"romaji":"Kaki no tōri goannai mōshiagemasu.","german":"Please allow us to inform you as follows."},{"japanese":"年末年始の営業時間につきまして、ご案内申し上げます。","cloze":{"start":16,"answer":"ご案内申し上げます"},"romaji":"Nenmatsu nenshi no eigyō jikan ni tsukimashite, goannai mōshiagemasu.","german":"Please allow us to inform you of our business hours over the year-end and New Year holidays."},{"japanese":"新製品発売のご案内を申し上げます。","romaji":"Shinseihin hatsubai no goannai wo mōshiagemasu.","german":"Please allow us to inform you of the launch of our new product."}],"notes":"ご案内申し上げます is the standard opening for formal business announcements and letters of invitation. It often appears after the subject line of an official email or at the beginning of an informational letter.","related":["keigo-kenjougo-moushiageru","keigo-business-nokenni"]},
{"id":"keigo-business-oneguimouchiagemasu","pattern":"お願い申し上げます","level":"N2","category":"Keigo","subcategory":"ビジネス敬語","meaning":"I humbly request","explanation":"お願い申し上げます is the most formal version of お願いします and is used in official requests, business letters and formal inquiries. 申し上げる (to say/to offer, humble) gives the request the highest level of humility.","formation":"お願い申し上げます ／ 何卒お願い申し上げます (earnestly) ／ ～くださいますようお願い申し上げます","examples":[{"japanese":"何卒よろしくお願い申し上げます。","cloze":{"start":6,"answer":"お願い申し上げます","quiz":{"level":"N2","japanese":"何卒よろしくお願い申し上げます。","german":"I earnestly ask for your kind support.","start":6,"answer":"お願い申し上げます","acceptedAnswers":["お願い申し上げます","お願いいたします"],"distractors":[{"text":"お願い申し上げません","reason":"This negates the request."},{"text":"お願い申し上げるます","reason":"ます is not attached to the dictionary form."},{"text":"お願い申し上げまする","reason":"る cannot be attached to ます."}]}},"romaji":"Nanitozo yoroshiku onegai mōshiagemasu.","german":"I earnestly ask for your kind support."},{"japanese":"ご出席くださいますようお願い申し上げます。","cloze":{"start":11,"answer":"お願い申し上げます"},"romaji":"Goshusseki kudasaimasu yō onegai mōshiagemasu.","german":"I humbly request your attendance."},{"japanese":"ご容赦くださいますようお願い申し上げます。","cloze":{"start":11,"answer":"お願い申し上げます"},"romaji":"Goyōsha kudasaimasu yō onegai mōshiagemasu.","german":"I humbly ask for your indulgence."}],"notes":"お願い申し上げます is more formal than お願いいたします. In emails it is often used at the end, especially combined with 何卒 (earnestly). The progression: お願いします < お願いいたします < お願い申し上げます.","related":["keigo-business-yoroshiku","keigo-kenjougo-moushiageru"]},
{"id":"keigo-business-mailkaishibun","pattern":"平素より（へいそより）","level":"N2","category":"Keigo","subcategory":"ビジネス敬語","meaning":"as always / all along / continually (formal email opening)","explanation":"平素より is a formal adverb used as an opening in business letters and emails. It means \"all along\" or \"as always\" and introduces thanks for the business relationship so far. It is more formal than いつも (always).","formation":"平素より + 大変お世話になっております / 格別のお引き立てを賜り","examples":[{"japanese":"平素より大変お世話になっております。","romaji":"Heiso yori taihen osewa ni natte orimasu.","german":"Thank you very much for your continued support.","cloze":{"start":0,"answer":"平素より","quiz":{"level":"N2","japanese":"平素より大変お世話になっております。","german":"Thank you very much for your continued support.","start":0,"answer":"平素より","acceptedAnswers":["平素より","いつも"],"distractors":[{"text":"平素を","reason":"を does not form a time expression here."},{"text":"平素な","reason":"な does not connect to the thanks that follow here."},{"text":"平素ます","reason":"ます cannot be attached directly to 平素."}]}}},{"japanese":"平素より格別のお引き立てを賜り、誠にありがとうございます。","romaji":"Heiso yori kakubetsu no ohikitate wo tamawari, makoto ni arigatō gozaimasu.","german":"We sincerely thank you for your continued special patronage."},{"japanese":"平素より弊社製品をご愛顧いただき、厚く御礼申し上げます。","romaji":"Heiso yori heisha seihin wo goaiko itadaki, atsuku onrei mōshiagemasu.","german":"We extend our heartfelt thanks for your continued patronage of our products."}],"notes":"平素より is the most formal opening for business letters and emails. In everyday email communication, いつもお世話になっております is enough. 格別のお引き立て (special patronage) and ご愛顧 (customer loyalty) are common additions in official letters.","related":["keigo-business-osewani","keigo-sonkeigo-tamawaru"]},
{"id":"keigo-business-mailshimebun","pattern":"末筆ながら（まっぴつながら）","level":"N1","category":"Keigo","subcategory":"ビジネス敬語","meaning":"in closing / last but not least (letter ending)","explanation":"末筆ながら is a formal closing formula in business letters that literally means \"although it is the last line.\" It introduces a final wish, a wish for good health or an additional request. This formula shows that the writer is aware of the hierarchy.","formation":"末筆ながら + ご自愛ください / ますますのご発展をお祈り申し上げます","examples":[{"japanese":"末筆ながら、皆様のご健勝をお祈り申し上げます。","romaji":"Mappitsu nagara, minasama no gokenshō wo oinori mōshiagemasu.","german":"In closing, I wish you all the best of health.","cloze":{"start":0,"answer":"末筆ながら","quiz":{"level":"N1","japanese":"末筆ながら、皆様のご健勝をお祈り申し上げます。","german":"In closing, I wish you all the best of health.","start":0,"answer":"末筆ながら","acceptedAnswers":["末筆ながら"],"distractors":[{"text":"末筆ながらな","reason":"な cannot be attached here."},{"text":"末筆ながらを","reason":"を does not form a closing connection here."},{"text":"末筆ながらます","reason":"ます cannot be attached to ながら."}]}}},{"japanese":"末筆ながら、貴社のますますのご発展をお祈り申し上げます。","romaji":"Mappitsu nagara, kisha no masumasu no gohatten wo oinori mōshiagemasu.","german":"In closing, I wish your company continued prosperity."},{"japanese":"末筆ながら、時節柄くれぐれもご自愛くださいませ。","romaji":"Mappitsu nagara, jisetsugara kuregure mo gojiai kudasaimase.","german":"In closing, given the season, please take good care of yourself."}],"notes":"末筆ながら is used only in written communication. The formula implies modesty: the personal wish is placed at the end because it is secondary to the business content. ご自愛ください (please take care of your health) is the most common closing formula.","related":["keigo-business-yoroshiku","keigo-kenjougo-tsutsushinde"]},
{"id":"keigo-business-nantozosamaku","pattern":"何卒（なにとぞ）","level":"N2","category":"Keigo","subcategory":"ビジネス敬語","meaning":"earnestly / at all costs / please, by all means","explanation":"何卒 is a formal adverb that strengthens a request and expresses great urgency or seriousness. It means \"at all costs\" or \"please, by all means\" and is used in business emails, letters and formal requests to underline the importance of the request.","formation":"何卒 + よろしくお願いいたします / ご理解ください / ご容赦ください","examples":[{"japanese":"何卒ご理解いただけますようお願いいたします。","romaji":"Nanitozo gorikai itadakemasu yō onegai itashimasu.","german":"I earnestly ask for your understanding.","cloze":{"start":0,"answer":"何卒","quiz":{"level":"N2","japanese":"何卒ご理解いただけますようお願いいたします。","german":"I earnestly ask for your understanding.","start":0,"answer":"何卒","acceptedAnswers":["何卒","どうか"],"distractors":[{"text":"何卒を","reason":"を does not form an adverbial request here."},{"text":"何卒な","reason":"な cannot connect to the request here."},{"text":"何卒ます","reason":"ます cannot be attached directly to 何卒."}]}}},{"japanese":"何卒ご検討のほどよろしくお願いいたします。","romaji":"Nanitozo gokentō no hodo yoroshiku onegai itashimasu.","german":"I earnestly ask you to consider this matter."},{"japanese":"何卒お力添えいただけますようお願い申し上げます。","romaji":"Nanitozo ochikarazoe itadakemasu yō onegai mōshiagemasu.","german":"I humbly ask for your support."}],"notes":"何卒 is used almost exclusively in written business communication. It is one of the most important intensifiers in business letters. 何卒よろしくお願いいたします is the strongest standard closing formula in emails.","related":["keigo-business-yoroshiku","keigo-business-gokentou"]},
{"id":"keigo-business-ohikikaenitsukaesai","pattern":"ご笑納ください","level":"N1","category":"Keigo","subcategory":"ビジネス敬語","meaning":"please kindly accept it (for gifts/enclosures)","explanation":"ご笑納ください (ごしょうのうください) is used when you give someone a gift or an enclosure and literally means \"please accept it with a smile.\" It expresses modesty about the gift and asks the recipient to accept it graciously.","formation":"ご笑納ください / お納めください (less formal) / ご笑納いただければ幸いです","examples":[{"japanese":"ほんの気持ちですが、ご笑納ください。","cloze":{"start":10,"answer":"ご笑納ください","quiz":{"level":"N1","japanese":"ほんの気持ちですが、ご笑納ください。","german":"It's just a small token of my appreciation, but please kindly accept it.","start":10,"answer":"ご笑納ください","acceptedAnswers":["ご笑納ください"],"distractors":[{"text":"ご笑納するください","reason":"ください is not attached to する."},{"text":"ご笑納くださいまする","reason":"る cannot be attached to ます."},{"text":"ご笑納くださるました","reason":"The polite past requires the verb stem."}]}},"romaji":"Hon no kimochi desu ga, goshōnō kudasai.","german":"It's just a small token of my appreciation, but please kindly accept it."},{"japanese":"つまらないものですが、ご笑納いただければ幸いです。","romaji":"Tsumaranai mono desu ga, goshōnō itadakereba saiwai desu.","german":"It's nothing special, but I would be glad if you would accept it."},{"japanese":"粗品ではございますが、どうぞお納めください。","romaji":"Soshina de wa gozaimasu ga, dōzo oosame kudasai.","german":"It's just a small gift, but please accept it."}],"notes":"The Japanese culture of giving gifts includes traditional modest set phrases: つまらないものですが (it's nothing special), ほんの気持ちです (it's just a small token), 粗品ですが (it's just a little something). ご笑納 goes with all of these lead-ins.","related":["keigo-kenjougo-sashiageru","keigo-kenjougo-zoujisuru"]},
{"id":"keigo-business-goisainakunokosubekaku","pattern":"ご一報いただければ幸いです","level":"N2","category":"Keigo","subcategory":"ビジネス敬語","meaning":"I would be grateful for a quick message","explanation":"ご一報いただければ幸いです is a polite request for a short reply. 一報 means \"a message/notice,\" and the whole phrase politely asks the recipient to get in touch briefly. It is used in business emails when you are waiting for an answer or confirmation.","formation":"ご一報ください / ご一報いただければ幸いです / ご一報くださいますようお願いいたします","examples":[{"japanese":"ご都合が決まりましたら、ご一報いただければ幸いです。","cloze":{"start":12,"answer":"ご一報いただければ幸いです","quiz":{"level":"N2","japanese":"ご都合が決まりましたら、ご一報いただければ幸いです。","german":"Once your schedule is settled, I would be grateful for a quick message.","start":12,"answer":"ご一報いただければ幸いです","acceptedAnswers":["ご一報いただければ幸いです"],"distractors":[{"text":"ご一報いただけるれば幸いです","reason":"The conditional is いただければ."},{"text":"ご一報いただければ幸います","reason":"ます cannot be attached directly to 幸い."},{"text":"ご一報いただければ幸いを","reason":"を cannot complete this request."}]}},"romaji":"Gotsugō ga kimarimashitara, goippō itadakereba saiwai desu.","german":"Once your schedule is settled, I would be grateful for a quick message."},{"japanese":"到着されましたら、ご一報ください。","romaji":"Tōchaku saremashitara, goippō kudasai.","german":"Please let us know when you have arrived."},{"japanese":"何かお気づきの点がございましたら、ご一報くださいますようお願いいたします。","romaji":"Nanika okizuki no ten ga gozaimashitara, goippō kudasaimasu yō onegai itashimasu.","german":"If you notice anything, please let us know."}],"notes":"ご一報 is used as a less demanding alternative to ご連絡 (getting in touch) and signals that only a short confirmation message is expected, not a detailed letter.","related":["keigo-business-gofumeina","keigo-business-gokentou"]},
{"id":"keigo-business-gorenkudasaru","pattern":"ご返信いただけますと幸いです","level":"N2","category":"Keigo","subcategory":"ビジネス敬語","meaning":"I would be grateful for your reply","explanation":"ご返信いただけますと幸いです is a standard request for a reply in business emails. It is more polite than ご返信ください and less urgent than ご返信くださいますようお願い申し上げます. The と conditional together with 幸いです expresses a wish.","formation":"ご返信 + いただけますと / いただければ + 幸いです / 幸いに存じます","examples":[{"japanese":"お忙しいところ恐れ入りますが、今週中にご返信いただけますと幸いです。","cloze":{"start":19,"answer":"ご返信いただけますと幸いです","quiz":{"level":"N2","japanese":"お忙しいところ恐れ入りますが、今週中にご返信いただけますと幸いです。","german":"I'm sorry to trouble you when you're busy, but I would be grateful for a reply within this week.","start":19,"answer":"ご返信いただけますと幸いです","acceptedAnswers":["ご返信いただけますと幸いです"],"distractors":[{"text":"ご返信いただけるますと幸いです","reason":"ます is not attached to the dictionary form."},{"text":"ご返信いただけますと幸います","reason":"ます cannot be attached directly to 幸い."},{"text":"ご返信いただけますと幸いを","reason":"を cannot complete this request."}]}},"romaji":"Oisogashii tokoro osore irimasu ga, konshūchū ni gohenshin itadakemasu to saiwai desu.","german":"I'm sorry to trouble you when you're busy, but I would be grateful for a reply within this week."},{"japanese":"ご確認の上、ご返信いただければ幸いに存じます。","romaji":"Gokakunin no ue, gohenshin itadakereba saiwai ni zonjimasu.","german":"I would be grateful if you could check it and then reply."},{"japanese":"可能であれば、来週の月曜日までにご返信いただけますと助かります。","romaji":"Kanō de areba, raishū no getsuyōbi made ni gohenshin itadakemasu to tasukarimasu.","german":"If possible, it would be a great help if you could reply by next Monday."}],"notes":"In business emails, a deadline for the reply is always given. 幸いです is softer than お願いいたします and gives the recipient more leeway. 助かります (that would help me) is a slightly more informal but frequently used alternative.","related":["keigo-business-gokentou","keigo-teinei-itadakerebato"]},
{"id":"keigo-business-moushitsukeru","pattern":"お申し付けください","level":"N2","category":"Keigo","subcategory":"ビジネス敬語","meaning":"please let us know / please tell me","explanation":"お申し付けください is a polite customer-service phrase that signals to the other person that you are available at any time for inquiries, requests or instructions. 申し付ける means \"to instruct/to charge someone with,\" and with the respectful (sonkeigo) frame お～ください it becomes a deferential request.","formation":"お申し付けください ／ 何なりとお申し付けください (emphatic)","examples":[{"japanese":"何なりとお申し付けください。","cloze":{"start":4,"answer":"お申し付けください","quiz":{"level":"N2","japanese":"何なりとお申し付けください。","german":"Please don't hesitate to tell me anything you need.","start":4,"answer":"お申し付けください","acceptedAnswers":["お申し付けください"],"distractors":[{"text":"お申し付けるください","reason":"ください is not attached to the dictionary form."},{"text":"お申し付けくださいまする","reason":"る cannot be attached to ます."},{"text":"お申し付けくださるました","reason":"The polite past requires the correct stem."}]}},"romaji":"Nan nari to omōshitsuke kudasai.","german":"Please don't hesitate to tell me anything you need."},{"japanese":"ご不明な点がございましたら、お気軽にお申し付けください。","cloze":{"start":18,"answer":"お申し付けください"},"romaji":"Gofumei na ten ga gozaimashitara, okigaru ni omōshitsuke kudasai.","german":"If anything is unclear, please feel free to let us know at any time."},{"japanese":"追加のご要望がございましたら、お申し付けくださいませ。","cloze":{"start":15,"answer":"お申し付けください"},"romaji":"Tsuika no goyōbō ga gozaimashitara, omōshitsuke kudasaimase.","german":"If you have any further requests, please let us know."}],"notes":"何なりとお申し付けください is one of the most popular customer-service phrases and is often heard in hotels, restaurants and upscale retail. It sounds more welcoming and respectful than ~~ください alone.","related":["keigo-business-okigaruni","keigo-sonkeigo-okudasai"]},
{"id":"keigo-business-gorenraku-itadaki","pattern":"ご連絡いただきありがとうございます","level":"N2","category":"Keigo","subcategory":"ビジネス敬語","meaning":"thank you for your message / for getting in touch","explanation":"ご連絡いただきありがとうございます is a standard thank-you formula at the start of an email reply when the other person has gotten in touch. It shows appreciation for the contact and is one of the most frequently used opening phrases in business.","formation":"ご連絡いただきありがとうございます ／ ご連絡くださりありがとうございます","examples":[{"japanese":"早速のご連絡をいただきありがとうございます。","romaji":"Sassoku no gorenraku wo itadaki arigatō gozaimasu.","german":"Thank you for your prompt message."},{"japanese":"お忙しい中、ご連絡いただきありがとうございます。","cloze":{"start":6,"answer":"ご連絡いただきありがとうございます","quiz":{"level":"N2","japanese":"お忙しい中、ご連絡いただきありがとうございます。","german":"Thank you for getting in touch despite being so busy.","start":6,"answer":"ご連絡いただきありがとうございます","acceptedAnswers":["ご連絡いただきありがとうございます"],"distractors":[{"text":"ご連絡いただくありがとうございます","reason":"The thanks must be preceded here by the connecting stem or て-form."},{"text":"ご連絡いただきありがとうます","reason":"The polite form of thanks is ありがとうございます."},{"text":"ご連絡いただきありがとうございまする","reason":"る cannot be attached to ます."}]}},"romaji":"Oisogashii naka, gorenraku itadaki arigatō gozaimasu.","german":"Thank you for getting in touch despite being so busy."},{"japanese":"ご丁寧にご連絡くださり、誠にありがとうございます。","romaji":"Goteinei ni gorenraku kudasari, makoto ni arigatō gozaimasu.","german":"Thank you very much for your kind message."}],"notes":"This phrase is used at the beginning of reply emails, directly after お世話になっております. 早速の (prompt) is added when the reply came quickly. ご丁寧に (courteous/thorough) emphasizes appreciation for a detailed message.","related":["keigo-business-osewani","keigo-kenjougo-itadaku"]},
{"id":"keigo-business-goyouken","pattern":"ご用件をお伺いいたします","level":"N2","category":"Keigo","subcategory":"ビジネス敬語","meaning":"may I ask what your business is?","explanation":"ご用件をお伺いいたします is a standard phrase on the phone or at reception for asking what a visitor or caller needs. It combines ご用件 (business/matter, honorific), お伺い (to ask, humble) and いたします (to do, humble) into a triply polite construction.","formation":"ご用件をお伺いいたします ／ どのようなご用件でしょうか (as a question)","examples":[{"japanese":"ご用件をお伺いしてもよろしいでしょうか。","romaji":"Goyōken wo oukagai shite mo yoroshii deshō ka.","german":"May I ask what this is regarding?","cloze":{"start":0,"answer":"ご用件をお伺いして","quiz":{"level":"N2","japanese":"ご用件をお伺いしてもよろしいでしょうか。","german":"May I ask what this is regarding?","start":0,"answer":"ご用件をお伺いして","acceptedAnswers":["ご用件をお伺いして"],"distractors":[{"text":"ご用件をお伺いする","reason":"もよろしい is preceded by the て-form."},{"text":"ご用件をお伺いした","reason":"もよろしい is preceded by the て-form."},{"text":"ご用件をお伺いします","reason":"The finite polite form does not fit before もよろしい here."}]}}},{"japanese":"どのようなご用件でしょうか。","romaji":"Dono yō na goyōken deshō ka.","german":"How may I help you?"},{"japanese":"恐れ入りますが、ご用件をお聞かせいただけますか。","romaji":"Osore irimasu ga, goyōken wo okikase itadakemasu ka.","german":"Excuse me, but could you tell me what this is regarding?"}],"notes":"This phrase is standard at reception desks and on the phone. At reception it is typically followed by お約束はいただいておりますか (do you have an appointment?) or 少々お待ちくださいませ (please wait a moment).","related":["keigo-kenjougo-ukagau","keigo-business-denwataiou"]},
{"id":"keigo-business-gosoudansha","pattern":"ご足労いただきありがとうございます","level":"N1","category":"Keigo","subcategory":"ビジネス敬語","meaning":"thank you for taking the trouble to come","explanation":"ご足労いただきありがとうございます is a formal thank-you formula used when someone has taken the trouble to come in person. 足労 literally means \"leg work / effort of the feet\" and expresses appreciation for the effort of coming.","formation":"ご足労いただき / おかけいたしまして + ありがとうございます / 申し訳ございません","examples":[{"japanese":"本日はご足労いただきありがとうございます。","cloze":{"start":3,"answer":"ご足労いただきありがとうございます","quiz":{"level":"N1","japanese":"本日はご足労いただきありがとうございます。","german":"Thank you for taking the trouble to come today.","start":3,"answer":"ご足労いただきありがとうございます","acceptedAnswers":["ご足労いただきありがとうございます"],"distractors":[{"text":"ご足労いただくありがとうございます","reason":"The thanks requires a connecting stem or て-form."},{"text":"ご足労いただきありがとうます","reason":"The polite form of thanks is ありがとうございます."},{"text":"ご足労いただきありがとうございまする","reason":"る cannot be attached to ます."}]}},"romaji":"Honjitsu wa gosokurō itadaki arigatō gozaimasu.","german":"Thank you for taking the trouble to come today."},{"japanese":"お忙しい中ご足労をおかけいたしまして、申し訳ございません。","romaji":"Oisogashii naka gosokurō wo okake itashimashite, mōshiwake gozaimasen.","german":"I'm sorry to have put you to the trouble of coming when you are so busy."},{"japanese":"ご足労いただき恐縮でございます。","romaji":"Gosokurō itadaki kyōshuku de gozaimasu.","german":"I feel humbled that you took the trouble to come."}],"notes":"ご足労 is used especially when a customer or business partner comes to your own office. It shows appreciation for the physical effort of the journey. The phrase is used at reception and at the start of meetings.","related":["keigo-sonkeigo-okoshininaru","keigo-teinei-osoreirimashitsuki"]},
{"id":"keigo-business-gokitainikotaerareru","pattern":"ご期待に沿えず申し訳ございません","level":"N1","category":"Keigo","subcategory":"ビジネス敬語","meaning":"I'm sorry we could not meet your expectations","explanation":"ご期待に沿えず申し訳ございません is a formal apology used when turning something down in business. 期待に沿う means \"to meet expectations,\" and the negative 沿えず expresses that one was unable to do so. This form is more polite than a direct refusal.","formation":"ご期待に沿えず / ご希望に添えず + 申し訳ございません / 大変残念ですが","examples":[{"japanese":"ご期待に沿えず、誠に申し訳ございません。","romaji":"Gokitai ni soezu, makoto ni mōshiwake gozaimasen.","german":"We are truly sorry that we were unable to meet your expectations.","cloze":{"start":0,"answer":"ご期待に沿えず","quiz":{"level":"N1","japanese":"ご期待に沿えず、誠に申し訳ございません。","german":"We are truly sorry that we were unable to meet your expectations.","start":0,"answer":"ご期待に沿えず","acceptedAnswers":["ご期待に沿えず"],"distractors":[{"text":"ご期待に沿えて","reason":"This affirms that the expectations are met."},{"text":"ご期待を沿えず","reason":"The point of reference requires に."},{"text":"ご期待に沿えずな","reason":"な cannot be attached here."}]}}},{"japanese":"ご希望に添えず大変恐縮ですが、今回は見送らせていただきます。","romaji":"Gokibō ni soezu taihen kyōshuku desu ga, konkai wa miokurasete itadakimasu.","german":"I'm very sorry that we cannot accommodate your wishes, but we will have to pass this time."},{"japanese":"ご要望に沿えず心苦しいのですが、対応いたしかねます。","romaji":"Goyōbō ni soezu kokorogurushii no desu ga, taiō itashikanemasu.","german":"It pains me not to be able to meet your request, but I'm afraid we are unable to do so."}],"notes":"This phrase is the standard opening for business refusals. It softens the refusal and shows regret. In Japan, refusals are almost never stated directly but are always introduced with cushioning formulas like this one.","related":["keigo-teinei-kanemasu","keigo-bikago-moushiwake"]},
{"id":"keigo-business-gojiainokudasaimase","pattern":"ご自愛ください（ごじあいください）","level":"N2","category":"Keigo","subcategory":"ビジネス敬語","meaning":"please take care of your health","explanation":"ご自愛ください is a traditional closing formula in letters and emails that asks the recipient to look after their health. 自愛 literally means \"self-love/self-care.\" This phrase is used especially when the seasons change and in more personal business letters.","formation":"ご自愛ください / ご自愛くださいませ / くれぐれもご自愛ください (emphatic)","examples":[{"japanese":"寒い日が続きますが、くれぐれもご自愛ください。","romaji":"Samui hi ga tsuzukimasu ga, kuregure mo gojiai kudasai.","german":"The cold days continue, so please take extra good care of yourself.","cloze":{"start":15,"answer":"ご自愛ください","quiz":{"level":"N2","japanese":"寒い日が続きますが、くれぐれもご自愛ください。","german":"The cold days continue, so please take extra good care of yourself.","start":15,"answer":"ご自愛ください","acceptedAnswers":["ご自愛ください"],"distractors":[{"text":"ご自愛するください","reason":"ください is not attached to する."},{"text":"ご自愛くださいまする","reason":"る cannot be attached to ます."},{"text":"ご自愛くださるました","reason":"The polite past requires the correct stem."}]}}},{"japanese":"時節柄、ご自愛くださいますようお祈り申し上げます。","romaji":"Jisetsugara, gojiai kudasaimasu yō oinori mōshiagemasu.","german":"Given the season, I pray that you take good care of yourself."},{"japanese":"お体にお気をつけて、ご自愛くださいませ。","romaji":"Okarada ni oki wo tsukete, gojiai kudasaimase.","german":"Please look after yourself and take care of your health."}],"notes":"ご自愛ください is used to close personal and semi-business letters. It goes particularly well with seasonal greetings (時候の挨拶). It is used less often in purely factual business emails.","related":["keigo-business-mailshimebun","keigo-business-yoroshiku"]},
{"id":"keigo-sonkeigo-gokurou","pattern":"お疲れ様です vs ご苦労様です","level":"N2","category":"Keigo","subcategory":"ビジネス敬語","meaning":"correct use of phrases that acknowledge someone's effort","explanation":"お疲れ様です and ご苦労様です both mean \"thank you for your hard work,\" but they follow different usage rules. お疲れ様です can be used toward anyone (including superiors), whereas ご苦労様です is only appropriate toward subordinates or equals. This distinction is a common keigo pitfall.","formation":"お疲れ様です (universal) ／ ご苦労様です (only toward people below you or equals)","examples":[{"japanese":"部長、お疲れ様です。報告書をお持ちいたしました。","romaji":"Buchō, otsukaresama desu. Hōkokusho wo omochi itashimashita.","german":"Thank you for your hard work, sir/ma'am. I've brought the report. (to the department head)","cloze":{"start":3,"answer":"お疲れ様です","quiz":{"level":"N2","japanese":"部長、お疲れ様です。報告書をお持ちいたしました。","german":"Thank you for your hard work, sir/ma'am. I've brought the report. (to the department head)","start":3,"answer":"お疲れ様です","acceptedAnswers":["お疲れ様です","お疲れ様でございます"],"distractors":[{"text":"お疲れ様ます","reason":"ます cannot be attached directly to 様."},{"text":"お疲れ様でする","reason":"る cannot be attached to the copula です."},{"text":"お疲れ様なです","reason":"No な comes before the copula です here."}]}}},{"japanese":"配達員さん、ご苦労様です。","romaji":"Haitatsu-in san, gokurōsama desu.","german":"Thanks for your hard work. (said to a delivery person)"},{"japanese":"本日もお疲れ様でした。","romaji":"Honjitsu mo otsukaresama deshita.","german":"Thank you for your hard work today as well."}],"notes":"The rule that ご苦労様です should not be used toward superiors is less strict among younger Japanese people, but it is still observed in the business world. When in doubt, お疲れ様です is always the safe choice. Some companies no longer use ご苦労様 internally at all.","related":["keigo-bikago-otsukaresama","keigo-business-osewani"]},
{"id":"keigo-kenjougo-mairushinchuu","pattern":"～の折には（のおりには）","level":"N1","category":"Keigo","subcategory":"謙譲語","meaning":"on the occasion of ... / when the opportunity arises ...","explanation":"～の折には is a formal expression meaning \"on the occasion of\" or \"when the opportunity arises.\" 折 (おり) means \"occasion/moment\" and is used in elevated language instead of 時 (とき). This form appears in formal invitations and polite letters.","formation":"Noun + の折には / ～した折には / お近くにお越しの折には","examples":[{"japanese":"お近くにお越しの折には、ぜひお立ち寄りください。","romaji":"Ochikaku ni okoshi no ori ni wa, zehi otachiyori kudasai.","german":"If you are ever in the area, please do drop by.","cloze":{"start":7,"answer":"の折には","quiz":{"level":"N1","japanese":"お近くにお越しの折には、ぜひお立ち寄りください。","german":"If you are ever in the area, please do drop by.","start":7,"answer":"の折には","acceptedAnswers":["の折には","の際には"],"distractors":[{"text":"の折を","reason":"を does not form a time connection here."},{"text":"の折な","reason":"な cannot be attached here."},{"text":"の折ます","reason":"ます cannot be attached directly to 折."}]}}},{"japanese":"東京にいらっしゃる折には、ご連絡いただければ幸いです。","romaji":"Tōkyō ni irassharu ori ni wa, gorenraku itadakereba saiwai desu.","german":"If you are ever in Tokyo, I would be glad to hear from you."},{"japanese":"次にお目にかかる折を楽しみにしております。","romaji":"Tsugi ni ome ni kakaru ori wo tanoshimi ni shite orimasu.","german":"I look forward to our next opportunity to meet."}],"notes":"折 is preferred in formal correspondence and sounds more elegant than 時 or 場合. The phrase お近くにお越しの折には is a classic courtesy formula at the end of business letters and New Year's cards.","related":["keigo-kenjougo-omenikakaru","keigo-sonkeigo-okoshininaru"]},
{"id":"keigo-kenjougo-osagashisuru","pattern":"お調べする / お探しする","level":"N2","category":"Keigo","subcategory":"謙譲語","meaning":"to look up (humble) / to search for (humble)","explanation":"お調べする and お探しする are the humble (kenjōgo) forms of 調べる (to look up/to investigate) and 探す (to search for). They follow the standard humble pattern お + verb stem + する and are often used in customer service when you look something up for a customer.","formation":"お調べする / お調べいたす ／ お探しする / お探しいたす","examples":[{"japanese":"ただいまお調べいたしますので、少々お待ちください。","romaji":"Tadaima oshirabe itashimasu node, shōshō omachi kudasai.","german":"I'll look into it for you right now, so please wait a moment.","cloze":{"start":4,"answer":"お調べいたします","quiz":{"level":"N2","japanese":"ただいまお調べいたしますので、少々お待ちください。","german":"I'll look into it for you right now, so please wait a moment.","start":4,"answer":"お調べいたします","acceptedAnswers":["お調べいたします","お調べします"],"distractors":[{"text":"お調べいたしません","reason":"This negates the announced checking."},{"text":"お調べいたすます","reason":"ます requires the stem いたし."},{"text":"お調べいたしまする","reason":"る cannot be attached to ます."}]}}},{"japanese":"在庫をお調べいたします。","romaji":"Zaiko wo oshirabe itashimasu.","german":"I'll check the stock for you."},{"japanese":"ご希望の商品をお探しいたしましょうか。","romaji":"Gokibō no shōhin wo osagashi itashimashō ka.","german":"Shall I look for the item you would like?"}],"notes":"These forms are standard vocabulary in retail and customer service. They follow the universal お～する/お～いたす pattern, which can be applied to practically any verb (with exceptions such as the special keigo verbs).","related":["keigo-kenjougo-osuru","keigo-kenjougo-kashikomarimashita"]},
{"id":"keigo-business-gohenjiitadaki","pattern":"お忙しいところ恐縮ですが","level":"N2","category":"Keigo","subcategory":"ビジネス敬語","meaning":"I realize you are busy, but ...","explanation":"お忙しいところ恐縮ですが is a variant of the cushion phrase お忙しいところ恐れ入りますが in which 恐縮です (to feel ashamed/humbled) is used instead of 恐れ入ります. Both forms are interchangeable in business emails and introduce a request that might cause the recipient some trouble.","formation":"お忙しいところ恐縮ですが + request ／ ご多忙のところ恐縮ですが (variant)","examples":[{"japanese":"お忙しいところ恐縮ですが、ご署名をいただけますでしょうか。","cloze":{"start":0,"answer":"お忙しいところ恐縮ですが","quiz":{"level":"N2","japanese":"お忙しいところ恐縮ですが、ご署名をいただけますでしょうか。","german":"I know you're busy, but could you please sign this?","start":0,"answer":"お忙しいところ恐縮ですが","acceptedAnswers":["お忙しいところ恐縮ですが","お忙しいところ恐れ入りますが"],"distractors":[{"text":"お忙しいところ恐縮ますが","reason":"ます cannot be attached directly to 恐縮."},{"text":"お忙しいところ恐縮ですがを","reason":"を cannot be attached to the clause connection."},{"text":"お忙しいところ恐縮なです","reason":"No な comes before the copula です here."}]}},"romaji":"Oisogashii tokoro kyōshuku desu ga, goshomei wo itadakemasu deshō ka.","german":"I know you're busy, but could you please sign this?"},{"japanese":"ご多忙のところ大変恐縮ですが、資料をお送りいただけますか。","romaji":"Gotabō no tokoro taihen kyōshuku desu ga, shiryō wo ookuriitadakemasu ka.","german":"I'm very sorry to trouble you when you're so busy, but could you send me the documents?"},{"japanese":"お忙しいところ恐縮に存じますが、ご対応のほどよろしくお願いいたします。","romaji":"Oisogashii tokoro kyōshuku ni zonjimasu ga, gotaiō no hodo yoroshiku onegai itashimasu.","german":"I'm sorry to impose on you when you're busy, but I would ask you to take care of this."}],"notes":"恐縮ですが and 恐れ入りますが are interchangeable in everyday business. 恐縮ですが has a slightly stronger undertone of guilt. Intensifying it with 大変 or making it more formal with 存じます are the usual ways to step it up.","related":["keigo-business-oisogashii","keigo-teinei-osoreirimashitsuki"]},
{"id":"keigo-bikago-omizu","pattern":"お水（おみず）","level":"N4","category":"Keigo","subcategory":"美化語","meaning":"water (polite)","explanation":"お水 is the polite form of 水 (water). The お prefix is optional here but common in most everyday situations, especially in restaurants, when offering drinks or when politely asking for water. Without お, 水 sounds rather matter-of-fact or blunt.","formation":"お + 水（みず）","examples":[{"japanese":"お水をください。","romaji":"Omizu wo kudasai.","german":"Water, please.","cloze":{"start":0,"answer":"お水","quiz":{"level":"N4","japanese":"お水をください。","german":"Water, please.","start":0,"answer":"お水","acceptedAnswers":["お水","水"],"distractors":[{"text":"お茶","reason":"The translation calls for water, not tea."},{"text":"お米","reason":"The translation calls for water, not rice."},{"text":"お金","reason":"The translation calls for water, not money."}],"promptKana":"＿＿＿をください。"}}},{"japanese":"お水をお持ちしましょうか。","romaji":"Omizu wo omochi shimashō ka.","german":"Shall I bring you some water?"},{"japanese":"冷たいお水がありますよ。","romaji":"Tsumetai omizu ga arimasu yo.","german":"There's some cold water, you know."}],"notes":"In everyday life お水 is almost always used with お, especially by women and in polite speech. In scientific or technical contexts, 水 without the prefix is more common. In restaurants, お水 is the standard term.","related":["keigo-bikago-ocha","keigo-bikago-obi"]},
{"id":"keigo-bikago-ocha","pattern":"お茶（おちゃ）","level":"N4","category":"Keigo","subcategory":"美化語","meaning":"tea (practically always with お)","explanation":"お茶 is one of the best-known examples of 美化語, where the お prefix is so firmly attached that it is practically mandatory. 茶 without お sounds unnatural; it appears without お almost only in compounds such as 茶道 (sadō, tea ceremony) or 緑茶 (ryokucha, green tea).","formation":"お + 茶（ちゃ）— prefix practically mandatory","examples":[{"japanese":"お茶でもいかがですか。","romaji":"Ocha demo ikaga desu ka.","german":"Would you like some tea or something?","cloze":{"start":0,"answer":"お茶","quiz":{"level":"N4","japanese":"お茶でもいかがですか。","german":"Would you like some tea or something?","start":0,"answer":"お茶","acceptedAnswers":["お茶","茶"],"distractors":[{"text":"お水","reason":"This offers water instead of tea."},{"text":"コーヒー","reason":"This offers coffee instead of tea."},{"text":"お酒","reason":"This offers alcohol instead of tea."}],"promptKana":"＿＿＿でもいかがですか。"}}},{"japanese":"お茶を入れますね。","romaji":"Ocha wo iremasu ne.","german":"I'll make some tea, okay?"},{"japanese":"毎朝お茶を飲みます。","romaji":"Maiasa ocha wo nomimasu.","german":"I drink tea every morning."}],"notes":"お茶 is a prime example of a word in which the お prefix has become mandatory. Even in casual speech, people say お茶 and not 茶 on its own. The word shows how 美化語 can become a fixed part of the vocabulary over time.","related":["keigo-bikago-omizu","keigo-bikago-obi"]},
{"id":"keigo-bikago-okane","pattern":"お金（おかね）","level":"N4","category":"Keigo","subcategory":"美化語","meaning":"money (always with お)","explanation":"お金 is the standard word for \"money\" in Japanese. The お prefix is mandatory here – 金 (かね) on its own is hardly used and sounds crude or rude. 金 is used without お only in compounds such as 金額 (kingaku, amount of money) or 金持ち (kanemochi, rich person).","formation":"お + 金（かね）— prefix mandatory","examples":[{"japanese":"お金が足りません。","romaji":"Okane ga tarimasen.","german":"I don't have enough money.","cloze":{"start":0,"answer":"お金","quiz":{"level":"N4","japanese":"お金が足りません。","german":"I don't have enough money.","start":0,"answer":"お金","acceptedAnswers":["お金","金"],"distractors":[{"text":"お水","reason":"This means water, not money."},{"text":"お時間","reason":"This means time, not money."},{"text":"お米","reason":"This means rice, not money."}],"promptKana":"＿＿＿がたりません。"}}},{"japanese":"お金を貯めています。","romaji":"Okane wo tamete imasu.","german":"I'm saving money."},{"japanese":"お金のことは心配しないでください。","romaji":"Okane no koto wa shinpai shinaide kudasai.","german":"Please don't worry about the money."}],"notes":"お金 is one of the words where the お prefix is so deeply rooted that many Japanese people no longer perceive it as an honorific prefix at all. Even in colloquial speech and in rude contexts, お金 is used with お.","related":["keigo-bikago-otsuri","keigo-bikago-obi"]},
{"id":"keigo-bikago-onamae","pattern":"お名前（おなまえ）","level":"N4","category":"Keigo","subcategory":"美化語","meaning":"name (polite, when asking others)","explanation":"お名前 is the polite form of 名前 (name). The お prefix is used especially when asking for another person's name or talking about the name of a respected person. When talking about your own name, お is left out: 名前は田中です。","formation":"お + 名前（なまえ）— prefix usual for other people","examples":[{"japanese":"お名前をお願いします。","romaji":"Onamae wo onegai shimasu.","german":"Your name, please.","cloze":{"start":0,"answer":"お名前","quiz":{"level":"N4","japanese":"お名前をお願いします。","german":"Your name, please.","start":0,"answer":"お名前","acceptedAnswers":["お名前","名前"],"distractors":[{"text":"ご住所","reason":"This asks for the address instead of the name."},{"text":"お仕事","reason":"This does not ask about the name."},{"text":"お電話","reason":"This does not request the name."}],"promptKana":"＿＿＿をおねがいします。"}}},{"japanese":"お名前は何とおっしゃいますか。","romaji":"Onamae wa nan to osshaimasu ka.","german":"What is your name? (very polite)"},{"japanese":"こちらにお名前をご記入ください。","romaji":"Kochira ni onamae wo gokinyū kudasai.","german":"Please write your name here."}],"notes":"お名前 shows the difference between 美化語 and 尊敬語: when you mean the other person's name, お serves as a mark of respect (尊敬語 function). When talking about names in general, it is 美化語. You give your own name without お, since you do not honor yourself.","related":["keigo-bikago-obi","keigo-sonkeigo-ossharu"]},
{"id":"keigo-bikago-onaka","pattern":"お腹（おなか）","level":"N4","category":"Keigo","subcategory":"美化語","meaning":"belly / stomach (always with お)","explanation":"お腹 is the standard everyday word for \"belly\" or \"stomach.\" The お prefix is mandatory here – 腹（はら）on its own is used in some idioms (腹が立つ = to get angry), but for the body part people always say お腹. Especially in the well-known phrase お腹が空いた (I'm hungry), お is indispensable.","formation":"お + 腹（なか）— prefix mandatory in everyday speech","examples":[{"japanese":"お腹が空きました。","romaji":"Onaka ga sukimashita.","german":"I'm hungry.","cloze":{"start":0,"answer":"お腹","quiz":{"level":"N4","japanese":"お腹が空きました。","german":"I'm hungry.","start":0,"answer":"お腹","acceptedAnswers":["お腹","腹"],"distractors":[{"text":"お名前","reason":"A name does not get hungry."},{"text":"お茶","reason":"Tea does not get hungry."},{"text":"お金","reason":"Money does not get hungry."}],"promptKana":"＿＿＿がすきました。"}}},{"japanese":"お腹がいっぱいです。","romaji":"Onaka ga ippai desu.","german":"I'm full."},{"japanese":"お腹の調子が悪いんです。","romaji":"Onaka no chōshi ga warui n desu.","german":"My stomach isn't feeling well."}],"notes":"お腹 is another example where the お prefix has fused so firmly with the word that it is no longer perceived as a polite form. The reading なか (instead of はら) is used only with お. 腹（はら）without お sounds masculine and coarse.","related":["keigo-bikago-obi","keigo-bikago-gohan"]},
{"id":"keigo-bikago-obentou","pattern":"お弁当（おべんとう）","level":"N4","category":"Keigo","subcategory":"美化語","meaning":"lunch box / bento (polite)","explanation":"お弁当 is the polite form of 弁当 (lunch box). The お prefix is widespread here and usual in most everyday situations. 弁当 without お is used in compounds such as 弁当箱 (bentōbako, lunch box container) or in matter-of-fact contexts (menus, business descriptions).","formation":"お + 弁当（べんとう）— prefix usual in everyday speech","examples":[{"japanese":"今日はお弁当を持ってきました。","romaji":"Kyō wa obentō wo motte kimashita.","german":"I brought a bento today.","cloze":{"start":3,"answer":"お弁当","quiz":{"level":"N4","japanese":"今日はお弁当を持ってきました。","german":"I brought a bento today.","start":3,"answer":"お弁当","acceptedAnswers":["お弁当","弁当"],"distractors":[{"text":"お土産","reason":"This means a souvenir gift, not the bento meal."},{"text":"お金","reason":"This means money, not the bento meal."},{"text":"お花","reason":"This means flowers, not the bento meal."}],"promptKana":"きょうは＿＿＿をもってきました。"}}},{"japanese":"お弁当を買いに行きましょう。","romaji":"Obentō wo kai ni ikimashō.","german":"Let's go buy a bento."},{"japanese":"毎日お弁当を作っています。","romaji":"Mainichi obentō wo tsukutte imasu.","german":"I make a bento every day."}],"notes":"In everyday life, お弁当 is almost always used with お, especially in spoken language. On signs and menus in shops you sometimes see 弁当 without お. Bento culture is deeply rooted in Japan, and お弁当 is an everyday word that every learner of Japanese should know.","related":["keigo-bikago-ocha","keigo-bikago-obi"]},
{"id":"keigo-bikago-omiyage","pattern":"お土産（おみやげ）","level":"N4","category":"Keigo","subcategory":"美化語","meaning":"gift brought back from a trip / souvenir (always with お)","explanation":"お土産 is the standard word for a gift brought back from a trip, or a \"souvenir.\" The お prefix is practically mandatory here – 土産（みやげ）on its own is used almost only in compounds such as 土産物（みやげもの）or 土産話（みやげばなし, travel stories）. The culture of buying お土産 is deeply rooted in Japan.","formation":"お + 土産（みやげ）— prefix practically mandatory","examples":[{"japanese":"旅行のお土産を買いました。","romaji":"Ryokō no omiyage wo kaimashita.","german":"I bought souvenirs from my trip.","cloze":{"start":3,"answer":"お土産","quiz":{"level":"N4","japanese":"旅行のお土産を買いました。","german":"I bought souvenirs from my trip.","start":3,"answer":"お土産","acceptedAnswers":["お土産","土産"],"distractors":[{"text":"お弁当","reason":"This means a meal, not a travel souvenir."},{"text":"お薬","reason":"This means medicine, not a travel souvenir."},{"text":"お水","reason":"This means water, not a travel souvenir."}],"promptKana":"りょこうの＿＿＿をかいました。"}}},{"japanese":"これ、京都のお土産です。どうぞ。","romaji":"Kore, Kyōto no omiyage desu. Dōzo.","german":"This is a souvenir from Kyoto. Here you go."},{"japanese":"お土産を選ぶのに時間がかかりました。","romaji":"Omiyage wo erabu no ni jikan ga kakarimashita.","german":"It took me a long time to choose souvenirs."}],"notes":"In Japan it is customary to bring お土産 back from trips for colleagues and friends. Train stations and airports have large お土産 sections. The word is practically never used without お and is an excellent example of a culturally deep-rooted 美化語.","related":["keigo-bikago-obi","keigo-bikago-omatsuri"]},
{"id":"keigo-bikago-omatsuri","pattern":"お祭り（おまつり）","level":"N4","category":"Keigo","subcategory":"美化語","meaning":"festival / celebration (always with お)","explanation":"お祭り is the usual word for \"festival\" in Japanese. The お prefix is firmly built in here – 祭り（まつり）without お is used in some compounds such as 夏祭り（なつまつり, summer festival）or 火祭り（ひまつり, fire festival）, but as a standalone word people almost always say お祭り.","formation":"お + 祭り（まつり）— prefix mandatory as a standalone word","examples":[{"japanese":"今週末、お祭りがありますよ。","romaji":"Konshūmatsu, omatsuri ga arimasu yo.","german":"There's a festival this weekend, you know.","cloze":{"start":4,"answer":"お祭り","quiz":{"level":"N4","japanese":"今週末、お祭りがありますよ。","german":"There's a festival this weekend, you know.","start":4,"answer":"お祭り","acceptedAnswers":["お祭り","祭り"],"distractors":[{"text":"お仕事","reason":"This means work, not a festival."},{"text":"お休み","reason":"This means time off, not a festival."},{"text":"お食事","reason":"This means a meal, not a festival."}],"promptKana":"こんしゅうまつ、＿＿＿がありますよ。"}}},{"japanese":"お祭りで浴衣を着ました。","romaji":"Omatsuri de yukata wo kimashita.","german":"I wore a yukata at the festival."},{"japanese":"子供たちがお祭りを楽しみにしています。","romaji":"Kodomotachi ga omatsuri wo tanoshimi ni shite imasu.","german":"The children are looking forward to the festival."}],"notes":"お祭り has its origins in the worship of the gods (祭る = to worship, to pay homage to the kami). The お prefix originally showed reverence for the religious character of the festival. In compounds such as 夏祭り or 花祭り, the お is dropped.","related":["keigo-bikago-obi","keigo-bikago-omiyage"]},
{"id":"keigo-bikago-gohan","pattern":"ご飯（ごはん）","level":"N3","category":"Keigo","subcategory":"美化語","meaning":"rice / meal (always with ご)","explanation":"ご飯 is the standard word for \"cooked rice\" and for \"meal\" in general. The ご prefix is completely mandatory here – 飯（めし）without a prefix is a coarse, masculine variant that is avoided in polite speech. ご飯 is one of the most important examples of a ご-美化語.","formation":"ご + 飯（はん）— prefix mandatory in normal speech","examples":[{"japanese":"ご飯を食べましたか。","romaji":"Gohan wo tabemashita ka.","german":"Have you eaten?","cloze":{"start":0,"answer":"ご飯","quiz":{"level":"N3","japanese":"ご飯を食べましたか。","german":"Have you eaten?","start":0,"answer":"ご飯","acceptedAnswers":["ご飯","食事"],"distractors":[{"text":"お薬","reason":"This asks about medicine instead of the meal."},{"text":"お菓子","reason":"This asks specifically about sweets instead of the meal."},{"text":"お肉","reason":"This asks specifically about meat instead of the meal."}]}}},{"japanese":"ご飯ができましたよ。","romaji":"Gohan ga dekimashita yo.","german":"The food is ready!"},{"japanese":"朝ご飯は何を食べますか。","romaji":"Asagohan wa nani wo tabemasu ka.","german":"What do you eat for breakfast?"}],"notes":"ご飯 is used both for \"rice\" and for \"meal\" (朝ご飯 = breakfast, 昼ご飯 = lunch, 晩ご飯 = dinner). 飯（めし）without ご sounds coarse and is mainly used by men in informal speech. ご飯 is proof that rice is at the center of Japanese food culture.","related":["keigo-bikago-ocha","keigo-bikago-obi"]},
{"id":"keigo-bikago-gokazoku","pattern":"ご家族（ごかぞく）","level":"N3","category":"Keigo","subcategory":"美化語","meaning":"family (polite, for someone else's family)","explanation":"ご家族 is the polite word for another person's family. The ご prefix is used here because 家族 is a Sino-Japanese word (漢語). Important: ご家族 is only used for the family of the person you are talking to or of third parties – for your own family you simply say 家族.","formation":"ご + 家族（かぞく）— prefix for other people's families","examples":[{"japanese":"ご家族はお元気ですか。","romaji":"Gokazoku wa ogenki desu ka.","german":"Is your family well?","cloze":{"start":0,"answer":"ご家族","quiz":{"level":"N3","japanese":"ご家族はお元気ですか。","german":"Is your family well?","start":0,"answer":"ご家族","acceptedAnswers":["ご家族","家族"],"distractors":[{"text":"ご住所","reason":"This means the address, not the family."},{"text":"お名前","reason":"This means the name, not the family."},{"text":"お仕事","reason":"This means work, not the family."}]}}},{"japanese":"ご家族の皆様によろしくお伝えください。","romaji":"Gokazoku no minasama ni yoroshiku otsutae kudasai.","german":"Please give my regards to your family."},{"japanese":"ご家族でいらっしゃいますか。","romaji":"Gokazoku de irasshaimasu ka.","german":"Are you here with your family?"}],"notes":"The distinction between ご家族 (for others) and 家族 (for yourself) is a basic principle of keigo: you honor what belongs to others and speak modestly about what is your own. Similarly: ご主人 (your husband) vs. 主人/夫 (my husband), ご両親 (your parents) vs. 両親/父と母 (my parents).","related":["keigo-bikago-obi","keigo-bikago-gojuusho"]},
{"id":"keigo-bikago-gojuusho","pattern":"ご住所（ごじゅうしょ）","level":"N3","category":"Keigo","subcategory":"美化語","meaning":"address (polite, when asking others)","explanation":"ご住所 is the polite form of 住所 (address). The ご prefix is used because 住所 is a Sino-Japanese word. As with お名前, ご住所 is mainly used when asking for another person's address or politely asking someone to fill it in on a form.","formation":"ご + 住所（じゅうしょ）— prefix when asking others","examples":[{"japanese":"ご住所をお教えいただけますか。","romaji":"Gojūsho wo ooshie itadakemasu ka.","german":"Could you tell me your address?","cloze":{"start":0,"answer":"ご住所","quiz":{"level":"N3","japanese":"ご住所をお教えいただけますか。","german":"Could you tell me your address?","start":0,"answer":"ご住所","acceptedAnswers":["ご住所","住所"],"distractors":[{"text":"お名前","reason":"This asks for the name instead of the address."},{"text":"お電話番号","reason":"This asks for the phone number instead of the address."},{"text":"お仕事","reason":"This asks about work instead of the address."}]}}},{"japanese":"こちらにご住所をご記入ください。","romaji":"Kochira ni gojūsho wo gokinyū kudasai.","german":"Please write your address here."},{"japanese":"ご住所の変更はございますか。","romaji":"Gojūsho no henkō wa gozaimasu ka.","german":"Has your address changed?"}],"notes":"ご住所 follows the same pattern as お名前: you use the polite prefix when referring to the other person's details. You talk about your own address without the prefix: 住所は東京です。Forms often have ご住所 printed on them to show politeness toward the person filling them in.","related":["keigo-bikago-onamae","keigo-bikago-obi"]},
{"id":"keigo-bikago-prefix-rules","pattern":"お/ご-Präfix-Regeln (和語 vs. 漢語)","level":"N3","category":"Keigo","subcategory":"美化語","meaning":"rules for using お (native Japanese) and ご (Sino-Japanese)","explanation":"The basic rule for 美化語 prefixes is: お goes before 和語 (native Japanese words, mostly with kun readings), ご before 漢語 (Sino-Japanese words, mostly with on readings). There are exceptions, however: some 漢語 take お instead of ご (e.g. お電話, お料理, お返事), and katakana words (loanwords) usually take no prefix.","formation":"お + 和語（kun reading）／ ご + 漢語（on reading）／ watch out for exceptions","examples":[{"japanese":"お花、お水、お酒 → 和語 (japanisch) → お","romaji":"Ohana, omizu, osake → Wago → o","german":"Flowers, water, sake → native Japanese words → お"},{"japanese":"ご家族、ご住所、ご意見 → 漢語 (sino-japanisch) → ご","romaji":"Gokazoku, gojūsho, goiken → Kango → go","german":"Family, address, opinion → Sino-Japanese words → ご"},{"japanese":"お電話、お料理、お返事 → 漢語だけど「お」を使う例外","romaji":"Odenwa, oryōri, ohenji → Kango, aber Ausnahme mit „o“","german":"Telephone, cooking, reply → Sino-Japanese, but exceptions with お"}],"notes":"The distinction 和語→お / 漢語→ご is a helpful rule of thumb but not an absolute law. Many frequently used 漢語 take お (お電話, お料理, お食事, お返事, お天気). Loanwords (katakana) normally take no prefix – おコーヒー or おビール are considered colloquial/jokey. When in doubt, it helps to memorize common combinations.","related":["keigo-bikago-obi","keigo-bikago-gohan"],"clozeExcludedReason":"Metasprachliche Präfixübersicht; kein eigenständiger Satz für einen Lückentext."},
{"id":"keigo-bikago-otearai","pattern":"お手洗い（おてあらい）","level":"N3","category":"Keigo","subcategory":"美化語","meaning":"toilet / restroom (polite, always with お)","explanation":"お手洗い is the standard polite word for \"toilet\" or \"restroom.\" Literally it means \"hand-washing\" (手を洗う). The お prefix is mandatory here – 手洗い alone is hardly ever used in the sense of \"toilet.\" お手洗い is the preferred form in polite speech and the usual word on signs in public buildings.","formation":"お + 手洗い（てあらい）— prefix mandatory","examples":[{"japanese":"お手洗いはどこですか。","romaji":"Otearai wa doko desu ka.","german":"Where is the restroom?","cloze":{"start":0,"answer":"お手洗い","quiz":{"level":"N3","japanese":"お手洗いはどこですか。","german":"Where is the restroom?","start":0,"answer":"お手洗い","acceptedAnswers":["お手洗い","トイレ"],"distractors":[{"text":"お出口","reason":"This asks about the exit instead of the restroom."},{"text":"お会計","reason":"This asks about paying the bill instead of the restroom."},{"text":"お食事","reason":"This asks about a meal instead of the restroom."}]}}},{"japanese":"お手洗いに行ってまいります。","romaji":"Otearai ni itte mairimasu.","german":"I'll just go to the restroom. (very polite)"},{"japanese":"お手洗いはあちらでございます。","romaji":"Otearai wa achira de gozaimasu.","german":"The restroom is over there."}],"notes":"Japanese has several words for \"toilet\" with different levels of politeness: トイレ (neutral, most common), お手洗い (polite), 化粧室（けしょうしつ, \"powder room,\" very polite, in department stores), お手水（おちょうず, traditional/religious). お手洗い is the safest choice in polite conversation.","related":["keigo-bikago-obi","keigo-teinei-degozaimasu"]},
{"id":"keigo-bikago-gochisou","pattern":"ご馳走（ごちそう）","level":"N3","category":"Keigo","subcategory":"美化語","meaning":"feast / hospitality / treating someone to a meal (always with ご)","explanation":"ご馳走 means \"feast\" or \"lavish meal\" and is best known from the expression ご馳走様でした (thank you for the meal). The ご prefix is mandatory – 馳走 without ご is not used. The kanji 馳走 literally mean \"running around,\" alluding to the host going to great lengths to obtain ingredients.","formation":"ご + 馳走（ちそう）— prefix mandatory","examples":[{"japanese":"ご馳走様でした。","romaji":"Gochisōsama deshita.","german":"Thank you for the meal. (said after eating)","cloze":{"start":0,"answer":"ご馳走様","quiz":{"level":"N3","japanese":"ご馳走様でした。","german":"Thank you for the meal. (said after eating)","start":0,"answer":"ご馳走様","acceptedAnswers":["ご馳走様","ごちそうさま"],"distractors":[{"text":"いただきます","reason":"いただきます is said before the meal and does not come before でした."},{"text":"おやすみ","reason":"This is a goodnight greeting, not thanks for the meal."},{"text":"こんにちは","reason":"This is a daytime greeting, not thanks for the meal."}]}}},{"japanese":"今日は私がご馳走します。","romaji":"Kyō wa watashi ga gochisō shimasu.","german":"Today it's my treat. (I'm paying.)"},{"japanese":"すごいご馳走ですね！","romaji":"Sugoi gochisō desu ne!","german":"What a wonderful feast!"}],"notes":"ご馳走様でした is one of the most important Japanese table manners – you say it after every meal, whether at home, in a restaurant or when you have been treated. Its counterpart before eating is いただきます. ご馳走する means \"to treat someone (to a meal)\" and is a useful everyday expression.","related":["keigo-bikago-gohan","keigo-bikago-obi"]},
{"id":"keigo-bikago-otsuri","pattern":"お釣り（おつり）","level":"N3","category":"Keigo","subcategory":"美化語","meaning":"change / money given back (always with お)","explanation":"お釣り is the standard word for \"change\" (money). The お prefix is mandatory here – 釣り（つり）on its own means \"fishing\" or \"angling\" and is not used without お in the sense of \"change.\" お釣り is an indispensable word for everyday life in Japan, especially when shopping.","formation":"お + 釣り（つり）— prefix mandatory in the sense of \"change\"","examples":[{"japanese":"お釣りをお確かめください。","romaji":"Otsuri wo otashikame kudasai.","german":"Please check your change.","cloze":{"start":0,"answer":"お釣り","quiz":{"level":"N3","japanese":"お釣りをお確かめください。","german":"Please check your change.","start":0,"answer":"お釣り","acceptedAnswers":["お釣り","釣り"],"distractors":[{"text":"お名前","reason":"This means a name, not the change."},{"text":"ご住所","reason":"This means an address, not the change."},{"text":"お荷物","reason":"This means luggage, not the change."}]}}},{"japanese":"お釣りは結構です。","romaji":"Otsuri wa kekkō desu.","german":"Keep the change."},{"japanese":"千円からお預かりします。お釣りは三百円です。","romaji":"Sen'en kara oazukari shimasu. Otsuri wa sanbyaku en desu.","german":"Out of 1,000 yen. Your change is 300 yen."}],"notes":"You hear お釣り constantly at Japanese checkouts. Although cashless payment is spreading in Japan, cash is still widely used. The checkout phrase お釣りは○○円です is part of everyday language. Without お, 釣り means only \"fishing.\"","related":["keigo-bikago-okane","keigo-bikago-obi"]}
];
